void axisdev88_init(MachineState *machine)

{

    ram_addr_t ram_size = machine->ram_size;

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    const char *kernel_cmdline = machine->kernel_cmdline;

    CRISCPU *cpu;

    CPUCRISState *env;

    DeviceState *dev;

    SysBusDevice *s;

    DriveInfo *nand;

    qemu_irq irq[30], nmi[2];

    void *etraxfs_dmac;

    struct etraxfs_dma_client *dma_eth;

    int i;

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *phys_ram = g_new(MemoryRegion, 1);

    MemoryRegion *phys_intmem = g_new(MemoryRegion, 1);



    /* init CPUs */

    if (cpu_model == NULL) {

        cpu_model = "crisv32";

    }

    cpu = cpu_cris_init(cpu_model);

    env = &cpu->env;



    /* allocate RAM */

    memory_region_allocate_system_memory(phys_ram, NULL, "axisdev88.ram",

                                         ram_size);

    memory_region_add_subregion(address_space_mem, 0x40000000, phys_ram);



    /* The ETRAX-FS has 128Kb on chip ram, the docs refer to it as the 

       internal memory.  */

    memory_region_init_ram(phys_intmem, NULL, "axisdev88.chipram", INTMEM_SIZE,

                           &error_abort);

    vmstate_register_ram_global(phys_intmem);

    memory_region_add_subregion(address_space_mem, 0x38000000, phys_intmem);



      /* Attach a NAND flash to CS1.  */

    nand = drive_get(IF_MTD, 0, 0);

    nand_state.nand = nand_init(nand ? blk_by_legacy_dinfo(nand) : NULL,

                                NAND_MFR_STMICRO, 0x39);

    memory_region_init_io(&nand_state.iomem, NULL, &nand_ops, &nand_state,

                          "nand", 0x05000000);

    memory_region_add_subregion(address_space_mem, 0x10000000,

                                &nand_state.iomem);



    gpio_state.nand = &nand_state;

    memory_region_init_io(&gpio_state.iomem, NULL, &gpio_ops, &gpio_state,

                          "gpio", 0x5c);

    memory_region_add_subregion(address_space_mem, 0x3001a000,

                                &gpio_state.iomem);





    dev = qdev_create(NULL, "etraxfs,pic");

    /* FIXME: Is there a proper way to signal vectors to the CPU core?  */

    qdev_prop_set_ptr(dev, "interrupt_vector", &env->interrupt_vector);

    qdev_init_nofail(dev);

    s = SYS_BUS_DEVICE(dev);

    sysbus_mmio_map(s, 0, 0x3001c000);

    sysbus_connect_irq(s, 0, qdev_get_gpio_in(DEVICE(cpu), CRIS_CPU_IRQ));

    sysbus_connect_irq(s, 1, qdev_get_gpio_in(DEVICE(cpu), CRIS_CPU_NMI));

    for (i = 0; i < 30; i++) {

        irq[i] = qdev_get_gpio_in(dev, i);

    }

    nmi[0] = qdev_get_gpio_in(dev, 30);

    nmi[1] = qdev_get_gpio_in(dev, 31);



    etraxfs_dmac = etraxfs_dmac_init(0x30000000, 10);

    for (i = 0; i < 10; i++) {

        /* On ETRAX, odd numbered channels are inputs.  */

        etraxfs_dmac_connect(etraxfs_dmac, i, irq + 7 + i, i & 1);

    }



    /* Add the two ethernet blocks.  */

    dma_eth = g_malloc0(sizeof dma_eth[0] * 4); /* Allocate 4 channels.  */

    etraxfs_eth_init(&nd_table[0], 0x30034000, 1, &dma_eth[0], &dma_eth[1]);

    if (nb_nics > 1) {

        etraxfs_eth_init(&nd_table[1], 0x30036000, 2, &dma_eth[2], &dma_eth[3]);

    }



    /* The DMA Connector block is missing, hardwire things for now.  */

    etraxfs_dmac_connect_client(etraxfs_dmac, 0, &dma_eth[0]);

    etraxfs_dmac_connect_client(etraxfs_dmac, 1, &dma_eth[1]);

    if (nb_nics > 1) {

        etraxfs_dmac_connect_client(etraxfs_dmac, 6, &dma_eth[2]);

        etraxfs_dmac_connect_client(etraxfs_dmac, 7, &dma_eth[3]);

    }



    /* 2 timers.  */

    sysbus_create_varargs("etraxfs,timer", 0x3001e000, irq[0x1b], nmi[1], NULL);

    sysbus_create_varargs("etraxfs,timer", 0x3005e000, irq[0x1b], nmi[1], NULL);



    for (i = 0; i < 4; i++) {

        sysbus_create_simple("etraxfs,serial", 0x30026000 + i * 0x2000,

                             irq[0x14 + i]);

    }



    if (kernel_filename) {

        li.image_filename = kernel_filename;

        li.cmdline = kernel_cmdline;

        cris_load_image(cpu, &li);

    } else if (!qtest_enabled()) {

        fprintf(stderr, "Kernel image must be specified\n");

        exit(1);

    }

}

static int read_rle_sgi(const SGIInfo *sgi_info, 

        AVPicture *pict, ByteIOContext *f)

{

    uint8_t *dest_row, *rle_data = NULL;

    unsigned long *start_table, *length_table;

    int y, z, xsize, ysize, zsize, tablen; 

    long start_offset, run_length;

    int ret = 0;



    xsize = sgi_info->xsize;

    ysize = sgi_info->ysize;

    zsize = sgi_info->zsize;



    rle_data = av_malloc(xsize);



    /* skip header */ 

    url_fseek(f, SGI_HEADER_SIZE, SEEK_SET);



    /* size of rle offset and length tables */

    tablen = ysize * zsize * sizeof(long);



    start_table = (unsigned long *)av_malloc(tablen);

    length_table = (unsigned long *)av_malloc(tablen);



    if (!get_buffer(f, (uint8_t *)start_table, tablen)) {

        ret = -1;

        goto fail;

    }



    if (!get_buffer(f, (uint8_t *)length_table, tablen)) {

        ret = -1;

        goto fail;

    }



    for (z = 0; z < zsize; z++) {

        for (y = 0; y < ysize; y++) {

            dest_row = pict->data[0] + (ysize - 1 - y) * (xsize * zsize);



            start_offset = BE_32(&start_table[y + z * ysize]);

            run_length = BE_32(&length_table[y + z * ysize]);



            /* don't seek if already in the correct spot */

            if (url_ftell(f) != start_offset) {

                url_fseek(f, start_offset, SEEK_SET);

            }



            get_buffer(f, rle_data, run_length);



            expand_rle_row(dest_row, rle_data, z, zsize);

        }

    }



fail:

    av_free(start_table);

    av_free(length_table);

    av_free(rle_data);



    return ret;

}

BlockAIOCB *bdrv_aio_ioctl(BlockDriverState *bs,

        unsigned long int req, void *buf,

        BlockCompletionFunc *cb, void *opaque)

{

    BlockAIOCBCoroutine *acb = qemu_aio_get(&bdrv_em_co_aiocb_info,

                                            bs, cb, opaque);

    Coroutine *co;



    acb->need_bh = true;

    acb->req.error = -EINPROGRESS;

    acb->req.req = req;

    acb->req.buf = buf;

    co = qemu_coroutine_create(bdrv_co_aio_ioctl_entry);

    qemu_coroutine_enter(co, acb);



    bdrv_co_maybe_schedule_bh(acb);

    return &acb->common;

}

static uint64_t gt64120_readl (void *opaque,

                               target_phys_addr_t addr, unsigned size)

{

    GT64120State *s = opaque;

    PCIHostState *phb = PCI_HOST_BRIDGE(s);

    uint32_t val;

    uint32_t saddr;



    saddr = (addr & 0xfff) >> 2;

    switch (saddr) {



    /* CPU Configuration */

    case GT_MULTI:

        /* Only one GT64xxx is present on the CPU bus, return

           the initial value */

        val = s->regs[saddr];

        break;



    /* CPU Error Report */

    case GT_CPUERR_ADDRLO:

    case GT_CPUERR_ADDRHI:

    case GT_CPUERR_DATALO:

    case GT_CPUERR_DATAHI:

    case GT_CPUERR_PARITY:

        /* Emulated memory has no error, always return the initial

           values */

        val = s->regs[saddr];

        break;



    /* CPU Sync Barrier */

    case GT_PCI0SYNC:

    case GT_PCI1SYNC:

        /* Reading those register should empty all FIFO on the PCI

           bus, which are not emulated. The return value should be

           a random value that should be ignored. */

        val = 0xc000ffee;

        break;



    /* ECC */

    case GT_ECC_ERRDATALO:

    case GT_ECC_ERRDATAHI:

    case GT_ECC_MEM:

    case GT_ECC_CALC:

    case GT_ECC_ERRADDR:

        /* Emulated memory has no error, always return the initial

           values */

        val = s->regs[saddr];

        break;



    case GT_CPU:

    case GT_SCS10LD:

    case GT_SCS10HD:

    case GT_SCS32LD:

    case GT_SCS32HD:

    case GT_CS20LD:

    case GT_CS20HD:

    case GT_CS3BOOTLD:

    case GT_CS3BOOTHD:

    case GT_SCS10AR:

    case GT_SCS32AR:

    case GT_CS20R:

    case GT_CS3BOOTR:

    case GT_PCI0IOLD:

    case GT_PCI0M0LD:

    case GT_PCI0M1LD:

    case GT_PCI1IOLD:

    case GT_PCI1M0LD:

    case GT_PCI1M1LD:

    case GT_PCI0IOHD:

    case GT_PCI0M0HD:

    case GT_PCI0M1HD:

    case GT_PCI1IOHD:

    case GT_PCI1M0HD:

    case GT_PCI1M1HD:

    case GT_PCI0IOREMAP:

    case GT_PCI0M0REMAP:

    case GT_PCI0M1REMAP:

    case GT_PCI1IOREMAP:

    case GT_PCI1M0REMAP:

    case GT_PCI1M1REMAP:

    case GT_ISD:

        val = s->regs[saddr];

        break;

    case GT_PCI0_IACK:

        /* Read the IRQ number */

        val = pic_read_irq(isa_pic);

        break;



    /* SDRAM and Device Address Decode */

    case GT_SCS0LD:

    case GT_SCS0HD:

    case GT_SCS1LD:

    case GT_SCS1HD:

    case GT_SCS2LD:

    case GT_SCS2HD:

    case GT_SCS3LD:

    case GT_SCS3HD:

    case GT_CS0LD:

    case GT_CS0HD:

    case GT_CS1LD:

    case GT_CS1HD:

    case GT_CS2LD:

    case GT_CS2HD:

    case GT_CS3LD:

    case GT_CS3HD:

    case GT_BOOTLD:

    case GT_BOOTHD:

    case GT_ADERR:

        val = s->regs[saddr];

        break;



    /* SDRAM Configuration */

    case GT_SDRAM_CFG:

    case GT_SDRAM_OPMODE:

    case GT_SDRAM_BM:

    case GT_SDRAM_ADDRDECODE:

        val = s->regs[saddr];

        break;



    /* SDRAM Parameters */

    case GT_SDRAM_B0:

    case GT_SDRAM_B1:

    case GT_SDRAM_B2:

    case GT_SDRAM_B3:

        /* We don't simulate electrical parameters of the SDRAM.

           Just return the last written value. */

        val = s->regs[saddr];

        break;



    /* Device Parameters */

    case GT_DEV_B0:

    case GT_DEV_B1:

    case GT_DEV_B2:

    case GT_DEV_B3:

    case GT_DEV_BOOT:

        val = s->regs[saddr];

        break;



    /* DMA Record */

    case GT_DMA0_CNT:

    case GT_DMA1_CNT:

    case GT_DMA2_CNT:

    case GT_DMA3_CNT:

    case GT_DMA0_SA:

    case GT_DMA1_SA:

    case GT_DMA2_SA:

    case GT_DMA3_SA:

    case GT_DMA0_DA:

    case GT_DMA1_DA:

    case GT_DMA2_DA:

    case GT_DMA3_DA:

    case GT_DMA0_NEXT:

    case GT_DMA1_NEXT:

    case GT_DMA2_NEXT:

    case GT_DMA3_NEXT:

    case GT_DMA0_CUR:

    case GT_DMA1_CUR:

    case GT_DMA2_CUR:

    case GT_DMA3_CUR:

        val = s->regs[saddr];

        break;



    /* DMA Channel Control */

    case GT_DMA0_CTRL:

    case GT_DMA1_CTRL:

    case GT_DMA2_CTRL:

    case GT_DMA3_CTRL:

        val = s->regs[saddr];

        break;



    /* DMA Arbiter */

    case GT_DMA_ARB:

        val = s->regs[saddr];

        break;



    /* Timer/Counter */

    case GT_TC0:

    case GT_TC1:

    case GT_TC2:

    case GT_TC3:

    case GT_TC_CONTROL:

        val = s->regs[saddr];

        break;



    /* PCI Internal */

    case GT_PCI0_CFGADDR:

        val = phb->config_reg;

        break;

    case GT_PCI0_CFGDATA:

        if (!(phb->config_reg & (1 << 31))) {

            val = 0xffffffff;

        } else {

            val = pci_data_read(phb->bus, phb->config_reg, 4);

        }

        if (!(s->regs[GT_PCI0_CMD] & 1) && (phb->config_reg & 0x00fff800)) {

            val = bswap32(val);

        }

        break;



    case GT_PCI0_CMD:

    case GT_PCI0_TOR:

    case GT_PCI0_BS_SCS10:

    case GT_PCI0_BS_SCS32:

    case GT_PCI0_BS_CS20:

    case GT_PCI0_BS_CS3BT:

    case GT_PCI1_IACK:

    case GT_PCI0_BARE:

    case GT_PCI0_PREFMBR:

    case GT_PCI0_SCS10_BAR:

    case GT_PCI0_SCS32_BAR:

    case GT_PCI0_CS20_BAR:

    case GT_PCI0_CS3BT_BAR:

    case GT_PCI0_SSCS10_BAR:

    case GT_PCI0_SSCS32_BAR:

    case GT_PCI0_SCS3BT_BAR:

    case GT_PCI1_CMD:

    case GT_PCI1_TOR:

    case GT_PCI1_BS_SCS10:

    case GT_PCI1_BS_SCS32:

    case GT_PCI1_BS_CS20:

    case GT_PCI1_BS_CS3BT:

    case GT_PCI1_BARE:

    case GT_PCI1_PREFMBR:

    case GT_PCI1_SCS10_BAR:

    case GT_PCI1_SCS32_BAR:

    case GT_PCI1_CS20_BAR:

    case GT_PCI1_CS3BT_BAR:

    case GT_PCI1_SSCS10_BAR:

    case GT_PCI1_SSCS32_BAR:

    case GT_PCI1_SCS3BT_BAR:

    case GT_PCI1_CFGADDR:

    case GT_PCI1_CFGDATA:

        val = s->regs[saddr];

        break;



    /* Interrupts */

    case GT_INTRCAUSE:

        val = s->regs[saddr];

        DPRINTF("INTRCAUSE %x\n", val);

        break;

    case GT_INTRMASK:

        val = s->regs[saddr];

        DPRINTF("INTRMASK %x\n", val);

        break;

    case GT_PCI0_ICMASK:

        val = s->regs[saddr];

        DPRINTF("ICMASK %x\n", val);

        break;

    case GT_PCI0_SERR0MASK:

        val = s->regs[saddr];

        DPRINTF("SERR0MASK %x\n", val);

        break;



    /* Reserved when only PCI_0 is configured. */

    case GT_HINTRCAUSE:

    case GT_CPU_INTSEL:

    case GT_PCI0_INTSEL:

    case GT_HINTRMASK:

    case GT_PCI0_HICMASK:

    case GT_PCI1_SERR1MASK:

        val = s->regs[saddr];

        break;



    default:

        val = s->regs[saddr];

        DPRINTF ("Bad register offset 0x%x\n", (int)addr);

        break;

    }



    if (!(s->regs[GT_CPU] & 0x00001000))

        val = bswap32(val);



    return val;

}

static QemuOpt *qemu_opt_find(QemuOpts *opts, const char *name)

{

    QemuOpt *opt;



    TAILQ_FOREACH(opt, &opts->head, next) {

        if (strcmp(opt->name, name) != 0)

            continue;

        return opt;

    }

    return NULL;

}

static int dnxhd_init_vlc(DNXHDContext *ctx, uint32_t cid)

{

    if (cid != ctx->cid) {

        int index;



        if ((index = ff_dnxhd_get_cid_table(cid)) < 0) {

            av_log(ctx->avctx, AV_LOG_ERROR, "unsupported cid %d\n", cid);

            return AVERROR(ENOSYS);

        }

        if (ff_dnxhd_cid_table[index].bit_depth != ctx->bit_depth) {

            av_log(ctx->avctx, AV_LOG_ERROR, "bit depth mismatches %d %d\n", ff_dnxhd_cid_table[index].bit_depth, ctx->bit_depth);

            return AVERROR_INVALIDDATA;

        }

        ctx->cid_table = &ff_dnxhd_cid_table[index];

        av_log(ctx->avctx, AV_LOG_VERBOSE, "Profile cid %d.\n", cid);



        ff_free_vlc(&ctx->ac_vlc);

        ff_free_vlc(&ctx->dc_vlc);

        ff_free_vlc(&ctx->run_vlc);



        init_vlc(&ctx->ac_vlc, DNXHD_VLC_BITS, 257,

                 ctx->cid_table->ac_bits, 1, 1,

                 ctx->cid_table->ac_codes, 2, 2, 0);

        init_vlc(&ctx->dc_vlc, DNXHD_DC_VLC_BITS, ctx->bit_depth + 4,

                 ctx->cid_table->dc_bits, 1, 1,

                 ctx->cid_table->dc_codes, 1, 1, 0);

        init_vlc(&ctx->run_vlc, DNXHD_VLC_BITS, 62,

                 ctx->cid_table->run_bits, 1, 1,

                 ctx->cid_table->run_codes, 2, 2, 0);



        ctx->cid = cid;

    }

    return 0;

}

static void tosa_init(MachineState *machine)

{

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    const char *kernel_cmdline = machine->kernel_cmdline;

    const char *initrd_filename = machine->initrd_filename;

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *rom = g_new(MemoryRegion, 1);

    PXA2xxState *mpu;

    TC6393xbState *tmio;

    DeviceState *scp0, *scp1;



    if (!cpu_model)

        cpu_model = "pxa255";



    mpu = pxa255_init(address_space_mem, tosa_binfo.ram_size);



    memory_region_init_ram(rom, NULL, "tosa.rom", TOSA_ROM, &error_abort);

    vmstate_register_ram_global(rom);

    memory_region_set_readonly(rom, true);

    memory_region_add_subregion(address_space_mem, 0, rom);



    tmio = tc6393xb_init(address_space_mem, 0x10000000,

            qdev_get_gpio_in(mpu->gpio, TOSA_GPIO_TC6393XB_INT));



    scp0 = sysbus_create_simple("scoop", 0x08800000, NULL);

    scp1 = sysbus_create_simple("scoop", 0x14800040, NULL);



    tosa_gpio_setup(mpu, scp0, scp1, tmio);



    tosa_microdrive_attach(mpu);



    tosa_tg_init(mpu);



    tosa_binfo.kernel_filename = kernel_filename;

    tosa_binfo.kernel_cmdline = kernel_cmdline;

    tosa_binfo.initrd_filename = initrd_filename;

    tosa_binfo.board_id = 0x208;

    arm_load_kernel(mpu->cpu, &tosa_binfo);

    sl_bootparam_write(SL_PXA_PARAM_BASE);

}

static int read_quant_table(RangeCoder *c, int16_t *quant_table, int scale)

{

    int v;

    int i = 0;

    uint8_t state[CONTEXT_SIZE];



    memset(state, 128, sizeof(state));



    for (v = 0; i < 128; v++) {

        unsigned len = get_symbol(c, state, 0) + 1;



        if (len > 128 - i)

            return AVERROR_INVALIDDATA;



        while (len--) {

            quant_table[i] = scale * v;

            i++;

        }

    }



    for (i = 1; i < 128; i++)

        quant_table[256 - i] = -quant_table[i];

    quant_table[128] = -quant_table[127];



    return 2 * v - 1;

}

static int qcow_create2(const char *filename, int64_t total_size,

                        const char *backing_file, const char *backing_format,

                        int flags, size_t cluster_size, int prealloc)

{



    int fd, header_size, backing_filename_len, l1_size, i, shift, l2_bits;

    int ref_clusters, backing_format_len = 0;

    int rounded_ext_bf_len = 0;

    QCowHeader header;

    uint64_t tmp, offset;

    QCowCreateState s1, *s = &s1;

    QCowExtension ext_bf = {0, 0};

    int ret;



    memset(s, 0, sizeof(*s));



    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC | O_BINARY, 0644);

    if (fd < 0)

        return -1;

    memset(&header, 0, sizeof(header));

    header.magic = cpu_to_be32(QCOW_MAGIC);

    header.version = cpu_to_be32(QCOW_VERSION);

    header.size = cpu_to_be64(total_size * 512);

    header_size = sizeof(header);

    backing_filename_len = 0;

    if (backing_file) {

        if (backing_format) {

            ext_bf.magic = QCOW_EXT_MAGIC_BACKING_FORMAT;

            backing_format_len = strlen(backing_format);

            ext_bf.len = backing_format_len;

            rounded_ext_bf_len = (sizeof(ext_bf) + ext_bf.len + 7) & ~7;

            header_size += rounded_ext_bf_len;

        }

        header.backing_file_offset = cpu_to_be64(header_size);

        backing_filename_len = strlen(backing_file);

        header.backing_file_size = cpu_to_be32(backing_filename_len);

        header_size += backing_filename_len;

    }



    /* Cluster size */

    s->cluster_bits = get_bits_from_size(cluster_size);

    if (s->cluster_bits < MIN_CLUSTER_BITS ||

        s->cluster_bits > MAX_CLUSTER_BITS)

    {

        fprintf(stderr, "Cluster size must be a power of two between "

            "%d and %dk\n",

            1 << MIN_CLUSTER_BITS,

            1 << (MAX_CLUSTER_BITS - 10));

        return -EINVAL;

    }

    s->cluster_size = 1 << s->cluster_bits;



    header.cluster_bits = cpu_to_be32(s->cluster_bits);

    header_size = (header_size + 7) & ~7;

    if (flags & BLOCK_FLAG_ENCRYPT) {

        header.crypt_method = cpu_to_be32(QCOW_CRYPT_AES);

    } else {

        header.crypt_method = cpu_to_be32(QCOW_CRYPT_NONE);

    }

    l2_bits = s->cluster_bits - 3;

    shift = s->cluster_bits + l2_bits;

    l1_size = (((total_size * 512) + (1LL << shift) - 1) >> shift);

    offset = align_offset(header_size, s->cluster_size);

    s->l1_table_offset = offset;

    header.l1_table_offset = cpu_to_be64(s->l1_table_offset);

    header.l1_size = cpu_to_be32(l1_size);

    offset += align_offset(l1_size * sizeof(uint64_t), s->cluster_size);



    s->refcount_table = qemu_mallocz(s->cluster_size);



    s->refcount_table_offset = offset;

    header.refcount_table_offset = cpu_to_be64(offset);

    header.refcount_table_clusters = cpu_to_be32(1);

    offset += s->cluster_size;

    s->refcount_block_offset = offset;



    /* count how many refcount blocks needed */

    tmp = offset >> s->cluster_bits;

    ref_clusters = (tmp >> (s->cluster_bits - REFCOUNT_SHIFT)) + 1;

    for (i=0; i < ref_clusters; i++) {

        s->refcount_table[i] = cpu_to_be64(offset);

        offset += s->cluster_size;

    }



    s->refcount_block = qemu_mallocz(ref_clusters * s->cluster_size);



    /* update refcounts */

    qcow2_create_refcount_update(s, 0, header_size);

    qcow2_create_refcount_update(s, s->l1_table_offset,

        l1_size * sizeof(uint64_t));

    qcow2_create_refcount_update(s, s->refcount_table_offset, s->cluster_size);

    qcow2_create_refcount_update(s, s->refcount_block_offset,

        ref_clusters * s->cluster_size);



    /* write all the data */

    ret = qemu_write_full(fd, &header, sizeof(header));

    if (ret != sizeof(header)) {

        ret = -1;

        goto exit;

    }

    if (backing_file) {

        if (backing_format_len) {

            char zero[16];

            int padding = rounded_ext_bf_len - (ext_bf.len + sizeof(ext_bf));



            memset(zero, 0, sizeof(zero));

            cpu_to_be32s(&ext_bf.magic);

            cpu_to_be32s(&ext_bf.len);

            ret = qemu_write_full(fd, &ext_bf, sizeof(ext_bf));

            if (ret != sizeof(ext_bf)) {

                ret = -1;

                goto exit;

            }

            ret = qemu_write_full(fd, backing_format, backing_format_len);

            if (ret != backing_format_len) {

                ret = -1;

                goto exit;

            }

            if (padding > 0) {

                ret = qemu_write_full(fd, zero, padding);

                if (ret != padding) {

                    ret = -1;

                    goto exit;

                }

            }

        }

        ret = qemu_write_full(fd, backing_file, backing_filename_len);

        if (ret != backing_filename_len) {

            ret = -1;

            goto exit;

        }

    }

    lseek(fd, s->l1_table_offset, SEEK_SET);

    tmp = 0;

    for(i = 0;i < l1_size; i++) {

        ret = qemu_write_full(fd, &tmp, sizeof(tmp));

        if (ret != sizeof(tmp)) {

            ret = -1;

            goto exit;

        }

    }

    lseek(fd, s->refcount_table_offset, SEEK_SET);

    ret = qemu_write_full(fd, s->refcount_table, s->cluster_size);

    if (ret != s->cluster_size) {

        ret = -1;

        goto exit;

    }



    lseek(fd, s->refcount_block_offset, SEEK_SET);

    ret = qemu_write_full(fd, s->refcount_block,

		    ref_clusters * s->cluster_size);

    if (ret != s->cluster_size) {

        ret = -1;

        goto exit;

    }



    ret = 0;

exit:

    qemu_free(s->refcount_table);

    qemu_free(s->refcount_block);

    close(fd);



    /* Preallocate metadata */

    if (prealloc) {

        BlockDriverState *bs;

        bs = bdrv_new("");

        bdrv_open(bs, filename, BDRV_O_CACHE_WB | BDRV_O_RDWR);

        preallocate(bs);

        bdrv_close(bs);

    }



    return ret;

}

static void omap_prcm_dpll_update(struct omap_prcm_s *s)

{

    omap_clk dpll = omap_findclk(s->mpu, "dpll");

    omap_clk dpll_x2 = omap_findclk(s->mpu, "dpll");

    omap_clk core = omap_findclk(s->mpu, "core_clk");

    int mode = (s->clken[9] >> 0) & 3;

    int mult, div;



    mult = (s->clksel[5] >> 12) & 0x3ff;

    div = (s->clksel[5] >> 8) & 0xf;

    if (mult == 0 || mult == 1)

        mode = 1;	/* Bypass */



    s->dpll_lock = 0;

    switch (mode) {

    case 0:

        fprintf(stderr, "%s: bad EN_DPLL\n", __FUNCTION__);

        break;

    case 1:	/* Low-power bypass mode (Default) */

    case 2:	/* Fast-relock bypass mode */

        omap_clk_setrate(dpll, 1, 1);

        omap_clk_setrate(dpll_x2, 1, 1);

        break;

    case 3:	/* Lock mode */

        s->dpll_lock = 1; /* After 20 FINT cycles (ref_clk / (div + 1)).  */



        omap_clk_setrate(dpll, div + 1, mult);

        omap_clk_setrate(dpll_x2, div + 1, mult * 2);

        break;

    }



    switch ((s->clksel[6] >> 0) & 3) {

    case 0:

        omap_clk_reparent(core, omap_findclk(s->mpu, "clk32-kHz"));

        break;

    case 1:

        omap_clk_reparent(core, dpll);

        break;

    case 2:

        /* Default */

        omap_clk_reparent(core, dpll_x2);

        break;

    case 3:

        fprintf(stderr, "%s: bad CORE_CLK_SRC\n", __FUNCTION__);

        break;

    }

}

static int parse_source_parameters(AVCodecContext *avctx, GetBitContext *gb,

                                   dirac_source_params *source)

{

    AVRational frame_rate = {0,0};

    unsigned luma_depth = 8, luma_offset = 16;

    int idx;

    int chroma_x_shift, chroma_y_shift;



    /* [DIRAC_STD] 10.3.2 Frame size. frame_size(video_params) */

    /* [DIRAC_STD] custom_dimensions_flag */

    if (get_bits1(gb)) {

        source->width  = svq3_get_ue_golomb(gb); /* [DIRAC_STD] FRAME_WIDTH  */

        source->height = svq3_get_ue_golomb(gb); /* [DIRAC_STD] FRAME_HEIGHT */

    }



    /* [DIRAC_STD] 10.3.3 Chroma Sampling Format.

     *  chroma_sampling_format(video_params) */

    /* [DIRAC_STD] custom_chroma_format_flag */

    if (get_bits1(gb))

        /* [DIRAC_STD] CHROMA_FORMAT_INDEX */

        source->chroma_format = svq3_get_ue_golomb(gb);

    if (source->chroma_format > 2U) {

        av_log(avctx, AV_LOG_ERROR, "Unknown chroma format %d\n",

               source->chroma_format);

        return AVERROR_INVALIDDATA;

    }



    /* [DIRAC_STD] 10.3.4 Scan Format. scan_format(video_params) */

    /* [DIRAC_STD] custom_scan_format_flag */

    if (get_bits1(gb))

        /* [DIRAC_STD] SOURCE_SAMPLING */

        source->interlaced = svq3_get_ue_golomb(gb);

    if (source->interlaced > 1U)

        return AVERROR_INVALIDDATA;



    /* [DIRAC_STD] 10.3.5 Frame Rate. frame_rate(video_params) */

    if (get_bits1(gb)) { /* [DIRAC_STD] custom_frame_rate_flag */

        source->frame_rate_index = svq3_get_ue_golomb(gb);



        if (source->frame_rate_index > 10U)

            return AVERROR_INVALIDDATA;



        if (!source->frame_rate_index) {

            /* [DIRAC_STD] FRAME_RATE_NUMER */

            frame_rate.num = svq3_get_ue_golomb(gb);

            /* [DIRAC_STD] FRAME_RATE_DENOM */

            frame_rate.den = svq3_get_ue_golomb(gb);

        }

    }

    /* [DIRAC_STD] preset_frame_rate(video_params, index) */

    if (source->frame_rate_index > 0) {

        if (source->frame_rate_index <= 8)

            frame_rate = ff_mpeg12_frame_rate_tab[source->frame_rate_index];

        else

             /* [DIRAC_STD] Table 10.3 values 9-10 */

            frame_rate = dirac_frame_rate[source->frame_rate_index-9];

    }

    av_reduce(&avctx->time_base.num, &avctx->time_base.den,

              frame_rate.den, frame_rate.num, 1<<30);



    /* [DIRAC_STD] 10.3.6 Pixel Aspect Ratio.

     * pixel_aspect_ratio(video_params) */

    if (get_bits1(gb)) { /* [DIRAC_STD] custom_pixel_aspect_ratio_flag */

         /* [DIRAC_STD] index */

        source->aspect_ratio_index = svq3_get_ue_golomb(gb);



        if (source->aspect_ratio_index > 6U)

            return AVERROR_INVALIDDATA;



        if (!source->aspect_ratio_index) {

            avctx->sample_aspect_ratio.num = svq3_get_ue_golomb(gb);

            avctx->sample_aspect_ratio.den = svq3_get_ue_golomb(gb);

        }

    }

    /* [DIRAC_STD] Take value from Table 10.4 Available preset pixel

     *  aspect ratio values */

    if (source->aspect_ratio_index > 0)

        avctx->sample_aspect_ratio =

            dirac_preset_aspect_ratios[source->aspect_ratio_index-1];



    /* [DIRAC_STD] 10.3.7 Clean area. clean_area(video_params) */

    if (get_bits1(gb)) { /* [DIRAC_STD] custom_clean_area_flag */

        /* [DIRAC_STD] CLEAN_WIDTH */

        source->clean_width        = svq3_get_ue_golomb(gb);

         /* [DIRAC_STD] CLEAN_HEIGHT */

        source->clean_height       = svq3_get_ue_golomb(gb);

         /* [DIRAC_STD] CLEAN_LEFT_OFFSET */

        source->clean_left_offset  = svq3_get_ue_golomb(gb);

        /* [DIRAC_STD] CLEAN_RIGHT_OFFSET */

        source->clean_right_offset = svq3_get_ue_golomb(gb);

    }



    /* [DIRAC_STD] 10.3.8 Signal range. signal_range(video_params)

     * WARNING: Some adaptation seems to be done using the

     * AVCOL_RANGE_MPEG/JPEG values */

    if (get_bits1(gb)) { /* [DIRAC_STD] custom_signal_range_flag */

        /* [DIRAC_STD] index */

        source->pixel_range_index = svq3_get_ue_golomb(gb);



        if (source->pixel_range_index > 4U)

            return AVERROR_INVALIDDATA;



        /* This assumes either fullrange or MPEG levels only */

        if (!source->pixel_range_index) {

            luma_offset = svq3_get_ue_golomb(gb);

            luma_depth  = av_log2(svq3_get_ue_golomb(gb))+1;

            svq3_get_ue_golomb(gb); /* chroma offset    */

            svq3_get_ue_golomb(gb); /* chroma excursion */

            avctx->color_range = luma_offset ? AVCOL_RANGE_MPEG : AVCOL_RANGE_JPEG;

        }

    }

    /* [DIRAC_STD] Table 10.5

     * Available signal range presets <--> pixel_range_presets */

    if (source->pixel_range_index > 0) {

        idx                = source->pixel_range_index-1;

        luma_depth         = pixel_range_presets[idx].bitdepth;

        avctx->color_range = pixel_range_presets[idx].color_range;

    }



    if (luma_depth > 8)

        av_log(avctx, AV_LOG_WARNING, "Bitdepth greater than 8\n");



    avctx->pix_fmt = dirac_pix_fmt[!luma_offset][source->chroma_format];

    avcodec_get_chroma_sub_sample(avctx->pix_fmt, &chroma_x_shift, &chroma_y_shift);

    if (!(source->width % (1<<chroma_x_shift)) || !(source->height % (1<<chroma_y_shift))) {

        av_log(avctx, AV_LOG_ERROR, "Dimensions must be a integer multiply of the chroma subsampling\n");

        return AVERROR_INVALIDDATA;

    }





    /* [DIRAC_STD] 10.3.9 Colour specification. colour_spec(video_params) */

    if (get_bits1(gb)) { /* [DIRAC_STD] custom_colour_spec_flag */

         /* [DIRAC_STD] index */

        idx = source->color_spec_index = svq3_get_ue_golomb(gb);



        if (source->color_spec_index > 4U)

            return AVERROR_INVALIDDATA;



        avctx->color_primaries = dirac_color_presets[idx].color_primaries;

        avctx->colorspace      = dirac_color_presets[idx].colorspace;

        avctx->color_trc       = dirac_color_presets[idx].color_trc;



        if (!source->color_spec_index) {

            /* [DIRAC_STD] 10.3.9.1 Colour primaries */

            if (get_bits1(gb)) {

                idx = svq3_get_ue_golomb(gb);

                if (idx < 3U)

                    avctx->color_primaries = dirac_primaries[idx];

            }

            /* [DIRAC_STD] 10.3.9.2 Colour matrix */

            if (get_bits1(gb)) {

                idx = svq3_get_ue_golomb(gb);

                if (!idx)

                    avctx->colorspace = AVCOL_SPC_BT709;

                else if (idx == 1)

                    avctx->colorspace = AVCOL_SPC_BT470BG;

            }

            /* [DIRAC_STD] 10.3.9.3 Transfer function */

            if (get_bits1(gb) && !svq3_get_ue_golomb(gb))

                avctx->color_trc = AVCOL_TRC_BT709;

        }

    } else {

        idx = source->color_spec_index;

        avctx->color_primaries = dirac_color_presets[idx].color_primaries;

        avctx->colorspace      = dirac_color_presets[idx].colorspace;

        avctx->color_trc       = dirac_color_presets[idx].color_trc;

    }



    return 0;

}

static int virtio_blk_handle_rw_error(VirtIOBlockReq *req, int error,

    bool is_read)

{

    BlockErrorAction action = bdrv_get_error_action(req->dev->bs, is_read, error);

    VirtIOBlock *s = req->dev;



    if (action == BLOCK_ERROR_ACTION_STOP) {

        req->next = s->rq;

        s->rq = req;

    } else if (action == BLOCK_ERROR_ACTION_REPORT) {

        virtio_blk_req_complete(req, VIRTIO_BLK_S_IOERR);

        block_acct_done(bdrv_get_stats(s->bs), &req->acct);

        virtio_blk_free_request(req);

    }



    bdrv_error_action(s->bs, action, is_read, error);

    return action != BLOCK_ERROR_ACTION_IGNORE;

}

static av_cold int vc2_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                                      const AVFrame *frame, int *got_packet)

{

    int ret = 0;

    int sig_size = 256;

    VC2EncContext *s = avctx->priv_data;

    const char aux_data[] = LIBAVCODEC_IDENT;

    const int aux_data_size = sizeof(aux_data);

    const int header_size = 100 + aux_data_size;

    int64_t max_frame_bytes, r_bitrate = avctx->bit_rate >> (s->interlaced);



    s->avctx = avctx;

    s->size_scaler = 1;

    s->prefix_bytes = 0;

    s->last_parse_code = 0;

    s->next_parse_offset = 0;



    /* Rate control */

    max_frame_bytes = (av_rescale(r_bitrate, s->avctx->time_base.num,

                                  s->avctx->time_base.den) >> 3) - header_size;



    /* Find an appropriate size scaler */

    while (sig_size > 255) {

        s->slice_max_bytes = FFALIGN(av_rescale(max_frame_bytes, 1,

                                                s->num_x*s->num_y), s->size_scaler);

        s->slice_max_bytes += 4 + s->prefix_bytes;

        sig_size = s->slice_max_bytes/s->size_scaler; /* Signalled slize size */

        s->size_scaler <<= 1;

    }



    s->slice_min_bytes = s->slice_max_bytes - s->slice_max_bytes*(s->tolerance/100.0f);



    ret = encode_frame(s, avpkt, frame, aux_data, header_size, s->interlaced);

    if (ret)

        return ret;

    if (s->interlaced) {

        ret = encode_frame(s, avpkt, frame, aux_data, header_size, 2);

        if (ret)

            return ret;

    }



    flush_put_bits(&s->pb);

    avpkt->size = put_bits_count(&s->pb) >> 3;



    *got_packet = 1;



    return 0;

}

static ImageInfoSpecific *vmdk_get_specific_info(BlockDriverState *bs)

{

    int i;

    BDRVVmdkState *s = bs->opaque;

    ImageInfoSpecific *spec_info = g_new0(ImageInfoSpecific, 1);

    ImageInfoList **next;



    *spec_info = (ImageInfoSpecific){

        .type = IMAGE_INFO_SPECIFIC_KIND_VMDK,

        {

            .vmdk = g_new0(ImageInfoSpecificVmdk, 1),

        },

    };



    *spec_info->u.vmdk = (ImageInfoSpecificVmdk) {

        .create_type = g_strdup(s->create_type),

        .cid = s->cid,

        .parent_cid = s->parent_cid,

    };



    next = &spec_info->u.vmdk->extents;

    for (i = 0; i < s->num_extents; i++) {

        *next = g_new0(ImageInfoList, 1);

        (*next)->value = vmdk_get_extent_info(&s->extents[i]);

        (*next)->next = NULL;

        next = &(*next)->next;

    }



    return spec_info;

}

static int ogg_build_flac_headers(AVCodecContext *avctx,

                                  OGGStreamContext *oggstream, int bitexact)

{

    const char *vendor = bitexact ? "ffmpeg" : LIBAVFORMAT_IDENT;

    enum FLACExtradataFormat format;

    uint8_t *streaminfo;

    uint8_t *p;

    if (!ff_flac_is_extradata_valid(avctx, &format, &streaminfo))

        return -1;

    oggstream->header_len[0] = 51;

    oggstream->header[0] = av_mallocz(51); // per ogg flac specs

    p = oggstream->header[0];



    bytestream_put_byte(&p, 0x7F);

    bytestream_put_buffer(&p, "FLAC", 4);

    bytestream_put_byte(&p, 1); // major version

    bytestream_put_byte(&p, 0); // minor version

    bytestream_put_be16(&p, 1); // headers packets without this one

    bytestream_put_buffer(&p, "fLaC", 4);

    bytestream_put_byte(&p, 0x00); // streaminfo

    bytestream_put_be24(&p, 34);

    bytestream_put_buffer(&p, streaminfo, FLAC_STREAMINFO_SIZE);

    oggstream->header_len[1] = 1+3+4+strlen(vendor)+4;

    oggstream->header[1] = av_mallocz(oggstream->header_len[1]);

    p = oggstream->header[1];



    bytestream_put_byte(&p, 0x84); // last metadata block and vorbis comment

    bytestream_put_be24(&p, oggstream->header_len[1] - 4);

    bytestream_put_le32(&p, strlen(vendor));

    bytestream_put_buffer(&p, vendor, strlen(vendor));

    bytestream_put_le32(&p, 0); // user comment list length

    return 0;

}

static int decode_lt_rps(HEVCContext *s, LongTermRPS *rps, GetBitContext *gb)

{

    const HEVCSPS *sps = s->ps.sps;

    int max_poc_lsb    = 1 << sps->log2_max_poc_lsb;

    int prev_delta_msb = 0;

    unsigned int nb_sps = 0, nb_sh;

    int i;



    rps->nb_refs = 0;

    if (!sps->long_term_ref_pics_present_flag)

        return 0;



    if (sps->num_long_term_ref_pics_sps > 0)

        nb_sps = get_ue_golomb_long(gb);

    nb_sh = get_ue_golomb_long(gb);



    if (nb_sps > sps->num_long_term_ref_pics_sps)

        return AVERROR_INVALIDDATA;

    if (nb_sh + (uint64_t)nb_sps > FF_ARRAY_ELEMS(rps->poc))

        return AVERROR_INVALIDDATA;



    rps->nb_refs = nb_sh + nb_sps;



    for (i = 0; i < rps->nb_refs; i++) {

        uint8_t delta_poc_msb_present;



        if (i < nb_sps) {

            uint8_t lt_idx_sps = 0;



            if (sps->num_long_term_ref_pics_sps > 1)

                lt_idx_sps = get_bits(gb, av_ceil_log2(sps->num_long_term_ref_pics_sps));



            rps->poc[i]  = sps->lt_ref_pic_poc_lsb_sps[lt_idx_sps];

            rps->used[i] = sps->used_by_curr_pic_lt_sps_flag[lt_idx_sps];

        } else {

            rps->poc[i]  = get_bits(gb, sps->log2_max_poc_lsb);

            rps->used[i] = get_bits1(gb);

        }



        delta_poc_msb_present = get_bits1(gb);

        if (delta_poc_msb_present) {

            int delta = get_ue_golomb_long(gb);



            if (i && i != nb_sps)

                delta += prev_delta_msb;



            rps->poc[i] += s->poc - delta * max_poc_lsb - s->sh.pic_order_cnt_lsb;

            prev_delta_msb = delta;

        }

    }



    return 0;

}

