int av_image_fill_black(uint8_t *dst_data[4], const ptrdiff_t dst_linesize[4],

                        enum AVPixelFormat pix_fmt, enum AVColorRange range,

                        int width, int height)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(pix_fmt);

    int nb_planes = av_pix_fmt_count_planes(pix_fmt);

    // A pixel or a group of pixels on each plane, with a value that represents black.

    // Consider e.g. AV_PIX_FMT_UYVY422 for non-trivial cases.

    uint8_t clear_block[4][MAX_BLOCK_SIZE] = {0}; // clear padding with 0

    int clear_block_size[4] = {0};

    ptrdiff_t plane_line_bytes[4] = {0};

    int rgb, limited;

    int plane, c;



    if (!desc || nb_planes < 1 || nb_planes > 4 || desc->flags & AV_PIX_FMT_FLAG_HWACCEL)

        return AVERROR(EINVAL);



    rgb = !!(desc->flags & AV_PIX_FMT_FLAG_RGB);

    limited = !rgb && range != AVCOL_RANGE_JPEG;



    if (desc->flags & AV_PIX_FMT_FLAG_BITSTREAM) {

        ptrdiff_t bytewidth = av_image_get_linesize(pix_fmt, width, 0);

        uint8_t *data;

        int mono = pix_fmt == AV_PIX_FMT_MONOWHITE || pix_fmt == AV_PIX_FMT_MONOBLACK;

        int fill = pix_fmt == AV_PIX_FMT_MONOWHITE ? 0xFF : 0;

        if (nb_planes != 1 || !(rgb || mono) || bytewidth < 1)

            return AVERROR(EINVAL);



        if (!dst_data)

            return 0;



        data = dst_data[0];



        // (Bitstream + alpha will be handled incorrectly - it'll remain transparent.)

        for (;height > 0; height--) {

            memset(data, fill, bytewidth);

            data += dst_linesize[0];

        }

        return 0;

    }



    for (c = 0; c < desc->nb_components; c++) {

        const AVComponentDescriptor comp = desc->comp[c];



        // We try to operate on entire non-subsampled pixel groups (for

        // AV_PIX_FMT_UYVY422 this would mean two consecutive pixels).

        clear_block_size[comp.plane] = FFMAX(clear_block_size[comp.plane], comp.step);



        if (clear_block_size[comp.plane] > MAX_BLOCK_SIZE)

            return AVERROR(EINVAL);

    }



    // Create a byte array for clearing 1 pixel (sometimes several pixels).

    for (c = 0; c < desc->nb_components; c++) {

        const AVComponentDescriptor comp = desc->comp[c];

        // (Multiple pixels happen e.g. with AV_PIX_FMT_UYVY422.)

        int w = clear_block_size[comp.plane] / comp.step;

        uint8_t *c_data[4];

        const int c_linesize[4] = {0};

        uint16_t src_array[MAX_BLOCK_SIZE];

        uint16_t src = 0;

        int x;



        if (comp.depth > 16)

            return AVERROR(EINVAL);

        if (!rgb && comp.depth < 8)

            return AVERROR(EINVAL);

        if (w < 1)

            return AVERROR(EINVAL);



        if (c == 0 && limited) {

            src = 16 << (comp.depth - 8);

        } else if ((c == 1 || c == 2) && !rgb) {

            src = 128 << (comp.depth - 8);

        } else if (c == 3) {

            // (Assume even limited YUV uses full range alpha.)

            src = (1 << comp.depth) - 1;

        }



        for (x = 0; x < w; x++)

            src_array[x] = src;



        for (x = 0; x < 4; x++)

            c_data[x] = &clear_block[x][0];



        av_write_image_line(src_array, c_data, c_linesize, desc, 0, 0, c, w);

    }



    for (plane = 0; plane < nb_planes; plane++) {

        plane_line_bytes[plane] = av_image_get_linesize(pix_fmt, width, plane);

        if (plane_line_bytes[plane] < 0)

            return AVERROR(EINVAL);

    }



    if (!dst_data)

        return 0;



    for (plane = 0; plane < nb_planes; plane++) {

        size_t bytewidth = plane_line_bytes[plane];

        uint8_t *data = dst_data[plane];

        int chroma_div = plane == 1 || plane == 2 ? desc->log2_chroma_h : 0;

        int plane_h = ((height + ( 1 << chroma_div) - 1)) >> chroma_div;



        for (; plane_h > 0; plane_h--) {

            memset_bytes(data, bytewidth, &clear_block[plane][0], clear_block_size[plane]);

            data += dst_linesize[plane];

        }

    }



    return 0;

}

int ff_parse_mpeg2_descriptor(AVFormatContext *fc, AVStream *st, int stream_type,

                              const uint8_t **pp, const uint8_t *desc_list_end,

                              Mp4Descr *mp4_descr, int mp4_descr_count, int pid,

                              MpegTSContext *ts)

{

    const uint8_t *desc_end;

    int desc_len, desc_tag, desc_es_id;

    char language[252];

    int i;



    desc_tag = get8(pp, desc_list_end);

    if (desc_tag < 0)

        return AVERROR_INVALIDDATA;

    desc_len = get8(pp, desc_list_end);

    if (desc_len < 0)

        return AVERROR_INVALIDDATA;

    desc_end = *pp + desc_len;

    if (desc_end > desc_list_end)

        return AVERROR_INVALIDDATA;



    av_dlog(fc, "tag: 0x%02x len=%d\n", desc_tag, desc_len);



    if (st->codec->codec_id == AV_CODEC_ID_NONE &&

        stream_type == STREAM_TYPE_PRIVATE_DATA)

        mpegts_find_stream_type(st, desc_tag, DESC_types);



    switch (desc_tag) {

    case 0x1E: /* SL descriptor */

        desc_es_id = get16(pp, desc_end);

        if (ts && ts->pids[pid])

            ts->pids[pid]->es_id = desc_es_id;

        for (i = 0; i < mp4_descr_count; i++)

            if (mp4_descr[i].dec_config_descr_len &&

                mp4_descr[i].es_id == desc_es_id) {

                AVIOContext pb;

                ffio_init_context(&pb, mp4_descr[i].dec_config_descr,

                                  mp4_descr[i].dec_config_descr_len, 0,

                                  NULL, NULL, NULL, NULL);

                ff_mp4_read_dec_config_descr(fc, st, &pb);

                if (st->codec->codec_id == AV_CODEC_ID_AAC &&

                    st->codec->extradata_size > 0)

                    st->need_parsing = 0;

                if (st->codec->codec_id == AV_CODEC_ID_MPEG4SYSTEMS)

                    mpegts_open_section_filter(ts, pid, m4sl_cb, ts, 1);

            }

        break;

    case 0x1F: /* FMC descriptor */

        get16(pp, desc_end);

        if (mp4_descr_count > 0 &&

            st->codec->codec_id == AV_CODEC_ID_AAC_LATM &&

            mp4_descr->dec_config_descr_len && mp4_descr->es_id == pid) {

            AVIOContext pb;

            ffio_init_context(&pb, mp4_descr->dec_config_descr,

                              mp4_descr->dec_config_descr_len, 0,

                              NULL, NULL, NULL, NULL);

            ff_mp4_read_dec_config_descr(fc, st, &pb);

            if (st->codec->codec_id == AV_CODEC_ID_AAC &&

                st->codec->extradata_size > 0)

                st->need_parsing = 0;

        }

        break;

    case 0x56: /* DVB teletext descriptor */

        language[0] = get8(pp, desc_end);

        language[1] = get8(pp, desc_end);

        language[2] = get8(pp, desc_end);

        language[3] = 0;

        av_dict_set(&st->metadata, "language", language, 0);

        break;

    case 0x59: /* subtitling descriptor */

        language[0] = get8(pp, desc_end);

        language[1] = get8(pp, desc_end);

        language[2] = get8(pp, desc_end);

        language[3] = 0;

        /* hearing impaired subtitles detection */

        switch (get8(pp, desc_end)) {

        case 0x20: /* DVB subtitles (for the hard of hearing) with no monitor aspect ratio criticality */

        case 0x21: /* DVB subtitles (for the hard of hearing) for display on 4:3 aspect ratio monitor */

        case 0x22: /* DVB subtitles (for the hard of hearing) for display on 16:9 aspect ratio monitor */

        case 0x23: /* DVB subtitles (for the hard of hearing) for display on 2.21:1 aspect ratio monitor */

        case 0x24: /* DVB subtitles (for the hard of hearing) for display on a high definition monitor */

        case 0x25: /* DVB subtitles (for the hard of hearing) with plano-stereoscopic disparity for display on a high definition monitor */

            st->disposition |= AV_DISPOSITION_HEARING_IMPAIRED;

            break;

        }

        if (st->codec->extradata) {

            if (st->codec->extradata_size == 4 &&

                memcmp(st->codec->extradata, *pp, 4))

                avpriv_request_sample(fc, "DVB sub with multiple IDs");

        } else {

            st->codec->extradata = av_malloc(4 + FF_INPUT_BUFFER_PADDING_SIZE);

            if (st->codec->extradata) {

                st->codec->extradata_size = 4;

                memcpy(st->codec->extradata, *pp, 4);

            }

        }

        *pp += 4;

        av_dict_set(&st->metadata, "language", language, 0);

        break;

    case 0x0a: /* ISO 639 language descriptor */

        for (i = 0; i + 4 <= desc_len; i += 4) {

            language[i + 0] = get8(pp, desc_end);

            language[i + 1] = get8(pp, desc_end);

            language[i + 2] = get8(pp, desc_end);

            language[i + 3] = ',';

            switch (get8(pp, desc_end)) {

            case 0x01:

                st->disposition |= AV_DISPOSITION_CLEAN_EFFECTS;

                break;

            case 0x02:

                st->disposition |= AV_DISPOSITION_HEARING_IMPAIRED;

                break;

            case 0x03:

                st->disposition |= AV_DISPOSITION_VISUAL_IMPAIRED;

                break;

            }

        }

        if (i && language[0]) {

            language[i - 1] = 0;

            av_dict_set(&st->metadata, "language", language, 0);

        }

        break;

    case 0x05: /* registration descriptor */

        st->codec->codec_tag = bytestream_get_le32(pp);

        av_dlog(fc, "reg_desc=%.4s\n", (char *)&st->codec->codec_tag);

        if (st->codec->codec_id == AV_CODEC_ID_NONE)

            mpegts_find_stream_type(st, st->codec->codec_tag, REGD_types);

        break;

    default:

        break;

    }

    *pp = desc_end;

    return 0;

}

static void gen_dcbi(DisasContext *ctx)

{

#if defined(CONFIG_USER_ONLY)

    gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

#else

    TCGv EA, val;

    if (unlikely(ctx->pr)) {

        gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

        return;

    }

    EA = tcg_temp_new();

    gen_set_access_type(ctx, ACCESS_CACHE);

    gen_addr_reg_index(ctx, EA);

    val = tcg_temp_new();

    /* XXX: specification says this should be treated as a store by the MMU */

    gen_qemu_ld8u(ctx, val, EA);

    gen_qemu_st8(ctx, val, EA);

    tcg_temp_free(val);

    tcg_temp_free(EA);

#endif

}

