int MPV_common_init(MpegEncContext *s)

{

    int y_size, c_size, yc_size, i, mb_array_size, mv_table_size, x, y, threads;



    s->mb_height = (s->height + 15) / 16;



    if(s->avctx->thread_count > MAX_THREADS || (s->avctx->thread_count > s->mb_height && s->mb_height)){

        av_log(s->avctx, AV_LOG_ERROR, "too many threads\n");

        return -1;

    }



    if((s->width || s->height) && avcodec_check_dimensions(s->avctx, s->width, s->height))

        return -1;



    dsputil_init(&s->dsp, s->avctx);

    ff_dct_common_init(s);



    s->flags= s->avctx->flags;

    s->flags2= s->avctx->flags2;



    s->mb_width  = (s->width  + 15) / 16;

    s->mb_stride = s->mb_width + 1;

    s->b8_stride = s->mb_width*2 + 1;

    s->b4_stride = s->mb_width*4 + 1;

    mb_array_size= s->mb_height * s->mb_stride;

    mv_table_size= (s->mb_height+2) * s->mb_stride + 1;



    /* set chroma shifts */

    avcodec_get_chroma_sub_sample(s->avctx->pix_fmt,&(s->chroma_x_shift),

                                                    &(s->chroma_y_shift) );



    /* set default edge pos, will be overriden in decode_header if needed */

    s->h_edge_pos= s->mb_width*16;

    s->v_edge_pos= s->mb_height*16;



    s->mb_num = s->mb_width * s->mb_height;



    s->block_wrap[0]=

    s->block_wrap[1]=

    s->block_wrap[2]=

    s->block_wrap[3]= s->b8_stride;

    s->block_wrap[4]=

    s->block_wrap[5]= s->mb_stride;



    y_size = s->b8_stride * (2 * s->mb_height + 1);

    c_size = s->mb_stride * (s->mb_height + 1);

    yc_size = y_size + 2 * c_size;



    /* convert fourcc to upper case */

    s->codec_tag=          toupper( s->avctx->codec_tag     &0xFF)

                        + (toupper((s->avctx->codec_tag>>8 )&0xFF)<<8 )

                        + (toupper((s->avctx->codec_tag>>16)&0xFF)<<16)

                        + (toupper((s->avctx->codec_tag>>24)&0xFF)<<24);



    s->stream_codec_tag=          toupper( s->avctx->stream_codec_tag     &0xFF)

                               + (toupper((s->avctx->stream_codec_tag>>8 )&0xFF)<<8 )

                               + (toupper((s->avctx->stream_codec_tag>>16)&0xFF)<<16)

                               + (toupper((s->avctx->stream_codec_tag>>24)&0xFF)<<24);



    s->avctx->coded_frame= (AVFrame*)&s->current_picture;



    CHECKED_ALLOCZ(s->mb_index2xy, (s->mb_num+1)*sizeof(int)) //error ressilience code looks cleaner with this

    for(y=0; y<s->mb_height; y++){

        for(x=0; x<s->mb_width; x++){

            s->mb_index2xy[ x + y*s->mb_width ] = x + y*s->mb_stride;

        }

    }

    s->mb_index2xy[ s->mb_height*s->mb_width ] = (s->mb_height-1)*s->mb_stride + s->mb_width; //FIXME really needed?



    if (s->encoding) {

        /* Allocate MV tables */

        CHECKED_ALLOCZ(s->p_mv_table_base            , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_forw_mv_table_base       , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_back_mv_table_base       , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_bidir_forw_mv_table_base , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_bidir_back_mv_table_base , mv_table_size * 2 * sizeof(int16_t))

        CHECKED_ALLOCZ(s->b_direct_mv_table_base     , mv_table_size * 2 * sizeof(int16_t))

        s->p_mv_table           = s->p_mv_table_base            + s->mb_stride + 1;

        s->b_forw_mv_table      = s->b_forw_mv_table_base       + s->mb_stride + 1;

        s->b_back_mv_table      = s->b_back_mv_table_base       + s->mb_stride + 1;

        s->b_bidir_forw_mv_table= s->b_bidir_forw_mv_table_base + s->mb_stride + 1;

        s->b_bidir_back_mv_table= s->b_bidir_back_mv_table_base + s->mb_stride + 1;

        s->b_direct_mv_table    = s->b_direct_mv_table_base     + s->mb_stride + 1;



        if(s->msmpeg4_version){

            CHECKED_ALLOCZ(s->ac_stats, 2*2*(MAX_LEVEL+1)*(MAX_RUN+1)*2*sizeof(int));

        }

        CHECKED_ALLOCZ(s->avctx->stats_out, 256);



        /* Allocate MB type table */

        CHECKED_ALLOCZ(s->mb_type  , mb_array_size * sizeof(uint16_t)) //needed for encoding



        CHECKED_ALLOCZ(s->lambda_table, mb_array_size * sizeof(int))



        CHECKED_ALLOCZ(s->q_intra_matrix, 64*32 * sizeof(int))

        CHECKED_ALLOCZ(s->q_inter_matrix, 64*32 * sizeof(int))

        CHECKED_ALLOCZ(s->q_intra_matrix16, 64*32*2 * sizeof(uint16_t))

        CHECKED_ALLOCZ(s->q_inter_matrix16, 64*32*2 * sizeof(uint16_t))

        CHECKED_ALLOCZ(s->input_picture, MAX_PICTURE_COUNT * sizeof(Picture*))

        CHECKED_ALLOCZ(s->reordered_input_picture, MAX_PICTURE_COUNT * sizeof(Picture*))



        if(s->avctx->noise_reduction){

            CHECKED_ALLOCZ(s->dct_offset, 2 * 64 * sizeof(uint16_t))

        }

    }

    CHECKED_ALLOCZ(s->picture, MAX_PICTURE_COUNT * sizeof(Picture))



    CHECKED_ALLOCZ(s->error_status_table, mb_array_size*sizeof(uint8_t))



    if(s->codec_id==CODEC_ID_MPEG4 || (s->flags & CODEC_FLAG_INTERLACED_ME)){

        /* interlaced direct mode decoding tables */

            for(i=0; i<2; i++){

                int j, k;

                for(j=0; j<2; j++){

                    for(k=0; k<2; k++){

                        CHECKED_ALLOCZ(s->b_field_mv_table_base[i][j][k]     , mv_table_size * 2 * sizeof(int16_t))

                        s->b_field_mv_table[i][j][k]    = s->b_field_mv_table_base[i][j][k]     + s->mb_stride + 1;

                    }

                    CHECKED_ALLOCZ(s->b_field_select_table[i][j]     , mb_array_size * 2 * sizeof(uint8_t))

                    CHECKED_ALLOCZ(s->p_field_mv_table_base[i][j]     , mv_table_size * 2 * sizeof(int16_t))

                    s->p_field_mv_table[i][j]    = s->p_field_mv_table_base[i][j]     + s->mb_stride + 1;

                }

                CHECKED_ALLOCZ(s->p_field_select_table[i]      , mb_array_size * 2 * sizeof(uint8_t))

            }

    }

    if (s->out_format == FMT_H263) {

        /* ac values */

        CHECKED_ALLOCZ(s->ac_val_base, yc_size * sizeof(int16_t) * 16);

        s->ac_val[0] = s->ac_val_base + s->b8_stride + 1;

        s->ac_val[1] = s->ac_val_base + y_size + s->mb_stride + 1;

        s->ac_val[2] = s->ac_val[1] + c_size;



        /* cbp values */

        CHECKED_ALLOCZ(s->coded_block_base, y_size);

        s->coded_block= s->coded_block_base + s->b8_stride + 1;



        /* cbp, ac_pred, pred_dir */

        CHECKED_ALLOCZ(s->cbp_table  , mb_array_size * sizeof(uint8_t))

        CHECKED_ALLOCZ(s->pred_dir_table, mb_array_size * sizeof(uint8_t))

    }



    if (s->h263_pred || s->h263_plus || !s->encoding) {

        /* dc values */

        //MN: we need these for error resilience of intra-frames

        CHECKED_ALLOCZ(s->dc_val_base, yc_size * sizeof(int16_t));

        s->dc_val[0] = s->dc_val_base + s->b8_stride + 1;

        s->dc_val[1] = s->dc_val_base + y_size + s->mb_stride + 1;

        s->dc_val[2] = s->dc_val[1] + c_size;

        for(i=0;i<yc_size;i++)

            s->dc_val_base[i] = 1024;

    }



    /* which mb is a intra block */

    CHECKED_ALLOCZ(s->mbintra_table, mb_array_size);

    memset(s->mbintra_table, 1, mb_array_size);



    /* init macroblock skip table */

    CHECKED_ALLOCZ(s->mbskip_table, mb_array_size+2);

    //Note the +1 is for a quicker mpeg4 slice_end detection

    CHECKED_ALLOCZ(s->prev_pict_types, PREV_PICT_TYPES_BUFFER_SIZE);



    s->parse_context.state= -1;

    if((s->avctx->debug&(FF_DEBUG_VIS_QP|FF_DEBUG_VIS_MB_TYPE)) || (s->avctx->debug_mv)){

       s->visualization_buffer[0] = av_malloc((s->mb_width*16 + 2*EDGE_WIDTH) * s->mb_height*16 + 2*EDGE_WIDTH);

       s->visualization_buffer[1] = av_malloc((s->mb_width*8 + EDGE_WIDTH) * s->mb_height*8 + EDGE_WIDTH);

       s->visualization_buffer[2] = av_malloc((s->mb_width*8 + EDGE_WIDTH) * s->mb_height*8 + EDGE_WIDTH);

    }



    s->context_initialized = 1;



    s->thread_context[0]= s;

    /* h264 does thread context setup itself, but it needs context[0]

     * to be fully initialized for the error resilience code */

    threads = s->codec_id == CODEC_ID_H264 ? 1 : s->avctx->thread_count;



    for(i=1; i<threads; i++){

        s->thread_context[i]= av_malloc(sizeof(MpegEncContext));

        memcpy(s->thread_context[i], s, sizeof(MpegEncContext));

    }



    for(i=0; i<threads; i++){

        if(init_duplicate_context(s->thread_context[i], s) < 0)

           goto fail;

        s->thread_context[i]->start_mb_y= (s->mb_height*(i  ) + s->avctx->thread_count/2) / s->avctx->thread_count;

        s->thread_context[i]->end_mb_y  = (s->mb_height*(i+1) + s->avctx->thread_count/2) / s->avctx->thread_count;

    }



    return 0;

 fail:

    MPV_common_end(s);

    return -1;

}

static int get_audio_flags(AVCodecContext *enc){

    int flags = (enc->bits_per_coded_sample == 16) ? FLV_SAMPLESSIZE_16BIT : FLV_SAMPLESSIZE_8BIT;



    if (enc->codec_id == CODEC_ID_AAC) // specs force these parameters

        return FLV_CODECID_AAC | FLV_SAMPLERATE_44100HZ | FLV_SAMPLESSIZE_16BIT | FLV_STEREO;

    else if (enc->codec_id == CODEC_ID_SPEEX) {

        if (enc->sample_rate != 16000) {

            av_log(enc, AV_LOG_ERROR, "flv only supports wideband (16kHz) Speex audio\n");

            return -1;

        }

        if (enc->channels != 1) {

            av_log(enc, AV_LOG_ERROR, "flv only supports mono Speex audio\n");

            return -1;

        }

        if (enc->frame_size / 320 > 8) {

            av_log(enc, AV_LOG_WARNING, "Warning: Speex stream has more than "

                                        "8 frames per packet. Adobe Flash "

                                        "Player cannot handle this!\n");

        }

        return FLV_CODECID_SPEEX | FLV_SAMPLERATE_11025HZ | FLV_SAMPLESSIZE_16BIT;

    } else {

    switch (enc->sample_rate) {

        case    44100:

            flags |= FLV_SAMPLERATE_44100HZ;

            break;

        case    22050:

            flags |= FLV_SAMPLERATE_22050HZ;

            break;

        case    11025:

            flags |= FLV_SAMPLERATE_11025HZ;

            break;

        case     8000: //nellymoser only

        case     5512: //not mp3

            if(enc->codec_id != CODEC_ID_MP3){

                flags |= FLV_SAMPLERATE_SPECIAL;

                break;

            }

        default:

            av_log(enc, AV_LOG_ERROR, "flv does not support that sample rate, choose from (44100, 22050, 11025).\n");

            return -1;

    }

    }



    if (enc->channels > 1) {

        flags |= FLV_STEREO;

    }



    switch(enc->codec_id){

    case CODEC_ID_MP3:

        flags |= FLV_CODECID_MP3    | FLV_SAMPLESSIZE_16BIT;

        break;

    case CODEC_ID_PCM_U8:

        flags |= FLV_CODECID_PCM    | FLV_SAMPLESSIZE_8BIT;

        break;

    case CODEC_ID_PCM_S16BE:

        flags |= FLV_CODECID_PCM    | FLV_SAMPLESSIZE_16BIT;

        break;

    case CODEC_ID_PCM_S16LE:

        flags |= FLV_CODECID_PCM_LE | FLV_SAMPLESSIZE_16BIT;

        break;

    case CODEC_ID_ADPCM_SWF:

        flags |= FLV_CODECID_ADPCM | FLV_SAMPLESSIZE_16BIT;

        break;

    case CODEC_ID_NELLYMOSER:

        if (enc->sample_rate == 8000) {

            flags |= FLV_CODECID_NELLYMOSER_8KHZ_MONO | FLV_SAMPLESSIZE_16BIT;

        } else {

            flags |= FLV_CODECID_NELLYMOSER | FLV_SAMPLESSIZE_16BIT;

        }

        break;

    case 0:

        flags |= enc->codec_tag<<4;

        break;

    default:

        av_log(enc, AV_LOG_ERROR, "codec not compatible with flv\n");

        return -1;

    }



    return flags;

}

int ff_h264_decode_sei(H264Context *h)

{

    while (get_bits_left(&h->gb) > 16) {

        int size = 0;

        int type = 0;

        int ret  = 0;

        int last = 0;



        while (get_bits_left(&h->gb) >= 8 &&

               (last = get_bits(&h->gb, 8)) == 255) {

            type += 255;

        }

        type += last;



        last = 0;

        while (get_bits_left(&h->gb) >= 8 &&

               (last = get_bits(&h->gb, 8)) == 255) {

            size += 255;

        }

        size += last;



        if (size > get_bits_left(&h->gb) / 8) {

            av_log(h->avctx, AV_LOG_ERROR, "SEI type %d truncated at %d\n",

                   type, get_bits_left(&h->gb));

            return AVERROR_INVALIDDATA;

        }



        switch (type) {

        case SEI_TYPE_PIC_TIMING: // Picture timing SEI

            ret = decode_picture_timing(h);

            if (ret < 0)

                return ret;

            break;

        case SEI_TYPE_USER_DATA_UNREGISTERED:

            ret = decode_unregistered_user_data(h, size);

            if (ret < 0)

                return ret;

            break;

        case SEI_TYPE_RECOVERY_POINT:

            ret = decode_recovery_point(h);

            if (ret < 0)

                return ret;

            break;

        case SEI_TYPE_BUFFERING_PERIOD:

            ret = decode_buffering_period(h);

            if (ret < 0)

                return ret;

            break;

        case SEI_TYPE_FRAME_PACKING:

            ret = decode_frame_packing_arrangement(h);

            if (ret < 0)

                return ret;

            break;

        case SEI_TYPE_DISPLAY_ORIENTATION:

            ret = decode_display_orientation(h);

            if (ret < 0)

                return ret;

            break;

        default:

            av_log(h->avctx, AV_LOG_DEBUG, "unknown SEI type %d\n", type);

            skip_bits(&h->gb, 8 * size);

        }



        // FIXME check bits here

        align_get_bits(&h->gb);

    }



    return 0;

}

static int dvbsub_display_end_segment(AVCodecContext *avctx, const uint8_t *buf,

                                        int buf_size, AVSubtitle *sub)

{

    DVBSubContext *ctx = avctx->priv_data;

    DVBSubDisplayDefinition *display_def = ctx->display_definition;



    DVBSubRegion *region;

    DVBSubRegionDisplay *display;

    AVSubtitleRect *rect;

    DVBSubCLUT *clut;

    uint32_t *clut_table;

    int i;

    int offset_x=0, offset_y=0;



    sub->rects = NULL;

    sub->start_display_time = 0;

    sub->end_display_time = ctx->time_out * 1000;

    sub->format = 0;



    if (display_def) {

        offset_x = display_def->x;

        offset_y = display_def->y;

    }



    sub->num_rects = ctx->display_list_size;

    if (sub->num_rects <= 0)

        return AVERROR_INVALIDDATA;



    sub->rects = av_mallocz_array(sub->num_rects * sub->num_rects,

                                  sizeof(*sub->rects));

    if (!sub->rects)

        return AVERROR(ENOMEM);



    i = 0;



    for (display = ctx->display_list; display; display = display->next) {

        region = get_region(ctx, display->region_id);

        rect = sub->rects[i];



        if (!region)

            continue;



        rect->x = display->x_pos + offset_x;

        rect->y = display->y_pos + offset_y;

        rect->w = region->width;

        rect->h = region->height;

        rect->nb_colors = 16;

        rect->type      = SUBTITLE_BITMAP;

        rect->pict.linesize[0] = region->width;



        clut = get_clut(ctx, region->clut);



        if (!clut)

            clut = &default_clut;



        switch (region->depth) {

        case 2:

            clut_table = clut->clut4;

            break;

        case 8:

            clut_table = clut->clut256;

            break;

        case 4:

        default:

            clut_table = clut->clut16;

            break;

        }



        rect->pict.data[1] = av_mallocz(AVPALETTE_SIZE);

        if (!rect->pict.data[1]) {

            av_free(sub->rects);

            return AVERROR(ENOMEM);

        }

        memcpy(rect->pict.data[1], clut_table, (1 << region->depth) * sizeof(uint32_t));



        rect->pict.data[0] = av_malloc(region->buf_size);

        if (!rect->pict.data[0]) {

            av_free(rect->pict.data[1]);

            av_free(sub->rects);

            return AVERROR(ENOMEM);

        }

        memcpy(rect->pict.data[0], region->pbuf, region->buf_size);



        i++;

    }



    sub->num_rects = i;



#ifdef DEBUG

    save_display_set(ctx);

#endif



    return 1;

}

