static void count_frame_bits(AC3EncodeContext *s)

{

    AC3EncOptions *opt = &s->options;

    int blk, ch;

    int frame_bits = 0;



    /* header */

    if (s->eac3) {

        /* coupling */

        if (s->channel_mode > AC3_CHMODE_MONO) {

            frame_bits++;

            for (blk = 1; blk < AC3_MAX_BLOCKS; blk++) {

                AC3Block *block = &s->blocks[blk];

                frame_bits++;

                if (block->new_cpl_strategy)

                    frame_bits++;

            }

        }

        /* coupling exponent strategy */

        for (blk = 0; blk < AC3_MAX_BLOCKS; blk++)

            frame_bits += 2 * s->blocks[blk].cpl_in_use;

    } else {

        if (opt->audio_production_info)

            frame_bits += 7;

        if (s->bitstream_id == 6) {

            if (opt->extended_bsi_1)

                frame_bits += 14;

            if (opt->extended_bsi_2)

                frame_bits += 14;

        }

    }



    /* audio blocks */

    for (blk = 0; blk < AC3_MAX_BLOCKS; blk++) {

        AC3Block *block = &s->blocks[blk];



        /* coupling strategy */

        if (!s->eac3)

            frame_bits++;

        if (block->new_cpl_strategy) {

            if (!s->eac3)

                frame_bits++;

            if (block->cpl_in_use) {

                if (s->eac3)

                    frame_bits++;

                if (!s->eac3 || s->channel_mode != AC3_CHMODE_STEREO)

                    frame_bits += s->fbw_channels;

                if (s->channel_mode == AC3_CHMODE_STEREO)

                    frame_bits++;

                frame_bits += 4 + 4;

                if (s->eac3)

                    frame_bits++;

                else

                    frame_bits += s->num_cpl_subbands - 1;

            }

        }



        /* coupling coordinates */

        if (block->cpl_in_use) {

            for (ch = 1; ch <= s->fbw_channels; ch++) {

                if (block->channel_in_cpl[ch]) {

                    if (!s->eac3 || block->new_cpl_coords != 2)

                        frame_bits++;

                    if (block->new_cpl_coords) {

                        frame_bits += 2;

                        frame_bits += (4 + 4) * s->num_cpl_bands;

                    }

                }

            }

        }



        /* stereo rematrixing */

        if (s->channel_mode == AC3_CHMODE_STEREO) {

            if (!s->eac3 || blk > 0)

                frame_bits++;

            if (s->blocks[blk].new_rematrixing_strategy)

                frame_bits += block->num_rematrixing_bands;

        }



        /* bandwidth codes & gain range */

        for (ch = 1; ch <= s->fbw_channels; ch++) {

            if (s->exp_strategy[ch][blk] != EXP_REUSE) {

                if (!block->channel_in_cpl[ch])

                    frame_bits += 6;

                frame_bits += 2;

            }

        }



        /* coupling exponent strategy */

        if (!s->eac3 && block->cpl_in_use)

            frame_bits += 2;



        /* snr offsets and fast gain codes */

        if (!s->eac3) {

            frame_bits++;

            if (block->new_snr_offsets)

                frame_bits += 6 + (s->channels + block->cpl_in_use) * (4 + 3);

        }



        /* coupling leak info */

        if (block->cpl_in_use) {

            if (!s->eac3 || block->new_cpl_leak != 2)

                frame_bits++;

            if (block->new_cpl_leak)

                frame_bits += 3 + 3;

        }

    }



    s->frame_bits = s->frame_bits_fixed + frame_bits;

}

static int qemu_rdma_drain_cq(QEMUFile *f, RDMAContext *rdma)

{

    int ret;



    if (qemu_rdma_write_flush(f, rdma) < 0) {

        return -EIO;

    }



    while (rdma->nb_sent) {

        ret = qemu_rdma_block_for_wrid(rdma, RDMA_WRID_RDMA_WRITE, NULL);

        if (ret < 0) {

            fprintf(stderr, "rdma migration: complete polling error!\n");

            return -EIO;

        }

    }



    qemu_rdma_unregister_waiting(rdma);



    return 0;

}

