int acpi_pcihp_device_hotplug(AcpiPciHpState *s, PCIDevice *dev,

                              PCIHotplugState state)

{

    int slot = PCI_SLOT(dev->devfn);

    int bsel = acpi_pcihp_get_bsel(dev->bus);

    if (bsel < 0) {

        return -1;

    }



    /* Don't send event when device is enabled during qemu machine creation:

     * it is present on boot, no hotplug event is necessary. We do send an

     * event when the device is disabled later. */

    if (state == PCI_COLDPLUG_ENABLED) {

        s->acpi_pcihp_pci_status[bsel].device_present |= (1U << slot);

        return 0;

    }



    if (state == PCI_HOTPLUG_ENABLED) {

        enable_device(s, bsel, slot);

    } else {

        disable_device(s, bsel, slot);

    }



    return 0;

}

static void mxf_write_cdci_common(AVFormatContext *s, AVStream *st, const UID key, unsigned size)

{

    MXFStreamContext *sc = st->priv_data;

    AVIOContext *pb = s->pb;

    int stored_height = (st->codec->height+15)/16*16;

    int display_height;

    int f1, f2;

    unsigned desc_size = size+8+8+8+8+8+8+5+16+sc->interlaced*4+12+20;

    if (sc->interlaced && sc->field_dominance)

        desc_size += 5;



    mxf_write_generic_desc(s, st, key, desc_size);



    mxf_write_local_tag(pb, 4, 0x3203);

    avio_wb32(pb, st->codec->width);



    mxf_write_local_tag(pb, 4, 0x3202);

    avio_wb32(pb, stored_height>>sc->interlaced);



    mxf_write_local_tag(pb, 4, 0x3209);

    avio_wb32(pb, st->codec->width);



    if (st->codec->height == 608) // PAL + VBI

        display_height = 576;

    else if (st->codec->height == 512)  // NTSC + VBI

        display_height = 486;

    else

        display_height = st->codec->height;



    mxf_write_local_tag(pb, 4, 0x3208);

    avio_wb32(pb, display_height>>sc->interlaced);



    // component depth

    mxf_write_local_tag(pb, 4, 0x3301);

    avio_wb32(pb, sc->component_depth);



    // horizontal subsampling

    mxf_write_local_tag(pb, 4, 0x3302);

    avio_wb32(pb, 2);



    // frame layout

    mxf_write_local_tag(pb, 1, 0x320C);

    avio_w8(pb, sc->interlaced);



    // video line map

    switch (st->codec->height) {

    case  576: f1 = 23; f2 = st->codec->codec_id == AV_CODEC_ID_DVVIDEO ? 335 : 336; break;

    case  608: f1 =  7; f2 = 320; break;

    case  480: f1 = 20; f2 = st->codec->codec_id == AV_CODEC_ID_DVVIDEO ? 285 : 283; break;

    case  512: f1 =  7; f2 = 270; break;

    case  720: f1 = 26; f2 =   0; break; // progressive

    case 1080: f1 = 21; f2 = 584; break;

    default:   f1 =  0; f2 =   0; break;

    }



    if (!sc->interlaced) {

        f2  = 0;

        f1 *= 2;

    }



    mxf_write_local_tag(pb, 12+sc->interlaced*4, 0x320D);

    avio_wb32(pb, sc->interlaced ? 2 : 1);

    avio_wb32(pb, 4);

    avio_wb32(pb, f1);

    if (sc->interlaced)

        avio_wb32(pb, f2);



    mxf_write_local_tag(pb, 8, 0x320E);

    avio_wb32(pb, sc->aspect_ratio.num);

    avio_wb32(pb, sc->aspect_ratio.den);



    mxf_write_local_tag(pb, 16, 0x3201);

    avio_write(pb, *sc->codec_ul, 16);



    if (sc->interlaced && sc->field_dominance) {

        mxf_write_local_tag(pb, 1, 0x3212);

        avio_w8(pb, sc->field_dominance);

    }



}

static int coroutine_fn cow_co_is_allocated(BlockDriverState *bs,

        int64_t sector_num, int nb_sectors, int *num_same)

{

    int64_t bitnum = sector_num + sizeof(struct cow_header_v2) * 8;

    uint64_t offset = (bitnum / 8) & -BDRV_SECTOR_SIZE;

    bool first = true;

    int changed = 0, same = 0;



    do {

        int ret;

        uint8_t bitmap[BDRV_SECTOR_SIZE];



        bitnum &= BITS_PER_BITMAP_SECTOR - 1;

        int sector_bits = MIN(nb_sectors, BITS_PER_BITMAP_SECTOR - bitnum);



        ret = bdrv_pread(bs->file, offset, &bitmap, sizeof(bitmap));

        if (ret < 0) {

            return ret;

        }



        if (first) {

            changed = cow_test_bit(bitnum, bitmap);

            first = false;

        }



        same += cow_find_streak(bitmap, changed, bitnum, nb_sectors);



        bitnum += sector_bits;

        nb_sectors -= sector_bits;

        offset += BDRV_SECTOR_SIZE;

    } while (nb_sectors);



    *num_same = same;

    return changed;

}

static inline void idct4col_put(uint8_t *dest, int line_size, const DCTELEM *col)

{

    int c0, c1, c2, c3, a0, a1, a2, a3;

    const uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    a0 = col[8*0];

    a1 = col[8*2];

    a2 = col[8*4];

    a3 = col[8*6];

    c0 = ((a0 + a2) << (CN_SHIFT - 1)) + (1 << (C_SHIFT - 1));

    c2 = ((a0 - a2) << (CN_SHIFT - 1)) + (1 << (C_SHIFT - 1));

    c1 = a1 * C1 + a3 * C2;

    c3 = a1 * C2 - a3 * C1;

    dest[0] = cm[(c0 + c1) >> C_SHIFT];

    dest += line_size;

    dest[0] = cm[(c2 + c3) >> C_SHIFT];

    dest += line_size;

    dest[0] = cm[(c2 - c3) >> C_SHIFT];

    dest += line_size;

    dest[0] = cm[(c0 - c1) >> C_SHIFT];

}

static uint64_t pl110_read(void *opaque, hwaddr offset,

                           unsigned size)

{

    pl110_state *s = (pl110_state *)opaque;



    if (offset >= 0xfe0 && offset < 0x1000) {

        return idregs[s->version][(offset - 0xfe0) >> 2];

    }

    if (offset >= 0x200 && offset < 0x400) {

        return s->raw_palette[(offset - 0x200) >> 2];

    }

    switch (offset >> 2) {

    case 0: /* LCDTiming0 */

        return s->timing[0];

    case 1: /* LCDTiming1 */

        return s->timing[1];

    case 2: /* LCDTiming2 */

        return s->timing[2];

    case 3: /* LCDTiming3 */

        return s->timing[3];

    case 4: /* LCDUPBASE */

        return s->upbase;

    case 5: /* LCDLPBASE */

        return s->lpbase;

    case 6: /* LCDIMSC */

        if (s->version != PL110) {

            return s->cr;

        }

        return s->int_mask;

    case 7: /* LCDControl */

        if (s->version != PL110) {

            return s->int_mask;

        }

        return s->cr;

    case 8: /* LCDRIS */

        return s->int_status;

    case 9: /* LCDMIS */

        return s->int_status & s->int_mask;

    case 11: /* LCDUPCURR */

        /* TODO: Implement vertical refresh.  */

        return s->upbase;

    case 12: /* LCDLPCURR */

        return s->lpbase;

    default:

        hw_error("pl110_read: Bad offset %x\n", (int)offset);

        return 0;

    }

}

static int mp3_read_probe(AVProbeData *p)

{

    int max_frames, first_frames = 0;

    int fsize, frames, sample_rate;

    uint32_t header;

    uint8_t *buf, *buf2, *end;

    AVCodecContext avctx;



    if(id3v2_match(p->buf))

        return AVPROBE_SCORE_MAX/2+1; // this must be less than mpeg-ps because some retards put id3v2 tags before mpeg-ps files



    max_frames = 0;

    buf = p->buf;

    end = buf + p->buf_size - sizeof(uint32_t);



    for(; buf < end; buf= buf2+1) {

        buf2 = buf;



        for(frames = 0; buf2 < end; frames++) {

            header = AV_RB32(buf2);

            fsize = ff_mpa_decode_header(&avctx, header, &sample_rate);

            if(fsize < 0)

                break;

            buf2 += fsize;

        }

        max_frames = FFMAX(max_frames, frames);

        if(buf == p->buf)

            first_frames= frames;

    }

    if   (first_frames>=3) return AVPROBE_SCORE_MAX/2+1;

    else if(max_frames>500)return AVPROBE_SCORE_MAX/2;

    else if(max_frames>=3) return AVPROBE_SCORE_MAX/4;

    else if(max_frames>=1) return 1;

    else                   return 0;

}

long do_sigreturn(CPUMBState *env)

{

    struct target_signal_frame *frame;

    abi_ulong frame_addr;

    target_sigset_t target_set;

    sigset_t set;

    int i;



    frame_addr = env->regs[R_SP];

    /* Make sure the guest isn't playing games.  */

    if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 1))

        goto badframe;



    /* Restore blocked signals */

    if (__get_user(target_set.sig[0], &frame->uc.tuc_mcontext.oldmask))

        goto badframe;

    for(i = 1; i < TARGET_NSIG_WORDS; i++) {

        if (__get_user(target_set.sig[i], &frame->extramask[i - 1]))

            goto badframe;

    }

    target_to_host_sigset_internal(&set, &target_set);

    sigprocmask(SIG_SETMASK, &set, NULL);



    restore_sigcontext(&frame->uc.tuc_mcontext, env);

    /* We got here through a sigreturn syscall, our path back is via an

       rtb insn so setup r14 for that.  */

    env->regs[14] = env->sregs[SR_PC];



    unlock_user_struct(frame, frame_addr, 0);

    return env->regs[10];

  badframe:

    unlock_user_struct(frame, frame_addr, 0);

    force_sig(TARGET_SIGSEGV);

}

