QemuOptsList *qemu_opts_append(QemuOptsList *dst,

                               QemuOptsList *list)

{

    size_t num_opts, num_dst_opts;

    QemuOptDesc *desc;

    bool need_init = false;



    if (!list) {

        return dst;

    }



    /* If dst is NULL, after realloc, some area of dst should be initialized

     * before adding options to it.

     */

    if (!dst) {

        need_init = true;

    }



    num_opts = count_opts_list(dst);

    num_dst_opts = num_opts;

    num_opts += count_opts_list(list);

    dst = g_realloc(dst, sizeof(QemuOptsList) +

                    (num_opts + 1) * sizeof(QemuOptDesc));

    if (need_init) {

        dst->name = NULL;

        dst->implied_opt_name = NULL;

        QTAILQ_INIT(&dst->head);

        dst->merge_lists = false;

    }

    dst->desc[num_dst_opts].name = NULL;



    /* append list->desc to dst->desc */

    if (list) {

        desc = list->desc;

        while (desc && desc->name) {

            if (find_desc_by_name(dst->desc, desc->name) == NULL) {

                dst->desc[num_dst_opts++] = *desc;

                dst->desc[num_dst_opts].name = NULL;

            }

            desc++;

        }

    }



    return dst;

}

static void create_flash(const VirtBoardInfo *vbi)

{

    /* Create two flash devices to fill the VIRT_FLASH space in the memmap.

     * Any file passed via -bios goes in the first of these.

     */

    hwaddr flashsize = vbi->memmap[VIRT_FLASH].size / 2;

    hwaddr flashbase = vbi->memmap[VIRT_FLASH].base;

    char *nodename;



    if (bios_name) {

        char *fn;

        int image_size;



        if (drive_get(IF_PFLASH, 0, 0)) {

            error_report("The contents of the first flash device may be "

                         "specified with -bios or with -drive if=pflash... "

                         "but you cannot use both options at once");

            exit(1);

        }

        fn = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

        if (!fn) {

            error_report("Could not find ROM image '%s'", bios_name);

            exit(1);

        }

        image_size = load_image_targphys(fn, flashbase, flashsize);

        g_free(fn);

        if (image_size < 0) {

            error_report("Could not load ROM image '%s'", bios_name);

            exit(1);

        }

        g_free(fn);

    }



    create_one_flash("virt.flash0", flashbase, flashsize);

    create_one_flash("virt.flash1", flashbase + flashsize, flashsize);



    nodename = g_strdup_printf("/flash@%" PRIx64, flashbase);

    qemu_fdt_add_subnode(vbi->fdt, nodename);

    qemu_fdt_setprop_string(vbi->fdt, nodename, "compatible", "cfi-flash");

    qemu_fdt_setprop_sized_cells(vbi->fdt, nodename, "reg",

                                 2, flashbase, 2, flashsize,

                                 2, flashbase + flashsize, 2, flashsize);

    qemu_fdt_setprop_cell(vbi->fdt, nodename, "bank-width", 4);

    g_free(nodename);

}

static int field_end(H264Context *h, int in_setup)

{

    MpegEncContext *const s     = &h->s;

    AVCodecContext *const avctx = s->avctx;

    int err = 0;

    s->mb_y = 0;



    if (!in_setup && !s->droppable)

        ff_thread_report_progress(&s->current_picture_ptr->f, INT_MAX,

                                  s->picture_structure == PICT_BOTTOM_FIELD);



    if (CONFIG_H264_VDPAU_DECODER &&

        s->avctx->codec->capabilities & CODEC_CAP_HWACCEL_VDPAU)

        ff_vdpau_h264_set_reference_frames(s);



    if (in_setup || !(avctx->active_thread_type & FF_THREAD_FRAME)) {

        if (!s->droppable) {

            err = ff_h264_execute_ref_pic_marking(h, h->mmco, h->mmco_index);

            h->prev_poc_msb = h->poc_msb;

            h->prev_poc_lsb = h->poc_lsb;

        }

        h->prev_frame_num_offset = h->frame_num_offset;

        h->prev_frame_num        = h->frame_num;

        h->outputed_poc          = h->next_outputed_poc;

    }



    if (avctx->hwaccel) {

        if (avctx->hwaccel->end_frame(avctx) < 0)

            av_log(avctx, AV_LOG_ERROR,

                   "hardware accelerator failed to decode picture\n");

    }



    if (CONFIG_H264_VDPAU_DECODER &&

        s->avctx->codec->capabilities & CODEC_CAP_HWACCEL_VDPAU)

        ff_vdpau_h264_picture_complete(s);



    /*

     * FIXME: Error handling code does not seem to support interlaced

     * when slices span multiple rows

     * The ff_er_add_slice calls don't work right for bottom

     * fields; they cause massive erroneous error concealing

     * Error marking covers both fields (top and bottom).

     * This causes a mismatched s->error_count

     * and a bad error table. Further, the error count goes to

     * INT_MAX when called for bottom field, because mb_y is

     * past end by one (callers fault) and resync_mb_y != 0

     * causes problems for the first MB line, too.

     */

    if (!FIELD_PICTURE && h->current_slice)

        ff_er_frame_end(s);



    ff_MPV_frame_end(s);



    h->current_slice = 0;



    return err;

}

static uint64_t *l2_allocate(BlockDriverState *bs, int l1_index)

{

    BDRVQcowState *s = bs->opaque;

    int min_index;

    uint64_t old_l2_offset;

    uint64_t *l2_table, l2_offset;



    old_l2_offset = s->l1_table[l1_index];



    /* allocate a new l2 entry */



    l2_offset = qcow2_alloc_clusters(bs, s->l2_size * sizeof(uint64_t));

    if (l2_offset < 0) {

        return NULL;

    }



    /* update the L1 entry */



    s->l1_table[l1_index] = l2_offset | QCOW_OFLAG_COPIED;

    if (write_l1_entry(s, l1_index) < 0) {

        return NULL;

    }



    /* allocate a new entry in the l2 cache */



    min_index = l2_cache_new_entry(bs);

    l2_table = s->l2_cache + (min_index << s->l2_bits);



    if (old_l2_offset == 0) {

        /* if there was no old l2 table, clear the new table */

        memset(l2_table, 0, s->l2_size * sizeof(uint64_t));

    } else {

        /* if there was an old l2 table, read it from the disk */

        if (bdrv_pread(s->hd, old_l2_offset,

                       l2_table, s->l2_size * sizeof(uint64_t)) !=

            s->l2_size * sizeof(uint64_t))

            return NULL;

    }

    /* write the l2 table to the file */

    if (bdrv_pwrite(s->hd, l2_offset,

                    l2_table, s->l2_size * sizeof(uint64_t)) !=

        s->l2_size * sizeof(uint64_t))

        return NULL;



    /* update the l2 cache entry */



    s->l2_cache_offsets[min_index] = l2_offset;

    s->l2_cache_counts[min_index] = 1;



    return l2_table;

}

static int walk_memory_regions_1(struct walk_memory_regions_data *data,

                                 abi_ulong base, int level, void **lp)

{

    abi_ulong pa;

    int i, rc;



    if (*lp == NULL) {

        return walk_memory_regions_end(data, base, 0);

    }



    if (level == 0) {

        PageDesc *pd = *lp;



        for (i = 0; i < L2_SIZE; ++i) {

            int prot = pd[i].flags;



            pa = base | (i << TARGET_PAGE_BITS);

            if (prot != data->prot) {

                rc = walk_memory_regions_end(data, pa, prot);

                if (rc != 0) {

                    return rc;

                }

            }

        }

    } else {

        void **pp = *lp;



        for (i = 0; i < L2_SIZE; ++i) {

            pa = base | ((abi_ulong)i <<

                (TARGET_PAGE_BITS + L2_BITS * level));

            rc = walk_memory_regions_1(data, pa, level - 1, pp + i);

            if (rc != 0) {

                return rc;

            }

        }

    }



    return 0;

}

