static int gdb_get_avr_reg(CPUState *env, uint8_t *mem_buf, int n)

{

    if (n < 32) {

#ifdef WORDS_BIGENDIAN

        stq_p(mem_buf, env->avr[n].u64[0]);

        stq_p(mem_buf+8, env->avr[n].u64[1]);

#else

        stq_p(mem_buf, env->avr[n].u64[1]);

        stq_p(mem_buf+8, env->avr[n].u64[0]);

#endif

        return 16;

    }

    if (n == 33) {

        stl_p(mem_buf, env->vscr);

        return 4;

    }

    if (n == 34) {

        stl_p(mem_buf, (uint32_t)env->spr[SPR_VRSAVE]);

        return 4;

    }

    return 0;

}

static void scsi_dma_complete_noio(void *opaque, int ret)

{

    SCSIDiskReq *r = (SCSIDiskReq *)opaque;

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, r->req.dev);



    if (r->req.aiocb != NULL) {

        r->req.aiocb = NULL;

        block_acct_done(bdrv_get_stats(s->qdev.conf.bs), &r->acct);

    }

    if (r->req.io_canceled) {

        goto done;

    }



    if (ret < 0) {

        if (scsi_handle_rw_error(r, -ret)) {

            goto done;

        }

    }



    r->sector += r->sector_count;

    r->sector_count = 0;

    if (r->req.cmd.mode == SCSI_XFER_TO_DEV) {

        scsi_write_do_fua(r);

        return;

    } else {

        scsi_req_complete(&r->req, GOOD);

    }



done:

    if (!r->req.io_canceled) {

        scsi_req_unref(&r->req);

    }

}

int kvm_arch_put_registers(CPUState *cpu, int level)

{

    X86CPU *x86_cpu = X86_CPU(cpu);

    int ret;



    assert(cpu_is_stopped(cpu) || qemu_cpu_is_self(cpu));



    if (level >= KVM_PUT_RESET_STATE) {

        ret = kvm_put_msr_feature_control(x86_cpu);

        if (ret < 0) {

            return ret;

        }

    }



    if (level == KVM_PUT_FULL_STATE) {

        /* We don't check for kvm_arch_set_tsc_khz() errors here,

         * because TSC frequency mismatch shouldn't abort migration,

         * unless the user explicitly asked for a more strict TSC

         * setting (e.g. using an explicit "tsc-freq" option).

         */

        kvm_arch_set_tsc_khz(cpu);

    }



    ret = kvm_getput_regs(x86_cpu, 1);

    if (ret < 0) {

        return ret;

    }

    ret = kvm_put_xsave(x86_cpu);

    if (ret < 0) {

        return ret;

    }

    ret = kvm_put_xcrs(x86_cpu);

    if (ret < 0) {

        return ret;

    }

    ret = kvm_put_sregs(x86_cpu);

    if (ret < 0) {

        return ret;

    }

    /* must be before kvm_put_msrs */

    ret = kvm_inject_mce_oldstyle(x86_cpu);

    if (ret < 0) {

        return ret;

    }

    ret = kvm_put_msrs(x86_cpu, level);

    if (ret < 0) {

        return ret;

    }

    if (level >= KVM_PUT_RESET_STATE) {

        ret = kvm_put_mp_state(x86_cpu);

        if (ret < 0) {

            return ret;

        }

    }



    ret = kvm_put_tscdeadline_msr(x86_cpu);

    if (ret < 0) {

        return ret;

    }



    ret = kvm_put_vcpu_events(x86_cpu, level);

    if (ret < 0) {

        return ret;

    }

    ret = kvm_put_debugregs(x86_cpu);

    if (ret < 0) {

        return ret;

    }

    /* must be last */

    ret = kvm_guest_debug_workarounds(x86_cpu);

    if (ret < 0) {

        return ret;

    }

    return 0;

}

callback(void *priv_data, int index, uint8_t *buf, int buf_size, int64_t time)

{

    AVFormatContext *s = priv_data;

    struct dshow_ctx *ctx = s->priv_data;

    AVPacketList **ppktl, *pktl_next;



//    dump_videohdr(s, vdhdr);



    WaitForSingleObject(ctx->mutex, INFINITE);



    if(shall_we_drop(s))

        goto fail;



    pktl_next = av_mallocz(sizeof(AVPacketList));

    if(!pktl_next)

        goto fail;



    if(av_new_packet(&pktl_next->pkt, buf_size) < 0) {

        av_free(pktl_next);

        goto fail;

    }



    pktl_next->pkt.stream_index = index;

    pktl_next->pkt.pts = time;

    memcpy(pktl_next->pkt.data, buf, buf_size);



    for(ppktl = &ctx->pktl ; *ppktl ; ppktl = &(*ppktl)->next);

    *ppktl = pktl_next;



    ctx->curbufsize += buf_size;



    SetEvent(ctx->event);

    ReleaseMutex(ctx->mutex);



    return;

fail:

    ReleaseMutex(ctx->mutex);

    return;

}

