static int doTest(uint8_t *ref[4], int refStride[4], int w, int h,

                  enum AVPixelFormat srcFormat, enum AVPixelFormat dstFormat,

                  int srcW, int srcH, int dstW, int dstH, int flags,

                  struct Results *r)

{

    static enum AVPixelFormat cur_srcFormat;

    static int cur_srcW, cur_srcH;

    static uint8_t *src[4];

    static int srcStride[4];

    uint8_t *dst[4] = { 0 };

    uint8_t *out[4] = { 0 };

    int dstStride[4];

    int i;

    uint64_t ssdY, ssdU = 0, ssdV = 0, ssdA = 0;

    struct SwsContext *dstContext = NULL, *outContext = NULL;

    uint32_t crc = 0;

    int res      = 0;



    if (cur_srcFormat != srcFormat || cur_srcW != srcW || cur_srcH != srcH) {

        struct SwsContext *srcContext = NULL;

        int p;



        for (p = 0; p < 4; p++)

            av_freep(&src[p]);



        av_image_fill_linesizes(srcStride, srcFormat, srcW);

        for (p = 0; p < 4; p++) {

            srcStride[p] = FFALIGN(srcStride[p], 16);

            if (srcStride[p])

                src[p] = av_mallocz(srcStride[p] * srcH + 16);

            if (srcStride[p] && !src[p]) {

                perror("Malloc");

                res = -1;

                goto end;

            }

        }

        srcContext = sws_getContext(w, h, AV_PIX_FMT_YUVA420P, srcW, srcH,

                                    srcFormat, SWS_BILINEAR, NULL, NULL, NULL);

        if (!srcContext) {

            fprintf(stderr, "Failed to get %s ---> %s\n",

                    av_pix_fmt_descriptors[AV_PIX_FMT_YUVA420P].name,

                    av_pix_fmt_descriptors[srcFormat].name);

            res = -1;

            goto end;

        }

        sws_scale(srcContext, ref, refStride, 0, h, src, srcStride);

        sws_freeContext(srcContext);



        cur_srcFormat = srcFormat;

        cur_srcW      = srcW;

        cur_srcH      = srcH;

    }



    av_image_fill_linesizes(dstStride, dstFormat, dstW);

    for (i = 0; i < 4; i++) {

        /* Image buffers passed into libswscale can be allocated any way you

         * prefer, as long as they're aligned enough for the architecture, and

         * they're freed appropriately (such as using av_free for buffers

         * allocated with av_malloc). */

        /* An extra 16 bytes is being allocated because some scalers may write

         * out of bounds. */

        dstStride[i] = FFALIGN(dstStride[i], 16);

        if (dstStride[i])

            dst[i] = av_mallocz(dstStride[i] * dstH + 16);

        if (dstStride[i] && !dst[i]) {

            perror("Malloc");

            res = -1;



            goto end;

        }

    }



    dstContext = sws_getContext(srcW, srcH, srcFormat, dstW, dstH, dstFormat,

                                flags, NULL, NULL, NULL);

    if (!dstContext) {

        fprintf(stderr, "Failed to get %s ---> %s\n",

                av_pix_fmt_descriptors[srcFormat].name,

                av_pix_fmt_descriptors[dstFormat].name);

        res = -1;

        goto end;

    }



    printf(" %s %dx%d -> %s %3dx%3d flags=%2d",

           av_pix_fmt_descriptors[srcFormat].name, srcW, srcH,

           av_pix_fmt_descriptors[dstFormat].name, dstW, dstH,

           flags);

    fflush(stdout);



    sws_scale(dstContext, src, srcStride, 0, srcH, dst, dstStride);



    for (i = 0; i < 4 && dstStride[i]; i++)

        crc = av_crc(av_crc_get_table(AV_CRC_32_IEEE), crc, dst[i],

                     dstStride[i] * dstH);



    if (r && crc == r->crc) {

        ssdY = r->ssdY;

        ssdU = r->ssdU;

        ssdV = r->ssdV;

        ssdA = r->ssdA;

    } else {

        for (i = 0; i < 4; i++) {

            refStride[i] = FFALIGN(refStride[i], 16);

            if (refStride[i])

                out[i] = av_mallocz(refStride[i] * h);

            if (refStride[i] && !out[i]) {

                perror("Malloc");

                res = -1;

                goto end;

            }

        }

        outContext = sws_getContext(dstW, dstH, dstFormat, w, h,

                                    AV_PIX_FMT_YUVA420P, SWS_BILINEAR,

                                    NULL, NULL, NULL);

        if (!outContext) {

            fprintf(stderr, "Failed to get %s ---> %s\n",

                    av_pix_fmt_descriptors[dstFormat].name,

                    av_pix_fmt_descriptors[AV_PIX_FMT_YUVA420P].name);

            res = -1;

            goto end;

        }

        sws_scale(outContext, dst, dstStride, 0, dstH, out, refStride);



        ssdY = getSSD(ref[0], out[0], refStride[0], refStride[0], w, h);

        if (hasChroma(srcFormat) && hasChroma(dstFormat)) {

            //FIXME check that output is really gray

            ssdU = getSSD(ref[1], out[1], refStride[1], refStride[1],

                          (w + 1) >> 1, (h + 1) >> 1);

            ssdV = getSSD(ref[2], out[2], refStride[2], refStride[2],

                          (w + 1) >> 1, (h + 1) >> 1);

        }

        if (isALPHA(srcFormat) && isALPHA(dstFormat))

            ssdA = getSSD(ref[3], out[3], refStride[3], refStride[3], w, h);



        ssdY /= w * h;

        ssdU /= w * h / 4;

        ssdV /= w * h / 4;

        ssdA /= w * h;



        sws_freeContext(outContext);



        for (i = 0; i < 4; i++)

            if (refStride[i])

                av_free(out[i]);

    }



    printf(" CRC=%08x SSD=%5"PRId64 ",%5"PRId64 ",%5"PRId64 ",%5"PRId64 "\n",

           crc, ssdY, ssdU, ssdV, ssdA);



end:

    sws_freeContext(dstContext);



    for (i = 0; i < 4; i++)

        if (dstStride[i])

            av_free(dst[i]);



    return res;

}

qemu_irq *pxa2xx_pic_init(target_phys_addr_t base, CPUState *env)

{

    PXA2xxPICState *s;

    int iomemtype;

    qemu_irq *qi;



    s = (PXA2xxPICState *)

            qemu_mallocz(sizeof(PXA2xxPICState));

    if (!s)

        return NULL;



    s->cpu_env = env;



    s->int_pending[0] = 0;

    s->int_pending[1] = 0;

    s->int_enabled[0] = 0;

    s->int_enabled[1] = 0;

    s->is_fiq[0] = 0;

    s->is_fiq[1] = 0;



    qi = qemu_allocate_irqs(pxa2xx_pic_set_irq, s, PXA2XX_PIC_SRCS);



    /* Enable IC memory-mapped registers access.  */

    iomemtype = cpu_register_io_memory(pxa2xx_pic_readfn,

                    pxa2xx_pic_writefn, s, DEVICE_NATIVE_ENDIAN);

    cpu_register_physical_memory(base, 0x00100000, iomemtype);



    /* Enable IC coprocessor access.  */

    cpu_arm_set_cp_io(env, 6, pxa2xx_pic_cp_read, pxa2xx_pic_cp_write, s);



    register_savevm(NULL, "pxa2xx_pic", 0, 0, pxa2xx_pic_save,

                    pxa2xx_pic_load, s);



    return qi;

}

