static float128 addFloat128Sigs( float128 a, float128 b, flag zSign STATUS_PARAM)

{

    int32 aExp, bExp, zExp;

    uint64_t aSig0, aSig1, bSig0, bSig1, zSig0, zSig1, zSig2;

    int32 expDiff;



    aSig1 = extractFloat128Frac1( a );

    aSig0 = extractFloat128Frac0( a );

    aExp = extractFloat128Exp( a );

    bSig1 = extractFloat128Frac1( b );

    bSig0 = extractFloat128Frac0( b );

    bExp = extractFloat128Exp( b );

    expDiff = aExp - bExp;

    if ( 0 < expDiff ) {

        if ( aExp == 0x7FFF ) {

            if ( aSig0 | aSig1 ) return propagateFloat128NaN( a, b STATUS_VAR );

            return a;

        }

        if ( bExp == 0 ) {

            --expDiff;

        }

        else {

            bSig0 |= LIT64( 0x0001000000000000 );

        }

        shift128ExtraRightJamming(

            bSig0, bSig1, 0, expDiff, &bSig0, &bSig1, &zSig2 );

        zExp = aExp;

    }

    else if ( expDiff < 0 ) {

        if ( bExp == 0x7FFF ) {

            if ( bSig0 | bSig1 ) return propagateFloat128NaN( a, b STATUS_VAR );

            return packFloat128( zSign, 0x7FFF, 0, 0 );

        }

        if ( aExp == 0 ) {

            ++expDiff;

        }

        else {

            aSig0 |= LIT64( 0x0001000000000000 );

        }

        shift128ExtraRightJamming(

            aSig0, aSig1, 0, - expDiff, &aSig0, &aSig1, &zSig2 );

        zExp = bExp;

    }

    else {

        if ( aExp == 0x7FFF ) {

            if ( aSig0 | aSig1 | bSig0 | bSig1 ) {

                return propagateFloat128NaN( a, b STATUS_VAR );

            }

            return a;

        }

        add128( aSig0, aSig1, bSig0, bSig1, &zSig0, &zSig1 );

        if ( aExp == 0 ) {

            if ( STATUS(flush_to_zero) ) return packFloat128( zSign, 0, 0, 0 );

            return packFloat128( zSign, 0, zSig0, zSig1 );

        }

        zSig2 = 0;

        zSig0 |= LIT64( 0x0002000000000000 );

        zExp = aExp;

        goto shiftRight1;

    }

    aSig0 |= LIT64( 0x0001000000000000 );

    add128( aSig0, aSig1, bSig0, bSig1, &zSig0, &zSig1 );

    --zExp;

    if ( zSig0 < LIT64( 0x0002000000000000 ) ) goto roundAndPack;

    ++zExp;

 shiftRight1:

    shift128ExtraRightJamming(

        zSig0, zSig1, zSig2, 1, &zSig0, &zSig1, &zSig2 );

 roundAndPack:

    return roundAndPackFloat128( zSign, zExp, zSig0, zSig1, zSig2 STATUS_VAR );



}

static void serial_update_parameters(SerialState *s)

{

    int speed, parity, data_bits, stop_bits, frame_size;

    QEMUSerialSetParams ssp;



    if (s->divider == 0)

        return;



    /* Start bit. */

    frame_size = 1;

    if (s->lcr & 0x08) {

        /* Parity bit. */

        frame_size++;

        if (s->lcr & 0x10)

            parity = 'E';

        else

            parity = 'O';

    } else {

            parity = 'N';

    }

    if (s->lcr & 0x04)

        stop_bits = 2;

    else

        stop_bits = 1;



    data_bits = (s->lcr & 0x03) + 5;

    frame_size += data_bits + stop_bits;

    speed = s->baudbase / s->divider;

    ssp.speed = speed;

    ssp.parity = parity;

    ssp.data_bits = data_bits;

    ssp.stop_bits = stop_bits;

    s->char_transmit_time =  (NANOSECONDS_PER_SECOND / speed) * frame_size;

    qemu_chr_fe_ioctl(s->chr, CHR_IOCTL_SERIAL_SET_PARAMS, &ssp);



    DPRINTF("speed=%d parity=%c data=%d stop=%d\n",

           speed, parity, data_bits, stop_bits);

}

static void *do_data_compress(void *opaque)

{

    CompressParam *param = opaque;



    while (!quit_comp_thread) {

        qemu_mutex_lock(&param->mutex);

        /* Re-check the quit_comp_thread in case of

         * terminate_compression_threads is called just before

         * qemu_mutex_lock(&param->mutex) and after

         * while(!quit_comp_thread), re-check it here can make

         * sure the compression thread terminate as expected.

         */

        while (!param->start && !quit_comp_thread) {

            qemu_cond_wait(&param->cond, &param->mutex);

        }

        if (!quit_comp_thread) {

            do_compress_ram_page(param);

        }

        param->start = false;

        qemu_mutex_unlock(&param->mutex);



        qemu_mutex_lock(comp_done_lock);

        param->done = true;

        qemu_cond_signal(comp_done_cond);

        qemu_mutex_unlock(comp_done_lock);

    }



    return NULL;

}

static void do_transmit_packets(dp8393xState *s)

{

    uint16_t data[12];

    int width, size;

    int tx_len, len;

    uint16_t i;



    width = (s->regs[SONIC_DCR] & SONIC_DCR_DW) ? 2 : 1;



    while (1) {

        /* Read memory */

        DPRINTF("Transmit packet at %08x\n",

                (s->regs[SONIC_UTDA] << 16) | s->regs[SONIC_CTDA]);

        size = sizeof(uint16_t) * 6 * width;

        s->regs[SONIC_TTDA] = s->regs[SONIC_CTDA];

        s->memory_rw(s->mem_opaque,

            ((s->regs[SONIC_UTDA] << 16) | s->regs[SONIC_TTDA]) + sizeof(uint16_t) * width,

            (uint8_t *)data, size, 0);

        tx_len = 0;



        /* Update registers */

        s->regs[SONIC_TCR] = data[0 * width] & 0xf000;

        s->regs[SONIC_TPS] = data[1 * width];

        s->regs[SONIC_TFC] = data[2 * width];

        s->regs[SONIC_TSA0] = data[3 * width];

        s->regs[SONIC_TSA1] = data[4 * width];

        s->regs[SONIC_TFS] = data[5 * width];



        /* Handle programmable interrupt */

        if (s->regs[SONIC_TCR] & SONIC_TCR_PINT) {

            s->regs[SONIC_ISR] |= SONIC_ISR_PINT;

        } else {

            s->regs[SONIC_ISR] &= ~SONIC_ISR_PINT;

        }



        for (i = 0; i < s->regs[SONIC_TFC]; ) {

            /* Append fragment */

            len = s->regs[SONIC_TFS];

            if (tx_len + len > sizeof(s->tx_buffer)) {

                len = sizeof(s->tx_buffer) - tx_len;

            }

            s->memory_rw(s->mem_opaque,

                (s->regs[SONIC_TSA1] << 16) | s->regs[SONIC_TSA0],

                &s->tx_buffer[tx_len], len, 0);

            tx_len += len;



            i++;

            if (i != s->regs[SONIC_TFC]) {

                /* Read next fragment details */

                size = sizeof(uint16_t) * 3 * width;

                s->memory_rw(s->mem_opaque,

                    ((s->regs[SONIC_UTDA] << 16) | s->regs[SONIC_TTDA]) + sizeof(uint16_t) * (4 + 3 * i) * width,

                    (uint8_t *)data, size, 0);

                s->regs[SONIC_TSA0] = data[0 * width];

                s->regs[SONIC_TSA1] = data[1 * width];

                s->regs[SONIC_TFS] = data[2 * width];

            }

        }



        /* Handle Ethernet checksum */

        if (!(s->regs[SONIC_TCR] & SONIC_TCR_CRCI)) {

            /* Don't append FCS there, to look like slirp packets

             * which don't have one */

        } else {

            /* Remove existing FCS */

            tx_len -= 4;

        }



        if (s->regs[SONIC_RCR] & (SONIC_RCR_LB1 | SONIC_RCR_LB0)) {

            /* Loopback */

            s->regs[SONIC_TCR] |= SONIC_TCR_CRSL;

            if (s->vc->fd_can_read(s)) {

                s->loopback_packet = 1;

                s->vc->receive(s, s->tx_buffer, tx_len);

            }

        } else {

            /* Transmit packet */

            qemu_send_packet(s->vc, s->tx_buffer, tx_len);

        }

        s->regs[SONIC_TCR] |= SONIC_TCR_PTX;



        /* Write status */

        data[0 * width] = s->regs[SONIC_TCR] & 0x0fff; /* status */

        size = sizeof(uint16_t) * width;

        s->memory_rw(s->mem_opaque,

            (s->regs[SONIC_UTDA] << 16) | s->regs[SONIC_TTDA],

            (uint8_t *)data, size, 1);



        if (!(s->regs[SONIC_CR] & SONIC_CR_HTX)) {

            /* Read footer of packet */

            size = sizeof(uint16_t) * width;

            s->memory_rw(s->mem_opaque,

                ((s->regs[SONIC_UTDA] << 16) | s->regs[SONIC_TTDA]) + sizeof(uint16_t) * (4 + 3 * s->regs[SONIC_TFC]) * width,

                (uint8_t *)data, size, 0);

            s->regs[SONIC_CTDA] = data[0 * width] & ~0x1;

            if (data[0 * width] & 0x1) {

                /* EOL detected */

                break;

            }

        }

    }



    /* Done */

    s->regs[SONIC_CR] &= ~SONIC_CR_TXP;

    s->regs[SONIC_ISR] |= SONIC_ISR_TXDN;

    dp8393x_update_irq(s);

}

