static void fdt_add_timer_nodes(const VirtBoardInfo *vbi)

{

    /* Note that on A15 h/w these interrupts are level-triggered,

     * but for the GIC implementation provided by both QEMU and KVM

     * they are edge-triggered.

     */

    uint32_t irqflags = GIC_FDT_IRQ_FLAGS_EDGE_LO_HI;



    irqflags = deposit32(irqflags, GIC_FDT_IRQ_PPI_CPU_START,

                         GIC_FDT_IRQ_PPI_CPU_WIDTH, (1 << vbi->smp_cpus) - 1);



    qemu_fdt_add_subnode(vbi->fdt, "/timer");

    qemu_fdt_setprop_string(vbi->fdt, "/timer",

                                "compatible", "arm,armv7-timer");

    qemu_fdt_setprop_cells(vbi->fdt, "/timer", "interrupts",

                               GIC_FDT_IRQ_TYPE_PPI, 13, irqflags,

                               GIC_FDT_IRQ_TYPE_PPI, 14, irqflags,

                               GIC_FDT_IRQ_TYPE_PPI, 11, irqflags,

                               GIC_FDT_IRQ_TYPE_PPI, 10, irqflags);

}

void ff_slice_thread_free(AVCodecContext *avctx)

{

    ThreadContext *c = avctx->thread_opaque;

    int i;



    pthread_mutex_lock(&c->current_job_lock);

    c->done = 1;

    pthread_cond_broadcast(&c->current_job_cond);

    pthread_mutex_unlock(&c->current_job_lock);



    for (i=0; i<avctx->thread_count; i++)

         pthread_join(c->workers[i], NULL);



    pthread_mutex_destroy(&c->current_job_lock);

    pthread_cond_destroy(&c->current_job_cond);

    pthread_cond_destroy(&c->last_job_cond);

    av_free(c->workers);

    av_freep(&avctx->thread_opaque);

}

static int svq3_decode_frame (AVCodecContext *avctx,

			      void *data, int *data_size,

			      uint8_t *buf, int buf_size) {

  MpegEncContext *const s = avctx->priv_data;

  H264Context *const h = avctx->priv_data;

  int m, mb_type;

  unsigned char *extradata;

  unsigned int size;



  s->flags = avctx->flags;

  s->flags2 = avctx->flags2;

  s->unrestricted_mv = 1;



  if (!s->context_initialized) {

    s->width = avctx->width;

    s->height = avctx->height;

    h->pred4x4[DIAG_DOWN_LEFT_PRED] = pred4x4_down_left_svq3_c;

    h->pred16x16[PLANE_PRED8x8] = pred16x16_plane_svq3_c;

    h->halfpel_flag = 1;

    h->thirdpel_flag = 1;

    h->unknown_svq3_flag = 0;

    h->chroma_qp = 4;



    if (MPV_common_init (s) < 0)

      return -1;



    h->b_stride = 4*s->mb_width;



    alloc_tables (h);



    /* prowl for the "SEQH" marker in the extradata */

    extradata = (unsigned char *)avctx->extradata;

    for (m = 0; m < avctx->extradata_size; m++) {

      if (!memcmp (extradata, "SEQH", 4))

        break;

      extradata++;

    }



    /* if a match was found, parse the extra data */

    if (!memcmp (extradata, "SEQH", 4)) {



      GetBitContext gb;



      size = BE_32(&extradata[4]);

      init_get_bits (&gb, extradata + 8, size);



      /* 'frame size code' and optional 'width, height' */

      if (get_bits (&gb, 3) == 7) {

	get_bits (&gb, 12);

	get_bits (&gb, 12);

      }



      h->halfpel_flag = get_bits1 (&gb);

      h->thirdpel_flag = get_bits1 (&gb);



      /* unknown fields */

      get_bits1 (&gb);

      get_bits1 (&gb);

      get_bits1 (&gb);

      get_bits1 (&gb);



      s->low_delay = get_bits1 (&gb);



      /* unknown field */

      get_bits1 (&gb);



      while (get_bits1 (&gb)) {

	get_bits (&gb, 8);

      }



      h->unknown_svq3_flag = get_bits1 (&gb);

      avctx->has_b_frames = !s->low_delay;

    }

  }



  /* special case for last picture */

  if (buf_size == 0) {

    if (s->next_picture_ptr && !s->low_delay) {

      *(AVFrame *) data = *(AVFrame *) &s->next_picture;

      *data_size = sizeof(AVFrame);

    }

    return 0;

  }



  init_get_bits (&s->gb, buf, 8*buf_size);



  s->mb_x = s->mb_y = 0;



  if (svq3_decode_slice_header (h))

    return -1;



  s->pict_type = h->slice_type;

  s->picture_number = h->slice_num;



  if(avctx->debug&FF_DEBUG_PICT_INFO){

      av_log(h->s.avctx, AV_LOG_DEBUG, "%c hpel:%d, tpel:%d aqp:%d qp:%d\n", 

      av_get_pict_type_char(s->pict_type), h->halfpel_flag, h->thirdpel_flag,

      s->adaptive_quant, s->qscale

      );

  }



  /* for hurry_up==5 */

  s->current_picture.pict_type = s->pict_type;

  s->current_picture.key_frame = (s->pict_type == I_TYPE);



  /* skip b frames if we dont have reference frames */

  if (s->last_picture_ptr == NULL && s->pict_type == B_TYPE) return 0;

  /* skip b frames if we are in a hurry */

  if (avctx->hurry_up && s->pict_type == B_TYPE) return 0;

  /* skip everything if we are in a hurry >= 5 */

  if (avctx->hurry_up >= 5) return 0;

  if(  (avctx->skip_frame >= AVDISCARD_NONREF && s->pict_type==B_TYPE)

     ||(avctx->skip_frame >= AVDISCARD_NONKEY && s->pict_type!=I_TYPE)

     || avctx->skip_frame >= AVDISCARD_ALL)

      return 0;



  if (s->next_p_frame_damaged) {

    if (s->pict_type == B_TYPE)

      return 0;

    else

      s->next_p_frame_damaged = 0;

  }



  frame_start (h);



  if (s->pict_type == B_TYPE) {

    h->frame_num_offset = (h->slice_num - h->prev_frame_num);



    if (h->frame_num_offset < 0) {

      h->frame_num_offset += 256;

    }

    if (h->frame_num_offset == 0 || h->frame_num_offset >= h->prev_frame_num_offset) {

      av_log(h->s.avctx, AV_LOG_ERROR, "error in B-frame picture id\n");

      return -1;

    }

  } else {

    h->prev_frame_num = h->frame_num;

    h->frame_num = h->slice_num;

    h->prev_frame_num_offset = (h->frame_num - h->prev_frame_num);



    if (h->prev_frame_num_offset < 0) {

      h->prev_frame_num_offset += 256;

    }

  }



  for(m=0; m<2; m++){

    int i;

    for(i=0; i<4; i++){

      int j;

      for(j=-1; j<4; j++)

	h->ref_cache[m][scan8[0] + 8*i + j]= 1;

      h->ref_cache[m][scan8[0] + 8*i + j]= PART_NOT_AVAILABLE;

    }

  }



  for (s->mb_y=0; s->mb_y < s->mb_height; s->mb_y++) {

    for (s->mb_x=0; s->mb_x < s->mb_width; s->mb_x++) {



      if ( (get_bits_count(&s->gb) + 7) >= s->gb.size_in_bits &&

	  ((get_bits_count(&s->gb) & 7) == 0 || show_bits (&s->gb, (-get_bits_count(&s->gb) & 7)) == 0)) {



	skip_bits(&s->gb, h->next_slice_index - get_bits_count(&s->gb));

	s->gb.size_in_bits = 8*buf_size;



	if (svq3_decode_slice_header (h))

	  return -1;



	/* TODO: support s->mb_skip_run */

      }



      mb_type = svq3_get_ue_golomb (&s->gb);



      if (s->pict_type == I_TYPE) {

	mb_type += 8;

      } else if (s->pict_type == B_TYPE && mb_type >= 4) {

	mb_type += 4;

      }

      if (mb_type > 33 || svq3_decode_mb (h, mb_type)) {

	av_log(h->s.avctx, AV_LOG_ERROR, "error while decoding MB %d %d\n", s->mb_x, s->mb_y);

	return -1;

      }



      if (mb_type != 0) {

	hl_decode_mb (h);

      }



      if (s->pict_type != B_TYPE && !s->low_delay) {

	s->current_picture.mb_type[s->mb_x + s->mb_y*s->mb_stride] =

			(s->pict_type == P_TYPE && mb_type < 8) ? (mb_type - 1) : -1;

      }

    }



    ff_draw_horiz_band(s, 16*s->mb_y, 16);

  }



  MPV_frame_end(s);



  if (s->pict_type == B_TYPE || s->low_delay) {

    *(AVFrame *) data = *(AVFrame *) &s->current_picture;

  } else {

    *(AVFrame *) data = *(AVFrame *) &s->last_picture;

  }



  avctx->frame_number = s->picture_number - 1;



  /* dont output the last pic after seeking */

  if (s->last_picture_ptr || s->low_delay) {

    *data_size = sizeof(AVFrame);

  }



  return buf_size;

}

void memory_region_add_eventfd(MemoryRegion *mr,

                               hwaddr addr,

                               unsigned size,

                               bool match_data,

                               uint64_t data,

                               EventNotifier *e)

{

    MemoryRegionIoeventfd mrfd = {

        .addr.start = int128_make64(addr),

        .addr.size = int128_make64(size),

        .match_data = match_data,

        .data = data,

        .e = e,

    };

    unsigned i;



    adjust_endianness(mr, &mrfd.data, size);

    memory_region_transaction_begin();

    for (i = 0; i < mr->ioeventfd_nb; ++i) {

        if (memory_region_ioeventfd_before(mrfd, mr->ioeventfds[i])) {

            break;

        }

    }

    ++mr->ioeventfd_nb;

    mr->ioeventfds = g_realloc(mr->ioeventfds,

                                  sizeof(*mr->ioeventfds) * mr->ioeventfd_nb);

    memmove(&mr->ioeventfds[i+1], &mr->ioeventfds[i],

            sizeof(*mr->ioeventfds) * (mr->ioeventfd_nb-1 - i));

    mr->ioeventfds[i] = mrfd;

    ioeventfd_update_pending |= mr->enabled;

    memory_region_transaction_commit();

}

static int alsa_init_out (HWVoiceOut *hw, struct audsettings *as)

{

    ALSAVoiceOut *alsa = (ALSAVoiceOut *) hw;

    struct alsa_params_req req;

    struct alsa_params_obt obt;

    snd_pcm_t *handle;

    struct audsettings obt_as;



    req.fmt = aud_to_alsafmt (as->fmt, as->endianness);

    req.freq = as->freq;

    req.nchannels = as->nchannels;

    req.period_size = conf.period_size_out;

    req.buffer_size = conf.buffer_size_out;

    req.size_in_usec = conf.size_in_usec_out;

    req.override_mask =

        (conf.period_size_out_overridden ? 1 : 0) |

        (conf.buffer_size_out_overridden ? 2 : 0);



    if (alsa_open (0, &req, &obt, &handle)) {

        return -1;

    }



    obt_as.freq = obt.freq;

    obt_as.nchannels = obt.nchannels;

    obt_as.fmt = obt.fmt;

    obt_as.endianness = obt.endianness;



    audio_pcm_init_info (&hw->info, &obt_as);

    hw->samples = obt.samples;



    alsa->pcm_buf = audio_calloc (AUDIO_FUNC, obt.samples, 1 << hw->info.shift);

    if (!alsa->pcm_buf) {

        dolog ("Could not allocate DAC buffer (%d samples, each %d bytes)\n",

               hw->samples, 1 << hw->info.shift);

        alsa_anal_close1 (&handle);

        return -1;

    }



    alsa->handle = handle;

    return 0;

}

static av_cold int mdct_init(AVCodecContext *avctx, AC3MDCTContext *mdct,

                             int nbits)

{

    int i, n, n4, ret;



    n  = 1 << nbits;

    n4 = n >> 2;



    mdct->nbits = nbits;



    ret = fft_init(avctx, mdct, nbits - 2);

    if (ret)

        return ret;



    mdct->window = ff_ac3_window;



    FF_ALLOC_OR_GOTO(avctx, mdct->xcos1,    n4 * sizeof(*mdct->xcos1),    mdct_alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, mdct->xsin1,    n4 * sizeof(*mdct->xsin1),    mdct_alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, mdct->rot_tmp,  n  * sizeof(*mdct->rot_tmp),  mdct_alloc_fail);

    FF_ALLOC_OR_GOTO(avctx, mdct->cplx_tmp, n4 * sizeof(*mdct->cplx_tmp), mdct_alloc_fail);



    for (i = 0; i < n4; i++) {

        float alpha = 2.0 * M_PI * (i + 1.0 / 8.0) / n;

        mdct->xcos1[i] = FIX15(-cos(alpha));

        mdct->xsin1[i] = FIX15(-sin(alpha));

    }



    return 0;

mdct_alloc_fail:

    mdct_end(mdct);

    return AVERROR(ENOMEM);

}

static inline abi_long host_to_target_stat64(void *cpu_env,

                                             abi_ulong target_addr,

                                             struct stat *host_st)

{

#ifdef TARGET_ARM

    if (((CPUARMState *)cpu_env)->eabi) {

        struct target_eabi_stat64 *target_st;



        if (!lock_user_struct(VERIFY_WRITE, target_st, target_addr, 0))

            return -TARGET_EFAULT;

        memset(target_st, 0, sizeof(struct target_eabi_stat64));

        __put_user(host_st->st_dev, &target_st->st_dev);

        __put_user(host_st->st_ino, &target_st->st_ino);

#ifdef TARGET_STAT64_HAS_BROKEN_ST_INO

        __put_user(host_st->st_ino, &target_st->__st_ino);

#endif

        __put_user(host_st->st_mode, &target_st->st_mode);

        __put_user(host_st->st_nlink, &target_st->st_nlink);

        __put_user(host_st->st_uid, &target_st->st_uid);

        __put_user(host_st->st_gid, &target_st->st_gid);

        __put_user(host_st->st_rdev, &target_st->st_rdev);

        __put_user(host_st->st_size, &target_st->st_size);

        __put_user(host_st->st_blksize, &target_st->st_blksize);

        __put_user(host_st->st_blocks, &target_st->st_blocks);

        __put_user(host_st->st_atime, &target_st->target_st_atime);

        __put_user(host_st->st_mtime, &target_st->target_st_mtime);

        __put_user(host_st->st_ctime, &target_st->target_st_ctime);

        unlock_user_struct(target_st, target_addr, 1);

    } else

#endif

    {

#if TARGET_LONG_BITS == 64

        struct target_stat *target_st;

#else

        struct target_stat64 *target_st;

#endif



        if (!lock_user_struct(VERIFY_WRITE, target_st, target_addr, 0))

            return -TARGET_EFAULT;

        memset(target_st, 0, sizeof(*target_st));

        __put_user(host_st->st_dev, &target_st->st_dev);

        __put_user(host_st->st_ino, &target_st->st_ino);

#ifdef TARGET_STAT64_HAS_BROKEN_ST_INO

        __put_user(host_st->st_ino, &target_st->__st_ino);

#endif

        __put_user(host_st->st_mode, &target_st->st_mode);

        __put_user(host_st->st_nlink, &target_st->st_nlink);

        __put_user(host_st->st_uid, &target_st->st_uid);

        __put_user(host_st->st_gid, &target_st->st_gid);

        __put_user(host_st->st_rdev, &target_st->st_rdev);

        /* XXX: better use of kernel struct */

        __put_user(host_st->st_size, &target_st->st_size);

        __put_user(host_st->st_blksize, &target_st->st_blksize);

        __put_user(host_st->st_blocks, &target_st->st_blocks);

        __put_user(host_st->st_atime, &target_st->target_st_atime);

        __put_user(host_st->st_mtime, &target_st->target_st_mtime);

        __put_user(host_st->st_ctime, &target_st->target_st_ctime);

        unlock_user_struct(target_st, target_addr, 1);

    }



    return 0;

}

static int svq1_decode_frame_header(GetBitContext *bitbuf, MpegEncContext *s)

{

    int frame_size_code;



    skip_bits(bitbuf, 8); /* temporal_reference */



    /* frame type */

    s->pict_type = get_bits(bitbuf, 2) + 1;

    if (s->pict_type == 4)

        return AVERROR_INVALIDDATA;



    if (s->pict_type == AV_PICTURE_TYPE_I) {

        /* unknown fields */

        if (s->f_code == 0x50 || s->f_code == 0x60) {

            int csum = get_bits(bitbuf, 16);



            csum = ff_svq1_packet_checksum(bitbuf->buffer,

                                           bitbuf->size_in_bits >> 3,

                                           csum);



            av_dlog(s->avctx, "%s checksum (%02x) for packet data\n",

                    (csum == 0) ? "correct" : "incorrect", csum);

        }



        if ((s->f_code ^ 0x10) >= 0x50) {

            uint8_t msg[256];



            svq1_parse_string(bitbuf, msg);



            av_log(s->avctx, AV_LOG_ERROR,

                   "embedded message: \"%s\"\n", (char *)msg);

        }



        skip_bits(bitbuf, 2);

        skip_bits(bitbuf, 2);

        skip_bits1(bitbuf);



        /* load frame size */

        frame_size_code = get_bits(bitbuf, 3);



        if (frame_size_code == 7) {

            /* load width, height (12 bits each) */

            s->width  = get_bits(bitbuf, 12);

            s->height = get_bits(bitbuf, 12);



            if (!s->width || !s->height)

                return AVERROR_INVALIDDATA;

        } else {

            /* get width, height from table */

            s->width  = ff_svq1_frame_size_table[frame_size_code].width;

            s->height = ff_svq1_frame_size_table[frame_size_code].height;

        }

    }



    /* unknown fields */

    if (get_bits1(bitbuf) == 1) {

        skip_bits1(bitbuf);    /* use packet checksum if (1) */

        skip_bits1(bitbuf);    /* component checksums after image data if (1) */



        if (get_bits(bitbuf, 2) != 0)

            return AVERROR_INVALIDDATA;

    }



    if (get_bits1(bitbuf) == 1) {

        skip_bits1(bitbuf);

        skip_bits(bitbuf, 4);

        skip_bits1(bitbuf);

        skip_bits(bitbuf, 2);



        while (get_bits1(bitbuf) == 1)

            skip_bits(bitbuf, 8);

    }



    return 0;

}

static void gen_tlbilx_booke206(DisasContext *ctx)

{

#if defined(CONFIG_USER_ONLY)

    gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

#else

    TCGv t0;

    if (unlikely(ctx->pr)) {

        gen_inval_exception(ctx, POWERPC_EXCP_PRIV_OPC);

        return;

    }



    t0 = tcg_temp_new();

    gen_addr_reg_index(ctx, t0);



    switch((ctx->opcode >> 21) & 0x3) {

    case 0:

        gen_helper_booke206_tlbilx0(cpu_env, t0);

        break;

    case 1:

        gen_helper_booke206_tlbilx1(cpu_env, t0);

        break;

    case 3:

        gen_helper_booke206_tlbilx3(cpu_env, t0);

        break;

    default:

        gen_inval_exception(ctx, POWERPC_EXCP_INVAL_INVAL);

        break;

    }



    tcg_temp_free(t0);

#endif

}

static void mainstone_common_init(int ram_size, int vga_ram_size,

                DisplayState *ds, const char *kernel_filename,

                const char *kernel_cmdline, const char *initrd_filename,

                const char *cpu_model, enum mainstone_model_e model, int arm_id)

{

    uint32_t mainstone_ram = 0x04000000;

    uint32_t mainstone_rom = 0x00800000;

    struct pxa2xx_state_s *cpu;

    qemu_irq *mst_irq;

    int index;



    if (!cpu_model)

        cpu_model = "pxa270-c5";



    /* Setup CPU & memory */

    if (ram_size < mainstone_ram + mainstone_rom + PXA2XX_INTERNAL_SIZE) {

        fprintf(stderr, "This platform requires %i bytes of memory\n",

                        mainstone_ram + mainstone_rom + PXA2XX_INTERNAL_SIZE);

        exit(1);

    }



    cpu = pxa270_init(mainstone_ram, ds, cpu_model);

    cpu_register_physical_memory(0, mainstone_rom,

                    qemu_ram_alloc(mainstone_rom) | IO_MEM_ROM);



    /* Setup initial (reset) machine state */

    cpu->env->regs[15] = PXA2XX_SDRAM_BASE;



    /* There are two 32MiB flash devices on the board */

    index = drive_get_index(IF_PFLASH, 0, 0);

    if (index == -1) {

        fprintf(stderr, "Two flash images must be given with the "

                "'pflash' parameter\n");

        exit(1);

    }

    if (!pflash_register(MST_FLASH_0, mainstone_ram + PXA2XX_INTERNAL_SIZE,

                         drives_table[index].bdrv,

                         256 * 1024, 128, 4, 0, 0, 0, 0)) {

        fprintf(stderr, "qemu: Error registering flash memory.\n");

        exit(1);

    }



    index = drive_get_index(IF_PFLASH, 0, 1);

    if (index == -1) {

        fprintf(stderr, "Two flash images must be given with the "

                "'pflash' parameter\n");

        exit(1);

    }

    if (!pflash_register(MST_FLASH_1, mainstone_ram + PXA2XX_INTERNAL_SIZE,

                         drives_table[index].bdrv,

                         256 * 1024, 128, 4, 0, 0, 0, 0)) {

        fprintf(stderr, "qemu: Error registering flash memory.\n");

        exit(1);

    }



    mst_irq = mst_irq_init(cpu, MST_FPGA_PHYS, PXA2XX_PIC_GPIO_0);



    /* MMC/SD host */

    pxa2xx_mmci_handlers(cpu->mmc, mst_irq[MMC_IRQ], mst_irq[MMC_IRQ]);



    smc91c111_init(&nd_table[0], MST_ETH_PHYS, mst_irq[ETHERNET_IRQ]);



    arm_load_kernel(cpu->env, mainstone_ram, kernel_filename, kernel_cmdline,

                    initrd_filename, arm_id, PXA2XX_SDRAM_BASE);

}

