static av_cold int vc2_encode_init(AVCodecContext *avctx)

{

    Plane *p;

    SubBand *b;

    int i, j, level, o, shift;

    const AVPixFmtDescriptor *fmt = av_pix_fmt_desc_get(avctx->pix_fmt);

    const int depth = fmt->comp[0].depth;

    VC2EncContext *s = avctx->priv_data;



    s->picture_number = 0;



    /* Total allowed quantization range */

    s->q_ceil    = DIRAC_MAX_QUANT_INDEX;



    s->ver.major = 2;

    s->ver.minor = 0;

    s->profile   = 3;

    s->level     = 3;



    s->base_vf   = -1;

    s->strict_compliance = 1;



    s->q_avg = 0;

    s->slice_max_bytes = 0;

    s->slice_min_bytes = 0;



    /* Mark unknown as progressive */

    s->interlaced = !((avctx->field_order == AV_FIELD_UNKNOWN) ||

                      (avctx->field_order == AV_FIELD_PROGRESSIVE));



    for (i = 0; i < base_video_fmts_len; i++) {

        const VC2BaseVideoFormat *fmt = &base_video_fmts[i];

        if (avctx->pix_fmt != fmt->pix_fmt)

            continue;

        if (avctx->time_base.num != fmt->time_base.num)

            continue;

        if (avctx->time_base.den != fmt->time_base.den)

            continue;

        if (avctx->width != fmt->width)

            continue;

        if (avctx->height != fmt->height)

            continue;

        if (s->interlaced != fmt->interlaced)

            continue;

        s->base_vf = i;

        s->level   = base_video_fmts[i].level;

        break;

    }



    if (s->interlaced)

        av_log(avctx, AV_LOG_WARNING, "Interlacing enabled!\n");



    if ((s->slice_width  & (s->slice_width  - 1)) ||

        (s->slice_height & (s->slice_height - 1))) {

        av_log(avctx, AV_LOG_ERROR, "Slice size is not a power of two!\n");

        return AVERROR_UNKNOWN;

    }



    if ((s->slice_width > avctx->width) ||

        (s->slice_height > avctx->height)) {

        av_log(avctx, AV_LOG_ERROR, "Slice size is bigger than the image!\n");

        return AVERROR_UNKNOWN;

    }



    if (s->base_vf <= 0) {

        if (avctx->strict_std_compliance <= FF_COMPLIANCE_UNOFFICIAL) {

            s->strict_compliance = s->base_vf = 0;

            av_log(avctx, AV_LOG_WARNING, "Disabling strict compliance\n");

        } else {

            av_log(avctx, AV_LOG_WARNING, "Given format does not strictly comply with "

                   "the specifications, please add a -strict -1 flag to use it\n");

            return AVERROR_UNKNOWN;

        }

    } else {

        av_log(avctx, AV_LOG_INFO, "Selected base video format = %i (%s)\n",

               s->base_vf, base_video_fmts[s->base_vf].name);

    }



    /* Chroma subsampling */

    avcodec_get_chroma_sub_sample(avctx->pix_fmt, &s->chroma_x_shift, &s->chroma_y_shift);



    /* Bit depth and color range index */

    if (depth == 8 && avctx->color_range == AVCOL_RANGE_JPEG) {

        s->bpp = 1;

        s->bpp_idx = 1;

        s->diff_offset = 128;

    } else if (depth == 8 && (avctx->color_range == AVCOL_RANGE_MPEG ||

               avctx->color_range == AVCOL_RANGE_UNSPECIFIED)) {

        s->bpp = 1;

        s->bpp_idx = 2;

        s->diff_offset = 128;

    } else if (depth == 10) {

        s->bpp = 2;

        s->bpp_idx = 3;

        s->diff_offset = 512;

    } else {

        s->bpp = 2;

        s->bpp_idx = 4;

        s->diff_offset = 2048;

    }



    /* Planes initialization */

    for (i = 0; i < 3; i++) {

        int w, h;

        p = &s->plane[i];

        p->width      = avctx->width  >> (i ? s->chroma_x_shift : 0);

        p->height     = avctx->height >> (i ? s->chroma_y_shift : 0);

        if (s->interlaced)

            p->height >>= 1;

        p->dwt_width  = w = FFALIGN(p->width,  (1 << s->wavelet_depth));

        p->dwt_height = h = FFALIGN(p->height, (1 << s->wavelet_depth));

        p->coef_stride = FFALIGN(p->dwt_width, 32);

        p->coef_buf = av_malloc(p->coef_stride*p->dwt_height*sizeof(dwtcoef));

        if (!p->coef_buf)

            goto alloc_fail;

        for (level = s->wavelet_depth-1; level >= 0; level--) {

            w = w >> 1;

            h = h >> 1;

            for (o = 0; o < 4; o++) {

                b = &p->band[level][o];

                b->width  = w;

                b->height = h;

                b->stride = p->coef_stride;

                shift = (o > 1)*b->height*b->stride + (o & 1)*b->width;

                b->buf = p->coef_buf + shift;

            }

        }



        /* DWT init */

        if (ff_vc2enc_init_transforms(&s->transform_args[i].t,

                                      s->plane[i].coef_stride,

                                      s->plane[i].dwt_height))

            goto alloc_fail;

    }



    /* Slices */

    s->num_x = s->plane[0].dwt_width/s->slice_width;

    s->num_y = s->plane[0].dwt_height/s->slice_height;



    s->slice_args = av_calloc(s->num_x*s->num_y, sizeof(SliceArgs));

    if (!s->slice_args)

        goto alloc_fail;



    /* Lookup tables */

    s->coef_lut_len = av_malloc(COEF_LUT_TAB*(s->q_ceil+1)*sizeof(*s->coef_lut_len));

    if (!s->coef_lut_len)

        goto alloc_fail;



    s->coef_lut_val = av_malloc(COEF_LUT_TAB*(s->q_ceil+1)*sizeof(*s->coef_lut_val));

    if (!s->coef_lut_val)

        goto alloc_fail;



    for (i = 0; i < s->q_ceil; i++) {

        uint8_t  *len_lut = &s->coef_lut_len[i*COEF_LUT_TAB];

        uint32_t *val_lut = &s->coef_lut_val[i*COEF_LUT_TAB];

        for (j = 0; j < COEF_LUT_TAB; j++) {

            get_vc2_ue_uint(QUANT(j, ff_dirac_qscale_tab[i]),

                            &len_lut[j], &val_lut[j]);

            if (len_lut[j] != 1) {

                len_lut[j] += 1;

                val_lut[j] <<= 1;

            } else {

                val_lut[j] = 1;

            }

        }

    }



    return 0;



alloc_fail:

    vc2_encode_end(avctx);

    av_log(avctx, AV_LOG_ERROR, "Unable to allocate memory!\n");

    return AVERROR(ENOMEM);

}

static int lag_decode_zero_run_line(LagarithContext *l, uint8_t *dst,
                                    const uint8_t *src, const uint8_t *src_end,
                                    int width, int esc_count)
{
    int i = 0;
    int count;
    uint8_t zero_run = 0;
    const uint8_t *src_start = src;
    uint8_t mask1 = -(esc_count < 2);
    uint8_t mask2 = -(esc_count < 3);
    uint8_t *end = dst + (width - 2);
output_zeros:
    if (l->zeros_rem) {
        count = FFMIN(l->zeros_rem, width - i);
        if (end - dst < count) {
            av_log(l->avctx, AV_LOG_ERROR, "Too many zeros remaining.\n");
            return AVERROR_INVALIDDATA;
        }
        memset(dst, 0, count);
        l->zeros_rem -= count;
        dst += count;
    }
    while (dst < end) {
        i = 0;
        while (!zero_run && dst + i < end) {
            i++;
            if (i+2 >= src_end - src)
                return AVERROR_INVALIDDATA;
            zero_run =
                !(src[i] | (src[i + 1] & mask1) | (src[i + 2] & mask2));
        }
        if (zero_run) {
            zero_run = 0;
            i += esc_count;
            memcpy(dst, src, i);
            dst += i;
            l->zeros_rem = lag_calc_zero_run(src[i]);
            src += i + 1;
            goto output_zeros;
        } else {
            memcpy(dst, src, i);
            src += i;
            dst += i;
        }
    }
    return  src - src_start;
}

static int make_cdt24_entry(int p1, int p2, int16_t *cdt)

{

    int r, b;



    b = cdt[p2];

    r = cdt[p1]<<16;

    return (b+r) << 1;

}

void eth_setup_vlan_headers(struct eth_header *ehdr, uint16_t vlan_tag,

    bool *is_new)

{

    struct vlan_header *vhdr = PKT_GET_VLAN_HDR(ehdr);



    switch (be16_to_cpu(ehdr->h_proto)) {

    case ETH_P_VLAN:

    case ETH_P_DVLAN:

        /* vlan hdr exists */

        *is_new = false;

        break;



    default:

        /* No VLAN header, put a new one */

        vhdr->h_proto = ehdr->h_proto;

        ehdr->h_proto = cpu_to_be16(ETH_P_VLAN);

        *is_new = true;

        break;

    }

    vhdr->h_tci = cpu_to_be16(vlan_tag);

}

static int vc9_decode_init(AVCodecContext *avctx)

{

    VC9Context *v = avctx->priv_data;

    GetBitContext gb;



    if (!avctx->extradata_size || !avctx->extradata) return -1;

    avctx->pix_fmt = PIX_FMT_YUV420P;

    v->avctx = avctx;



    if (init_common(v) < 0) return -1;



    if (avctx->codec_id == CODEC_ID_WMV3)

    {

        int count = 0;



	// looks like WMV3 has a sequence header stored in the extradata

	// advanced sequence header may be before the first frame

	// the last byte of the extradata is a version number, 1 for the

	// samples we can decode



	init_get_bits(&gb, avctx->extradata, avctx->extradata_size);



	decode_sequence_header(avctx, &gb);



	count = avctx->extradata_size*8 - get_bits_count(&gb);

	if (count>0)

	{

    	    av_log(avctx, AV_LOG_INFO, "Extra data: %i bits left, value: %X\n",

               count, get_bits(&gb, count));

	}

	else

	{

    	    av_log(avctx, AV_LOG_INFO, "Read %i bits in overflow\n", -count);

	}

    }



    /* Done with header parsing */

    //FIXME I feel like this is wrong

    v->width_mb = (avctx->coded_width+15)>>4;

    v->height_mb = (avctx->coded_height+15)>>4;



    /* Allocate mb bitplanes */

    v->mv_type_mb_plane = (uint8_t *)av_malloc(v->width_mb*v->height_mb);

    if (!v->mv_type_mb_plane) return -1;

    v->skip_mb_plane = (uint8_t *)av_malloc(v->width_mb*v->height_mb);

    if (!v->skip_mb_plane) return -1;

    v->direct_mb_plane = (uint8_t *)av_malloc(v->width_mb*v->height_mb);

    if (!v->direct_mb_plane) return -1;



#if HAS_ADVANCED_PROFILE

    if (v->profile > PROFILE_MAIN)

    {

        v->over_flags_plane = (uint8_t *)av_malloc(v->width_mb*v->height_mb);

        if (!v->over_flags_plane) return -1;

        v->ac_pred_plane = (uint8_t *)av_malloc(v->width_mb*v->height_mb);

        if (!v->ac_pred_plane) return -1;

    }

#endif



    return 0;

}

void av_aes_crypt(AVAES *a, uint8_t *dst_, const uint8_t *src_,

                  int count, uint8_t *iv_, int decrypt)

{

    av_aes_block       *dst = (av_aes_block *) dst_;

    const av_aes_block *src = (const av_aes_block *) src_;

    av_aes_block        *iv = (av_aes_block *) iv_;



    while (count--) {

        addkey(&a->state[1], src, &a->round_key[a->rounds]);

        if (decrypt) {

            crypt(a, 0, inv_sbox, dec_multbl);

            if (iv) {

                addkey(&a->state[0], &a->state[0], iv);

                memcpy(iv, src, 16);

            }

            addkey(dst, &a->state[0], &a->round_key[0]);

        } else {

            if (iv)

                addkey(&a->state[1], &a->state[1], iv);

            crypt(a, 2, sbox, enc_multbl);

            addkey(dst, &a->state[0], &a->round_key[0]);

            if (iv)

                memcpy(iv, dst, 16);

        }

        src++;

        dst++;

    }

}

static inline int l3_unscale(int value, int exponent)

{

    unsigned int m;

    int e;



    e  = table_4_3_exp  [4 * value + (exponent & 3)];

    m  = table_4_3_value[4 * value + (exponent & 3)];

    e -= exponent >> 2;

    assert(e >= 1);

    if (e > 31)

        return 0;

    m = (m + (1 << (e - 1))) >> e;



    return m;

}

static void vga_ioport_write(void *opaque, uint32_t addr, uint32_t val)

{

    CirrusVGAState *s = opaque;

    int index;



    /* check port range access depending on color/monochrome mode */

    if ((addr >= 0x3b0 && addr <= 0x3bf && (s->msr & MSR_COLOR_EMULATION))

	|| (addr >= 0x3d0 && addr <= 0x3df

	    && !(s->msr & MSR_COLOR_EMULATION)))

	return;



#ifdef DEBUG_VGA

    printf("VGA: write addr=0x%04x data=0x%02x\n", addr, val);

#endif



    switch (addr) {

    case 0x3c0:

	if (s->ar_flip_flop == 0) {

	    val &= 0x3f;

	    s->ar_index = val;

	} else {

	    index = s->ar_index & 0x1f;

	    switch (index) {

	    case 0x00 ... 0x0f:

		s->ar[index] = val & 0x3f;

		break;

	    case 0x10:

		s->ar[index] = val & ~0x10;

		break;

	    case 0x11:

		s->ar[index] = val;

		break;

	    case 0x12:

		s->ar[index] = val & ~0xc0;

		break;

	    case 0x13:

		s->ar[index] = val & ~0xf0;

		break;

	    case 0x14:

		s->ar[index] = val & ~0xf0;

		break;

	    default:

		break;

	    }

	}

	s->ar_flip_flop ^= 1;

	break;

    case 0x3c2:

	s->msr = val & ~0x10;

	break;

    case 0x3c4:

	s->sr_index = val;

	break;

    case 0x3c5:

	if (cirrus_hook_write_sr(s, s->sr_index, val))

	    break;

#ifdef DEBUG_VGA_REG

	printf("vga: write SR%x = 0x%02x\n", s->sr_index, val);

#endif

	s->sr[s->sr_index] = val & sr_mask[s->sr_index];

	break;

    case 0x3c6:

	cirrus_write_hidden_dac(s, val);

	break;

    case 0x3c7:

	s->dac_read_index = val;

	s->dac_sub_index = 0;

	s->dac_state = 3;

	break;

    case 0x3c8:

	s->dac_write_index = val;

	s->dac_sub_index = 0;

	s->dac_state = 0;

	break;

    case 0x3c9:

	if (cirrus_hook_write_palette(s, val))

	    break;

	s->dac_cache[s->dac_sub_index] = val;

	if (++s->dac_sub_index == 3) {

	    memcpy(&s->palette[s->dac_write_index * 3], s->dac_cache, 3);

	    s->dac_sub_index = 0;

	    s->dac_write_index++;

	}

	break;

    case 0x3ce:

	s->gr_index = val;

	break;

    case 0x3cf:

	if (cirrus_hook_write_gr(s, s->gr_index, val))

	    break;

#ifdef DEBUG_VGA_REG

	printf("vga: write GR%x = 0x%02x\n", s->gr_index, val);

#endif

	s->gr[s->gr_index] = val & gr_mask[s->gr_index];

	break;

    case 0x3b4:

    case 0x3d4:

	s->cr_index = val;

	break;

    case 0x3b5:

    case 0x3d5:

	if (cirrus_hook_write_cr(s, s->cr_index, val))

	    break;

#ifdef DEBUG_VGA_REG

	printf("vga: write CR%x = 0x%02x\n", s->cr_index, val);

#endif

	/* handle CR0-7 protection */

	if ((s->cr[11] & 0x80) && s->cr_index <= 7) {

	    /* can always write bit 4 of CR7 */

	    if (s->cr_index == 7)

		s->cr[7] = (s->cr[7] & ~0x10) | (val & 0x10);

	    return;

	}

	switch (s->cr_index) {

	case 0x01:		/* horizontal display end */

	case 0x07:

	case 0x09:

	case 0x0c:

	case 0x0d:

	case 0x12:		/* veritcal display end */

	    s->cr[s->cr_index] = val;

	    break;



	default:

	    s->cr[s->cr_index] = val;

	    break;

	}

	break;

    case 0x3ba:

    case 0x3da:

	s->fcr = val & 0x10;

	break;

    }

}

static int write_option(void *optctx, const OptionDef *po, const char *opt,

                        const char *arg)

{

    /* new-style options contain an offset into optctx, old-style address of

     * a global var*/

    void *dst = po->flags & (OPT_OFFSET | OPT_SPEC) ?

                (uint8_t *)optctx + po->u.off : po->u.dst_ptr;

    int *dstcount;



    if (po->flags & OPT_SPEC) {

        SpecifierOpt **so = dst;

        char *p = strchr(opt, ':');



        dstcount = (int *)(so + 1);

        *so = grow_array(*so, sizeof(**so), dstcount, *dstcount + 1);

        (*so)[*dstcount - 1].specifier = av_strdup(p ? p + 1 : "");

        dst = &(*so)[*dstcount - 1].u;

    }



    if (po->flags & OPT_STRING) {

        char *str;

        str = av_strdup(arg);

        av_freep(dst);

        *(char **)dst = str;

    } else if (po->flags & OPT_BOOL || po->flags & OPT_INT) {

        *(int *)dst = parse_number_or_die(opt, arg, OPT_INT64, INT_MIN, INT_MAX);

    } else if (po->flags & OPT_INT64) {

        *(int64_t *)dst = parse_number_or_die(opt, arg, OPT_INT64, INT64_MIN, INT64_MAX);

    } else if (po->flags & OPT_TIME) {

        *(int64_t *)dst = parse_time_or_die(opt, arg, 1);

    } else if (po->flags & OPT_FLOAT) {

        *(float *)dst = parse_number_or_die(opt, arg, OPT_FLOAT, -INFINITY, INFINITY);

    } else if (po->flags & OPT_DOUBLE) {

        *(double *)dst = parse_number_or_die(opt, arg, OPT_DOUBLE, -INFINITY, INFINITY);

    } else if (po->u.func_arg) {

        int ret = po->u.func_arg(optctx, opt, arg);

        if (ret < 0) {

            av_log(NULL, AV_LOG_ERROR,

                   "Failed to set value '%s' for option '%s'\n", arg, opt);

            return ret;

        }

    }

    if (po->flags & OPT_EXIT)

        exit(0);



    return 0;

}

static int vp8_decode_frame(AVCodecContext *avctx, void *data, int *data_size,

                            AVPacket *avpkt)

{

    VP8Context *s = avctx->priv_data;

    int ret, mb_x, mb_y, i, y, referenced;

    enum AVDiscard skip_thresh;

    AVFrame *curframe;



    if ((ret = decode_frame_header(s, avpkt->data, avpkt->size)) < 0)

        return ret;



    referenced = s->update_last || s->update_golden == VP56_FRAME_CURRENT

                                || s->update_altref == VP56_FRAME_CURRENT;



    skip_thresh = !referenced ? AVDISCARD_NONREF :

                    !s->keyframe ? AVDISCARD_NONKEY : AVDISCARD_ALL;



    if (avctx->skip_frame >= skip_thresh) {

        s->invisible = 1;

        goto skip_decode;

    }



    for (i = 0; i < 4; i++)

        if (&s->frames[i] != s->framep[VP56_FRAME_PREVIOUS] &&

            &s->frames[i] != s->framep[VP56_FRAME_GOLDEN] &&

            &s->frames[i] != s->framep[VP56_FRAME_GOLDEN2]) {

            curframe = s->framep[VP56_FRAME_CURRENT] = &s->frames[i];

            break;

        }

    if (curframe->data[0])

        avctx->release_buffer(avctx, curframe);



    curframe->key_frame = s->keyframe;

    curframe->pict_type = s->keyframe ? FF_I_TYPE : FF_P_TYPE;

    curframe->reference = referenced ? 3 : 0;

    if ((ret = avctx->get_buffer(avctx, curframe))) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed!\n");

        return ret;

    }



    // Given that arithmetic probabilities are updated every frame, it's quite likely

    // that the values we have on a random interframe are complete junk if we didn't

    // start decode on a keyframe. So just don't display anything rather than junk.

    if (!s->keyframe && (!s->framep[VP56_FRAME_PREVIOUS] ||

                         !s->framep[VP56_FRAME_GOLDEN] ||

                         !s->framep[VP56_FRAME_GOLDEN2])) {

        av_log(avctx, AV_LOG_WARNING, "Discarding interframe without a prior keyframe!\n");

        return AVERROR_INVALIDDATA;

    }



    s->linesize   = curframe->linesize[0];

    s->uvlinesize = curframe->linesize[1];



    if (!s->edge_emu_buffer)

        s->edge_emu_buffer = av_malloc(21*s->linesize);



    memset(s->top_nnz, 0, s->mb_width*sizeof(*s->top_nnz));



    // top edge of 127 for intra prediction

    if (!(avctx->flags & CODEC_FLAG_EMU_EDGE)) {

        memset(curframe->data[0] - s->linesize  -1, 127, s->linesize  +1);

        memset(curframe->data[1] - s->uvlinesize-1, 127, s->uvlinesize+1);

        memset(curframe->data[2] - s->uvlinesize-1, 127, s->uvlinesize+1);

    }



    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        VP56RangeCoder *c = &s->coeff_partition[mb_y & (s->num_coeff_partitions-1)];

        VP8Macroblock *mb = s->macroblocks + mb_y*s->mb_stride;

        uint8_t *intra4x4 = s->intra4x4_pred_mode + 4*mb_y*s->b4_stride;

        uint8_t *dst[3] = {

            curframe->data[0] + 16*mb_y*s->linesize,

            curframe->data[1] +  8*mb_y*s->uvlinesize,

            curframe->data[2] +  8*mb_y*s->uvlinesize

        };



        memset(s->left_nnz, 0, sizeof(s->left_nnz));



        // left edge of 129 for intra prediction

        if (!(avctx->flags & CODEC_FLAG_EMU_EDGE))

            for (i = 0; i < 3; i++)

                for (y = 0; y < 16>>!!i; y++)

                    dst[i][y*curframe->linesize[i]-1] = 129;



        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            decode_mb_mode(s, mb, mb_x, mb_y, intra4x4 + 4*mb_x);



            if (!mb->skip)

                decode_mb_coeffs(s, c, mb, s->top_nnz[mb_x], s->left_nnz);

            else {

                AV_ZERO128(s->non_zero_count_cache);    // luma

                AV_ZERO64(s->non_zero_count_cache[4]);  // chroma

            }



            if (mb->mode <= MODE_I4x4) {

                intra_predict(s, dst, mb, intra4x4 + 4*mb_x, mb_x, mb_y);

                memset(mb->bmv, 0, sizeof(mb->bmv));

            } else {

                inter_predict(s, dst, mb, mb_x, mb_y);

            }



            if (!mb->skip) {

                idct_mb(s, dst[0], dst[1], dst[2], mb);

            } else {

                AV_ZERO64(s->left_nnz);

                AV_WN64(s->top_nnz[mb_x], 0);   // array of 9, so unaligned



                // Reset DC block predictors if they would exist if the mb had coefficients

                if (mb->mode != MODE_I4x4 && mb->mode != VP8_MVMODE_SPLIT) {

                    s->left_nnz[8]      = 0;

                    s->top_nnz[mb_x][8] = 0;

                }

            }



            dst[0] += 16;

            dst[1] += 8;

            dst[2] += 8;

            mb++;

        }

        if (mb_y && s->filter.level && avctx->skip_loop_filter < skip_thresh) {

            if (s->filter.simple)

                filter_mb_row_simple(s, mb_y-1);

            else

                filter_mb_row(s, mb_y-1);

        }

    }

    if (s->filter.level && avctx->skip_loop_filter < skip_thresh) {

        if (s->filter.simple)

            filter_mb_row_simple(s, mb_y-1);

        else

            filter_mb_row(s, mb_y-1);

    }



skip_decode:

    // if future frames don't use the updated probabilities,

    // reset them to the values we saved

    if (!s->update_probabilities)

        s->prob[0] = s->prob[1];



    // check if golden and altref are swapped

    if (s->update_altref == VP56_FRAME_GOLDEN &&

        s->update_golden == VP56_FRAME_GOLDEN2)

        FFSWAP(AVFrame *, s->framep[VP56_FRAME_GOLDEN], s->framep[VP56_FRAME_GOLDEN2]);

    else {

        if (s->update_altref != VP56_FRAME_NONE)

            s->framep[VP56_FRAME_GOLDEN2] = s->framep[s->update_altref];



        if (s->update_golden != VP56_FRAME_NONE)

            s->framep[VP56_FRAME_GOLDEN] = s->framep[s->update_golden];

    }



    if (s->update_last) // move cur->prev

        s->framep[VP56_FRAME_PREVIOUS] = s->framep[VP56_FRAME_CURRENT];



    // release no longer referenced frames

    for (i = 0; i < 4; i++)

        if (s->frames[i].data[0] &&

            &s->frames[i] != s->framep[VP56_FRAME_CURRENT] &&

            &s->frames[i] != s->framep[VP56_FRAME_PREVIOUS] &&

            &s->frames[i] != s->framep[VP56_FRAME_GOLDEN] &&

            &s->frames[i] != s->framep[VP56_FRAME_GOLDEN2])

            avctx->release_buffer(avctx, &s->frames[i]);



    if (!s->invisible) {

        *(AVFrame*)data = *s->framep[VP56_FRAME_CURRENT];

        *data_size = sizeof(AVFrame);

    }



    return avpkt->size;

}

static void coded_frame_add(void *list, struct FrameListData *cx_frame)

{

