static void gen_lswi(DisasContext *ctx)

{

    TCGv t0;

    TCGv_i32 t1, t2;

    int nb = NB(ctx->opcode);

    int start = rD(ctx->opcode);

    int ra = rA(ctx->opcode);

    int nr;



    if (nb == 0)

        nb = 32;

    nr = nb / 4;

    if (unlikely(((start + nr) > 32  &&

                  start <= ra && (start + nr - 32) > ra) ||

                 ((start + nr) <= 32 && start <= ra && (start + nr) > ra))) {

        gen_inval_exception(ctx, POWERPC_EXCP_INVAL_LSWX);

        return;

    }

    gen_set_access_type(ctx, ACCESS_INT);

    /* NIP cannot be restored if the memory exception comes from an helper */

    gen_update_nip(ctx, ctx->nip - 4);

    t0 = tcg_temp_new();

    gen_addr_register(ctx, t0);

    t1 = tcg_const_i32(nb);

    t2 = tcg_const_i32(start);

    gen_helper_lsw(cpu_env, t0, t1, t2);

    tcg_temp_free(t0);

    tcg_temp_free_i32(t1);

    tcg_temp_free_i32(t2);

}

static void rv34_output_i16x16(RV34DecContext *r, int8_t *intra_types, int cbp)

{

    LOCAL_ALIGNED_16(DCTELEM, block16, [16]);

    MpegEncContext *s    = &r->s;

    GetBitContext  *gb   = &s->gb;

    int             q_dc = rv34_qscale_tab[ r->luma_dc_quant_i[s->qscale] ],

                    q_ac = rv34_qscale_tab[s->qscale];

    uint8_t        *dst  = s->dest[0];

    DCTELEM        *ptr  = s->block[0];

    int       avail[6*8] = {0};

    int i, j, itype, has_ac;



    memset(block16, 0, 16 * sizeof(*block16));



    // Set neighbour information.

    if(r->avail_cache[1])

        avail[0] = 1;

    if(r->avail_cache[2])

        avail[1] = avail[2] = 1;

    if(r->avail_cache[3])

        avail[3] = avail[4] = 1;

    if(r->avail_cache[4])

        avail[5] = 1;

    if(r->avail_cache[5])

        avail[8] = avail[16] = 1;

    if(r->avail_cache[9])

        avail[24] = avail[32] = 1;



    has_ac = rv34_decode_block(block16, gb, r->cur_vlcs, 3, 0, q_dc, q_dc, q_ac);

    if(has_ac)

        r->rdsp.rv34_inv_transform(block16);

    else

        r->rdsp.rv34_inv_transform_dc(block16);



    itype = ittrans16[intra_types[0]];

    itype = adjust_pred16(itype, r->avail_cache[6-4], r->avail_cache[6-1]);

    r->h.pred16x16[itype](dst, s->linesize);



    for(j = 0; j < 4; j++){

        for(i = 0; i < 4; i++, cbp >>= 1){

            int dc = block16[i + j*4];



            if(cbp & 1){

                has_ac = rv34_decode_block(ptr, gb, r->cur_vlcs, r->luma_vlc, 0, q_ac, q_ac, q_ac);

            }else

                has_ac = 0;



            if(has_ac){

                ptr[0] = dc;

                r->rdsp.rv34_idct_add(dst+4*i, s->linesize, ptr);

            }else

                r->rdsp.rv34_idct_dc_add(dst+4*i, s->linesize, dc);

        }



        dst += 4*s->linesize;

    }



    itype = ittrans16[intra_types[0]];

    if(itype == PLANE_PRED8x8) itype = DC_PRED8x8;

    itype = adjust_pred16(itype, r->avail_cache[6-4], r->avail_cache[6-1]);



    q_dc = rv34_qscale_tab[rv34_chroma_quant[1][s->qscale]];

    q_ac = rv34_qscale_tab[rv34_chroma_quant[0][s->qscale]];



    for(j = 1; j < 3; j++){

        dst = s->dest[j];

        r->h.pred8x8[itype](dst, s->uvlinesize);

        for(i = 0; i < 4; i++, cbp >>= 1){

            uint8_t *pdst;

            if(!(cbp & 1)) continue;

            pdst   = dst + (i&1)*4 + (i&2)*2*s->uvlinesize;



            rv34_process_block(r, pdst, s->uvlinesize,

                               r->chroma_vlc, 1, q_dc, q_ac);

        }

    }

}

static void term_update(void)

{

    int i, delta;



    if (term_cmd_buf_size != term_last_cmd_buf_size ||

        memcmp(term_cmd_buf, term_last_cmd_buf, term_cmd_buf_size) != 0) {

        for(i = 0; i < term_last_cmd_buf_index; i++) {

            term_printf("\033[D");

        }

        term_cmd_buf[term_cmd_buf_size] = '\0';

        term_printf("%s", term_cmd_buf);

        term_printf("\033[K");

        memcpy(term_last_cmd_buf, term_cmd_buf, term_cmd_buf_size);

        term_last_cmd_buf_size = term_cmd_buf_size;

        term_last_cmd_buf_index = term_cmd_buf_size;

    }

    if (term_cmd_buf_index != term_last_cmd_buf_index) {

        delta = term_cmd_buf_index - term_last_cmd_buf_index;

        if (delta > 0) {

            for(i = 0;i < delta; i++) {

                term_printf("\033[C");

            }

        } else {

            delta = -delta;

            for(i = 0;i < delta; i++) {

                term_printf("\033[D");

            }

        }

        term_last_cmd_buf_index = term_cmd_buf_index;

    }

    term_flush();

}

uint64_t float64_to_uint64 (float64 a STATUS_PARAM)

{

    int64_t v;



    v = int64_to_float64(INT64_MIN STATUS_VAR);

    v = float64_to_int64((a + v) STATUS_VAR);



    return v - INT64_MIN;

}

void tcg_func_start(TCGContext *s)

{

    tcg_pool_reset(s);

    s->nb_temps = s->nb_globals;



    /* No temps have been previously allocated for size or locality.  */

    memset(s->free_temps, 0, sizeof(s->free_temps));



    s->nb_labels = 0;

    s->current_frame_offset = s->frame_start;



#ifdef CONFIG_DEBUG_TCG

    s->goto_tb_issue_mask = 0;

#endif



    s->gen_op_buf[0].next = 1;

    s->gen_op_buf[0].prev = 0;

    s->gen_next_op_idx = 1;

}

uint64_t helper_fdiv (uint64_t arg1, uint64_t arg2)

{

    CPU_DoubleU farg1, farg2;



    farg1.ll = arg1;

    farg2.ll = arg2;

#if USE_PRECISE_EMULATION

    if (unlikely(float64_is_signaling_nan(farg1.d) ||

                 float64_is_signaling_nan(farg2.d))) {

        /* sNaN division */

        farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXSNAN);

    } else if (unlikely(float64_is_infinity(farg1.d) && float64_is_infinity(farg2.d))) {

        /* Division of infinity by infinity */

        farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXIDI);

    } else if (unlikely(!float64_is_nan(farg1.d) && float64_is_zero(farg2.d))) {

        if (float64_is_zero(farg1.d)) {

            /* Division of zero by zero */

            farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXZDZ);

        } else {

            /* Division by zero */

            farg1.ll = float_zero_divide_excp(farg1.d, farg2.d);

        }

    } else {

        farg1.d = float64_div(farg1.d, farg2.d, &env->fp_status);

    }

#else

    farg1.d = float64_div(farg1.d, farg2.d, &env->fp_status);

#endif

    return farg1.ll;

}

static void pflash_cfi02_realize(DeviceState *dev, Error **errp)

{

    pflash_t *pfl = CFI_PFLASH02(dev);

    uint32_t chip_len;

    int ret;

    Error *local_err = NULL;



    chip_len = pfl->sector_len * pfl->nb_blocs;

    /* XXX: to be fixed */

#if 0

    if (total_len != (8 * 1024 * 1024) && total_len != (16 * 1024 * 1024) &&

        total_len != (32 * 1024 * 1024) && total_len != (64 * 1024 * 1024))

        return NULL;

#endif



    memory_region_init_rom_device(&pfl->orig_mem, OBJECT(pfl), pfl->be ?

                                  &pflash_cfi02_ops_be : &pflash_cfi02_ops_le,

                                  pfl, pfl->name, chip_len, &local_err);

    if (local_err) {

        error_propagate(errp, local_err);

