    if (pfl->bs) {

        /* read the initial flash content */

        ret = bdrv_read(pfl->bs, 0, pfl->storage, chip_len >> 9);

        if (ret < 0) {

            vmstate_unregister_ram(&pfl->orig_mem, DEVICE(pfl));

            error_setg(errp, "failed to read the initial flash content");

            return;

        }

    }



    pflash_setup_mappings(pfl);

    pfl->rom_mode = 1;

    sysbus_init_mmio(SYS_BUS_DEVICE(dev), &pfl->mem);



    if (pfl->bs) {

        pfl->ro = bdrv_is_read_only(pfl->bs);

    } else {

        pfl->ro = 0;

    }



    pfl->timer = timer_new_ns(QEMU_CLOCK_VIRTUAL, pflash_timer, pfl);

    pfl->wcycle = 0;

    pfl->cmd = 0;

    pfl->status = 0;

    /* Hardcoded CFI table (mostly from SG29 Spansion flash) */

    pfl->cfi_len = 0x52;

    /* Standard "QRY" string */

    pfl->cfi_table[0x10] = 'Q';

    pfl->cfi_table[0x11] = 'R';

    pfl->cfi_table[0x12] = 'Y';

    /* Command set (AMD/Fujitsu) */

    pfl->cfi_table[0x13] = 0x02;

    pfl->cfi_table[0x14] = 0x00;

    /* Primary extended table address */

    pfl->cfi_table[0x15] = 0x31;

    pfl->cfi_table[0x16] = 0x00;

    /* Alternate command set (none) */

    pfl->cfi_table[0x17] = 0x00;

    pfl->cfi_table[0x18] = 0x00;

    /* Alternate extended table (none) */

    pfl->cfi_table[0x19] = 0x00;

    pfl->cfi_table[0x1A] = 0x00;

    /* Vcc min */

    pfl->cfi_table[0x1B] = 0x27;

    /* Vcc max */

    pfl->cfi_table[0x1C] = 0x36;

    /* Vpp min (no Vpp pin) */

    pfl->cfi_table[0x1D] = 0x00;

    /* Vpp max (no Vpp pin) */

    pfl->cfi_table[0x1E] = 0x00;

    /* Reserved */

    pfl->cfi_table[0x1F] = 0x07;

    /* Timeout for min size buffer write (NA) */

    pfl->cfi_table[0x20] = 0x00;

    /* Typical timeout for block erase (512 ms) */

    pfl->cfi_table[0x21] = 0x09;

    /* Typical timeout for full chip erase (4096 ms) */

    pfl->cfi_table[0x22] = 0x0C;

    /* Reserved */

    pfl->cfi_table[0x23] = 0x01;

    /* Max timeout for buffer write (NA) */

    pfl->cfi_table[0x24] = 0x00;

    /* Max timeout for block erase */

    pfl->cfi_table[0x25] = 0x0A;

    /* Max timeout for chip erase */

    pfl->cfi_table[0x26] = 0x0D;

    /* Device size */

    pfl->cfi_table[0x27] = ctz32(chip_len);

    /* Flash device interface (8 & 16 bits) */

    pfl->cfi_table[0x28] = 0x02;

    pfl->cfi_table[0x29] = 0x00;

    /* Max number of bytes in multi-bytes write */

    /* XXX: disable buffered write as it's not supported */

    //    pfl->cfi_table[0x2A] = 0x05;

    pfl->cfi_table[0x2A] = 0x00;

    pfl->cfi_table[0x2B] = 0x00;

    /* Number of erase block regions (uniform) */

    pfl->cfi_table[0x2C] = 0x01;

    /* Erase block region 1 */

    pfl->cfi_table[0x2D] = pfl->nb_blocs - 1;

    pfl->cfi_table[0x2E] = (pfl->nb_blocs - 1) >> 8;

    pfl->cfi_table[0x2F] = pfl->sector_len >> 8;

    pfl->cfi_table[0x30] = pfl->sector_len >> 16;



    /* Extended */

    pfl->cfi_table[0x31] = 'P';

    pfl->cfi_table[0x32] = 'R';

    pfl->cfi_table[0x33] = 'I';



    pfl->cfi_table[0x34] = '1';

    pfl->cfi_table[0x35] = '0';



    pfl->cfi_table[0x36] = 0x00;

    pfl->cfi_table[0x37] = 0x00;

    pfl->cfi_table[0x38] = 0x00;

    pfl->cfi_table[0x39] = 0x00;



    pfl->cfi_table[0x3a] = 0x00;



    pfl->cfi_table[0x3b] = 0x00;

    pfl->cfi_table[0x3c] = 0x00;

}

static av_always_inline int get_decoded_frame(AVFormatContext *fmt_ctx,

                                              AVFrame *frame, int *got_frame,

                                              AVPacket *pkt)

{

    AVCodecContext *dec_ctx = fmt_ctx->streams[pkt->stream_index]->codec;

    int ret = 0;



    *got_frame = 0;

    if (dec_ctx->codec) {

    switch (dec_ctx->codec_type) {

    case AVMEDIA_TYPE_VIDEO:

        ret = avcodec_decode_video2(dec_ctx, frame, got_frame, pkt);

        break;



    case AVMEDIA_TYPE_AUDIO:

        ret = avcodec_decode_audio4(dec_ctx, frame, got_frame, pkt);

        break;





    return ret;

static int cdxa_probe(AVProbeData *p)

{

    /* check file header */

    if (p->buf[0] == 'R' && p->buf[1] == 'I' &&

        p->buf[2] == 'F' && p->buf[3] == 'F' &&

        p->buf[8] == 'C' && p->buf[9] == 'D' &&

        p->buf[10] == 'X' && p->buf[11] == 'A')

        return AVPROBE_SCORE_MAX;

    else

        return 0;

}

static uint64_t omap_os_timer_read(void *opaque, target_phys_addr_t addr,

                                   unsigned size)

{

    struct omap_32khz_timer_s *s = (struct omap_32khz_timer_s *) opaque;

    int offset = addr & OMAP_MPUI_REG_MASK;



    if (size != 4) {

        return omap_badwidth_read32(opaque, addr);

    }



    switch (offset) {

    case 0x00:	/* TVR */

        return s->timer.reset_val;



    case 0x04:	/* TCR */

        return omap_timer_read(&s->timer);



    case 0x08:	/* CR */

        return (s->timer.ar << 3) | (s->timer.it_ena << 2) | s->timer.st;



    default:

        break;

    }

    OMAP_BAD_REG(addr);

    return 0;

}

static int mlp_parse(AVCodecParserContext *s,

                     AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    MLPParseContext *mp = s->priv_data;

    int sync_present;

    uint8_t parity_bits;

    int next;

    int i, p = 0;



    *poutbuf_size = 0;

    if (buf_size == 0)

        return 0;



    if (!mp->in_sync) {

        // Not in sync - find a major sync header



        for (i = 0; i < buf_size; i++) {

            mp->pc.state = (mp->pc.state << 8) | buf[i];

            if ((mp->pc.state & 0xfffffffe) == 0xf8726fba &&

                // ignore if we do not have the data for the start of header

                mp->pc.index + i >= 7) {

                mp->in_sync = 1;

                mp->bytes_left = 0;

                break;

            }

        }



        if (!mp->in_sync) {

            if (ff_combine_frame(&mp->pc, END_NOT_FOUND, &buf, &buf_size) != -1)

                av_log(avctx, AV_LOG_WARNING, "ff_combine_frame failed\n");

            return buf_size;

        }



        ff_combine_frame(&mp->pc, i - 7, &buf, &buf_size);



        return i - 7;

    }



    if (mp->bytes_left == 0) {

        // Find length of this packet



        /* Copy overread bytes from last frame into buffer. */

        for(; mp->pc.overread>0; mp->pc.overread--) {

            mp->pc.buffer[mp->pc.index++]= mp->pc.buffer[mp->pc.overread_index++];

        }



        if (mp->pc.index + buf_size < 2) {

            if (ff_combine_frame(&mp->pc, END_NOT_FOUND, &buf, &buf_size) != -1)

                av_log(avctx, AV_LOG_WARNING, "ff_combine_frame failed\n");

            return buf_size;

        }



        mp->bytes_left = ((mp->pc.index > 0 ? mp->pc.buffer[0] : buf[0]) << 8)

                       |  (mp->pc.index > 1 ? mp->pc.buffer[1] : buf[1-mp->pc.index]);

        mp->bytes_left = (mp->bytes_left & 0xfff) * 2;

        if (mp->bytes_left <= 0) { // prevent infinite loop

            goto lost_sync;

        }

        mp->bytes_left -= mp->pc.index;

    }



    next = (mp->bytes_left > buf_size) ? END_NOT_FOUND : mp->bytes_left;



    if (ff_combine_frame(&mp->pc, next, &buf, &buf_size) < 0) {

        mp->bytes_left -= buf_size;

        return buf_size;

    }



    mp->bytes_left = 0;



    sync_present = (AV_RB32(buf + 4) & 0xfffffffe) == 0xf8726fba;



    if (!sync_present) {

        /* The first nibble of a frame is a parity check of the 4-byte

         * access unit header and all the 2- or 4-byte substream headers. */

        // Only check when this isn't a sync frame - syncs have a checksum.



        parity_bits = 0;

        for (i = -1; i < mp->num_substreams; i++) {

            parity_bits ^= buf[p++];

            parity_bits ^= buf[p++];



            if (i < 0 || buf[p-2] & 0x80) {

                parity_bits ^= buf[p++];

                parity_bits ^= buf[p++];

            }

        }



        if ((((parity_bits >> 4) ^ parity_bits) & 0xF) != 0xF) {

            av_log(avctx, AV_LOG_INFO, "mlpparse: Parity check failed.\n");

            goto lost_sync;

        }

    } else {

        GetBitContext gb;

        MLPHeaderInfo mh;



        init_get_bits(&gb, buf + 4, (buf_size - 4) << 3);

        if (ff_mlp_read_major_sync(avctx, &mh, &gb) < 0)

            goto lost_sync;



        avctx->bits_per_raw_sample = mh.group1_bits;

        if (avctx->bits_per_raw_sample > 16)

            avctx->sample_fmt = AV_SAMPLE_FMT_S32;

        else

            avctx->sample_fmt = AV_SAMPLE_FMT_S16;

        avctx->sample_rate = mh.group1_samplerate;

        s->duration = mh.access_unit_size;



        if(!avctx->channels || !avctx->channel_layout) {

        if (mh.stream_type == 0xbb) {

            /* MLP stream */

#if FF_API_REQUEST_CHANNELS

FF_DISABLE_DEPRECATION_WARNINGS

            if (avctx->request_channels > 0 && avctx->request_channels <= 2 &&

                mh.num_substreams > 1) {

                avctx->channels       = 2;

                avctx->channel_layout = AV_CH_LAYOUT_STEREO;

FF_ENABLE_DEPRECATION_WARNINGS

            } else

#endif

            if (avctx->request_channel_layout &&

                (avctx->request_channel_layout & AV_CH_LAYOUT_STEREO) ==

                avctx->request_channel_layout &&

                mh.num_substreams > 1) {

                avctx->channels       = 2;

                avctx->channel_layout = AV_CH_LAYOUT_STEREO;

            } else {

                avctx->channels       = mh.channels_mlp;

                avctx->channel_layout = mh.channel_layout_mlp;

            }

        } else { /* mh.stream_type == 0xba */

            /* TrueHD stream */

#if FF_API_REQUEST_CHANNELS

FF_DISABLE_DEPRECATION_WARNINGS

            if (avctx->request_channels > 0 && avctx->request_channels <= 2 &&

                mh.num_substreams > 1) {

                avctx->channels       = 2;

                avctx->channel_layout = AV_CH_LAYOUT_STEREO;

            } else if (avctx->request_channels > 0 &&

                       avctx->request_channels <= mh.channels_thd_stream1) {

                avctx->channels       = mh.channels_thd_stream1;

                avctx->channel_layout = mh.channel_layout_thd_stream1;

FF_ENABLE_DEPRECATION_WARNINGS

            } else

#endif

                if (avctx->request_channel_layout &&

                    (avctx->request_channel_layout & AV_CH_LAYOUT_STEREO) ==

                    avctx->request_channel_layout &&

                    mh.num_substreams > 1) {

                avctx->channels       = 2;

                avctx->channel_layout = AV_CH_LAYOUT_STEREO;

            } else if (!mh.channels_thd_stream2 ||

                       (avctx->request_channel_layout &&

                        (avctx->request_channel_layout & mh.channel_layout_thd_stream1) ==

                        avctx->request_channel_layout)) {

                avctx->channels       = mh.channels_thd_stream1;

                avctx->channel_layout = mh.channel_layout_thd_stream1;

            } else {

                avctx->channels       = mh.channels_thd_stream2;

                avctx->channel_layout = mh.channel_layout_thd_stream2;

            }

        }

        }



        if (!mh.is_vbr) /* Stream is CBR */

            avctx->bit_rate = mh.peak_bitrate;



        mp->num_substreams = mh.num_substreams;

    }



    *poutbuf = buf;

    *poutbuf_size = buf_size;



    return next;



lost_sync:

    mp->in_sync = 0;

    return 1;

}

static int xen_platform_initfn(PCIDevice *dev)
{
    PCIXenPlatformState *d = XEN_PLATFORM(dev);
    uint8_t *pci_conf;
    pci_conf = dev->config;
    pci_set_word(pci_conf + PCI_COMMAND, PCI_COMMAND_IO | PCI_COMMAND_MEMORY);
    pci_config_set_prog_interface(pci_conf, 0);
    pci_conf[PCI_INTERRUPT_PIN] = 1;
    platform_ioport_bar_setup(d);
    pci_register_bar(dev, 0, PCI_BASE_ADDRESS_SPACE_IO, &d->bar);
    /* reserve 16MB mmio address for share memory*/
    platform_mmio_setup(d);
    pci_register_bar(dev, 1, PCI_BASE_ADDRESS_MEM_PREFETCH,
                     &d->mmio_bar);
    platform_fixed_ioport_init(d);
    return 0;
}

static int ftp_passive_mode(FTPContext *s)

{

    char *res = NULL, *start, *end;

    int i;

    const char *command = "PASV\r\n";

    const int pasv_codes[] = {227, 501, 0}; /* 501 is incorrect code */



    if (ftp_send_command(s, command, pasv_codes, &res) != 227 || !res)

        goto fail;



    start = NULL;

    for (i = 0; i < strlen(res); ++i) {

        if (res[i] == '(') {

            start = res + i + 1;

        } else if (res[i] == ')') {

            end = res + i;

            break;

        }

    }

    if (!start || !end)

        goto fail;



    *end  = '\0';

    /* skip ip */

    if (!av_strtok(start, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;



    /* parse port number */

    start = av_strtok(end, ",", &end);

    if (!start) goto fail;

    s->server_data_port = atoi(start) * 256;

    start = av_strtok(end, ",", &end);

    if (!start) goto fail;

    s->server_data_port += atoi(start);

    av_dlog(s, "Server data port: %d\n", s->server_data_port);



    av_free(res);

    return 0;



  fail:

    av_free(res);

    s->server_data_port = -1;

    return AVERROR(EIO);

}

static void RENAME(yuv2yuv1_ar)(SwsContext *c, const int16_t *lumSrc,

                                const int16_t *chrUSrc, const int16_t *chrVSrc,

                                const int16_t *alpSrc,

                                uint8_t *dest, uint8_t *uDest, uint8_t *vDest,

                                uint8_t *aDest, int dstW, int chrDstW)

{

    int p= 4;

    const int16_t *src[4]= { alpSrc + dstW, lumSrc + dstW, chrUSrc + chrDstW, chrVSrc + chrDstW };

    uint8_t *dst[4]= { aDest, dest, uDest, vDest };

    x86_reg counter[4]= { dstW, dstW, chrDstW, chrDstW };



    while (p--) {

        if (dst[p]) {

            __asm__ volatile(

                "mov %2, %%"REG_a"                    \n\t"

                "pcmpeqw %%mm7, %%mm7                 \n\t"

                "psrlw                 $15, %%mm7     \n\t"

                "psllw                  $6, %%mm7     \n\t"

                ".p2align                4            \n\t" /* FIXME Unroll? */

                "1:                                   \n\t"

                "movq  (%0, %%"REG_a", 2), %%mm0      \n\t"

                "movq 8(%0, %%"REG_a", 2), %%mm1      \n\t"

                "paddsw             %%mm7, %%mm0      \n\t"

                "paddsw             %%mm7, %%mm1      \n\t"

                "psraw                 $7, %%mm0      \n\t"

                "psraw                 $7, %%mm1      \n\t"

                "packuswb           %%mm1, %%mm0      \n\t"

                MOVNTQ(%%mm0, (%1, %%REGa))

                "add                   $8, %%"REG_a"  \n\t"

                "jnc                   1b             \n\t"

                :: "r" (src[p]), "r" (dst[p] + counter[p]),

                   "g" (-counter[p])

                : "%"REG_a

            );

        }

    }

}

static sPAPRDRConnector *spapr_phb_get_pci_drc(sPAPRPHBState *phb,

                                               PCIDevice *pdev)

{

    uint32_t busnr = pci_bus_num(PCI_BUS(qdev_get_parent_bus(DEVICE(pdev))));

    return spapr_dr_connector_by_id(SPAPR_DR_CONNECTOR_TYPE_PCI,

                                    (phb->index << 16) |

                                    (busnr << 8) |

                                    pdev->devfn);

}

static int dvvideo_init(AVCodecContext *avctx)

{

    DVVideoContext *s = avctx->priv_data;

    DSPContext dsp;

    static int done=0;

    int i, j;



    if (!done) {

        VLC dv_vlc;

        uint16_t new_dv_vlc_bits[NB_DV_VLC*2];

        uint8_t new_dv_vlc_len[NB_DV_VLC*2];

        uint8_t new_dv_vlc_run[NB_DV_VLC*2];

        int16_t new_dv_vlc_level[NB_DV_VLC*2];



        done = 1;



        dv_vlc_map = av_mallocz(DV_VLC_MAP_LEV_SIZE*DV_VLC_MAP_RUN_SIZE*sizeof(struct dv_vlc_pair));

	if (!dv_vlc_map)

	    return -ENOMEM;



	/* dv_anchor lets each thread know its Id */

	dv_anchor = av_malloc(12*27*sizeof(void*));

	if (!dv_anchor) {

	    av_free(dv_vlc_map);

	    return -ENOMEM;

	}

	for (i=0; i<12*27; i++)

	    dv_anchor[i] = (void*)(size_t)i;



	/* it's faster to include sign bit in a generic VLC parsing scheme */

	for (i=0, j=0; i<NB_DV_VLC; i++, j++) {

	    new_dv_vlc_bits[j] = dv_vlc_bits[i];

	    new_dv_vlc_len[j] = dv_vlc_len[i];

	    new_dv_vlc_run[j] = dv_vlc_run[i];

	    new_dv_vlc_level[j] = dv_vlc_level[i];



	    if (dv_vlc_level[i]) {

	        new_dv_vlc_bits[j] <<= 1;

		new_dv_vlc_len[j]++;



		j++;

		new_dv_vlc_bits[j] = (dv_vlc_bits[i] << 1) | 1;

		new_dv_vlc_len[j] = dv_vlc_len[i] + 1;

		new_dv_vlc_run[j] = dv_vlc_run[i];

		new_dv_vlc_level[j] = -dv_vlc_level[i];

	    }

	}



        /* NOTE: as a trick, we use the fact the no codes are unused

           to accelerate the parsing of partial codes */

        init_vlc(&dv_vlc, TEX_VLC_BITS, j, 

                 new_dv_vlc_len, 1, 1, new_dv_vlc_bits, 2, 2);



        dv_rl_vlc = av_malloc(dv_vlc.table_size * sizeof(RL_VLC_ELEM));

	if (!dv_rl_vlc) {

	    av_free(dv_anchor);

	    av_free(dv_vlc_map);

	    return -ENOMEM;

	}

        for(i = 0; i < dv_vlc.table_size; i++){

            int code= dv_vlc.table[i][0];

            int len = dv_vlc.table[i][1];

            int level, run;



            if(len<0){ //more bits needed

                run= 0;

                level= code;

            } else {

                run=   new_dv_vlc_run[code] + 1;

                level= new_dv_vlc_level[code];

            }

            dv_rl_vlc[i].len = len;

            dv_rl_vlc[i].level = level;

            dv_rl_vlc[i].run = run;

        }

	free_vlc(&dv_vlc);



	for (i = 0; i < NB_DV_VLC - 1; i++) {

           if (dv_vlc_run[i] >= DV_VLC_MAP_RUN_SIZE || dv_vlc_level[i] >= DV_VLC_MAP_LEV_SIZE)

	       continue;



	   if (dv_vlc_map[dv_vlc_run[i]][dv_vlc_level[i]].size != 0)

	       continue;



	   dv_vlc_map[dv_vlc_run[i]][dv_vlc_level[i]].vlc = dv_vlc_bits[i] << 

	                                                    (!!dv_vlc_level[i]);

	   dv_vlc_map[dv_vlc_run[i]][dv_vlc_level[i]].size = dv_vlc_len[i] + 

	                                                     (!!dv_vlc_level[i]);

	}

	for (i = 0; i < DV_VLC_MAP_RUN_SIZE; i++) {

#ifdef DV_CODEC_TINY_TARGET

	   for (j = 1; j < DV_VLC_MAP_LEV_SIZE; j++) {

	      if (dv_vlc_map[i][j].size == 0) {

	          dv_vlc_map[i][j].vlc = dv_vlc_map[0][j].vlc |

		            (dv_vlc_map[i-1][0].vlc << (dv_vlc_map[0][j].size));

	          dv_vlc_map[i][j].size = dv_vlc_map[i-1][0].size + 

		                          dv_vlc_map[0][j].size;

	      }

	   }

#else

	   for (j = 1; j < DV_VLC_MAP_LEV_SIZE/2; j++) {

	      if (dv_vlc_map[i][j].size == 0) {

	          dv_vlc_map[i][j].vlc = dv_vlc_map[0][j].vlc |

		            (dv_vlc_map[i-1][0].vlc << (dv_vlc_map[0][j].size));

	          dv_vlc_map[i][j].size = dv_vlc_map[i-1][0].size + 

		                          dv_vlc_map[0][j].size;

	      }

	      dv_vlc_map[i][((uint16_t)(-j))&0x1ff].vlc = 

	                                    dv_vlc_map[i][j].vlc | 1;

	      dv_vlc_map[i][((uint16_t)(-j))&0x1ff].size = 

	                                    dv_vlc_map[i][j].size;

	   }

#endif

	}

    }



    /* Generic DSP setup */

    dsputil_init(&dsp, avctx);

    s->get_pixels = dsp.get_pixels;



    /* 88DCT setup */

    s->fdct[0] = dsp.fdct;

    s->idct_put[0] = dsp.idct_put;

    for (i=0; i<64; i++)

       s->dv_zigzag[0][i] = dsp.idct_permutation[ff_zigzag_direct[i]];



    /* 248DCT setup */

    s->fdct[1] = dsp.fdct248;

    s->idct_put[1] = simple_idct248_put;  // FIXME: need to add it to DSP

    memcpy(s->dv_zigzag[1], ff_zigzag248_direct, 64);



    /* XXX: do it only for constant case */

    dv_build_unquantize_tables(s, dsp.idct_permutation);



    /* FIXME: I really don't think this should be here */

    if (dv_codec_profile(avctx))

	avctx->pix_fmt = dv_codec_profile(avctx)->pix_fmt; 

    avctx->coded_frame = &s->picture;



    return 0;

}

