static void stereo_processing(PSContext *ps, INTFLOAT (*l)[32][2], INTFLOAT (*r)[32][2], int is34)

{

    int e, b, k;



    INTFLOAT (*H11)[PS_MAX_NUM_ENV+1][PS_MAX_NR_IIDICC] = ps->H11;

    INTFLOAT (*H12)[PS_MAX_NUM_ENV+1][PS_MAX_NR_IIDICC] = ps->H12;

    INTFLOAT (*H21)[PS_MAX_NUM_ENV+1][PS_MAX_NR_IIDICC] = ps->H21;

    INTFLOAT (*H22)[PS_MAX_NUM_ENV+1][PS_MAX_NR_IIDICC] = ps->H22;

    int8_t *opd_hist = ps->opd_hist;

    int8_t *ipd_hist = ps->ipd_hist;

    int8_t iid_mapped_buf[PS_MAX_NUM_ENV][PS_MAX_NR_IIDICC];

    int8_t icc_mapped_buf[PS_MAX_NUM_ENV][PS_MAX_NR_IIDICC];

    int8_t ipd_mapped_buf[PS_MAX_NUM_ENV][PS_MAX_NR_IIDICC];

    int8_t opd_mapped_buf[PS_MAX_NUM_ENV][PS_MAX_NR_IIDICC];

    int8_t (*iid_mapped)[PS_MAX_NR_IIDICC] = iid_mapped_buf;

    int8_t (*icc_mapped)[PS_MAX_NR_IIDICC] = icc_mapped_buf;

    int8_t (*ipd_mapped)[PS_MAX_NR_IIDICC] = ipd_mapped_buf;

    int8_t (*opd_mapped)[PS_MAX_NR_IIDICC] = opd_mapped_buf;

    const int8_t *k_to_i = is34 ? k_to_i_34 : k_to_i_20;

    TABLE_CONST INTFLOAT (*H_LUT)[8][4] = (PS_BASELINE || ps->icc_mode < 3) ? HA : HB;



    //Remapping

    if (ps->num_env_old) {

        memcpy(H11[0][0], H11[0][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H11[0][0][0]));

        memcpy(H11[1][0], H11[1][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H11[1][0][0]));

        memcpy(H12[0][0], H12[0][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H12[0][0][0]));

        memcpy(H12[1][0], H12[1][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H12[1][0][0]));

        memcpy(H21[0][0], H21[0][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H21[0][0][0]));

        memcpy(H21[1][0], H21[1][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H21[1][0][0]));

        memcpy(H22[0][0], H22[0][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H22[0][0][0]));

        memcpy(H22[1][0], H22[1][ps->num_env_old], PS_MAX_NR_IIDICC*sizeof(H22[1][0][0]));

    }



    if (is34) {

        remap34(&iid_mapped, ps->iid_par, ps->nr_iid_par, ps->num_env, 1);

        remap34(&icc_mapped, ps->icc_par, ps->nr_icc_par, ps->num_env, 1);

        if (ps->enable_ipdopd) {

            remap34(&ipd_mapped, ps->ipd_par, ps->nr_ipdopd_par, ps->num_env, 0);

            remap34(&opd_mapped, ps->opd_par, ps->nr_ipdopd_par, ps->num_env, 0);

        }

        if (!ps->is34bands_old) {

            map_val_20_to_34(H11[0][0]);

            map_val_20_to_34(H11[1][0]);

            map_val_20_to_34(H12[0][0]);

            map_val_20_to_34(H12[1][0]);

            map_val_20_to_34(H21[0][0]);

            map_val_20_to_34(H21[1][0]);

            map_val_20_to_34(H22[0][0]);

            map_val_20_to_34(H22[1][0]);

            ipdopd_reset(ipd_hist, opd_hist);

        }

    } else {

        remap20(&iid_mapped, ps->iid_par, ps->nr_iid_par, ps->num_env, 1);

        remap20(&icc_mapped, ps->icc_par, ps->nr_icc_par, ps->num_env, 1);

        if (ps->enable_ipdopd) {

            remap20(&ipd_mapped, ps->ipd_par, ps->nr_ipdopd_par, ps->num_env, 0);

            remap20(&opd_mapped, ps->opd_par, ps->nr_ipdopd_par, ps->num_env, 0);

        }

        if (ps->is34bands_old) {

            map_val_34_to_20(H11[0][0]);

            map_val_34_to_20(H11[1][0]);

            map_val_34_to_20(H12[0][0]);

            map_val_34_to_20(H12[1][0]);

            map_val_34_to_20(H21[0][0]);

            map_val_34_to_20(H21[1][0]);

            map_val_34_to_20(H22[0][0]);

            map_val_34_to_20(H22[1][0]);

            ipdopd_reset(ipd_hist, opd_hist);

        }

    }



    //Mixing

    for (e = 0; e < ps->num_env; e++) {

        for (b = 0; b < NR_PAR_BANDS[is34]; b++) {

            INTFLOAT h11, h12, h21, h22;

            h11 = H_LUT[iid_mapped[e][b] + 7 + 23 * ps->iid_quant][icc_mapped[e][b]][0];

            h12 = H_LUT[iid_mapped[e][b] + 7 + 23 * ps->iid_quant][icc_mapped[e][b]][1];

            h21 = H_LUT[iid_mapped[e][b] + 7 + 23 * ps->iid_quant][icc_mapped[e][b]][2];

            h22 = H_LUT[iid_mapped[e][b] + 7 + 23 * ps->iid_quant][icc_mapped[e][b]][3];



            if (!PS_BASELINE && ps->enable_ipdopd && b < NR_IPDOPD_BANDS[is34]) {

                //The spec say says to only run this smoother when enable_ipdopd

                //is set but the reference decoder appears to run it constantly

                INTFLOAT h11i, h12i, h21i, h22i;

                INTFLOAT ipd_adj_re, ipd_adj_im;

                int opd_idx = opd_hist[b] * 8 + opd_mapped[e][b];

                int ipd_idx = ipd_hist[b] * 8 + ipd_mapped[e][b];

                INTFLOAT opd_re = pd_re_smooth[opd_idx];

                INTFLOAT opd_im = pd_im_smooth[opd_idx];

                INTFLOAT ipd_re = pd_re_smooth[ipd_idx];

                INTFLOAT ipd_im = pd_im_smooth[ipd_idx];

                opd_hist[b] = opd_idx & 0x3F;

                ipd_hist[b] = ipd_idx & 0x3F;



                ipd_adj_re = AAC_MADD30(opd_re, ipd_re, opd_im, ipd_im);

                ipd_adj_im = AAC_MSUB30(opd_im, ipd_re, opd_re, ipd_im);

                h11i = AAC_MUL30(h11,  opd_im);

                h11  = AAC_MUL30(h11,  opd_re);

                h12i = AAC_MUL30(h12,  ipd_adj_im);

                h12  = AAC_MUL30(h12,  ipd_adj_re);

                h21i = AAC_MUL30(h21,  opd_im);

                h21  = AAC_MUL30(h21,  opd_re);

                h22i = AAC_MUL30(h22,  ipd_adj_im);

                h22  = AAC_MUL30(h22,  ipd_adj_re);

                H11[1][e+1][b] = h11i;

                H12[1][e+1][b] = h12i;

                H21[1][e+1][b] = h21i;

                H22[1][e+1][b] = h22i;

            }

            H11[0][e+1][b] = h11;

            H12[0][e+1][b] = h12;

            H21[0][e+1][b] = h21;

            H22[0][e+1][b] = h22;

        }

        for (k = 0; k < NR_BANDS[is34]; k++) {

            LOCAL_ALIGNED_16(INTFLOAT, h, [2], [4]);

            LOCAL_ALIGNED_16(INTFLOAT, h_step, [2], [4]);

            int start = ps->border_position[e];

            int stop  = ps->border_position[e+1];

            INTFLOAT width = Q30(1.f) / ((stop - start) ? (stop - start) : 1);

#if USE_FIXED

            width <<= 1;

#endif

            b = k_to_i[k];

            h[0][0] = H11[0][e][b];

            h[0][1] = H12[0][e][b];

            h[0][2] = H21[0][e][b];

            h[0][3] = H22[0][e][b];

            if (!PS_BASELINE && ps->enable_ipdopd) {

            //Is this necessary? ps_04_new seems unchanged

            if ((is34 && k <= 13 && k >= 9) || (!is34 && k <= 1)) {

                h[1][0] = -H11[1][e][b];

                h[1][1] = -H12[1][e][b];

                h[1][2] = -H21[1][e][b];

                h[1][3] = -H22[1][e][b];

            } else {

                h[1][0] = H11[1][e][b];

                h[1][1] = H12[1][e][b];

                h[1][2] = H21[1][e][b];

                h[1][3] = H22[1][e][b];

            }

            }

            //Interpolation

            h_step[0][0] = AAC_MSUB31_V3(H11[0][e+1][b], h[0][0], width);

            h_step[0][1] = AAC_MSUB31_V3(H12[0][e+1][b], h[0][1], width);

            h_step[0][2] = AAC_MSUB31_V3(H21[0][e+1][b], h[0][2], width);

            h_step[0][3] = AAC_MSUB31_V3(H22[0][e+1][b], h[0][3], width);

            if (!PS_BASELINE && ps->enable_ipdopd) {

                h_step[1][0] = AAC_MSUB31_V3(H11[1][e+1][b], h[1][0], width);

                h_step[1][1] = AAC_MSUB31_V3(H12[1][e+1][b], h[1][1], width);

                h_step[1][2] = AAC_MSUB31_V3(H21[1][e+1][b], h[1][2], width);

                h_step[1][3] = AAC_MSUB31_V3(H22[1][e+1][b], h[1][3], width);

            }

            ps->dsp.stereo_interpolate[!PS_BASELINE && ps->enable_ipdopd](

                l[k] + start + 1, r[k] + start + 1,

                h, h_step, stop - start);

        }

    }

}

static int http_prepare_data(HTTPContext *c)

{

    int i, len, ret;

    AVFormatContext *ctx;



    switch(c->state) {

    case HTTPSTATE_SEND_DATA_HEADER:

        memset(&c->fmt_ctx, 0, sizeof(c->fmt_ctx));

        pstrcpy(c->fmt_ctx.author, sizeof(c->fmt_ctx.author), 

                c->stream->author);

        pstrcpy(c->fmt_ctx.comment, sizeof(c->fmt_ctx.comment), 

                c->stream->comment);

        pstrcpy(c->fmt_ctx.copyright, sizeof(c->fmt_ctx.copyright), 

                c->stream->copyright);

        pstrcpy(c->fmt_ctx.title, sizeof(c->fmt_ctx.title), 

                c->stream->title);



        /* open output stream by using specified codecs */

        c->fmt_ctx.oformat = c->stream->fmt;

        c->fmt_ctx.nb_streams = c->stream->nb_streams;

        for(i=0;i<c->fmt_ctx.nb_streams;i++) {

            AVStream *st;

            st = av_mallocz(sizeof(AVStream));

            c->fmt_ctx.streams[i] = st;

            /* if file or feed, then just take streams from FFStream struct */

            if (!c->stream->feed || 

                c->stream->feed == c->stream)

                memcpy(st, c->stream->streams[i], sizeof(AVStream));

            else

                memcpy(st, c->stream->feed->streams[c->stream->feed_streams[i]],

                           sizeof(AVStream));

            st->codec.frame_number = 0; /* XXX: should be done in

                                           AVStream, not in codec */

        }

        c->got_key_frame = 0;



        /* prepare header and save header data in a stream */

        if (url_open_dyn_buf(&c->fmt_ctx.pb) < 0) {

            /* XXX: potential leak */

            return -1;

        }

        c->fmt_ctx.pb.is_streamed = 1;



        av_write_header(&c->fmt_ctx);



        len = url_close_dyn_buf(&c->fmt_ctx.pb, &c->pb_buffer);

        c->buffer_ptr = c->pb_buffer;

        c->buffer_end = c->pb_buffer + len;



        c->state = HTTPSTATE_SEND_DATA;

        c->last_packet_sent = 0;

        break;

    case HTTPSTATE_SEND_DATA:

        /* find a new packet */

        {

            AVPacket pkt;



            /* read a packet from the input stream */

            if (c->stream->feed) {

                ffm_set_write_index(c->fmt_in, 

                                    c->stream->feed->feed_write_index,

                                    c->stream->feed->feed_size);

            }



            if (c->stream->max_time && 

                c->stream->max_time + c->start_time - cur_time < 0) {

                /* We have timed out */

                c->state = HTTPSTATE_SEND_DATA_TRAILER;

            } else {

                if (c->is_packetized) {

                    if (compute_send_delay(c) > 0) {

                        c->state = HTTPSTATE_WAIT;

                        return 1; /* state changed */

                    }

                }

                if (av_read_frame(c->fmt_in, &pkt) < 0) {

                    if (c->stream->feed && c->stream->feed->feed_opened) {

                        /* if coming from feed, it means we reached the end of the

                           ffm file, so must wait for more data */

                        c->state = HTTPSTATE_WAIT_FEED;

                        return 1; /* state changed */

                    } else {

                        /* must send trailer now because eof or error */

                        c->state = HTTPSTATE_SEND_DATA_TRAILER;

                    }

                } else {

                    /* update first pts if needed */

                    if (c->first_pts == AV_NOPTS_VALUE)

                        c->first_pts = pkt.pts;



                    /* send it to the appropriate stream */

                    if (c->stream->feed) {

                        /* if coming from a feed, select the right stream */

                        if (c->switch_pending) {

                            c->switch_pending = 0;

                            for(i=0;i<c->stream->nb_streams;i++) {

                                if (c->switch_feed_streams[i] == pkt.stream_index) {

                                    if (pkt.flags & PKT_FLAG_KEY) {

                                        do_switch_stream(c, i);

                                    }

                                }

                                if (c->switch_feed_streams[i] >= 0) {

                                    c->switch_pending = 1;

                                }

                            }

                        }

                        for(i=0;i<c->stream->nb_streams;i++) {

                            if (c->feed_streams[i] == pkt.stream_index) {

                                pkt.stream_index = i;

                                if (pkt.flags & PKT_FLAG_KEY) {

                                    c->got_key_frame |= 1 << i;

                                }

                                /* See if we have all the key frames, then 

                                 * we start to send. This logic is not quite

                                 * right, but it works for the case of a 

                                 * single video stream with one or more

                                 * audio streams (for which every frame is 

                                 * typically a key frame). 

                                 */

                                if (!c->stream->send_on_key || 

                                    ((c->got_key_frame + 1) >> c->stream->nb_streams)) {

                                    goto send_it;

                                }

                            }

                        }

                    } else {

                        AVCodecContext *codec;



                    send_it:

                        /* specific handling for RTP: we use several

                           output stream (one for each RTP

                           connection). XXX: need more abstract handling */

                        if (c->is_packetized) {

                            c->packet_stream_index = pkt.stream_index;

                            ctx = c->rtp_ctx[c->packet_stream_index];

                            codec = &ctx->streams[0]->codec;

                        } else {

                            ctx = &c->fmt_ctx;

                            /* Fudge here */

                            codec = &ctx->streams[pkt.stream_index]->codec;

                        }



                        codec->key_frame = ((pkt.flags & PKT_FLAG_KEY) != 0);



#ifdef PJSG

                        if (codec->codec_type == CODEC_TYPE_AUDIO) {

                            codec->frame_size = (codec->sample_rate * pkt.duration + 500000) / 1000000;

                            /* printf("Calculated size %d, from sr %d, duration %d\n", codec->frame_size, codec->sample_rate, pkt.duration); */

                        }

#endif



                        if (c->is_packetized) {

                            ret = url_open_dyn_packet_buf(&ctx->pb, 

                                                          url_get_max_packet_size(c->rtp_handles[c->packet_stream_index]));

                            c->packet_byte_count = 0;

                            c->packet_start_time_us = av_gettime();

                        } else {

                            ret = url_open_dyn_buf(&ctx->pb);

                        }

                        if (ret < 0) {

                            /* XXX: potential leak */

                            return -1;

                        }

                        if (av_write_packet(ctx, &pkt, pkt.pts)) {

                            c->state = HTTPSTATE_SEND_DATA_TRAILER;

                        }



                        len = url_close_dyn_buf(&ctx->pb, &c->pb_buffer);

                        c->buffer_ptr = c->pb_buffer;

                        c->buffer_end = c->pb_buffer + len;



                        codec->frame_number++;

                    }

#ifndef AV_READ_FRAME

                    av_free_packet(&pkt);

#endif

                }

            }

        }

        break;

    default:

    case HTTPSTATE_SEND_DATA_TRAILER:

        /* last packet test ? */

        if (c->last_packet_sent || c->is_packetized)

            return -1;

        ctx = &c->fmt_ctx;

        /* prepare header */

        if (url_open_dyn_buf(&ctx->pb) < 0) {

            /* XXX: potential leak */

            return -1;

        }

        av_write_trailer(ctx);

        len = url_close_dyn_buf(&ctx->pb, &c->pb_buffer);

        c->buffer_ptr = c->pb_buffer;

        c->buffer_end = c->pb_buffer + len;



        c->last_packet_sent = 1;

        break;

    }

    return 0;

}

