    atexit(xen_domain_cleanup);

    xen_domain_watcher();



    xenstore_domain_init1(kernel, ramdisk, cmdline);



    rc = xc_domain_max_vcpus(xen_xc, xen_domid, smp_cpus);

    if (rc < 0) {

        fprintf(stderr, "xen: xc_domain_max_vcpus() failed\n");

