qemu_inject_x86_mce(Monitor *mon, CPUState *cenv, int bank, uint64_t status,

                    uint64_t mcg_status, uint64_t addr, uint64_t misc,

                    int flags)

{

    uint64_t mcg_cap = cenv->mcg_cap;

    uint64_t *banks = cenv->mce_banks + 4 * bank;



    /*

     * If there is an MCE exception being processed, ignore this SRAO MCE

     * unless unconditional injection was requested.

     */

    if (!(flags & MCE_INJECT_UNCOND_AO) && !(status & MCI_STATUS_AR)

        && (cenv->mcg_status & MCG_STATUS_MCIP)) {

        return;

    }

    if (status & MCI_STATUS_UC) {

        /*

         * if MSR_MCG_CTL is not all 1s, the uncorrected error

         * reporting is disabled

         */

        if ((mcg_cap & MCG_CTL_P) && cenv->mcg_ctl != ~(uint64_t)0) {

            monitor_printf(mon,

                           "CPU %d: Uncorrected error reporting disabled\n",

                           cenv->cpu_index);

            return;

        }



        /*

         * if MSR_MCi_CTL is not all 1s, the uncorrected error

         * reporting is disabled for the bank

         */

        if (banks[0] != ~(uint64_t)0) {

            monitor_printf(mon, "CPU %d: Uncorrected error reporting disabled "

                           "for bank %d\n", cenv->cpu_index, bank);

            return;

        }



        if ((cenv->mcg_status & MCG_STATUS_MCIP) ||

            !(cenv->cr[4] & CR4_MCE_MASK)) {

            monitor_printf(mon, "CPU %d: Previous MCE still in progress, "

                                "raising triple fault\n", cenv->cpu_index);

            qemu_log_mask(CPU_LOG_RESET, "Triple fault\n");

            qemu_system_reset_request();

            return;

        }

        if (banks[1] & MCI_STATUS_VAL) {

            status |= MCI_STATUS_OVER;

        }

        banks[2] = addr;

        banks[3] = misc;

        cenv->mcg_status = mcg_status;

        banks[1] = status;

        cpu_interrupt(cenv, CPU_INTERRUPT_MCE);

    } else if (!(banks[1] & MCI_STATUS_VAL)

               || !(banks[1] & MCI_STATUS_UC)) {

        if (banks[1] & MCI_STATUS_VAL) {

            status |= MCI_STATUS_OVER;

        }

        banks[2] = addr;

        banks[3] = misc;

        banks[1] = status;

    } else {

        banks[1] |= MCI_STATUS_OVER;

    }

}

static int mmu_translate_region(CPUS390XState *env, target_ulong vaddr,

                                uint64_t asc, uint64_t entry, int level,

                                target_ulong *raddr, int *flags, int rw)

{

    CPUState *cs = CPU(s390_env_get_cpu(env));

    uint64_t origin, offs, new_entry;

    const int pchks[4] = {

        PGM_SEGMENT_TRANS, PGM_REG_THIRD_TRANS,

        PGM_REG_SEC_TRANS, PGM_REG_FIRST_TRANS

    };



    PTE_DPRINTF("%s: 0x%" PRIx64 "\n", __func__, entry);



    origin = entry & _REGION_ENTRY_ORIGIN;

    offs = (vaddr >> (17 + 11 * level / 4)) & 0x3ff8;



    new_entry = ldq_phys(cs->as, origin + offs);

    PTE_DPRINTF("%s: 0x%" PRIx64 " + 0x%" PRIx64 " => 0x%016" PRIx64 "\n",

                __func__, origin, offs, new_entry);



    if ((new_entry & _REGION_ENTRY_INV) != 0) {

        /* XXX different regions have different faults */

        DPRINTF("%s: invalid region\n", __func__);

        trigger_page_fault(env, vaddr, PGM_SEGMENT_TRANS, asc, rw);

        return -1;

    }



    if ((new_entry & _REGION_ENTRY_TYPE_MASK) != level) {

        trigger_page_fault(env, vaddr, PGM_TRANS_SPEC, asc, rw);

        return -1;

    }



    /* XXX region protection flags */

    /* *flags &= ~PAGE_WRITE */



    if (level == _ASCE_TYPE_SEGMENT) {

        return mmu_translate_segment(env, vaddr, asc, new_entry, raddr, flags,

                                     rw);

    }



    /* Check region table offset and length */

    offs = (vaddr >> (28 + 11 * (level - 4) / 4)) & 3;

    if (offs < ((new_entry & _REGION_ENTRY_TF) >> 6)

        || offs > (new_entry & _REGION_ENTRY_LENGTH)) {

        DPRINTF("%s: invalid offset or len (%lx)\n", __func__, new_entry);

        trigger_page_fault(env, vaddr, pchks[level / 4 - 1], asc, rw);

        return -1;

    }



    /* yet another region */

    return mmu_translate_region(env, vaddr, asc, new_entry, level - 4,

                                raddr, flags, rw);

}

