static int bitpacked_decode_yuv422p10(AVCodecContext *avctx, AVFrame *frame,

                                      AVPacket *avpkt)

{

    uint64_t frame_size = (uint64_t)avctx->width * (uint64_t)avctx->height * 20;

    uint64_t packet_size = avpkt->size * 8;

    GetBitContext bc;

    uint16_t *y, *u, *v;

    int ret, i;



    ret = ff_get_buffer(avctx, frame, 0);

    if (ret < 0)

        return ret;



    y = (uint16_t*)frame->data[0];

    u = (uint16_t*)frame->data[1];

    v = (uint16_t*)frame->data[2];



    if (frame_size > packet_size)

        return AVERROR_INVALIDDATA;



    if (avctx->width % 2)

        return AVERROR_PATCHWELCOME;



    ret = init_get_bits(&bc, avpkt->data, avctx->width * avctx->height * 20);

    if (ret)

        return ret;



    for (i = 0; i < avctx->height; i++) {

        y = (uint16_t*)(frame->data[0] + i * frame->linesize[0]);

        u = (uint16_t*)(frame->data[1] + i * frame->linesize[1]);

        v = (uint16_t*)(frame->data[2] + i * frame->linesize[2]);



        for (int j = 0; j < avctx->width; j += 2) {

            *u++ = get_bits(&bc, 10);

            *y++ = get_bits(&bc, 10);

            *v++ = get_bits(&bc, 10);

            *y++ = get_bits(&bc, 10);

        }

    }



    return 0;

}

dma_write(void *opaque, target_phys_addr_t addr,

	  uint64_t val64, unsigned int size)

{

        struct fs_dma_ctrl *ctrl = opaque;

	uint32_t value = val64;

	int c;



	if (size != 4) {

		dma_winvalid(opaque, addr, value);

	}



        /* Make addr relative to this channel and bounded to nr regs.  */

	c = fs_channel(addr);

        addr &= 0xff;

        addr >>= 2;

        switch (addr)

	{

		case RW_DATA:

			ctrl->channels[c].regs[addr] = value;

			break;



		case RW_CFG:

			ctrl->channels[c].regs[addr] = value;

			dma_update_state(ctrl, c);

			break;

		case RW_CMD:

			/* continue.  */

			if (value & ~1)

				printf("Invalid store to ch=%d RW_CMD %x\n",

				       c, value);

			ctrl->channels[c].regs[addr] = value;

			channel_continue(ctrl, c);

			break;



		case RW_SAVED_DATA:

		case RW_SAVED_DATA_BUF:

		case RW_GROUP:

		case RW_GROUP_DOWN:

			ctrl->channels[c].regs[addr] = value;

			break;



		case RW_ACK_INTR:

		case RW_INTR_MASK:

			ctrl->channels[c].regs[addr] = value;

			channel_update_irq(ctrl, c);

			if (addr == RW_ACK_INTR)

				ctrl->channels[c].regs[RW_ACK_INTR] = 0;

			break;



		case RW_STREAM_CMD:

			if (value & ~1023)

				printf("Invalid store to ch=%d "

				       "RW_STREAMCMD %x\n",

				       c, value);

			ctrl->channels[c].regs[addr] = value;

			D(printf("stream_cmd ch=%d\n", c));

			channel_stream_cmd(ctrl, c, value);

			break;



	        default:

			D(printf ("%s c=%d " TARGET_FMT_plx "\n",

				__func__, c, addr));

			break;

        }

}

ivshmem_client_handle_server_msg(IvshmemClient *client)
{
    IvshmemClientPeer *peer;
    long peer_id;
    int ret, fd;
    ret = ivshmem_client_read_one_msg(client, &peer_id, &fd);
    if (ret < 0) {
    /* can return a peer or the local client */
    peer = ivshmem_client_search_peer(client, peer_id);
    /* delete peer */
    if (fd == -1) {
        if (peer == NULL || peer == &client->local) {
            IVSHMEM_CLIENT_DEBUG(client, "receive delete for invalid "
                                 "peer %ld\n", peer_id);
        IVSHMEM_CLIENT_DEBUG(client, "delete peer id = %ld\n", peer_id);
        ivshmem_client_free_peer(client, peer);
        return 0;
    /* new peer */
    if (peer == NULL) {
        peer = g_malloc0(sizeof(*peer));
        peer->id = peer_id;
        peer->vectors_count = 0;
        QTAILQ_INSERT_TAIL(&client->peer_list, peer, next);
        IVSHMEM_CLIENT_DEBUG(client, "new peer id = %ld\n", peer_id);
    /* new vector */
    IVSHMEM_CLIENT_DEBUG(client, "  new vector %d (fd=%d) for peer id %ld\n",
                         peer->vectors_count, fd, peer->id);
    peer->vectors[peer->vectors_count] = fd;
    peer->vectors_count++;
    return 0;

