AVOption *av_set_string(void *obj, const char *name, const char *val){

    AVOption *o= find_opt(obj, name);

    if(!o || !val || o->offset<=0) 

        return NULL;

    if(o->type != FF_OPT_TYPE_STRING){

        double d=0, tmp_d;

        for(;;){

            int i;

            char buf[256], *tail;



            for(i=0; i<sizeof(buf)-1 && val[i] && val[i]!='+'; i++)

                buf[i]= val[i];

            buf[i]=0;

            val+= i;



            tmp_d= av_parse_num(buf, &tail);

            if(tail > buf)

                d+= tmp_d;

            else{

                AVOption *o_named= find_opt(obj, buf);

                if(o_named && o_named->type == FF_OPT_TYPE_CONST) 

                    d+= o_named->default_val;

                else if(!strcmp(buf, "default")) d+= o->default_val;

                else if(!strcmp(buf, "max"    )) d+= o->max;

                else if(!strcmp(buf, "min"    )) d+= o->min;

                else return NULL;

            }



            if(*val == '+') val++;

            if(!*val)

                return av_set_number(obj, name, d, 1, 1);

        }

        return NULL;

    }



    memcpy(((uint8_t*)obj) + o->offset, val, sizeof(val));

    return o;

}

void helper_xssubqp(CPUPPCState *env, uint32_t opcode)

{

    ppc_vsr_t xt, xa, xb;

    float_status tstat;



    getVSR(rA(opcode) + 32, &xa, env);

    getVSR(rB(opcode) + 32, &xb, env);

    getVSR(rD(opcode) + 32, &xt, env);

    helper_reset_fpstatus(env);



    if (unlikely(Rc(opcode) != 0)) {

        /* TODO: Support xssubqp after round-to-odd is implemented */

        abort();

    }



    tstat = env->fp_status;

    set_float_exception_flags(0, &tstat);

    xt.f128 = float128_sub(xa.f128, xb.f128, &tstat);

    env->fp_status.float_exception_flags |= tstat.float_exception_flags;



    if (unlikely(tstat.float_exception_flags & float_flag_invalid)) {

        if (float128_is_infinity(xa.f128) && float128_is_infinity(xb.f128)) {

            float_invalid_op_excp(env, POWERPC_EXCP_FP_VXISI, 1);

        } else if (float128_is_signaling_nan(xa.f128, &tstat) ||

                   float128_is_signaling_nan(xb.f128, &tstat)) {

            float_invalid_op_excp(env, POWERPC_EXCP_FP_VXSNAN, 1);

        }

    }



    helper_compute_fprf_float128(env, xt.f128);

    putVSR(rD(opcode) + 32, &xt, env);

    float_check_status(env);

}

static void tcx_rstip_writel(void *opaque, hwaddr addr,

                             uint64_t val, unsigned size)

{

    TCXState *s = opaque;

    int i;

    uint32_t col;



    if (!(addr & 4)) {

        s->tmpblit = val;

    } else {

        addr = (addr >> 3) & 0xfffff;

        col = cpu_to_be32(s->tmpblit);

        if (s->depth == 24) {

            for (i = 0; i < 32; i++) {

                if (val & 0x80000000) {

                    s->vram[addr + i] = s->tmpblit;

                    s->vram24[addr + i] = col;

                    s->cplane[addr + i] = col;

                }

                val <<= 1;

            }

        } else {

            for (i = 0; i < 32; i++)  {

                if (val & 0x80000000) {

                    s->vram[addr + i] = s->tmpblit;

                }

                val <<= 1;

            }

        }

        memory_region_set_dirty(&s->vram_mem, addr, 32);

    }

}

