int av_image_fill_arrays(uint8_t *dst_data[4], int dst_linesize[4],

                         const uint8_t *src,

                         enum AVPixelFormat pix_fmt, int width, int height, int align)

{

    int ret, i;



    if ((ret = av_image_check_size(width, height, 0, NULL)) < 0)

        return ret;



    if ((ret = av_image_fill_linesizes(dst_linesize, pix_fmt, width)) < 0)

        return ret;



    for (i = 0; i < 4; i++)

        dst_linesize[i] = FFALIGN(dst_linesize[i], align);



    if ((ret = av_image_fill_pointers(dst_data, pix_fmt, width, NULL, dst_linesize)) < 0)

        return ret;



    return av_image_fill_pointers(dst_data, pix_fmt, height, (uint8_t *)src, dst_linesize);

}

ff_voc_get_packet(AVFormatContext *s, AVPacket *pkt, AVStream *st, int max_size)

{

    VocDecContext *voc = s->priv_data;

    AVCodecParameters *par = st->codecpar;

    AVIOContext *pb = s->pb;

    VocType type;

    int size, tmp_codec=-1;

    int sample_rate = 0;

    int channels = 1;

    int64_t duration;

    int ret;



    av_add_index_entry(st,

                       avio_tell(pb),

                       voc->pts,

                       voc->remaining_size,

                       0,

                       AVINDEX_KEYFRAME);



    while (!voc->remaining_size) {

        type = avio_r8(pb);

        if (type == VOC_TYPE_EOF)

            return AVERROR_EOF;

        voc->remaining_size = avio_rl24(pb);

        if (!voc->remaining_size) {

            if (!s->pb->seekable)

                return AVERROR(EIO);

            voc->remaining_size = avio_size(pb) - avio_tell(pb);

        }

        max_size -= 4;



        switch (type) {

        case VOC_TYPE_VOICE_DATA:

            if (!par->sample_rate) {

                par->sample_rate = 1000000 / (256 - avio_r8(pb));

                if (sample_rate)

                    par->sample_rate = sample_rate;

                avpriv_set_pts_info(st, 64, 1, par->sample_rate);

                par->channels = channels;

                par->bits_per_coded_sample = av_get_bits_per_sample(par->codec_id);

            } else

                avio_skip(pb, 1);

            tmp_codec = avio_r8(pb);

            voc->remaining_size -= 2;

            max_size -= 2;

            channels = 1;

            break;



        case VOC_TYPE_VOICE_DATA_CONT:

            break;



        case VOC_TYPE_EXTENDED:

            sample_rate = avio_rl16(pb);

            avio_r8(pb);

            channels = avio_r8(pb) + 1;

            sample_rate = 256000000 / (channels * (65536 - sample_rate));

            voc->remaining_size = 0;

            max_size -= 4;

            break;



        case VOC_TYPE_NEW_VOICE_DATA:

            if (!par->sample_rate) {

                par->sample_rate = avio_rl32(pb);

                avpriv_set_pts_info(st, 64, 1, par->sample_rate);

                par->bits_per_coded_sample = avio_r8(pb);

                par->channels = avio_r8(pb);

            } else

                avio_skip(pb, 6);

            tmp_codec = avio_rl16(pb);

            avio_skip(pb, 4);

            voc->remaining_size -= 12;

            max_size -= 12;

            break;



        default:

            avio_skip(pb, voc->remaining_size);

            max_size -= voc->remaining_size;

            voc->remaining_size = 0;

            break;

        }

    }



    if (par->sample_rate <= 0) {

        av_log(s, AV_LOG_ERROR, "Invalid sample rate %d\n", par->sample_rate);

        return AVERROR_INVALIDDATA;

    }



    if (tmp_codec >= 0) {

        tmp_codec = ff_codec_get_id(ff_voc_codec_tags, tmp_codec);

        if (par->codec_id == AV_CODEC_ID_NONE)

            par->codec_id = tmp_codec;

        else if (par->codec_id != tmp_codec)

            av_log(s, AV_LOG_WARNING, "Ignoring mid-stream change in audio codec\n");

        if (par->codec_id == AV_CODEC_ID_NONE) {

            if (s->audio_codec_id == AV_CODEC_ID_NONE) {

                av_log(s, AV_LOG_ERROR, "unknown codec tag\n");

                return AVERROR(EINVAL);

            }

            av_log(s, AV_LOG_WARNING, "unknown codec tag\n");

        }

    }



    par->bit_rate = par->sample_rate * par->channels * par->bits_per_coded_sample;



    if (max_size <= 0)

        max_size = 2048;

    size = FFMIN(voc->remaining_size, max_size);

    voc->remaining_size -= size;



    ret = av_get_packet(pb, pkt, size);

    pkt->dts = pkt->pts = voc->pts;



    duration = av_get_audio_frame_duration2(st->codecpar, size);

    if (duration > 0 && voc->pts != AV_NOPTS_VALUE)

        voc->pts += duration;

    else

        voc->pts = AV_NOPTS_VALUE;



    return ret;

}

static int old_codec37(SANMVideoContext *ctx, int top,

                       int left, int width, int height)

{

    int stride = ctx->pitch;

    int i, j, k, t;

    int skip_run = 0;

    int compr, mvoff, seq, flags;

    uint32_t decoded_size;

    uint8_t *dst, *prev;



    compr        = bytestream2_get_byte(&ctx->gb);

    mvoff        = bytestream2_get_byte(&ctx->gb);

    seq          = bytestream2_get_le16(&ctx->gb);

    decoded_size = bytestream2_get_le32(&ctx->gb);

    bytestream2_skip(&ctx->gb, 4);

    flags        = bytestream2_get_byte(&ctx->gb);

    bytestream2_skip(&ctx->gb, 3);



    if (decoded_size > height * stride - left - top * stride) {

        decoded_size = height * stride - left - top * stride;

        av_log(ctx->avctx, AV_LOG_WARNING, "decoded size is too large\n");

    }



    ctx->rotate_code = 0;



    if (((seq & 1) || !(flags & 1)) && (compr && compr != 2))

        rotate_bufs(ctx, 1);



    dst  = ((uint8_t*)ctx->frm0) + left + top * stride;

    prev = ((uint8_t*)ctx->frm2) + left + top * stride;



    if (mvoff > 2) {

        av_log(ctx->avctx, AV_LOG_ERROR, "invalid motion base value %d\n", mvoff);

        return AVERROR_INVALIDDATA;

    }

    av_dlog(ctx->avctx, "compression %d\n", compr);

    switch (compr) {

    case 0:

        for (i = 0; i < height; i++) {

            bytestream2_get_buffer(&ctx->gb, dst, width);

            dst += stride;

        }

        memset(ctx->frm1, 0, ctx->height * stride);

        memset(ctx->frm2, 0, ctx->height * stride);

        break;

    case 2:

        if (rle_decode(ctx, dst, decoded_size))

            return AVERROR_INVALIDDATA;

        memset(ctx->frm1, 0, ctx->frm1_size);

        memset(ctx->frm2, 0, ctx->frm2_size);

        break;

    case 3:

    case 4:

        if (flags & 4) {

            for (j = 0; j < height; j += 4) {

                for (i = 0; i < width; i += 4) {

                    int code;

                    if (skip_run) {

                        skip_run--;

                        copy_block4(dst + i, prev + i, stride, stride, 4);

                        continue;

                    }

                    if (bytestream2_get_bytes_left(&ctx->gb) < 1)

                        return AVERROR_INVALIDDATA;

                    code = bytestream2_get_byteu(&ctx->gb);

                    switch (code) {

                    case 0xFF:

                        if (bytestream2_get_bytes_left(&ctx->gb) < 16)

                            return AVERROR_INVALIDDATA;

                        for (k = 0; k < 4; k++)

                            bytestream2_get_bufferu(&ctx->gb, dst + i + k * stride, 4);

                        break;

                    case 0xFE:

                        if (bytestream2_get_bytes_left(&ctx->gb) < 4)

                            return AVERROR_INVALIDDATA;

                        for (k = 0; k < 4; k++)

                            memset(dst + i + k * stride, bytestream2_get_byteu(&ctx->gb), 4);

                        break;

                    case 0xFD:

                        if (bytestream2_get_bytes_left(&ctx->gb) < 1)

                            return AVERROR_INVALIDDATA;

                        t = bytestream2_get_byteu(&ctx->gb);

                        for (k = 0; k < 4; k++)

                            memset(dst + i + k * stride, t, 4);

                        break;

                    default:

                        if (compr == 4 && !code) {

                            if (bytestream2_get_bytes_left(&ctx->gb) < 1)

                                return AVERROR_INVALIDDATA;

                            skip_run = bytestream2_get_byteu(&ctx->gb) + 1;

                            i -= 4;

                        } else {

                            int mx, my;



                            mx = c37_mv[(mvoff * 255 + code) * 2    ];

                            my = c37_mv[(mvoff * 255 + code) * 2 + 1];

                            codec37_mv(dst + i, prev + i + mx + my * stride,

                                       ctx->height, stride, i + mx, j + my);

                        }

                    }

                }

                dst  += stride * 4;

                prev += stride * 4;

            }

        } else {

            for (j = 0; j < height; j += 4) {

                for (i = 0; i < width; i += 4) {

                    int code;

                    if (skip_run) {

                        skip_run--;

                        copy_block4(dst + i, prev + i, stride, stride, 4);

                        continue;

                    }

                    code = bytestream2_get_byte(&ctx->gb);

                    if (code == 0xFF) {

                        if (bytestream2_get_bytes_left(&ctx->gb) < 16)

                            return AVERROR_INVALIDDATA;

                        for (k = 0; k < 4; k++)

                            bytestream2_get_bufferu(&ctx->gb, dst + i + k * stride, 4);

                    } else if (compr == 4 && !code) {

                        if (bytestream2_get_bytes_left(&ctx->gb) < 1)

                            return AVERROR_INVALIDDATA;

                        skip_run = bytestream2_get_byteu(&ctx->gb) + 1;

                        i -= 4;

                    } else {

                        int mx, my;



                        mx = c37_mv[(mvoff * 255 + code) * 2];

                        my = c37_mv[(mvoff * 255 + code) * 2 + 1];

                        codec37_mv(dst + i, prev + i + mx + my * stride,

                                   ctx->height, stride, i + mx, j + my);

                    }

                }

                dst  += stride * 4;

                prev += stride * 4;

            }

        }

        break;

    default:

        av_log(ctx->avctx, AV_LOG_ERROR,

               "subcodec 37 compression %d not implemented\n", compr);

        return AVERROR_PATCHWELCOME;

    }



    return 0;

}

static void v9fs_stat(void *opaque)

{

    int32_t fid;

    V9fsStat v9stat;

    ssize_t err = 0;

    size_t offset = 7;

    struct stat stbuf;

    V9fsFidState *fidp;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    pdu_unmarshal(pdu, offset, "d", &fid);

    trace_v9fs_stat(pdu->tag, pdu->id, fid);



    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }

    err = v9fs_co_lstat(pdu, &fidp->path, &stbuf);

    if (err < 0) {

        goto out;

    }

    err = stat_to_v9stat(pdu, &fidp->path, &stbuf, &v9stat);

    if (err < 0) {

        goto out;

    }

    offset += pdu_marshal(pdu, offset, "wS", 0, &v9stat);

    err = offset;

    trace_v9fs_stat_return(pdu->tag, pdu->id, v9stat.mode,

                           v9stat.atime, v9stat.mtime, v9stat.length);

    v9fs_stat_free(&v9stat);

out:

    put_fid(pdu, fidp);

out_nofid:

    complete_pdu(s, pdu, err);

}

void rgb16tobgr32(const uint8_t *src, uint8_t *dst, unsigned int src_size)

{

	const uint16_t *end;

	uint8_t *d = (uint8_t *)dst;

	const uint16_t *s = (uint16_t *)src;

	end = s + src_size/2;

	while(s < end)

	{

		register uint16_t bgr;

		bgr = *s++;

		*d++ = (bgr&0xF800)>>8;

		*d++ = (bgr&0x7E0)>>3;

		*d++ = (bgr&0x1F)<<3;

		*d++ = 0;

	}

}

