MemTxResult address_space_read_continue(AddressSpace *as, hwaddr addr,

                                        MemTxAttrs attrs, uint8_t *buf,

                                        int len, hwaddr addr1, hwaddr l,

                                        MemoryRegion *mr)

{

    uint8_t *ptr;

    uint64_t val;

    MemTxResult result = MEMTX_OK;

    bool release_lock = false;



    for (;;) {

        if (!memory_access_is_direct(mr, false)) {

            /* I/O case */

            release_lock |= prepare_mmio_access(mr);

            l = memory_access_size(mr, l, addr1);

            switch (l) {

            case 8:

                /* 64 bit read access */

                result |= memory_region_dispatch_read(mr, addr1, &val, 8,

                                                      attrs);

                stq_p(buf, val);

                break;

            case 4:

                /* 32 bit read access */

                result |= memory_region_dispatch_read(mr, addr1, &val, 4,

                                                      attrs);

                stl_p(buf, val);

                break;

            case 2:

                /* 16 bit read access */

                result |= memory_region_dispatch_read(mr, addr1, &val, 2,

                                                      attrs);

                stw_p(buf, val);

                break;

            case 1:

                /* 8 bit read access */

                result |= memory_region_dispatch_read(mr, addr1, &val, 1,

                                                      attrs);

                stb_p(buf, val);

                break;

            default:

                abort();

            }

        } else {

            /* RAM case */

            ptr = qemu_map_ram_ptr(mr->ram_block, addr1);

            memcpy(buf, ptr, l);

        }



        if (release_lock) {

            qemu_mutex_unlock_iothread();

            release_lock = false;

        }



        len -= l;

        buf += l;

        addr += l;



        if (!len) {

            break;

        }



        l = len;

        mr = address_space_translate(as, addr, &addr1, &l, false);

    }



    return result;

}

static double setup_compress_thresh(double threshold)

{

    if ((threshold > DBL_EPSILON) && (threshold < (1.0 - DBL_EPSILON))) {

        double current_threshold = threshold;

        double step_size = 1.0;



        while (step_size > DBL_EPSILON) {

            while ((current_threshold + step_size > current_threshold) &&

                   (bound(current_threshold + step_size, 1.0) <= threshold)) {

                current_threshold += step_size;

            }



            step_size /= 2.0;

        }



        return current_threshold;

    } else {

        return threshold;

    }

}

