static int decode_frame_common(AVCodecContext *avctx, PNGDecContext *s,

                               AVFrame *p, AVPacket *avpkt)

{

    AVDictionary **metadatap = NULL;

    uint32_t tag, length;

    int decode_next_dat = 0;

    int ret;



    for (;;) {

        length = bytestream2_get_bytes_left(&s->gb);

        if (length <= 0) {



            if (avctx->codec_id == AV_CODEC_ID_PNG &&

                avctx->skip_frame == AVDISCARD_ALL) {

                return 0;

            }



            if (CONFIG_APNG_DECODER && avctx->codec_id == AV_CODEC_ID_APNG && length == 0) {

                if (!(s->pic_state & PNG_IDAT))

                    return 0;

                else

                    goto exit_loop;

            }

            av_log(avctx, AV_LOG_ERROR, "%d bytes left\n", length);

            if (   s->pic_state & PNG_ALLIMAGE

                && avctx->strict_std_compliance <= FF_COMPLIANCE_NORMAL)

                goto exit_loop;

            ret = AVERROR_INVALIDDATA;

            goto fail;

        }



        length = bytestream2_get_be32(&s->gb);

        if (length > 0x7fffffff || length > bytestream2_get_bytes_left(&s->gb)) {

            av_log(avctx, AV_LOG_ERROR, "chunk too big\n");

            ret = AVERROR_INVALIDDATA;

            goto fail;

        }

        tag = bytestream2_get_le32(&s->gb);

        if (avctx->debug & FF_DEBUG_STARTCODE)

            av_log(avctx, AV_LOG_DEBUG, "png: tag=%s length=%u\n",

                   av_fourcc2str(tag), length);



        if (avctx->codec_id == AV_CODEC_ID_PNG &&

            avctx->skip_frame == AVDISCARD_ALL) {

            switch(tag) {

            case MKTAG('I', 'H', 'D', 'R'):

            case MKTAG('p', 'H', 'Y', 's'):

            case MKTAG('t', 'E', 'X', 't'):

            case MKTAG('I', 'D', 'A', 'T'):

            case MKTAG('t', 'R', 'N', 'S'):

                break;

            default:

                goto skip_tag;

            }

        }



        metadatap = &p->metadata;

        switch (tag) {

        case MKTAG('I', 'H', 'D', 'R'):

            if ((ret = decode_ihdr_chunk(avctx, s, length)) < 0)

                goto fail;

            break;

        case MKTAG('p', 'H', 'Y', 's'):

            if ((ret = decode_phys_chunk(avctx, s)) < 0)

                goto fail;

            break;

        case MKTAG('f', 'c', 'T', 'L'):

            if (!CONFIG_APNG_DECODER || avctx->codec_id != AV_CODEC_ID_APNG)

                goto skip_tag;

            if ((ret = decode_fctl_chunk(avctx, s, length)) < 0)

                goto fail;

            decode_next_dat = 1;

            break;

        case MKTAG('f', 'd', 'A', 'T'):

            if (!CONFIG_APNG_DECODER || avctx->codec_id != AV_CODEC_ID_APNG)

                goto skip_tag;

            if (!decode_next_dat) {

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            bytestream2_get_be32(&s->gb);

            length -= 4;

            /* fallthrough */

        case MKTAG('I', 'D', 'A', 'T'):

            if (CONFIG_APNG_DECODER && avctx->codec_id == AV_CODEC_ID_APNG && !decode_next_dat)

                goto skip_tag;

            if ((ret = decode_idat_chunk(avctx, s, length, p)) < 0)

                goto fail;

            break;

        case MKTAG('P', 'L', 'T', 'E'):

            if (decode_plte_chunk(avctx, s, length) < 0)

                goto skip_tag;

            break;

        case MKTAG('t', 'R', 'N', 'S'):

            if (decode_trns_chunk(avctx, s, length) < 0)

                goto skip_tag;

            break;

        case MKTAG('t', 'E', 'X', 't'):

            if (decode_text_chunk(s, length, 0, metadatap) < 0)

                av_log(avctx, AV_LOG_WARNING, "Broken tEXt chunk\n");

            bytestream2_skip(&s->gb, length + 4);

            break;

        case MKTAG('z', 'T', 'X', 't'):

            if (decode_text_chunk(s, length, 1, metadatap) < 0)

                av_log(avctx, AV_LOG_WARNING, "Broken zTXt chunk\n");

            bytestream2_skip(&s->gb, length + 4);

            break;

        case MKTAG('s', 'T', 'E', 'R'): {

            int mode = bytestream2_get_byte(&s->gb);

            AVStereo3D *stereo3d = av_stereo3d_create_side_data(p);

            if (!stereo3d)

                goto fail;



            if (mode == 0 || mode == 1) {

                stereo3d->type  = AV_STEREO3D_SIDEBYSIDE;

                stereo3d->flags = mode ? 0 : AV_STEREO3D_FLAG_INVERT;

            } else {

                 av_log(avctx, AV_LOG_WARNING,

                        "Unknown value in sTER chunk (%d)\n", mode);

            }

            bytestream2_skip(&s->gb, 4); /* crc */

            break;

        }

        case MKTAG('i', 'C', 'C', 'P'): {

            if (decode_iccp_chunk(s, length, p) < 0)

                goto fail;

            break;

        }

        case MKTAG('I', 'E', 'N', 'D'):

            if (!(s->pic_state & PNG_ALLIMAGE))

                av_log(avctx, AV_LOG_ERROR, "IEND without all image\n");

            if (!(s->pic_state & (PNG_ALLIMAGE|PNG_IDAT))) {

                ret = AVERROR_INVALIDDATA;

                goto fail;

            }

            bytestream2_skip(&s->gb, 4); /* crc */

            goto exit_loop;

        default:

            /* skip tag */

skip_tag:

            bytestream2_skip(&s->gb, length + 4);

            break;

        }

    }

exit_loop:



    if (avctx->codec_id == AV_CODEC_ID_PNG &&

        avctx->skip_frame == AVDISCARD_ALL) {

        return 0;

    }



    if (s->bits_per_pixel <= 4)

        handle_small_bpp(s, p);



    /* apply transparency if needed */

    if (s->has_trns && s->color_type != PNG_COLOR_TYPE_PALETTE) {

        size_t byte_depth = s->bit_depth > 8 ? 2 : 1;

        size_t raw_bpp = s->bpp - byte_depth;

        unsigned x, y;



        av_assert0(s->bit_depth > 1);



        for (y = 0; y < s->height; ++y) {

            uint8_t *row = &s->image_buf[s->image_linesize * y];



            /* since we're updating in-place, we have to go from right to left */

            for (x = s->width; x > 0; --x) {

                uint8_t *pixel = &row[s->bpp * (x - 1)];

                memmove(pixel, &row[raw_bpp * (x - 1)], raw_bpp);



                if (!memcmp(pixel, s->transparent_color_be, raw_bpp)) {

                    memset(&pixel[raw_bpp], 0, byte_depth);

                } else {

                    memset(&pixel[raw_bpp], 0xff, byte_depth);

                }

            }

        }

    }



    /* handle P-frames only if a predecessor frame is available */

    if (s->last_picture.f->data[0]) {

        if (   !(avpkt->flags & AV_PKT_FLAG_KEY) && avctx->codec_tag != AV_RL32("MPNG")

            && s->last_picture.f->width == p->width

            && s->last_picture.f->height== p->height

            && s->last_picture.f->format== p->format

         ) {

            if (CONFIG_PNG_DECODER && avctx->codec_id != AV_CODEC_ID_APNG)

                handle_p_frame_png(s, p);

            else if (CONFIG_APNG_DECODER &&

                     avctx->codec_id == AV_CODEC_ID_APNG &&

                     (ret = handle_p_frame_apng(avctx, s, p)) < 0)

                goto fail;

        }

    }

    ff_thread_report_progress(&s->picture, INT_MAX, 0);

    ff_thread_report_progress(&s->previous_picture, INT_MAX, 0);



    return 0;



fail:

    ff_thread_report_progress(&s->picture, INT_MAX, 0);

    ff_thread_report_progress(&s->previous_picture, INT_MAX, 0);

    return ret;

}

static int reap_filters(int flush)

{

    AVFrame *filtered_frame = NULL;

    int i;



    /* Reap all buffers present in the buffer sinks */

    for (i = 0; i < nb_output_streams; i++) {

        OutputStream *ost = output_streams[i];

        OutputFile    *of = output_files[ost->file_index];

        AVFilterContext *filter;

        AVCodecContext *enc = ost->enc_ctx;

        int ret = 0;



        if (!ost->filter || !ost->filter->graph->graph)

            continue;

        filter = ost->filter->filter;



        if (!ost->initialized) {

            char error[1024];

            ret = init_output_stream(ost, error, sizeof(error));

            if (ret < 0) {

                av_log(NULL, AV_LOG_ERROR, "Error initializing output stream %d:%d -- %s\n",

                       ost->file_index, ost->index, error);

                exit_program(1);

            }

        }



        if (!ost->filtered_frame && !(ost->filtered_frame = av_frame_alloc())) {

            return AVERROR(ENOMEM);

        }

        filtered_frame = ost->filtered_frame;



        while (1) {

            double float_pts = AV_NOPTS_VALUE; // this is identical to filtered_frame.pts but with higher precision

            ret = av_buffersink_get_frame_flags(filter, filtered_frame,

                                               AV_BUFFERSINK_FLAG_NO_REQUEST);

            if (ret < 0) {

                if (ret != AVERROR(EAGAIN) && ret != AVERROR_EOF) {

                    av_log(NULL, AV_LOG_WARNING,

                           "Error in av_buffersink_get_frame_flags(): %s\n", av_err2str(ret));

                } else if (flush && ret == AVERROR_EOF) {

                    if (av_buffersink_get_type(filter) == AVMEDIA_TYPE_VIDEO)

                        do_video_out(of, ost, NULL, AV_NOPTS_VALUE);

                }

                break;

            }

            if (ost->finished) {

                av_frame_unref(filtered_frame);

                continue;

            }

            if (filtered_frame->pts != AV_NOPTS_VALUE) {

                int64_t start_time = (of->start_time == AV_NOPTS_VALUE) ? 0 : of->start_time;

                AVRational filter_tb = av_buffersink_get_time_base(filter);

                AVRational tb = enc->time_base;

                int extra_bits = av_clip(29 - av_log2(tb.den), 0, 16);



                tb.den <<= extra_bits;

                float_pts =

                    av_rescale_q(filtered_frame->pts, filter_tb, tb) -

                    av_rescale_q(start_time, AV_TIME_BASE_Q, tb);

                float_pts /= 1 << extra_bits;

                // avoid exact midoints to reduce the chance of rounding differences, this can be removed in case the fps code is changed to work with integers

                float_pts += FFSIGN(float_pts) * 1.0 / (1<<17);



                filtered_frame->pts =

                    av_rescale_q(filtered_frame->pts, filter_tb, enc->time_base) -

                    av_rescale_q(start_time, AV_TIME_BASE_Q, enc->time_base);

            }

            //if (ost->source_index >= 0)

            //    *filtered_frame= *input_streams[ost->source_index]->decoded_frame; //for me_threshold



            switch (av_buffersink_get_type(filter)) {

            case AVMEDIA_TYPE_VIDEO:

                if (!ost->frame_aspect_ratio.num)

                    enc->sample_aspect_ratio = filtered_frame->sample_aspect_ratio;



                if (debug_ts) {

                    av_log(NULL, AV_LOG_INFO, "filter -> pts:%s pts_time:%s exact:%f time_base:%d/%d\n",

                            av_ts2str(filtered_frame->pts), av_ts2timestr(filtered_frame->pts, &enc->time_base),

                            float_pts,

                            enc->time_base.num, enc->time_base.den);

                }



                do_video_out(of, ost, filtered_frame, float_pts);

                break;

            case AVMEDIA_TYPE_AUDIO:

                if (!(enc->codec->capabilities & AV_CODEC_CAP_PARAM_CHANGE) &&

                    enc->channels != av_frame_get_channels(filtered_frame)) {

                    av_log(NULL, AV_LOG_ERROR,

                           "Audio filter graph output is not normalized and encoder does not support parameter changes\n");

                    break;

                }

                do_audio_out(of, ost, filtered_frame);

                break;

            default:

                // TODO support subtitle filters

                av_assert0(0);

            }



            av_frame_unref(filtered_frame);

        }

    }



    return 0;

}

static void FUNC(put_hevc_qpel_bi_w_v)(uint8_t *_dst, ptrdiff_t _dststride, uint8_t *_src, ptrdiff_t _srcstride,

                                       int16_t *src2,

                                       int height, int denom, int wx0, int wx1,

                                       int ox0, int ox1, intptr_t mx, intptr_t my, int width)

{

    int x, y;

    pixel        *src       = (pixel*)_src;

    ptrdiff_t     srcstride = _srcstride / sizeof(pixel);

    pixel *dst          = (pixel *)_dst;

    ptrdiff_t dststride = _dststride / sizeof(pixel);



    const int8_t *filter    = ff_hevc_qpel_filters[my - 1];



    int shift = 14 + 1 - BIT_DEPTH;

    int log2Wd = denom + shift - 1;



    ox0     = ox0 * (1 << (BIT_DEPTH - 8));

    ox1     = ox1 * (1 << (BIT_DEPTH - 8));

    for (y = 0; y < height; y++) {

        for (x = 0; x < width; x++)

            dst[x] = av_clip_pixel(((QPEL_FILTER(src, srcstride) >> (BIT_DEPTH - 8)) * wx1 + src2[x] * wx0 +

                                    ((ox0 + ox1 + 1) << log2Wd)) >> (log2Wd + 1));

        src  += srcstride;

        dst  += dststride;

        src2 += MAX_PB_SIZE;

    }

}

static int skip_check(MpegEncContext *s, Picture *p, Picture *ref)

{

    int x, y, plane;

    int score = 0;

    int64_t score64 = 0;



    for (plane = 0; plane < 3; plane++) {

        const int stride = p->f.linesize[plane];

        const int bw = plane ? 1 : 2;

        for (y = 0; y < s->mb_height * bw; y++) {

            for (x = 0; x < s->mb_width * bw; x++) {

                int off = p->shared ? 0 : 16;

                uint8_t *dptr = p->f.data[plane] + 8 * (x + y * stride) + off;

                uint8_t *rptr = ref->f.data[plane] + 8 * (x + y * stride);

                int v   = s->dsp.frame_skip_cmp[1](s, dptr, rptr, stride, 8);



                switch (s->avctx->frame_skip_exp) {

                case 0: score    =  FFMAX(score, v);          break;

                case 1: score   += FFABS(v);                  break;

                case 2: score   += v * v;                     break;

                case 3: score64 += FFABS(v * v * (int64_t)v); break;

                case 4: score64 += v * v * (int64_t)(v * v);  break;

                }

            }

        }

    }



    if (score)

        score64 = score;



    if (score64 < s->avctx->frame_skip_threshold)

        return 1;

    if (score64 < ((s->avctx->frame_skip_factor * (int64_t)s->lambda) >> 8))

        return 1;

    return 0;

}

int qcrypto_cipher_setiv(QCryptoCipher *cipher,

                         const uint8_t *iv, size_t niv,

                         Error **errp)

{

    QCryptoCipherNettle *ctx = cipher->opaque;

    if (niv != ctx->niv) {

        error_setg(errp, "Expected IV size %zu not %zu",

                   ctx->niv, niv);

        return -1;

    }

    memcpy(ctx->iv, iv, niv);

    return 0;

}

