    pob->bear = 0x00000000;

    pob->besr[0] = 0x0000000;

    pob->besr[1] = 0x0000000;

}

static void kvm_hwpoison_page_add(ram_addr_t ram_addr)

{

    HWPoisonPage *page;



    QLIST_FOREACH(page, &hwpoison_page_list, list) {

        if (page->ram_addr == ram_addr) {

            return;

        }

    }

    page = g_malloc(sizeof(HWPoisonPage));

    page->ram_addr = ram_addr;

    QLIST_INSERT_HEAD(&hwpoison_page_list, page, list);

}

static int QEMU_WARN_UNUSED_RESULT update_refcount(BlockDriverState *bs,

    int64_t offset, int64_t length, int addend)

{

    BDRVQcowState *s = bs->opaque;

    int64_t start, last, cluster_offset;

    int64_t refcount_block_offset = 0;

    int64_t table_index = -1, old_table_index;

    int first_index = -1, last_index = -1;

    int ret;



#ifdef DEBUG_ALLOC2

    printf("update_refcount: offset=%" PRId64 " size=%" PRId64 " addend=%d\n",

           offset, length, addend);

#endif

    if (length < 0) {

        return -EINVAL;

    } else if (length == 0) {

        return 0;

    }



    start = offset & ~(s->cluster_size - 1);

    last = (offset + length - 1) & ~(s->cluster_size - 1);

    for(cluster_offset = start; cluster_offset <= last;

        cluster_offset += s->cluster_size)

    {

        int block_index, refcount;

        int64_t cluster_index = cluster_offset >> s->cluster_bits;

        int64_t new_block;



        /* Only write refcount block to disk when we are done with it */

        old_table_index = table_index;

        table_index = cluster_index >> (s->cluster_bits - REFCOUNT_SHIFT);

        if ((old_table_index >= 0) && (table_index != old_table_index)) {



            ret = write_refcount_block_entries(bs, refcount_block_offset,

                first_index, last_index);

            if (ret < 0) {

                return ret;

            }



            first_index = -1;

            last_index = -1;

        }



        /* Load the refcount block and allocate it if needed */

        new_block = alloc_refcount_block(bs, cluster_index);

        if (new_block < 0) {

            ret = new_block;

            goto fail;

        }

        refcount_block_offset = new_block;



        /* we can update the count and save it */

        block_index = cluster_index &

            ((1 << (s->cluster_bits - REFCOUNT_SHIFT)) - 1);

        if (first_index == -1 || block_index < first_index) {

            first_index = block_index;

        }

        if (block_index > last_index) {

            last_index = block_index;

        }



        refcount = be16_to_cpu(s->refcount_block_cache[block_index]);

        refcount += addend;

        if (refcount < 0 || refcount > 0xffff) {

            ret = -EINVAL;

            goto fail;

        }

        if (refcount == 0 && cluster_index < s->free_cluster_index) {

            s->free_cluster_index = cluster_index;

        }

        s->refcount_block_cache[block_index] = cpu_to_be16(refcount);

    }



    ret = 0;

fail:



    /* Write last changed block to disk */

    if (refcount_block_offset != 0) {

        int wret;

        wret = write_refcount_block_entries(bs, refcount_block_offset,

            first_index, last_index);

        if (wret < 0) {

            return ret < 0 ? ret : wret;

        }

    }



    /*

     * Try do undo any updates if an error is returned (This may succeed in

     * some cases like ENOSPC for allocating a new refcount block)

     */

    if (ret < 0) {

        int dummy;

        dummy = update_refcount(bs, offset, cluster_offset - offset, -addend);

    }



    bdrv_flush(bs->file);



    return ret;

}

static int config_input_ref(AVFilterLink *inlink)

{

    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(inlink->format);

    AVFilterContext *ctx  = inlink->dst;

    PSNRContext *s = ctx->priv;

    unsigned sum;

    int j;



    s->nb_components = desc->nb_components;

    if (ctx->inputs[0]->w != ctx->inputs[1]->w ||

        ctx->inputs[0]->h != ctx->inputs[1]->h) {

        av_log(ctx, AV_LOG_ERROR, "Width and height of input videos must be same.\n");

        return AVERROR(EINVAL);

    }

    if (ctx->inputs[0]->format != ctx->inputs[1]->format) {

        av_log(ctx, AV_LOG_ERROR, "Inputs must be of same pixel format.\n");

        return AVERROR(EINVAL);

    }



    s->max[0] = (1 << (desc->comp[0].depth_minus1 + 1)) - 1;

    s->max[1] = (1 << (desc->comp[1].depth_minus1 + 1)) - 1;

    s->max[2] = (1 << (desc->comp[2].depth_minus1 + 1)) - 1;

    s->max[3] = (1 << (desc->comp[3].depth_minus1 + 1)) - 1;



    s->is_rgb = ff_fill_rgba_map(s->rgba_map, inlink->format) >= 0;

    s->comps[0] = s->is_rgb ? 'r' : 'y' ;

    s->comps[1] = s->is_rgb ? 'g' : 'u' ;

    s->comps[2] = s->is_rgb ? 'b' : 'v' ;

    s->comps[3] = 'a';



    s->planeheight[1] = s->planeheight[2] = FF_CEIL_RSHIFT(inlink->h, desc->log2_chroma_h);

    s->planeheight[0] = s->planeheight[3] = inlink->h;

    s->planewidth[1]  = s->planewidth[2]  = FF_CEIL_RSHIFT(inlink->w, desc->log2_chroma_w);

    s->planewidth[0]  = s->planewidth[3]  = inlink->w;

    sum = 0;

    for (j = 0; j < s->nb_components; j++)

        sum += s->planeheight[j] * s->planewidth[j];

    for (j = 0; j < s->nb_components; j++) {

        s->planeweight[j] = (double) s->planeheight[j] * s->planewidth[j] / sum;

        s->average_max += s->max[j] * s->planeweight[j];

    }



    s->compute_mse = desc->comp[0].depth_minus1 > 7 ? compute_images_mse_16bit : compute_images_mse;



    return 0;

}

static int mpeg_decode_slice(MpegEncContext *s, int mb_y,

                             const uint8_t **buf, int buf_size)

{

    AVCodecContext *avctx = s->avctx;

    const int field_pic   = s->picture_structure != PICT_FRAME;

    int ret;



    s->resync_mb_x =

    s->resync_mb_y = -1;



    assert(mb_y < s->mb_height);



    init_get_bits(&s->gb, *buf, buf_size * 8);



    ff_mpeg1_clean_buffers(s);

    s->interlaced_dct = 0;



    s->qscale = get_qscale(s);



    if (s->qscale == 0) {

        av_log(s->avctx, AV_LOG_ERROR, "qscale == 0\n");

        return AVERROR_INVALIDDATA;

    }



    /* extra slice info */

    while (get_bits1(&s->gb) != 0)

        skip_bits(&s->gb, 8);



    s->mb_x = 0;



    if (mb_y == 0 && s->codec_tag == AV_RL32("SLIF")) {

        skip_bits1(&s->gb);

    } else {

        while (get_bits_left(&s->gb) > 0) {

            int code = get_vlc2(&s->gb, ff_mbincr_vlc.table,

                                MBINCR_VLC_BITS, 2);

            if (code < 0) {

                av_log(s->avctx, AV_LOG_ERROR, "first mb_incr damaged\n");

                return AVERROR_INVALIDDATA;

            }

            if (code >= 33) {

                if (code == 33)

                    s->mb_x += 33;

                /* otherwise, stuffing, nothing to do */

            } else {

                s->mb_x += code;

                break;

            }

        }

    }



    if (s->mb_x >= (unsigned) s->mb_width) {

        av_log(s->avctx, AV_LOG_ERROR, "initial skip overflow\n");

        return AVERROR_INVALIDDATA;

    }



    if (avctx->hwaccel) {

        const uint8_t *buf_end, *buf_start = *buf - 4; /* include start_code */

        int start_code = -1;

        buf_end = avpriv_find_start_code(buf_start + 2, *buf + buf_size, &start_code);

        if (buf_end < *buf + buf_size)

            buf_end -= 4;

        s->mb_y = mb_y;

        if (avctx->hwaccel->decode_slice(avctx, buf_start, buf_end - buf_start) < 0)

            return DECODE_SLICE_ERROR;

        *buf = buf_end;

        return DECODE_SLICE_OK;

    }



    s->resync_mb_x = s->mb_x;

    s->resync_mb_y = s->mb_y = mb_y;

    s->mb_skip_run = 0;

    ff_init_block_index(s);



    if (s->mb_y == 0 && s->mb_x == 0 && (s->first_field || s->picture_structure == PICT_FRAME)) {

        if (s->avctx->debug & FF_DEBUG_PICT_INFO) {

            av_log(s->avctx, AV_LOG_DEBUG,

                   "qp:%d fc:%2d%2d%2d%2d %s %s %s %s %s dc:%d pstruct:%d fdct:%d cmv:%d qtype:%d ivlc:%d rff:%d %s\n",

                   s->qscale,

                   s->mpeg_f_code[0][0], s->mpeg_f_code[0][1],

                   s->mpeg_f_code[1][0], s->mpeg_f_code[1][1],

                   s->pict_type  == AV_PICTURE_TYPE_I ? "I" :

                   (s->pict_type == AV_PICTURE_TYPE_P ? "P" :

                   (s->pict_type == AV_PICTURE_TYPE_B ? "B" : "S")),

                   s->progressive_sequence ? "ps"  : "",

                   s->progressive_frame    ? "pf"  : "",

                   s->alternate_scan       ? "alt" : "",

                   s->top_field_first      ? "top" : "",

                   s->intra_dc_precision, s->picture_structure,

                   s->frame_pred_frame_dct, s->concealment_motion_vectors,

                   s->q_scale_type, s->intra_vlc_format,

                   s->repeat_first_field, s->chroma_420_type ? "420" : "");

        }

    }



    for (;;) {

#if FF_API_XVMC

FF_DISABLE_DEPRECATION_WARNINGS

        // If 1, we memcpy blocks in xvmcvideo.

        if (CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration > 1)

            ff_xvmc_init_block(s); // set s->block

FF_ENABLE_DEPRECATION_WARNINGS

#endif /* FF_API_XVMC */



        if ((ret = mpeg_decode_mb(s, s->block)) < 0)

            return ret;



        // Note motion_val is normally NULL unless we want to extract the MVs.

        if (s->current_picture.motion_val[0] && !s->encoding) {

            const int wrap = s->b8_stride;

            int xy         = s->mb_x * 2 + s->mb_y * 2 * wrap;

            int b8_xy      = 4 * (s->mb_x + s->mb_y * s->mb_stride);

            int motion_x, motion_y, dir, i;



            for (i = 0; i < 2; i++) {

                for (dir = 0; dir < 2; dir++) {

                    if (s->mb_intra ||

                        (dir == 1 && s->pict_type != AV_PICTURE_TYPE_B)) {

                        motion_x = motion_y = 0;

                    } else if (s->mv_type == MV_TYPE_16X16 ||

                               (s->mv_type == MV_TYPE_FIELD && field_pic)) {

                        motion_x = s->mv[dir][0][0];

                        motion_y = s->mv[dir][0][1];

                    } else { /* if ((s->mv_type == MV_TYPE_FIELD) || (s->mv_type == MV_TYPE_16X8)) */

                        motion_x = s->mv[dir][i][0];

                        motion_y = s->mv[dir][i][1];

                    }



                    s->current_picture.motion_val[dir][xy][0]     = motion_x;

                    s->current_picture.motion_val[dir][xy][1]     = motion_y;

                    s->current_picture.motion_val[dir][xy + 1][0] = motion_x;

                    s->current_picture.motion_val[dir][xy + 1][1] = motion_y;

                    s->current_picture.ref_index [dir][b8_xy]     =

                    s->current_picture.ref_index [dir][b8_xy + 1] = s->field_select[dir][i];

                    assert(s->field_select[dir][i] == 0 ||

                           s->field_select[dir][i] == 1);

                }

                xy    += wrap;

                b8_xy += 2;

            }

        }



        s->dest[0] += 16;

        s->dest[1] += 16 >> s->chroma_x_shift;

        s->dest[2] += 16 >> s->chroma_x_shift;



        ff_mpv_decode_mb(s, s->block);



        if (++s->mb_x >= s->mb_width) {

            const int mb_size = 16;



            ff_mpeg_draw_horiz_band(s, mb_size * (s->mb_y >> field_pic), mb_size);

            ff_mpv_report_decode_progress(s);



            s->mb_x  = 0;

            s->mb_y += 1 << field_pic;



            if (s->mb_y >= s->mb_height) {

                int left   = get_bits_left(&s->gb);

                int is_d10 = s->chroma_format == 2 &&

                             s->pict_type == AV_PICTURE_TYPE_I &&

                             avctx->profile == 0 && avctx->level == 5 &&

                             s->intra_dc_precision == 2 &&

                             s->q_scale_type == 1 && s->alternate_scan == 0 &&

                             s->progressive_frame == 0

                             /* vbv_delay == 0xBBB || 0xE10 */;



                if (left < 0 ||

                    (left && show_bits(&s->gb, FFMIN(left, 23)) && !is_d10) ||

                    ((avctx->err_recognition & AV_EF_BUFFER) && left > 8)) {

                    av_log(avctx, AV_LOG_ERROR, "end mismatch left=%d %0X\n",

                           left, show_bits(&s->gb, FFMIN(left, 23)));

                    return AVERROR_INVALIDDATA;

                } else

                    goto eos;

            }



            ff_init_block_index(s);

        }



        /* skip mb handling */

        if (s->mb_skip_run == -1) {

            /* read increment again */

            s->mb_skip_run = 0;

            for (;;) {

                int code = get_vlc2(&s->gb, ff_mbincr_vlc.table,

                                    MBINCR_VLC_BITS, 2);

                if (code < 0) {

                    av_log(s->avctx, AV_LOG_ERROR, "mb incr damaged\n");

                    return AVERROR_INVALIDDATA;

                }

                if (code >= 33) {

                    if (code == 33) {

                        s->mb_skip_run += 33;

                    } else if (code == 35) {

                        if (s->mb_skip_run != 0 || show_bits(&s->gb, 15) != 0) {

                            av_log(s->avctx, AV_LOG_ERROR, "slice mismatch\n");

                            return AVERROR_INVALIDDATA;

                        }

                        goto eos; /* end of slice */

                    }

                    /* otherwise, stuffing, nothing to do */

                } else {

                    s->mb_skip_run += code;

                    break;

                }

            }

            if (s->mb_skip_run) {

                int i;

                if (s->pict_type == AV_PICTURE_TYPE_I) {

                    av_log(s->avctx, AV_LOG_ERROR,

                           "skipped MB in I-frame at %d %d\n", s->mb_x, s->mb_y);

                    return AVERROR_INVALIDDATA;

                }



                /* skip mb */

                s->mb_intra = 0;

                for (i = 0; i < 12; i++)

                    s->block_last_index[i] = -1;

                if (s->picture_structure == PICT_FRAME)

                    s->mv_type = MV_TYPE_16X16;

                else

                    s->mv_type = MV_TYPE_FIELD;

                if (s->pict_type == AV_PICTURE_TYPE_P) {

                    /* if P type, zero motion vector is implied */

                    s->mv_dir             = MV_DIR_FORWARD;

                    s->mv[0][0][0]        = s->mv[0][0][1]      = 0;

                    s->last_mv[0][0][0]   = s->last_mv[0][0][1] = 0;

                    s->last_mv[0][1][0]   = s->last_mv[0][1][1] = 0;

                    s->field_select[0][0] = (s->picture_structure - 1) & 1;

                } else {

                    /* if B type, reuse previous vectors and directions */

                    s->mv[0][0][0] = s->last_mv[0][0][0];

                    s->mv[0][0][1] = s->last_mv[0][0][1];

                    s->mv[1][0][0] = s->last_mv[1][0][0];

                    s->mv[1][0][1] = s->last_mv[1][0][1];

                }

            }

        }

    }

eos: // end of slice

    *buf += (get_bits_count(&s->gb) - 1) / 8;

    ff_dlog(s, "y %d %d %d %d\n", s->resync_mb_x, s->resync_mb_y, s->mb_x, s->mb_y);

    return 0;

}

