uart_write(void *opaque, hwaddr addr,

           uint64_t val64, unsigned int size)

{

    XilinxUARTLite *s = opaque;

    uint32_t value = val64;

    unsigned char ch = value;



    addr >>= 2;

    switch (addr)

    {

        case R_STATUS:

            hw_error("write to UART STATUS?\n");

            break;



        case R_CTRL:

            if (value & CONTROL_RST_RX) {

                s->rx_fifo_pos = 0;

                s->rx_fifo_len = 0;

            }

            s->regs[addr] = value;

            break;



        case R_TX:

            if (s->chr)

                qemu_chr_fe_write(s->chr, &ch, 1);



            s->regs[addr] = value;



            /* hax.  */

            s->regs[R_STATUS] |= STATUS_IE;

            break;



        default:

            DUART(printf("%s addr=%x v=%x\n", __func__, addr, value));

            if (addr < ARRAY_SIZE(s->regs))

                s->regs[addr] = value;

            break;

    }

    uart_update_status(s);

    uart_update_irq(s);

}

BlockDriverState *bdrv_find_backing_image(BlockDriverState *bs,

        const char *backing_file)

{

    char *filename_full = NULL;

    char *backing_file_full = NULL;

    char *filename_tmp = NULL;

    int is_protocol = 0;

    BlockDriverState *curr_bs = NULL;

    BlockDriverState *retval = NULL;



    if (!bs || !bs->drv || !backing_file) {

        return NULL;

    }



    filename_full     = g_malloc(PATH_MAX);

    backing_file_full = g_malloc(PATH_MAX);

    filename_tmp      = g_malloc(PATH_MAX);



    is_protocol = path_has_protocol(backing_file);



    for (curr_bs = bs; curr_bs->backing_hd; curr_bs = curr_bs->backing_hd) {



        /* If either of the filename paths is actually a protocol, then

         * compare unmodified paths; otherwise make paths relative */

        if (is_protocol || path_has_protocol(curr_bs->backing_file)) {

            if (strcmp(backing_file, curr_bs->backing_file) == 0) {

                retval = curr_bs->backing_hd;

                break;

            }

        } else {

            /* If not an absolute filename path, make it relative to the current

             * image's filename path */

            path_combine(filename_tmp, PATH_MAX, curr_bs->filename,

                         backing_file);



            /* We are going to compare absolute pathnames */

            if (!realpath(filename_tmp, filename_full)) {

                continue;

            }



            /* We need to make sure the backing filename we are comparing against

             * is relative to the current image filename (or absolute) */

            path_combine(filename_tmp, PATH_MAX, curr_bs->filename,

                         curr_bs->backing_file);



            if (!realpath(filename_tmp, backing_file_full)) {

                continue;

            }



            if (strcmp(backing_file_full, filename_full) == 0) {

                retval = curr_bs->backing_hd;

                break;

            }

        }

    }



    g_free(filename_full);

    g_free(backing_file_full);

    g_free(filename_tmp);

    return retval;

}

void error_setg_errno(Error **errp, int os_errno, const char *fmt, ...)

{

    va_list ap;

    char *msg;

    int saved_errno = errno;



    if (errp == NULL) {

        return;

    }



    va_start(ap, fmt);

    error_setv(errp, ERROR_CLASS_GENERIC_ERROR, fmt, ap);

    va_end(ap);



    if (os_errno != 0) {

        msg = (*errp)->msg;

        (*errp)->msg = g_strdup_printf("%s: %s", msg, strerror(os_errno));

        g_free(msg);

    }



    errno = saved_errno;

}

int xen_hvm_init(ram_addr_t *below_4g_mem_size, ram_addr_t *above_4g_mem_size,

                 MemoryRegion **ram_memory)

{

    int i, rc;

    unsigned long ioreq_pfn;

    unsigned long bufioreq_evtchn;

    XenIOState *state;



    state = g_malloc0(sizeof (XenIOState));



    state->xce_handle = xen_xc_evtchn_open(NULL, 0);

    if (state->xce_handle == XC_HANDLER_INITIAL_VALUE) {

        perror("xen: event channel open");

        return -1;

    }



    state->xenstore = xs_daemon_open();

    if (state->xenstore == NULL) {

        perror("xen: xenstore open");

        return -1;

    }



    state->exit.notify = xen_exit_notifier;

    qemu_add_exit_notifier(&state->exit);



    state->suspend.notify = xen_suspend_notifier;

    qemu_register_suspend_notifier(&state->suspend);



    state->wakeup.notify = xen_wakeup_notifier;

    qemu_register_wakeup_notifier(&state->wakeup);



    xc_get_hvm_param(xen_xc, xen_domid, HVM_PARAM_IOREQ_PFN, &ioreq_pfn);

    DPRINTF("shared page at pfn %lx\n", ioreq_pfn);

    state->shared_page = xc_map_foreign_range(xen_xc, xen_domid, XC_PAGE_SIZE,

                                              PROT_READ|PROT_WRITE, ioreq_pfn);

    if (state->shared_page == NULL) {

        hw_error("map shared IO page returned error %d handle=" XC_INTERFACE_FMT,

                 errno, xen_xc);

    }



    rc = xen_get_vmport_regs_pfn(xen_xc, xen_domid, &ioreq_pfn);

    if (!rc) {

        DPRINTF("shared vmport page at pfn %lx\n", ioreq_pfn);

        state->shared_vmport_page =

            xc_map_foreign_range(xen_xc, xen_domid, XC_PAGE_SIZE,

                                 PROT_READ|PROT_WRITE, ioreq_pfn);

        if (state->shared_vmport_page == NULL) {

            hw_error("map shared vmport IO page returned error %d handle="

                     XC_INTERFACE_FMT, errno, xen_xc);

        }

    } else if (rc != -ENOSYS) {

        hw_error("get vmport regs pfn returned error %d, rc=%d", errno, rc);

    }



    xc_get_hvm_param(xen_xc, xen_domid, HVM_PARAM_BUFIOREQ_PFN, &ioreq_pfn);

    DPRINTF("buffered io page at pfn %lx\n", ioreq_pfn);

    state->buffered_io_page = xc_map_foreign_range(xen_xc, xen_domid, XC_PAGE_SIZE,

                                                   PROT_READ|PROT_WRITE, ioreq_pfn);

    if (state->buffered_io_page == NULL) {

        hw_error("map buffered IO page returned error %d", errno);

    }



    /* Note: cpus is empty at this point in init */

    state->cpu_by_vcpu_id = g_malloc0(max_cpus * sizeof(CPUState *));



    state->ioreq_local_port = g_malloc0(max_cpus * sizeof (evtchn_port_t));



    /* FIXME: how about if we overflow the page here? */

    for (i = 0; i < max_cpus; i++) {

        rc = xc_evtchn_bind_interdomain(state->xce_handle, xen_domid,

                                        xen_vcpu_eport(state->shared_page, i));

        if (rc == -1) {

            fprintf(stderr, "bind interdomain ioctl error %d\n", errno);

            return -1;

        }

        state->ioreq_local_port[i] = rc;

    }



    rc = xc_get_hvm_param(xen_xc, xen_domid, HVM_PARAM_BUFIOREQ_EVTCHN,

            &bufioreq_evtchn);

    if (rc < 0) {

        fprintf(stderr, "failed to get HVM_PARAM_BUFIOREQ_EVTCHN\n");

        return -1;

    }

    rc = xc_evtchn_bind_interdomain(state->xce_handle, xen_domid,

            (uint32_t)bufioreq_evtchn);

    if (rc == -1) {

        fprintf(stderr, "bind interdomain ioctl error %d\n", errno);

        return -1;

    }

    state->bufioreq_local_port = rc;



    /* Init RAM management */

    xen_map_cache_init(xen_phys_offset_to_gaddr, state);

    xen_ram_init(below_4g_mem_size, above_4g_mem_size, ram_size, ram_memory);



    qemu_add_vm_change_state_handler(xen_hvm_change_state_handler, state);



    state->memory_listener = xen_memory_listener;

    QLIST_INIT(&state->physmap);

    memory_listener_register(&state->memory_listener, &address_space_memory);

    state->log_for_dirtybit = NULL;



    /* Initialize backend core & drivers */

    if (xen_be_init() != 0) {

        fprintf(stderr, "%s: xen backend core setup failed\n", __FUNCTION__);

        return -1;

    }

    xen_be_register("console", &xen_console_ops);

    xen_be_register("vkbd", &xen_kbdmouse_ops);

    xen_be_register("qdisk", &xen_blkdev_ops);

    xen_read_physmap(state);



    return 0;

}

int print_insn_xtensa(bfd_vma memaddr, struct disassemble_info *info)

{

    xtensa_isa isa = info->private_data;

    xtensa_insnbuf insnbuf = xtensa_insnbuf_alloc(isa);

    xtensa_insnbuf slotbuf = xtensa_insnbuf_alloc(isa);

    bfd_byte *buffer = g_malloc(1);

    int status = info->read_memory_func(memaddr, buffer, 1, info);

    xtensa_format fmt;

    unsigned slot, slots;

    unsigned len;



    if (status) {

        info->memory_error_func(status, memaddr, info);

        len = -1;

        goto out;

    }

    len = xtensa_isa_length_from_chars(isa, buffer);

    if (len == XTENSA_UNDEFINED) {

        info->fprintf_func(info->stream, ".byte 0x%02x", buffer[0]);

        len = 1;

        goto out;

    }

    buffer = g_realloc(buffer, len);

    status = info->read_memory_func(memaddr + 1, buffer + 1, len - 1, info);

    if (status) {

        info->fprintf_func(info->stream, ".byte 0x%02x", buffer[0]);

        info->memory_error_func(status, memaddr + 1, info);

        len = 1;

        goto out;

    }



    xtensa_insnbuf_from_chars(isa, insnbuf, buffer, len);

    fmt = xtensa_format_decode(isa, insnbuf);

    if (fmt == XTENSA_UNDEFINED) {

        unsigned i;



        for (i = 0; i < len; ++i) {

            info->fprintf_func(info->stream, "%s 0x%02x",

                               i ? ", " : ".byte ", buffer[i]);

        }

        goto out;

    }

    slots = xtensa_format_num_slots(isa, fmt);



    if (slots > 1) {

        info->fprintf_func(info->stream, "{ ");

    }



    for (slot = 0; slot < slots; ++slot) {

        xtensa_opcode opc;

        unsigned opnd, vopnd, opnds;



        if (slot) {

            info->fprintf_func(info->stream, "; ");

        }

        xtensa_format_get_slot(isa, fmt, slot, insnbuf, slotbuf);

        opc = xtensa_opcode_decode(isa, fmt, slot, slotbuf);

        if (opc == XTENSA_UNDEFINED) {

            info->fprintf_func(info->stream, "???");

            continue;

        }

        opnds = xtensa_opcode_num_operands(isa, opc);



        info->fprintf_func(info->stream, "%s", xtensa_opcode_name(isa, opc));



        for (opnd = vopnd = 0; opnd < opnds; ++opnd) {

            if (xtensa_operand_is_visible(isa, opc, opnd)) {

                uint32_t v = 0xbadc0de;

                int rc;



                info->fprintf_func(info->stream, vopnd ? ", " : "\t");

                xtensa_operand_get_field(isa, opc, opnd, fmt, slot,

                                         slotbuf, &v);

                rc = xtensa_operand_decode(isa, opc, opnd, &v);

                if (rc == XTENSA_UNDEFINED) {

                    info->fprintf_func(info->stream, "???");

                } else if (xtensa_operand_is_register(isa, opc, opnd)) {

                    xtensa_regfile rf = xtensa_operand_regfile(isa, opc, opnd);



                    info->fprintf_func(info->stream, "%s%d",

                                       xtensa_regfile_shortname(isa, rf), v);

                } else if (xtensa_operand_is_PCrelative(isa, opc, opnd)) {

                    xtensa_operand_undo_reloc(isa, opc, opnd, &v, memaddr);

                    info->fprintf_func(info->stream, "0x%x", v);

                } else {

                    info->fprintf_func(info->stream, "%d", v);

                }

                ++vopnd;

            }

        }

    }

    if (slots > 1) {

        info->fprintf_func(info->stream, " }");

    }



out:

    g_free(buffer);

    xtensa_insnbuf_free(isa, insnbuf);

    xtensa_insnbuf_free(isa, slotbuf);



    return len;

}

static int ipvideo_decode_block_opcode_0xE(IpvideoContext *s)

{

    int y;

    unsigned char pix;



    /* 1-color encoding: the whole block is 1 solid color */

    CHECK_STREAM_PTR(1);

    pix = *s->stream_ptr++;



    for (y = 0; y < 8; y++) {

        memset(s->pixel_ptr, pix, 8);

        s->pixel_ptr += s->stride;

    }



    /* report success */

    return 0;

}

