static int decode_spectrum_and_dequant(AACContext * ac, float coef[1024], GetBitContext * gb, float sf[120],

        int pulse_present, const Pulse * pulse, const IndividualChannelStream * ics, enum BandType band_type[120]) {

    int i, k, g, idx = 0;

    const int c = 1024/ics->num_windows;

    const uint16_t * offsets = ics->swb_offset;

    float *coef_base = coef;



    for (g = 0; g < ics->num_windows; g++)

        memset(coef + g * 128 + offsets[ics->max_sfb], 0, sizeof(float)*(c - offsets[ics->max_sfb]));



    for (g = 0; g < ics->num_window_groups; g++) {

        for (i = 0; i < ics->max_sfb; i++, idx++) {

            const int cur_band_type = band_type[idx];

            const int dim = cur_band_type >= FIRST_PAIR_BT ? 2 : 4;

            const int is_cb_unsigned = IS_CODEBOOK_UNSIGNED(cur_band_type);

            int group;

            if (cur_band_type == ZERO_BT) {

                for (group = 0; group < ics->group_len[g]; group++) {

                    memset(coef + group * 128 + offsets[i], 0, (offsets[i+1] - offsets[i])*sizeof(float));

                }

            }else if (cur_band_type == NOISE_BT) {

                const float scale = sf[idx] / ((offsets[i+1] - offsets[i]) * PNS_MEAN_ENERGY);

                for (group = 0; group < ics->group_len[g]; group++) {

                    for (k = offsets[i]; k < offsets[i+1]; k++) {

                        ac->random_state  = lcg_random(ac->random_state);

                        coef[group*128+k] = ac->random_state * scale;

                    }

                }

            }else if (cur_band_type != INTENSITY_BT2 && cur_band_type != INTENSITY_BT) {

                for (group = 0; group < ics->group_len[g]; group++) {

                    for (k = offsets[i]; k < offsets[i+1]; k += dim) {

                        const int index = get_vlc2(gb, vlc_spectral[cur_band_type - 1].table, 6, 3);

                        const int coef_tmp_idx = (group << 7) + k;

                        const float *vq_ptr;

                        int j;

                        if(index >= ff_aac_spectral_sizes[cur_band_type - 1]) {

                            av_log(ac->avccontext, AV_LOG_ERROR,

                                "Read beyond end of ff_aac_codebook_vectors[%d][]. index %d >= %d\n",

                                cur_band_type - 1, index, ff_aac_spectral_sizes[cur_band_type - 1]);

                            return -1;

                        }

                        vq_ptr = &ff_aac_codebook_vectors[cur_band_type - 1][index * dim];

                        if (is_cb_unsigned) {

                            for (j = 0; j < dim; j++)

                                if (vq_ptr[j])

                                    coef[coef_tmp_idx + j] = 1 - 2*(int)get_bits1(gb);

                        }else {

                            for (j = 0; j < dim; j++)

                                coef[coef_tmp_idx + j] = 1.0f;

                        }

                        if (cur_band_type == ESC_BT) {

                            for (j = 0; j < 2; j++) {

                                if (vq_ptr[j] == 64.0f) {

                                    int n = 4;

                                    /* The total length of escape_sequence must be < 22 bits according

                                       to the specification (i.e. max is 11111111110xxxxxxxxxx). */

                                    while (get_bits1(gb) && n < 15) n++;

                                    if(n == 15) {

                                        av_log(ac->avccontext, AV_LOG_ERROR, "error in spectral data, ESC overflow\n");

                                        return -1;

                                    }

                                    n = (1<<n) + get_bits(gb, n);

                                    coef[coef_tmp_idx + j] *= cbrtf(fabsf(n)) * n;

                                }else

                                    coef[coef_tmp_idx + j] *= vq_ptr[j];

                            }

                        }else

                            for (j = 0; j < dim; j++)

                                coef[coef_tmp_idx + j] *= vq_ptr[j];

                        for (j = 0; j < dim; j++)

                            coef[coef_tmp_idx + j] *= sf[idx];

                    }

                }

            }

        }

        coef += ics->group_len[g]<<7;

    }



    if (pulse_present) {

        for(i = 0; i < pulse->num_pulse; i++){

            float co  = coef_base[ pulse->pos[i] ];

            float ico = co / sqrtf(sqrtf(fabsf(co))) + pulse->amp[i];

            coef_base[ pulse->pos[i] ] = cbrtf(fabsf(ico)) * ico;

        }

    }

    return 0;

}

static uint32_t vmsvga_value_read(void *opaque, uint32_t address)

{

    uint32_t caps;

    struct vmsvga_state_s *s = opaque;

    switch (s->index) {

    case SVGA_REG_ID:

        return s->svgaid;



    case SVGA_REG_ENABLE:

        return s->enable;



    case SVGA_REG_WIDTH:

        return s->width;



    case SVGA_REG_HEIGHT:

        return s->height;



    case SVGA_REG_MAX_WIDTH:

        return SVGA_MAX_WIDTH;



    case SVGA_REG_MAX_HEIGHT:

        return SVGA_MAX_HEIGHT;



    case SVGA_REG_DEPTH:

        return s->depth;



    case SVGA_REG_BITS_PER_PIXEL:

        return (s->depth + 7) & ~7;



    case SVGA_REG_PSEUDOCOLOR:

        return 0x0;



    case SVGA_REG_RED_MASK:

        return s->wred;

    case SVGA_REG_GREEN_MASK:

        return s->wgreen;

    case SVGA_REG_BLUE_MASK:

        return s->wblue;



    case SVGA_REG_BYTES_PER_LINE:

        return ((s->depth + 7) >> 3) * s->new_width;



    case SVGA_REG_FB_START: {

        struct pci_vmsvga_state_s *pci_vmsvga

            = container_of(s, struct pci_vmsvga_state_s, chip);

        return pci_get_bar_addr(&pci_vmsvga->card, 1);

    }



    case SVGA_REG_FB_OFFSET:

        return 0x0;



    case SVGA_REG_VRAM_SIZE:

        return s->vga.vram_size;



    case SVGA_REG_FB_SIZE:

        return s->fb_size;



    case SVGA_REG_CAPABILITIES:

        caps = SVGA_CAP_NONE;

#ifdef HW_RECT_ACCEL

        caps |= SVGA_CAP_RECT_COPY;

#endif

#ifdef HW_FILL_ACCEL

        caps |= SVGA_CAP_RECT_FILL;

#endif

#ifdef HW_MOUSE_ACCEL

        if (dpy_cursor_define_supported(s->vga.ds)) {

            caps |= SVGA_CAP_CURSOR | SVGA_CAP_CURSOR_BYPASS_2 |

                    SVGA_CAP_CURSOR_BYPASS;

        }

#endif

        return caps;



    case SVGA_REG_MEM_START: {

        struct pci_vmsvga_state_s *pci_vmsvga

            = container_of(s, struct pci_vmsvga_state_s, chip);

        return pci_get_bar_addr(&pci_vmsvga->card, 2);

    }



    case SVGA_REG_MEM_SIZE:

        return s->fifo_size;



    case SVGA_REG_CONFIG_DONE:

        return s->config;



    case SVGA_REG_SYNC:

    case SVGA_REG_BUSY:

        return s->syncing;



    case SVGA_REG_GUEST_ID:

        return s->guest;



    case SVGA_REG_CURSOR_ID:

        return s->cursor.id;



    case SVGA_REG_CURSOR_X:

        return s->cursor.x;



    case SVGA_REG_CURSOR_Y:

        return s->cursor.x;



    case SVGA_REG_CURSOR_ON:

        return s->cursor.on;



    case SVGA_REG_HOST_BITS_PER_PIXEL:

        return (s->depth + 7) & ~7;



    case SVGA_REG_SCRATCH_SIZE:

        return s->scratch_size;



    case SVGA_REG_MEM_REGS:

    case SVGA_REG_NUM_DISPLAYS:

    case SVGA_REG_PITCHLOCK:

    case SVGA_PALETTE_BASE ... SVGA_PALETTE_END:

        return 0;



    default:

        if (s->index >= SVGA_SCRATCH_BASE &&

                s->index < SVGA_SCRATCH_BASE + s->scratch_size)

            return s->scratch[s->index - SVGA_SCRATCH_BASE];

        printf("%s: Bad register %02x\n", __FUNCTION__, s->index);

    }



    return 0;

}

