static int nbd_co_writev_1(NbdClientSession *client, int64_t sector_num,

                           int nb_sectors, QEMUIOVector *qiov,

                           int offset)

{

    struct nbd_request request = { .type = NBD_CMD_WRITE };

    struct nbd_reply reply;

    ssize_t ret;



    if (!bdrv_enable_write_cache(client->bs) &&

        (client->nbdflags & NBD_FLAG_SEND_FUA)) {

        request.type |= NBD_CMD_FLAG_FUA;

    }



    request.from = sector_num * 512;

    request.len = nb_sectors * 512;



    nbd_coroutine_start(client, &request);

    ret = nbd_co_send_request(client, &request, qiov, offset);

    if (ret < 0) {

        reply.error = -ret;

    } else {

        nbd_co_receive_reply(client, &request, &reply, NULL, 0);

    }

    nbd_coroutine_end(client, &request);

    return -reply.error;

}

static void decode_opc_special3(CPUMIPSState *env, DisasContext *ctx)

{

    int rs, rt, rd, sa;

    uint32_t op1, op2;



    rs = (ctx->opcode >> 21) & 0x1f;

    rt = (ctx->opcode >> 16) & 0x1f;

    rd = (ctx->opcode >> 11) & 0x1f;

    sa = (ctx->opcode >> 6) & 0x1f;



    op1 = MASK_SPECIAL3(ctx->opcode);

    switch (op1) {

    case OPC_EXT:

    case OPC_INS:

        check_insn(ctx, ISA_MIPS32R2);

        gen_bitops(ctx, op1, rt, rs, sa, rd);

        break;

    case OPC_BSHFL:

        op2 = MASK_BSHFL(ctx->opcode);

        switch (op2) {

        case OPC_ALIGN ... OPC_ALIGN_END:

        case OPC_BITSWAP:

            check_insn(ctx, ISA_MIPS32R6);

            decode_opc_special3_r6(env, ctx);

            break;

        default:

            check_insn(ctx, ISA_MIPS32R2);

            gen_bshfl(ctx, op2, rt, rd);

            break;

        }

        break;

#if defined(TARGET_MIPS64)

    case OPC_DEXTM ... OPC_DEXT:

    case OPC_DINSM ... OPC_DINS:

        check_insn(ctx, ISA_MIPS64R2);

        check_mips_64(ctx);

        gen_bitops(ctx, op1, rt, rs, sa, rd);

        break;

    case OPC_DBSHFL:

        op2 = MASK_DBSHFL(ctx->opcode);

        switch (op2) {

        case OPC_DALIGN ... OPC_DALIGN_END:

        case OPC_DBITSWAP:

            check_insn(ctx, ISA_MIPS32R6);

            decode_opc_special3_r6(env, ctx);

            break;

        default:

            check_insn(ctx, ISA_MIPS64R2);

            check_mips_64(ctx);

            op2 = MASK_DBSHFL(ctx->opcode);

            gen_bshfl(ctx, op2, rt, rd);

            break;

        }

        break;

#endif

    case OPC_RDHWR:

        gen_rdhwr(ctx, rt, rd);

        break;

    case OPC_FORK:

        check_insn(ctx, ASE_MT);

        {

            TCGv t0 = tcg_temp_new();

            TCGv t1 = tcg_temp_new();



            gen_load_gpr(t0, rt);

            gen_load_gpr(t1, rs);

            gen_helper_fork(t0, t1);

            tcg_temp_free(t0);

            tcg_temp_free(t1);

        }

        break;

    case OPC_YIELD:

        check_insn(ctx, ASE_MT);

        {

            TCGv t0 = tcg_temp_new();



            gen_load_gpr(t0, rs);

            gen_helper_yield(t0, cpu_env, t0);

            gen_store_gpr(t0, rd);

            tcg_temp_free(t0);

        }

        break;

    default:

        if (ctx->insn_flags & ISA_MIPS32R6) {

            decode_opc_special3_r6(env, ctx);

        } else {

            decode_opc_special3_legacy(env, ctx);

        }

    }

}

static int applehttp_open(URLContext *h, const char *uri, int flags)

{

    AppleHTTPContext *s;

    int ret, i;

    const char *nested_url;



    if (flags & AVIO_FLAG_WRITE)

        return AVERROR(ENOSYS);



    s = av_mallocz(sizeof(AppleHTTPContext));

    if (!s)

        return AVERROR(ENOMEM);

    h->priv_data = s;

    h->is_streamed = 1;



    if (av_strstart(uri, "applehttp+", &nested_url)) {

        av_strlcpy(s->playlisturl, nested_url, sizeof(s->playlisturl));

    } else if (av_strstart(uri, "applehttp://", &nested_url)) {

        av_strlcpy(s->playlisturl, "http://", sizeof(s->playlisturl));

        av_strlcat(s->playlisturl, nested_url, sizeof(s->playlisturl));

    } else {

        av_log(h, AV_LOG_ERROR, "Unsupported url %s\n", uri);

        ret = AVERROR(EINVAL);

        goto fail;

    }



    if ((ret = parse_playlist(h, s->playlisturl)) < 0)

        goto fail;



    if (s->n_segments == 0 && s->n_variants > 0) {

        int max_bandwidth = 0, maxvar = -1;

        for (i = 0; i < s->n_variants; i++) {

            if (s->variants[i]->bandwidth > max_bandwidth || i == 0) {

                max_bandwidth = s->variants[i]->bandwidth;

                maxvar = i;

            }

        }

        av_strlcpy(s->playlisturl, s->variants[maxvar]->url,

                   sizeof(s->playlisturl));

        if ((ret = parse_playlist(h, s->playlisturl)) < 0)

            goto fail;

    }



    if (s->n_segments == 0) {

        av_log(h, AV_LOG_WARNING, "Empty playlist\n");

        ret = AVERROR(EIO);

        goto fail;

    }

    s->cur_seq_no = s->start_seq_no;

    if (!s->finished && s->n_segments >= 3)

        s->cur_seq_no = s->start_seq_no + s->n_segments - 3;



    return 0;



fail:

    av_free(s);

    return ret;

}

