static void mpic_reset (void *opaque)

{

    openpic_t *mpp = (openpic_t *)opaque;

    int i;



    mpp->glbc = 0x80000000;

    /* Initialise controller registers */

    mpp->frep = 0x004f0002;

    mpp->veni = VENI;

    mpp->pint = 0x00000000;

    mpp->spve = 0x0000FFFF;

    /* Initialise IRQ sources */

    for (i = 0; i < mpp->max_irq; i++) {

        mpp->src[i].ipvp = 0x80800000;

        mpp->src[i].ide  = 0x00000001;

    }

    /* Set IDE for IPIs to 0 so we don't get spurious interrupts */

    for (i = mpp->irq_ipi0; i < (mpp->irq_ipi0 + MAX_IPI); i++) {

        mpp->src[i].ide = 0;

    }

    /* Initialise IRQ destinations */

    for (i = 0; i < MAX_CPU; i++) {

        mpp->dst[i].pctp      = 0x0000000F;

        mpp->dst[i].tfrr      = 0x00000000;

        memset(&mpp->dst[i].raised, 0, sizeof(IRQ_queue_t));

        mpp->dst[i].raised.next = -1;

        memset(&mpp->dst[i].servicing, 0, sizeof(IRQ_queue_t));

        mpp->dst[i].servicing.next = -1;

    }

    /* Initialise timers */

    for (i = 0; i < MAX_TMR; i++) {

        mpp->timers[i].ticc = 0x00000000;

        mpp->timers[i].tibc = 0x80000000;

    }

    /* Go out of RESET state */

    mpp->glbc = 0x00000000;

}

static av_cold int libspeex_decode_init(AVCodecContext *avctx)

{

    LibSpeexContext *s = avctx->priv_data;

    const SpeexMode *mode;



    // defaults in the case of a missing header

    if (avctx->sample_rate <= 8000)

        mode = &speex_nb_mode;

    else if (avctx->sample_rate <= 16000)

        mode = &speex_wb_mode;

    else

        mode = &speex_uwb_mode;



    if (avctx->extradata_size >= 80)

        s->header = speex_packet_to_header(avctx->extradata, avctx->extradata_size);



    avctx->sample_fmt = AV_SAMPLE_FMT_S16;

    if (s->header) {

        avctx->sample_rate = s->header->rate;

        avctx->channels    = s->header->nb_channels;

        s->frame_size      = s->header->frame_size;



        mode = speex_lib_get_mode(s->header->mode);

        if (!mode) {

            av_log(avctx, AV_LOG_ERROR, "Unknown Speex mode %d", s->header->mode);

            return AVERROR_INVALIDDATA;

        }

    } else

        av_log(avctx, AV_LOG_INFO, "Missing Speex header, assuming defaults.\n");



    if (avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "Only stereo and mono are supported.\n");

        return AVERROR(EINVAL);

    }



    speex_bits_init(&s->bits);

    s->dec_state = speex_decoder_init(mode);

    if (!s->dec_state) {

        av_log(avctx, AV_LOG_ERROR, "Error initializing libspeex decoder.\n");

        return -1;

    }



    if (!s->header) {

        speex_decoder_ctl(s->dec_state, SPEEX_GET_FRAME_SIZE, &s->frame_size);

    }



    if (avctx->channels == 2) {

        SpeexCallback callback;

        callback.callback_id = SPEEX_INBAND_STEREO;

        callback.func = speex_std_stereo_request_handler;

        callback.data = &s->stereo;

        s->stereo = (SpeexStereoState)SPEEX_STEREO_STATE_INIT;

        speex_decoder_ctl(s->dec_state, SPEEX_SET_HANDLER, &callback);

    }



    avcodec_get_frame_defaults(&s->frame);

    avctx->coded_frame = &s->frame;



    return 0;

}

static int create_header64(DumpState *s)

{

    int ret = 0;

    DiskDumpHeader64 *dh = NULL;

    KdumpSubHeader64 *kh = NULL;

    size_t size;

    int endian = s->dump_info.d_endian;

    uint32_t block_size;

    uint32_t sub_hdr_size;

    uint32_t bitmap_blocks;

    uint32_t status = 0;

    uint64_t offset_note;



    /* write common header, the version of kdump-compressed format is 6th */

    size = sizeof(DiskDumpHeader64);

    dh = g_malloc0(size);



    strncpy(dh->signature, KDUMP_SIGNATURE, strlen(KDUMP_SIGNATURE));

    dh->header_version = cpu_convert_to_target32(6, endian);

    block_size = s->page_size;

    dh->block_size = cpu_convert_to_target32(block_size, endian);

    sub_hdr_size = sizeof(struct KdumpSubHeader64) + s->note_size;

    sub_hdr_size = DIV_ROUND_UP(sub_hdr_size, block_size);

    dh->sub_hdr_size = cpu_convert_to_target32(sub_hdr_size, endian);

    /* dh->max_mapnr may be truncated, full 64bit is in kh.max_mapnr_64 */

    dh->max_mapnr = cpu_convert_to_target32(MIN(s->max_mapnr, UINT_MAX),

                                            endian);

    dh->nr_cpus = cpu_convert_to_target32(s->nr_cpus, endian);

    bitmap_blocks = DIV_ROUND_UP(s->len_dump_bitmap, block_size) * 2;

    dh->bitmap_blocks = cpu_convert_to_target32(bitmap_blocks, endian);

    strncpy(dh->utsname.machine, ELF_MACHINE_UNAME, sizeof(dh->utsname.machine));



    if (s->flag_compress & DUMP_DH_COMPRESSED_ZLIB) {

        status |= DUMP_DH_COMPRESSED_ZLIB;

    }

#ifdef CONFIG_LZO

    if (s->flag_compress & DUMP_DH_COMPRESSED_LZO) {

        status |= DUMP_DH_COMPRESSED_LZO;

    }

#endif

#ifdef CONFIG_SNAPPY

    if (s->flag_compress & DUMP_DH_COMPRESSED_SNAPPY) {

        status |= DUMP_DH_COMPRESSED_SNAPPY;

    }

#endif

    dh->status = cpu_convert_to_target32(status, endian);



    if (write_buffer(s->fd, 0, dh, size) < 0) {

        dump_error(s, "dump: failed to write disk dump header.\n");

        ret = -1;

        goto out;

    }



    /* write sub header */

    size = sizeof(KdumpSubHeader64);

    kh = g_malloc0(size);



    /* 64bit max_mapnr_64 */

    kh->max_mapnr_64 = cpu_convert_to_target64(s->max_mapnr, endian);

    kh->phys_base = cpu_convert_to_target64(PHYS_BASE, endian);

    kh->dump_level = cpu_convert_to_target32(DUMP_LEVEL, endian);



    offset_note = DISKDUMP_HEADER_BLOCKS * block_size + size;

    kh->offset_note = cpu_convert_to_target64(offset_note, endian);

    kh->note_size = cpu_convert_to_target64(s->note_size, endian);



    if (write_buffer(s->fd, DISKDUMP_HEADER_BLOCKS *

                     block_size, kh, size) < 0) {

        dump_error(s, "dump: failed to write kdump sub header.\n");

        ret = -1;

        goto out;

    }



    /* write note */

    s->note_buf = g_malloc0(s->note_size);

    s->note_buf_offset = 0;



    /* use s->note_buf to store notes temporarily */

    if (write_elf64_notes(buf_write_note, s) < 0) {

        ret = -1;

        goto out;

    }



    if (write_buffer(s->fd, offset_note, s->note_buf,

                     s->note_size) < 0) {

        dump_error(s, "dump: failed to write notes");

        ret = -1;

        goto out;

    }



    /* get offset of dump_bitmap */

    s->offset_dump_bitmap = (DISKDUMP_HEADER_BLOCKS + sub_hdr_size) *

                             block_size;



    /* get offset of page */

    s->offset_page = (DISKDUMP_HEADER_BLOCKS + sub_hdr_size + bitmap_blocks) *

                     block_size;



out:

    g_free(dh);

    g_free(kh);

    g_free(s->note_buf);



    return ret;

}

void tlb_set_page(CPUArchState *env, target_ulong vaddr,

                  target_phys_addr_t paddr, int prot,

                  int mmu_idx, target_ulong size)

{

    MemoryRegionSection *section;

    unsigned int index;

    target_ulong address;

    target_ulong code_address;

    uintptr_t addend;

    CPUTLBEntry *te;

    target_phys_addr_t iotlb;



    assert(size >= TARGET_PAGE_SIZE);

    if (size != TARGET_PAGE_SIZE) {

        tlb_add_large_page(env, vaddr, size);

    }

    section = phys_page_find(paddr >> TARGET_PAGE_BITS);

#if defined(DEBUG_TLB)

    printf("tlb_set_page: vaddr=" TARGET_FMT_lx " paddr=0x" TARGET_FMT_plx

           " prot=%x idx=%d pd=0x%08lx\n",

           vaddr, paddr, prot, mmu_idx, pd);

#endif



    address = vaddr;

    if (!(memory_region_is_ram(section->mr) ||

          memory_region_is_romd(section->mr))) {

        /* IO memory case (romd handled later) */

        address |= TLB_MMIO;

    }

    if (memory_region_is_ram(section->mr) ||

        memory_region_is_romd(section->mr)) {

        addend = (uintptr_t)memory_region_get_ram_ptr(section->mr)

        + memory_region_section_addr(section, paddr);

    } else {

        addend = 0;

    }



    code_address = address;

    iotlb = memory_region_section_get_iotlb(env, section, vaddr, paddr, prot,

                                            &address);



    index = (vaddr >> TARGET_PAGE_BITS) & (CPU_TLB_SIZE - 1);

    env->iotlb[mmu_idx][index] = iotlb - vaddr;

    te = &env->tlb_table[mmu_idx][index];

    te->addend = addend - vaddr;

    if (prot & PAGE_READ) {

        te->addr_read = address;

    } else {

        te->addr_read = -1;

    }



    if (prot & PAGE_EXEC) {

        te->addr_code = code_address;

    } else {

        te->addr_code = -1;

    }

    if (prot & PAGE_WRITE) {

        if ((memory_region_is_ram(section->mr) && section->readonly)

            || memory_region_is_romd(section->mr)) {

            /* Write access calls the I/O callback.  */

            te->addr_write = address | TLB_MMIO;

        } else if (memory_region_is_ram(section->mr)

                   && !cpu_physical_memory_is_dirty(

                           section->mr->ram_addr

                           + memory_region_section_addr(section, paddr))) {

            te->addr_write = address | TLB_NOTDIRTY;

        } else {

            te->addr_write = address;

        }

    } else {

        te->addr_write = -1;

    }

}

static int update_wrap_reference(AVFormatContext *s, AVStream *st, int stream_index, AVPacket *pkt)

{

    int64_t ref = pkt->dts;



    if (ref == AV_NOPTS_VALUE)

        ref = pkt->pts;

    if (ref == AV_NOPTS_VALUE)

        return 0;

    ref &= (1LL<<st->pts_wrap_bits)-1;



    if (s->correct_ts_overflow && st->pts_wrap_bits < 63 &&

        st->pts_wrap_reference == AV_NOPTS_VALUE) {

        int i;



        // reference time stamp should be 60 s before first time stamp

        int64_t pts_wrap_reference = ref - av_rescale(60, st->time_base.den, st->time_base.num);

        // if first time stamp is not more than 1/8 and 60s before the wrap point, subtract rather than add wrap offset

        int pts_wrap_behavior = (ref < (1LL<<st->pts_wrap_bits) - (1LL<<st->pts_wrap_bits-3)) ||

            (ref < (1LL<<st->pts_wrap_bits) - av_rescale(60, st->time_base.den, st->time_base.num)) ?

            AV_PTS_WRAP_ADD_OFFSET : AV_PTS_WRAP_SUB_OFFSET;



        AVProgram *first_program = av_find_program_from_stream(s, NULL, stream_index);



        if (!first_program) {

            int default_stream_index = av_find_default_stream_index(s);

            if (s->streams[default_stream_index]->pts_wrap_reference == AV_NOPTS_VALUE) {

                for (i=0; i<s->nb_streams; i++) {

                    s->streams[i]->pts_wrap_reference = pts_wrap_reference;

                    s->streams[i]->pts_wrap_behavior = pts_wrap_behavior;

                }

            }

            else {

                st->pts_wrap_reference = s->streams[default_stream_index]->pts_wrap_reference;

                st->pts_wrap_behavior = s->streams[default_stream_index]->pts_wrap_behavior;

            }

        }

        else {

            AVProgram *program = first_program;

            while (program) {

                if (program->pts_wrap_reference != AV_NOPTS_VALUE) {

                    pts_wrap_reference = program->pts_wrap_reference;

                    pts_wrap_behavior = program->pts_wrap_behavior;

                    break;

                }

                program = av_find_program_from_stream(s, program, stream_index);

            }



            // update every program with differing pts_wrap_reference

            program = first_program;

            while(program) {

                if (program->pts_wrap_reference != pts_wrap_reference) {

                    for (i=0; i<program->nb_stream_indexes; i++) {

                        s->streams[program->stream_index[i]]->pts_wrap_reference = pts_wrap_reference;

                        s->streams[program->stream_index[i]]->pts_wrap_behavior = pts_wrap_behavior;

                    }



                    program->pts_wrap_reference = pts_wrap_reference;

                    program->pts_wrap_behavior = pts_wrap_behavior;

                }

                program = av_find_program_from_stream(s, program, stream_index);

            }

        }

        return 1;

    }

    return 0;

}

