static int dvbsub_parse_clut_segment(AVCodecContext *avctx,

                                     const uint8_t *buf, int buf_size)

{

    DVBSubContext *ctx = avctx->priv_data;



    const uint8_t *buf_end = buf + buf_size;

    int i, clut_id;

    int version;

    DVBSubCLUT *clut;

    int entry_id, depth , full_range;

    int y, cr, cb, alpha;

    int r, g, b, r_add, g_add, b_add;



    ff_dlog(avctx, "DVB clut packet:\n");



    for (i=0; i < buf_size; i++) {

        ff_dlog(avctx, "%02x ", buf[i]);

        if (i % 16 == 15)

            ff_dlog(avctx, "\n");

    }



    if (i % 16)

        ff_dlog(avctx, "\n");



    clut_id = *buf++;

    version = ((*buf)>>4)&15;

    buf += 1;



    clut = get_clut(ctx, clut_id);



    if (!clut) {

        clut = av_malloc(sizeof(DVBSubCLUT));

        if (!clut)

            return AVERROR(ENOMEM);



        memcpy(clut, &default_clut, sizeof(DVBSubCLUT));



        clut->id = clut_id;

        clut->version = -1;



        clut->next = ctx->clut_list;

        ctx->clut_list = clut;

    }



    if (clut->version != version) {



    clut->version = version;



    while (buf + 4 < buf_end) {

        entry_id = *buf++;



        depth = (*buf) & 0xe0;



        if (depth == 0) {

            av_log(avctx, AV_LOG_ERROR, "Invalid clut depth 0x%x!\n", *buf);

        }



        full_range = (*buf++) & 1;



        if (full_range) {

            y = *buf++;

            cr = *buf++;

            cb = *buf++;

            alpha = *buf++;

        } else {

            y = buf[0] & 0xfc;

            cr = (((buf[0] & 3) << 2) | ((buf[1] >> 6) & 3)) << 4;

            cb = (buf[1] << 2) & 0xf0;

            alpha = (buf[1] << 6) & 0xc0;



            buf += 2;

        }



        if (y == 0)

            alpha = 0xff;



        YUV_TO_RGB1_CCIR(cb, cr);

        YUV_TO_RGB2_CCIR(r, g, b, y);



        ff_dlog(avctx, "clut %d := (%d,%d,%d,%d)\n", entry_id, r, g, b, alpha);

        if (!!(depth & 0x80) + !!(depth & 0x40) + !!(depth & 0x20) > 1) {

            ff_dlog(avctx, "More than one bit level marked: %x\n", depth);

            if (avctx->strict_std_compliance > FF_COMPLIANCE_NORMAL)

                return AVERROR_INVALIDDATA;

        }



        if (depth & 0x80)

            clut->clut4[entry_id] = RGBA(r,g,b,255 - alpha);

        else if (depth & 0x40)

            clut->clut16[entry_id] = RGBA(r,g,b,255 - alpha);

        else if (depth & 0x20)

            clut->clut256[entry_id] = RGBA(r,g,b,255 - alpha);

    }

    }



    return 0;

}

static int img_map(int argc, char **argv)

{

    int c;

    OutputFormat output_format = OFORMAT_HUMAN;

    BlockBackend *blk;

    BlockDriverState *bs;

    const char *filename, *fmt, *output;

    int64_t length;

    MapEntry curr = { .length = 0 }, next;

    int ret = 0;

    bool image_opts = false;



    fmt = NULL;

    output = NULL;

    for (;;) {

        int option_index = 0;

        static const struct option long_options[] = {

            {"help", no_argument, 0, 'h'},

            {"format", required_argument, 0, 'f'},

            {"output", required_argument, 0, OPTION_OUTPUT},

            {"object", required_argument, 0, OPTION_OBJECT},

            {"image-opts", no_argument, 0, OPTION_IMAGE_OPTS},

            {0, 0, 0, 0}

        };

        c = getopt_long(argc, argv, "f:h",

                        long_options, &option_index);

        if (c == -1) {

            break;

        }

        switch (c) {

        case '?':

        case 'h':

            help();

            break;

        case 'f':

            fmt = optarg;

            break;

        case OPTION_OUTPUT:

            output = optarg;

            break;

        case OPTION_OBJECT: {

            QemuOpts *opts;

            opts = qemu_opts_parse_noisily(&qemu_object_opts,

                                           optarg, true);

            if (!opts) {

                return 1;

            }

        }   break;

        case OPTION_IMAGE_OPTS:

            image_opts = true;

            break;

        }

    }

    if (optind != argc - 1) {

        error_exit("Expecting one image file name");

    }

    filename = argv[optind];



    if (output && !strcmp(output, "json")) {

        output_format = OFORMAT_JSON;

    } else if (output && !strcmp(output, "human")) {

        output_format = OFORMAT_HUMAN;

    } else if (output) {

        error_report("--output must be used with human or json as argument.");

        return 1;

    }



    if (qemu_opts_foreach(&qemu_object_opts,

                          user_creatable_add_opts_foreach,

                          NULL, NULL)) {

        return 1;

    }



    blk = img_open(image_opts, filename, fmt, 0, false, false);

    if (!blk) {

        return 1;

    }

    bs = blk_bs(blk);



    if (output_format == OFORMAT_HUMAN) {

        printf("%-16s%-16s%-16s%s\n", "Offset", "Length", "Mapped to", "File");

    }



    length = blk_getlength(blk);

    while (curr.start + curr.length < length) {

        int64_t nsectors_left;

        int64_t sector_num;

        int n;



        sector_num = (curr.start + curr.length) >> BDRV_SECTOR_BITS;



        /* Probe up to 1 GiB at a time.  */

        nsectors_left = DIV_ROUND_UP(length, BDRV_SECTOR_SIZE) - sector_num;

        n = MIN(1 << (30 - BDRV_SECTOR_BITS), nsectors_left);

        ret = get_block_status(bs, sector_num, n, &next);



        if (ret < 0) {

            error_report("Could not read file metadata: %s", strerror(-ret));

            goto out;

        }



        if (entry_mergeable(&curr, &next)) {

            curr.length += next.length;

            continue;

        }



        if (curr.length > 0) {

            dump_map_entry(output_format, &curr, &next);

        }

        curr = next;

    }



    dump_map_entry(output_format, &curr, NULL);



out:

    blk_unref(blk);

    return ret < 0;

}

static int decode_cabac_mb_skip( H264Context *h, int mb_x, int mb_y ) {

    MpegEncContext * const s = &h->s;

    int mba_xy, mbb_xy;

    int ctx = 0;



    if(FRAME_MBAFF){ //FIXME merge with the stuff in fill_caches?

        int mb_xy = mb_x + (mb_y&~1)*s->mb_stride;

        mba_xy = mb_xy - 1;

        if( (mb_y&1)

            && h->slice_table[mba_xy] == h->slice_num

            && MB_FIELD == !!IS_INTERLACED( s->current_picture.mb_type[mba_xy] ) )

            mba_xy += s->mb_stride;

        if( MB_FIELD ){

            mbb_xy = mb_xy - s->mb_stride;

            if( !(mb_y&1)

                && h->slice_table[mbb_xy] == h->slice_num

                && IS_INTERLACED( s->current_picture.mb_type[mbb_xy] ) )

                mbb_xy -= s->mb_stride;

        }else

            mbb_xy = mb_x + (mb_y-1)*s->mb_stride;

    }else{

        int mb_xy = mb_x + mb_y*s->mb_stride;

        mba_xy = mb_xy - 1;

        mbb_xy = mb_xy - s->mb_stride;

    }



    if( h->slice_table[mba_xy] == h->slice_num && !IS_SKIP( s->current_picture.mb_type[mba_xy] ))

        ctx++;

    if( h->slice_table[mbb_xy] == h->slice_num && !IS_SKIP( s->current_picture.mb_type[mbb_xy] ))

        ctx++;



    if( h->slice_type == B_TYPE )

        ctx += 13;

    return get_cabac( &h->cabac, &h->cabac_state[11+ctx] );

}

static int nbd_co_send_request(BlockDriverState *bs,

                               struct nbd_request *request,

                               QEMUIOVector *qiov, int offset)

{

    NbdClientSession *s = nbd_get_client_session(bs);

    AioContext *aio_context;

    int rc, ret;



    qemu_co_mutex_lock(&s->send_mutex);

    s->send_coroutine = qemu_coroutine_self();

    aio_context = bdrv_get_aio_context(bs);

    aio_set_fd_handler(aio_context, s->sock,

                       nbd_reply_ready, nbd_restart_write, bs);

    if (qiov) {

        if (!s->is_unix) {

            socket_set_cork(s->sock, 1);

        }

        rc = nbd_send_request(s->sock, request);

        if (rc >= 0) {

            ret = qemu_co_sendv(s->sock, qiov->iov, qiov->niov,

                                offset, request->len);

            if (ret != request->len) {

                rc = -EIO;

            }

        }

        if (!s->is_unix) {

            socket_set_cork(s->sock, 0);

        }

    } else {

        rc = nbd_send_request(s->sock, request);

    }

    aio_set_fd_handler(aio_context, s->sock, nbd_reply_ready, NULL, bs);

    s->send_coroutine = NULL;

    qemu_co_mutex_unlock(&s->send_mutex);

    return rc;

}

static void print_block_info(Monitor *mon, BlockInfo *info,

                             BlockDeviceInfo *inserted, bool verbose)

{

    ImageInfo *image_info;



    assert(!info || !info->has_inserted || info->inserted == inserted);



    if (info) {

        monitor_printf(mon, "%s", info->device);

        if (inserted && inserted->has_node_name) {

            monitor_printf(mon, " (%s)", inserted->node_name);

        }

    } else {

        assert(inserted);

        monitor_printf(mon, "%s",

                       inserted->has_node_name

                       ? inserted->node_name

                       : "<anonymous>");

    }



    if (inserted) {

        monitor_printf(mon, ": %s (%s%s%s)\n",

                       inserted->file,

                       inserted->drv,

                       inserted->ro ? ", read-only" : "",

                       inserted->encrypted ? ", encrypted" : "");

    } else {

        monitor_printf(mon, ": [not inserted]\n");

    }



    if (info) {

        if (info->has_io_status && info->io_status != BLOCK_DEVICE_IO_STATUS_OK) {

            monitor_printf(mon, "    I/O status:       %s\n",

                           BlockDeviceIoStatus_lookup[info->io_status]);

        }



        if (info->removable) {

            monitor_printf(mon, "    Removable device: %slocked, tray %s\n",

                           info->locked ? "" : "not ",

                           info->tray_open ? "open" : "closed");

        }

    }





    if (!inserted) {

        return;

    }



    monitor_printf(mon, "    Cache mode:       %s%s%s\n",

                   inserted->cache->writeback ? "writeback" : "writethrough",

                   inserted->cache->direct ? ", direct" : "",

                   inserted->cache->no_flush ? ", ignore flushes" : "");



    if (inserted->has_backing_file) {

        monitor_printf(mon,

                       "    Backing file:     %s "

                       "(chain depth: %" PRId64 ")\n",

                       inserted->backing_file,

                       inserted->backing_file_depth);

    }



    if (inserted->detect_zeroes != BLOCKDEV_DETECT_ZEROES_OPTIONS_OFF) {

        monitor_printf(mon, "    Detect zeroes:    %s\n",

                       BlockdevDetectZeroesOptions_lookup[inserted->detect_zeroes]);

    }



    if (inserted->bps  || inserted->bps_rd  || inserted->bps_wr  ||

        inserted->iops || inserted->iops_rd || inserted->iops_wr)

    {

        monitor_printf(mon, "    I/O throttling:   bps=%" PRId64

                        " bps_rd=%" PRId64  " bps_wr=%" PRId64

                        " bps_max=%" PRId64

                        " bps_rd_max=%" PRId64

                        " bps_wr_max=%" PRId64

                        " iops=%" PRId64 " iops_rd=%" PRId64

                        " iops_wr=%" PRId64

                        " iops_max=%" PRId64

                        " iops_rd_max=%" PRId64

                        " iops_wr_max=%" PRId64

                        " iops_size=%" PRId64 "\n",

                        inserted->bps,

                        inserted->bps_rd,

                        inserted->bps_wr,

                        inserted->bps_max,

                        inserted->bps_rd_max,

                        inserted->bps_wr_max,

                        inserted->iops,

                        inserted->iops_rd,

                        inserted->iops_wr,

                        inserted->iops_max,

                        inserted->iops_rd_max,

                        inserted->iops_wr_max,

                        inserted->iops_size);

    }



    /* TODO: inserted->image should never be null */

    if (verbose && inserted->image) {

        monitor_printf(mon, "\nImages:\n");

        image_info = inserted->image;

        while (1) {

                bdrv_image_info_dump((fprintf_function)monitor_printf,

                                     mon, image_info);

            if (image_info->has_backing_image) {

                image_info = image_info->backing_image;

            } else {

                break;

            }

        }

    }

}

static void qemu_tcg_wait_io_event(CPUState *cpu)

{

    while (all_cpu_threads_idle()) {

        stop_tcg_kick_timer();

        qemu_cond_wait(cpu->halt_cond, &qemu_global_mutex);

    }



    start_tcg_kick_timer();



    CPU_FOREACH(cpu) {

        qemu_wait_io_event_common(cpu);

    }

}

static TileExcp gen_rr_opcode(DisasContext *dc, unsigned opext,

                              unsigned dest, unsigned srca)

{

    TCGv tdest, tsrca;

    const char *mnemonic;

    TCGMemOp memop;

    TileExcp ret = TILEGX_EXCP_NONE;



    /* Eliminate instructions with no output before doing anything else.  */

    switch (opext) {

    case OE_RR_Y0(NOP):

    case OE_RR_Y1(NOP):

    case OE_RR_X0(NOP):

    case OE_RR_X1(NOP):

        mnemonic = "nop";

        goto done0;

    case OE_RR_Y0(FNOP):

    case OE_RR_Y1(FNOP):

    case OE_RR_X0(FNOP):

    case OE_RR_X1(FNOP):

        mnemonic = "fnop";

        goto done0;

    case OE_RR_X1(DRAIN):

        mnemonic = "drain";

        goto done0;

    case OE_RR_X1(FLUSHWB):

        mnemonic = "flushwb";

        goto done0;

    case OE_RR_X1(ILL):

        if (dest == 0x1c && srca == 0x25) {

            mnemonic = "bpt";

            goto done2;

        }

        /* Fall through */

    case OE_RR_Y1(ILL):

        mnemonic = "ill";

    done2:

        qemu_log_mask(CPU_LOG_TB_IN_ASM, "%s", mnemonic);

        return TILEGX_EXCP_OPCODE_UNKNOWN;

    case OE_RR_X1(MF):

        mnemonic = "mf";

        goto done0;

    case OE_RR_X1(NAP):

        /* ??? This should yield, especially in system mode.  */

        mnemonic = "nap";

        goto done0;

    case OE_RR_X1(SWINT0):

    case OE_RR_X1(SWINT2):

    case OE_RR_X1(SWINT3):

        return TILEGX_EXCP_OPCODE_UNIMPLEMENTED;

    case OE_RR_X1(SWINT1):

        ret = TILEGX_EXCP_SYSCALL;

        mnemonic = "swint1";

    done0:

        if (srca || dest) {

            return TILEGX_EXCP_OPCODE_UNIMPLEMENTED;

        }

        qemu_log_mask(CPU_LOG_TB_IN_ASM, "%s", mnemonic);

        return ret;



    case OE_RR_X1(DTLBPR):

        return TILEGX_EXCP_OPCODE_UNIMPLEMENTED;

    case OE_RR_X1(FINV):

        mnemonic = "finv";

        goto done1;

    case OE_RR_X1(FLUSH):

        mnemonic = "flush";

        goto done1;

    case OE_RR_X1(ICOH):

        mnemonic = "icoh";

        goto done1;

    case OE_RR_X1(INV):

        mnemonic = "inv";

        goto done1;

    case OE_RR_X1(WH64):

        mnemonic = "wh64";

        goto done1;

    case OE_RR_X1(JRP):

    case OE_RR_Y1(JRP):

        mnemonic = "jrp";

        goto do_jr;

    case OE_RR_X1(JR):

    case OE_RR_Y1(JR):

        mnemonic = "jr";

        goto do_jr;

    case OE_RR_X1(JALRP):

    case OE_RR_Y1(JALRP):

        mnemonic = "jalrp";

        goto do_jalr;

    case OE_RR_X1(JALR):

    case OE_RR_Y1(JALR):

        mnemonic = "jalr";

    do_jalr:

        tcg_gen_movi_tl(dest_gr(dc, TILEGX_R_LR),

                        dc->pc + TILEGX_BUNDLE_SIZE_IN_BYTES);

    do_jr:

        dc->jmp.cond = TCG_COND_ALWAYS;

        dc->jmp.dest = tcg_temp_new();

        tcg_gen_andi_tl(dc->jmp.dest, load_gr(dc, srca), ~7);

    done1:

        if (dest) {

            return TILEGX_EXCP_OPCODE_UNIMPLEMENTED;

        }

        qemu_log_mask(CPU_LOG_TB_IN_ASM, "%s %s", mnemonic, reg_names[srca]);

        return ret;

    }



    tdest = dest_gr(dc, dest);

    tsrca = load_gr(dc, srca);



    switch (opext) {

    case OE_RR_X0(CNTLZ):

    case OE_RR_Y0(CNTLZ):

        gen_helper_cntlz(tdest, tsrca);

        mnemonic = "cntlz";

        break;

    case OE_RR_X0(CNTTZ):

    case OE_RR_Y0(CNTTZ):

        gen_helper_cnttz(tdest, tsrca);

        mnemonic = "cnttz";

        break;

    case OE_RR_X0(FSINGLE_PACK1):

    case OE_RR_Y0(FSINGLE_PACK1):

    case OE_RR_X1(IRET):

        return TILEGX_EXCP_OPCODE_UNIMPLEMENTED;

    case OE_RR_X1(LD1S):

        memop = MO_SB;

        mnemonic = "ld1s";

        goto do_load;

    case OE_RR_X1(LD1U):

        memop = MO_UB;

        mnemonic = "ld1u";

        goto do_load;

    case OE_RR_X1(LD2S):

        memop = MO_TESW;

        mnemonic = "ld2s";

        goto do_load;

    case OE_RR_X1(LD2U):

        memop = MO_TEUW;

        mnemonic = "ld2u";

        goto do_load;

    case OE_RR_X1(LD4S):

        memop = MO_TESL;

        mnemonic = "ld4s";

        goto do_load;

    case OE_RR_X1(LD4U):

        memop = MO_TEUL;

        mnemonic = "ld4u";

        goto do_load;

    case OE_RR_X1(LDNT1S):

        memop = MO_SB;

        mnemonic = "ldnt1s";

        goto do_load;

    case OE_RR_X1(LDNT1U):

        memop = MO_UB;

        mnemonic = "ldnt1u";

        goto do_load;

    case OE_RR_X1(LDNT2S):

        memop = MO_TESW;

        mnemonic = "ldnt2s";

        goto do_load;

    case OE_RR_X1(LDNT2U):

        memop = MO_TEUW;

        mnemonic = "ldnt2u";

        goto do_load;

    case OE_RR_X1(LDNT4S):

        memop = MO_TESL;

        mnemonic = "ldnt4s";

        goto do_load;

    case OE_RR_X1(LDNT4U):

        memop = MO_TEUL;

        mnemonic = "ldnt4u";

        goto do_load;

    case OE_RR_X1(LDNT):

        memop = MO_TEQ;

        mnemonic = "ldnt";

        goto do_load;

    case OE_RR_X1(LD):

        memop = MO_TEQ;

        mnemonic = "ld";

    do_load:

        tcg_gen_qemu_ld_tl(tdest, tsrca, dc->mmuidx, memop);

        break;

    case OE_RR_X1(LDNA):

        tcg_gen_andi_tl(tdest, tsrca, ~7);

        tcg_gen_qemu_ld_tl(tdest, tdest, dc->mmuidx, MO_TEQ);

        mnemonic = "ldna";

        break;

    case OE_RR_X1(LNK):

    case OE_RR_Y1(LNK):

        if (srca) {

            return TILEGX_EXCP_OPCODE_UNIMPLEMENTED;

        }

        tcg_gen_movi_tl(tdest, dc->pc + TILEGX_BUNDLE_SIZE_IN_BYTES);

        mnemonic = "lnk";

        break;

    case OE_RR_X0(PCNT):

    case OE_RR_Y0(PCNT):

        gen_helper_pcnt(tdest, tsrca);

        mnemonic = "pcnt";

        break;

    case OE_RR_X0(REVBITS):

    case OE_RR_Y0(REVBITS):

        gen_helper_revbits(tdest, tsrca);

        mnemonic = "revbits";

        break;

    case OE_RR_X0(REVBYTES):

    case OE_RR_Y0(REVBYTES):

        tcg_gen_bswap64_tl(tdest, tsrca);

        mnemonic = "revbytes";

        break;

    case OE_RR_X0(TBLIDXB0):

    case OE_RR_Y0(TBLIDXB0):

        tcg_gen_deposit_tl(tdest, load_gr(dc, dest), tsrca, 2, 8);

        mnemonic = "tblidxb0";

        break;

    case OE_RR_X0(TBLIDXB1):

    case OE_RR_Y0(TBLIDXB1):

        tcg_gen_shri_tl(tdest, tsrca, 8);

        tcg_gen_deposit_tl(tdest, load_gr(dc, dest), tdest, 2, 8);

        mnemonic = "tblidxb1";

        break;

    case OE_RR_X0(TBLIDXB2):

    case OE_RR_Y0(TBLIDXB2):

        tcg_gen_shri_tl(tdest, tsrca, 16);

        tcg_gen_deposit_tl(tdest, load_gr(dc, dest), tdest, 2, 8);

        mnemonic = "tblidxb2";

        break;

    case OE_RR_X0(TBLIDXB3):

    case OE_RR_Y0(TBLIDXB3):

        tcg_gen_shri_tl(tdest, tsrca, 24);

        tcg_gen_deposit_tl(tdest, load_gr(dc, dest), tdest, 2, 8);

        mnemonic = "tblidxb3";

        break;

    default:

        return TILEGX_EXCP_OPCODE_UNIMPLEMENTED;

    }



    qemu_log_mask(CPU_LOG_TB_IN_ASM, "%s %s, %s", mnemonic,

                  reg_names[dest], reg_names[srca]);

    return ret;

}

static void pci_reg_write4(void *opaque, target_phys_addr_t addr,

                               uint32_t value)

{

    PPCE500PCIState *pci = opaque;

    unsigned long win;



    win = addr & 0xfe0;



    pci_debug("%s: value:%x -> win:%lx(addr:" TARGET_FMT_plx ")\n",

              __func__, value, win, addr);



    switch (win) {

    case PPCE500_PCI_OW1:

    case PPCE500_PCI_OW2:

    case PPCE500_PCI_OW3:

    case PPCE500_PCI_OW4:

        switch (addr & 0xC) {

        case PCI_POTAR:

            pci->pob[(addr >> 5) & 0x7].potar = value;

            break;

        case PCI_POTEAR:

            pci->pob[(addr >> 5) & 0x7].potear = value;

            break;

        case PCI_POWBAR:

            pci->pob[(addr >> 5) & 0x7].powbar = value;

            break;

        case PCI_POWAR:

            pci->pob[(addr >> 5) & 0x7].powar = value;

            break;

        default:

            break;

        };

        break;



    case PPCE500_PCI_IW3:

    case PPCE500_PCI_IW2:

    case PPCE500_PCI_IW1:

        switch (addr & 0xC) {

        case PCI_PITAR:

            pci->pib[(addr >> 5) & 0x3].pitar = value;

            break;

        case PCI_PIWBAR:

            pci->pib[(addr >> 5) & 0x3].piwbar = value;

            break;

        case PCI_PIWBEAR:

            pci->pib[(addr >> 5) & 0x3].piwbear = value;

            break;

        case PCI_PIWAR:

            pci->pib[(addr >> 5) & 0x3].piwar = value;

            break;

        default:

            break;

        };

        break;



    case PPCE500_PCI_GASKET_TIMR:

        pci->gasket_time = value;

        break;



    default:

        break;

    };

}

