static int find_image_range(int *pfirst_index, int *plast_index,

                            const char *path, int start_index, int start_index_range)

{

    char buf[1024];

    int range, last_index, range1, first_index;



    /* find the first image */

    for (first_index = start_index; first_index < start_index + start_index_range; first_index++) {

        if (av_get_frame_filename(buf, sizeof(buf), path, first_index) < 0) {

            *pfirst_index =

            *plast_index  = 1;

            if (avio_check(buf, AVIO_FLAG_READ) > 0)

                return 0;

            return -1;

        }

        if (avio_check(buf, AVIO_FLAG_READ) > 0)

            break;

    }

    if (first_index == start_index + start_index_range)

        goto fail;



    /* find the last image */

    last_index = first_index;

    for (;;) {

        range = 0;

        for (;;) {

            if (!range)

                range1 = 1;

            else

                range1 = 2 * range;

            if (av_get_frame_filename(buf, sizeof(buf), path,

                                      last_index + range1) < 0)

                goto fail;

            if (avio_check(buf, AVIO_FLAG_READ) <= 0)

                break;

            range = range1;

            /* just in case... */

            if (range >= (1 << 30))

                goto fail;

        }

        /* we are sure than image last_index + range exists */

        if (!range)

            break;

        last_index += range;

    }

    *pfirst_index = first_index;

    *plast_index  = last_index;

    return 0;



fail:

    return -1;

}

static int seg_write_packet(AVFormatContext *s, AVPacket *pkt)

{

    SegmentContext *seg = s->priv_data;

    AVStream *st = s->streams[pkt->stream_index];

    int64_t end_pts = INT64_MAX, offset;

    int start_frame = INT_MAX;

    int ret;

    struct tm ti;

    int64_t usecs;

    int64_t wrapped_val;



    if (!seg->avf)

        return AVERROR(EINVAL);



calc_times:

    if (seg->times) {

        end_pts = seg->segment_count < seg->nb_times ?

            seg->times[seg->segment_count] : INT64_MAX;

    } else if (seg->frames) {

        start_frame = seg->segment_count < seg->nb_frames ?

            seg->frames[seg->segment_count] : INT_MAX;

    } else {

        if (seg->use_clocktime) {

            int64_t avgt = av_gettime();

            time_t sec = avgt / 1000000;

            localtime_r(&sec, &ti);

            usecs = (int64_t)(ti.tm_hour * 3600 + ti.tm_min * 60 + ti.tm_sec) * 1000000 + (avgt % 1000000);

            wrapped_val = (usecs + seg->clocktime_offset) % seg->time;

            if (seg->last_cut != usecs && wrapped_val < seg->last_val && wrapped_val < seg->clocktime_wrap_duration) {

                seg->cut_pending = 1;

                seg->last_cut = usecs;

            }

            seg->last_val = wrapped_val;

        } else {

            end_pts = seg->time * (seg->segment_count + 1);

        }

    }



    ff_dlog(s, "packet stream:%d pts:%s pts_time:%s duration_time:%s is_key:%d frame:%d\n",

            pkt->stream_index, av_ts2str(pkt->pts), av_ts2timestr(pkt->pts, &st->time_base),

            av_ts2timestr(pkt->duration, &st->time_base),

            pkt->flags & AV_PKT_FLAG_KEY,

            pkt->stream_index == seg->reference_stream_index ? seg->frame_count : -1);



    if (pkt->stream_index == seg->reference_stream_index &&

        (pkt->flags & AV_PKT_FLAG_KEY || seg->break_non_keyframes) &&

        (seg->segment_frame_count > 0 || seg->write_empty) &&

        (seg->cut_pending || seg->frame_count >= start_frame ||

         (pkt->pts != AV_NOPTS_VALUE &&

          av_compare_ts(pkt->pts, st->time_base,

                        end_pts - seg->time_delta, AV_TIME_BASE_Q) >= 0))) {

        /* sanitize end time in case last packet didn't have a defined duration */

        if (seg->cur_entry.last_duration == 0)

            seg->cur_entry.end_time = (double)pkt->pts * av_q2d(st->time_base);



        if ((ret = segment_end(s, seg->individual_header_trailer, 0)) < 0)

            goto fail;



        if ((ret = segment_start(s, seg->individual_header_trailer)) < 0)

            goto fail;



        seg->cut_pending = 0;

        seg->cur_entry.index = seg->segment_idx + seg->segment_idx_wrap * seg->segment_idx_wrap_nb;

        seg->cur_entry.start_time = (double)pkt->pts * av_q2d(st->time_base);

        seg->cur_entry.start_pts = av_rescale_q(pkt->pts, st->time_base, AV_TIME_BASE_Q);

        seg->cur_entry.end_time = seg->cur_entry.start_time;



        if (seg->times || (!seg->frames && !seg->use_clocktime) && seg->write_empty)

            goto calc_times;

    }



    if (pkt->stream_index == seg->reference_stream_index) {

        if (pkt->pts != AV_NOPTS_VALUE)

            seg->cur_entry.end_time =

                FFMAX(seg->cur_entry.end_time, (double)(pkt->pts + pkt->duration) * av_q2d(st->time_base));

        seg->cur_entry.last_duration = pkt->duration;

    }



    if (seg->segment_frame_count == 0) {

        av_log(s, AV_LOG_VERBOSE, "segment:'%s' starts with packet stream:%d pts:%s pts_time:%s frame:%d\n",

               seg->avf->filename, pkt->stream_index,

               av_ts2str(pkt->pts), av_ts2timestr(pkt->pts, &st->time_base), seg->frame_count);

    }



    av_log(s, AV_LOG_DEBUG, "stream:%d start_pts_time:%s pts:%s pts_time:%s dts:%s dts_time:%s",

           pkt->stream_index,

           av_ts2timestr(seg->cur_entry.start_pts, &AV_TIME_BASE_Q),

           av_ts2str(pkt->pts), av_ts2timestr(pkt->pts, &st->time_base),

           av_ts2str(pkt->dts), av_ts2timestr(pkt->dts, &st->time_base));



    /* compute new timestamps */

    offset = av_rescale_q(seg->initial_offset - (seg->reset_timestamps ? seg->cur_entry.start_pts : 0),

                          AV_TIME_BASE_Q, st->time_base);

    if (pkt->pts != AV_NOPTS_VALUE)

        pkt->pts += offset;

    if (pkt->dts != AV_NOPTS_VALUE)

        pkt->dts += offset;



    av_log(s, AV_LOG_DEBUG, " -> pts:%s pts_time:%s dts:%s dts_time:%s\n",

           av_ts2str(pkt->pts), av_ts2timestr(pkt->pts, &st->time_base),

           av_ts2str(pkt->dts), av_ts2timestr(pkt->dts, &st->time_base));



    ret = ff_write_chained(seg->avf, pkt->stream_index, pkt, s, seg->initial_offset || seg->reset_timestamps);



fail:

    if (pkt->stream_index == seg->reference_stream_index) {

        seg->frame_count++;

        seg->segment_frame_count++;

    }



    return ret;

}

AVFilterContext *ff_filter_alloc(const AVFilter *filter, const char *inst_name)

{

    AVFilterContext *ret;



    if (!filter)

        return NULL;



    ret = av_mallocz(sizeof(AVFilterContext));

    if (!ret)

        return NULL;



    ret->av_class = &avfilter_class;

    ret->filter   = filter;

    ret->name     = inst_name ? av_strdup(inst_name) : NULL;

    if (filter->priv_size) {

        ret->priv     = av_mallocz(filter->priv_size);

        if (!ret->priv)

            goto err;

    }



    if (filter->priv_class) {

        *(const AVClass**)ret->priv = filter->priv_class;

        av_opt_set_defaults(ret->priv);

    }



    ret->nb_inputs = pad_count(filter->inputs);

    if (ret->nb_inputs ) {

        ret->input_pads   = av_malloc(sizeof(AVFilterPad) * ret->nb_inputs);

        if (!ret->input_pads)

            goto err;

        memcpy(ret->input_pads, filter->inputs, sizeof(AVFilterPad) * ret->nb_inputs);

        ret->inputs       = av_mallocz(sizeof(AVFilterLink*) * ret->nb_inputs);

        if (!ret->inputs)

            goto err;

    }



    ret->nb_outputs = pad_count(filter->outputs);

    if (ret->nb_outputs) {

        ret->output_pads  = av_malloc(sizeof(AVFilterPad) * ret->nb_outputs);

        if (!ret->output_pads)

            goto err;

        memcpy(ret->output_pads, filter->outputs, sizeof(AVFilterPad) * ret->nb_outputs);

        ret->outputs      = av_mallocz(sizeof(AVFilterLink*) * ret->nb_outputs);

        if (!ret->outputs)

            goto err;

    }

#if FF_API_FOO_COUNT

    ret->output_count = ret->nb_outputs;

    ret->input_count  = ret->nb_inputs;

#endif



    return ret;



err:

    av_freep(&ret->inputs);

    av_freep(&ret->input_pads);

    ret->nb_inputs = 0;

    av_freep(&ret->outputs);

    av_freep(&ret->output_pads);

    ret->nb_outputs = 0;

    av_freep(&ret->priv);

    av_free(ret);

    return NULL;

}

static int rate_control(AVCodecContext *avctx, void *arg)

{

    SliceArgs *slice_dat = arg;

    VC2EncContext *s = slice_dat->ctx;

    const int sx = slice_dat->x;

    const int sy = slice_dat->y;

    int quant_buf[2], bits_buf[2], quant = s->q_start, range = s->q_start/3;

    const int64_t top = slice_dat->bits_ceil;

    const double percent = s->tolerance;

    const double bottom = top - top*(percent/100.0f);

    int bits = count_hq_slice(s, sx, sy, quant);

    range -= range & 1; /* Make it an even number */

    while ((bits > top) || (bits < bottom)) {

        range *= bits > top ? +1 : -1;

        quant = av_clip(quant + range, 0, s->q_ceil);

        bits = count_hq_slice(s, sx, sy, quant);

        range = av_clip(range/2, 1, s->q_ceil);

        if (quant_buf[1] == quant) {

            quant = bits_buf[0] < bits ? quant_buf[0] : quant;

            bits = bits_buf[0] < bits ? bits_buf[0] : bits;

            break;

        }

        quant_buf[1] = quant_buf[0];

        quant_buf[0] = quant;

        bits_buf[1] = bits_buf[0];

        bits_buf[0] = bits;

    }

    slice_dat->quant_idx = av_clip(quant, 0, s->q_ceil);

    slice_dat->bytes = FFALIGN((bits >> 3), s->size_scaler) + 4 + s->prefix_bytes;



    return 0;

}

static void pl181_fifo_run(pl181_state *s)

{

    uint32_t bits;

    uint32_t value;

    int n;

    int limit;

    int is_read;



    is_read = (s->datactrl & PL181_DATA_DIRECTION) != 0;

    if (s->datacnt != 0 && (!is_read || sd_data_ready(s->card))

            && !s->linux_hack) {

        limit = is_read ? PL181_FIFO_LEN : 0;

        n = 0;

        value = 0;

        while (s->datacnt && s->fifo_len != limit) {

            if (is_read) {

                value |= (uint32_t)sd_read_data(s->card) << (n * 8);

                n++;

                if (n == 4) {

                    pl181_fifo_push(s, value);

                    value = 0;

                    n = 0;

                }

            } else {

                if (n == 0) {

                    value = pl181_fifo_pop(s);

                    n = 4;

                }

                sd_write_data(s->card, value & 0xff);

                value >>= 8;

                n--;

            }

            s->datacnt--;

        }

        if (n && is_read) {

            pl181_fifo_push(s, value);

        }

    }

    s->status &= ~(PL181_STATUS_RX_FIFO | PL181_STATUS_TX_FIFO);

    if (s->datacnt == 0) {

        s->status |= PL181_STATUS_DATAEND;

        /* HACK: */

        s->status |= PL181_STATUS_DATABLOCKEND;

        DPRINTF("Transfer Complete\n");

    }

    if (s->datacnt == 0 && s->fifo_len == 0) {

        s->datactrl &= ~PL181_DATA_ENABLE;

        DPRINTF("Data engine idle\n");

    } else {

        /* Update FIFO bits.  */

        bits = PL181_STATUS_TXACTIVE | PL181_STATUS_RXACTIVE;

        if (s->fifo_len == 0) {

            bits |= PL181_STATUS_TXFIFOEMPTY;

            bits |= PL181_STATUS_RXFIFOEMPTY;

        } else {

            bits |= PL181_STATUS_TXDATAAVLBL;

            bits |= PL181_STATUS_RXDATAAVLBL;

        }

        if (s->fifo_len == 16) {

            bits |= PL181_STATUS_TXFIFOFULL;

            bits |= PL181_STATUS_RXFIFOFULL;

        }

        if (s->fifo_len <= 8) {

            bits |= PL181_STATUS_TXFIFOHALFEMPTY;

        }

        if (s->fifo_len >= 8) {

            bits |= PL181_STATUS_RXFIFOHALFFULL;

        }

        if (s->datactrl & PL181_DATA_DIRECTION) {

            bits &= PL181_STATUS_RX_FIFO;

        } else {

            bits &= PL181_STATUS_TX_FIFO;

        }

        s->status |= bits;

    }

}

