        if (err) {
            error_propagate(errp, err);
    } else {
        usb_bus_new(&ohci->bus, sizeof(ohci->bus), &ohci_bus_ops, dev);
        for (i = 0; i < num_ports; i++) {
            usb_register_port(&ohci->bus, &ohci->rhport[i].port,
                              ohci, i, &ohci_port_ops,
                              USB_SPEED_MASK_LOW | USB_SPEED_MASK_FULL);
    memory_region_init_io(&ohci->mem, OBJECT(dev), &ohci_mem_ops,
                          ohci, "ohci", 256);
    ohci->localmem_base = localmem_base;
    ohci->name = object_get_typename(OBJECT(dev));
    usb_packet_init(&ohci->usb_packet);
    ohci->async_td = 0;
    ohci->eof_timer = timer_new_ns(QEMU_CLOCK_VIRTUAL,
                                   ohci_frame_boundary, ohci);

static MemTxResult nvic_sysreg_read(void *opaque, hwaddr addr,

                                    uint64_t *data, unsigned size,

                                    MemTxAttrs attrs)

{

    NVICState *s = (NVICState *)opaque;

    uint32_t offset = addr;

    unsigned i, startvec, end;

    uint32_t val;



    if (attrs.user && !nvic_user_access_ok(s, addr)) {

        /* Generate BusFault for unprivileged accesses */

        return MEMTX_ERROR;

    }



    switch (offset) {

    /* reads of set and clear both return the status */

    case 0x100 ... 0x13f: /* NVIC Set enable */

        offset += 0x80;

        /* fall through */

    case 0x180 ... 0x1bf: /* NVIC Clear enable */

        val = 0;

        startvec = offset - 0x180 + NVIC_FIRST_IRQ; /* vector # */



        for (i = 0, end = size * 8; i < end && startvec + i < s->num_irq; i++) {

            if (s->vectors[startvec + i].enabled) {

                val |= (1 << i);

            }

        }

        break;

    case 0x200 ... 0x23f: /* NVIC Set pend */

        offset += 0x80;

        /* fall through */

    case 0x280 ... 0x2bf: /* NVIC Clear pend */

        val = 0;

        startvec = offset - 0x280 + NVIC_FIRST_IRQ; /* vector # */

        for (i = 0, end = size * 8; i < end && startvec + i < s->num_irq; i++) {

            if (s->vectors[startvec + i].pending) {

                val |= (1 << i);

            }

        }

        break;

    case 0x300 ... 0x33f: /* NVIC Active */

        val = 0;

        startvec = offset - 0x300 + NVIC_FIRST_IRQ; /* vector # */



        for (i = 0, end = size * 8; i < end && startvec + i < s->num_irq; i++) {

            if (s->vectors[startvec + i].active) {

                val |= (1 << i);

            }

        }

        break;

    case 0x400 ... 0x5ef: /* NVIC Priority */

        val = 0;

        startvec = offset - 0x400 + NVIC_FIRST_IRQ; /* vector # */



        for (i = 0; i < size && startvec + i < s->num_irq; i++) {

            val |= s->vectors[startvec + i].prio << (8 * i);

        }

        break;

    case 0xd18 ... 0xd23: /* System Handler Priority.  */

        val = 0;

        for (i = 0; i < size; i++) {

            val |= s->vectors[(offset - 0xd14) + i].prio << (i * 8);

        }

        break;

    case 0xfe0 ... 0xfff: /* ID.  */

        if (offset & 3) {

            val = 0;

        } else {

            val = nvic_id[(offset - 0xfe0) >> 2];

        }

        break;

    default:

        if (size == 4) {

            val = nvic_readl(s, offset);

        } else {

            qemu_log_mask(LOG_GUEST_ERROR,

                          "NVIC: Bad read of size %d at offset 0x%x\n",

                          size, offset);

            val = 0;

        }

    }



    trace_nvic_sysreg_read(addr, val, size);

    *data = val;

    return MEMTX_OK;

}

static void vfio_vga_quirk_teardown(VFIOPCIDevice *vdev)

{

    int i;



    for (i = 0; i < ARRAY_SIZE(vdev->vga.region); i++) {

        while (!QLIST_EMPTY(&vdev->vga.region[i].quirks)) {

            VFIOQuirk *quirk = QLIST_FIRST(&vdev->vga.region[i].quirks);

            memory_region_del_subregion(&vdev->vga.region[i].mem, &quirk->mem);

            object_unparent(OBJECT(&quirk->mem));

            QLIST_REMOVE(quirk, next);

            g_free(quirk);

        }

    }

}

static void vertical_filter(unsigned char *first_pixel, int stride,

    int *bounding_values)

{

    int i;

    int filter_value;



    for (i = 0; i < 8; i++, first_pixel++) {

        filter_value = 

            (first_pixel[-(2 * stride)] * 1) - 

            (first_pixel[-(1 * stride)] * 3) +

            (first_pixel[ (0         )] * 3) -

            (first_pixel[ (1 * stride)] * 1);

        filter_value = bounding_values[(filter_value + 4) >> 3];

        first_pixel[-(1 * stride)] = SATURATE_U8(first_pixel[-(1 * stride)] + filter_value);

        first_pixel[0] = SATURATE_U8(first_pixel[0] - filter_value);

    }

}

