static int libkvazaar_encode(AVCodecContext *avctx,

                             AVPacket *avpkt,

                             const AVFrame *frame,

                             int *got_packet_ptr)

{

    int retval = 0;

    kvz_picture *img_in = NULL;



    kvz_data_chunk *data_out = NULL;

    uint32_t len_out = 0;

    kvz_frame_info frame_info;



    LibkvazaarContext *ctx = avctx->priv_data;



    *got_packet_ptr = 0;



    if (frame) {

        int i = 0;



        av_assert0(frame->width == ctx->config->width);

        av_assert0(frame->height == ctx->config->height);

        av_assert0(frame->format == avctx->pix_fmt);



        // Allocate input picture for kvazaar.

        img_in = ctx->api->picture_alloc(frame->width, frame->height);

        if (!img_in) {

            av_log(avctx, AV_LOG_ERROR, "Failed to allocate picture.\n");

            retval = AVERROR(ENOMEM);

            goto done;

        }



        // Copy pixels from frame to img_in.

        for (i = 0; i < 3; ++i) {

            uint8_t *dst = img_in->data[i];

            uint8_t *src = frame->data[i];

            int width = (i == 0) ? frame->width : (frame->width / 2);

            int height = (i == 0) ? frame->height : (frame->height / 2);

            int y = 0;

            for (y = 0; y < height; ++y) {

                memcpy(dst, src, width);

                src += frame->linesize[i];

                dst += width;

            }

        }

    }



    if (!ctx->api->encoder_encode(ctx->encoder, img_in,

                                  &data_out, &len_out,

                                  NULL, NULL,

                                  &frame_info)) {

        av_log(avctx, AV_LOG_ERROR, "Failed to encode frame.\n");

        retval = AVERROR_EXTERNAL;

        goto done;

    }



    if (data_out) {

        kvz_data_chunk *chunk = NULL;

        uint64_t written = 0;



        retval = ff_alloc_packet(avpkt, len_out);

        if (retval < 0) {

            av_log(avctx, AV_LOG_ERROR, "Failed to allocate output packet.\n");

            goto done;

        }



        for (chunk = data_out; chunk != NULL; chunk = chunk->next) {

            av_assert0(written + chunk->len <= len_out);

            memcpy(avpkt->data + written, chunk->data, chunk->len);

            written += chunk->len;

        }

        *got_packet_ptr = 1;



        ctx->api->chunk_free(data_out);

        data_out = NULL;



        avpkt->flags = 0;

        // IRAP VCL NAL unit types span the range

        // [BLA_W_LP (16), RSV_IRAP_VCL23 (23)].

        if (frame_info.nal_unit_type >= KVZ_NAL_BLA_W_LP &&

                frame_info.nal_unit_type <= KVZ_NAL_RSV_IRAP_VCL23) {

            avpkt->flags |= AV_PKT_FLAG_KEY;

        }

    }



done:

    ctx->api->picture_free(img_in);

    ctx->api->chunk_free(data_out);

    return retval;

}

static void search_for_ms(AACEncContext *s, ChannelElement *cpe,

                          const float lambda)

{

    int start = 0, i, w, w2, g;

    float M[128], S[128];

    float *L34 = s->scoefs, *R34 = s->scoefs + 128, *M34 = s->scoefs + 128*2, *S34 = s->scoefs + 128*3;

    SingleChannelElement *sce0 = &cpe->ch[0];

    SingleChannelElement *sce1 = &cpe->ch[1];

    if (!cpe->common_window)

        return;

    for (w = 0; w < sce0->ics.num_windows; w += sce0->ics.group_len[w]) {

        for (g = 0;  g < sce0->ics.num_swb; g++) {

            if (!cpe->ch[0].zeroes[w*16+g] && !cpe->ch[1].zeroes[w*16+g]) {

                float dist1 = 0.0f, dist2 = 0.0f;

                for (w2 = 0; w2 < sce0->ics.group_len[w]; w2++) {

                    FFPsyBand *band0 = &s->psy.ch[s->cur_channel+0].psy_bands[(w+w2)*16+g];

                    FFPsyBand *band1 = &s->psy.ch[s->cur_channel+1].psy_bands[(w+w2)*16+g];

                    float minthr = FFMIN(band0->threshold, band1->threshold);

                    float maxthr = FFMAX(band0->threshold, band1->threshold);

                    for (i = 0; i < sce0->ics.swb_sizes[g]; i++) {

                        M[i] = (sce0->coeffs[start+w2*128+i]

                              + sce1->coeffs[start+w2*128+i]) * 0.5;

                        S[i] =  M[i]

                              - sce1->coeffs[start+w2*128+i];

                    }

                    abs_pow34_v(L34, sce0->coeffs+start+w2*128, sce0->ics.swb_sizes[g]);

                    abs_pow34_v(R34, sce1->coeffs+start+w2*128, sce0->ics.swb_sizes[g]);

                    abs_pow34_v(M34, M,                         sce0->ics.swb_sizes[g]);

                    abs_pow34_v(S34, S,                         sce0->ics.swb_sizes[g]);

                    dist1 += quantize_band_cost(s, sce0->coeffs + start + w2*128,

                                                L34,

                                                sce0->ics.swb_sizes[g],

                                                sce0->sf_idx[(w+w2)*16+g],

                                                sce0->band_type[(w+w2)*16+g],

                                                lambda / band0->threshold, INFINITY, NULL);

                    dist1 += quantize_band_cost(s, sce1->coeffs + start + w2*128,

                                                R34,

                                                sce1->ics.swb_sizes[g],

                                                sce1->sf_idx[(w+w2)*16+g],

                                                sce1->band_type[(w+w2)*16+g],

                                                lambda / band1->threshold, INFINITY, NULL);

                    dist2 += quantize_band_cost(s, M,

                                                M34,

                                                sce0->ics.swb_sizes[g],

                                                sce0->sf_idx[(w+w2)*16+g],

                                                sce0->band_type[(w+w2)*16+g],

                                                lambda / maxthr, INFINITY, NULL);

                    dist2 += quantize_band_cost(s, S,

                                                S34,

                                                sce1->ics.swb_sizes[g],

                                                sce1->sf_idx[(w+w2)*16+g],

                                                sce1->band_type[(w+w2)*16+g],

                                                lambda / minthr, INFINITY, NULL);

                }

                cpe->ms_mask[w*16+g] = dist2 < dist1;

            }

            start += sce0->ics.swb_sizes[g];

        }

    }

}

static float32 addFloat32Sigs( float32 a, float32 b, flag zSign STATUS_PARAM)

{

    int16 aExp, bExp, zExp;

    uint32_t aSig, bSig, zSig;

    int16 expDiff;



    aSig = extractFloat32Frac( a );

    aExp = extractFloat32Exp( a );

    bSig = extractFloat32Frac( b );

    bExp = extractFloat32Exp( b );

    expDiff = aExp - bExp;

    aSig <<= 6;

    bSig <<= 6;

    if ( 0 < expDiff ) {

        if ( aExp == 0xFF ) {

            if ( aSig ) return propagateFloat32NaN( a, b STATUS_VAR );

            return a;

        }

        if ( bExp == 0 ) {

            --expDiff;

        }

        else {

            bSig |= 0x20000000;

        }

        shift32RightJamming( bSig, expDiff, &bSig );

        zExp = aExp;

    }

    else if ( expDiff < 0 ) {

        if ( bExp == 0xFF ) {

            if ( bSig ) return propagateFloat32NaN( a, b STATUS_VAR );

            return packFloat32( zSign, 0xFF, 0 );

        }

        if ( aExp == 0 ) {

            ++expDiff;

        }

        else {

            aSig |= 0x20000000;

        }

        shift32RightJamming( aSig, - expDiff, &aSig );

        zExp = bExp;

    }

    else {

        if ( aExp == 0xFF ) {

            if ( aSig | bSig ) return propagateFloat32NaN( a, b STATUS_VAR );

            return a;

        }

        if ( aExp == 0 ) {

            if ( STATUS(flush_to_zero) ) return packFloat32( zSign, 0, 0 );

            return packFloat32( zSign, 0, ( aSig + bSig )>>6 );

        }

        zSig = 0x40000000 + aSig + bSig;

        zExp = aExp;

        goto roundAndPack;

    }

    aSig |= 0x20000000;

    zSig = ( aSig + bSig )<<1;

    --zExp;

    if ( (int32_t) zSig < 0 ) {

        zSig = aSig + bSig;

        ++zExp;

    }

 roundAndPack:

    return roundAndPackFloat32( zSign, zExp, zSig STATUS_VAR );



}

static void openpic_cpu_write_internal(void *opaque, hwaddr addr,

                                       uint32_t val, int idx)

{

    openpic_t *opp = opaque;

    IRQ_src_t *src;

    IRQ_dst_t *dst;

    int s_IRQ, n_IRQ;



    DPRINTF("%s: cpu %d addr " TARGET_FMT_plx " <= %08x\n", __func__, idx,

            addr, val);

    if (addr & 0xF)

        return;

    dst = &opp->dst[idx];

    addr &= 0xFF0;

    switch (addr) {

    case 0x40: /* IPIDR */

    case 0x50:

    case 0x60:

    case 0x70:

        idx = (addr - 0x40) >> 4;

        /* we use IDE as mask which CPUs to deliver the IPI to still. */

        write_IRQreg_ide(opp, opp->irq_ipi0 + idx,

                         opp->src[opp->irq_ipi0 + idx].ide | val);

        openpic_set_irq(opp, opp->irq_ipi0 + idx, 1);

        openpic_set_irq(opp, opp->irq_ipi0 + idx, 0);

        break;

    case 0x80: /* PCTP */

        dst->pctp = val & 0x0000000F;

        break;

    case 0x90: /* WHOAMI */

        /* Read-only register */

        break;

    case 0xA0: /* PIAC */

        /* Read-only register */

        break;

    case 0xB0: /* PEOI */

        DPRINTF("PEOI\n");

        s_IRQ = IRQ_get_next(opp, &dst->servicing);

        IRQ_resetbit(&dst->servicing, s_IRQ);

        dst->servicing.next = -1;

        /* Set up next servicing IRQ */

        s_IRQ = IRQ_get_next(opp, &dst->servicing);

        /* Check queued interrupts. */

        n_IRQ = IRQ_get_next(opp, &dst->raised);

        src = &opp->src[n_IRQ];

        if (n_IRQ != -1 &&

            (s_IRQ == -1 ||

             IPVP_PRIORITY(src->ipvp) > dst->servicing.priority)) {

            DPRINTF("Raise OpenPIC INT output cpu %d irq %d\n",

                    idx, n_IRQ);

            opp->irq_raise(opp, idx, src);

        }

        break;

    default:

        break;

    }

}

static void FUNCC(pred16x16_horizontal)(uint8_t *_src, int stride){

    int i;

    pixel *src = (pixel*)_src;

    stride /= sizeof(pixel);



    for(i=0; i<16; i++){

        ((pixel4*)(src+i*stride))[0] =

        ((pixel4*)(src+i*stride))[1] =

        ((pixel4*)(src+i*stride))[2] =

        ((pixel4*)(src+i*stride))[3] = PIXEL_SPLAT_X4(src[-1+i*stride]);

    }

}

static void pci_write(void *opaque, hwaddr addr, uint64_t data,

                      unsigned int size)

{

    AcpiPciHpState *s = opaque;

    switch (addr) {

    case PCI_EJ_BASE:

        if (s->hotplug_select >= ACPI_PCIHP_MAX_HOTPLUG_BUS) {

            break;

        }

        acpi_pcihp_eject_slot(s, s->hotplug_select, data);

        ACPI_PCIHP_DPRINTF("pciej write %" HWADDR_PRIx " <== %" PRIu64 "\n",

                      addr, data);

        break;

    case PCI_SEL_BASE:

        s->hotplug_select = data;

        ACPI_PCIHP_DPRINTF("pcisel write %" HWADDR_PRIx " <== %" PRIu64 "\n",

                      addr, data);

    default:

        break;

    }

}

