static int mov_get_h264_codec_tag(AVFormatContext *s, MOVTrack *track)

{

    int tag = track->par->codec_tag;

    int interlaced = track->par->field_order > AV_FIELD_PROGRESSIVE;

    AVStream *st = track->st;

    int rate = av_q2d(find_fps(s, st));



    if (!tag)

        tag = MKTAG('a', 'v', 'c', 'i'); //fallback tag



    if (track->par->format == AV_PIX_FMT_YUV420P10) {

        if (track->par->width == 960 && track->par->height == 720) {

            if (!interlaced) {

                if      (rate == 24) tag = MKTAG('a','i','5','p');

                else if (rate == 25) tag = MKTAG('a','i','5','q');

                else if (rate == 30) tag = MKTAG('a','i','5','p');

                else if (rate == 50) tag = MKTAG('a','i','5','q');

                else if (rate == 60) tag = MKTAG('a','i','5','p');

            }

        } else if (track->par->width == 1440 && track->par->height == 1080) {

            if (!interlaced) {

                if      (rate == 24) tag = MKTAG('a','i','5','3');

                else if (rate == 25) tag = MKTAG('a','i','5','2');

                else if (rate == 30) tag = MKTAG('a','i','5','3');

            } else {

                if      (rate == 50) tag = MKTAG('a','i','5','5');

                else if (rate == 60) tag = MKTAG('a','i','5','6');

            }

        }

    } else if (track->par->format == AV_PIX_FMT_YUV422P10) {

        if (track->par->width == 1280 && track->par->height == 720) {

            if (!interlaced) {

                if      (rate == 24) tag = MKTAG('a','i','1','p');

                else if (rate == 25) tag = MKTAG('a','i','1','q');

                else if (rate == 30) tag = MKTAG('a','i','1','p');

                else if (rate == 50) tag = MKTAG('a','i','1','q');

                else if (rate == 60) tag = MKTAG('a','i','1','p');

            }

        } else if (track->par->width == 1920 && track->par->height == 1080) {

            if (!interlaced) {

                if      (rate == 24) tag = MKTAG('a','i','1','3');

                else if (rate == 25) tag = MKTAG('a','i','1','2');

                else if (rate == 30) tag = MKTAG('a','i','1','3');

            } else {

                if      (rate == 25) tag = MKTAG('a','i','1','5');

                else if (rate == 50) tag = MKTAG('a','i','1','5');

                else if (rate == 60) tag = MKTAG('a','i','1','6');

            }

        } else if (   track->par->width == 4096 && track->par->height == 2160

                   || track->par->width == 3840 && track->par->height == 2160

                   || track->par->width == 2048 && track->par->height == 1080) {

            tag = MKTAG('a','i','v','x');

        }

    }



    return tag;

}

static int ratecontrol_1pass(SnowContext *s, AVFrame *pict)

{

    /* estimate the frame's complexity as a sum of weighted dwt coefs.

     * FIXME we know exact mv bits at this point,

     * but ratecontrol isn't set up to include them. */

    uint32_t coef_sum= 0;

    int level, orientation, delta_qlog;



    for(level=0; level<s->spatial_decomposition_count; level++){

        for(orientation=level ? 1 : 0; orientation<4; orientation++){

            SubBand *b= &s->plane[0].band[level][orientation];

            DWTELEM *buf= b->buf;

            const int w= b->width;

            const int h= b->height;

            const int stride= b->stride;

            const int qlog= clip(2*QROOT + b->qlog, 0, QROOT*16);

            const int qmul= qexp[qlog&(QROOT-1)]<<(qlog>>QSHIFT);

            const int qdiv= (1<<16)/qmul;

            int x, y;

            if(orientation==0)

                decorrelate(s, b, buf, stride, 1, 0);

            for(y=0; y<h; y++)

                for(x=0; x<w; x++)

                    coef_sum+= abs(buf[x+y*stride]) * qdiv >> 16;

            if(orientation==0)

                correlate(s, b, buf, stride, 1, 0);

        }

    }



    /* ugly, ratecontrol just takes a sqrt again */

    coef_sum = (uint64_t)coef_sum * coef_sum >> 16;

    assert(coef_sum < INT_MAX);



    if(pict->pict_type == I_TYPE){

        s->m.current_picture.mb_var_sum= coef_sum;

        s->m.current_picture.mc_mb_var_sum= 0;

    }else{

        s->m.current_picture.mc_mb_var_sum= coef_sum;

        s->m.current_picture.mb_var_sum= 0;

    }



    pict->quality= ff_rate_estimate_qscale(&s->m, 1);

    if (pict->quality < 0)

        return -1;

    s->lambda= pict->quality * 3/2;

    delta_qlog= qscale2qlog(pict->quality) - s->qlog;

    s->qlog+= delta_qlog;

    return delta_qlog;

}

static int vmdaudio_decode_init(AVCodecContext *avctx)

{

    VmdAudioContext *s = (VmdAudioContext *)avctx->priv_data;

    int i;



    s->channels = avctx->channels;

    s->bits = avctx->bits_per_sample;

    s->block_align = avctx->block_align;



printf ("  %d channels, %d bits/sample, block align = %d\n",

  s->channels, s->bits, s->block_align);



    /* set up the steps8 and steps16 tables */

    for (i = 0; i < 8; i++) {

        if (i < 4)

            s->steps8[i] = i;

        else

            s->steps8[i] = s->steps8[i - 1] + i - 1;



        if (i == 0)

            s->steps16[i] = 0;

        else if (i == 1)

            s->steps16[i] = 4;

        else if (i == 2)

            s->steps16[i] = 16;

        else

            s->steps16[i] = 1 << (i + 4);

    }



    /* set up the step128 table */

    s->steps128[0] = 0;

    s->steps128[1] = 8;

    for (i = 0x02; i <= 0x20; i++)

        s->steps128[i] = (i - 1) << 4;

    for (i = 0x21; i <= 0x60; i++)

        s->steps128[i] = (i + 0x1F) << 3;

    for (i = 0x61; i <= 0x70; i++)

        s->steps128[i] = (i - 0x51) << 6;

    for (i = 0x71; i <= 0x78; i++)

        s->steps128[i] = (i - 0x69) << 8;

    for (i = 0x79; i <= 0x7D; i++)

        s->steps128[i] = (i - 0x75) << 10;

    s->steps128[0x7E] = 0x3000;

    s->steps128[0x7F] = 0x4000;



    /* set up the negative half of each table */

    for (i = 0; i < 8; i++) {

        s->steps8[i + 8] = -s->steps8[i];

        s->steps16[i + 8] = -s->steps16[i];

    }

    for (i = 0; i < 128; i++)

      s->steps128[i + 128] = -s->steps128[i];



    return 0;

}

static bool coroutine_fn wait_serialising_requests(BdrvTrackedRequest *self)

{

    BlockDriverState *bs = self->bs;

    BdrvTrackedRequest *req;

    bool retry;

    bool waited = false;



    if (!bs->serialising_in_flight) {

        return false;

    }



    do {

        retry = false;

        QLIST_FOREACH(req, &bs->tracked_requests, list) {

            if (req == self || (!req->serialising && !self->serialising)) {

                continue;

            }

            if (tracked_request_overlaps(req, self->overlap_offset,

                                         self->overlap_bytes))

            {

                /* Hitting this means there was a reentrant request, for

                 * example, a block driver issuing nested requests.  This must

                 * never happen since it means deadlock.

                 */

                assert(qemu_coroutine_self() != req->co);



                /* If the request is already (indirectly) waiting for us, or

                 * will wait for us as soon as it wakes up, then just go on

                 * (instead of producing a deadlock in the former case). */

                if (!req->waiting_for) {

                    self->waiting_for = req;

                    qemu_co_queue_wait(&req->wait_queue);

                    self->waiting_for = NULL;

                    retry = true;

                    waited = true;

                    break;

                }

            }

        }

    } while (retry);



    return waited;

}

static void read_storage_element0_info(SCLPDevice *sclp, SCCB *sccb)

{

    int i, assigned;

    int subincrement_id = SCLP_STARTING_SUBINCREMENT_ID;

    ReadStorageElementInfo *storage_info = (ReadStorageElementInfo *) sccb;

    sclpMemoryHotplugDev *mhd = get_sclp_memory_hotplug_dev();



    assert(mhd);



    if ((ram_size >> mhd->increment_size) >= 0x10000) {

        sccb->h.response_code = cpu_to_be16(SCLP_RC_SCCB_BOUNDARY_VIOLATION);

        return;

    }



    /* Return information regarding core memory */

    storage_info->max_id = cpu_to_be16(mhd->standby_mem_size ? 1 : 0);

    assigned = ram_size >> mhd->increment_size;

    storage_info->assigned = cpu_to_be16(assigned);



    for (i = 0; i < assigned; i++) {

        storage_info->entries[i] = cpu_to_be32(subincrement_id);

        subincrement_id += SCLP_INCREMENT_UNIT;

    }

    sccb->h.response_code = cpu_to_be16(SCLP_RC_NORMAL_READ_COMPLETION);

}

