static int add_graphics_client(Monitor *mon, const QDict *qdict, QObject **ret_data)

{

    const char *protocol  = qdict_get_str(qdict, "protocol");

    const char *fdname = qdict_get_str(qdict, "fdname");

    CharDriverState *s;



    if (strcmp(protocol, "spice") == 0) {

        int fd = monitor_get_fd(mon, fdname, NULL);

        int skipauth = qdict_get_try_bool(qdict, "skipauth", 0);

        int tls = qdict_get_try_bool(qdict, "tls", 0);

        if (!using_spice) {

            /* correct one? spice isn't a device ,,, */

            qerror_report(QERR_DEVICE_NOT_ACTIVE, "spice");

            return -1;

        }

        if (qemu_spice_display_add_client(fd, skipauth, tls) < 0) {

            close(fd);

        }

        return 0;

#ifdef CONFIG_VNC

    } else if (strcmp(protocol, "vnc") == 0) {

	int fd = monitor_get_fd(mon, fdname, NULL);

        int skipauth = qdict_get_try_bool(qdict, "skipauth", 0);

	vnc_display_add_client(NULL, fd, skipauth);

	return 0;

#endif

    } else if ((s = qemu_chr_find(protocol)) != NULL) {

	int fd = monitor_get_fd(mon, fdname, NULL);

	if (qemu_chr_add_client(s, fd) < 0) {

	    qerror_report(QERR_ADD_CLIENT_FAILED);

	    return -1;

	}

	return 0;

    }



    qerror_report(QERR_INVALID_PARAMETER, "protocol");

    return -1;

}

static int ffm_read_header(AVFormatContext *s, AVFormatParameters *ap)

{

    FFMContext *ffm = s->priv_data;

    AVStream *st;

    ByteIOContext *pb = s->pb;

    AVCodecContext *codec;

    int i, nb_streams;

    uint32_t tag;



    /* header */

    tag = get_le32(pb);

    if (tag != MKTAG('F', 'F', 'M', '1'))

        goto fail;

    ffm->packet_size = get_be32(pb);

    if (ffm->packet_size != FFM_PACKET_SIZE)

        goto fail;

    ffm->write_index = get_be64(pb);

    /* get also filesize */

    if (!url_is_streamed(pb)) {

        ffm->file_size = url_fsize(pb);

        if (ffm->write_index)

            adjust_write_index(s);

    } else {

        ffm->file_size = (UINT64_C(1) << 63) - 1;

    }



    nb_streams = get_be32(pb);

    get_be32(pb); /* total bitrate */

    /* read each stream */

    for(i=0;i<nb_streams;i++) {

        char rc_eq_buf[128];



        st = av_new_stream(s, 0);

        if (!st)

            goto fail;



        av_set_pts_info(st, 64, 1, 1000000);



        codec = st->codec;

        /* generic info */

        codec->codec_id = get_be32(pb);

        codec->codec_type = get_byte(pb); /* codec_type */

        codec->bit_rate = get_be32(pb);

        st->quality = get_be32(pb);

        codec->flags = get_be32(pb);

        codec->flags2 = get_be32(pb);

        codec->debug = get_be32(pb);

        /* specific info */

        switch(codec->codec_type) {

        case CODEC_TYPE_VIDEO:

            codec->time_base.num = get_be32(pb);

            codec->time_base.den = get_be32(pb);

            codec->width = get_be16(pb);

            codec->height = get_be16(pb);

            codec->gop_size = get_be16(pb);

            codec->pix_fmt = get_be32(pb);

            codec->qmin = get_byte(pb);

            codec->qmax = get_byte(pb);

            codec->max_qdiff = get_byte(pb);

            codec->qcompress = get_be16(pb) / 10000.0;

            codec->qblur = get_be16(pb) / 10000.0;

            codec->bit_rate_tolerance = get_be32(pb);

            codec->rc_eq = av_strdup(get_strz(pb, rc_eq_buf, sizeof(rc_eq_buf)));

            codec->rc_max_rate = get_be32(pb);

            codec->rc_min_rate = get_be32(pb);

            codec->rc_buffer_size = get_be32(pb);

            codec->i_quant_factor = av_int2dbl(get_be64(pb));

            codec->b_quant_factor = av_int2dbl(get_be64(pb));

            codec->i_quant_offset = av_int2dbl(get_be64(pb));

            codec->b_quant_offset = av_int2dbl(get_be64(pb));

            codec->dct_algo = get_be32(pb);

            codec->strict_std_compliance = get_be32(pb);

            codec->max_b_frames = get_be32(pb);

            codec->luma_elim_threshold = get_be32(pb);

            codec->chroma_elim_threshold = get_be32(pb);

            codec->mpeg_quant = get_be32(pb);

            codec->intra_dc_precision = get_be32(pb);

            codec->me_method = get_be32(pb);

            codec->mb_decision = get_be32(pb);

            codec->nsse_weight = get_be32(pb);

            codec->frame_skip_cmp = get_be32(pb);

            codec->rc_buffer_aggressivity = av_int2dbl(get_be64(pb));

            codec->codec_tag = get_be32(pb);

            codec->thread_count = get_byte(pb);

            codec->coder_type = get_be32(pb);

            codec->me_cmp = get_be32(pb);

            codec->partitions = get_be32(pb);

            codec->me_subpel_quality = get_be32(pb);

            codec->me_range = get_be32(pb);

            codec->keyint_min = get_be32(pb);

            codec->scenechange_threshold = get_be32(pb);

            codec->b_frame_strategy = get_be32(pb);

            codec->qcompress = av_int2dbl(get_be64(pb));

            codec->qblur = av_int2dbl(get_be64(pb));

            codec->max_qdiff = get_be32(pb);

            codec->refs = get_be32(pb);

            codec->directpred = get_be32(pb);

            break;

        case CODEC_TYPE_AUDIO:

            codec->sample_rate = get_be32(pb);

            codec->channels = get_le16(pb);

            codec->frame_size = get_le16(pb);

            codec->sample_fmt = get_le16(pb);

            break;

        default:

            goto fail;

        }

        if (codec->flags & CODEC_FLAG_GLOBAL_HEADER) {

            codec->extradata_size = get_be32(pb);

            codec->extradata = av_malloc(codec->extradata_size);

            if (!codec->extradata)

                return AVERROR(ENOMEM);

            get_buffer(pb, codec->extradata, codec->extradata_size);

        }

    }



    /* get until end of block reached */

    while ((url_ftell(pb) % ffm->packet_size) != 0)

        get_byte(pb);



    /* init packet demux */

    ffm->packet_ptr = ffm->packet;

    ffm->packet_end = ffm->packet;

    ffm->frame_offset = 0;

    ffm->dts = 0;

    ffm->read_state = READ_HEADER;

    ffm->first_packet = 1;

    return 0;

 fail:

    for(i=0;i<s->nb_streams;i++) {

        st = s->streams[i];

        if (st) {

            av_free(st);

        }

    }

    return -1;

}

static int svq3_decode_frame(AVCodecContext *avctx,

                             void *data, int *data_size,

                             AVPacket *avpkt)

{

    SVQ3Context *svq3 = avctx->priv_data;

    H264Context *h = &svq3->h;

    MpegEncContext *s = &h->s;

    int buf_size = avpkt->size;

    int m, mb_type, left;

    uint8_t *buf;



    /* special case for last picture */

    if (buf_size == 0) {

        if (s->next_picture_ptr && !s->low_delay) {

            *(AVFrame *) data = *(AVFrame *) &s->next_picture;

            s->next_picture_ptr = NULL;

            *data_size = sizeof(AVFrame);

        }

        return 0;

    }



    s->mb_x = s->mb_y = h->mb_xy = 0;



    if (svq3->watermark_key) {

        svq3->buf = av_fast_realloc(svq3->buf, &svq3->buf_size,

                                    buf_size+FF_INPUT_BUFFER_PADDING_SIZE);

        if (!svq3->buf)

            return AVERROR(ENOMEM);

        memcpy(svq3->buf, avpkt->data, buf_size);

        buf = svq3->buf;

    } else {

        buf = avpkt->data;

    }



    init_get_bits(&s->gb, buf, 8*buf_size);



    if (svq3_decode_slice_header(avctx))

        return -1;



    s->pict_type = h->slice_type;

    s->picture_number = h->slice_num;



    if (avctx->debug&FF_DEBUG_PICT_INFO){

        av_log(h->s.avctx, AV_LOG_DEBUG, "%c hpel:%d, tpel:%d aqp:%d qp:%d, slice_num:%02X\n",

               av_get_picture_type_char(s->pict_type), svq3->halfpel_flag, svq3->thirdpel_flag,

               s->adaptive_quant, s->qscale, h->slice_num);

    }



    /* for skipping the frame */

    s->current_picture.pict_type = s->pict_type;

    s->current_picture.key_frame = (s->pict_type == AV_PICTURE_TYPE_I);



    /* Skip B-frames if we do not have reference frames. */

    if (s->last_picture_ptr == NULL && s->pict_type == AV_PICTURE_TYPE_B)

        return 0;

    if (  (avctx->skip_frame >= AVDISCARD_NONREF && s->pict_type == AV_PICTURE_TYPE_B)

        ||(avctx->skip_frame >= AVDISCARD_NONKEY && s->pict_type != AV_PICTURE_TYPE_I)

        || avctx->skip_frame >= AVDISCARD_ALL)

        return 0;



    if (s->next_p_frame_damaged) {

        if (s->pict_type == AV_PICTURE_TYPE_B)

            return 0;

        else

            s->next_p_frame_damaged = 0;

    }



    if (ff_h264_frame_start(h) < 0)

        return -1;



    if (s->pict_type == AV_PICTURE_TYPE_B) {

        h->frame_num_offset = (h->slice_num - h->prev_frame_num);



        if (h->frame_num_offset < 0) {

            h->frame_num_offset += 256;

        }

        if (h->frame_num_offset == 0 || h->frame_num_offset >= h->prev_frame_num_offset) {

            av_log(h->s.avctx, AV_LOG_ERROR, "error in B-frame picture id\n");

            return -1;

        }

    } else {

        h->prev_frame_num = h->frame_num;

        h->frame_num = h->slice_num;

        h->prev_frame_num_offset = (h->frame_num - h->prev_frame_num);



        if (h->prev_frame_num_offset < 0) {

            h->prev_frame_num_offset += 256;

        }

    }



    for (m = 0; m < 2; m++){

        int i;

        for (i = 0; i < 4; i++){

            int j;

            for (j = -1; j < 4; j++)

                h->ref_cache[m][scan8[0] + 8*i + j]= 1;

            if (i < 3)

                h->ref_cache[m][scan8[0] + 8*i + j]= PART_NOT_AVAILABLE;

        }

    }



    for (s->mb_y = 0; s->mb_y < s->mb_height; s->mb_y++) {

        for (s->mb_x = 0; s->mb_x < s->mb_width; s->mb_x++) {

            h->mb_xy = s->mb_x + s->mb_y*s->mb_stride;



            if ( (get_bits_count(&s->gb) + 7) >= s->gb.size_in_bits &&

                ((get_bits_count(&s->gb) & 7) == 0 || show_bits(&s->gb, (-get_bits_count(&s->gb) & 7)) == 0)) {



                skip_bits(&s->gb, svq3->next_slice_index - get_bits_count(&s->gb));

                s->gb.size_in_bits = 8*buf_size;



                if (svq3_decode_slice_header(avctx))

                    return -1;



                /* TODO: support s->mb_skip_run */

            }



            mb_type = svq3_get_ue_golomb(&s->gb);



            if (s->pict_type == AV_PICTURE_TYPE_I) {

                mb_type += 8;

            } else if (s->pict_type == AV_PICTURE_TYPE_B && mb_type >= 4) {

                mb_type += 4;

            }

            if (mb_type > 33 || svq3_decode_mb(svq3, mb_type)) {

                av_log(h->s.avctx, AV_LOG_ERROR, "error while decoding MB %d %d\n", s->mb_x, s->mb_y);

                return -1;

            }



            if (mb_type != 0) {

                ff_h264_hl_decode_mb (h);

            }



            if (s->pict_type != AV_PICTURE_TYPE_B && !s->low_delay) {

                s->current_picture.mb_type[s->mb_x + s->mb_y*s->mb_stride] =

                    (s->pict_type == AV_PICTURE_TYPE_P && mb_type < 8) ? (mb_type - 1) : -1;

            }

        }



        ff_draw_horiz_band(s, 16*s->mb_y, 16);

    }



    left = buf_size*8 - get_bits_count(&s->gb);



    if (s->mb_y != s->mb_height || s->mb_x != s->mb_width) {

        av_log(avctx, AV_LOG_INFO, "frame num %d incomplete pic x %d y %d left %d\n", avctx->frame_number, s->mb_y, s->mb_x, left);

        //av_hex_dump(stderr, buf+buf_size-8, 8);

    }



    if (left < 0) {

        av_log(avctx, AV_LOG_ERROR, "frame num %d left %d\n", avctx->frame_number, left);

        return -1;

    }



    MPV_frame_end(s);



    if (s->pict_type == AV_PICTURE_TYPE_B || s->low_delay) {

        *(AVFrame *) data = *(AVFrame *) &s->current_picture;

    } else {

        *(AVFrame *) data = *(AVFrame *) &s->last_picture;

    }



    /* Do not output the last pic after seeking. */

    if (s->last_picture_ptr || s->low_delay) {

        *data_size = sizeof(AVFrame);

    }



    return buf_size;

}

static int ffm_read_header(AVFormatContext *s)

{

    FFMContext *ffm = s->priv_data;

    AVStream *st;

    AVIOContext *pb = s->pb;

    AVCodecContext *codec;

    int i, nb_streams;

    uint32_t tag;



    /* header */

    tag = avio_rl32(pb);

    if (tag == MKTAG('F', 'F', 'M', '2'))

        return ffm2_read_header(s);

    if (tag != MKTAG('F', 'F', 'M', '1'))

        goto fail;

    ffm->packet_size = avio_rb32(pb);

    if (ffm->packet_size != FFM_PACKET_SIZE)

        goto fail;

    ffm->write_index = avio_rb64(pb);

    /* get also filesize */

    if (pb->seekable) {

        ffm->file_size = avio_size(pb);

        if (ffm->write_index && 0)

            adjust_write_index(s);

    } else {

        ffm->file_size = (UINT64_C(1) << 63) - 1;

    }



    nb_streams = avio_rb32(pb);

    avio_rb32(pb); /* total bitrate */

    /* read each stream */

    for(i=0;i<nb_streams;i++) {

        char rc_eq_buf[128];



        st = avformat_new_stream(s, NULL);

        if (!st)

            goto fail;



        avpriv_set_pts_info(st, 64, 1, 1000000);



        codec = st->codec;

        /* generic info */

        codec->codec_id = avio_rb32(pb);

        codec->codec_type = avio_r8(pb); /* codec_type */

        codec->bit_rate = avio_rb32(pb);

        codec->flags = avio_rb32(pb);

        codec->flags2 = avio_rb32(pb);

        codec->debug = avio_rb32(pb);

        /* specific info */

        switch(codec->codec_type) {

        case AVMEDIA_TYPE_VIDEO:

            codec->time_base.num = avio_rb32(pb);

            codec->time_base.den = avio_rb32(pb);

            codec->width = avio_rb16(pb);

            codec->height = avio_rb16(pb);

            codec->gop_size = avio_rb16(pb);

            codec->pix_fmt = avio_rb32(pb);

            codec->qmin = avio_r8(pb);

            codec->qmax = avio_r8(pb);

            codec->max_qdiff = avio_r8(pb);

            codec->qcompress = avio_rb16(pb) / 10000.0;

            codec->qblur = avio_rb16(pb) / 10000.0;

            codec->bit_rate_tolerance = avio_rb32(pb);

            avio_get_str(pb, INT_MAX, rc_eq_buf, sizeof(rc_eq_buf));

            codec->rc_eq = av_strdup(rc_eq_buf);

            codec->rc_max_rate = avio_rb32(pb);

            codec->rc_min_rate = avio_rb32(pb);

            codec->rc_buffer_size = avio_rb32(pb);

            codec->i_quant_factor = av_int2double(avio_rb64(pb));

            codec->b_quant_factor = av_int2double(avio_rb64(pb));

            codec->i_quant_offset = av_int2double(avio_rb64(pb));

            codec->b_quant_offset = av_int2double(avio_rb64(pb));

            codec->dct_algo = avio_rb32(pb);

            codec->strict_std_compliance = avio_rb32(pb);

            codec->max_b_frames = avio_rb32(pb);

            codec->mpeg_quant = avio_rb32(pb);

            codec->intra_dc_precision = avio_rb32(pb);

            codec->me_method = avio_rb32(pb);

            codec->mb_decision = avio_rb32(pb);

            codec->nsse_weight = avio_rb32(pb);

            codec->frame_skip_cmp = avio_rb32(pb);

            codec->rc_buffer_aggressivity = av_int2double(avio_rb64(pb));

            codec->codec_tag = avio_rb32(pb);

            codec->thread_count = avio_r8(pb);

            codec->coder_type = avio_rb32(pb);

            codec->me_cmp = avio_rb32(pb);

            codec->me_subpel_quality = avio_rb32(pb);

            codec->me_range = avio_rb32(pb);

            codec->keyint_min = avio_rb32(pb);

            codec->scenechange_threshold = avio_rb32(pb);

            codec->b_frame_strategy = avio_rb32(pb);

            codec->qcompress = av_int2double(avio_rb64(pb));

            codec->qblur = av_int2double(avio_rb64(pb));

            codec->max_qdiff = avio_rb32(pb);

            codec->refs = avio_rb32(pb);

            break;

        case AVMEDIA_TYPE_AUDIO:

            codec->sample_rate = avio_rb32(pb);

            codec->channels = avio_rl16(pb);

            codec->frame_size = avio_rl16(pb);

            break;

        default:

            goto fail;

        }

        if (codec->flags & CODEC_FLAG_GLOBAL_HEADER) {

            if (ff_get_extradata(codec, pb, avio_rb32(pb)) < 0)

                return AVERROR(ENOMEM);

        }

    }



    /* get until end of block reached */

    while ((avio_tell(pb) % ffm->packet_size) != 0)

        avio_r8(pb);



    /* init packet demux */

    ffm->packet_ptr = ffm->packet;

    ffm->packet_end = ffm->packet;

    ffm->frame_offset = 0;

    ffm->dts = 0;

    ffm->read_state = READ_HEADER;

    ffm->first_packet = 1;

    return 0;

 fail:

    ffm_close(s);

    return -1;

}

static void serial_ioport_write(void *opaque, uint32_t addr, uint32_t val)

{

    SerialState *s = opaque;

    unsigned char ch;



    addr &= 7;

#ifdef DEBUG_SERIAL

    printf("serial: write addr=0x%02x val=0x%02x\n", addr, val);

#endif

    switch(addr) {

    default:

    case 0:

        if (s->lcr & UART_LCR_DLAB) {

            s->divider = (s->divider & 0xff00) | val;

            serial_update_parameters(s);

        } else {

            s->thr_ipending = 0;

            s->lsr &= ~UART_LSR_THRE;

            serial_update_irq(s);

            ch = val;

            if (!(s->mcr & UART_MCR_LOOP)) {

                /* when not in loopback mode, send the char */

                qemu_chr_write(s->chr, &ch, 1);

            } else {

                /* in loopback mode, say that we just received a char */

                serial_receive_byte(s, ch);

            }

            if (s->tx_burst > 0) {

                s->tx_burst--;

                serial_tx_done(s);

            } else if (s->tx_burst == 0) {

                s->tx_burst--;

                qemu_mod_timer(s->tx_timer, qemu_get_clock(vm_clock) +

                               ticks_per_sec * THROTTLE_TX_INTERVAL / 1000);

            }

        }

        break;

    case 1:

        if (s->lcr & UART_LCR_DLAB) {

            s->divider = (s->divider & 0x00ff) | (val << 8);

            serial_update_parameters(s);

        } else {

            s->ier = val & 0x0f;

            if (s->lsr & UART_LSR_THRE) {

                s->thr_ipending = 1;

            }

            serial_update_irq(s);

        }

        break;

    case 2:

        break;

    case 3:

        {

            int break_enable;

            s->lcr = val;

            serial_update_parameters(s);

            break_enable = (val >> 6) & 1;

            if (break_enable != s->last_break_enable) {

                s->last_break_enable = break_enable;

                qemu_chr_ioctl(s->chr, CHR_IOCTL_SERIAL_SET_BREAK,

                               &break_enable);

            }

        }

        break;

    case 4:

        s->mcr = val & 0x1f;

        break;

    case 5:

        break;

    case 6:

        break;

    case 7:

        s->scr = val;

        break;

    }

}

static int av_encode(AVFormatContext **output_files,
                     int nb_output_files,
                     AVFormatContext **input_files,
                     int nb_input_files,
                     AVStreamMap *stream_maps, int nb_stream_maps)
{
    int ret, i, j, k, n, nb_istreams = 0, nb_ostreams = 0, pts_set;
    AVFormatContext *is, *os;
