static int output_frame(AVFilterLink *outlink, int need_request)

{

    AVFilterContext *ctx = outlink->src;

    MixContext      *s = ctx->priv;

    AVFrame *out_buf, *in_buf;

    int nb_samples, ns, ret, i;



    ret = calc_active_inputs(s);

    if (ret < 0)

        return ret;



    if (s->input_state[0] & INPUT_ON) {

        /* first input live: use the corresponding frame size */

        nb_samples = frame_list_next_frame_size(s->frame_list);

        for (i = 1; i < s->nb_inputs; i++) {

            if (s->input_state[i] & INPUT_ON) {

                ns = av_audio_fifo_size(s->fifos[i]);

                if (ns < nb_samples) {

                    if (!(s->input_state[i] & INPUT_EOF))

                        /* unclosed input with not enough samples */

                        return need_request ? ff_request_frame(ctx->inputs[i]) : 0;

                    /* closed input to drain */

                    nb_samples = ns;

                }

            }

        }

    } else {

        /* first input closed: use the available samples */

        nb_samples = INT_MAX;

        for (i = 1; i < s->nb_inputs; i++) {

            if (s->input_state[i] & INPUT_ON) {

                ns = av_audio_fifo_size(s->fifos[i]);

                nb_samples = FFMIN(nb_samples, ns);

            }

        }

        if (nb_samples == INT_MAX)

            return AVERROR_EOF;

    }



    s->next_pts = frame_list_next_pts(s->frame_list);

    frame_list_remove_samples(s->frame_list, nb_samples);



    calculate_scales(s, nb_samples);



    if (nb_samples == 0)

        return 0;



    out_buf = ff_get_audio_buffer(outlink, nb_samples);

    if (!out_buf)

        return AVERROR(ENOMEM);



    in_buf = ff_get_audio_buffer(outlink, nb_samples);

    if (!in_buf) {

        av_frame_free(&out_buf);

        return AVERROR(ENOMEM);

    }



    for (i = 0; i < s->nb_inputs; i++) {

        if (s->input_state[i] & INPUT_ON) {

            int planes, plane_size, p;



            av_audio_fifo_read(s->fifos[i], (void **)in_buf->extended_data,

                               nb_samples);



            planes     = s->planar ? s->nb_channels : 1;

            plane_size = nb_samples * (s->planar ? 1 : s->nb_channels);

            plane_size = FFALIGN(plane_size, 16);



            if (out_buf->format == AV_SAMPLE_FMT_FLT ||

                out_buf->format == AV_SAMPLE_FMT_FLTP) {

                for (p = 0; p < planes; p++) {

                    s->fdsp->vector_fmac_scalar((float *)out_buf->extended_data[p],

                                                (float *) in_buf->extended_data[p],

                                                s->input_scale[i], plane_size);

                }

            } else {

                for (p = 0; p < planes; p++) {

                    s->fdsp->vector_dmac_scalar((double *)out_buf->extended_data[p],

                                                (double *) in_buf->extended_data[p],

                                                s->input_scale[i], plane_size);

                }

            }

        }

    }

    av_frame_free(&in_buf);



    out_buf->pts = s->next_pts;

    if (s->next_pts != AV_NOPTS_VALUE)

        s->next_pts += nb_samples;



    return ff_filter_frame(outlink, out_buf);

}

static int handle_secondary_tcp_pkt(NetFilterState *nf,

                                    Connection *conn,

                                    Packet *pkt)

{

    struct tcphdr *tcp_pkt;



    tcp_pkt = (struct tcphdr *)pkt->transport_header;



    if (trace_event_get_state(TRACE_COLO_FILTER_REWRITER_DEBUG)) {

        char *sdebug, *ddebug;

        sdebug = strdup(inet_ntoa(pkt->ip->ip_src));

        ddebug = strdup(inet_ntoa(pkt->ip->ip_dst));

        trace_colo_filter_rewriter_pkt_info(__func__, sdebug, ddebug,

                    ntohl(tcp_pkt->th_seq), ntohl(tcp_pkt->th_ack),

                    tcp_pkt->th_flags);

        trace_colo_filter_rewriter_conn_offset(conn->offset);

        g_free(sdebug);

        g_free(ddebug);

    }



    if (((tcp_pkt->th_flags & (TH_ACK | TH_SYN)) == (TH_ACK | TH_SYN))) {

        /*

         * save offset = secondary_seq and then

         * in handle_primary_tcp_pkt make offset

         * = secondary_seq - primary_seq

         */

        conn->offset = ntohl(tcp_pkt->th_seq);

    }



    if ((tcp_pkt->th_flags & (TH_ACK | TH_SYN)) == TH_ACK) {

        /* handle packets to the primary from the secondary*/

        tcp_pkt->th_seq = htonl(ntohl(tcp_pkt->th_seq) - conn->offset);



        net_checksum_calculate((uint8_t *)pkt->data, pkt->size);

    }



    return 0;

}

int nbd_trip(BlockDriverState *bs, int csock, off_t size,

             uint64_t dev_offset, uint32_t nbdflags,

             uint8_t *data)

{

    struct nbd_request request;

    struct nbd_reply reply;

    int ret;



    TRACE("Reading request.");



    if (nbd_receive_request(csock, &request) == -1)

        return -1;



    if (request.len > NBD_BUFFER_SIZE) {

        LOG("len (%u) is larger than max len (%u)",

            request.len, NBD_BUFFER_SIZE);

        errno = EINVAL;

        return -1;

    }



    if ((request.from + request.len) < request.from) {

        LOG("integer overflow detected! "

            "you're probably being attacked");

        errno = EINVAL;

        return -1;

    }



    if ((request.from + request.len) > size) {

            LOG("From: %" PRIu64 ", Len: %u, Size: %" PRIu64

            ", Offset: %" PRIu64 "\n",

                    request.from, request.len, (uint64_t)size, dev_offset);

        LOG("requested operation past EOF--bad client?");

        errno = EINVAL;

        return -1;

    }



    TRACE("Decoding type");



    reply.handle = request.handle;

    reply.error = 0;



    switch (request.type & NBD_CMD_MASK_COMMAND) {

    case NBD_CMD_READ:

        TRACE("Request type is READ");



        ret = bdrv_read(bs, (request.from + dev_offset) / 512,

                        data, request.len / 512);

        if (ret < 0) {

            LOG("reading from file failed");

            reply.error = -ret;

            request.len = 0;

        }



        TRACE("Read %u byte(s)", request.len);

        if (nbd_do_send_reply(csock, &reply, data, request.len) < 0)

            return -1;

        break;

    case NBD_CMD_WRITE:

        TRACE("Request type is WRITE");



        TRACE("Reading %u byte(s)", request.len);



        if (read_sync(csock, data, request.len) != request.len) {

            LOG("reading from socket failed");

            errno = EINVAL;

            return -1;

        }



        if (nbdflags & NBD_FLAG_READ_ONLY) {

            TRACE("Server is read-only, return error");

            reply.error = 1;

        } else {

            TRACE("Writing to device");



            ret = bdrv_write(bs, (request.from + dev_offset) / 512,

                             data, request.len / 512);

            if (ret < 0) {

                LOG("writing to file failed");

                reply.error = -ret;

                request.len = 0;

            }



            if (request.type & NBD_CMD_FLAG_FUA) {

                ret = bdrv_flush(bs);

                if (ret < 0) {

                    LOG("flush failed");

                    reply.error = -ret;

                }

            }

        }



        if (nbd_do_send_reply(csock, &reply, NULL, 0) < 0)

            return -1;

        break;

    case NBD_CMD_DISC:

        TRACE("Request type is DISCONNECT");

        errno = 0;

        return 1;

    case NBD_CMD_FLUSH:

        TRACE("Request type is FLUSH");



        ret = bdrv_flush(bs);

        if (ret < 0) {

            LOG("flush failed");

            reply.error = -ret;

        }



        if (nbd_do_send_reply(csock, &reply, NULL, 0) < 0)

            return -1;

        break;

    case NBD_CMD_TRIM:

        TRACE("Request type is TRIM");

        ret = bdrv_discard(bs, (request.from + dev_offset) / 512,

                           request.len / 512);

        if (ret < 0) {

            LOG("discard failed");

            reply.error = -ret;

        }

        if (nbd_do_send_reply(csock, &reply, NULL, 0) < 0)

            return -1;

        break;

    default:

        LOG("invalid request type (%u) received", request.type);

        errno = EINVAL;

        return -1;

    }



    TRACE("Request/Reply complete");



    return 0;

}

static inline void idct4col_put(uint8_t *dest, int line_size, const DCTELEM *col)

{

    int c0, c1, c2, c3, a0, a1, a2, a3;

    const uint8_t *cm = ff_cropTbl + MAX_NEG_CROP;



    a0 = col[8*0];

    a1 = col[8*2];

    a2 = col[8*4];

    a3 = col[8*6];

    c0 = ((a0 + a2) << (CN_SHIFT - 1)) + (1 << (C_SHIFT - 1));

    c2 = ((a0 - a2) << (CN_SHIFT - 1)) + (1 << (C_SHIFT - 1));

    c1 = a1 * C1 + a3 * C2;

    c3 = a1 * C2 - a3 * C1;

    dest[0] = cm[(c0 + c1) >> C_SHIFT];

    dest += line_size;

    dest[0] = cm[(c2 + c3) >> C_SHIFT];

    dest += line_size;

    dest[0] = cm[(c2 - c3) >> C_SHIFT];

    dest += line_size;

    dest[0] = cm[(c0 - c1) >> C_SHIFT];

}

static void mp3_parse_info_tag(AVFormatContext *s, AVStream *st,

                               MPADecodeHeader *c, uint32_t spf)

{

#define LAST_BITS(k, n) ((k) & ((1 << (n)) - 1))

#define MIDDLE_BITS(k, m, n) LAST_BITS((k) >> (m), ((n) - (m)))



    uint16_t crc;

    uint32_t v;



    char version[10];



    uint32_t peak   = 0;

    int32_t  r_gain = INT32_MIN, a_gain = INT32_MIN;



    MP3DecContext *mp3 = s->priv_data;

    static const int64_t xing_offtbl[2][2] = {{32, 17}, {17,9}};

    uint64_t fsize = avio_size(s->pb);



    /* Check for Xing / Info tag */

    avio_skip(s->pb, xing_offtbl[c->lsf == 1][c->nb_channels == 1]);

    v = avio_rb32(s->pb);

    mp3->is_cbr = v == MKBETAG('I', 'n', 'f', 'o');

    if (v != MKBETAG('X', 'i', 'n', 'g') && !mp3->is_cbr)

        return;



    v = avio_rb32(s->pb);

    if (v & XING_FLAG_FRAMES)

        mp3->frames = avio_rb32(s->pb);

    if (v & XING_FLAG_SIZE)

        mp3->header_filesize = avio_rb32(s->pb);

    if (fsize && mp3->header_filesize) {

        uint64_t min, delta;

        min = FFMIN(fsize, mp3->header_filesize);

        delta = FFMAX(fsize, mp3->header_filesize) - min;

        if (fsize > mp3->header_filesize && delta > min >> 4) {

            mp3->frames = 0;

        } else if (delta > min >> 4) {

            av_log(s, AV_LOG_WARNING,

                   "filesize and duration do not match (growing file?)\n");

        }

    }

    if (v & XING_FLAG_TOC)

        read_xing_toc(s, mp3->header_filesize, av_rescale_q(mp3->frames,

                                       (AVRational){spf, c->sample_rate},

                                       st->time_base));

    /* VBR quality */

    if(v & 8)

        avio_skip(s->pb, 4);



    /* Encoder short version string */

    memset(version, 0, sizeof(version));

    avio_read(s->pb, version, 9);



    /* Info Tag revision + VBR method */

    avio_r8(s->pb);



    /* Lowpass filter value */

    avio_r8(s->pb);



    /* ReplayGain peak */

    v    = avio_rb32(s->pb);

    peak = av_rescale(v, 100000, 1 << 23);



    /* Radio ReplayGain */

    v = avio_rb16(s->pb);



    if (MIDDLE_BITS(v, 13, 15) == 1) {

        r_gain = MIDDLE_BITS(v, 0, 8) * 10000;



        if (v & (1 << 9))

            r_gain *= -1;

    }



    /* Audiophile ReplayGain */

    v = avio_rb16(s->pb);



    if (MIDDLE_BITS(v, 13, 15) == 2) {

        a_gain = MIDDLE_BITS(v, 0, 8) * 10000;



        if (v & (1 << 9))

            a_gain *= -1;

    }



    /* Encoding flags + ATH Type */

    avio_r8(s->pb);



    /* if ABR {specified bitrate} else {minimal bitrate} */

    avio_r8(s->pb);



    /* Encoder delays */

    v= avio_rb24(s->pb);

    if(AV_RB32(version) == MKBETAG('L', 'A', 'M', 'E')

        || AV_RB32(version) == MKBETAG('L', 'a', 'v', 'f')) {



        mp3->start_pad = v>>12;

        mp3->  end_pad = v&4095;

        st->skip_samples = mp3->start_pad + 528 + 1;

        if (mp3->frames)

            st->end_discard_sample = -mp3->end_pad + 528 + 1 + mp3->frames * (int64_t)spf;

        if (!st->start_time)

            st->start_time = av_rescale_q(st->skip_samples,

                                            (AVRational){1, c->sample_rate},

                                            st->time_base);

        av_log(s, AV_LOG_DEBUG, "pad %d %d\n", mp3->start_pad, mp3->  end_pad);

    }



    /* Misc */

    avio_r8(s->pb);



    /* MP3 gain */

    avio_r8(s->pb);



    /* Preset and surround info */

    avio_rb16(s->pb);



    /* Music length */

    avio_rb32(s->pb);



    /* Music CRC */

    avio_rb16(s->pb);



    /* Info Tag CRC */

    crc = ffio_get_checksum(s->pb);

    v   = avio_rb16(s->pb);



    if (v == crc) {

        ff_replaygain_export_raw(st, r_gain, peak, a_gain, 0);

        av_dict_set(&st->metadata, "encoder", version, 0);

    }

}

