int ff_vda_create_decoder(struct vda_context *vda_ctx,

                          uint8_t *extradata,

                          int extradata_size)

{

    OSStatus status = kVDADecoderNoErr;

    CFNumberRef height;

    CFNumberRef width;

    CFNumberRef format;

    CFDataRef avc_data;

    CFMutableDictionaryRef config_info;

    CFMutableDictionaryRef buffer_attributes;

    CFMutableDictionaryRef io_surface_properties;

    CFNumberRef cv_pix_fmt;



    /* Each VCL NAL in the bistream sent to the decoder

     * is preceded by a 4 bytes length header.

     * Change the avcC atom header if needed, to signal headers of 4 bytes. */

    if (extradata_size >= 4 && (extradata[4] & 0x03) != 0x03) {

        uint8_t *rw_extradata;



        if (!(rw_extradata = av_malloc(extradata_size)))

            return AVERROR(ENOMEM);



        memcpy(rw_extradata, extradata, extradata_size);



        rw_extradata[4] |= 0x03;



        avc_data = CFDataCreate(kCFAllocatorDefault, rw_extradata, extradata_size);



        av_freep(&rw_extradata);

    } else {

        avc_data = CFDataCreate(kCFAllocatorDefault, extradata, extradata_size);

    }



    config_info = CFDictionaryCreateMutable(kCFAllocatorDefault,

                                            4,

                                            &kCFTypeDictionaryKeyCallBacks,

                                            &kCFTypeDictionaryValueCallBacks);



    height   = CFNumberCreate(kCFAllocatorDefault, kCFNumberSInt32Type, &vda_ctx->height);

    width    = CFNumberCreate(kCFAllocatorDefault, kCFNumberSInt32Type, &vda_ctx->width);

    format   = CFNumberCreate(kCFAllocatorDefault, kCFNumberSInt32Type, &vda_ctx->format);



    CFDictionarySetValue(config_info, kVDADecoderConfiguration_Height, height);

    CFDictionarySetValue(config_info, kVDADecoderConfiguration_Width, width);

    CFDictionarySetValue(config_info, kVDADecoderConfiguration_SourceFormat, format);

    CFDictionarySetValue(config_info, kVDADecoderConfiguration_avcCData, avc_data);



    buffer_attributes = CFDictionaryCreateMutable(kCFAllocatorDefault,

                                                  2,

                                                  &kCFTypeDictionaryKeyCallBacks,

                                                  &kCFTypeDictionaryValueCallBacks);

    io_surface_properties = CFDictionaryCreateMutable(kCFAllocatorDefault,

                                                      0,

                                                      &kCFTypeDictionaryKeyCallBacks,

                                                      &kCFTypeDictionaryValueCallBacks);

    cv_pix_fmt      = CFNumberCreate(kCFAllocatorDefault,

                                     kCFNumberSInt32Type,

                                     &vda_ctx->cv_pix_fmt_type);

    CFDictionarySetValue(buffer_attributes,

                         kCVPixelBufferPixelFormatTypeKey,

                         cv_pix_fmt);

    CFDictionarySetValue(buffer_attributes,

                         kCVPixelBufferIOSurfacePropertiesKey,

                         io_surface_properties);



    status = VDADecoderCreate(config_info,

                              buffer_attributes,

                              vda_decoder_callback,

                              vda_ctx,

                              &vda_ctx->decoder);



    CFRelease(height);

    CFRelease(width);

    CFRelease(format);

    CFRelease(avc_data);

    CFRelease(config_info);

    CFRelease(io_surface_properties);

    CFRelease(cv_pix_fmt);

    CFRelease(buffer_attributes);



    return status;

}

static int nbd_negotiate_options(NBDClient *client, uint16_t myflags,

                                 Error **errp)

{

    uint32_t flags;

    bool fixedNewstyle = false;

    bool no_zeroes = false;



    /* Client sends:

        [ 0 ..   3]   client flags



       Then we loop until NBD_OPT_EXPORT_NAME or NBD_OPT_GO:

        [ 0 ..   7]   NBD_OPTS_MAGIC

        [ 8 ..  11]   NBD option

        [12 ..  15]   Data length

        ...           Rest of request



        [ 0 ..   7]   NBD_OPTS_MAGIC

        [ 8 ..  11]   Second NBD option

        [12 ..  15]   Data length

        ...           Rest of request

    */



    if (nbd_read(client->ioc, &flags, sizeof(flags), errp) < 0) {

        error_prepend(errp, "read failed: ");

        return -EIO;

    }

    be32_to_cpus(&flags);

    trace_nbd_negotiate_options_flags(flags);

    if (flags & NBD_FLAG_C_FIXED_NEWSTYLE) {

        fixedNewstyle = true;

        flags &= ~NBD_FLAG_C_FIXED_NEWSTYLE;

    }

    if (flags & NBD_FLAG_C_NO_ZEROES) {

        no_zeroes = true;

        flags &= ~NBD_FLAG_C_NO_ZEROES;

    }

    if (flags != 0) {

        error_setg(errp, "Unknown client flags 0x%" PRIx32 " received", flags);

        return -EINVAL;

    }



    while (1) {

        int ret;

        uint32_t option, length;

        uint64_t magic;



        if (nbd_read(client->ioc, &magic, sizeof(magic), errp) < 0) {

            error_prepend(errp, "read failed: ");

            return -EINVAL;

        }

        magic = be64_to_cpu(magic);

        trace_nbd_negotiate_options_check_magic(magic);

        if (magic != NBD_OPTS_MAGIC) {

            error_setg(errp, "Bad magic received");

            return -EINVAL;

        }



        if (nbd_read(client->ioc, &option,

                     sizeof(option), errp) < 0) {

            error_prepend(errp, "read failed: ");

            return -EINVAL;

        }

        option = be32_to_cpu(option);



        if (nbd_read(client->ioc, &length, sizeof(length), errp) < 0) {

            error_prepend(errp, "read failed: ");

            return -EINVAL;

        }

        length = be32_to_cpu(length);



        trace_nbd_negotiate_options_check_option(option,

                                                 nbd_opt_lookup(option));

        if (client->tlscreds &&

            client->ioc == (QIOChannel *)client->sioc) {

            QIOChannel *tioc;

            if (!fixedNewstyle) {

                error_setg(errp, "Unsupported option 0x%" PRIx32, option);

                return -EINVAL;

            }

            switch (option) {

            case NBD_OPT_STARTTLS:

                tioc = nbd_negotiate_handle_starttls(client, length, errp);

                if (!tioc) {

                    return -EIO;

                }

                object_unref(OBJECT(client->ioc));

                client->ioc = QIO_CHANNEL(tioc);

                break;



            case NBD_OPT_EXPORT_NAME:

                /* No way to return an error to client, so drop connection */

                error_setg(errp, "Option 0x%x not permitted before TLS",

                           option);

                return -EINVAL;



            default:

                if (nbd_drop(client->ioc, length, errp) < 0) {

                    return -EIO;

                }

                ret = nbd_negotiate_send_rep_err(client->ioc,

                                                 NBD_REP_ERR_TLS_REQD,

                                                 option, errp,

                                                 "Option 0x%" PRIx32

                                                 "not permitted before TLS",

                                                 option);

                if (ret < 0) {

                    return ret;

                }

                /* Let the client keep trying, unless they asked to

                 * quit. In this mode, we've already sent an error, so

                 * we can't ack the abort.  */

                if (option == NBD_OPT_ABORT) {

                    return 1;

                }

                break;

            }

        } else if (fixedNewstyle) {

            switch (option) {

            case NBD_OPT_LIST:

                ret = nbd_negotiate_handle_list(client, length, errp);

                if (ret < 0) {

                    return ret;

                }

                break;



            case NBD_OPT_ABORT:

                /* NBD spec says we must try to reply before

                 * disconnecting, but that we must also tolerate

                 * guests that don't wait for our reply. */

                nbd_negotiate_send_rep(client->ioc, NBD_REP_ACK, option, NULL);

                return 1;



            case NBD_OPT_EXPORT_NAME:

                return nbd_negotiate_handle_export_name(client, length,

                                                        myflags, no_zeroes,

                                                        errp);



            case NBD_OPT_INFO:

            case NBD_OPT_GO:

                ret = nbd_negotiate_handle_info(client, length, option,

                                                myflags, errp);

                if (ret == 1) {

                    assert(option == NBD_OPT_GO);

                    return 0;

                }

                if (ret) {

                    return ret;

                }

                break;



            case NBD_OPT_STARTTLS:

                if (nbd_drop(client->ioc, length, errp) < 0) {

                    return -EIO;

                }

                if (client->tlscreds) {

                    ret = nbd_negotiate_send_rep_err(client->ioc,

                                                     NBD_REP_ERR_INVALID,

                                                     option, errp,

                                                     "TLS already enabled");

                } else {

                    ret = nbd_negotiate_send_rep_err(client->ioc,

                                                     NBD_REP_ERR_POLICY,

                                                     option, errp,

                                                     "TLS not configured");

                }

                if (ret < 0) {

                    return ret;

                }

                break;

            default:

                if (nbd_drop(client->ioc, length, errp) < 0) {

                    return -EIO;

                }

                ret = nbd_negotiate_send_rep_err(client->ioc,

                                                 NBD_REP_ERR_UNSUP,

                                                 option, errp,

                                                 "Unsupported option 0x%"

                                                 PRIx32 " (%s)", option,

                                                 nbd_opt_lookup(option));

                if (ret < 0) {

                    return ret;

                }

                break;

            }

        } else {

            /*

             * If broken new-style we should drop the connection

             * for anything except NBD_OPT_EXPORT_NAME

             */

            switch (option) {

            case NBD_OPT_EXPORT_NAME:

                return nbd_negotiate_handle_export_name(client, length,

                                                        myflags, no_zeroes,

                                                        errp);



            default:

                error_setg(errp, "Unsupported option 0x%" PRIx32 " (%s)",

                           option, nbd_opt_lookup(option));

                return -EINVAL;

            }

        }

    }

}

BlockDriverAIOCB *dma_bdrv_io(

    BlockDriverState *bs, QEMUSGList *sg, uint64_t sector_num,

    DMAIOFunc *io_func, BlockDriverCompletionFunc *cb,

    void *opaque, DMADirection dir)

{

    DMAAIOCB *dbs = qemu_aio_get(&dma_aiocb_info, bs, cb, opaque);



    trace_dma_bdrv_io(dbs, bs, sector_num, (dir == DMA_DIRECTION_TO_DEVICE));



    dbs->acb = NULL;

    dbs->bs = bs;

    dbs->sg = sg;

    dbs->sector_num = sector_num;

    dbs->sg_cur_index = 0;

    dbs->sg_cur_byte = 0;

    dbs->dir = dir;


    dbs->io_func = io_func;

    dbs->bh = NULL;

    qemu_iovec_init(&dbs->iov, sg->nsg);

    dma_bdrv_cb(dbs, 0);

    return &dbs->common;

}

static int local_link(FsContext *ctx, V9fsPath *oldpath,

                      V9fsPath *dirpath, const char *name)

{

    int ret;

    V9fsString newpath;

    char buffer[PATH_MAX], buffer1[PATH_MAX];



    v9fs_string_init(&newpath);

    v9fs_string_sprintf(&newpath, "%s/%s", dirpath->data, name);



    ret = link(rpath(ctx, oldpath->data, buffer),

               rpath(ctx, newpath.data, buffer1));



    /* now link the virtfs_metadata files */

    if (!ret && (ctx->export_flags & V9FS_SM_MAPPED_FILE)) {

        /* Link the .virtfs_metadata files. Create the metada directory */

        ret = local_create_mapped_attr_dir(ctx, newpath.data);

        if (ret < 0) {

            goto err_out;

        }

        ret = link(local_mapped_attr_path(ctx, oldpath->data, buffer),

                   local_mapped_attr_path(ctx, newpath.data, buffer1));

        if (ret < 0 && errno != ENOENT) {

            goto err_out;

        }

    }

err_out:

    v9fs_string_free(&newpath);

    return ret;

}

static void test_cipher_speed(const void *opaque)

{

    QCryptoCipher *cipher;

    Error *err = NULL;

    double total = 0.0;

    size_t chunk_size = (size_t)opaque;

    uint8_t *key = NULL, *iv = NULL;

    uint8_t *plaintext = NULL, *ciphertext = NULL;

    size_t nkey = qcrypto_cipher_get_key_len(QCRYPTO_CIPHER_ALG_AES_128);

    size_t niv = qcrypto_cipher_get_iv_len(QCRYPTO_CIPHER_ALG_AES_128,

                                           QCRYPTO_CIPHER_MODE_CBC);



    key = g_new0(uint8_t, nkey);

    memset(key, g_test_rand_int(), nkey);



    iv = g_new0(uint8_t, niv);

    memset(iv, g_test_rand_int(), niv);



    ciphertext = g_new0(uint8_t, chunk_size);



    plaintext = g_new0(uint8_t, chunk_size);

    memset(plaintext, g_test_rand_int(), chunk_size);



    cipher = qcrypto_cipher_new(QCRYPTO_CIPHER_ALG_AES_128,

                                QCRYPTO_CIPHER_MODE_CBC,

                                key, nkey, &err);

    g_assert(cipher != NULL);



    g_assert(qcrypto_cipher_setiv(cipher,

                                  iv, niv,

                                  &err) == 0);



    g_test_timer_start();

    do {

        g_assert(qcrypto_cipher_encrypt(cipher,

                                        plaintext,

                                        ciphertext,

                                        chunk_size,

                                        &err) == 0);

        total += chunk_size;

    } while (g_test_timer_elapsed() < 5.0);



    total /= 1024 * 1024; /* to MB */



    g_print("cbc(aes128): ");

    g_print("Testing chunk_size %ld bytes ", chunk_size);

    g_print("done: %.2f MB in %.2f secs: ", total, g_test_timer_last());

    g_print("%.2f MB/sec\n", total / g_test_timer_last());



    qcrypto_cipher_free(cipher);

    g_free(plaintext);

    g_free(ciphertext);

    g_free(iv);

    g_free(key);

}

