static bool gen_wsr_ccompare(DisasContext *dc, uint32_t sr, TCGv_i32 v)

{

    uint32_t id = sr - CCOMPARE;

    bool ret = false;



    if (id < dc->config->nccompare) {

        uint32_t int_bit = 1 << dc->config->timerint[id];

        TCGv_i32 tmp = tcg_const_i32(id);



        tcg_gen_mov_i32(cpu_SR[sr], v);

        tcg_gen_andi_i32(cpu_SR[INTSET], cpu_SR[INTSET], ~int_bit);

        if (dc->tb->cflags & CF_USE_ICOUNT) {

            gen_io_start();

        }

        gen_helper_update_ccompare(cpu_env, tmp);

        if (dc->tb->cflags & CF_USE_ICOUNT) {

            gen_io_end();

            gen_jumpi_check_loop_end(dc, 0);

            ret = true;

        }

        tcg_temp_free(tmp);

    }

    return ret;

}

int ff_audio_mix(AudioMix *am, AudioData *src)

{

    int use_generic = 1;

    int len = src->nb_samples;

    int i, j;



    /* determine whether to use the optimized function based on pointer and

       samples alignment in both the input and output */

    if (am->has_optimized_func) {

        int aligned_len = FFALIGN(len, am->samples_align);

        if (!(src->ptr_align % am->ptr_align) &&

            src->samples_align >= aligned_len) {

            len = aligned_len;

            use_generic = 0;

        }

    }

    av_dlog(am->avr, "audio_mix: %d samples - %d to %d channels (%s)\n",

            src->nb_samples, am->in_channels, am->out_channels,

            use_generic ? am->func_descr_generic : am->func_descr);



    if (am->in_matrix_channels && am->out_matrix_channels) {

        uint8_t **data;

        uint8_t *data0[AVRESAMPLE_MAX_CHANNELS];



        if (am->out_matrix_channels < am->out_channels ||

             am->in_matrix_channels <  am->in_channels) {

            for (i = 0, j = 0; i < FFMAX(am->in_channels, am->out_channels); i++) {

                if (am->input_skip[i] || am->output_skip[i] || am->output_zero[i])

                    continue;

                data0[j++] = src->data[i];

            }

            data = data0;

        } else {

            data = src->data;

        }



        if (use_generic)

            am->mix_generic(data, am->matrix, len, am->out_matrix_channels,

                            am->in_matrix_channels);

        else

            am->mix(data, am->matrix, len, am->out_matrix_channels,

                    am->in_matrix_channels);

    }



    if (am->out_matrix_channels < am->out_channels) {

        for (i = 0; i < am->out_channels; i++)

            if (am->output_zero[i])

                av_samples_set_silence(&src->data[i], 0, len, 1, am->fmt);

    }



    ff_audio_data_set_channels(src, am->out_channels);



    return 0;

}

static int sdp_parse_rtpmap(AVCodecContext *codec, RTSPStream *rtsp_st, int payload_type, const char *p)

{

    char buf[256];

    int i;

    AVCodec *c;

    const char *c_name;



    /* Loop into AVRtpDynamicPayloadTypes[] and AVRtpPayloadTypes[] and

       see if we can handle this kind of payload */

    get_word_sep(buf, sizeof(buf), "/", &p);

    if (payload_type >= RTP_PT_PRIVATE) {

        RTPDynamicProtocolHandler *handler= RTPFirstDynamicPayloadHandler;

        while(handler) {

            if (!strcasecmp(buf, handler->enc_name) && (codec->codec_type == handler->codec_type)) {

                codec->codec_id = handler->codec_id;

                rtsp_st->dynamic_handler= handler;

                if(handler->open) {

                    rtsp_st->dynamic_protocol_context= handler->open();

                }

                break;

            }

            handler= handler->next;

        }

    } else {

        /* We are in a standard case ( from http://www.iana.org/assignments/rtp-parameters) */

        /* search into AVRtpPayloadTypes[] */

        codec->codec_id = ff_rtp_codec_id(buf, codec->codec_type);

    }



    c = avcodec_find_decoder(codec->codec_id);

    if (c && c->name)

        c_name = c->name;

    else

        c_name = (char *)NULL;



    if (c_name) {

        get_word_sep(buf, sizeof(buf), "/", &p);

        i = atoi(buf);

        switch (codec->codec_type) {

            case CODEC_TYPE_AUDIO:

                av_log(codec, AV_LOG_DEBUG, " audio codec set to : %s\n", c_name);

                codec->sample_rate = RTSP_DEFAULT_AUDIO_SAMPLERATE;

                codec->channels = RTSP_DEFAULT_NB_AUDIO_CHANNELS;

                if (i > 0) {

                    codec->sample_rate = i;

                    get_word_sep(buf, sizeof(buf), "/", &p);

                    i = atoi(buf);

                    if (i > 0)

                        codec->channels = i;

                    // TODO: there is a bug here; if it is a mono stream, and less than 22000Hz, faad upconverts to stereo and twice the

                    //  frequency.  No problem, but the sample rate is being set here by the sdp line.  Upcoming patch forthcoming. (rdm)

                }

                av_log(codec, AV_LOG_DEBUG, " audio samplerate set to : %i\n", codec->sample_rate);

                av_log(codec, AV_LOG_DEBUG, " audio channels set to : %i\n", codec->channels);

                break;

            case CODEC_TYPE_VIDEO:

                av_log(codec, AV_LOG_DEBUG, " video codec set to : %s\n", c_name);

                break;

            default:

                break;

        }

        return 0;

    }



    return -1;

}

