    }

#endif /* COMPILE_TEMPLATE_MMX */

}

static void mptsas_process_scsi_task_mgmt(MPTSASState *s, MPIMsgSCSITaskMgmt *req)

{

    MPIMsgSCSITaskMgmtReply reply;

    MPIMsgSCSITaskMgmtReply *reply_async;

    int status, count;

    SCSIDevice *sdev;

    SCSIRequest *r, *next;

    BusChild *kid;



    mptsas_fix_scsi_task_mgmt_endianness(req);



    QEMU_BUILD_BUG_ON(MPTSAS_MAX_REQUEST_SIZE < sizeof(*req));

    QEMU_BUILD_BUG_ON(sizeof(s->doorbell_msg) < sizeof(*req));

    QEMU_BUILD_BUG_ON(sizeof(s->doorbell_reply) < sizeof(reply));



    memset(&reply, 0, sizeof(reply));

    reply.TargetID   = req->TargetID;

    reply.Bus        = req->Bus;

    reply.MsgLength  = sizeof(reply) / 4;

    reply.Function   = req->Function;

    reply.TaskType   = req->TaskType;

    reply.MsgContext = req->MsgContext;



    switch (req->TaskType) {

    case MPI_SCSITASKMGMT_TASKTYPE_ABORT_TASK:

    case MPI_SCSITASKMGMT_TASKTYPE_QUERY_TASK:

        status = mptsas_scsi_device_find(s, req->Bus, req->TargetID,

                                         req->LUN, &sdev);

        if (status) {

            reply.IOCStatus = status;

            goto out;

        }

        if (sdev->lun != req->LUN[1]) {

            reply.ResponseCode = MPI_SCSITASKMGMT_RSP_TM_INVALID_LUN;

            goto out;

        }



        QTAILQ_FOREACH_SAFE(r, &sdev->requests, next, next) {

            MPTSASRequest *cmd_req = r->hba_private;

            if (cmd_req && cmd_req->scsi_io.MsgContext == req->TaskMsgContext) {

                break;

            }

        }

        if (r) {

            /*

             * Assert that the request has not been completed yet, we

             * check for it in the loop above.

             */

            assert(r->hba_private);

            if (req->TaskType == MPI_SCSITASKMGMT_TASKTYPE_QUERY_TASK) {

                /* "If the specified command is present in the task set, then

                 * return a service response set to FUNCTION SUCCEEDED".

                 */

                reply.ResponseCode = MPI_SCSITASKMGMT_RSP_TM_SUCCEEDED;

            } else {

                MPTSASCancelNotifier *notifier;



                reply_async = g_memdup(&reply, sizeof(MPIMsgSCSITaskMgmtReply));

                reply_async->IOCLogInfo = INT_MAX;



                count = 1;

                notifier = g_new(MPTSASCancelNotifier, 1);

                notifier->s = s;

                notifier->reply = reply_async;

                notifier->notifier.notify = mptsas_cancel_notify;

                scsi_req_cancel_async(r, &notifier->notifier);

                goto reply_maybe_async;

            }

        }

        break;



    case MPI_SCSITASKMGMT_TASKTYPE_ABRT_TASK_SET:

    case MPI_SCSITASKMGMT_TASKTYPE_CLEAR_TASK_SET:

        status = mptsas_scsi_device_find(s, req->Bus, req->TargetID,

                                         req->LUN, &sdev);

        if (status) {

            reply.IOCStatus = status;

            goto out;

        }

        if (sdev->lun != req->LUN[1]) {

            reply.ResponseCode = MPI_SCSITASKMGMT_RSP_TM_INVALID_LUN;

            goto out;

        }



        reply_async = g_memdup(&reply, sizeof(MPIMsgSCSITaskMgmtReply));

        reply_async->IOCLogInfo = INT_MAX;



        count = 0;

        QTAILQ_FOREACH_SAFE(r, &sdev->requests, next, next) {

            if (r->hba_private) {

                MPTSASCancelNotifier *notifier;



                count++;

                notifier = g_new(MPTSASCancelNotifier, 1);

                notifier->s = s;

                notifier->reply = reply_async;

                notifier->notifier.notify = mptsas_cancel_notify;

                scsi_req_cancel_async(r, &notifier->notifier);

            }

        }



reply_maybe_async:

        if (reply_async->TerminationCount < count) {

            reply_async->IOCLogInfo = count;

            return;

        }


        reply.TerminationCount = count;

        break;



    case MPI_SCSITASKMGMT_TASKTYPE_LOGICAL_UNIT_RESET:

        status = mptsas_scsi_device_find(s, req->Bus, req->TargetID,

                                         req->LUN, &sdev);

        if (status) {

            reply.IOCStatus = status;

            goto out;

        }

        if (sdev->lun != req->LUN[1]) {

            reply.ResponseCode = MPI_SCSITASKMGMT_RSP_TM_INVALID_LUN;

            goto out;

        }

        qdev_reset_all(&sdev->qdev);

        break;



    case MPI_SCSITASKMGMT_TASKTYPE_TARGET_RESET:

        if (req->Bus != 0) {

            reply.IOCStatus = MPI_IOCSTATUS_SCSI_INVALID_BUS;

            goto out;

        }

        if (req->TargetID > s->max_devices) {

            reply.IOCStatus = MPI_IOCSTATUS_SCSI_INVALID_TARGETID;

            goto out;

        }



        QTAILQ_FOREACH(kid, &s->bus.qbus.children, sibling) {

            sdev = SCSI_DEVICE(kid->child);

            if (sdev->channel == 0 && sdev->id == req->TargetID) {

                qdev_reset_all(kid->child);

            }

        }

        break;



    case MPI_SCSITASKMGMT_TASKTYPE_RESET_BUS:

        qbus_reset_all(&s->bus.qbus);

        break;



    default:

        reply.ResponseCode = MPI_SCSITASKMGMT_RSP_TM_NOT_SUPPORTED;

        break;

    }



out:

    mptsas_fix_scsi_task_mgmt_reply_endianness(&reply);

    mptsas_post_reply(s, (MPIDefaultReply *)&reply);

}

static inline void silk_stabilize_lsf(int16_t nlsf[16], int order, const uint16_t min_delta[17])

{

    int pass, i;

    for (pass = 0; pass < 20; pass++) {

        int k, min_diff = 0;

        for (i = 0; i < order+1; i++) {

            int low  = i != 0     ? nlsf[i-1] : 0;

            int high = i != order ? nlsf[i]   : 32768;

            int diff = (high - low) - (min_delta[i]);



            if (diff < min_diff) {

                min_diff = diff;

                k = i;



                if (pass == 20)

                    break;

            }

        }

        if (min_diff == 0) /* no issues; stabilized */

            return;



        /* wiggle one or two LSFs */

        if (k == 0) {

            /* repel away from lower bound */

            nlsf[0] = min_delta[0];

        } else if (k == order) {

            /* repel away from higher bound */

            nlsf[order-1] = 32768 - min_delta[order];

        } else {

            /* repel away from current position */

            int min_center = 0, max_center = 32768, center_val;



            /* lower extent */

            for (i = 0; i < k; i++)

                min_center += min_delta[i];

            min_center += min_delta[k] >> 1;



            /* upper extent */

            for (i = order; i > k; i--)

                max_center -= min_delta[k];

            max_center -= min_delta[k] >> 1;



            /* move apart */

            center_val = nlsf[k - 1] + nlsf[k];

            center_val = (center_val >> 1) + (center_val & 1); // rounded divide by 2

            center_val = FFMIN(max_center, FFMAX(min_center, center_val));



            nlsf[k - 1] = center_val - (min_delta[k] >> 1);

            nlsf[k]     = nlsf[k - 1] + min_delta[k];

        }

    }



    /* resort to the fall-back method, the standard method for LSF stabilization */



    /* sort; as the LSFs should be nearly sorted, use insertion sort */

    for (i = 1; i < order; i++) {

        int j, value = nlsf[i];

        for (j = i - 1; j >= 0 && nlsf[j] > value; j--)

            nlsf[j + 1] = nlsf[j];

        nlsf[j + 1] = value;

    }



    /* push forwards to increase distance */

    if (nlsf[0] < min_delta[0])

        nlsf[0] = min_delta[0];

    for (i = 1; i < order; i++)

        if (nlsf[i] < nlsf[i - 1] + min_delta[i])

            nlsf[i] = nlsf[i - 1] + min_delta[i];



    /* push backwards to increase distance */

    if (nlsf[order-1] > 32768 - min_delta[order])

        nlsf[order-1] = 32768 - min_delta[order];

    for (i = order-2; i >= 0; i--)

        if (nlsf[i] > nlsf[i + 1] - min_delta[i+1])

            nlsf[i] = nlsf[i + 1] - min_delta[i+1];



    return;

}

static void RENAME(extract_odd2)(const uint8_t *src, uint8_t *dst0, uint8_t *dst1, x86_reg count)

{

    dst0+=   count;

    dst1+=   count;

    src += 4*count;

    count= - count;

#if COMPILE_TEMPLATE_MMX

    if(count <= -8) {

        count += 7;

        __asm__ volatile(

            "pcmpeqw       %%mm7, %%mm7        \n\t"

            "psrlw            $8, %%mm7        \n\t"

            "1:                                \n\t"

            "movq -28(%1, %0, 4), %%mm0        \n\t"

            "movq -20(%1, %0, 4), %%mm1        \n\t"

            "movq -12(%1, %0, 4), %%mm2        \n\t"

            "movq  -4(%1, %0, 4), %%mm3        \n\t"

            "psrlw            $8, %%mm0        \n\t"

            "psrlw            $8, %%mm1        \n\t"

            "psrlw            $8, %%mm2        \n\t"

            "psrlw            $8, %%mm3        \n\t"

            "packuswb      %%mm1, %%mm0        \n\t"

            "packuswb      %%mm3, %%mm2        \n\t"

            "movq          %%mm0, %%mm1        \n\t"

            "movq          %%mm2, %%mm3        \n\t"

            "psrlw            $8, %%mm0        \n\t"

            "psrlw            $8, %%mm2        \n\t"

            "pand          %%mm7, %%mm1        \n\t"

            "pand          %%mm7, %%mm3        \n\t"

            "packuswb      %%mm2, %%mm0        \n\t"

            "packuswb      %%mm3, %%mm1        \n\t"

            MOVNTQ"        %%mm0,- 7(%3, %0)   \n\t"

            MOVNTQ"        %%mm1,- 7(%2, %0)   \n\t"

            "add              $8, %0           \n\t"

            " js 1b                            \n\t"

            : "+r"(count)

            : "r"(src), "r"(dst0), "r"(dst1)

        );

        count -= 7;

    }

#endif

    src++;

    while(count<0) {

        dst0[count]= src[4*count+0];

        dst1[count]= src[4*count+2];

        count++;

    }

}

static void setup_frame(int sig, struct target_sigaction *ka,

                        target_sigset_t *set, CPUS390XState *env)

{

    sigframe *frame;

    abi_ulong frame_addr;



    frame_addr = get_sigframe(ka, env, sizeof(*frame));

    qemu_log("%s: frame_addr 0x%llx\n", __FUNCTION__,

             (unsigned long long)frame_addr);

    if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 0)) {

            goto give_sigsegv;

    }



    qemu_log("%s: 1\n", __FUNCTION__);

    if (__put_user(set->sig[0], &frame->sc.oldmask[0])) {

              goto give_sigsegv;

    }



    save_sigregs(env, &frame->sregs);



    __put_user((abi_ulong)(unsigned long)&frame->sregs,

               (abi_ulong *)&frame->sc.sregs);



    /* Set up to return from userspace.  If provided, use a stub

       already in userspace.  */

    if (ka->sa_flags & TARGET_SA_RESTORER) {

            env->regs[14] = (unsigned long)

                    ka->sa_restorer | PSW_ADDR_AMODE;

    } else {

            env->regs[14] = (unsigned long)

                    frame->retcode | PSW_ADDR_AMODE;

            if (__put_user(S390_SYSCALL_OPCODE | TARGET_NR_sigreturn,

                           (uint16_t *)(frame->retcode)))

                    goto give_sigsegv;

    }



    /* Set up backchain. */

    if (__put_user(env->regs[15], (abi_ulong *) frame)) {

            goto give_sigsegv;

    }



    /* Set up registers for signal handler */

    env->regs[15] = frame_addr;

    env->psw.addr = (target_ulong) ka->_sa_handler | PSW_ADDR_AMODE;



    env->regs[2] = sig; //map_signal(sig);

    env->regs[3] = frame_addr += offsetof(typeof(*frame), sc);



    /* We forgot to include these in the sigcontext.

       To avoid breaking binary compatibility, they are passed as args. */

    env->regs[4] = 0; // FIXME: no clue... current->thread.trap_no;

    env->regs[5] = 0; // FIXME: no clue... current->thread.prot_addr;



    /* Place signal number on stack to allow backtrace from handler.  */

    if (__put_user(env->regs[2], (int *) &frame->signo)) {

            goto give_sigsegv;

    }

    unlock_user_struct(frame, frame_addr, 1);

    return;



give_sigsegv:

    qemu_log("%s: give_sigsegv\n", __FUNCTION__);

    unlock_user_struct(frame, frame_addr, 1);

    force_sig(TARGET_SIGSEGV);

}

