static void handle_qmp_command(JSONMessageParser *parser, QList *tokens)

{

    int err;

    QObject *obj;

    QDict *input, *args;

    const mon_cmd_t *cmd;

    Monitor *mon = cur_mon;

    const char *cmd_name, *info_item;



    args = NULL;



    obj = json_parser_parse(tokens, NULL);

    if (!obj) {

        // FIXME: should be triggered in json_parser_parse()

        qerror_report(QERR_JSON_PARSING);

        goto err_out;


        qerror_report(QERR_QMP_BAD_INPUT_OBJECT, "object");

        qobject_decref(obj);

        goto err_out;

    }



    input = qobject_to_qdict(obj);



    mon->mc->id = qdict_get(input, "id");

    qobject_incref(mon->mc->id);



    obj = qdict_get(input, "execute");

    if (!obj) {

        qerror_report(QERR_QMP_BAD_INPUT_OBJECT, "execute");


    } else if (qobject_type(obj) != QTYPE_QSTRING) {

        qerror_report(QERR_QMP_BAD_INPUT_OBJECT_MEMBER, "execute", "string");


    }



    cmd_name = qstring_get_str(qobject_to_qstring(obj));



    if (invalid_qmp_mode(mon, cmd_name)) {

        qerror_report(QERR_COMMAND_NOT_FOUND, cmd_name);


    }



    /*

     * XXX: We need this special case until we get info handlers

     * converted into 'query-' commands

     */

    if (compare_cmd(cmd_name, "info")) {

        qerror_report(QERR_COMMAND_NOT_FOUND, cmd_name);


    } else if (strstart(cmd_name, "query-", &info_item)) {

        cmd = monitor_find_command("info");

        qdict_put_obj(input, "arguments",

                      qobject_from_jsonf("{ 'item': %s }", info_item));

    } else {

        cmd = monitor_find_command(cmd_name);

        if (!cmd || !monitor_handler_ported(cmd)) {

            qerror_report(QERR_COMMAND_NOT_FOUND, cmd_name);


        }

    }



    obj = qdict_get(input, "arguments");

    if (!obj) {

        args = qdict_new();




    } else {

        args = qobject_to_qdict(obj);

        QINCREF(args);

    }



    QDECREF(input);



    err = monitor_check_qmp_args(cmd, args);

    if (err < 0) {

        goto err_out;

    }



    if (monitor_handler_is_async(cmd)) {

        qmp_async_cmd_handler(mon, cmd, args);

    } else {

        monitor_call_handler(mon, cmd, args);

    }

    goto out;



err_input:

    QDECREF(input);

err_out:

    monitor_protocol_emitter(mon, NULL);

out:

    QDECREF(args);

}

static void gen_exts(int ot, TCGv reg)

{

    switch(ot) {

    case OT_BYTE:

        tcg_gen_ext8s_tl(reg, reg);

        break;

    case OT_WORD:

        tcg_gen_ext16s_tl(reg, reg);

        break;

    case OT_LONG:

        tcg_gen_ext32s_tl(reg, reg);

        break;

    default:

        break;

    }

}

static void colo_compare_complete(UserCreatable *uc, Error **errp)

{

    CompareState *s = COLO_COMPARE(uc);

    Chardev *chr;

    char thread_name[64];

    static int compare_id;



    if (!s->pri_indev || !s->sec_indev || !s->outdev) {

        error_setg(errp, "colo compare needs 'primary_in' ,"

                   "'secondary_in','outdev' property set");

        return;

    } else if (!strcmp(s->pri_indev, s->outdev) ||

               !strcmp(s->sec_indev, s->outdev) ||

               !strcmp(s->pri_indev, s->sec_indev)) {

        error_setg(errp, "'indev' and 'outdev' could not be same "

                   "for compare module");

        return;

    }



    if (find_and_check_chardev(&chr, s->pri_indev, errp) ||

        !qemu_chr_fe_init(&s->chr_pri_in, chr, errp)) {

        return;

    }



    if (find_and_check_chardev(&chr, s->sec_indev, errp) ||

        !qemu_chr_fe_init(&s->chr_sec_in, chr, errp)) {

        return;

    }



    if (find_and_check_chardev(&chr, s->outdev, errp) ||

        !qemu_chr_fe_init(&s->chr_out, chr, errp)) {

        return;

    }



    net_socket_rs_init(&s->pri_rs, compare_pri_rs_finalize, s->vnet_hdr);

    net_socket_rs_init(&s->sec_rs, compare_sec_rs_finalize, s->vnet_hdr);



    g_queue_init(&s->conn_list);



    s->connection_track_table = g_hash_table_new_full(connection_key_hash,

                                                      connection_key_equal,

                                                      g_free,

                                                      connection_destroy);



    sprintf(thread_name, "colo-compare %d", compare_id);

    qemu_thread_create(&s->thread, thread_name,

                       colo_compare_thread, s,

                       QEMU_THREAD_JOINABLE);

    compare_id++;



    return;

}

void parse_option_size(const char *name, const char *value,

                       uint64_t *ret, Error **errp)

{

    char *postfix;

    double sizef;



    sizef = strtod(value, &postfix);

    if (sizef < 0 || sizef > UINT64_MAX) {

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE, name,

                   "a non-negative number below 2^64");

        return;

    }

    switch (*postfix) {

    case 'T':

        sizef *= 1024;

        /* fall through */

    case 'G':

        sizef *= 1024;

        /* fall through */

    case 'M':

        sizef *= 1024;

        /* fall through */

    case 'K':

    case 'k':

        sizef *= 1024;

        /* fall through */

    case 'b':

    case '\0':

        *ret = (uint64_t) sizef;

        break;

    default:

        error_setg(errp, QERR_INVALID_PARAMETER_VALUE, name, "a size");

        error_append_hint(errp, "You may use k, M, G or T suffixes for "

                          "kilobytes, megabytes, gigabytes and terabytes.\n");

        return;

    }

}

static void do_fp_st(DisasContext *s, int srcidx, TCGv_i64 tcg_addr, int size)

{

    /* This writes the bottom N bits of a 128 bit wide vector to memory */

    TCGv_i64 tmp = tcg_temp_new_i64();

    tcg_gen_ld_i64(tmp, cpu_env, fp_reg_offset(srcidx, MO_64));

    if (size < 4) {

        tcg_gen_qemu_st_i64(tmp, tcg_addr, get_mem_index(s), MO_TE + size);

    } else {

        TCGv_i64 tcg_hiaddr = tcg_temp_new_i64();

        tcg_gen_qemu_st_i64(tmp, tcg_addr, get_mem_index(s), MO_TEQ);

        tcg_gen_qemu_st64(tmp, tcg_addr, get_mem_index(s));

        tcg_gen_ld_i64(tmp, cpu_env, fp_reg_hi_offset(srcidx));

        tcg_gen_addi_i64(tcg_hiaddr, tcg_addr, 8);

        tcg_gen_qemu_st_i64(tmp, tcg_hiaddr, get_mem_index(s), MO_TEQ);

        tcg_temp_free_i64(tcg_hiaddr);

    }



    tcg_temp_free_i64(tmp);

}

