static int decode_frame(AVCodecContext *avctx, 

                        void *data, int *data_size,

                        uint8_t *buf, int buf_size)

{

    MDECContext * const a = avctx->priv_data;

    AVFrame *picture = data;

    AVFrame * const p= (AVFrame*)&a->picture;

    int i;



    /* special case for last picture */

    if (buf_size == 0) {

        return 0;

    }



    if(p->data[0])

        avctx->release_buffer(avctx, p);



    p->reference= 0;

    if(avctx->get_buffer(avctx, p) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }

    p->pict_type= I_TYPE;

    p->key_frame= 1;

    a->last_dc[0]=

    a->last_dc[1]=

    a->last_dc[2]= 0;



    a->bitstream_buffer= av_fast_realloc(a->bitstream_buffer, &a->bitstream_buffer_size, buf_size + FF_INPUT_BUFFER_PADDING_SIZE);

    for(i=0; i<buf_size; i+=2){

        a->bitstream_buffer[i]  = buf[i+1];

        a->bitstream_buffer[i+1]= buf[i  ];

    }

    init_get_bits(&a->gb, a->bitstream_buffer, buf_size*8);



    /* skip over 4 preamble bytes in stream (typically 0xXX 0xXX 0x00 0x38) */

    skip_bits(&a->gb, 32);



    a->qscale=  get_bits(&a->gb, 16);

    a->version= get_bits(&a->gb, 16);



//    printf("qscale:%d (0x%X), version:%d (0x%X)\n", a->qscale, a->qscale, a->version, a->version);



    for(a->mb_x=0; a->mb_x<a->mb_width; a->mb_x++){

        for(a->mb_y=0; a->mb_y<a->mb_height; a->mb_y++){

            if( decode_mb(a, a->block) <0)

                return -1;



            idct_put(a, a->mb_x, a->mb_y);

        }

    }



//    p->quality= (32 + a->inv_qscale/2)/a->inv_qscale;

//    memset(p->qscale_table, p->quality, p->qstride*a->mb_height);



    *picture= *(AVFrame*)&a->picture;

    *data_size = sizeof(AVPicture);



    emms_c();



    return (get_bits_count(&a->gb)+31)/32*4;

}

static int gif_image_write_image(AVCodecContext *avctx,

                                 uint8_t **bytestream, uint8_t *end,

                                 const uint32_t *palette,

                                 const uint8_t *buf, const int linesize,

                                 AVPacket *pkt)

{

    GIFContext *s = avctx->priv_data;

    int len = 0, height = avctx->height, width = avctx->width, x, y;

    int x_start = 0, y_start = 0, trans = s->transparent_index;

    int honor_transparency = (s->flags & GF_TRANSDIFF) && s->last_frame;

    const uint8_t *ptr;



    /* Crop image */

    if ((s->flags & GF_OFFSETTING) && s->last_frame && !palette) {

        const uint8_t *ref = s->last_frame->data[0];

        const int ref_linesize = s->last_frame->linesize[0];

        int x_end = avctx->width  - 1,

            y_end = avctx->height - 1;



        /* skip common lines */

        while (y_start < y_end) {

            if (memcmp(ref + y_start*ref_linesize, buf + y_start*linesize, width))

                break;

            y_start++;

        }

        while (y_end > y_start) {

            if (memcmp(ref + y_end*ref_linesize, buf + y_end*linesize, width))

                break;

            y_end--;

        }

        height = y_end + 1 - y_start;



        /* skip common columns */

        while (x_start < x_end) {

            int same_column = 1;

            for (y = y_start; y <= y_end; y++) {

                if (ref[y*ref_linesize + x_start] != buf[y*linesize + x_start]) {

                    same_column = 0;

                    break;

                }

            }

            if (!same_column)

                break;

            x_start++;

        }

        while (x_end > x_start) {

            int same_column = 1;

            for (y = y_start; y <= y_end; y++) {

                if (ref[y*ref_linesize + x_end] != buf[y*linesize + x_end]) {

                    same_column = 0;

                    break;

                }

            }

            if (!same_column)

                break;

            x_end--;

        }

        width = x_end + 1 - x_start;



        av_log(avctx, AV_LOG_DEBUG,"%dx%d image at pos (%d;%d) [area:%dx%d]\n",

               width, height, x_start, y_start, avctx->width, avctx->height);

    }



    /* image block */

    bytestream_put_byte(bytestream, GIF_IMAGE_SEPARATOR);

    bytestream_put_le16(bytestream, x_start);

    bytestream_put_le16(bytestream, y_start);

    bytestream_put_le16(bytestream, width);

    bytestream_put_le16(bytestream, height);



    if (!palette) {

        bytestream_put_byte(bytestream, 0x00); /* flags */

    } else {

        unsigned i;

        bytestream_put_byte(bytestream, 1<<7 | 0x7); /* flags */

        for (i = 0; i < AVPALETTE_COUNT; i++) {

            const uint32_t v = palette[i];

            bytestream_put_be24(bytestream, v);

        }

    }



    if (honor_transparency && trans < 0) {

        trans = pick_palette_entry(buf + y_start*linesize + x_start,

                                   linesize, width, height);

        if (trans < 0) { // TODO, patch welcome

            av_log(avctx, AV_LOG_DEBUG, "No available color, can not use transparency\n");

        } else {

            uint8_t *pal_exdata = s->pal_exdata;

            if (!pal_exdata)

                pal_exdata = av_packet_new_side_data(pkt, AV_PKT_DATA_PALETTE, AVPALETTE_SIZE);

            if (!pal_exdata)

                return AVERROR(ENOMEM);

            memcpy(pal_exdata, s->palette, AVPALETTE_SIZE);

            pal_exdata[trans*4 + 3*!HAVE_BIGENDIAN] = 0x00;

        }

    }

    if (trans < 0)

        honor_transparency = 0;



    bytestream_put_byte(bytestream, 0x08);



    ff_lzw_encode_init(s->lzw, s->buf, 2 * width * height,

                       12, FF_LZW_GIF, put_bits);



    ptr = buf + y_start*linesize + x_start;

    if (honor_transparency) {

        const int ref_linesize = s->last_frame->linesize[0];

        const uint8_t *ref = s->last_frame->data[0] + y_start*ref_linesize + x_start;



        for (y = 0; y < height; y++) {

            memcpy(s->tmpl, ptr, width);

            for (x = 0; x < width; x++)

                if (ref[x] == ptr[x])

                    s->tmpl[x] = trans;

            len += ff_lzw_encode(s->lzw, s->tmpl, width);

            ptr += linesize;

            ref += ref_linesize;

        }

    } else {

        for (y = 0; y < height; y++) {

            len += ff_lzw_encode(s->lzw, ptr, width);

            ptr += linesize;

        }

    }

    len += ff_lzw_encode_flush(s->lzw, flush_put_bits);



    ptr = s->buf;

    while (len > 0) {

        int size = FFMIN(255, len);

        bytestream_put_byte(bytestream, size);

        if (end - *bytestream < size)

            return -1;

        bytestream_put_buffer(bytestream, ptr, size);

        ptr += size;

        len -= size;

    }

    bytestream_put_byte(bytestream, 0x00); /* end of image block */

    return 0;

}

uint64_t helper_fnmadd (uint64_t arg1, uint64_t arg2, uint64_t arg3)

{

    CPU_DoubleU farg1, farg2, farg3;



    farg1.ll = arg1;

    farg2.ll = arg2;

    farg3.ll = arg3;



    if (unlikely(float64_is_signaling_nan(farg1.d) ||

                 float64_is_signaling_nan(farg2.d) ||

                 float64_is_signaling_nan(farg3.d))) {

        /* sNaN operation */

        farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXSNAN);

    } else if (unlikely((float64_is_infinity(farg1.d) && float64_is_zero(farg2.d)) ||

                        (float64_is_zero(farg1.d) && float64_is_infinity(farg2.d)))) {

        /* Multiplication of zero by infinity */

        farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXIMZ);

    } else {

#if USE_PRECISE_EMULATION

#ifdef FLOAT128

        /* This is the way the PowerPC specification defines it */

        float128 ft0_128, ft1_128;



        ft0_128 = float64_to_float128(farg1.d, &env->fp_status);

        ft1_128 = float64_to_float128(farg2.d, &env->fp_status);

        ft0_128 = float128_mul(ft0_128, ft1_128, &env->fp_status);

        if (unlikely(float128_is_infinity(ft0_128) && float64_is_infinity(farg3.d) &&

                     float128_is_neg(ft0_128) != float64_is_neg(farg3.d))) {

            /* Magnitude subtraction of infinities */

            farg1.ll = fload_invalid_op_excp(POWERPC_EXCP_FP_VXISI);

        } else {

            ft1_128 = float64_to_float128(farg3.d, &env->fp_status);

            ft0_128 = float128_add(ft0_128, ft1_128, &env->fp_status);

            farg1.d = float128_to_float64(ft0_128, &env->fp_status);

        }

#else

        /* This is OK on x86 hosts */

        farg1.d = (farg1.d * farg2.d) + farg3.d;

#endif

#else

        farg1.d = float64_mul(farg1.d, farg2.d, &env->fp_status);

        farg1.d = float64_add(farg1.d, farg3.d, &env->fp_status);

#endif

        if (likely(!float64_is_nan(farg1.d)))

            farg1.d = float64_chs(farg1.d);

    }

    return farg1.ll;

}

static unsigned long copy_elf_strings(int argc,char ** argv, void **page,

                                      unsigned long p)

{

    char *tmp, *tmp1, *pag = NULL;

    int len, offset = 0;



    if (!p) {

	return 0;       /* bullet-proofing */

    }

    while (argc-- > 0) {

        tmp = argv[argc];

        if (!tmp) {

	    fprintf(stderr, "VFS: argc is wrong");

	    exit(-1);

	}

        tmp1 = tmp;

	while (*tmp++);

	len = tmp - tmp1;

	if (p < len) {  /* this shouldn't happen - 128kB */

		return 0;

	}

	while (len) {

	    --p; --tmp; --len;

	    if (--offset < 0) {

		offset = p % TARGET_PAGE_SIZE;

                pag = (char *)page[p/TARGET_PAGE_SIZE];

                if (!pag) {

                    pag = (char *)malloc(TARGET_PAGE_SIZE);

                    page[p/TARGET_PAGE_SIZE] = pag;

                    if (!pag)

                        return 0;

		}

	    }

	    if (len == 0 || offset == 0) {

	        *(pag + offset) = *tmp;

	    }

	    else {

	      int bytes_to_copy = (len > offset) ? offset : len;

	      tmp -= bytes_to_copy;

	      p -= bytes_to_copy;

	      offset -= bytes_to_copy;

	      len -= bytes_to_copy;

	      memcpy_fromfs(pag + offset, tmp, bytes_to_copy + 1);

	    }

	}

    }

    return p;

}

