static int read_channels(AVFilterContext *ctx, int channels, uint8_t *item_str, int *nb, double **c, double **cache)

{

    char *p, *arg, *old_str, *prev_arg = NULL, *saveptr = NULL;

    int i, ret;



    p = old_str = av_strdup(item_str);

    if (!p)

        return AVERROR(ENOMEM);

    for (i = 0; i < channels; i++) {

        if (!(arg = av_strtok(p, "|", &saveptr)))

            arg = prev_arg;



        p = NULL;

        count_coefficients(arg, &nb[i]);

        cache[i] = av_calloc(nb[i], sizeof(cache[i]));

        c[i] = av_calloc(nb[i], sizeof(c[i]));

        if (!c[i] || !cache[i])

            return AVERROR(ENOMEM);



        ret = read_coefficients(ctx, arg, nb[i], c[i]);

        if (ret < 0)

            return ret;

        prev_arg = arg;

    }



    av_freep(&old_str);



    return 0;

}

static void opt_output_file(const char *filename)

{

    AVFormatContext *oc;

    int err, use_video, use_audio, use_subtitle;

    int input_has_video, input_has_audio, input_has_subtitle;

    AVFormatParameters params, *ap = &params;

    AVOutputFormat *file_oformat;



    if (!strcmp(filename, "-"))

        filename = "pipe:";



    oc = avformat_alloc_context();

    if (!oc) {

        print_error(filename, AVERROR(ENOMEM));

        ffmpeg_exit(1);

    }



    if (last_asked_format) {

        file_oformat = av_guess_format(last_asked_format, NULL, NULL);

        if (!file_oformat) {

            fprintf(stderr, "Requested output format '%s' is not a suitable output format\n", last_asked_format);

            ffmpeg_exit(1);

        }

        last_asked_format = NULL;

    } else {

        file_oformat = av_guess_format(NULL, filename, NULL);

        if (!file_oformat) {

            fprintf(stderr, "Unable to find a suitable output format for '%s'\n",

                    filename);

            ffmpeg_exit(1);

        }

    }



    oc->oformat = file_oformat;

    av_strlcpy(oc->filename, filename, sizeof(oc->filename));



    if (!strcmp(file_oformat->name, "ffm") &&

        av_strstart(filename, "http:", NULL)) {

        /* special case for files sent to ffserver: we get the stream

           parameters from ffserver */

        int err = read_ffserver_streams(oc, filename);

        if (err < 0) {

            print_error(filename, err);

            ffmpeg_exit(1);

        }

    } else {

        use_video = file_oformat->video_codec != CODEC_ID_NONE || video_stream_copy || video_codec_name;

        use_audio = file_oformat->audio_codec != CODEC_ID_NONE || audio_stream_copy || audio_codec_name;

        use_subtitle = file_oformat->subtitle_codec != CODEC_ID_NONE || subtitle_stream_copy || subtitle_codec_name;



        /* disable if no corresponding type found and at least one

           input file */

        if (nb_input_files > 0) {

            check_audio_video_sub_inputs(&input_has_video, &input_has_audio,

                                         &input_has_subtitle);

            if (!input_has_video)

                use_video = 0;

            if (!input_has_audio)

                use_audio = 0;

            if (!input_has_subtitle)

                use_subtitle = 0;

        }



        /* manual disable */

        if (audio_disable) {

            use_audio = 0;

        }

        if (video_disable) {

            use_video = 0;

        }

        if (subtitle_disable) {

            use_subtitle = 0;

        }



        if (use_video) {

            new_video_stream(oc);

        }



        if (use_audio) {

            new_audio_stream(oc);

        }



        if (use_subtitle) {

            new_subtitle_stream(oc);

        }



        oc->timestamp = recording_timestamp;



        for(; metadata_count>0; metadata_count--){

            av_metadata_set2(&oc->metadata, metadata[metadata_count-1].key,

                                            metadata[metadata_count-1].value, 0);

        }

        av_metadata_conv(oc, oc->oformat->metadata_conv, NULL);

    }



    output_files[nb_output_files++] = oc;



    /* check filename in case of an image number is expected */

    if (oc->oformat->flags & AVFMT_NEEDNUMBER) {

        if (!av_filename_number_test(oc->filename)) {

            print_error(oc->filename, AVERROR_NUMEXPECTED);

            ffmpeg_exit(1);

        }

    }



    if (!(oc->oformat->flags & AVFMT_NOFILE)) {

        /* test if it already exists to avoid loosing precious files */

        if (!file_overwrite &&

            (strchr(filename, ':') == NULL ||

             filename[1] == ':' ||

             av_strstart(filename, "file:", NULL))) {

            if (url_exist(filename)) {

                if (!using_stdin) {

                    fprintf(stderr,"File '%s' already exists. Overwrite ? [y/N] ", filename);

                    fflush(stderr);

                    if (!read_yesno()) {

                        fprintf(stderr, "Not overwriting - exiting\n");

                        ffmpeg_exit(1);

                    }

                }

                else {

                    fprintf(stderr,"File '%s' already exists. Exiting.\n", filename);

                    ffmpeg_exit(1);

                }

            }

        }



        /* open the file */

        if ((err = url_fopen(&oc->pb, filename, URL_WRONLY)) < 0) {

            print_error(filename, err);

            ffmpeg_exit(1);

        }

    }



    memset(ap, 0, sizeof(*ap));

    if (av_set_parameters(oc, ap) < 0) {

        fprintf(stderr, "%s: Invalid encoding parameters\n",

                oc->filename);

        ffmpeg_exit(1);

    }



    oc->preload= (int)(mux_preload*AV_TIME_BASE);

    oc->max_delay= (int)(mux_max_delay*AV_TIME_BASE);

    oc->loop_output = loop_output;

    oc->flags |= AVFMT_FLAG_NONBLOCK;



    set_context_opts(oc, avformat_opts, AV_OPT_FLAG_ENCODING_PARAM, NULL);



    nb_streamid_map = 0;

}

int main(int argc, char **argv, char **envp)

{

    struct target_pt_regs regs1, *regs = &regs1;

    struct image_info info1, *info = &info1;

    struct linux_binprm bprm;

    TaskState *ts;

    CPUArchState *env;

    CPUState *cpu;

    int optind;

    char **target_environ, **wrk;

    char **target_argv;

    int target_argc;

    int i;

    int ret;

    int execfd;



    module_call_init(MODULE_INIT_TRACE);

    qemu_init_cpu_list();

    module_call_init(MODULE_INIT_QOM);



    if ((envlist = envlist_create()) == NULL) {

        (void) fprintf(stderr, "Unable to allocate envlist\n");

        exit(EXIT_FAILURE);

    }



    /* add current environment into the list */

    for (wrk = environ; *wrk != NULL; wrk++) {

        (void) envlist_setenv(envlist, *wrk);

    }



    /* Read the stack limit from the kernel.  If it's "unlimited",

       then we can do little else besides use the default.  */

    {

        struct rlimit lim;

        if (getrlimit(RLIMIT_STACK, &lim) == 0

            && lim.rlim_cur != RLIM_INFINITY

            && lim.rlim_cur == (target_long)lim.rlim_cur) {

            guest_stack_size = lim.rlim_cur;

        }

    }



    cpu_model = NULL;



    srand(time(NULL));



    qemu_add_opts(&qemu_trace_opts);



    optind = parse_args(argc, argv);



    if (!trace_init_backends()) {

        exit(1);

    }

    trace_init_file(trace_file);



    /* Zero out regs */

    memset(regs, 0, sizeof(struct target_pt_regs));



    /* Zero out image_info */

    memset(info, 0, sizeof(struct image_info));



    memset(&bprm, 0, sizeof (bprm));



    /* Scan interp_prefix dir for replacement files. */

    init_paths(interp_prefix);



    init_qemu_uname_release();



    if (cpu_model == NULL) {

#if defined(TARGET_I386)

#ifdef TARGET_X86_64

        cpu_model = "qemu64";

#else

        cpu_model = "qemu32";

#endif

#elif defined(TARGET_ARM)

        cpu_model = "any";

#elif defined(TARGET_UNICORE32)

        cpu_model = "any";

#elif defined(TARGET_M68K)

        cpu_model = "any";

#elif defined(TARGET_SPARC)

#ifdef TARGET_SPARC64

        cpu_model = "TI UltraSparc II";

#else

        cpu_model = "Fujitsu MB86904";

#endif

#elif defined(TARGET_MIPS)

#if defined(TARGET_ABI_MIPSN32) || defined(TARGET_ABI_MIPSN64)

        cpu_model = "5KEf";

#else

        cpu_model = "24Kf";

#endif

#elif defined TARGET_OPENRISC

        cpu_model = "or1200";

#elif defined(TARGET_PPC)

# ifdef TARGET_PPC64

        cpu_model = "POWER8";

# else

        cpu_model = "750";

# endif

#elif defined TARGET_SH4

        cpu_model = TYPE_SH7785_CPU;

#elif defined TARGET_S390X

        cpu_model = "qemu";

#else

        cpu_model = "any";

#endif

    }

    tcg_exec_init(0);

    /* NOTE: we need to init the CPU at this stage to get

       qemu_host_page_size */

    cpu = cpu_init(cpu_model);

    if (!cpu) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(EXIT_FAILURE);

    }

    env = cpu->env_ptr;

    cpu_reset(cpu);



    thread_cpu = cpu;



    if (getenv("QEMU_STRACE")) {

        do_strace = 1;

    }



    if (getenv("QEMU_RAND_SEED")) {

        handle_arg_randseed(getenv("QEMU_RAND_SEED"));

    }



    target_environ = envlist_to_environ(envlist, NULL);

    envlist_free(envlist);



    /*

     * Now that page sizes are configured in cpu_init() we can do

     * proper page alignment for guest_base.

     */

    guest_base = HOST_PAGE_ALIGN(guest_base);



    if (reserved_va || have_guest_base) {

        guest_base = init_guest_space(guest_base, reserved_va, 0,

                                      have_guest_base);

        if (guest_base == (unsigned long)-1) {

            fprintf(stderr, "Unable to reserve 0x%lx bytes of virtual address "

                    "space for use as guest address space (check your virtual "

                    "memory ulimit setting or reserve less using -R option)\n",

                    reserved_va);

            exit(EXIT_FAILURE);

        }



        if (reserved_va) {

            mmap_next_start = reserved_va;

        }

    }



    /*

     * Read in mmap_min_addr kernel parameter.  This value is used

     * When loading the ELF image to determine whether guest_base

     * is needed.  It is also used in mmap_find_vma.

     */

    {

        FILE *fp;



        if ((fp = fopen("/proc/sys/vm/mmap_min_addr", "r")) != NULL) {

            unsigned long tmp;

            if (fscanf(fp, "%lu", &tmp) == 1) {

                mmap_min_addr = tmp;

                qemu_log_mask(CPU_LOG_PAGE, "host mmap_min_addr=0x%lx\n", mmap_min_addr);

            }

            fclose(fp);

        }

    }



    /*

     * Prepare copy of argv vector for target.

     */

    target_argc = argc - optind;

    target_argv = calloc(target_argc + 1, sizeof (char *));

    if (target_argv == NULL) {

	(void) fprintf(stderr, "Unable to allocate memory for target_argv\n");

	exit(EXIT_FAILURE);

    }



    /*

     * If argv0 is specified (using '-0' switch) we replace

     * argv[0] pointer with the given one.

     */

    i = 0;

    if (argv0 != NULL) {

        target_argv[i++] = strdup(argv0);

    }

    for (; i < target_argc; i++) {

        target_argv[i] = strdup(argv[optind + i]);

    }

    target_argv[target_argc] = NULL;



    ts = g_new0(TaskState, 1);

    init_task_state(ts);

    /* build Task State */

    ts->info = info;

    ts->bprm = &bprm;

    cpu->opaque = ts;

    task_settid(ts);



    execfd = qemu_getauxval(AT_EXECFD);

    if (execfd == 0) {

        execfd = open(filename, O_RDONLY);

        if (execfd < 0) {

            printf("Error while loading %s: %s\n", filename, strerror(errno));

