int float_near_ulp(float a, float b, unsigned max_ulp)

{

    union av_intfloat32 x, y;



    x.f = a;

    y.f = b;



    if (is_negative(x) != is_negative(y)) {

        // handle -0.0 == +0.0

        return a == b;

    }



    if (abs(x.i - y.i) <= max_ulp)

        return 1;



    return 0;

}

static int vorbis_parse_setup_hdr_floors(vorbis_context *vc) {

    GetBitContext *gb=&vc->gb;

    uint_fast16_t i,j,k;



    vc->floor_count=get_bits(gb, 6)+1;



    vc->floors=av_mallocz(vc->floor_count * sizeof(vorbis_floor));



    for (i=0;i<vc->floor_count;++i) {

        vorbis_floor *floor_setup=&vc->floors[i];



        floor_setup->floor_type=get_bits(gb, 16);



        AV_DEBUG(" %d. floor type %d \n", i, floor_setup->floor_type);



        if (floor_setup->floor_type==1) {

            uint_fast8_t maximum_class=0;

            uint_fast8_t rangebits;

            uint_fast16_t floor1_values=2;



            floor_setup->decode=vorbis_floor1_decode;



            floor_setup->data.t1.partitions=get_bits(gb, 5);



            AV_DEBUG(" %d.floor: %d partitions \n", i, floor_setup->data.t1.partitions);



            for(j=0;j<floor_setup->data.t1.partitions;++j) {

                floor_setup->data.t1.partition_class[j]=get_bits(gb, 4);

                if (floor_setup->data.t1.partition_class[j]>maximum_class) maximum_class=floor_setup->data.t1.partition_class[j];



                AV_DEBUG(" %d. floor %d partition class %d \n", i, j, floor_setup->data.t1.partition_class[j]);



            }



            AV_DEBUG(" maximum class %d \n", maximum_class);



            floor_setup->data.t1.maximum_class=maximum_class;



            for(j=0;j<=maximum_class;++j) {

                floor_setup->data.t1.class_dimensions[j]=get_bits(gb, 3)+1;

                floor_setup->data.t1.class_subclasses[j]=get_bits(gb, 2);



                AV_DEBUG(" %d floor %d class dim: %d subclasses %d \n", i, j, floor_setup->data.t1.class_dimensions[j], floor_setup->data.t1.class_subclasses[j]);



                if (floor_setup->data.t1.class_subclasses[j]) {

                    floor_setup->data.t1.class_masterbook[j]=get_bits(gb, 8);



                    AV_DEBUG("   masterbook: %d \n", floor_setup->data.t1.class_masterbook[j]);

                }



                for(k=0;k<(1<<floor_setup->data.t1.class_subclasses[j]);++k) {

                    floor_setup->data.t1.subclass_books[j][k]=(int16_t)get_bits(gb, 8)-1;



                    AV_DEBUG("    book %d. : %d \n", k, floor_setup->data.t1.subclass_books[j][k]);

                }

            }



            floor_setup->data.t1.multiplier=get_bits(gb, 2)+1;

            floor_setup->data.t1.x_list_dim=2;



            for(j=0;j<floor_setup->data.t1.partitions;++j) {

                floor_setup->data.t1.x_list_dim+=floor_setup->data.t1.class_dimensions[floor_setup->data.t1.partition_class[j]];

            }



            floor_setup->data.t1.list=av_mallocz(floor_setup->data.t1.x_list_dim * sizeof(vorbis_floor1_entry));





            rangebits=get_bits(gb, 4);

            floor_setup->data.t1.list[0].x = 0;

            floor_setup->data.t1.list[1].x = (1<<rangebits);



            for(j=0;j<floor_setup->data.t1.partitions;++j) {

                for(k=0;k<floor_setup->data.t1.class_dimensions[floor_setup->data.t1.partition_class[j]];++k,++floor1_values) {

                    floor_setup->data.t1.list[floor1_values].x=get_bits(gb, rangebits);



                    AV_DEBUG(" %d. floor1 Y coord. %d \n", floor1_values, floor_setup->data.t1.list[floor1_values].x);

                }

            }



// Precalculate order of x coordinates - needed for decode

            ff_vorbis_ready_floor1_list(floor_setup->data.t1.list, floor_setup->data.t1.x_list_dim);

        }

        else if(floor_setup->floor_type==0) {

            uint_fast8_t max_codebook_dim=0;



            floor_setup->decode=vorbis_floor0_decode;



            floor_setup->data.t0.order=get_bits(gb, 8);

            floor_setup->data.t0.rate=get_bits(gb, 16);

            floor_setup->data.t0.bark_map_size=get_bits(gb, 16);

            floor_setup->data.t0.amplitude_bits=get_bits(gb, 6);

            /* zero would result in a div by zero later *

             * 2^0 - 1 == 0                             */

            if (floor_setup->data.t0.amplitude_bits == 0) {

              av_log(vc->avccontext, AV_LOG_ERROR,

                     "Floor 0 amplitude bits is 0.\n");

              return 1;

            }

            floor_setup->data.t0.amplitude_offset=get_bits(gb, 8);

            floor_setup->data.t0.num_books=get_bits(gb, 4)+1;



            /* allocate mem for booklist */

            floor_setup->data.t0.book_list=

                av_malloc(floor_setup->data.t0.num_books);

            if(!floor_setup->data.t0.book_list) { return 1; }

            /* read book indexes */

            {

                int idx;

                uint_fast8_t book_idx;

                for (idx=0;idx<floor_setup->data.t0.num_books;++idx) {

                    book_idx=get_bits(gb, 8);

                    if (book_idx>=vc->codebook_count)

                        return 1;

                    floor_setup->data.t0.book_list[idx]=book_idx;

                    if (vc->codebooks[book_idx].dimensions > max_codebook_dim)

                        max_codebook_dim=vc->codebooks[book_idx].dimensions;

                }

            }



            create_map( vc, i );



            /* allocate mem for lsp coefficients */

            {

                /* codebook dim is for padding if codebook dim doesn't *

                 * divide order+1 then we need to read more data       */

                floor_setup->data.t0.lsp=

                    av_malloc((floor_setup->data.t0.order+1 + max_codebook_dim)

                              * sizeof(float));

                if(!floor_setup->data.t0.lsp) { return 1; }

            }



#ifdef V_DEBUG /* debug output parsed headers */

            AV_DEBUG("floor0 order: %u\n", floor_setup->data.t0.order);

            AV_DEBUG("floor0 rate: %u\n", floor_setup->data.t0.rate);

            AV_DEBUG("floor0 bark map size: %u\n",

              floor_setup->data.t0.bark_map_size);

            AV_DEBUG("floor0 amplitude bits: %u\n",

              floor_setup->data.t0.amplitude_bits);

            AV_DEBUG("floor0 amplitude offset: %u\n",

              floor_setup->data.t0.amplitude_offset);

            AV_DEBUG("floor0 number of books: %u\n",

              floor_setup->data.t0.num_books);

            AV_DEBUG("floor0 book list pointer: %p\n",

              floor_setup->data.t0.book_list);

            {

              int idx;

              for (idx=0;idx<floor_setup->data.t0.num_books;++idx) {

                AV_DEBUG( "  Book %d: %u\n",

                  idx+1,

                  floor_setup->data.t0.book_list[idx] );

              }

            }

#endif

        }

        else {

            av_log(vc->avccontext, AV_LOG_ERROR, "Invalid floor type!\n");

            return 1;

        }

    }

    return 0;

}

static void decode_subband(DiracContext *s, GetBitContext *gb, int quant,

                           int slice_x, int slice_y, int bits_end,

                           SubBand *b1, SubBand *b2)

{

    int left   = b1->width  * slice_x    / s->num_x;

    int right  = b1->width  *(slice_x+1) / s->num_x;

    int top    = b1->height * slice_y    / s->num_y;

    int bottom = b1->height *(slice_y+1) / s->num_y;



    int qfactor, qoffset;



    uint8_t *buf1 =      b1->ibuf + top * b1->stride;

    uint8_t *buf2 = b2 ? b2->ibuf + top * b2->stride: NULL;

    int x, y;



    if (quant > 115) {

        av_log(s->avctx, AV_LOG_ERROR, "Unsupported quant %d\n", quant);

        return;

    }

    qfactor = ff_dirac_qscale_tab[quant & 0x7f];

    qoffset = ff_dirac_qoffset_intra_tab[quant & 0x7f] + 2;

    /* we have to constantly check for overread since the spec explicitly

       requires this, with the meaning that all remaining coeffs are set to 0 */

    if (get_bits_count(gb) >= bits_end)

        return;



    if (s->pshift) {

        for (y = top; y < bottom; y++) {

            for (x = left; x < right; x++) {

                PARSE_VALUES(int32_t, x, gb, bits_end, buf1, buf2);

            }

            buf1 += b1->stride;

            if (buf2)

                buf2 += b2->stride;

        }

    }

    else {

        for (y = top; y < bottom; y++) {

            for (x = left; x < right; x++) {

                PARSE_VALUES(int16_t, x, gb, bits_end, buf1, buf2);

            }

            buf1 += b1->stride;

            if (buf2)

                buf2 += b2->stride;

        }

    }

}

int ff_rle_encode(uint8_t *outbuf, int out_size, const uint8_t *ptr , int bpp, int w, int8_t add, uint8_t xor)

{

    int count, x;

    uint8_t *out;



    out = outbuf;





        for(x = 0; x < w; x += count) {

            /* see if we can encode the next set of pixels with RLE */

            if((count = count_pixels(ptr, w-x, bpp, 1)) > 1) {

                if(out + bpp + 1 > outbuf + out_size) return -1;

                *out++ = (count ^ xor) + add;

                memcpy(out, ptr, bpp);

                out += bpp;

            } else {

                /* fall back on uncompressed */

                count = count_pixels(ptr, w-x, bpp, 0);

                *out++ = count - 1;



                if(out + bpp*count > outbuf + out_size) return -1;

                memcpy(out, ptr, bpp * count);

                out += bpp * count;

        }



        ptr += count * bpp;

    }



    return out - outbuf;

}

void HELPER(simcall)(CPUXtensaState *env)

{

    uint32_t *regs = env->regs;



    switch (regs[2]) {

    case TARGET_SYS_exit:

        qemu_log("exit(%d) simcall\n", regs[3]);

        exit(regs[3]);

        break;



    case TARGET_SYS_read:

    case TARGET_SYS_write:

        {

            bool is_write = regs[2] == TARGET_SYS_write;

            uint32_t fd = regs[3];

            uint32_t vaddr = regs[4];

            uint32_t len = regs[5];



            while (len > 0) {

                target_phys_addr_t paddr =

                    cpu_get_phys_page_debug(env, vaddr);

                uint32_t page_left =

                    TARGET_PAGE_SIZE - (vaddr & (TARGET_PAGE_SIZE - 1));

                uint32_t io_sz = page_left < len ? page_left : len;

                target_phys_addr_t sz = io_sz;

                void *buf = cpu_physical_memory_map(paddr, &sz, is_write);



                if (buf) {

                    vaddr += io_sz;

                    len -= io_sz;

                    regs[2] = is_write ?

                        write(fd, buf, io_sz) :

                        read(fd, buf, io_sz);

                    regs[3] = errno;

                    cpu_physical_memory_unmap(buf, sz, is_write, sz);

                    if (regs[2] == -1) {

                        break;

                    }

                } else {


                    regs[3] = EINVAL;

                    break;

                }

            }

        }

        break;



    case TARGET_SYS_open:

        {

            char name[1024];

            int rc;

            int i;



            for (i = 0; i < ARRAY_SIZE(name); ++i) {

                rc = cpu_memory_rw_debug(

                        env, regs[3] + i, (uint8_t *)name + i, 1, 0);

                if (rc != 0 || name[i] == 0) {

                    break;

                }

            }



            if (rc == 0 && i < ARRAY_SIZE(name)) {

                regs[2] = open(name, regs[4], regs[5]);

                regs[3] = errno;

            } else {


                regs[3] = EINVAL;

            }

        }

        break;



    case TARGET_SYS_close:

        if (regs[3] < 3) {

            regs[2] = regs[3] = 0;

        } else {

            regs[2] = close(regs[3]);

            regs[3] = errno;

        }

        break;



    case TARGET_SYS_lseek:

        regs[2] = lseek(regs[3], (off_t)(int32_t)regs[4], regs[5]);

        regs[3] = errno;

        break;



    case TARGET_SYS_select_one:

        {

            uint32_t fd = regs[3];

            uint32_t rq = regs[4];

            uint32_t target_tv = regs[5];

            uint32_t target_tvv[2];



            struct timeval tv = {0};

            fd_set fdset;



            FD_ZERO(&fdset);

            FD_SET(fd, &fdset);



            if (target_tv) {

                cpu_memory_rw_debug(env, target_tv,

                        (uint8_t *)target_tvv, sizeof(target_tvv), 0);

                tv.tv_sec = (int32_t)tswap32(target_tvv[0]);

                tv.tv_usec = (int32_t)tswap32(target_tvv[1]);

            }

            regs[2] = select(fd + 1,

                    rq == SELECT_ONE_READ   ? &fdset : NULL,

                    rq == SELECT_ONE_WRITE  ? &fdset : NULL,

                    rq == SELECT_ONE_EXCEPT ? &fdset : NULL,

                    target_tv ? &tv : NULL);

            regs[3] = errno;

        }

        break;



    case TARGET_SYS_argc:

        regs[2] = 1;

        regs[3] = 0;

        break;



    case TARGET_SYS_argv_sz:

        regs[2] = 128;

        regs[3] = 0;

        break;



    case TARGET_SYS_argv:

        {

            struct Argv {

                uint32_t argptr[2];

                char text[120];

            } argv = {

                {0, 0},

                "test"

            };



            argv.argptr[0] = tswap32(regs[3] + offsetof(struct Argv, text));

            cpu_memory_rw_debug(

                    env, regs[3], (uint8_t *)&argv, sizeof(argv), 1);

        }

        break;



    case TARGET_SYS_memset:

        {

            uint32_t base = regs[3];

            uint32_t sz = regs[5];



            while (sz) {

                target_phys_addr_t len = sz;

                void *buf = cpu_physical_memory_map(base, &len, 1);



                if (buf && len) {

                    memset(buf, regs[4], len);

                    cpu_physical_memory_unmap(buf, len, 1, len);

                } else {

                    len = 1;

                }

                base += len;

                sz -= len;

            }

            regs[2] = regs[3];

            regs[3] = 0;

        }

        break;



    default:

        qemu_log("%s(%d): not implemented\n", __func__, regs[2]);



        break;

    }

}

static int decode_frame(AVCodecContext *avctx,
                        void *data, int *data_size,
                        AVPacket *avpkt)
{
    const uint8_t *buf = avpkt->data;
    const uint8_t *buf_end = avpkt->data + avpkt->size;
    int buf_size = avpkt->size;
    QdrawContext * const a = avctx->priv_data;
    AVFrame * const p= (AVFrame*)&a->pic;
    uint8_t* outdata;
    int colors;
    int i;
    uint32_t *pal;
    int r, g, b;
    if(p->data[0])
        avctx->release_buffer(avctx, p);
    p->reference= 0;
    if(avctx->get_buffer(avctx, p) < 0){
        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");
        return -1;
    }
    p->pict_type= AV_PICTURE_TYPE_I;
    p->key_frame= 1;
    outdata = a->pic.data[0];
    if (buf_end - buf < 0x68 + 4)
    buf += 0x68; /* jump to palette */
    colors = AV_RB32(buf);
    buf += 4;
    if(colors < 0 || colors > 256) {
        av_log(avctx, AV_LOG_ERROR, "Error color count - %i(0x%X)\n", colors, colors);
        return -1;
    }
    if (buf_end - buf < (colors + 1) * 8)
    pal = (uint32_t*)p->data[1];
    for (i = 0; i <= colors; i++) {
        unsigned int idx;
        idx = AV_RB16(buf); /* color index */
        buf += 2;
        if (idx > 255) {
            av_log(avctx, AV_LOG_ERROR, "Palette index out of range: %u\n", idx);
            buf += 6;
            continue;
        }
        r = *buf++;
        buf++;
        g = *buf++;
        buf++;
        b = *buf++;
        buf++;
        pal[idx] = (r << 16) | (g << 8) | b;
    }
    p->palette_has_changed = 1;
    if (buf_end - buf < 18)
    buf += 18; /* skip unneeded data */
    for (i = 0; i < avctx->height; i++) {
        int size, left, code, pix;
        const uint8_t *next;
        uint8_t *out;
        int tsize = 0;
        /* decode line */
        out = outdata;
        size = AV_RB16(buf); /* size of packed line */
        buf += 2;
        left = size;
        next = buf + size;
        while (left > 0) {
            code = *buf++;
            if (code & 0x80 ) { /* run */
                pix = *buf++;
                if ((out + (257 - code)) > (outdata +  a->pic.linesize[0]))
                    break;
                memset(out, pix, 257 - code);
                out += 257 - code;
                tsize += 257 - code;
                left -= 2;
            } else { /* copy */
                if ((out + code) > (outdata +  a->pic.linesize[0]))
                    break;
                if (buf_end - buf < code + 1)
                memcpy(out, buf, code + 1);
                out += code + 1;
                buf += code + 1;
                left -= 2 + code;
                tsize += code + 1;
            }
        }
        buf = next;
        outdata += a->pic.linesize[0];
    }
    *data_size = sizeof(AVFrame);
    *(AVFrame*)data = a->pic;
    return buf_size;
}

