static gboolean cadence_uart_xmit(GIOChannel *chan, GIOCondition cond,

                                  void *opaque)

{

    CadenceUARTState *s = opaque;

    int ret;



    /* instant drain the fifo when there's no back-end */

    if (!s->chr) {

        s->tx_count = 0;

        return FALSE;

    }



    if (!s->tx_count) {

        return FALSE;

    }



    ret = qemu_chr_fe_write(s->chr, s->tx_fifo, s->tx_count);

    s->tx_count -= ret;

    memmove(s->tx_fifo, s->tx_fifo + ret, s->tx_count);



    if (s->tx_count) {

        int r = qemu_chr_fe_add_watch(s->chr, G_IO_OUT|G_IO_HUP,

                                      cadence_uart_xmit, s);

        assert(r);

    }



    uart_update_status(s);

    return FALSE;

}

static int mpeg4_decode_video_packet_header(MpegEncContext *s)

{

    int mb_num_bits= av_log2(s->mb_num - 1) + 1;

    int header_extension=0, mb_num, len;



    /* is there enough space left for a video packet + header */

    if( get_bits_count(&s->gb) > s->gb.size*8-20) return -1;



    for(len=0; len<32; len++){

        if(get_bits1(&s->gb)) break;

    }



    if(len!=ff_mpeg4_get_video_packet_prefix_length(s)){

        printf("marker does not match f_code\n");

        return -1;

    }



    if(s->shape != RECT_SHAPE){

        header_extension= get_bits1(&s->gb);

        //FIXME more stuff here

    }



    mb_num= get_bits(&s->gb, mb_num_bits);

    if(mb_num>=s->mb_num){

        fprintf(stderr, "illegal mb_num in video packet (%d %d) \n", mb_num, s->mb_num);

        return -1;

    }

    s->mb_x= mb_num % s->mb_width;

    s->mb_y= mb_num / s->mb_width;



    if(s->shape != BIN_ONLY_SHAPE){

        int qscale= get_bits(&s->gb, s->quant_precision); 

        if(qscale)

            s->qscale= qscale;

    }



    if(s->shape == RECT_SHAPE){

        header_extension= get_bits1(&s->gb);

    }

    if(header_extension){

        int time_increment;

        int time_incr=0;



        while (get_bits1(&s->gb) != 0) 

            time_incr++;



        check_marker(&s->gb, "before time_increment in video packed header");

        time_increment= get_bits(&s->gb, s->time_increment_bits);

        check_marker(&s->gb, "before vop_coding_type in video packed header");



        skip_bits(&s->gb, 2); /* vop coding type */

        //FIXME not rect stuff here



        if(s->shape != BIN_ONLY_SHAPE){

            skip_bits(&s->gb, 3); /* intra dc vlc threshold */

//FIXME dont just ignore everything

            if(s->pict_type == S_TYPE && s->vol_sprite_usage==GMC_SPRITE){

                mpeg4_decode_sprite_trajectory(s);

                fprintf(stderr, "untested\n");

            }



            //FIXME reduced res stuff here



            if (s->pict_type != I_TYPE) {

                int f_code = get_bits(&s->gb, 3);	/* fcode_for */

                if(f_code==0){

                    printf("Error, video packet header damaged (f_code=0)\n");

                }

            }

            if (s->pict_type == B_TYPE) {

                int b_code = get_bits(&s->gb, 3);

                if(b_code==0){

                    printf("Error, video packet header damaged (b_code=0)\n");

                }

            }       

        }

    }

    //FIXME new-pred stuff



//printf("parse ok %d %d %d %d\n", mb_num, s->mb_x + s->mb_y*s->mb_width, get_bits_count(gb), get_bits_count(&s->gb));



    return 0;

}

