static int theora_decode_header(AVCodecContext *avctx, GetBitContext *gb)

{

    Vp3DecodeContext *s = avctx->priv_data;

    int visible_width, visible_height, colorspace;

    int offset_x = 0, offset_y = 0;

    AVRational fps, aspect;



    s->theora = get_bits_long(gb, 24);

    av_log(avctx, AV_LOG_DEBUG, "Theora bitstream version %X\n", s->theora);



    /* 3.2.0 aka alpha3 has the same frame orientation as original vp3 */

    /* but previous versions have the image flipped relative to vp3 */

    if (s->theora < 0x030200)

    {

        s->flipped_image = 1;

        av_log(avctx, AV_LOG_DEBUG, "Old (<alpha3) Theora bitstream, flipped image\n");

    }



    visible_width  = s->width  = get_bits(gb, 16) << 4;

    visible_height = s->height = get_bits(gb, 16) << 4;



    if(av_image_check_size(s->width, s->height, 0, avctx)){

        av_log(avctx, AV_LOG_ERROR, "Invalid dimensions (%dx%d)\n", s->width, s->height);

        s->width= s->height= 0;

        return -1;

    }



    if (s->theora >= 0x030200) {

        visible_width  = get_bits_long(gb, 24);

        visible_height = get_bits_long(gb, 24);



        offset_x = get_bits(gb, 8); /* offset x */

        offset_y = get_bits(gb, 8); /* offset y, from bottom */

    }



    fps.num = get_bits_long(gb, 32);

    fps.den = get_bits_long(gb, 32);

    if (fps.num && fps.den) {

        av_reduce(&avctx->time_base.num, &avctx->time_base.den,

                  fps.den, fps.num, 1<<30);

    }



    aspect.num = get_bits_long(gb, 24);

    aspect.den = get_bits_long(gb, 24);

    if (aspect.num && aspect.den) {

        av_reduce(&avctx->sample_aspect_ratio.num,

                  &avctx->sample_aspect_ratio.den,

                  aspect.num, aspect.den, 1<<30);

    }



    if (s->theora < 0x030200)

        skip_bits(gb, 5); /* keyframe frequency force */

    colorspace = get_bits(gb, 8);

    skip_bits(gb, 24); /* bitrate */



    skip_bits(gb, 6); /* quality hint */



    if (s->theora >= 0x030200)

    {

        skip_bits(gb, 5); /* keyframe frequency force */

        avctx->pix_fmt = theora_pix_fmts[get_bits(gb, 2)];

        if (avctx->pix_fmt == AV_PIX_FMT_NONE) {

            av_log(avctx, AV_LOG_ERROR, "Invalid pixel format\n");

            return AVERROR_INVALIDDATA;

        }

        skip_bits(gb, 3); /* reserved */

    }



//    align_get_bits(gb);



    if (   visible_width  <= s->width  && visible_width  > s->width-16

        && visible_height <= s->height && visible_height > s->height-16

        && !offset_x && (offset_y == s->height - visible_height))

        avcodec_set_dimensions(avctx, visible_width, visible_height);

    else

        avcodec_set_dimensions(avctx, s->width, s->height);



    if (colorspace == 1) {

        avctx->color_primaries = AVCOL_PRI_BT470M;

    } else if (colorspace == 2) {

        avctx->color_primaries = AVCOL_PRI_BT470BG;

    }

    if (colorspace == 1 || colorspace == 2) {

        avctx->colorspace = AVCOL_SPC_BT470BG;

        avctx->color_trc  = AVCOL_TRC_BT709;

    }



    return 0;

}

void HELPER(cdsg)(CPUS390XState *env, uint64_t addr,

                  uint32_t r1, uint32_t r3)

{

    uintptr_t ra = GETPC();

    Int128 cmpv = int128_make128(env->regs[r1 + 1], env->regs[r1]);

    Int128 newv = int128_make128(env->regs[r3 + 1], env->regs[r3]);

    Int128 oldv;

    bool fail;



    if (parallel_cpus) {

#ifndef CONFIG_ATOMIC128

        cpu_loop_exit_atomic(ENV_GET_CPU(env), ra);

#else

        int mem_idx = cpu_mmu_index(env, false);

        TCGMemOpIdx oi = make_memop_idx(MO_TEQ | MO_ALIGN_16, mem_idx);

        oldv = helper_atomic_cmpxchgo_be_mmu(env, addr, cmpv, newv, oi, ra);

        fail = !int128_eq(oldv, cmpv);

#endif

    } else {

        uint64_t oldh, oldl;



        check_alignment(env, addr, 16, ra);



        oldh = cpu_ldq_data_ra(env, addr + 0, ra);

        oldl = cpu_ldq_data_ra(env, addr + 8, ra);



        oldv = int128_make128(oldl, oldh);

        fail = !int128_eq(oldv, cmpv);

        if (fail) {

            newv = oldv;

        }



        cpu_stq_data_ra(env, addr + 0, int128_gethi(newv), ra);

        cpu_stq_data_ra(env, addr + 8, int128_getlo(newv), ra);

    }



    env->cc_op = fail;

    env->regs[r1] = int128_gethi(oldv);

    env->regs[r1 + 1] = int128_getlo(oldv);

}

static QObject *parse_object(JSONParserContext *ctxt, va_list *ap)

{

    QDict *dict = NULL;

    QObject *token, *peek;

    JSONParserContext saved_ctxt = parser_context_save(ctxt);



    token = parser_context_pop_token(ctxt);

    if (token == NULL) {

        goto out;

    }



    if (!token_is_operator(token, '{')) {

        goto out;

    }



    dict = qdict_new();



    peek = parser_context_peek_token(ctxt);

    if (peek == NULL) {

        parse_error(ctxt, NULL, "premature EOI");

        goto out;

    }



    if (!token_is_operator(peek, '}')) {

        if (parse_pair(ctxt, dict, ap) == -1) {

            goto out;

        }



        token = parser_context_pop_token(ctxt);

        if (token == NULL) {

            parse_error(ctxt, NULL, "premature EOI");

            goto out;

        }



        while (!token_is_operator(token, '}')) {

            if (!token_is_operator(token, ',')) {

                parse_error(ctxt, token, "expected separator in dict");

                goto out;

            }



            if (parse_pair(ctxt, dict, ap) == -1) {

                goto out;

            }



            token = parser_context_pop_token(ctxt);

            if (token == NULL) {

                parse_error(ctxt, NULL, "premature EOI");

                goto out;

            }

        }

    } else {

        (void)parser_context_pop_token(ctxt);

    }



    return QOBJECT(dict);



out:

    parser_context_restore(ctxt, saved_ctxt);

    QDECREF(dict);

    return NULL;

}

static inline void dxt3_block_internal(uint8_t *dst, ptrdiff_t stride,

                                       const uint8_t *block)

{

    int x, y;

    uint32_t colors[4];

    uint16_t color0 = AV_RL16(block +  8);

    uint16_t color1 = AV_RL16(block + 10);

    uint32_t code   = AV_RL32(block + 12);



    extract_color(colors, color0, color1, 1, 0);



    for (y = 0; y < 4; y++) {

        const uint16_t alpha_code = AV_RL16(block + 2 * y);

        uint8_t alpha_values[4];



        alpha_values[0] = ((alpha_code >>  0) & 0x0F) * 17;

        alpha_values[1] = ((alpha_code >>  4) & 0x0F) * 17;

        alpha_values[2] = ((alpha_code >>  8) & 0x0F) * 17;

        alpha_values[3] = ((alpha_code >> 12) & 0x0F) * 17;



        for (x = 0; x < 4; x++) {

            uint8_t alpha = alpha_values[x];

            uint32_t pixel = colors[code & 3] | (alpha << 24);

            code >>= 2;



            AV_WL32(dst + x * 4, pixel);

        }

        dst += stride;

    }

}

static void dec_scall(DisasContext *dc)

{

    if (dc->imm5 == 7) {

        LOG_DIS("scall\n");

    } else if (dc->imm5 == 2) {

        LOG_DIS("break\n");

    } else {

        cpu_abort(dc->env, "invalid opcode\n");

    }



    if (dc->imm5 == 7) {

        tcg_gen_movi_tl(cpu_pc, dc->pc);

        t_gen_raise_exception(dc, EXCP_SYSTEMCALL);

    } else {

        tcg_gen_movi_tl(cpu_pc, dc->pc);

        t_gen_raise_exception(dc, EXCP_BREAKPOINT);

    }

}

static void console_refresh(QemuConsole *s)

{

    DisplaySurface *surface = qemu_console_surface(s);

    TextCell *c;

    int x, y, y1;



    if (s->ds->have_text) {

        s->text_x[0] = 0;

        s->text_y[0] = 0;

        s->text_x[1] = s->width - 1;

        s->text_y[1] = s->height - 1;

        s->cursor_invalidate = 1;

    }



    vga_fill_rect(s, 0, 0, surface_width(surface), surface_height(surface),

                  color_table_rgb[0][COLOR_BLACK]);

    y1 = s->y_displayed;

    for (y = 0; y < s->height; y++) {

        c = s->cells + y1 * s->width;

        for (x = 0; x < s->width; x++) {

            vga_putcharxy(s, x, y, c->ch,

                          &(c->t_attrib));

            c++;

        }

        if (++y1 == s->total_height) {

            y1 = 0;

        }

    }

    console_show_cursor(s, 1);

    dpy_gfx_update(s, 0, 0,

                   surface_width(surface), surface_height(surface));

}

int avcodec_get_pix_fmt_loss(int dst_pix_fmt, int src_pix_fmt,

                             int has_alpha)

{

    const PixFmtInfo *pf, *ps;

    int loss;



    ps = &pix_fmt_info[src_pix_fmt];

    pf = &pix_fmt_info[dst_pix_fmt];



    /* compute loss */

    loss = 0;

    pf = &pix_fmt_info[dst_pix_fmt];

    if (pf->depth < ps->depth)

        loss |= FF_LOSS_DEPTH;

    if (pf->x_chroma_shift >= ps->x_chroma_shift ||

        pf->y_chroma_shift >= ps->y_chroma_shift)

        loss |= FF_LOSS_RESOLUTION;

    switch(pf->color_type) {

    case FF_COLOR_RGB:

        if (ps->color_type != FF_COLOR_RGB &&

            ps->color_type != FF_COLOR_GRAY)

            loss |= FF_LOSS_COLORSPACE;

        break;

    case FF_COLOR_GRAY:

        if (ps->color_type != FF_COLOR_GRAY)

            loss |= FF_LOSS_COLORSPACE;

        break;

    case FF_COLOR_YUV:

        if (ps->color_type != FF_COLOR_YUV)

            loss |= FF_LOSS_COLORSPACE;

        break;

    case FF_COLOR_YUV_JPEG:

        if (ps->color_type != FF_COLOR_YUV_JPEG &&

            ps->color_type != FF_COLOR_YUV)

            loss |= FF_LOSS_COLORSPACE;

        break;

    default:

        /* fail safe test */

        if (ps->color_type != pf->color_type)

            loss |= FF_LOSS_COLORSPACE;

        break;

    }

    if (pf->color_type == FF_COLOR_GRAY &&

        ps->color_type != FF_COLOR_GRAY)

        loss |= FF_LOSS_CHROMA;

    if (!pf->is_alpha && (ps->is_alpha && has_alpha))

        loss |= FF_LOSS_ALPHA;

    if (pf->is_paletted && (!ps->is_paletted && ps->color_type != FF_COLOR_GRAY))

        loss |= FF_LOSS_COLORQUANT;

    return loss;

}

static void coroutine_fn v9fs_xattrwalk(void *opaque)

{

    int64_t size;

    V9fsString name;

    ssize_t err = 0;

    size_t offset = 7;

    int32_t fid, newfid;

    V9fsFidState *file_fidp;

    V9fsFidState *xattr_fidp = NULL;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    v9fs_string_init(&name);

    err = pdu_unmarshal(pdu, offset, "dds", &fid, &newfid, &name);

    if (err < 0) {

        goto out_nofid;

    }

    trace_v9fs_xattrwalk(pdu->tag, pdu->id, fid, newfid, name.data);



    file_fidp = get_fid(pdu, fid);

    if (file_fidp == NULL) {

        err = -ENOENT;

        goto out_nofid;

    }

    xattr_fidp = alloc_fid(s, newfid);

    if (xattr_fidp == NULL) {

        err = -EINVAL;

        goto out;

    }

    v9fs_path_copy(&xattr_fidp->path, &file_fidp->path);

    if (!v9fs_string_size(&name)) {

        /*

         * listxattr request. Get the size first

         */

        size = v9fs_co_llistxattr(pdu, &xattr_fidp->path, NULL, 0);

        if (size < 0) {

            err = size;

            clunk_fid(s, xattr_fidp->fid);

            goto out;

        }

        /*

         * Read the xattr value

         */

        xattr_fidp->fs.xattr.len = size;

        xattr_fidp->fid_type = P9_FID_XATTR;

        xattr_fidp->fs.xattr.xattrwalk_fid = true;

        if (size) {

            xattr_fidp->fs.xattr.value = g_malloc(size);

            err = v9fs_co_llistxattr(pdu, &xattr_fidp->path,

                                     xattr_fidp->fs.xattr.value,

                                     xattr_fidp->fs.xattr.len);

            if (err < 0) {

                clunk_fid(s, xattr_fidp->fid);

                goto out;

            }

        }

        err = pdu_marshal(pdu, offset, "q", size);

        if (err < 0) {

            goto out;

        }

        err += offset;

    } else {

        /*

         * specific xattr fid. We check for xattr

         * presence also collect the xattr size

         */

        size = v9fs_co_lgetxattr(pdu, &xattr_fidp->path,

                                 &name, NULL, 0);

        if (size < 0) {

            err = size;

            clunk_fid(s, xattr_fidp->fid);

            goto out;

        }

        /*

         * Read the xattr value

         */

        xattr_fidp->fs.xattr.len = size;

        xattr_fidp->fid_type = P9_FID_XATTR;

        xattr_fidp->fs.xattr.xattrwalk_fid = true;

        if (size) {

            xattr_fidp->fs.xattr.value = g_malloc(size);

            err = v9fs_co_lgetxattr(pdu, &xattr_fidp->path,

                                    &name, xattr_fidp->fs.xattr.value,

                                    xattr_fidp->fs.xattr.len);

            if (err < 0) {

                clunk_fid(s, xattr_fidp->fid);

                goto out;

            }

        }

        err = pdu_marshal(pdu, offset, "q", size);

        if (err < 0) {

            goto out;

        }

        err += offset;

    }

    trace_v9fs_xattrwalk_return(pdu->tag, pdu->id, size);

out:

    put_fid(pdu, file_fidp);

    if (xattr_fidp) {

        put_fid(pdu, xattr_fidp);

    }

out_nofid:

    pdu_complete(pdu, err);

    v9fs_string_free(&name);

}

static av_cold int vaapi_encode_h265_init_internal(AVCodecContext *avctx)

{

    static const VAConfigAttrib default_config_attributes[] = {

        { .type  = VAConfigAttribRTFormat,

          .value = VA_RT_FORMAT_YUV420 },

        { .type  = VAConfigAttribEncPackedHeaders,

          .value = (VA_ENC_PACKED_HEADER_SEQUENCE |

                    VA_ENC_PACKED_HEADER_SLICE) },

    };



    VAAPIEncodeContext      *ctx = avctx->priv_data;

    VAAPIEncodeH265Context *priv = ctx->priv_data;

    int i, err;



    switch (avctx->profile) {

    case FF_PROFILE_HEVC_MAIN:

    case FF_PROFILE_UNKNOWN:

        ctx->va_profile = VAProfileHEVCMain;

        break;

    case FF_PROFILE_HEVC_MAIN_10:

        av_log(avctx, AV_LOG_ERROR, "H.265 main 10-bit profile "

               "is not supported.\n");

        return AVERROR_PATCHWELCOME;

    default:

        av_log(avctx, AV_LOG_ERROR, "Unknown H.265 profile %d.\n",

               avctx->profile);

        return AVERROR(EINVAL);

    }

    ctx->va_entrypoint = VAEntrypointEncSlice;



    ctx->input_width    = avctx->width;

    ctx->input_height   = avctx->height;

    ctx->aligned_width  = FFALIGN(ctx->input_width,  16);

    ctx->aligned_height = FFALIGN(ctx->input_height, 16);

    priv->ctu_width     = FFALIGN(ctx->aligned_width,  32) / 32;

    priv->ctu_height    = FFALIGN(ctx->aligned_height, 32) / 32;



    av_log(avctx, AV_LOG_VERBOSE, "Input %ux%u -> Aligned %ux%u -> CTU %ux%u.\n",

           ctx->input_width, ctx->input_height, ctx->aligned_width,

           ctx->aligned_height, priv->ctu_width, priv->ctu_height);



    for (i = 0; i < FF_ARRAY_ELEMS(default_config_attributes); i++) {

        ctx->config_attributes[ctx->nb_config_attributes++] =

            default_config_attributes[i];

    }



    if (avctx->bit_rate > 0) {

        ctx->va_rc_mode = VA_RC_CBR;

        err = vaapi_encode_h265_init_constant_bitrate(avctx);

    } else {

        ctx->va_rc_mode = VA_RC_CQP;

        err = vaapi_encode_h265_init_fixed_qp(avctx);

    }

    if (err < 0)

        return err;



    ctx->config_attributes[ctx->nb_config_attributes++] = (VAConfigAttrib) {

        .type  = VAConfigAttribRateControl,

        .value = ctx->va_rc_mode,

    };



    ctx->nb_recon_frames = 20;



    return 0;

}

