static int discard_single_l2(BlockDriverState *bs, uint64_t offset,

    unsigned int nb_clusters, enum qcow2_discard_type type, bool full_discard)

{

    BDRVQcow2State *s = bs->opaque;

    uint64_t *l2_table;

    int l2_index;

    int ret;

    int i;



    ret = get_cluster_table(bs, offset, &l2_table, &l2_index);

    if (ret < 0) {

        return ret;

    }



    /* Limit nb_clusters to one L2 table */

    nb_clusters = MIN(nb_clusters, s->l2_size - l2_index);



    for (i = 0; i < nb_clusters; i++) {

        uint64_t old_l2_entry;



        old_l2_entry = be64_to_cpu(l2_table[l2_index + i]);



        /*

         * If full_discard is false, make sure that a discarded area reads back

         * as zeroes for v3 images (we cannot do it for v2 without actually

         * writing a zero-filled buffer). We can skip the operation if the

         * cluster is already marked as zero, or if it's unallocated and we

         * don't have a backing file.

         *

         * TODO We might want to use bdrv_get_block_status(bs) here, but we're

         * holding s->lock, so that doesn't work today.

         *

         * If full_discard is true, the sector should not read back as zeroes,

         * but rather fall through to the backing file.

         */

        switch (qcow2_get_cluster_type(old_l2_entry)) {

            case QCOW2_CLUSTER_UNALLOCATED:

                if (full_discard || !bs->backing_hd) {

                    continue;

                }

                break;



            case QCOW2_CLUSTER_ZERO:

                if (!full_discard) {

                    continue;

                }

                break;



            case QCOW2_CLUSTER_NORMAL:

            case QCOW2_CLUSTER_COMPRESSED:

                break;



            default:

                abort();

        }



        /* First remove L2 entries */

        qcow2_cache_entry_mark_dirty(bs, s->l2_table_cache, l2_table);

        if (!full_discard && s->qcow_version >= 3) {

            l2_table[l2_index + i] = cpu_to_be64(QCOW_OFLAG_ZERO);

        } else {

            l2_table[l2_index + i] = cpu_to_be64(0);

        }



        /* Then decrease the refcount */

        qcow2_free_any_clusters(bs, old_l2_entry, 1, type);

    }



    qcow2_cache_put(bs, s->l2_table_cache, (void **) &l2_table);



    return nb_clusters;

}

static void gem_transmit(CadenceGEMState *s)
{
    unsigned    desc[2];
    hwaddr packet_desc_addr;
    uint8_t     tx_packet[2048];
    uint8_t     *p;
    unsigned    total_bytes;
    /* Do nothing if transmit is not enabled. */
    if (!(s->regs[GEM_NWCTRL] & GEM_NWCTRL_TXENA)) {
        return;
    DB_PRINT("\n");
    /* The packet we will hand off to QEMU.
     * Packets scattered across multiple descriptors are gathered to this
     * one contiguous buffer first.
     */
    p = tx_packet;
    total_bytes = 0;
    /* read current descriptor */
    packet_desc_addr = s->tx_desc_addr;
    DB_PRINT("read descriptor 0x%" HWADDR_PRIx "\n", packet_desc_addr);
    cpu_physical_memory_read(packet_desc_addr,
                             (uint8_t *)desc, sizeof(desc));
    /* Handle all descriptors owned by hardware */
    while (tx_desc_get_used(desc) == 0) {
        /* Do nothing if transmit is not enabled. */
        if (!(s->regs[GEM_NWCTRL] & GEM_NWCTRL_TXENA)) {
            return;
        print_gem_tx_desc(desc);
        /* The real hardware would eat this (and possibly crash).
         * For QEMU let's lend a helping hand.
         */
        if ((tx_desc_get_buffer(desc) == 0) ||
            (tx_desc_get_length(desc) == 0)) {
            DB_PRINT("Invalid TX descriptor @ 0x%x\n",
                     (unsigned)packet_desc_addr);
        /* Gather this fragment of the packet from "dma memory" to our contig.
         * buffer.
         */
        cpu_physical_memory_read(tx_desc_get_buffer(desc), p,
                                 tx_desc_get_length(desc));
        p += tx_desc_get_length(desc);
        total_bytes += tx_desc_get_length(desc);
        /* Last descriptor for this packet; hand the whole thing off */
        if (tx_desc_get_last(desc)) {
            unsigned    desc_first[2];
            /* Modify the 1st descriptor of this packet to be owned by
             * the processor.
             */
            cpu_physical_memory_read(s->tx_desc_addr, (uint8_t *)desc_first,
                                     sizeof(desc_first));
            tx_desc_set_used(desc_first);
            cpu_physical_memory_write(s->tx_desc_addr, (uint8_t *)desc_first,
                                      sizeof(desc_first));
            /* Advance the hardware current descriptor past this packet */
            if (tx_desc_get_wrap(desc)) {
                s->tx_desc_addr = s->regs[GEM_TXQBASE];
            } else {
                s->tx_desc_addr = packet_desc_addr + 8;
            DB_PRINT("TX descriptor next: 0x%08x\n", s->tx_desc_addr);
            s->regs[GEM_TXSTATUS] |= GEM_TXSTATUS_TXCMPL;
            s->regs[GEM_ISR] |= GEM_INT_TXCMPL & ~(s->regs[GEM_IMR]);
            /* Handle interrupt consequences */
            gem_update_int_status(s);
            /* Is checksum offload enabled? */
            if (s->regs[GEM_DMACFG] & GEM_DMACFG_TXCSUM_OFFL) {
                net_checksum_calculate(tx_packet, total_bytes);
            /* Update MAC statistics */
            gem_transmit_updatestats(s, tx_packet, total_bytes);
            /* Send the packet somewhere */
            if (s->phy_loop || (s->regs[GEM_NWCTRL] & GEM_NWCTRL_LOCALLOOP)) {
                gem_receive(qemu_get_queue(s->nic), tx_packet, total_bytes);
            } else {
                qemu_send_packet(qemu_get_queue(s->nic), tx_packet,
                                 total_bytes);
            /* Prepare for next packet */
            p = tx_packet;
            total_bytes = 0;
        /* read next descriptor */
        if (tx_desc_get_wrap(desc)) {
            packet_desc_addr = s->regs[GEM_TXQBASE];
        } else {
            packet_desc_addr += 8;
        DB_PRINT("read descriptor 0x%" HWADDR_PRIx "\n", packet_desc_addr);
        cpu_physical_memory_read(packet_desc_addr,
                                 (uint8_t *)desc, sizeof(desc));
    if (tx_desc_get_used(desc)) {
        s->regs[GEM_TXSTATUS] |= GEM_TXSTATUS_USED;
        s->regs[GEM_ISR] |= GEM_INT_TXUSED & ~(s->regs[GEM_IMR]);
        gem_update_int_status(s);

static void sdhci_data_transfer(SDHCIState *s)

{

    SDHCIClass *k = SDHCI_GET_CLASS(s);



    if (s->trnmod & SDHC_TRNS_DMA) {

        switch (SDHC_DMA_TYPE(s->hostctl)) {

        case SDHC_CTRL_SDMA:

            if ((s->trnmod & SDHC_TRNS_MULTI) &&

                    (!(s->trnmod & SDHC_TRNS_BLK_CNT_EN) || s->blkcnt == 0)) {

                break;

            }



            if ((s->blkcnt == 1) || !(s->trnmod & SDHC_TRNS_MULTI)) {

                k->do_sdma_single(s);

            } else {

                k->do_sdma_multi(s);

            }



            break;

        case SDHC_CTRL_ADMA1_32:

            if (!(s->capareg & SDHC_CAN_DO_ADMA1)) {

                ERRPRINT("ADMA1 not supported\n");

                break;

            }



            k->do_adma(s);

            break;

        case SDHC_CTRL_ADMA2_32:

            if (!(s->capareg & SDHC_CAN_DO_ADMA2)) {

                ERRPRINT("ADMA2 not supported\n");

                break;

            }



            k->do_adma(s);

            break;

        case SDHC_CTRL_ADMA2_64:

            if (!(s->capareg & SDHC_CAN_DO_ADMA2) ||

                    !(s->capareg & SDHC_64_BIT_BUS_SUPPORT)) {

                ERRPRINT("64 bit ADMA not supported\n");

                break;

            }



            k->do_adma(s);

            break;

        default:

            ERRPRINT("Unsupported DMA type\n");

            break;

        }

    } else {

        if ((s->trnmod & SDHC_TRNS_READ) && sd_data_ready(s->card)) {

            s->prnsts |= SDHC_DOING_READ | SDHC_DATA_INHIBIT |

                    SDHC_DAT_LINE_ACTIVE;

            SDHCI_GET_CLASS(s)->read_block_from_card(s);

        } else {

            s->prnsts |= SDHC_DOING_WRITE | SDHC_DAT_LINE_ACTIVE |

                    SDHC_SPACE_AVAILABLE | SDHC_DATA_INHIBIT;

            SDHCI_GET_CLASS(s)->write_block_to_card(s);

        }

    }

}

static int alloc_tables(H264Context *h){

    MpegEncContext * const s = &h->s;

    const int big_mb_num= s->mb_stride * (s->mb_height+1);

    int x,y;



    CHECKED_ALLOCZ(h->intra4x4_pred_mode, big_mb_num * 8  * sizeof(uint8_t))



    CHECKED_ALLOCZ(h->non_zero_count    , big_mb_num * 16 * sizeof(uint8_t))

    CHECKED_ALLOCZ(h->slice_table_base  , (big_mb_num+s->mb_stride) * sizeof(uint8_t))

    CHECKED_ALLOCZ(h->cbp_table, big_mb_num * sizeof(uint16_t))



    if( h->pps.cabac ) {

        CHECKED_ALLOCZ(h->chroma_pred_mode_table, big_mb_num * sizeof(uint8_t))

        CHECKED_ALLOCZ(h->mvd_table[0], 32*big_mb_num * sizeof(uint16_t));

        CHECKED_ALLOCZ(h->mvd_table[1], 32*big_mb_num * sizeof(uint16_t));

        CHECKED_ALLOCZ(h->direct_table, 32*big_mb_num * sizeof(uint8_t));

    }



    memset(h->slice_table_base, -1, (big_mb_num+s->mb_stride)  * sizeof(uint8_t));

    h->slice_table= h->slice_table_base + s->mb_stride*2 + 1;



    CHECKED_ALLOCZ(h->mb2b_xy  , big_mb_num * sizeof(uint32_t));

    CHECKED_ALLOCZ(h->mb2b8_xy , big_mb_num * sizeof(uint32_t));

    for(y=0; y<s->mb_height; y++){

        for(x=0; x<s->mb_width; x++){

            const int mb_xy= x + y*s->mb_stride;

            const int b_xy = 4*x + 4*y*h->b_stride;

            const int b8_xy= 2*x + 2*y*h->b8_stride;



            h->mb2b_xy [mb_xy]= b_xy;

            h->mb2b8_xy[mb_xy]= b8_xy;

        }

    }



    s->obmc_scratchpad = NULL;



    if(!h->dequant4_coeff[0])

        init_dequant_tables(h);



    return 0;

fail:

    free_tables(h);

    return -1;

}

static void do_video_out(AVFormatContext *s,

                         OutputStream *ost,

                         AVFrame *in_picture,

                         float quality)

{

    int ret, format_video_sync;

    AVPacket pkt;

    AVCodecContext *enc = ost->st->codec;

    int nb_frames;

    double sync_ipts, delta;

    double duration = 0;

    int frame_size = 0;

    InputStream *ist = NULL;



    if (ost->source_index >= 0)

        ist = input_streams[ost->source_index];



    if(ist && ist->st->start_time != AV_NOPTS_VALUE && ist->st->first_dts != AV_NOPTS_VALUE && ost->frame_rate.num)

        duration = 1/(av_q2d(ost->frame_rate) * av_q2d(enc->time_base));



    sync_ipts = in_picture->pts;

    delta = sync_ipts - ost->sync_opts + duration;



    /* by default, we output a single frame */

    nb_frames = 1;



    format_video_sync = video_sync_method;

    if (format_video_sync == VSYNC_AUTO)

        format_video_sync = (s->oformat->flags & AVFMT_VARIABLE_FPS) ? ((s->oformat->flags & AVFMT_NOTIMESTAMPS) ? VSYNC_PASSTHROUGH : VSYNC_VFR) : 1;



    switch (format_video_sync) {

    case VSYNC_CFR:

        // FIXME set to 0.5 after we fix some dts/pts bugs like in avidec.c

        if (delta < -1.1)

            nb_frames = 0;

        else if (delta > 1.1)

            nb_frames = lrintf(delta);

        break;

    case VSYNC_VFR:

        if (delta <= -0.6)

            nb_frames = 0;

        else if (delta > 0.6)

            ost->sync_opts = lrint(sync_ipts);

        break;

    case VSYNC_DROP:

    case VSYNC_PASSTHROUGH:

        ost->sync_opts = lrint(sync_ipts);

        break;

    default:

        av_assert0(0);




    nb_frames = FFMIN(nb_frames, ost->max_frames - ost->frame_number);

    if (nb_frames == 0) {


        av_log(NULL, AV_LOG_VERBOSE, "*** drop!\n");


    } else if (nb_frames > 1) {






        nb_frames_dup += nb_frames - 1;

        av_log(NULL, AV_LOG_VERBOSE, "*** %d dup!\n", nb_frames - 1);






duplicate_frame:

    av_init_packet(&pkt);

    pkt.data = NULL;

    pkt.size = 0;



    in_picture->pts = ost->sync_opts;



    if (s->oformat->flags & AVFMT_RAWPICTURE &&

        enc->codec->id == CODEC_ID_RAWVIDEO) {

        /* raw pictures are written as AVPicture structure to

           avoid any copies. We support temporarily the older

           method. */

        enc->coded_frame->interlaced_frame = in_picture->interlaced_frame;

        enc->coded_frame->top_field_first  = in_picture->top_field_first;

        pkt.data   = (uint8_t *)in_picture;

        pkt.size   =  sizeof(AVPicture);

        pkt.pts    = av_rescale_q(in_picture->pts, enc->time_base, ost->st->time_base);

        pkt.flags |= AV_PKT_FLAG_KEY;



        write_frame(s, &pkt, ost);

        video_size += pkt.size;

    } else {

        int got_packet;

        AVFrame big_picture;



        big_picture = *in_picture;

        /* better than nothing: use input picture interlaced

           settings */

        big_picture.interlaced_frame = in_picture->interlaced_frame;

        if (ost->st->codec->flags & (CODEC_FLAG_INTERLACED_DCT|CODEC_FLAG_INTERLACED_ME)) {

            if (ost->top_field_first == -1)

                big_picture.top_field_first = in_picture->top_field_first;

            else

                big_picture.top_field_first = !!ost->top_field_first;




        /* handles same_quant here. This is not correct because it may

           not be a global option */

        big_picture.quality = quality;

        if (!enc->me_threshold)

            big_picture.pict_type = 0;

        if (ost->forced_kf_index < ost->forced_kf_count &&

            big_picture.pts >= ost->forced_kf_pts[ost->forced_kf_index]) {

            big_picture.pict_type = AV_PICTURE_TYPE_I;

            ost->forced_kf_index++;


        update_benchmark(NULL);

        ret = avcodec_encode_video2(enc, &pkt, &big_picture, &got_packet);

        update_benchmark("encode_video %d.%d", ost->file_index, ost->index);

        if (ret < 0) {

            av_log(NULL, AV_LOG_FATAL, "Video encoding failed\n");

            exit_program(1);




        if (got_packet) {

            if (pkt.pts == AV_NOPTS_VALUE && !(enc->codec->capabilities & CODEC_CAP_DELAY))

                pkt.pts = ost->sync_opts;



            if (pkt.pts != AV_NOPTS_VALUE)

                pkt.pts = av_rescale_q(pkt.pts, enc->time_base, ost->st->time_base);

            if (pkt.dts != AV_NOPTS_VALUE)

                pkt.dts = av_rescale_q(pkt.dts, enc->time_base, ost->st->time_base);



            if (debug_ts) {

                av_log(NULL, AV_LOG_INFO, "encoder -> type:video "

                    "pkt_pts:%s pkt_pts_time:%s pkt_dts:%s pkt_dts_time:%s\n",

                    av_ts2str(pkt.pts), av_ts2timestr(pkt.pts, &ost->st->time_base),

                    av_ts2str(pkt.dts), av_ts2timestr(pkt.dts, &ost->st->time_base));




            write_frame(s, &pkt, ost);

            frame_size = pkt.size;

            video_size += pkt.size;

            av_free_packet(&pkt);



            /* if two pass, output log */

            if (ost->logfile && enc->stats_out) {

                fprintf(ost->logfile, "%s", enc->stats_out);




    ost->sync_opts++;

    /*

     * For video, number of frames in == number of packets out.

     * But there may be reordering, so we can't throw away frames on encoder

     * flush, we need to limit them here, before they go into encoder.

     */

    ost->frame_number++;



    if(--nb_frames)

        goto duplicate_frame;



    if (vstats_filename && frame_size)

        do_video_stats(output_files[ost->file_index]->ctx, ost, frame_size);

static ssize_t nic_receive(VLANClientState *vc, const uint8_t * buf, size_t size)

{

    /* TODO:

     * - Magic packets should set bit 30 in power management driver register.

     * - Interesting packets should set bit 29 in power management driver register.

     */

    EEPRO100State *s = vc->opaque;

    uint16_t rfd_status = 0xa000;

    static const uint8_t broadcast_macaddr[6] =

        { 0xff, 0xff, 0xff, 0xff, 0xff, 0xff };



    /* TODO: check multiple IA bit. */

    assert(!(s->configuration[20] & BIT(6)));



    if (s->configuration[8] & 0x80) {

        /* CSMA is disabled. */

        logout("%p received while CSMA is disabled\n", s);

        return -1;

    } else if (size < 64 && (s->configuration[7] & 1)) {

        /* Short frame and configuration byte 7/0 (discard short receive) set:

         * Short frame is discarded */

        logout("%p received short frame (%zu byte)\n", s, size);

        s->statistics.rx_short_frame_errors++;

        //~ return -1;

    } else if ((size > MAX_ETH_FRAME_SIZE + 4) && !(s->configuration[18] & 8)) {

        /* Long frame and configuration byte 18/3 (long receive ok) not set:

         * Long frames are discarded. */

        logout("%p received long frame (%zu byte), ignored\n", s, size);

        return -1;

    } else if (memcmp(buf, s->macaddr, 6) == 0) {       // !!!

        /* Frame matches individual address. */

        /* TODO: check configuration byte 15/4 (ignore U/L). */

        TRACE(RXTX, logout("%p received frame for me, len=%zu\n", s, size));

    } else if (memcmp(buf, broadcast_macaddr, 6) == 0) {

        /* Broadcast frame. */

        TRACE(RXTX, logout("%p received broadcast, len=%zu\n", s, size));

        rfd_status |= 0x0002;

    } else if (buf[0] & 0x01) { // !!!

        /* Multicast frame. */

        TRACE(RXTX, logout("%p received multicast, len=%zu\n", s, size));

        /* TODO: check multicast all bit. */

        assert(!(s->configuration[21] & BIT(3)));

        int mcast_idx = compute_mcast_idx(buf);

        if (!(s->mult[mcast_idx >> 3] & (1 << (mcast_idx & 7)))) {

            return size;

        }

        rfd_status |= 0x0002;

    } else if (s->configuration[15] & 1) {

        /* Promiscuous: receive all. */

        TRACE(RXTX, logout("%p received frame in promiscuous mode, len=%zu\n", s, size));

        rfd_status |= 0x0004;

    } else {

        TRACE(RXTX, logout("%p received frame, ignored, len=%zu,%s\n", s, size,

              nic_dump(buf, size)));

        return size;

    }



    if (get_ru_state(s) != ru_ready) {

        /* No resources available. */

        logout("no resources, state=%u\n", get_ru_state(s));

        s->statistics.rx_resource_errors++;

        //~ assert(!"no resources");

        return -1;

    }

    //~ !!!

//~ $3 = {status = 0x0, command = 0xc000, link = 0x2d220, rx_buf_addr = 0x207dc, count = 0x0, size = 0x5f8, packet = {0x0 <repeats 1518 times>}}

    eepro100_rx_t rx;

    cpu_physical_memory_read(s->ru_base + s->ru_offset, (uint8_t *) & rx,

                             offsetof(eepro100_rx_t, packet));

    uint16_t rfd_command = le16_to_cpu(rx.command);

    uint16_t rfd_size = le16_to_cpu(rx.size);

    assert(size <= rfd_size);

    if (size < 64) {

        rfd_status |= 0x0080;

    }

    TRACE(OTHER, logout("command 0x%04x, link 0x%08x, addr 0x%08x, size %u\n",

          rfd_command, rx.link, rx.rx_buf_addr, rfd_size));

    stw_phys(s->ru_base + s->ru_offset + offsetof(eepro100_rx_t, status),

             rfd_status);

    stw_phys(s->ru_base + s->ru_offset + offsetof(eepro100_rx_t, count), size);

    /* Early receive interrupt not supported. */

    //~ eepro100_er_interrupt(s);

    /* Receive CRC Transfer not supported. */

    assert(!(s->configuration[18] & 4));

    /* TODO: check stripping enable bit. */

    //~ assert(!(s->configuration[17] & 1));

    cpu_physical_memory_write(s->ru_base + s->ru_offset +

                              offsetof(eepro100_rx_t, packet), buf, size);

    s->statistics.rx_good_frames++;

    eepro100_fr_interrupt(s);

    s->ru_offset = le32_to_cpu(rx.link);

    if (rfd_command & 0x8000) {

        /* EL bit is set, so this was the last frame. */

        assert(0);

    }

    if (rfd_command & 0x4000) {

        /* S bit is set. */

        set_ru_state(s, ru_suspended);

    }

    return size;

}

static void mp3_write_xing(AVFormatContext *s)

{

    MP3Context       *mp3 = s->priv_data;

    AVCodecContext *codec = s->streams[mp3->audio_stream_idx]->codec;

    int32_t        header;

    MPADecodeHeader  mpah;

    int srate_idx, i, channels;

    int bitrate_idx;

    int best_bitrate_idx;

    int best_bitrate_error = INT_MAX;

    int xing_offset;

    int ver = 0;

    int lsf, bytes_needed;



    if (!s->pb->seekable || !mp3->write_xing)

        return;



    for (i = 0; i < FF_ARRAY_ELEMS(avpriv_mpa_freq_tab); i++) {

        const uint16_t base_freq = avpriv_mpa_freq_tab[i];



        if      (codec->sample_rate == base_freq)     ver = 0x3; // MPEG 1

        else if (codec->sample_rate == base_freq / 2) ver = 0x2; // MPEG 2

        else if (codec->sample_rate == base_freq / 4) ver = 0x0; // MPEG 2.5

        else continue;



        srate_idx = i;

        break;

    }

    if (i == FF_ARRAY_ELEMS(avpriv_mpa_freq_tab)) {

        av_log(s, AV_LOG_WARNING, "Unsupported sample rate, not writing Xing "

               "header.\n");

        return;

    }



    switch (codec->channels) {

    case 1:  channels = MPA_MONO;                                          break;

    case 2:  channels = MPA_STEREO;                                        break;

    default: av_log(s, AV_LOG_WARNING, "Unsupported number of channels, "

                    "not writing Xing header.\n");

             return;

    }



    /* dummy MPEG audio header */

    header  =  0xff                                  << 24; // sync

    header |= (0x7 << 5 | ver << 3 | 0x1 << 1 | 0x1) << 16; // sync/audio-version/layer 3/no crc*/

    header |= (srate_idx << 2) << 8;

    header |= channels << 6;



    lsf = !((header & (1 << 20) && header & (1 << 19)));



    xing_offset  = xing_offtbl[ver != 3][channels == 1];

    bytes_needed = 4              // header

                 + xing_offset

                 + 4              // xing tag

                 + 4              // frames/size/toc flags

                 + 4              // frames

                 + 4              // size

                 + XING_TOC_SIZE; // toc



    for (bitrate_idx = 1; bitrate_idx < 15; bitrate_idx++) {

        int bit_rate = 1000 * avpriv_mpa_bitrate_tab[lsf][3 - 1][bitrate_idx];

        int error    = FFABS(bit_rate - codec->bit_rate);



        if (error < best_bitrate_error){

            best_bitrate_error = error;

            best_bitrate_idx   = bitrate_idx;

        }

    }



    for (bitrate_idx = best_bitrate_idx; bitrate_idx < 15; bitrate_idx++) {

        int32_t mask = bitrate_idx << (4 + 8);

        header |= mask;



        avpriv_mpegaudio_decode_header(&mpah, header);



        if (bytes_needed <= mpah.frame_size)

            break;



        header &= ~mask;

    }



    avio_wb32(s->pb, header);



    avpriv_mpegaudio_decode_header(&mpah, header);



    av_assert0(mpah.frame_size >= XING_MAX_SIZE);



    ffio_fill(s->pb, 0, xing_offset);

    mp3->xing_offset = avio_tell(s->pb);

    ffio_wfourcc(s->pb, "Xing");

    avio_wb32(s->pb, 0x01 | 0x02 | 0x04);  // frames / size / TOC



    mp3->size = mpah.frame_size;

    mp3->want = 1;



    avio_wb32(s->pb, 0);  // frames

    avio_wb32(s->pb, 0);  // size



    // TOC

    for (i = 0; i < XING_TOC_SIZE; i++)

        avio_w8(s->pb, 255 * i / XING_TOC_SIZE);



    ffio_fill(s->pb, 0, mpah.frame_size - bytes_needed);

}

static char *pcibus_get_dev_path(DeviceState *dev)

{

    PCIDevice *d = container_of(dev, PCIDevice, qdev);

    PCIDevice *t;

    int slot_depth;

    /* Path format: Domain:00:Slot.Function:Slot.Function....:Slot.Function.

     * 00 is added here to make this format compatible with

     * domain:Bus:Slot.Func for systems without nested PCI bridges.

     * Slot.Function list specifies the slot and function numbers for all

     * devices on the path from root to the specific device. */

    int domain_len = strlen("DDDD:00");

    int slot_len = strlen(":SS.F");

    int path_len;

    char *path, *p;



    /* Calculate # of slots on path between device and root. */;

    slot_depth = 0;

    for (t = d; t; t = t->bus->parent_dev) {

        ++slot_depth;

    }



    path_len = domain_len + slot_len * slot_depth;



    /* Allocate memory, fill in the terminating null byte. */

    path = malloc(path_len + 1 /* For '\0' */);

    path[path_len] = '\0';



    /* First field is the domain. */

    snprintf(path, domain_len, "%04x:00", pci_find_domain(d->bus));



    /* Fill in slot numbers. We walk up from device to root, so need to print

     * them in the reverse order, last to first. */

    p = path + path_len;

    for (t = d; t; t = t->bus->parent_dev) {

        p -= slot_len;

        snprintf(p, slot_len, ":%02x.%x", PCI_SLOT(t->devfn), PCI_FUNC(d->devfn));

    }



    return path;

}

xilinx_pcie_init(MemoryRegion *sys_mem, uint32_t bus_nr,

                 hwaddr cfg_base, uint64_t cfg_size,

                 hwaddr mmio_base, uint64_t mmio_size,

                 qemu_irq irq, bool link_up)

{

    DeviceState *dev;

    MemoryRegion *cfg, *mmio;



    dev = qdev_create(NULL, TYPE_XILINX_PCIE_HOST);



    qdev_prop_set_uint32(dev, "bus_nr", bus_nr);

    qdev_prop_set_uint64(dev, "cfg_base", cfg_base);

    qdev_prop_set_uint64(dev, "cfg_size", cfg_size);

    qdev_prop_set_uint64(dev, "mmio_base", mmio_base);

    qdev_prop_set_uint64(dev, "mmio_size", mmio_size);

    qdev_prop_set_bit(dev, "link_up", link_up);



    qdev_init_nofail(dev);



    cfg = sysbus_mmio_get_region(SYS_BUS_DEVICE(dev), 0);

    memory_region_add_subregion_overlap(sys_mem, cfg_base, cfg, 0);



    mmio = sysbus_mmio_get_region(SYS_BUS_DEVICE(dev), 1);

    memory_region_add_subregion_overlap(sys_mem, 0, mmio, 0);



    qdev_connect_gpio_out_named(dev, "interrupt_out", 0, irq);



    return XILINX_PCIE_HOST(dev);

}

static int decode_frame(AVCodecContext *avctx, void *data, int *data_size, AVPacket *pkt)

{

    BinkContext * const c = avctx->priv_data;

    GetBitContext gb;

    int blk;

    int i, j, plane, plane_idx, bx, by;

    uint8_t *dst, *prev, *ref, *ref_start, *ref_end;

    int v, col[2];

    const uint8_t *scan;

    int xoff, yoff;

    DECLARE_ALIGNED_16(DCTELEM, block[64]);

    DECLARE_ALIGNED_16(uint8_t, ublock[64]);

    int coordmap[64];



    if(c->pic.data[0])

        avctx->release_buffer(avctx, &c->pic);



    if(avctx->get_buffer(avctx, &c->pic) < 0){

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }



    init_get_bits(&gb, pkt->data, pkt->size*8);

    if (c->version >= 'i')

        skip_bits_long(&gb, 32);



    for (plane = 0; plane < 3; plane++) {

        const int stride = c->pic.linesize[plane];

        int bw = plane ? (avctx->width  + 15) >> 4 : (avctx->width  + 7) >> 3;

        int bh = plane ? (avctx->height + 15) >> 4 : (avctx->height + 7) >> 3;

        int width = avctx->width >> !!plane;



        init_lengths(c, FFMAX(width, 8), bw);

        for (i = 0; i < BINK_NB_SRC; i++)

            read_bundle(&gb, c, i);



        plane_idx = (!plane || !c->swap_planes) ? plane : (plane ^ 3);

        ref_start = c->last.data[plane_idx];

        ref_end   = c->last.data[plane_idx]

                    + (bw - 1 + c->last.linesize[plane_idx] * (bh - 1)) * 8;



        for (i = 0; i < 64; i++)

            coordmap[i] = (i & 7) + (i >> 3) * stride;



        for (by = 0; by < bh; by++) {

            if (read_block_types(avctx, &gb, &c->bundle[BINK_SRC_BLOCK_TYPES]) < 0)

                return -1;

            if (read_block_types(avctx, &gb, &c->bundle[BINK_SRC_SUB_BLOCK_TYPES]) < 0)

                return -1;

            if (read_colors(&gb, &c->bundle[BINK_SRC_COLORS], c) < 0)

                return -1;

            if (read_patterns(avctx, &gb, &c->bundle[BINK_SRC_PATTERN]) < 0)

                return -1;

            if (read_motion_values(avctx, &gb, &c->bundle[BINK_SRC_X_OFF]) < 0)

                return -1;

            if (read_motion_values(avctx, &gb, &c->bundle[BINK_SRC_Y_OFF]) < 0)

                return -1;

            if (read_dcs(avctx, &gb, &c->bundle[BINK_SRC_INTRA_DC], DC_START_BITS, 0) < 0)

                return -1;

            if (read_dcs(avctx, &gb, &c->bundle[BINK_SRC_INTER_DC], DC_START_BITS, 1) < 0)

                return -1;

            if (read_runs(avctx, &gb, &c->bundle[BINK_SRC_RUN]) < 0)

                return -1;



            if (by == bh)

                break;

            dst  = c->pic.data[plane_idx]  + 8*by*stride;

            prev = c->last.data[plane_idx] + 8*by*stride;

            for (bx = 0; bx < bw; bx++, dst += 8, prev += 8) {

                blk = get_value(c, BINK_SRC_BLOCK_TYPES);

                // 16x16 block type on odd line means part of the already decoded block, so skip it

                if ((by & 1) && blk == SCALED_BLOCK) {

                    bx++;

                    dst  += 8;

                    prev += 8;

                    continue;

                }

                switch (blk) {

                case SKIP_BLOCK:

                    c->dsp.put_pixels_tab[1][0](dst, prev, stride, 8);

                    break;

                case SCALED_BLOCK:

                    blk = get_value(c, BINK_SRC_SUB_BLOCK_TYPES);

                    switch (blk) {

                    case RUN_BLOCK:

                        scan = bink_patterns[get_bits(&gb, 4)];

                        i = 0;

                        do {

                            int run = get_value(c, BINK_SRC_RUN) + 1;



                            i += run;

                            if (i > 64) {

                                av_log(avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                                return -1;

                            }

                            if (get_bits1(&gb)) {

                                v = get_value(c, BINK_SRC_COLORS);

                                for (j = 0; j < run; j++)

                                    ublock[*scan++] = v;

                            } else {

                                for (j = 0; j < run; j++)

                                    ublock[*scan++] = get_value(c, BINK_SRC_COLORS);

                            }

                        } while (i < 63);

                        if (i == 63)

                            ublock[*scan++] = get_value(c, BINK_SRC_COLORS);

                        break;

                    case INTRA_BLOCK:

                        c->dsp.clear_block(block);

                        block[0] = get_value(c, BINK_SRC_INTRA_DC);

                        read_dct_coeffs(&gb, block, c->scantable.permutated, 1);

                        c->dsp.idct(block);

                        c->dsp.put_pixels_nonclamped(block, ublock, 8);

                        break;

                    case FILL_BLOCK:

                        v = get_value(c, BINK_SRC_COLORS);

                        c->dsp.fill_block_tab[0](dst, v, stride, 16);

                        break;

                    case PATTERN_BLOCK:

                        for (i = 0; i < 2; i++)

                            col[i] = get_value(c, BINK_SRC_COLORS);

                        for (j = 0; j < 8; j++) {

                            v = get_value(c, BINK_SRC_PATTERN);

                            for (i = 0; i < 8; i++, v >>= 1)

                                ublock[i + j*8] = col[v & 1];

                        }

                        break;

                    case RAW_BLOCK:

                        for (j = 0; j < 8; j++)

                            for (i = 0; i < 8; i++)

                                ublock[i + j*8] = get_value(c, BINK_SRC_COLORS);

                        break;

                    default:

                        av_log(avctx, AV_LOG_ERROR, "Incorrect 16x16 block type %d\n", blk);

                        return -1;

                    }

                    if (blk != FILL_BLOCK)

                        c->dsp.scale_block(ublock, dst, stride);

                    bx++;

                    dst  += 8;

                    prev += 8;

                    break;

                case MOTION_BLOCK:

                    xoff = get_value(c, BINK_SRC_X_OFF);

                    yoff = get_value(c, BINK_SRC_Y_OFF);

                    ref = prev + xoff + yoff * stride;

                    if (ref < ref_start || ref > ref_end) {

                        av_log(avctx, AV_LOG_ERROR, "Copy out of bounds @%d, %d\n",

                               bx*8 + xoff, by*8 + yoff);

                        return -1;

                    }

                    c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                    break;

                case RUN_BLOCK:

                    scan = bink_patterns[get_bits(&gb, 4)];

                    i = 0;

                    do {

                        int run = get_value(c, BINK_SRC_RUN) + 1;



                        i += run;

                        if (i > 64) {

                            av_log(avctx, AV_LOG_ERROR, "Run went out of bounds\n");

                            return -1;

                        }

                        if (get_bits1(&gb)) {

                            v = get_value(c, BINK_SRC_COLORS);

                            for (j = 0; j < run; j++)

                                dst[coordmap[*scan++]] = v;

                        } else {

                            for (j = 0; j < run; j++)

                                dst[coordmap[*scan++]] = get_value(c, BINK_SRC_COLORS);

                        }

                    } while (i < 63);

                    if (i == 63)

                        dst[coordmap[*scan++]] = get_value(c, BINK_SRC_COLORS);

                    break;

                case RESIDUE_BLOCK:

                    xoff = get_value(c, BINK_SRC_X_OFF);

                    yoff = get_value(c, BINK_SRC_Y_OFF);

                    ref = prev + xoff + yoff * stride;

                    if (ref < ref_start || ref > ref_end) {

                        av_log(avctx, AV_LOG_ERROR, "Copy out of bounds @%d, %d\n",

                               bx*8 + xoff, by*8 + yoff);

                        return -1;

                    }

                    c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                    c->dsp.clear_block(block);

                    v = get_bits(&gb, 7);

                    read_residue(&gb, block, v);

                    c->dsp.add_pixels8(dst, block, stride);

                    break;

                case INTRA_BLOCK:

                    c->dsp.clear_block(block);

                    block[0] = get_value(c, BINK_SRC_INTRA_DC);

                    read_dct_coeffs(&gb, block, c->scantable.permutated, 1);

                    c->dsp.idct_put(dst, stride, block);

                    break;

                case FILL_BLOCK:

                    v = get_value(c, BINK_SRC_COLORS);

                    c->dsp.fill_block_tab[1](dst, v, stride, 8);

                    break;

                case INTER_BLOCK:

                    xoff = get_value(c, BINK_SRC_X_OFF);

                    yoff = get_value(c, BINK_SRC_Y_OFF);

                    ref = prev + xoff + yoff * stride;

                    c->dsp.put_pixels_tab[1][0](dst, ref, stride, 8);

                    c->dsp.clear_block(block);

                    block[0] = get_value(c, BINK_SRC_INTER_DC);

                    read_dct_coeffs(&gb, block, c->scantable.permutated, 0);

                    c->dsp.idct_add(dst, stride, block);

                    break;

                case PATTERN_BLOCK:

                    for (i = 0; i < 2; i++)

                        col[i] = get_value(c, BINK_SRC_COLORS);

                    for (i = 0; i < 8; i++) {

                        v = get_value(c, BINK_SRC_PATTERN);

                        for (j = 0; j < 8; j++, v >>= 1)

                            dst[i*stride + j] = col[v & 1];

                    }

                    break;

                case RAW_BLOCK:

                    for (i = 0; i < 8; i++)

                        memcpy(dst + i*stride, c->bundle[BINK_SRC_COLORS].cur_ptr + i*8, 8);

                    c->bundle[BINK_SRC_COLORS].cur_ptr += 64;

                    break;

                default:

                    av_log(avctx, AV_LOG_ERROR, "Unknown block type %d\n", blk);

                    return -1;

                }

            }

        }

        if (get_bits_count(&gb) & 0x1F) //next plane data starts at 32-bit boundary

            skip_bits_long(&gb, 32 - (get_bits_count(&gb) & 0x1F));

    }

    emms_c();



    *data_size = sizeof(AVFrame);

    *(AVFrame*)data = c->pic;



    FFSWAP(AVFrame, c->pic, c->last);



    /* always report that the buffer was completely consumed */

    return pkt->size;

}

