static int64_t coroutine_fn raw_co_get_block_status(BlockDriverState *bs,

                                                    int64_t sector_num,

                                                    int nb_sectors, int *pnum)

{

    off_t start, data = 0, hole = 0;

    int64_t total_size;

    int ret;



    ret = fd_open(bs);

    if (ret < 0) {

        return ret;

    }



    start = sector_num * BDRV_SECTOR_SIZE;

    total_size = bdrv_getlength(bs);

    if (total_size < 0) {

        return total_size;

    } else if (start >= total_size) {

        *pnum = 0;

        return 0;

    } else if (start + nb_sectors * BDRV_SECTOR_SIZE > total_size) {

        nb_sectors = DIV_ROUND_UP(total_size - start, BDRV_SECTOR_SIZE);

    }



    ret = find_allocation(bs, start, &data, &hole);

    if (ret == -ENXIO) {

        /* Trailing hole */

        *pnum = nb_sectors;

        ret = BDRV_BLOCK_ZERO;

    } else if (ret < 0) {

        /* No info available, so pretend there are no holes */

        *pnum = nb_sectors;

        ret = BDRV_BLOCK_DATA;

    } else if (data == start) {

        /* On a data extent, compute sectors to the end of the extent,

         * possibly including a partial sector at EOF. */

        *pnum = MIN(nb_sectors, DIV_ROUND_UP(hole - start, BDRV_SECTOR_SIZE));

        ret = BDRV_BLOCK_DATA;

    } else {

        /* On a hole, compute sectors to the beginning of the next extent.  */

        assert(hole == start);

        *pnum = MIN(nb_sectors, (data - start) / BDRV_SECTOR_SIZE);

        ret = BDRV_BLOCK_ZERO;

    }

    return ret | BDRV_BLOCK_OFFSET_VALID | start;

}

static int drawgrid_filter_frame(AVFilterLink *inlink, AVFrame *frame)

{

    DrawBoxContext *drawgrid = inlink->dst->priv;

    int plane, x, y;

    uint8_t *row[4];



    if (drawgrid->have_alpha) {

        for (y = 0; y < frame->height; y++) {

            row[0] = frame->data[0] + y * frame->linesize[0];

            row[3] = frame->data[3] + y * frame->linesize[3];



            for (plane = 1; plane < 3; plane++)

                row[plane] = frame->data[plane] +

                     frame->linesize[plane] * (y >> drawgrid->vsub);



            if (drawgrid->invert_color) {

                for (x = 0; x < frame->width; x++)

                    if (pixel_belongs_to_grid(drawgrid, x, y))

                        row[0][x] = 0xff - row[0][x];

            } else {

                for (x = 0; x < frame->width; x++) {

                    if (pixel_belongs_to_grid(drawgrid, x, y)) {

                        row[0][x                  ] = drawgrid->yuv_color[Y];

                        row[1][x >> drawgrid->hsub] = drawgrid->yuv_color[U];

                        row[2][x >> drawgrid->hsub] = drawgrid->yuv_color[V];

                        row[3][x                  ] = drawgrid->yuv_color[A];

                    }

                }

            }

        }

    } else {

        for (y = 0; y < frame->height; y++) {

            row[0] = frame->data[0] + y * frame->linesize[0];



            for (plane = 1; plane < 3; plane++)

                row[plane] = frame->data[plane] +

                     frame->linesize[plane] * (y >> drawgrid->vsub);



            if (drawgrid->invert_color) {

                for (x = 0; x < frame->width; x++)

                    if (pixel_belongs_to_grid(drawgrid, x, y))

                        row[0][x] = 0xff - row[0][x];

            } else {

                for (x = 0; x < frame->width; x++) {

                    double alpha = (double)drawgrid->yuv_color[A] / 255;



                    if (pixel_belongs_to_grid(drawgrid, x, y)) {

                        row[0][x                  ] = (1 - alpha) * row[0][x                  ] + alpha * drawgrid->yuv_color[Y];

                        row[1][x >> drawgrid->hsub] = (1 - alpha) * row[1][x >> drawgrid->hsub] + alpha * drawgrid->yuv_color[U];

                        row[2][x >> drawgrid->hsub] = (1 - alpha) * row[2][x >> drawgrid->hsub] + alpha * drawgrid->yuv_color[V];

                    }

                }

            }

        }

    }



    return ff_filter_frame(inlink->dst->outputs[0], frame);

}

static int pcm_encode_frame(AVCodecContext *avctx, AVPacket *avpkt,

                            const AVFrame *frame, int *got_packet_ptr)

{

    int n, c, sample_size, v, ret;

    const short *samples;

    unsigned char *dst;

    const uint8_t *samples_uint8_t;

    const int16_t *samples_int16_t;

    const int32_t *samples_int32_t;

    const int64_t *samples_int64_t;

    const uint16_t *samples_uint16_t;

    const uint32_t *samples_uint32_t;



    sample_size = av_get_bits_per_sample(avctx->codec->id) / 8;

    n           = frame->nb_samples * avctx->channels;

    samples     = (const short *)frame->data[0];



    if ((ret = ff_alloc_packet2(avctx, avpkt, n * sample_size)))

        return ret;

    dst = avpkt->data;



    switch (avctx->codec->id) {

    case AV_CODEC_ID_PCM_U32LE:

        ENCODE(uint32_t, le32, samples, dst, n, 0, 0x80000000)

        break;

    case AV_CODEC_ID_PCM_U32BE:

        ENCODE(uint32_t, be32, samples, dst, n, 0, 0x80000000)

        break;

    case AV_CODEC_ID_PCM_S24LE:

        ENCODE(int32_t, le24, samples, dst, n, 8, 0)

        break;

    case AV_CODEC_ID_PCM_S24LE_PLANAR:

        ENCODE_PLANAR(int32_t, le24, dst, n, 8, 0)

        break;

    case AV_CODEC_ID_PCM_S24BE:

        ENCODE(int32_t, be24, samples, dst, n, 8, 0)

        break;

    case AV_CODEC_ID_PCM_U24LE:

        ENCODE(uint32_t, le24, samples, dst, n, 8, 0x800000)

        break;

    case AV_CODEC_ID_PCM_U24BE:

        ENCODE(uint32_t, be24, samples, dst, n, 8, 0x800000)

        break;

    case AV_CODEC_ID_PCM_S24DAUD:

        for (; n > 0; n--) {

            uint32_t tmp = ff_reverse[(*samples >> 8) & 0xff] +

                           (ff_reverse[*samples & 0xff] << 8);

            tmp <<= 4; // sync flags would go here

            bytestream_put_be24(&dst, tmp);

            samples++;

        }

        break;

    case AV_CODEC_ID_PCM_U16LE:

        ENCODE(uint16_t, le16, samples, dst, n, 0, 0x8000)

        break;

    case AV_CODEC_ID_PCM_U16BE:

        ENCODE(uint16_t, be16, samples, dst, n, 0, 0x8000)

        break;

    case AV_CODEC_ID_PCM_S8:

        ENCODE(uint8_t, byte, samples, dst, n, 0, -128)

        break;

    case AV_CODEC_ID_PCM_S8_PLANAR:

        ENCODE_PLANAR(uint8_t, byte, dst, n, 0, -128)

        break;

#if HAVE_BIGENDIAN

    case AV_CODEC_ID_PCM_F64LE:

        ENCODE(int64_t, le64, samples, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S32LE:

    case AV_CODEC_ID_PCM_F32LE:

        ENCODE(int32_t, le32, samples, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S32LE_PLANAR:

        ENCODE_PLANAR(int32_t, le32, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S16LE:

        ENCODE(int16_t, le16, samples, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S16LE_PLANAR:

        ENCODE_PLANAR(int16_t, le16, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F64BE:

    case AV_CODEC_ID_PCM_F32BE:

    case AV_CODEC_ID_PCM_S32BE:

    case AV_CODEC_ID_PCM_S16BE:

#else

    case AV_CODEC_ID_PCM_F64BE:

        ENCODE(int64_t, be64, samples, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F32BE:

    case AV_CODEC_ID_PCM_S32BE:

        ENCODE(int32_t, be32, samples, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S16BE:

        ENCODE(int16_t, be16, samples, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_S16BE_PLANAR:

        ENCODE_PLANAR(int16_t, be16, dst, n, 0, 0)

        break;

    case AV_CODEC_ID_PCM_F64LE:

    case AV_CODEC_ID_PCM_F32LE:

    case AV_CODEC_ID_PCM_S32LE:

    case AV_CODEC_ID_PCM_S16LE:

#endif /* HAVE_BIGENDIAN */

    case AV_CODEC_ID_PCM_U8:

        memcpy(dst, samples, n * sample_size);

        break;

#if HAVE_BIGENDIAN

    case AV_CODEC_ID_PCM_S16BE_PLANAR:

#else

    case AV_CODEC_ID_PCM_S16LE_PLANAR:

    case AV_CODEC_ID_PCM_S32LE_PLANAR:

#endif /* HAVE_BIGENDIAN */

        n /= avctx->channels;

        for (c = 0; c < avctx->channels; c++) {

            const uint8_t *src = frame->extended_data[c];

            bytestream_put_buffer(&dst, src, n * sample_size);

        }

        break;

    case AV_CODEC_ID_PCM_ALAW:

        for (; n > 0; n--) {

            v      = *samples++;

            *dst++ = linear_to_alaw[(v + 32768) >> 2];

        }

        break;

    case AV_CODEC_ID_PCM_MULAW:

        for (; n > 0; n--) {

            v      = *samples++;

            *dst++ = linear_to_ulaw[(v + 32768) >> 2];

        }

        break;

    default:

        return -1;

    }



    *got_packet_ptr = 1;

    return 0;

}

static int rtsp_read_play(AVFormatContext *s)

{

    RTSPState *rt = s->priv_data;

    RTSPMessageHeader reply1, *reply = &reply1;

    int i;

    char cmd[1024];



    av_log(s, AV_LOG_DEBUG, "hello state=%d\n", rt->state);



    if (!(rt->server_type == RTSP_SERVER_REAL && rt->need_subscription)) {

        if (rt->state == RTSP_STATE_PAUSED) {

            cmd[0] = 0;

        } else {

            snprintf(cmd, sizeof(cmd),

                     "Range: npt=%0.3f-\r\n",

                     (double)rt->seek_timestamp / AV_TIME_BASE);

        }

        ff_rtsp_send_cmd(s, "PLAY", rt->control_uri, cmd, reply, NULL);

        if (reply->status_code != RTSP_STATUS_OK) {

            return -1;

        }

        if (reply->range_start != AV_NOPTS_VALUE &&

            rt->transport == RTSP_TRANSPORT_RTP) {

            for (i = 0; i < rt->nb_rtsp_streams; i++) {

                RTSPStream *rtsp_st = rt->rtsp_streams[i];

                RTPDemuxContext *rtpctx = rtsp_st->transport_priv;

                AVStream *st = NULL;



                if (rtsp_st->stream_index >= 0)

                    st = s->streams[rtsp_st->stream_index];

                rtpctx->last_rtcp_ntp_time  = AV_NOPTS_VALUE;

                rtpctx->first_rtcp_ntp_time = AV_NOPTS_VALUE;

                if (st)

                    rtpctx->range_start_offset = av_rescale_q(reply->range_start,

                                                              AV_TIME_BASE_Q,

                                                              st->time_base);

            }

        }

    }

    rt->state = RTSP_STATE_STREAMING;

    return 0;

}

static int scsi_generic_initfn(SCSIDevice *s)

{

    int rc;

    int sg_version;

    struct sg_scsi_id scsiid;



    if (!s->conf.bs) {

        error_report("drive property not set");

        return -1;

    }



    if (bdrv_get_on_error(s->conf.bs, 0) != BLOCKDEV_ON_ERROR_ENOSPC) {

        error_report("Device doesn't support drive option werror");

        return -1;

    }

    if (bdrv_get_on_error(s->conf.bs, 1) != BLOCKDEV_ON_ERROR_REPORT) {

        error_report("Device doesn't support drive option rerror");

        return -1;

    }



    /* check we are using a driver managing SG_IO (version 3 and after */

    rc = bdrv_ioctl(s->conf.bs, SG_GET_VERSION_NUM, &sg_version);

    if (rc < 0) {

        error_report("cannot get SG_IO version number: %s.  "

                     "Is this a SCSI device?",

                     strerror(-rc));

        return -1;

    }

    if (sg_version < 30000) {

        error_report("scsi generic interface too old");

        return -1;

    }



    /* get LUN of the /dev/sg? */

    if (bdrv_ioctl(s->conf.bs, SG_GET_SCSI_ID, &scsiid)) {

        error_report("SG_GET_SCSI_ID ioctl failed");

        return -1;

    }



    /* define device state */

    s->type = scsiid.scsi_type;

    DPRINTF("device type %d\n", s->type);

    if (s->type == TYPE_DISK || s->type == TYPE_ROM) {

        add_boot_device_path(s->conf.bootindex, &s->qdev, NULL);

    }



    switch (s->type) {

    case TYPE_TAPE:

        s->blocksize = get_stream_blocksize(s->conf.bs);

        if (s->blocksize == -1) {

            s->blocksize = 0;

        }

        break;



        /* Make a guess for block devices, we'll fix it when the guest sends.

         * READ CAPACITY.  If they don't, they likely would assume these sizes

         * anyway. (TODO: they could also send MODE SENSE).

         */

    case TYPE_ROM:

    case TYPE_WORM:

        s->blocksize = 2048;

        break;

    default:

        s->blocksize = 512;

        break;

    }



    DPRINTF("block size %d\n", s->blocksize);

    return 0;

}

static int coroutine_fn iscsi_co_readv(BlockDriverState *bs,

                                       int64_t sector_num, int nb_sectors,

                                       QEMUIOVector *iov)

{

    IscsiLun *iscsilun = bs->opaque;

    struct IscsiTask iTask;

    uint64_t lba;

    uint32_t num_sectors;



    if (!is_sector_request_lun_aligned(sector_num, nb_sectors, iscsilun)) {

        return -EINVAL;

    }



    if (bs->bl.max_transfer &&

        nb_sectors << BDRV_SECTOR_BITS > bs->bl.max_transfer) {

        error_report("iSCSI Error: Read of %d sectors exceeds max_xfer_len "

                     "of %" PRIu32 " bytes", nb_sectors, bs->bl.max_transfer);

        return -EINVAL;

    }



    if (iscsilun->lbprz && nb_sectors >= ISCSI_CHECKALLOC_THRES &&

        !iscsi_allocationmap_is_allocated(iscsilun, sector_num, nb_sectors)) {

        int64_t ret;

        int pnum;

        BlockDriverState *file;

        ret = iscsi_co_get_block_status(bs, sector_num,

                                        BDRV_REQUEST_MAX_SECTORS, &pnum, &file);

        if (ret < 0) {

            return ret;

        }

        if (ret & BDRV_BLOCK_ZERO && pnum >= nb_sectors) {

            qemu_iovec_memset(iov, 0, 0x00, iov->size);

            return 0;

        }

    }



    lba = sector_qemu2lun(sector_num, iscsilun);

    num_sectors = sector_qemu2lun(nb_sectors, iscsilun);



    iscsi_co_init_iscsitask(iscsilun, &iTask);

retry:

    if (iscsilun->use_16_for_rw) {

        iTask.task = iscsi_read16_task(iscsilun->iscsi, iscsilun->lun, lba,

                                       num_sectors * iscsilun->block_size,

                                       iscsilun->block_size, 0, 0, 0, 0, 0,

                                       iscsi_co_generic_cb, &iTask);

    } else {

        iTask.task = iscsi_read10_task(iscsilun->iscsi, iscsilun->lun, lba,

                                       num_sectors * iscsilun->block_size,

                                       iscsilun->block_size,

                                       0, 0, 0, 0, 0,

                                       iscsi_co_generic_cb, &iTask);

    }

    if (iTask.task == NULL) {

        return -ENOMEM;

    }

    scsi_task_set_iov_in(iTask.task, (struct scsi_iovec *) iov->iov, iov->niov);



    while (!iTask.complete) {

        iscsi_set_events(iscsilun);

        qemu_coroutine_yield();

    }



    if (iTask.task != NULL) {

        scsi_free_scsi_task(iTask.task);

        iTask.task = NULL;

    }



    if (iTask.do_retry) {

        iTask.complete = 0;

        goto retry;

    }



    if (iTask.status != SCSI_STATUS_GOOD) {

        return iTask.err_code;

    }



    return 0;

}

