}

static uint32_t omap_sysctl_read(void *opaque, target_phys_addr_t addr)

{

    struct omap_sysctl_s *s = (struct omap_sysctl_s *) opaque;



    switch (addr) {

    case 0x000:	/* CONTROL_REVISION */

        return 0x20;



    case 0x010:	/* CONTROL_SYSCONFIG */

        return s->sysconfig;



    case 0x030 ... 0x140:	/* CONTROL_PADCONF - only used in the POP */

        return s->padconf[(addr - 0x30) >> 2];



    case 0x270:	/* CONTROL_DEBOBS */

        return s->obs;



    case 0x274:	/* CONTROL_DEVCONF */

        return s->devconfig;



    case 0x28c:	/* CONTROL_EMU_SUPPORT */

        return 0;



    case 0x290:	/* CONTROL_MSUSPENDMUX_0 */

        return s->msuspendmux[0];

    case 0x294:	/* CONTROL_MSUSPENDMUX_1 */

        return s->msuspendmux[1];

    case 0x298:	/* CONTROL_MSUSPENDMUX_2 */

        return s->msuspendmux[2];

    case 0x29c:	/* CONTROL_MSUSPENDMUX_3 */

        return s->msuspendmux[3];

    case 0x2a0:	/* CONTROL_MSUSPENDMUX_4 */

        return s->msuspendmux[4];

    case 0x2a4:	/* CONTROL_MSUSPENDMUX_5 */

        return 0;



    case 0x2b8:	/* CONTROL_PSA_CTRL */

        return s->psaconfig;

    case 0x2bc:	/* CONTROL_PSA_CMD */

    case 0x2c0:	/* CONTROL_PSA_VALUE */

        return 0;



    case 0x2b0:	/* CONTROL_SEC_CTRL */

        return 0x800000f1;

    case 0x2d0:	/* CONTROL_SEC_EMU */

        return 0x80000015;

    case 0x2d4:	/* CONTROL_SEC_TAP */

        return 0x8000007f;

    case 0x2b4:	/* CONTROL_SEC_TEST */

    case 0x2f0:	/* CONTROL_SEC_STATUS */

    case 0x2f4:	/* CONTROL_SEC_ERR_STATUS */

        /* Secure mode is not present on general-pusrpose device.  Outside

         * secure mode these values cannot be read or written.  */

        return 0;



    case 0x2d8:	/* CONTROL_OCM_RAM_PERM */

        return 0xff;

    case 0x2dc:	/* CONTROL_OCM_PUB_RAM_ADD */

    case 0x2e0:	/* CONTROL_EXT_SEC_RAM_START_ADD */

    case 0x2e4:	/* CONTROL_EXT_SEC_RAM_STOP_ADD */

        /* No secure mode so no Extended Secure RAM present.  */

        return 0;



    case 0x2f8:	/* CONTROL_STATUS */

        /* Device Type => General-purpose */

        return 0x0300;

    case 0x2fc:	/* CONTROL_GENERAL_PURPOSE_STATUS */



    case 0x300:	/* CONTROL_RPUB_KEY_H_0 */

    case 0x304:	/* CONTROL_RPUB_KEY_H_1 */

    case 0x308:	/* CONTROL_RPUB_KEY_H_2 */

    case 0x30c:	/* CONTROL_RPUB_KEY_H_3 */

        return 0xdecafbad;



    case 0x310:	/* CONTROL_RAND_KEY_0 */

    case 0x314:	/* CONTROL_RAND_KEY_1 */

    case 0x318:	/* CONTROL_RAND_KEY_2 */

    case 0x31c:	/* CONTROL_RAND_KEY_3 */

    case 0x320:	/* CONTROL_CUST_KEY_0 */

    case 0x324:	/* CONTROL_CUST_KEY_1 */

    case 0x330:	/* CONTROL_TEST_KEY_0 */

    case 0x334:	/* CONTROL_TEST_KEY_1 */

    case 0x338:	/* CONTROL_TEST_KEY_2 */

    case 0x33c:	/* CONTROL_TEST_KEY_3 */

    case 0x340:	/* CONTROL_TEST_KEY_4 */

    case 0x344:	/* CONTROL_TEST_KEY_5 */

    case 0x348:	/* CONTROL_TEST_KEY_6 */

    case 0x34c:	/* CONTROL_TEST_KEY_7 */

    case 0x350:	/* CONTROL_TEST_KEY_8 */

    case 0x354:	/* CONTROL_TEST_KEY_9 */

        /* Can only be accessed in secure mode and when C_FieldAccEnable

         * bit is set in CONTROL_SEC_CTRL.

         * TODO: otherwise an interconnect access error is generated.  */

        return 0;

    }



    OMAP_BAD_REG(addr);

    return 0;

}

static void g364fb_screen_dump(void *opaque, const char *filename)
{
    G364State *s = opaque;
    int y, x;
    uint8_t index;
    uint8_t *data_buffer;
    FILE *f;
    if (s->depth != 8) {
        error_report("g364: unknown guest depth %d", s->depth);
        return;
    }
    f = fopen(filename, "wb");
    if (!f)
        return;
    if (s->ctla & CTLA_FORCE_BLANK) {
        /* blank screen */
        fprintf(f, "P4\n%d %d\n",
            s->width, s->height);
        for (y = 0; y < s->height; y++)
            for (x = 0; x < s->width; x++)
                fputc(0, f);
    } else {
        data_buffer = s->vram + s->top_of_screen;
        fprintf(f, "P6\n%d %d\n%d\n",
            s->width, s->height, 255);
        for (y = 0; y < s->height; y++)
            for (x = 0; x < s->width; x++, data_buffer++) {
                index = *data_buffer;
                fputc(s->color_palette[index][0], f);
                fputc(s->color_palette[index][1], f);
                fputc(s->color_palette[index][2], f);
        }
    }
    fclose(f);
}

static int qcow2_create(const char *filename, QEMUOptionParameter *options)

{

    const char *backing_file = NULL;

    const char *backing_fmt = NULL;

    uint64_t sectors = 0;

    int flags = 0;

    size_t cluster_size = DEFAULT_CLUSTER_SIZE;

    int prealloc = 0;



    /* Read out options */

    while (options && options->name) {

        if (!strcmp(options->name, BLOCK_OPT_SIZE)) {

            sectors = options->value.n / 512;

        } else if (!strcmp(options->name, BLOCK_OPT_BACKING_FILE)) {

            backing_file = options->value.s;

        } else if (!strcmp(options->name, BLOCK_OPT_BACKING_FMT)) {

            backing_fmt = options->value.s;

        } else if (!strcmp(options->name, BLOCK_OPT_ENCRYPT)) {

            flags |= options->value.n ? BLOCK_FLAG_ENCRYPT : 0;

        } else if (!strcmp(options->name, BLOCK_OPT_CLUSTER_SIZE)) {

            if (options->value.n) {

                cluster_size = options->value.n;

            }

        } else if (!strcmp(options->name, BLOCK_OPT_PREALLOC)) {

            if (!options->value.s || !strcmp(options->value.s, "off")) {

                prealloc = 0;

            } else if (!strcmp(options->value.s, "metadata")) {

                prealloc = 1;

            } else {

                fprintf(stderr, "Invalid preallocation mode: '%s'\n",

                    options->value.s);

                return -EINVAL;

            }

        }

        options++;

    }



    if (backing_file && prealloc) {

        fprintf(stderr, "Backing file and preallocation cannot be used at "

            "the same time\n");

        return -EINVAL;

    }



    return qcow2_create2(filename, sectors, backing_file, backing_fmt, flags,

                         cluster_size, prealloc, options);

}

static int mpeg1_find_frame_end(MpegEncContext *s, uint8_t *buf, int buf_size){

    ParseContext *pc= &s->parse_context;

    int i;

    uint32_t state;



    state= pc->state;



    i=0;

    if(!pc->frame_start_found){

        for(i=0; i<buf_size; i++){

            state= (state<<8) | buf[i];

            if(state >= SLICE_MIN_START_CODE && state <= SLICE_MAX_START_CODE){

                i++;

                pc->frame_start_found=1;

                break;

            }

        }

    }



    if(pc->frame_start_found){

        for(; i<buf_size; i++){

            state= (state<<8) | buf[i];

            if((state&0xFFFFFF00) == 0x100){

                if(state < SLICE_MIN_START_CODE || state > SLICE_MAX_START_CODE){

                    pc->frame_start_found=0;

                    pc->state=-1; 

                    return i-3;

                }

            }

        }

    }        

    pc->state= state;

    return -1;

}

static void gd_resize(DisplayChangeListener *dcl,

                      DisplayState *ds)

{

    GtkDisplayState *s = ds->opaque;

    cairo_format_t kind;

    int stride;



    DPRINTF("resize(width=%d, height=%d)\n",

            ds_get_width(ds), ds_get_height(ds));



    if (s->surface) {

        cairo_surface_destroy(s->surface);

    }



    switch (ds->surface->pf.bits_per_pixel) {

    case 8:

        kind = CAIRO_FORMAT_A8;

        break;

    case 16:

        kind = CAIRO_FORMAT_RGB16_565;

        break;

    case 32:

        kind = CAIRO_FORMAT_RGB24;

        break;

    default:

        g_assert_not_reached();

        break;

    }



    stride = cairo_format_stride_for_width(kind, ds_get_width(ds));

    g_assert(ds_get_linesize(ds) == stride);



    s->surface = cairo_image_surface_create_for_data(ds_get_data(ds),

                                                     kind,

                                                     ds_get_width(ds),

                                                     ds_get_height(ds),

                                                     ds_get_linesize(ds));



    if (!s->full_screen) {

        GtkRequisition req;

        double sx, sy;



        if (s->free_scale) {

            sx = s->scale_x;

            sy = s->scale_y;



            s->scale_y = 1.0;

            s->scale_x = 1.0;

        } else {

            sx = 1.0;

            sy = 1.0;

        }



        gtk_widget_set_size_request(s->drawing_area,

                                    ds_get_width(ds) * s->scale_x,

                                    ds_get_height(ds) * s->scale_y);

#if GTK_CHECK_VERSION(3, 0, 0)

        gtk_widget_get_preferred_size(s->vbox, NULL, &req);

#else

        gtk_widget_size_request(s->vbox, &req);

#endif



        gtk_window_resize(GTK_WINDOW(s->window),

                          req.width * sx, req.height * sy);

    }

}

