static int read_packet(AVFormatContext *s, AVPacket *pkt)

{

    PAFDemuxContext *p = s->priv_data;

    AVIOContext     *pb = s->pb;

    uint32_t        count, offset;

    int             size, i;



    if (p->current_frame >= p->nb_frames)

        return AVERROR_EOF;



    if (url_feof(pb))

        return AVERROR_EOF;



    if (p->got_audio) {

        if (av_new_packet(pkt, p->audio_size) < 0)

            return AVERROR(ENOMEM);



        memcpy(pkt->data, p->temp_audio_frame, p->audio_size);

        pkt->duration     = PAF_SOUND_SAMPLES * (p->audio_size / PAF_SOUND_FRAME_SIZE);

        pkt->flags       |= AV_PKT_FLAG_KEY;

        pkt->stream_index = 1;

        p->got_audio      = 0;

        return pkt->size;

    }



    count = (p->current_frame == 0) ? p->preload_count : p->blocks_count_table[p->current_frame - 1];

    for (i = 0; i < count; i++) {

        if (p->current_frame_block >= p->frame_blks)

            return AVERROR_INVALIDDATA;



        offset = p->blocks_offset_table[p->current_frame_block] & ~(1U << 31);

        if (p->blocks_offset_table[p->current_frame_block] & (1U << 31)) {

            if (offset > p->audio_size - p->buffer_size)

                return AVERROR_INVALIDDATA;



            avio_read(pb, p->audio_frame + offset, p->buffer_size);

            if (offset == (p->max_audio_blks - 2) * p->buffer_size) {

                memcpy(p->temp_audio_frame, p->audio_frame, p->audio_size);

                p->got_audio = 1;

            }

        } else {

            if (offset > p->video_size - p->buffer_size)

                return AVERROR_INVALIDDATA;



            avio_read(pb, p->video_frame + offset, p->buffer_size);

        }

        p->current_frame_block++;

    }



    size = p->video_size - p->frames_offset_table[p->current_frame];

    if (size < 1)

        return AVERROR_INVALIDDATA;



    if (av_new_packet(pkt, size) < 0)

        return AVERROR(ENOMEM);



    pkt->stream_index = 0;

    pkt->duration     = 1;

    memcpy(pkt->data, p->video_frame + p->frames_offset_table[p->current_frame], size);

    if (pkt->data[0] & 0x20)

        pkt->flags   |= AV_PKT_FLAG_KEY;

    p->current_frame++;



    return pkt->size;

}

bool timer_pending(QEMUTimer *ts)

{

    QEMUTimer *t;

    for (t = ts->timer_list->active_timers; t != NULL; t = t->next) {

        if (t == ts) {

            return true;

        }

    }

    return false;

}

static int tcp_chr_new_client(CharDriverState *chr, QIOChannelSocket *sioc)

{

    TCPCharDriver *s = chr->opaque;

    if (s->ioc != NULL) {

	return -1;

    }



    s->ioc = QIO_CHANNEL(sioc);

    object_ref(OBJECT(sioc));



    if (s->do_nodelay) {

        qio_channel_set_delay(s->ioc, false);

    }

    if (s->listen_tag) {

        g_source_remove(s->listen_tag);

        s->listen_tag = 0;

    }



    if (s->do_telnetopt) {

        tcp_chr_telnet_init(chr);

    } else {

        tcp_chr_connect(chr);

    }



    return 0;

}

static void ich9_lpc_update_pic(ICH9LPCState *lpc, int gsi)

{

    int i, pic_level;



    assert(gsi < ICH9_LPC_PIC_NUM_PINS);



    /* The pic level is the logical OR of all the PCI irqs mapped to it */

    pic_level = 0;

    for (i = 0; i < ICH9_LPC_NB_PIRQS; i++) {

        int tmp_irq;

        int tmp_dis;

        ich9_lpc_pic_irq(lpc, i, &tmp_irq, &tmp_dis);

        if (!tmp_dis && tmp_irq == gsi) {

            pic_level |= pci_bus_get_irq_level(lpc->d.bus, i);

        }

    }

    if (gsi == lpc->sci_gsi) {

        pic_level |= lpc->sci_level;

    }



    qemu_set_irq(lpc->gsi[gsi], pic_level);

}

int attribute_align_arg avcodec_decode_video2(AVCodecContext *avctx, AVFrame *picture,

                                              int *got_picture_ptr,

                                              AVPacket *avpkt)

{

    int ret;



    *got_picture_ptr = 0;

    if ((avctx->coded_width || avctx->coded_height) && av_image_check_size(avctx->coded_width, avctx->coded_height, 0, avctx))

        return -1;



    avctx->pkt = avpkt;

    apply_param_change(avctx, avpkt);



    avcodec_get_frame_defaults(picture);



    if ((avctx->codec->capabilities & CODEC_CAP_DELAY) || avpkt->size || (avctx->active_thread_type & FF_THREAD_FRAME)) {

        if (HAVE_THREADS && avctx->active_thread_type & FF_THREAD_FRAME)

            ret = ff_thread_decode_frame(avctx, picture, got_picture_ptr,

                                         avpkt);

        else {

            ret = avctx->codec->decode(avctx, picture, got_picture_ptr,

                                       avpkt);

            picture->pkt_dts             = avpkt->dts;

            picture->sample_aspect_ratio = avctx->sample_aspect_ratio;

            picture->width               = avctx->width;

            picture->height              = avctx->height;

            picture->format              = avctx->pix_fmt;

        }



        emms_c(); //needed to avoid an emms_c() call before every return;



        if (*got_picture_ptr)

            avctx->frame_number++;

    } else

        ret = 0;



    /* many decoders assign whole AVFrames, thus overwriting extended_data;

     * make sure it's set correctly */

    picture->extended_data = picture->data;



    return ret;

}

static int cirrus_do_copy(CirrusVGAState *s, int dst, int src, int w, int h)

{

    int sx = 0, sy = 0;

    int dx = 0, dy = 0;

    int depth = 0;

    int notify = 0;



    /* make sure to only copy if it's a plain copy ROP */

    if (*s->cirrus_rop == cirrus_bitblt_rop_fwd_src ||

        *s->cirrus_rop == cirrus_bitblt_rop_bkwd_src) {



        int width, height;



        depth = s->vga.get_bpp(&s->vga) / 8;

        if (!depth) {

            return 0;

        }

        s->vga.get_resolution(&s->vga, &width, &height);



        /* extra x, y */

        sx = (src % ABS(s->cirrus_blt_srcpitch)) / depth;

        sy = (src / ABS(s->cirrus_blt_srcpitch));

        dx = (dst % ABS(s->cirrus_blt_dstpitch)) / depth;

        dy = (dst / ABS(s->cirrus_blt_dstpitch));



        /* normalize width */

        w /= depth;



        /* if we're doing a backward copy, we have to adjust

           our x/y to be the upper left corner (instead of the lower

           right corner) */

        if (s->cirrus_blt_dstpitch < 0) {

            sx -= (s->cirrus_blt_width / depth) - 1;

            dx -= (s->cirrus_blt_width / depth) - 1;

            sy -= s->cirrus_blt_height - 1;

            dy -= s->cirrus_blt_height - 1;

        }



        /* are we in the visible portion of memory? */

        if (sx >= 0 && sy >= 0 && dx >= 0 && dy >= 0 &&

            (sx + w) <= width && (sy + h) <= height &&

            (dx + w) <= width && (dy + h) <= height) {

            notify = 1;

        }

    }



    /* we have to flush all pending changes so that the copy

       is generated at the appropriate moment in time */

    if (notify)

        graphic_hw_update(s->vga.con);



    (*s->cirrus_rop) (s, s->vga.vram_ptr + s->cirrus_blt_dstaddr,

                      s->vga.vram_ptr + s->cirrus_blt_srcaddr,

		      s->cirrus_blt_dstpitch, s->cirrus_blt_srcpitch,

		      s->cirrus_blt_width, s->cirrus_blt_height);



    if (notify) {

        qemu_console_copy(s->vga.con,

			  sx, sy, dx, dy,

			  s->cirrus_blt_width / depth,

			  s->cirrus_blt_height);

    }



    /* we don't have to notify the display that this portion has

       changed since qemu_console_copy implies this */



    cirrus_invalidate_region(s, s->cirrus_blt_dstaddr,

				s->cirrus_blt_dstpitch, s->cirrus_blt_width,

				s->cirrus_blt_height);



    return 1;

}

static int decode_wdlt(GetByteContext *gb, uint8_t *frame, int width, int height)

{

    const uint8_t *frame_end   = frame + width * height;

    uint8_t *line_ptr;

    int count, i, v, lines, segments;



    lines = bytestream2_get_le16(gb);

    if (lines > height)

        return -1;



    while (lines--) {

        if (bytestream2_get_bytes_left(gb) < 2)

            return -1;

        segments = bytestream2_get_le16u(gb);

        while ((segments & 0xC000) == 0xC000) {

            unsigned delta = -((int16_t)segments * width);

            if (frame_end - frame <= delta)

                return -1;

            frame    += delta;

            segments = bytestream2_get_le16(gb);

        }

        if (segments & 0x8000) {

            frame[width - 1] = segments & 0xFF;

            segments = bytestream2_get_le16(gb);

        }

        line_ptr = frame;

        frame += width;

        while (segments--) {

            if (frame - line_ptr <= bytestream2_peek_byte(gb))

                return -1;

            line_ptr += bytestream2_get_byte(gb);

            count = (int8_t)bytestream2_get_byte(gb);

            if (count >= 0) {

                if (frame - line_ptr < count * 2)

                    return -1;

                if (bytestream2_get_buffer(gb, line_ptr, count * 2) != count * 2)

                    return -1;

                line_ptr += count * 2;

            } else {

                count = -count;

                if (frame - line_ptr < count * 2)

                    return -1;

                v = bytestream2_get_le16(gb);

                for (i = 0; i < count; i++)

                    bytestream_put_le16(&line_ptr, v);

            }

        }

    }



    return 0;

}

static inline abi_long do_msgrcv(int msqid, abi_long msgp,

                                 unsigned int msgsz, abi_long msgtyp,

                                 int msgflg)

{

    struct target_msgbuf *target_mb;

    char *target_mtext;

    struct msgbuf *host_mb;

    abi_long ret = 0;



    if (!lock_user_struct(VERIFY_WRITE, target_mb, msgp, 0))

        return -TARGET_EFAULT;



    host_mb = malloc(msgsz+sizeof(long));

    ret = get_errno(msgrcv(msqid, host_mb, msgsz, tswapal(msgtyp), msgflg));



    if (ret > 0) {

        abi_ulong target_mtext_addr = msgp + sizeof(abi_ulong);

        target_mtext = lock_user(VERIFY_WRITE, target_mtext_addr, ret, 0);

        if (!target_mtext) {

            ret = -TARGET_EFAULT;

            goto end;

        }

        memcpy(target_mb->mtext, host_mb->mtext, ret);

        unlock_user(target_mtext, target_mtext_addr, ret);

    }



    target_mb->mtype = tswapal(host_mb->mtype);

    free(host_mb);



end:

    if (target_mb)

        unlock_user_struct(target_mb, msgp, 1);

    return ret;

}

