                gen_helper_ldl_raw(cpu_ir[ra], addr);

                gen_helper_restore_mode();

                break;

            case 0xD:

                /* Quadword virtual access with altenate access mode */

                gen_helper_set_alt_mode();

                gen_helper_st_virt_to_phys(addr, addr);

                gen_helper_ldq_raw(cpu_ir[ra], addr);

                gen_helper_restore_mode();

                break;

            case 0xE:

                /* Longword virtual access with alternate access mode and

                 * protection checks

                 */

                gen_helper_set_alt_mode();

                gen_helper_ldl_data(cpu_ir[ra], addr);

                gen_helper_restore_mode();

                break;

            case 0xF:

                /* Quadword virtual access with alternate access mode and

                 * protection checks

                 */

                gen_helper_set_alt_mode();

                gen_helper_ldq_data(cpu_ir[ra], addr);

                gen_helper_restore_mode();

                break;

            }

            tcg_temp_free(addr);

        }

        break;

#endif

    case 0x1C:

        switch (fn7) {

        case 0x00:

            /* SEXTB */

            if (!(ctx->amask & AMASK_BWX))

                goto invalid_opc;

            if (likely(rc != 31)) {

                if (islit)

                    tcg_gen_movi_i64(cpu_ir[rc], (int64_t)((int8_t)lit));

                else

                    tcg_gen_ext8s_i64(cpu_ir[rc], cpu_ir[rb]);

            }

            break;

        case 0x01:

            /* SEXTW */

            if (!(ctx->amask & AMASK_BWX))

                goto invalid_opc;

            if (likely(rc != 31)) {

                if (islit)

                    tcg_gen_movi_i64(cpu_ir[rc], (int64_t)((int16_t)lit));

                else

                    tcg_gen_ext16s_i64(cpu_ir[rc], cpu_ir[rb]);

            }

            break;

        case 0x30:

            /* CTPOP */

            if (!(ctx->amask & AMASK_CIX))

                goto invalid_opc;

            if (likely(rc != 31)) {

                if (islit)

                    tcg_gen_movi_i64(cpu_ir[rc], ctpop64(lit));

                else

                    gen_helper_ctpop(cpu_ir[rc], cpu_ir[rb]);

            }

            break;

        case 0x31:

            /* PERR */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x32:

            /* CTLZ */

            if (!(ctx->amask & AMASK_CIX))

                goto invalid_opc;

            if (likely(rc != 31)) {

                if (islit)

                    tcg_gen_movi_i64(cpu_ir[rc], clz64(lit));

                else

                    gen_helper_ctlz(cpu_ir[rc], cpu_ir[rb]);

            }

            break;

        case 0x33:

            /* CTTZ */

            if (!(ctx->amask & AMASK_CIX))

                goto invalid_opc;

            if (likely(rc != 31)) {

                if (islit)

                    tcg_gen_movi_i64(cpu_ir[rc], ctz64(lit));

                else

                    gen_helper_cttz(cpu_ir[rc], cpu_ir[rb]);

            }

            break;

        case 0x34:

            /* UNPKBW */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x35:

            /* UNPKWL */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x36:

            /* PKWB */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x37:

            /* PKLB */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x38:

            /* MINSB8 */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x39:

            /* MINSW4 */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x3A:

            /* MINUB8 */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x3B:

            /* MINUW4 */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x3C:

            /* MAXUB8 */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x3D:

            /* MAXUW4 */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x3E:

            /* MAXSB8 */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x3F:

            /* MAXSW4 */

            if (!(ctx->amask & AMASK_MVI))

                goto invalid_opc;

            /* XXX: TODO */

            goto invalid_opc;

            break;

        case 0x70:

            /* FTOIT */

            if (!(ctx->amask & AMASK_FIX))

                goto invalid_opc;

            if (likely(rc != 31)) {

                if (ra != 31)

                    tcg_gen_mov_i64(cpu_ir[rc], cpu_fir[ra]);

                else

                    tcg_gen_movi_i64(cpu_ir[rc], 0);

            }

            break;

        case 0x78:

            /* FTOIS */

            if (!(ctx->amask & AMASK_FIX))

                goto invalid_opc;

            if (rc != 31) {

                TCGv_i32 tmp1 = tcg_temp_new_i32();

                if (ra != 31)

                    gen_helper_s_to_memory(tmp1, cpu_fir[ra]);

                else {

                    TCGv tmp2 = tcg_const_i64(0);

                    gen_helper_s_to_memory(tmp1, tmp2);

                    tcg_temp_free(tmp2);

                }

                tcg_gen_ext_i32_i64(cpu_ir[rc], tmp1);

                tcg_temp_free_i32(tmp1);

            }

            break;

        default:

            goto invalid_opc;

        }

        break;

    case 0x1D:

        /* HW_MTPR (PALcode) */

#if defined (CONFIG_USER_ONLY)

        goto invalid_opc;

#else

        if (!ctx->pal_mode)

            goto invalid_opc;

        else {

            TCGv tmp1 = tcg_const_i32(insn & 0xFF);

            if (ra != 31)

                gen_helper_mtpr(tmp1, cpu_ir[ra]);

            else {

                TCGv tmp2 = tcg_const_i64(0);

                gen_helper_mtpr(tmp1, tmp2);

                tcg_temp_free(tmp2);

            }

            tcg_temp_free(tmp1);

            ret = 2;

        }

        break;

#endif

    case 0x1E:

        /* HW_REI (PALcode) */

#if defined (CONFIG_USER_ONLY)

        goto invalid_opc;

#else

        if (!ctx->pal_mode)

            goto invalid_opc;

        if (rb == 31) {

            /* "Old" alpha */

            gen_helper_hw_rei();

        } else {

            TCGv tmp;



            if (ra != 31) {

                tmp = tcg_temp_new();

                tcg_gen_addi_i64(tmp, cpu_ir[rb], (((int64_t)insn << 51) >> 51));

            } else

                tmp = tcg_const_i64(((int64_t)insn << 51) >> 51);

            gen_helper_hw_ret(tmp);

            tcg_temp_free(tmp);

        }

        ret = 2;

        break;

#endif

    case 0x1F:

        /* HW_ST (PALcode) */

#if defined (CONFIG_USER_ONLY)

        goto invalid_opc;

#else

        if (!ctx->pal_mode)

            goto invalid_opc;

        else {

            TCGv addr, val;

            addr = tcg_temp_new();

            if (rb != 31)

                tcg_gen_addi_i64(addr, cpu_ir[rb], disp12);

            else

                tcg_gen_movi_i64(addr, disp12);

            if (ra != 31)

                val = cpu_ir[ra];

            else {

                val = tcg_temp_new();

                tcg_gen_movi_i64(val, 0);

            }

            switch ((insn >> 12) & 0xF) {

            case 0x0:

                /* Longword physical access */

                gen_helper_stl_raw(val, addr);

                break;

            case 0x1:

                /* Quadword physical access */

                gen_helper_stq_raw(val, addr);

                break;

            case 0x2:

                /* Longword physical access with lock */

                gen_helper_stl_c_raw(val, val, addr);

                break;

            case 0x3:

                /* Quadword physical access with lock */

                gen_helper_stq_c_raw(val, val, addr);

                break;

            case 0x4:

                /* Longword virtual access */

                gen_helper_st_virt_to_phys(addr, addr);

                gen_helper_stl_raw(val, addr);

                break;

            case 0x5:

                /* Quadword virtual access */

                gen_helper_st_virt_to_phys(addr, addr);

                gen_helper_stq_raw(val, addr);

                break;

            case 0x6:

                /* Invalid */

                goto invalid_opc;

            case 0x7:

                /* Invalid */

                goto invalid_opc;

            case 0x8:

                /* Invalid */

                goto invalid_opc;

            case 0x9:

                /* Invalid */

                goto invalid_opc;

            case 0xA:

                /* Invalid */

                goto invalid_opc;

            case 0xB:

                /* Invalid */

                goto invalid_opc;

            case 0xC:

                /* Longword virtual access with alternate access mode */

                gen_helper_set_alt_mode();

                gen_helper_st_virt_to_phys(addr, addr);

                gen_helper_stl_raw(val, addr);

                gen_helper_restore_mode();

                break;

            case 0xD:

                /* Quadword virtual access with alternate access mode */

                gen_helper_set_alt_mode();

                gen_helper_st_virt_to_phys(addr, addr);

                gen_helper_stl_raw(val, addr);

                gen_helper_restore_mode();

                break;

            case 0xE:

                /* Invalid */

                goto invalid_opc;

            case 0xF:

                /* Invalid */

                goto invalid_opc;

            }

            if (ra == 31)

                tcg_temp_free(val);

            tcg_temp_free(addr);

        }

        break;

#endif

    case 0x20:

        /* LDF */

        gen_load_mem(ctx, &gen_qemu_ldf, ra, rb, disp16, 1, 0);

        break;

    case 0x21:

        /* LDG */

        gen_load_mem(ctx, &gen_qemu_ldg, ra, rb, disp16, 1, 0);

        break;

    case 0x22:

        /* LDS */

        gen_load_mem(ctx, &gen_qemu_lds, ra, rb, disp16, 1, 0);

        break;

    case 0x23:

        /* LDT */

        gen_load_mem(ctx, &tcg_gen_qemu_ld64, ra, rb, disp16, 1, 0);

        break;

    case 0x24:

        /* STF */

        gen_store_mem(ctx, &gen_qemu_stf, ra, rb, disp16, 1, 0, 0);

        break;

    case 0x25:

        /* STG */

        gen_store_mem(ctx, &gen_qemu_stg, ra, rb, disp16, 1, 0, 0);

        break;

    case 0x26:

        /* STS */

        gen_store_mem(ctx, &gen_qemu_sts, ra, rb, disp16, 1, 0, 0);

        break;

    case 0x27:

        /* STT */

        gen_store_mem(ctx, &tcg_gen_qemu_st64, ra, rb, disp16, 1, 0, 0);

        break;

    case 0x28:

        /* LDL */

        gen_load_mem(ctx, &tcg_gen_qemu_ld32s, ra, rb, disp16, 0, 0);

        break;

    case 0x29:

        /* LDQ */

        gen_load_mem(ctx, &tcg_gen_qemu_ld64, ra, rb, disp16, 0, 0);

        break;

    case 0x2A:

        /* LDL_L */

        gen_load_mem(ctx, &gen_qemu_ldl_l, ra, rb, disp16, 0, 0);

        break;

    case 0x2B:

        /* LDQ_L */

        gen_load_mem(ctx, &gen_qemu_ldq_l, ra, rb, disp16, 0, 0);

        break;

    case 0x2C:

        /* STL */

        gen_store_mem(ctx, &tcg_gen_qemu_st32, ra, rb, disp16, 0, 0, 0);

        break;

    case 0x2D:

        /* STQ */

        gen_store_mem(ctx, &tcg_gen_qemu_st64, ra, rb, disp16, 0, 0, 0);

        break;

    case 0x2E:

        /* STL_C */

        gen_store_mem(ctx, &gen_qemu_stl_c, ra, rb, disp16, 0, 0, 1);

        break;

    case 0x2F:

        /* STQ_C */

        gen_store_mem(ctx, &gen_qemu_stq_c, ra, rb, disp16, 0, 0, 1);

        break;

    case 0x30:

        /* BR */

        if (ra != 31)

            tcg_gen_movi_i64(cpu_ir[ra], ctx->pc);

        tcg_gen_movi_i64(cpu_pc, ctx->pc + (int64_t)(disp21 << 2));

        ret = 1;

        break;

    case 0x31: /* FBEQ */

    case 0x32: /* FBLT */

    case 0x33: /* FBLE */

        gen_fbcond(ctx, opc, ra, disp16);

        ret = 1;

        break;

    case 0x34:

        /* BSR */

        if (ra != 31)

            tcg_gen_movi_i64(cpu_ir[ra], ctx->pc);

        tcg_gen_movi_i64(cpu_pc, ctx->pc + (int64_t)(disp21 << 2));

        ret = 1;

        break;

    case 0x35: /* FBNE */

    case 0x36: /* FBGE */

    case 0x37: /* FBGT */

        gen_fbcond(ctx, opc, ra, disp16);

        ret = 1;

        break;

    case 0x38:

        /* BLBC */

        gen_bcond(ctx, TCG_COND_EQ, ra, disp21, 1);

        ret = 1;

        break;

    case 0x39:

        /* BEQ */

        gen_bcond(ctx, TCG_COND_EQ, ra, disp21, 0);

        ret = 1;

        break;

    case 0x3A:

        /* BLT */

        gen_bcond(ctx, TCG_COND_LT, ra, disp21, 0);

        ret = 1;

        break;

    case 0x3B:

        /* BLE */

        gen_bcond(ctx, TCG_COND_LE, ra, disp21, 0);

        ret = 1;

        break;

    case 0x3C:

        /* BLBS */

        gen_bcond(ctx, TCG_COND_NE, ra, disp21, 1);

        ret = 1;

        break;

    case 0x3D:

        /* BNE */

        gen_bcond(ctx, TCG_COND_NE, ra, disp21, 0);

        ret = 1;

        break;

    case 0x3E:

        /* BGE */

        gen_bcond(ctx, TCG_COND_GE, ra, disp21, 0);

        ret = 1;

        break;

    case 0x3F:

        /* BGT */

        gen_bcond(ctx, TCG_COND_GT, ra, disp21, 0);

        ret = 1;

        break;

    invalid_opc:

        gen_invalid(ctx);

        ret = 3;

        break;

    }



    return ret;

}

static int decode_chunks(AVCodecContext *avctx,

                             AVFrame *picture, int *data_size,

                             const uint8_t *buf, int buf_size)

{

    Mpeg1Context *s = avctx->priv_data;

    MpegEncContext *s2 = &s->mpeg_enc_ctx;

    const uint8_t *buf_ptr = buf;

    const uint8_t *buf_end = buf + buf_size;

    int ret, input_size;

    int last_code= 0;



    for(;;) {

        /* find next start code */

        uint32_t start_code = -1;

        buf_ptr = ff_find_start_code(buf_ptr,buf_end, &start_code);

        if (start_code > 0x1ff){

            if(s2->pict_type != AV_PICTURE_TYPE_B || avctx->skip_frame <= AVDISCARD_DEFAULT){

                if(avctx->thread_count > 1){

                    int i;



                    avctx->execute(avctx, slice_decode_thread,  &s2->thread_context[0], NULL, s->slice_count, sizeof(void*));

                    for(i=0; i<s->slice_count; i++)

                        s2->error_count += s2->thread_context[i]->error_count;

                }



                if (CONFIG_MPEG_VDPAU_DECODER && avctx->codec->capabilities&CODEC_CAP_HWACCEL_VDPAU)

                    ff_vdpau_mpeg_picture_complete(s2, buf, buf_size, s->slice_count);



                if (slice_end(avctx, picture)) {

                    if(s2->last_picture_ptr || s2->low_delay) //FIXME merge with the stuff in mpeg_decode_slice

                        *data_size = sizeof(AVPicture);

                }

            }

            s2->pict_type= 0;

            return FFMAX(0, buf_ptr - buf - s2->parse_context.last_index);

        }



        input_size = buf_end - buf_ptr;



        if(avctx->debug & FF_DEBUG_STARTCODE){

            av_log(avctx, AV_LOG_DEBUG, "%3X at %td left %d\n", start_code, buf_ptr-buf, input_size);

        }



        /* prepare data for next start code */

        switch(start_code) {

        case SEQ_START_CODE:

            if(last_code == 0){

            mpeg1_decode_sequence(avctx, buf_ptr,

                                    input_size);

                s->sync=1;

            }else{

                av_log(avctx, AV_LOG_ERROR, "ignoring SEQ_START_CODE after %X\n", last_code);

            }

            break;



        case PICTURE_START_CODE:

            if (HAVE_THREADS && (avctx->active_thread_type&FF_THREAD_SLICE) && s->slice_count) {

                int i;



                avctx->execute(avctx, slice_decode_thread,

                               s2->thread_context, NULL,

                               s->slice_count, sizeof(void*));

                for (i = 0; i < s->slice_count; i++)

                    s2->error_count += s2->thread_context[i]->error_count;

                s->slice_count = 0;

            }

            if(last_code == 0 || last_code == SLICE_MIN_START_CODE){

            if(mpeg_decode_postinit(avctx) < 0){

                av_log(avctx, AV_LOG_ERROR, "mpeg_decode_postinit() failure\n");

                return -1;

            }



            /* we have a complete image: we try to decompress it */

            if(mpeg1_decode_picture(avctx,

                                    buf_ptr, input_size) < 0)

                s2->pict_type=0;

                s2->first_slice = 1;

            last_code= PICTURE_START_CODE;

            }else{

                av_log(avctx, AV_LOG_ERROR, "ignoring pic after %X\n", last_code);

            }

            break;

        case EXT_START_CODE:

            init_get_bits(&s2->gb, buf_ptr, input_size*8);



            switch(get_bits(&s2->gb, 4)) {

            case 0x1:

                if(last_code == 0){

                mpeg_decode_sequence_extension(s);

                }else{

                    av_log(avctx, AV_LOG_ERROR, "ignoring seq ext after %X\n", last_code);

                }

                break;

            case 0x2:

                mpeg_decode_sequence_display_extension(s);

                break;

            case 0x3:

                mpeg_decode_quant_matrix_extension(s2);

                break;

            case 0x7:

                mpeg_decode_picture_display_extension(s);

                break;

            case 0x8:

                if(last_code == PICTURE_START_CODE){

                mpeg_decode_picture_coding_extension(s);

                }else{

                    av_log(avctx, AV_LOG_ERROR, "ignoring pic cod ext after %X\n", last_code);

                }

                break;

            }

            break;

        case USER_START_CODE:

            mpeg_decode_user_data(avctx,

                                    buf_ptr, input_size);

            break;

        case GOP_START_CODE:

            if(last_code == 0){

            s2->first_field=0;

            mpeg_decode_gop(avctx,

                                    buf_ptr, input_size);

                s->sync=1;

            }else{

                av_log(avctx, AV_LOG_ERROR, "ignoring GOP_START_CODE after %X\n", last_code);

            }

            break;

        default:

            if (start_code >= SLICE_MIN_START_CODE &&

                start_code <= SLICE_MAX_START_CODE && last_code!=0) {

                const int field_pic= s2->picture_structure != PICT_FRAME;

                int mb_y= (start_code - SLICE_MIN_START_CODE) << field_pic;

                last_code= SLICE_MIN_START_CODE;



                if(s2->picture_structure == PICT_BOTTOM_FIELD)

                    mb_y++;



                if (mb_y >= s2->mb_height){

                    av_log(s2->avctx, AV_LOG_ERROR, "slice below image (%d >= %d)\n", mb_y, s2->mb_height);

                    return -1;

                }



                if(s2->last_picture_ptr==NULL){

                /* Skip B-frames if we do not have reference frames and gop is not closed */

                    if(s2->pict_type==AV_PICTURE_TYPE_B){

                        if(!s2->closed_gop)

                            break;

                    }

                }

                if(s2->pict_type==AV_PICTURE_TYPE_I)

                    s->sync=1;

                if(s2->next_picture_ptr==NULL){

                /* Skip P-frames if we do not have a reference frame or we have an invalid header. */

                    if(s2->pict_type==AV_PICTURE_TYPE_P && !s->sync) break;

                }

                if(  (avctx->skip_frame >= AVDISCARD_NONREF && s2->pict_type==AV_PICTURE_TYPE_B)

                    ||(avctx->skip_frame >= AVDISCARD_NONKEY && s2->pict_type!=AV_PICTURE_TYPE_I)

                    || avctx->skip_frame >= AVDISCARD_ALL)

                    break;



                if (!s->mpeg_enc_ctx_allocated) break;



                if(s2->codec_id == CODEC_ID_MPEG2VIDEO){

                    if(mb_y < avctx->skip_top || mb_y >= s2->mb_height - avctx->skip_bottom)

                        break;

                }



                if(!s2->pict_type){

                    av_log(avctx, AV_LOG_ERROR, "Missing picture start code\n");

                    break;

                }



                if(s2->first_slice){

                    s2->first_slice=0;

                    if(mpeg_field_start(s2, buf, buf_size) < 0)

                        return -1;

                }

                if(!s2->current_picture_ptr){

                    av_log(avctx, AV_LOG_ERROR, "current_picture not initialized\n");

                    return -1;

                }



                if (avctx->codec->capabilities&CODEC_CAP_HWACCEL_VDPAU) {

                    s->slice_count++;

                    break;

                }



                if(avctx->thread_count > 1){

                    int threshold= (s2->mb_height*s->slice_count + avctx->thread_count/2) / avctx->thread_count;

                    if(threshold <= mb_y){

                        MpegEncContext *thread_context= s2->thread_context[s->slice_count];



                        thread_context->start_mb_y= mb_y;

                        thread_context->end_mb_y  = s2->mb_height;

                        if(s->slice_count){

                            s2->thread_context[s->slice_count-1]->end_mb_y= mb_y;

                            ff_update_duplicate_context(thread_context, s2);

                        }

                        init_get_bits(&thread_context->gb, buf_ptr, input_size*8);

                        s->slice_count++;

                    }

                    buf_ptr += 2; //FIXME add minimum number of bytes per slice

                }else{

                    ret = mpeg_decode_slice(s, mb_y, &buf_ptr, input_size);

                    emms_c();



                    if(ret < 0){

                        if(s2->resync_mb_x>=0 && s2->resync_mb_y>=0)

                            ff_er_add_slice(s2, s2->resync_mb_x, s2->resync_mb_y, s2->mb_x, s2->mb_y, AC_ERROR|DC_ERROR|MV_ERROR);

                    }else{

                        ff_er_add_slice(s2, s2->resync_mb_x, s2->resync_mb_y, s2->mb_x-1, s2->mb_y, AC_END|DC_END|MV_END);

                    }

                }

            }

            break;

        }

    }

}

static void rtas_ibm_query_interrupt_source_number(PowerPCCPU *cpu,

                                                   sPAPREnvironment *spapr,

                                                   uint32_t token,

                                                   uint32_t nargs,

                                                   target_ulong args,

                                                   uint32_t nret,

                                                   target_ulong rets)

{

    uint32_t config_addr = rtas_ld(args, 0);

    uint64_t buid = ((uint64_t)rtas_ld(args, 1) << 32) | rtas_ld(args, 2);

    unsigned int intr_src_num = -1, ioa_intr_num = rtas_ld(args, 3);

    int ndev;

    sPAPRPHBState *phb = NULL;



    /* Fins sPAPRPHBState */

    phb = find_phb(spapr, buid);

    if (!phb) {

        rtas_st(rets, 0, RTAS_OUT_PARAM_ERROR);

        return;

    }



    /* Find device descriptor and start IRQ */

    ndev = spapr_msicfg_find(phb, config_addr, false);

    if (ndev < 0) {

        trace_spapr_pci_msi("MSI has not been enabled", -1, config_addr);

        rtas_st(rets, 0, RTAS_OUT_HW_ERROR);

        return;

    }



    intr_src_num = phb->msi_table[ndev].irq + ioa_intr_num;

    trace_spapr_pci_rtas_ibm_query_interrupt_source_number(ioa_intr_num,

                                                           intr_src_num);



    rtas_st(rets, 0, RTAS_OUT_SUCCESS);

    rtas_st(rets, 1, intr_src_num);

    rtas_st(rets, 2, 1);/* 0 == level; 1 == edge */

}

