static void process_client(AVIOContext *client, const char *in_uri)

{

    AVIOContext *input = NULL;

    uint8_t buf[1024];

    int ret, n, reply_code;

    uint8_t *resource = NULL;

    while ((ret = avio_handshake(client)) > 0) {

        av_opt_get(client, "resource", AV_OPT_SEARCH_CHILDREN, &resource);

        // check for strlen(resource) is necessary, because av_opt_get()

        // may return empty string.

        if (resource && strlen(resource))

            break;


    }

    if (ret < 0)

        goto end;

    av_log(client, AV_LOG_TRACE, "resource=%p\n", resource);

    if (resource && resource[0] == '/' && !strcmp((resource + 1), in_uri)) {

        reply_code = 200;

    } else {

        reply_code = AVERROR_HTTP_NOT_FOUND;

    }

    if ((ret = av_opt_set_int(client, "reply_code", reply_code, AV_OPT_SEARCH_CHILDREN)) < 0) {

        av_log(client, AV_LOG_ERROR, "Failed to set reply_code: %s.\n", av_err2str(ret));

        goto end;

    }

    av_log(client, AV_LOG_TRACE, "Set reply code to %d\n", reply_code);



    while ((ret = avio_handshake(client)) > 0);



    if (ret < 0)

        goto end;



    fprintf(stderr, "Handshake performed.\n");

    if (reply_code != 200)

        goto end;

    fprintf(stderr, "Opening input file.\n");

    if ((ret = avio_open2(&input, in_uri, AVIO_FLAG_READ, NULL, NULL)) < 0) {

        av_log(input, AV_LOG_ERROR, "Failed to open input: %s: %s.\n", in_uri,

               av_err2str(ret));

        goto end;

    }

    for(;;) {

        n = avio_read(input, buf, sizeof(buf));

        if (n < 0) {

            if (n == AVERROR_EOF)

                break;

            av_log(input, AV_LOG_ERROR, "Error reading from input: %s.\n",

                   av_err2str(n));

            break;

        }

        avio_write(client, buf, n);

        avio_flush(client);

    }

end:

    fprintf(stderr, "Flushing client\n");

    avio_flush(client);

    fprintf(stderr, "Closing client\n");

    avio_close(client);

    fprintf(stderr, "Closing input\n");

    avio_close(input);


}

static int qxl_post_load(void *opaque, int version)

{

    PCIQXLDevice* d = opaque;

    uint8_t *ram_start = d->vga.vram_ptr;

    QXLCommandExt *cmds;

    int in, out, newmode;



    assert(d->last_release_offset < d->vga.vram_size);

    if (d->last_release_offset == 0) {

        d->last_release = NULL;

    } else {

        d->last_release = (QXLReleaseInfo *)(ram_start + d->last_release_offset);

    }



    d->modes = (QXLModes*)((uint8_t*)d->rom + d->rom->modes_offset);



    trace_qxl_post_load(d->id, qxl_mode_to_string(d->mode));

    newmode = d->mode;

    d->mode = QXL_MODE_UNDEFINED;



    switch (newmode) {

    case QXL_MODE_UNDEFINED:

        qxl_create_memslots(d);

        break;

    case QXL_MODE_VGA:

        qxl_create_memslots(d);

        qxl_enter_vga_mode(d);

        break;

    case QXL_MODE_NATIVE:

        qxl_create_memslots(d);

        qxl_create_guest_primary(d, 1, QXL_SYNC);



        /* replay surface-create and cursor-set commands */

        cmds = g_malloc0(sizeof(QXLCommandExt) * (d->ssd.num_surfaces + 1));

        for (in = 0, out = 0; in < d->ssd.num_surfaces; in++) {

            if (d->guest_surfaces.cmds[in] == 0) {

                continue;

            }

            cmds[out].cmd.data = d->guest_surfaces.cmds[in];

            cmds[out].cmd.type = QXL_CMD_SURFACE;

            cmds[out].group_id = MEMSLOT_GROUP_GUEST;

            out++;

        }

        if (d->guest_cursor) {

            cmds[out].cmd.data = d->guest_cursor;

            cmds[out].cmd.type = QXL_CMD_CURSOR;

            cmds[out].group_id = MEMSLOT_GROUP_GUEST;

            out++;

        }

        qxl_spice_loadvm_commands(d, cmds, out);

        g_free(cmds);

        if (d->guest_monitors_config) {

            qxl_spice_monitors_config_async(d, 1);

        }

        break;

    case QXL_MODE_COMPAT:

        /* note: no need to call qxl_create_memslots, qxl_set_mode

         * creates the mem slot. */

        qxl_set_mode(d, d->shadow_rom.mode, 1);

        break;

    }

    return 0;

}

static int sdp_parse_rtpmap(AVFormatContext *s,

                            AVStream *st, RTSPStream *rtsp_st,

                            int payload_type, const char *p)

{

    AVCodecContext *codec = st->codec;

    char buf[256];

    int i;

    AVCodec *c;

    const char *c_name;



    /* See if we can handle this kind of payload.

     * The space should normally not be there but some Real streams or

     * particular servers ("RealServer Version 6.1.3.970", see issue 1658)

     * have a trailing space. */

    get_word_sep(buf, sizeof(buf), "/ ", &p);

    if (payload_type < RTP_PT_PRIVATE) {

        /* We are in a standard case

         * (from http://www.iana.org/assignments/rtp-parameters). */

        codec->codec_id = ff_rtp_codec_id(buf, codec->codec_type);

    }



    if (codec->codec_id == AV_CODEC_ID_NONE) {

        RTPDynamicProtocolHandler *handler =

            ff_rtp_handler_find_by_name(buf, codec->codec_type);

        init_rtp_handler(handler, rtsp_st, st);

        /* If no dynamic handler was found, check with the list of standard

         * allocated types, if such a stream for some reason happens to

         * use a private payload type. This isn't handled in rtpdec.c, since

         * the format name from the rtpmap line never is passed into rtpdec. */

        if (!rtsp_st->dynamic_handler)

            codec->codec_id = ff_rtp_codec_id(buf, codec->codec_type);

    }



    c = avcodec_find_decoder(codec->codec_id);

    if (c && c->name)

        c_name = c->name;

    else

        c_name = "(null)";



    get_word_sep(buf, sizeof(buf), "/", &p);

    i = atoi(buf);

    switch (codec->codec_type) {

    case AVMEDIA_TYPE_AUDIO:

        av_log(s, AV_LOG_DEBUG, "audio codec set to: %s\n", c_name);

        codec->sample_rate = RTSP_DEFAULT_AUDIO_SAMPLERATE;

        codec->channels = RTSP_DEFAULT_NB_AUDIO_CHANNELS;

        if (i > 0) {

            codec->sample_rate = i;

            avpriv_set_pts_info(st, 32, 1, codec->sample_rate);

            get_word_sep(buf, sizeof(buf), "/", &p);

            i = atoi(buf);

            if (i > 0)

                codec->channels = i;

        }

        av_log(s, AV_LOG_DEBUG, "audio samplerate set to: %i\n",

               codec->sample_rate);

        av_log(s, AV_LOG_DEBUG, "audio channels set to: %i\n",

               codec->channels);

        break;

    case AVMEDIA_TYPE_VIDEO:

        av_log(s, AV_LOG_DEBUG, "video codec set to: %s\n", c_name);

        if (i > 0)

            avpriv_set_pts_info(st, 32, 1, i);

        break;

    default:

        break;

    }

    if (rtsp_st->dynamic_handler && rtsp_st->dynamic_handler->init)

        rtsp_st->dynamic_handler->init(s, st->index,

                                       rtsp_st->dynamic_protocol_context);

    return 0;

}

void framebuffer_update_display(

    DisplayState *ds,

    MemoryRegion *address_space,

    target_phys_addr_t base,

    int cols, /* Width in pixels.  */

    int rows, /* Height in pixels.  */

    int src_width, /* Length of source line, in bytes.  */

    int dest_row_pitch, /* Bytes between adjacent horizontal output pixels.  */

    int dest_col_pitch, /* Bytes between adjacent vertical output pixels.  */

    int invalidate, /* nonzero to redraw the whole image.  */

    drawfn fn,

    void *opaque,

    int *first_row, /* Input and output.  */

    int *last_row /* Output only */)

{

    target_phys_addr_t src_len;

    uint8_t *dest;

    uint8_t *src;

    uint8_t *src_base;

    int first, last = 0;

    int dirty;

    int i;

    ram_addr_t addr;

    MemoryRegionSection mem_section;

    MemoryRegion *mem;



    i = *first_row;

    *first_row = -1;

    src_len = src_width * rows;



    mem_section = memory_region_find(address_space, base, src_len);

    if (mem_section.size != src_len || !memory_region_is_ram(mem_section.mr)) {

        return;

    }

    mem = mem_section.mr;

    assert(mem);

    assert(mem_section.offset_within_address_space == base);



    memory_region_sync_dirty_bitmap(mem);

    src_base = cpu_physical_memory_map(base, &src_len, 0);

    /* If we can't map the framebuffer then bail.  We could try harder,

       but it's not really worth it as dirty flag tracking will probably

       already have failed above.  */

    if (!src_base)

        return;

    if (src_len != src_width * rows) {

        cpu_physical_memory_unmap(src_base, src_len, 0, 0);

        return;

    }

    src = src_base;

    dest = ds_get_data(ds);

    if (dest_col_pitch < 0)

        dest -= dest_col_pitch * (cols - 1);

    if (dest_row_pitch < 0) {

        dest -= dest_row_pitch * (rows - 1);

    }

    first = -1;

    addr = mem_section.offset_within_region;



    addr += i * src_width;

    src += i * src_width;

    dest += i * dest_row_pitch;



    for (; i < rows; i++) {

        dirty = memory_region_get_dirty(mem, addr, src_width,

                                             DIRTY_MEMORY_VGA);

        if (dirty || invalidate) {

            fn(opaque, dest, src, cols, dest_col_pitch);

            if (first == -1)

                first = i;

            last = i;

        }

        addr += src_width;

        src += src_width;

        dest += dest_row_pitch;

    }

    cpu_physical_memory_unmap(src_base, src_len, 0, 0);

    if (first < 0) {

        return;

    }

    memory_region_reset_dirty(mem, mem_section.offset_within_region, src_len,

                              DIRTY_MEMORY_VGA);

    *first_row = first;

    *last_row = last;

}

