static void RENAME(extract_odd2avg)(const uint8_t *src0, const uint8_t *src1, uint8_t *dst0, uint8_t *dst1, x86_reg count)

{

    dst0 +=   count;

    dst1 +=   count;

    src0 += 4*count;

    src1 += 4*count;

    count= - count;

#ifdef PAVGB

    if(count <= -8) {

        count += 7;

        __asm__ volatile(

            "pcmpeqw        %%mm7, %%mm7        \n\t"

            "psrlw             $8, %%mm7        \n\t"

            "1:                                \n\t"

            "movq  -28(%1, %0, 4), %%mm0        \n\t"

            "movq  -20(%1, %0, 4), %%mm1        \n\t"

            "movq  -12(%1, %0, 4), %%mm2        \n\t"

            "movq   -4(%1, %0, 4), %%mm3        \n\t"

            PAVGB" -28(%2, %0, 4), %%mm0        \n\t"

            PAVGB" -20(%2, %0, 4), %%mm1        \n\t"

            PAVGB" -12(%2, %0, 4), %%mm2        \n\t"

            PAVGB" - 4(%2, %0, 4), %%mm3        \n\t"

            "psrlw             $8, %%mm0        \n\t"

            "psrlw             $8, %%mm1        \n\t"

            "psrlw             $8, %%mm2        \n\t"

            "psrlw             $8, %%mm3        \n\t"

            "packuswb       %%mm1, %%mm0        \n\t"

            "packuswb       %%mm3, %%mm2        \n\t"

            "movq           %%mm0, %%mm1        \n\t"

            "movq           %%mm2, %%mm3        \n\t"

            "psrlw             $8, %%mm0        \n\t"

            "psrlw             $8, %%mm2        \n\t"

            "pand           %%mm7, %%mm1        \n\t"

            "pand           %%mm7, %%mm3        \n\t"

            "packuswb       %%mm2, %%mm0        \n\t"

            "packuswb       %%mm3, %%mm1        \n\t"

            MOVNTQ"         %%mm0,- 7(%4, %0)   \n\t"

            MOVNTQ"         %%mm1,- 7(%3, %0)   \n\t"

            "add               $8, %0           \n\t"

            " js 1b                            \n\t"

            : "+r"(count)

            : "r"(src0), "r"(src1), "r"(dst0), "r"(dst1)

        );

        count -= 7;

    }

#endif

    src0++;

    src1++;

    while(count<0) {

        dst0[count]= (src0[4*count+0]+src1[4*count+0])>>1;

        dst1[count]= (src0[4*count+2]+src1[4*count+2])>>1;

        count++;

    }

}

static void do_sendkey(const char *string)

{

    uint8_t keycodes[16];

    int nb_keycodes = 0;

    char keyname_buf[16];

    char *separator;

    int keyname_len, keycode, i;



    while (1) {

        separator = strchr(string, '-');

        keyname_len = separator ? separator - string : strlen(string);

        if (keyname_len > 0) {

            pstrcpy(keyname_buf, sizeof(keyname_buf), string);

            if (keyname_len > sizeof(keyname_buf) - 1) {

                term_printf("invalid key: '%s...'\n", keyname_buf);

                return;

            }

            if (nb_keycodes == sizeof(keycodes)) {

                term_printf("too many keys\n");

                return;

            }

            keyname_buf[keyname_len] = 0;

            keycode = get_keycode(keyname_buf);

            if (keycode < 0) {

                term_printf("unknown key: '%s'\n", keyname_buf);

                return;

            }

            keycodes[nb_keycodes++] = keycode;

        }

        if (!separator)

            break;

        string = separator + 1;

    }

    /* key down events */

    for(i = 0; i < nb_keycodes; i++) {

        keycode = keycodes[i];

        if (keycode & 0x80)

            kbd_put_keycode(0xe0);

        kbd_put_keycode(keycode & 0x7f);

    }

    /* key up events */

    for(i = nb_keycodes - 1; i >= 0; i--) {

        keycode = keycodes[i];

        if (keycode & 0x80)

            kbd_put_keycode(0xe0);

        kbd_put_keycode(keycode | 0x80);

    }

}

static int img_convert(int argc, char **argv)

{

    int c, ret = 0, n, n1, bs_n, bs_i, compress, cluster_size, cluster_sectors;

    int progress = 0, flags;

    const char *fmt, *out_fmt, *cache, *out_baseimg, *out_filename;

    BlockDriver *drv, *proto_drv;

    BlockDriverState **bs = NULL, *out_bs = NULL;

    int64_t total_sectors, nb_sectors, sector_num, bs_offset;

    uint64_t bs_sectors;

    uint8_t * buf = NULL;

    const uint8_t *buf1;

    BlockDriverInfo bdi;

    QEMUOptionParameter *param = NULL, *create_options = NULL;

    QEMUOptionParameter *out_baseimg_param;

    char *options = NULL;

    const char *snapshot_name = NULL;

    float local_progress;

    int min_sparse = 8; /* Need at least 4k of zeros for sparse detection */



    fmt = NULL;

    out_fmt = "raw";

    cache = "unsafe";

    out_baseimg = NULL;

    compress = 0;

    for(;;) {

        c = getopt(argc, argv, "f:O:B:s:hce6o:pS:t:");

        if (c == -1) {

            break;

        }

        switch(c) {

        case '?':

        case 'h':

            help();

            break;

        case 'f':

            fmt = optarg;

            break;

        case 'O':

            out_fmt = optarg;

            break;

        case 'B':

            out_baseimg = optarg;

            break;

        case 'c':

            compress = 1;

            break;

        case 'e':

            error_report("option -e is deprecated, please use \'-o "

                  "encryption\' instead!");

            return 1;

        case '6':

            error_report("option -6 is deprecated, please use \'-o "

                  "compat6\' instead!");

            return 1;

        case 'o':

            options = optarg;

            break;

        case 's':

            snapshot_name = optarg;

            break;

        case 'S':

        {

            int64_t sval;

            char *end;

            sval = strtosz_suffix(optarg, &end, STRTOSZ_DEFSUFFIX_B);

            if (sval < 0 || *end) {

                error_report("Invalid minimum zero buffer size for sparse output specified");

                return 1;

            }



            min_sparse = sval / BDRV_SECTOR_SIZE;

            break;

        }

        case 'p':

            progress = 1;

            break;

        case 't':

            cache = optarg;

            break;

        }

    }



    bs_n = argc - optind - 1;

    if (bs_n < 1) {

        help();

    }



    out_filename = argv[argc - 1];



    /* Initialize before goto out */

    qemu_progress_init(progress, 2.0);



    if (options && !strcmp(options, "?")) {

        ret = print_block_option_help(out_filename, out_fmt);

        goto out;

    }



    if (bs_n > 1 && out_baseimg) {

        error_report("-B makes no sense when concatenating multiple input "

                     "images");

        ret = -1;

        goto out;

    }



    qemu_progress_print(0, 100);



    bs = g_malloc0(bs_n * sizeof(BlockDriverState *));



    total_sectors = 0;

    for (bs_i = 0; bs_i < bs_n; bs_i++) {

        bs[bs_i] = bdrv_new_open(argv[optind + bs_i], fmt, BDRV_O_FLAGS);

        if (!bs[bs_i]) {

            error_report("Could not open '%s'", argv[optind + bs_i]);

            ret = -1;

            goto out;

        }

        bdrv_get_geometry(bs[bs_i], &bs_sectors);

        total_sectors += bs_sectors;

    }



    if (snapshot_name != NULL) {

        if (bs_n > 1) {

            error_report("No support for concatenating multiple snapshot");

            ret = -1;

            goto out;

        }

        if (bdrv_snapshot_load_tmp(bs[0], snapshot_name) < 0) {

            error_report("Failed to load snapshot");

            ret = -1;

            goto out;

        }

    }



    /* Find driver and parse its options */

    drv = bdrv_find_format(out_fmt);

    if (!drv) {

        error_report("Unknown file format '%s'", out_fmt);

        ret = -1;

        goto out;

    }



    proto_drv = bdrv_find_protocol(out_filename);

    if (!proto_drv) {

        error_report("Unknown protocol '%s'", out_filename);

        ret = -1;

        goto out;

    }



    create_options = append_option_parameters(create_options,

                                              drv->create_options);

    create_options = append_option_parameters(create_options,

                                              proto_drv->create_options);



    if (options) {

        param = parse_option_parameters(options, create_options, param);

        if (param == NULL) {

            error_report("Invalid options for file format '%s'.", out_fmt);

            ret = -1;

            goto out;

        }

    } else {

        param = parse_option_parameters("", create_options, param);

    }



    set_option_parameter_int(param, BLOCK_OPT_SIZE, total_sectors * 512);

    ret = add_old_style_options(out_fmt, param, out_baseimg, NULL);

    if (ret < 0) {

        goto out;

    }



    /* Get backing file name if -o backing_file was used */

    out_baseimg_param = get_option_parameter(param, BLOCK_OPT_BACKING_FILE);

    if (out_baseimg_param) {

        out_baseimg = out_baseimg_param->value.s;

    }



    /* Check if compression is supported */

    if (compress) {

        QEMUOptionParameter *encryption =

            get_option_parameter(param, BLOCK_OPT_ENCRYPT);

        QEMUOptionParameter *preallocation =

            get_option_parameter(param, BLOCK_OPT_PREALLOC);



        if (!drv->bdrv_write_compressed) {

            error_report("Compression not supported for this file format");

            ret = -1;

            goto out;

        }



        if (encryption && encryption->value.n) {

            error_report("Compression and encryption not supported at "

                         "the same time");

            ret = -1;

            goto out;

        }



        if (preallocation && preallocation->value.s

            && strcmp(preallocation->value.s, "off"))

        {

            error_report("Compression and preallocation not supported at "

                         "the same time");

            ret = -1;

            goto out;

        }

    }



    /* Create the new image */

    ret = bdrv_create(drv, out_filename, param);

    if (ret < 0) {

        if (ret == -ENOTSUP) {

            error_report("Formatting not supported for file format '%s'",

                         out_fmt);

        } else if (ret == -EFBIG) {

            error_report("The image size is too large for file format '%s'",

                         out_fmt);

        } else {

            error_report("%s: error while converting %s: %s",

                         out_filename, out_fmt, strerror(-ret));

        }

        goto out;

    }



    flags = BDRV_O_RDWR;

    ret = bdrv_parse_cache_flags(cache, &flags);

    if (ret < 0) {

        error_report("Invalid cache option: %s", cache);

        return -1;

    }



    out_bs = bdrv_new_open(out_filename, out_fmt, flags);

    if (!out_bs) {

        ret = -1;

        goto out;

    }



    bs_i = 0;

    bs_offset = 0;

    bdrv_get_geometry(bs[0], &bs_sectors);

    buf = qemu_blockalign(out_bs, IO_BUF_SIZE);



    if (compress) {

        ret = bdrv_get_info(out_bs, &bdi);

        if (ret < 0) {

            error_report("could not get block driver info");

            goto out;

        }

        cluster_size = bdi.cluster_size;

        if (cluster_size <= 0 || cluster_size > IO_BUF_SIZE) {

            error_report("invalid cluster size");

            ret = -1;

            goto out;

        }

        cluster_sectors = cluster_size >> 9;

        sector_num = 0;



        nb_sectors = total_sectors;

        local_progress = (float)100 /

            (nb_sectors / MIN(nb_sectors, cluster_sectors));



        for(;;) {

            int64_t bs_num;

            int remainder;

            uint8_t *buf2;



            nb_sectors = total_sectors - sector_num;

            if (nb_sectors <= 0)

                break;

            if (nb_sectors >= cluster_sectors)

                n = cluster_sectors;

            else

                n = nb_sectors;



            bs_num = sector_num - bs_offset;

            assert (bs_num >= 0);

            remainder = n;

            buf2 = buf;

            while (remainder > 0) {

                int nlow;

                while (bs_num == bs_sectors) {

                    bs_i++;

                    assert (bs_i < bs_n);

                    bs_offset += bs_sectors;

                    bdrv_get_geometry(bs[bs_i], &bs_sectors);

                    bs_num = 0;

                    /* printf("changing part: sector_num=%" PRId64 ", "

                       "bs_i=%d, bs_offset=%" PRId64 ", bs_sectors=%" PRId64

                       "\n", sector_num, bs_i, bs_offset, bs_sectors); */

                }

                assert (bs_num < bs_sectors);



                nlow = (remainder > bs_sectors - bs_num) ? bs_sectors - bs_num : remainder;



                ret = bdrv_read(bs[bs_i], bs_num, buf2, nlow);

                if (ret < 0) {

                    error_report("error while reading sector %" PRId64 ": %s",

                                 bs_num, strerror(-ret));

                    goto out;

                }



                buf2 += nlow * 512;

                bs_num += nlow;



                remainder -= nlow;

            }

            assert (remainder == 0);



            if (n < cluster_sectors) {

                memset(buf + n * 512, 0, cluster_size - n * 512);

            }

            if (!buffer_is_zero(buf, cluster_size)) {

                ret = bdrv_write_compressed(out_bs, sector_num, buf,

                                            cluster_sectors);

                if (ret != 0) {

                    error_report("error while compressing sector %" PRId64

                                 ": %s", sector_num, strerror(-ret));

                    goto out;

                }

            }

            sector_num += n;

            qemu_progress_print(local_progress, 100);

        }

        /* signal EOF to align */

        bdrv_write_compressed(out_bs, 0, NULL, 0);

    } else {

        int has_zero_init = bdrv_has_zero_init(out_bs);



        sector_num = 0; // total number of sectors converted so far

        nb_sectors = total_sectors - sector_num;

        local_progress = (float)100 /

            (nb_sectors / MIN(nb_sectors, IO_BUF_SIZE / 512));



        for(;;) {

            nb_sectors = total_sectors - sector_num;

            if (nb_sectors <= 0) {

                break;

            }

            if (nb_sectors >= (IO_BUF_SIZE / 512)) {

                n = (IO_BUF_SIZE / 512);

            } else {

                n = nb_sectors;

            }



            while (sector_num - bs_offset >= bs_sectors) {

                bs_i ++;

                assert (bs_i < bs_n);

                bs_offset += bs_sectors;

                bdrv_get_geometry(bs[bs_i], &bs_sectors);

                /* printf("changing part: sector_num=%" PRId64 ", bs_i=%d, "

                  "bs_offset=%" PRId64 ", bs_sectors=%" PRId64 "\n",

                   sector_num, bs_i, bs_offset, bs_sectors); */

            }



            if (n > bs_offset + bs_sectors - sector_num) {

                n = bs_offset + bs_sectors - sector_num;

            }



            if (has_zero_init) {

                /* If the output image is being created as a copy on write image,

                   assume that sectors which are unallocated in the input image

                   are present in both the output's and input's base images (no

                   need to copy them). */

                if (out_baseimg) {

                    if (!bdrv_is_allocated(bs[bs_i], sector_num - bs_offset,

                                           n, &n1)) {

                        sector_num += n1;

                        continue;

                    }

                    /* The next 'n1' sectors are allocated in the input image. Copy

                       only those as they may be followed by unallocated sectors. */

                    n = n1;

                }

            } else {

                n1 = n;

            }



            ret = bdrv_read(bs[bs_i], sector_num - bs_offset, buf, n);

            if (ret < 0) {

                error_report("error while reading sector %" PRId64 ": %s",

                             sector_num - bs_offset, strerror(-ret));

                goto out;

            }

            /* NOTE: at the same time we convert, we do not write zero

               sectors to have a chance to compress the image. Ideally, we

               should add a specific call to have the info to go faster */

            buf1 = buf;

            while (n > 0) {

                /* If the output image is being created as a copy on write image,

                   copy all sectors even the ones containing only NUL bytes,

                   because they may differ from the sectors in the base image.



                   If the output is to a host device, we also write out

                   sectors that are entirely 0, since whatever data was

                   already there is garbage, not 0s. */

                if (!has_zero_init || out_baseimg ||

                    is_allocated_sectors_min(buf1, n, &n1, min_sparse)) {

                    ret = bdrv_write(out_bs, sector_num, buf1, n1);

                    if (ret < 0) {

                        error_report("error while writing sector %" PRId64

                                     ": %s", sector_num, strerror(-ret));

                        goto out;

                    }

                }

                sector_num += n1;

                n -= n1;

                buf1 += n1 * 512;

            }

            qemu_progress_print(local_progress, 100);

        }

    }

out:

    qemu_progress_end();

    free_option_parameters(create_options);

    free_option_parameters(param);

    qemu_vfree(buf);

    if (out_bs) {

        bdrv_delete(out_bs);

    }

    if (bs) {

        for (bs_i = 0; bs_i < bs_n; bs_i++) {

            if (bs[bs_i]) {

                bdrv_delete(bs[bs_i]);

            }

        }

        g_free(bs);

    }

    if (ret) {

        return 1;

    }

    return 0;

}

static void qemu_kvm_eat_signal(CPUState *env, int timeout)

{

    struct timespec ts;

    int r, e;

    siginfo_t siginfo;

    sigset_t waitset;



    ts.tv_sec = timeout / 1000;

    ts.tv_nsec = (timeout % 1000) * 1000000;



    sigemptyset(&waitset);

    sigaddset(&waitset, SIG_IPI);



    qemu_mutex_unlock(&qemu_global_mutex);

    r = sigtimedwait(&waitset, &siginfo, &ts);

    e = errno;

    qemu_mutex_lock(&qemu_global_mutex);



    if (r == -1 && !(e == EAGAIN || e == EINTR)) {

        fprintf(stderr, "sigtimedwait: %s\n", strerror(e));

        exit(1);

    }

}

static void do_bit_allocation(AC3DecodeContext *ctx, int flags)

{

    ac3_audio_block *ab = &ctx->audio_block;

    int i, snroffst = 0;



    if (!flags) /* bit allocation is not required */

        return;



    if (ab->flags & AC3_AB_SNROFFSTE) { /* check whether snroffsts are zero */

        snroffst += ab->csnroffst;

        if (ab->flags & AC3_AB_CPLINU)

            snroffst += ab->cplfsnroffst;

        for (i = 0; i < ctx->bsi.nfchans; i++)

            snroffst += ab->fsnroffst[i];

        if (ctx->bsi.flags & AC3_BSI_LFEON)

            snroffst += ab->lfefsnroffst;

        if (!snroffst) {

            memset(ab->cplbap, 0, sizeof (ab->cplbap));

            for (i = 0; i < ctx->bsi.nfchans; i++)

                memset(ab->bap[i], 0, sizeof (ab->bap[i]));

            memset(ab->lfebap, 0, sizeof (ab->lfebap));



            return;

        }

    }



    /* perform bit allocation */

    if ((ab->flags & AC3_AB_CPLINU) && (flags & 64))

        do_bit_allocation1(ctx, 5);

    for (i = 0; i < ctx->bsi.nfchans; i++)

        if (flags & (1 << i))

            do_bit_allocation1(ctx, i);

    if ((ctx->bsi.flags & AC3_BSI_LFEON) && (flags & 32))

        do_bit_allocation1(ctx, 6);

}

int cpu_signal_handler(int host_signum, void *pinfo,

                       void *puc)

{

    siginfo_t *info = pinfo;

#if defined(__FreeBSD__) || defined(__FreeBSD_kernel__)

    ucontext_t *uc = puc;

#else

    ucontext_t *uc = puc;

#endif

    unsigned long pc;

    int is_write;



    pc = IAR_sig(uc);

    is_write = 0;

#if 0

    /* ppc 4xx case */

    if (DSISR_sig(uc) & 0x00800000) {

        is_write = 1;

    }

#else

    if (TRAP_sig(uc) != 0x400 && (DSISR_sig(uc) & 0x02000000)) {

        is_write = 1;

    }

#endif

    return handle_cpu_signal(pc, (unsigned long)info->si_addr,

                             is_write, &uc->uc_sigmask);

}

