uint32_t helper_efdctsf (uint64_t val)

{

    CPU_DoubleU u;

    float64 tmp;



    u.ll = val;

    /* NaN are not treated the same way IEEE 754 does */

    if (unlikely(float64_is_nan(u.d)))

        return 0;

    tmp = uint64_to_float64(1ULL << 32, &env->vec_status);

    u.d = float64_mul(u.d, tmp, &env->vec_status);



    return float64_to_int32(u.d, &env->vec_status);

}

int ff_hevc_split_packet(HEVCContext *s, HEVCPacket *pkt, const uint8_t *buf, int length,

                         AVCodecContext *avctx, int is_nalff, int nal_length_size)

{

    int consumed, ret = 0;



    pkt->nb_nals = 0;

    while (length >= 4) {

        HEVCNAL *nal;

        int extract_length = 0;



        if (is_nalff) {

            int i;

            for (i = 0; i < nal_length_size; i++)

                extract_length = (extract_length << 8) | buf[i];

            buf    += nal_length_size;

            length -= nal_length_size;



            if (extract_length > length) {

                av_log(avctx, AV_LOG_ERROR, "Invalid NAL unit size.\n");

                return AVERROR_INVALIDDATA;

            }

        } else {

            /* search start code */

            while (buf[0] != 0 || buf[1] != 0 || buf[2] != 1) {

                ++buf;

                --length;

                if (length < 4) {

                    if (pkt->nb_nals > 0) {

                        // No more start codes: we discarded some irrelevant

                        // bytes at the end of the packet.

                        return 0;

                    } else {

                        av_log(avctx, AV_LOG_ERROR, "No start code is found.\n");

                        return AVERROR_INVALIDDATA;

                    }

                }

            }



            buf           += 3;

            length        -= 3;

            extract_length = length;

        }



        if (pkt->nals_allocated < pkt->nb_nals + 1) {

            int new_size = pkt->nals_allocated + 1;

            void *tmp = av_realloc_array(pkt->nals, new_size, sizeof(*pkt->nals));



            if (!tmp)

                return AVERROR(ENOMEM);



            pkt->nals = tmp;

            memset(pkt->nals + pkt->nals_allocated, 0,

                   (new_size - pkt->nals_allocated) * sizeof(*pkt->nals));



            nal = &pkt->nals[pkt->nb_nals];

            nal->skipped_bytes_pos_size = 1024; // initial buffer size

            nal->skipped_bytes_pos = av_malloc_array(nal->skipped_bytes_pos_size, sizeof(*nal->skipped_bytes_pos));

            if (!nal->skipped_bytes_pos)

                return AVERROR(ENOMEM);



            pkt->nals_allocated = new_size;

        }

        nal = &pkt->nals[pkt->nb_nals];



        consumed = ff_hevc_extract_rbsp(s, buf, extract_length, nal);

        if (consumed < 0)

            return consumed;



        pkt->nb_nals++;



        ret = init_get_bits8(&nal->gb, nal->data, nal->size);

        if (ret < 0)

            return ret;



        ret = hls_nal_unit(nal, avctx);

        if (ret <= 0) {

            if (ret < 0) {

                av_log(avctx, AV_LOG_ERROR, "Invalid NAL unit %d, skipping.\n",

                       nal->type);

            }

            pkt->nb_nals--;

        }



        buf    += consumed;

        length -= consumed;

    }



    return 0;

}

int vnc_tls_validate_certificate(VncState *vs)

{

    int ret;

    unsigned int status;

    const gnutls_datum_t *certs;

    unsigned int nCerts, i;

    time_t now;



    VNC_DEBUG("Validating client certificate\n");

    if ((ret = gnutls_certificate_verify_peers2 (vs->tls.session, &status)) < 0) {

        VNC_DEBUG("Verify failed %s\n", gnutls_strerror(ret));

        return -1;

    }



    if ((now = time(NULL)) == ((time_t)-1)) {

        return -1;

    }



    if (status != 0) {

        if (status & GNUTLS_CERT_INVALID)

            VNC_DEBUG("The certificate is not trusted.\n");



        if (status & GNUTLS_CERT_SIGNER_NOT_FOUND)

            VNC_DEBUG("The certificate hasn't got a known issuer.\n");



        if (status & GNUTLS_CERT_REVOKED)

            VNC_DEBUG("The certificate has been revoked.\n");



        if (status & GNUTLS_CERT_INSECURE_ALGORITHM)

            VNC_DEBUG("The certificate uses an insecure algorithm\n");



        return -1;

    } else {

        VNC_DEBUG("Certificate is valid!\n");

    }



    /* Only support x509 for now */

    if (gnutls_certificate_type_get(vs->tls.session) != GNUTLS_CRT_X509)

        return -1;



    if (!(certs = gnutls_certificate_get_peers(vs->tls.session, &nCerts)))

        return -1;



    for (i = 0 ; i < nCerts ; i++) {

        gnutls_x509_crt_t cert;

        VNC_DEBUG ("Checking certificate chain %d\n", i);

        if (gnutls_x509_crt_init (&cert) < 0)

            return -1;



        if (gnutls_x509_crt_import(cert, &certs[i], GNUTLS_X509_FMT_DER) < 0) {

            gnutls_x509_crt_deinit (cert);

            return -1;

        }



        if (gnutls_x509_crt_get_expiration_time (cert) < now) {

            VNC_DEBUG("The certificate has expired\n");

            gnutls_x509_crt_deinit (cert);

            return -1;

        }



        if (gnutls_x509_crt_get_activation_time (cert) > now) {

            VNC_DEBUG("The certificate is not yet activated\n");

            gnutls_x509_crt_deinit (cert);

            return -1;

        }



        if (gnutls_x509_crt_get_activation_time (cert) > now) {

            VNC_DEBUG("The certificate is not yet activated\n");

            gnutls_x509_crt_deinit (cert);

            return -1;

        }



        if (i == 0) {

            size_t dnameSize = 1024;

            vs->tls.dname = g_malloc(dnameSize);

        requery:

            if ((ret = gnutls_x509_crt_get_dn (cert, vs->tls.dname, &dnameSize)) != 0) {

                if (ret == GNUTLS_E_SHORT_MEMORY_BUFFER) {

                    vs->tls.dname = g_realloc(vs->tls.dname, dnameSize);

                    goto requery;

                }

                gnutls_x509_crt_deinit (cert);

                VNC_DEBUG("Cannot get client distinguished name: %s",

                          gnutls_strerror (ret));

                return -1;

            }



            if (vs->vd->tls.x509verify) {

                int allow;

                if (!vs->vd->tls.acl) {

                    VNC_DEBUG("no ACL activated, allowing access");

                    gnutls_x509_crt_deinit (cert);

                    continue;

                }



                allow = qemu_acl_party_is_allowed(vs->vd->tls.acl,

                                                  vs->tls.dname);



                VNC_DEBUG("TLS x509 ACL check for %s is %s\n",

                          vs->tls.dname, allow ? "allowed" : "denied");

                if (!allow) {

                    gnutls_x509_crt_deinit (cert);

                    return -1;

                }

            }

        }



        gnutls_x509_crt_deinit (cert);

    }



    return 0;

}

void net_slirp_redir(Monitor *mon, const char *redir_str, const char *redir_opt2)

{

    struct slirp_config_str *config;



    if (!slirp_inited) {

        if (mon) {

            monitor_printf(mon, "user mode network stack not in use\n");

        } else {

            config = qemu_malloc(sizeof(*config));

            config->str = redir_str;

            config->next = slirp_redirs;

            slirp_redirs = config;

        }

        return;

    }



    if (!strcmp(redir_str, "remove")) {

        net_slirp_redir_rm(mon, redir_opt2);

        return;

    }



    slirp_redirection(mon, redir_str);

}

static void virtio_blk_rw_complete(void *opaque, int ret)

{

    VirtIOBlockReq *req = opaque;



    trace_virtio_blk_rw_complete(req, ret);



    if (ret) {

        int p = virtio_ldl_p(VIRTIO_DEVICE(req->dev), &req->out.type);

        bool is_read = !(p & VIRTIO_BLK_T_OUT);

        if (virtio_blk_handle_rw_error(req, -ret, is_read))

            return;

    }



    virtio_blk_req_complete(req, VIRTIO_BLK_S_OK);

    block_acct_done(bdrv_get_stats(req->dev->bs), &req->acct);

    virtio_blk_free_request(req);

}

static gboolean ga_channel_listen_accept(GIOChannel *channel,

                                         GIOCondition condition, gpointer data)

{

    GAChannel *c = data;

    int ret, client_fd;

    bool accepted = false;

    struct sockaddr_un addr;

    socklen_t addrlen = sizeof(addr);



    g_assert(channel != NULL);



    client_fd = qemu_accept(g_io_channel_unix_get_fd(channel),

                            (struct sockaddr *)&addr, &addrlen);

    if (client_fd == -1) {

        g_warning("error converting fd to gsocket: %s", strerror(errno));

        goto out;

    }

    fcntl(client_fd, F_SETFL, O_NONBLOCK);

    ret = ga_channel_client_add(c, client_fd);

    if (ret) {

        g_warning("error setting up connection");


        goto out;

    }

    accepted = true;



out:

    /* only accept 1 connection at a time */

    return !accepted;

}

static void sch_handle_start_func(SubchDev *sch, ORB *orb)

{



    PMCW *p = &sch->curr_status.pmcw;

    SCSW *s = &sch->curr_status.scsw;

    int path;

    int ret;



    /* Path management: In our simple css, we always choose the only path. */

    path = 0x80;



    if (!(s->ctrl & SCSW_ACTL_SUSP)) {



        /* Look at the orb and try to execute the channel program. */

        assert(orb != NULL); /* resume does not pass an orb */

        p->intparm = orb->intparm;

        if (!(orb->lpm & path)) {

            /* Generate a deferred cc 3 condition. */

            s->flags |= SCSW_FLAGS_MASK_CC;

            s->ctrl &= ~SCSW_CTRL_MASK_STCTL;

            s->ctrl |= (SCSW_STCTL_ALERT | SCSW_STCTL_STATUS_PEND);

            return;

        }

        sch->ccw_fmt_1 = !!(orb->ctrl0 & ORB_CTRL0_MASK_FMT);

        sch->ccw_no_data_cnt = 0;

    } else {

        s->ctrl &= ~(SCSW_ACTL_SUSP | SCSW_ACTL_RESUME_PEND);

    }

    sch->last_cmd_valid = false;

    do {

        ret = css_interpret_ccw(sch, sch->channel_prog);

        switch (ret) {

        case -EAGAIN:

            /* ccw chain, continue processing */

            break;

        case 0:

            /* success */

            s->ctrl &= ~SCSW_ACTL_START_PEND;

            s->ctrl &= ~SCSW_CTRL_MASK_STCTL;

            s->ctrl |= SCSW_STCTL_PRIMARY | SCSW_STCTL_SECONDARY |

                    SCSW_STCTL_STATUS_PEND;

            s->dstat = SCSW_DSTAT_CHANNEL_END | SCSW_DSTAT_DEVICE_END;

            s->cpa = sch->channel_prog + 8;

            break;

        case -ENOSYS:

            /* unsupported command, generate unit check (command reject) */

            s->ctrl &= ~SCSW_ACTL_START_PEND;

            s->dstat = SCSW_DSTAT_UNIT_CHECK;

            /* Set sense bit 0 in ecw0. */

            sch->sense_data[0] = 0x80;

            s->ctrl &= ~SCSW_CTRL_MASK_STCTL;

            s->ctrl |= SCSW_STCTL_PRIMARY | SCSW_STCTL_SECONDARY |

                    SCSW_STCTL_ALERT | SCSW_STCTL_STATUS_PEND;

            s->cpa = sch->channel_prog + 8;

            break;

        case -EFAULT:

            /* memory problem, generate channel data check */

            s->ctrl &= ~SCSW_ACTL_START_PEND;

            s->cstat = SCSW_CSTAT_DATA_CHECK;

            s->ctrl &= ~SCSW_CTRL_MASK_STCTL;

            s->ctrl |= SCSW_STCTL_PRIMARY | SCSW_STCTL_SECONDARY |

                    SCSW_STCTL_ALERT | SCSW_STCTL_STATUS_PEND;

            s->cpa = sch->channel_prog + 8;

            break;

        case -EBUSY:

            /* subchannel busy, generate deferred cc 1 */

            s->flags &= ~SCSW_FLAGS_MASK_CC;

            s->flags |= (1 << 8);

            s->ctrl &= ~SCSW_CTRL_MASK_STCTL;

            s->ctrl |= SCSW_STCTL_ALERT | SCSW_STCTL_STATUS_PEND;

            break;

        case -EINPROGRESS:

            /* channel program has been suspended */

            s->ctrl &= ~SCSW_ACTL_START_PEND;

            s->ctrl |= SCSW_ACTL_SUSP;

            break;

        default:

            /* error, generate channel program check */

            s->ctrl &= ~SCSW_ACTL_START_PEND;

            s->cstat = SCSW_CSTAT_PROG_CHECK;

            s->ctrl &= ~SCSW_CTRL_MASK_STCTL;

            s->ctrl |= SCSW_STCTL_PRIMARY | SCSW_STCTL_SECONDARY |

                    SCSW_STCTL_ALERT | SCSW_STCTL_STATUS_PEND;

            s->cpa = sch->channel_prog + 8;

            break;

        }

    } while (ret == -EAGAIN);



}

