        if (codec_id == CODEC_ID_VP8) {

            h->pred16x16[PLANE_PRED8x8] = ff_pred16x16_tm_vp8_mmxext;

            h->pred8x8  [DC_PRED8x8   ] = ff_pred8x8_dc_rv40_mmxext;

            h->pred8x8  [PLANE_PRED8x8] = ff_pred8x8_tm_vp8_mmxext;

            h->pred4x4  [TM_VP8_PRED  ] = ff_pred4x4_tm_vp8_mmxext;

            h->pred4x4  [VERT_PRED    ] = ff_pred4x4_vertical_vp8_mmxext;

        }

    }



    if (mm_flags & FF_MM_SSE) {

        h->pred16x16[VERT_PRED8x8] = ff_pred16x16_vertical_sse;

        h->pred16x16[DC_PRED8x8  ] = ff_pred16x16_dc_sse;

    }



    if (mm_flags & FF_MM_SSE2) {

        h->pred16x16[DC_PRED8x8  ] = ff_pred16x16_dc_sse2;

        if (codec_id == CODEC_ID_VP8) {

            h->pred16x16[PLANE_PRED8x8] = ff_pred16x16_tm_vp8_sse2;

            h->pred8x8  [PLANE_PRED8x8] = ff_pred8x8_tm_vp8_sse2;

        }

    }



    if (mm_flags & FF_MM_SSSE3) {

        h->pred16x16[HOR_PRED8x8 ] = ff_pred16x16_horizontal_ssse3;

        h->pred16x16[DC_PRED8x8  ] = ff_pred16x16_dc_ssse3;

        h->pred8x8  [HOR_PRED8x8 ] = ff_pred8x8_horizontal_ssse3;

        if (codec_id == CODEC_ID_VP8) {

            h->pred8x8  [PLANE_PRED8x8] = ff_pred8x8_tm_vp8_ssse3;

            h->pred4x4  [TM_VP8_PRED  ] = ff_pred4x4_tm_vp8_ssse3;

        }

    }

#endif

}

static void qdm2_decode_fft_packets(QDM2Context *q)

{

    int i, j, min, max, value, type, unknown_flag;

    GetBitContext gb;



    if (q->sub_packet_list_B[0].packet == NULL)

        return;



    /* reset minimum indexes for FFT coefficients */

    q->fft_coefs_index = 0;

    for (i = 0; i < 5; i++)

        q->fft_coefs_min_index[i] = -1;



    /* process subpackets ordered by type, largest type first */

    for (i = 0, max = 256; i < q->sub_packets_B; i++) {

        QDM2SubPacket *packet = NULL;



        /* find subpacket with largest type less than max */

        for (j = 0, min = 0; j < q->sub_packets_B; j++) {

            value = q->sub_packet_list_B[j].packet->type;

            if (value > min && value < max) {

                min    = value;

                packet = q->sub_packet_list_B[j].packet;

            }

        }



        max = min;



        /* check for errors (?) */

        if (!packet)

            return;



        if (i == 0 &&

            (packet->type < 16 || packet->type >= 48 ||

             fft_subpackets[packet->type - 16]))

            return;



        /* decode FFT tones */

        init_get_bits(&gb, packet->data, packet->size * 8);



        if (packet->type >= 32 && packet->type < 48 && !fft_subpackets[packet->type - 16])

            unknown_flag = 1;

        else

            unknown_flag = 0;



        type = packet->type;



        if ((type >= 17 && type < 24) || (type >= 33 && type < 40)) {

            int duration = q->sub_sampling + 5 - (type & 15);



            if (duration >= 0 && duration < 4)

                qdm2_fft_decode_tones(q, duration, &gb, unknown_flag);

        } else if (type == 31) {

            for (j = 0; j < 4; j++)

                qdm2_fft_decode_tones(q, j, &gb, unknown_flag);

        } else if (type == 46) {

            for (j = 0; j < 6; j++)

                q->fft_level_exp[j] = get_bits(&gb, 6);

            for (j = 0; j < 4; j++)

                qdm2_fft_decode_tones(q, j, &gb, unknown_flag);

        }

    } // Loop on B packets



    /* calculate maximum indexes for FFT coefficients */

    for (i = 0, j = -1; i < 5; i++)

        if (q->fft_coefs_min_index[i] >= 0) {

            if (j >= 0)

                q->fft_coefs_max_index[j] = q->fft_coefs_min_index[i];

            j = i;

        }

    if (j >= 0)

        q->fft_coefs_max_index[j] = q->fft_coefs_index;

}

