static int ape_decode_frame(AVCodecContext *avctx, void *data,

                            int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    APEContext *s = avctx->priv_data;

    uint8_t *sample8;

    int16_t *sample16;

    int32_t *sample24;

    int i, ch, ret;

    int blockstodecode;



    /* this should never be negative, but bad things will happen if it is, so

       check it just to make sure. */

    av_assert0(s->samples >= 0);



    if(!s->samples){

        uint32_t nblocks, offset;

        int buf_size;



        if (!avpkt->size) {

            *got_frame_ptr = 0;

            return 0;

        }

        if (avpkt->size < 8) {

            av_log(avctx, AV_LOG_ERROR, "Packet is too small\n");

            return AVERROR_INVALIDDATA;

        }

        buf_size = avpkt->size & ~3;

        if (buf_size != avpkt->size) {

            av_log(avctx, AV_LOG_WARNING, "packet size is not a multiple of 4. "

                   "extra bytes at the end will be skipped.\n");

        }

        if (s->fileversion < 3950) // previous versions overread two bytes

            buf_size += 2;

        av_fast_malloc(&s->data, &s->data_size, buf_size);

        if (!s->data)

            return AVERROR(ENOMEM);

        s->dsp.bswap_buf((uint32_t*)s->data, (const uint32_t*)buf, buf_size >> 2);

        memset(s->data + (buf_size & ~3), 0, buf_size & 3);

        s->ptr = s->data;

        s->data_end = s->data + buf_size;



        nblocks = bytestream_get_be32(&s->ptr);

        offset  = bytestream_get_be32(&s->ptr);

        if (s->fileversion >= 3900) {

            if (offset > 3) {

                av_log(avctx, AV_LOG_ERROR, "Incorrect offset passed\n");

                s->data = NULL;

                return AVERROR_INVALIDDATA;

            }

            if (s->data_end - s->ptr < offset) {

                av_log(avctx, AV_LOG_ERROR, "Packet is too small\n");

                return AVERROR_INVALIDDATA;

            }

            s->ptr += offset;

        } else {

            if ((ret = init_get_bits8(&s->gb, s->ptr, s->data_end - s->ptr)) < 0)

                return ret;

            if (s->fileversion > 3800)

                skip_bits_long(&s->gb, offset * 8);

            else

                skip_bits_long(&s->gb, offset);

        }



        if (!nblocks || nblocks > INT_MAX) {

            av_log(avctx, AV_LOG_ERROR, "Invalid sample count: %u.\n", nblocks);

            return AVERROR_INVALIDDATA;

        }

        s->samples = nblocks;



        /* Initialize the frame decoder */

        if (init_frame_decoder(s) < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error reading frame header\n");

            return AVERROR_INVALIDDATA;

        }

    }



    if (!s->data) {

        *got_frame_ptr = 0;

        return avpkt->size;

    }



    blockstodecode = FFMIN(s->blocks_per_loop, s->samples);

    // for old files coefficients were not interleaved,

    // so we need to decode all of them at once

    if (s->fileversion < 3930)

        blockstodecode = s->samples;



    /* reallocate decoded sample buffer if needed */

    av_fast_malloc(&s->decoded_buffer, &s->decoded_size,

                   2 * FFALIGN(blockstodecode, 8) * sizeof(*s->decoded_buffer));

    if (!s->decoded_buffer)

        return AVERROR(ENOMEM);

    memset(s->decoded_buffer, 0, s->decoded_size);

    s->decoded[0] = s->decoded_buffer;

    s->decoded[1] = s->decoded_buffer + FFALIGN(blockstodecode, 8);



    /* get output buffer */

    frame->nb_samples = blockstodecode;

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0)

        return ret;



    s->error=0;



    if ((s->channels == 1) || (s->frameflags & APE_FRAMECODE_PSEUDO_STEREO))

        ape_unpack_mono(s, blockstodecode);

    else

        ape_unpack_stereo(s, blockstodecode);

    emms_c();



    if (s->error) {

        s->samples=0;

        av_log(avctx, AV_LOG_ERROR, "Error decoding frame\n");

        return AVERROR_INVALIDDATA;

    }



    switch (s->bps) {

    case 8:

        for (ch = 0; ch < s->channels; ch++) {

            sample8 = (uint8_t *)frame->data[ch];

            for (i = 0; i < blockstodecode; i++)

                *sample8++ = (s->decoded[ch][i] + 0x80) & 0xff;

        }

        break;

    case 16:

        for (ch = 0; ch < s->channels; ch++) {

            sample16 = (int16_t *)frame->data[ch];

            for (i = 0; i < blockstodecode; i++)

                *sample16++ = s->decoded[ch][i];

        }

        break;

    case 24:

        for (ch = 0; ch < s->channels; ch++) {

            sample24 = (int32_t *)frame->data[ch];

            for (i = 0; i < blockstodecode; i++)

                *sample24++ = s->decoded[ch][i] << 8;

        }

        break;

    }



    s->samples -= blockstodecode;



    *got_frame_ptr = 1;



    return !s->samples ? avpkt->size : 0;

}

static inline uint16_t mipsdsp_trunc16_sat16_round(int32_t a,

                                                   CPUMIPSState *env)

{

    int64_t temp;



    temp = (int32_t)a + 0x00008000;



    if (a > (int)0x7fff8000) {

        temp = 0x7FFFFFFF;

        set_DSPControl_overflow_flag(1, 22, env);

    }



    return (temp >> 16) & 0xFFFF;

}

int qemu_strtoi64(const char *nptr, const char **endptr, int base,

                 int64_t *result)

{

    char *ep;

    int err = 0;

    if (!nptr) {

        if (endptr) {

            *endptr = nptr;

        }

        err = -EINVAL;

    } else {

        errno = 0;

        /* FIXME This assumes int64_t is long long */

        *result = strtoll(nptr, &ep, base);

        err = check_strtox_error(nptr, ep, endptr, errno);

    }

    return err;

}

int spapr_populate_pci_dt(sPAPRPHBState *phb,

                          uint32_t xics_phandle,

                          void *fdt)

{

    int bus_off, i, j, ret;

    char nodename[FDT_NAME_MAX];

    uint32_t bus_range[] = { cpu_to_be32(0), cpu_to_be32(0xff) };

    const uint64_t mmiosize = memory_region_size(&phb->memwindow);

    const uint64_t w32max = (1ULL << 32) - SPAPR_PCI_MEM_WIN_BUS_OFFSET;

    const uint64_t w32size = MIN(w32max, mmiosize);

    const uint64_t w64size = (mmiosize > w32size) ? (mmiosize - w32size) : 0;

    struct {

        uint32_t hi;

        uint64_t child;

        uint64_t parent;

        uint64_t size;

    } QEMU_PACKED ranges[] = {

        {

            cpu_to_be32(b_ss(1)), cpu_to_be64(0),

            cpu_to_be64(phb->io_win_addr),

            cpu_to_be64(memory_region_size(&phb->iospace)),

        },

        {

            cpu_to_be32(b_ss(2)), cpu_to_be64(SPAPR_PCI_MEM_WIN_BUS_OFFSET),

            cpu_to_be64(phb->mem_win_addr),

            cpu_to_be64(w32size),

        },

        {

            cpu_to_be32(b_ss(3)), cpu_to_be64(1ULL << 32),

            cpu_to_be64(phb->mem_win_addr + w32size),

            cpu_to_be64(w64size)

        },

    };

    const unsigned sizeof_ranges = (w64size ? 3 : 2) * sizeof(ranges[0]);

    uint64_t bus_reg[] = { cpu_to_be64(phb->buid), 0 };

    uint32_t interrupt_map_mask[] = {

        cpu_to_be32(b_ddddd(-1)|b_fff(0)), 0x0, 0x0, cpu_to_be32(-1)};

    uint32_t interrupt_map[PCI_SLOT_MAX * PCI_NUM_PINS][7];

    uint32_t ddw_applicable[] = {

        cpu_to_be32(RTAS_IBM_QUERY_PE_DMA_WINDOW),

        cpu_to_be32(RTAS_IBM_CREATE_PE_DMA_WINDOW),

        cpu_to_be32(RTAS_IBM_REMOVE_PE_DMA_WINDOW)

    };

    uint32_t ddw_extensions[] = {

        cpu_to_be32(1),

        cpu_to_be32(RTAS_IBM_RESET_PE_DMA_WINDOW)

    };

    uint32_t associativity[] = {cpu_to_be32(0x4),

                                cpu_to_be32(0x0),

                                cpu_to_be32(0x0),

                                cpu_to_be32(0x0),

                                cpu_to_be32(phb->numa_node)};

    sPAPRTCETable *tcet;

    PCIBus *bus = PCI_HOST_BRIDGE(phb)->bus;

    sPAPRFDT s_fdt;



    /* Start populating the FDT */

    snprintf(nodename, FDT_NAME_MAX, "pci@%" PRIx64, phb->buid);

    bus_off = fdt_add_subnode(fdt, 0, nodename);

    if (bus_off < 0) {

        return bus_off;

    }



    /* Write PHB properties */

    _FDT(fdt_setprop_string(fdt, bus_off, "device_type", "pci"));

    _FDT(fdt_setprop_string(fdt, bus_off, "compatible", "IBM,Logical_PHB"));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#address-cells", 0x3));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#size-cells", 0x2));

    _FDT(fdt_setprop_cell(fdt, bus_off, "#interrupt-cells", 0x1));

    _FDT(fdt_setprop(fdt, bus_off, "used-by-rtas", NULL, 0));

    _FDT(fdt_setprop(fdt, bus_off, "bus-range", &bus_range, sizeof(bus_range)));

    _FDT(fdt_setprop(fdt, bus_off, "ranges", &ranges, sizeof_ranges));

    _FDT(fdt_setprop(fdt, bus_off, "reg", &bus_reg, sizeof(bus_reg)));

    _FDT(fdt_setprop_cell(fdt, bus_off, "ibm,pci-config-space-type", 0x1));

    _FDT(fdt_setprop_cell(fdt, bus_off, "ibm,pe-total-#msi", XICS_IRQS_SPAPR));



    /* Dynamic DMA window */

    if (phb->ddw_enabled) {

        _FDT(fdt_setprop(fdt, bus_off, "ibm,ddw-applicable", &ddw_applicable,

                         sizeof(ddw_applicable)));

        _FDT(fdt_setprop(fdt, bus_off, "ibm,ddw-extensions",

                         &ddw_extensions, sizeof(ddw_extensions)));

    }



    /* Advertise NUMA via ibm,associativity */

    if (nb_numa_nodes > 1) {

        _FDT(fdt_setprop(fdt, bus_off, "ibm,associativity", associativity,

                         sizeof(associativity)));

    }



    /* Build the interrupt-map, this must matches what is done

     * in pci_spapr_map_irq

     */

    _FDT(fdt_setprop(fdt, bus_off, "interrupt-map-mask",

                     &interrupt_map_mask, sizeof(interrupt_map_mask)));

    for (i = 0; i < PCI_SLOT_MAX; i++) {

        for (j = 0; j < PCI_NUM_PINS; j++) {

            uint32_t *irqmap = interrupt_map[i*PCI_NUM_PINS + j];

            int lsi_num = pci_spapr_swizzle(i, j);



            irqmap[0] = cpu_to_be32(b_ddddd(i)|b_fff(0));

            irqmap[1] = 0;

            irqmap[2] = 0;

            irqmap[3] = cpu_to_be32(j+1);

            irqmap[4] = cpu_to_be32(xics_phandle);

            irqmap[5] = cpu_to_be32(phb->lsi_table[lsi_num].irq);

            irqmap[6] = cpu_to_be32(0x8);

        }

    }

    /* Write interrupt map */

    _FDT(fdt_setprop(fdt, bus_off, "interrupt-map", &interrupt_map,

                     sizeof(interrupt_map)));



    tcet = spapr_tce_find_by_liobn(phb->dma_liobn[0]);

    if (!tcet) {

        return -1;

    }

    spapr_dma_dt(fdt, bus_off, "ibm,dma-window",

                 tcet->liobn, tcet->bus_offset,

                 tcet->nb_table << tcet->page_shift);



    /* Walk the bridges and program the bus numbers*/

    spapr_phb_pci_enumerate(phb);

    _FDT(fdt_setprop_cell(fdt, bus_off, "qemu,phb-enumerated", 0x1));



    /* Populate tree nodes with PCI devices attached */

    s_fdt.fdt = fdt;

    s_fdt.node_off = bus_off;

    s_fdt.sphb = phb;

    pci_for_each_device(bus, pci_bus_num(bus),

                        spapr_populate_pci_devices_dt,

                        &s_fdt);



    ret = spapr_drc_populate_dt(fdt, bus_off, OBJECT(phb),

                                SPAPR_DR_CONNECTOR_TYPE_PCI);

    if (ret) {

        return ret;

    }



    return 0;

}

