static int get_aiff_header(AVFormatContext *s, int size,

                                    unsigned version)

{

    AVIOContext *pb        = s->pb;

    AVCodecParameters *par = s->streams[0]->codecpar;

    AIFFInputContext *aiff = s->priv_data;

    int exp;

    uint64_t val;

    int sample_rate;

    unsigned int num_frames;



    if (size & 1)

        size++;

    par->codec_type = AVMEDIA_TYPE_AUDIO;

    par->channels = avio_rb16(pb);

    num_frames = avio_rb32(pb);

    par->bits_per_coded_sample = avio_rb16(pb);



    exp = avio_rb16(pb) - 16383 - 63;

    val = avio_rb64(pb);

    if (exp <-63 || exp >63) {

        av_log(s, AV_LOG_ERROR, "exp %d is out of range\n", exp);

        return AVERROR_INVALIDDATA;

    }

    if (exp >= 0)

        sample_rate = val << exp;

    else

        sample_rate = (val + (1ULL<<(-exp-1))) >> -exp;

    par->sample_rate = sample_rate;

    size -= 18;



    /* get codec id for AIFF-C */

    if (size < 4) {

        version = AIFF;

    } else if (version == AIFF_C_VERSION1) {

        par->codec_tag = avio_rl32(pb);

        par->codec_id  = ff_codec_get_id(ff_codec_aiff_tags, par->codec_tag);

        if (par->codec_id == AV_CODEC_ID_NONE) {

            char tag[32];

            av_get_codec_tag_string(tag, sizeof(tag), par->codec_tag);

            avpriv_request_sample(s, "unknown or unsupported codec tag: %s", tag);

        }

        size -= 4;

    }



    if (version != AIFF_C_VERSION1 || par->codec_id == AV_CODEC_ID_PCM_S16BE) {

        par->codec_id = aiff_codec_get_id(par->bits_per_coded_sample);

        par->bits_per_coded_sample = av_get_bits_per_sample(par->codec_id);

        aiff->block_duration = 1;

    } else {

        switch (par->codec_id) {

        case AV_CODEC_ID_PCM_F32BE:

        case AV_CODEC_ID_PCM_F64BE:

        case AV_CODEC_ID_PCM_S16LE:

        case AV_CODEC_ID_PCM_ALAW:

        case AV_CODEC_ID_PCM_MULAW:

            aiff->block_duration = 1;

            break;

        case AV_CODEC_ID_ADPCM_IMA_QT:

            par->block_align = 34 * par->channels;

            break;

        case AV_CODEC_ID_MACE3:

            par->block_align = 2 * par->channels;

            break;

        case AV_CODEC_ID_ADPCM_G726LE:

            par->bits_per_coded_sample = 5;

        case AV_CODEC_ID_ADPCM_IMA_WS:

        case AV_CODEC_ID_ADPCM_G722:

        case AV_CODEC_ID_MACE6:

        case AV_CODEC_ID_SDX2_DPCM:

            par->block_align = 1 * par->channels;

            break;

        case AV_CODEC_ID_GSM:

            par->block_align = 33;

            break;

        default:

            aiff->block_duration = 1;

            break;

        }

        if (par->block_align > 0)

            aiff->block_duration = av_get_audio_frame_duration2(par,

                                                                par->block_align);

    }



    /* Block align needs to be computed in all cases, as the definition

     * is specific to applications -> here we use the WAVE format definition */

    if (!par->block_align)

        par->block_align = (av_get_bits_per_sample(par->codec_id) * par->channels) >> 3;



    if (aiff->block_duration) {

        par->bit_rate = par->sample_rate * (par->block_align << 3) /

                        aiff->block_duration;

    }



    /* Chunk is over */

    if (size)

        avio_skip(pb, size);



    return num_frames;

}

static bool run_poll_handlers_once(AioContext *ctx)

{

    bool progress = false;

    AioHandler *node;



    QLIST_FOREACH_RCU(node, &ctx->aio_handlers, node) {

        if (!node->deleted && node->io_poll &&

            aio_node_check(ctx, node->is_external) &&

            node->io_poll(node->opaque)) {

            progress = true;

        }



        /* Caller handles freeing deleted nodes.  Don't do it here. */

    }



    return progress;

}

static coroutine_fn int sd_co_writev(BlockDriverState *bs, int64_t sector_num,

                        int nb_sectors, QEMUIOVector *qiov)

{

    SheepdogAIOCB *acb;

    int ret;



    if (bs->growable && sector_num + nb_sectors > bs->total_sectors) {

        ret = sd_truncate(bs, (sector_num + nb_sectors) * BDRV_SECTOR_SIZE);

        if (ret < 0) {

            return ret;

        }

        bs->total_sectors = sector_num + nb_sectors;

    }



    acb = sd_aio_setup(bs, qiov, sector_num, nb_sectors);

    acb->aio_done_func = sd_write_done;

    acb->aiocb_type = AIOCB_WRITE_UDATA;



    ret = sd_co_rw_vector(acb);

    if (ret <= 0) {

        qemu_aio_release(acb);

        return ret;

    }



    qemu_coroutine_yield();



    return acb->ret;

}

static int kvm_set_user_memory_region(KVMState *s, KVMSlot *slot)

{

    struct kvm_userspace_memory_region mem;



    mem.slot = slot->slot;

    mem.guest_phys_addr = slot->start_addr;

    mem.userspace_addr = (unsigned long)slot->ram;

    mem.flags = slot->flags;

    if (s->migration_log) {

        mem.flags |= KVM_MEM_LOG_DIRTY_PAGES;

    }

    if (mem.flags & KVM_MEM_READONLY) {

        /* Set the slot size to 0 before setting the slot to the desired

         * value. This is needed based on KVM commit 75d61fbc. */

        mem.memory_size = 0;

        kvm_vm_ioctl(s, KVM_SET_USER_MEMORY_REGION, &mem);

    }

    mem.memory_size = slot->memory_size;

    return kvm_vm_ioctl(s, KVM_SET_USER_MEMORY_REGION, &mem);

}

static void rtas_set_tce_bypass(sPAPREnvironment *spapr, uint32_t token,

                                uint32_t nargs, target_ulong args,

                                uint32_t nret, target_ulong rets)

{

    VIOsPAPRBus *bus = spapr->vio_bus;

    VIOsPAPRDevice *dev;

    uint32_t unit, enable;



    if (nargs != 2) {

        rtas_st(rets, 0, -3);

        return;

    }

    unit = rtas_ld(args, 0);

    enable = rtas_ld(args, 1);

    dev = spapr_vio_find_by_reg(bus, unit);

    if (!dev) {

        rtas_st(rets, 0, -3);

        return;

    }

    if (enable) {

        dev->flags |= VIO_PAPR_FLAG_DMA_BYPASS;

    } else {

        dev->flags &= ~VIO_PAPR_FLAG_DMA_BYPASS;

    }



    rtas_st(rets, 0, 0);

}

int qcow2_alloc_cluster_offset(BlockDriverState *bs, uint64_t offset,

    int n_start, int n_end, int *num, QCowL2Meta *m)

{

    BDRVQcowState *s = bs->opaque;

    int l2_index, ret;

    uint64_t l2_offset, *l2_table;

    int64_t cluster_offset;

    unsigned int nb_clusters, i = 0;

    QCowL2Meta *old_alloc;



    ret = get_cluster_table(bs, offset, &l2_table, &l2_offset, &l2_index);

    if (ret < 0) {

        return ret;

    }



again:

    nb_clusters = size_to_clusters(s, n_end << 9);



    nb_clusters = MIN(nb_clusters, s->l2_size - l2_index);



    cluster_offset = be64_to_cpu(l2_table[l2_index]);



    /* We keep all QCOW_OFLAG_COPIED clusters */



    if (cluster_offset & QCOW_OFLAG_COPIED) {

        nb_clusters = count_contiguous_clusters(nb_clusters, s->cluster_size,

                &l2_table[l2_index], 0, 0);



        cluster_offset &= ~QCOW_OFLAG_COPIED;

        m->nb_clusters = 0;



        goto out;

    }



    /* for the moment, multiple compressed clusters are not managed */



    if (cluster_offset & QCOW_OFLAG_COMPRESSED)

        nb_clusters = 1;



    /* how many available clusters ? */



    while (i < nb_clusters) {

        i += count_contiguous_clusters(nb_clusters - i, s->cluster_size,

                &l2_table[l2_index], i, 0);

        if ((i >= nb_clusters) || be64_to_cpu(l2_table[l2_index + i])) {

            break;

        }



        i += count_contiguous_free_clusters(nb_clusters - i,

                &l2_table[l2_index + i]);

        if (i >= nb_clusters) {

            break;

        }



        cluster_offset = be64_to_cpu(l2_table[l2_index + i]);



        if ((cluster_offset & QCOW_OFLAG_COPIED) ||

                (cluster_offset & QCOW_OFLAG_COMPRESSED))

            break;

    }

    assert(i <= nb_clusters);

    nb_clusters = i;



    /*

     * Check if there already is an AIO write request in flight which allocates

     * the same cluster. In this case we need to wait until the previous

     * request has completed and updated the L2 table accordingly.

     */

    QLIST_FOREACH(old_alloc, &s->cluster_allocs, next_in_flight) {



        uint64_t end_offset = offset + nb_clusters * s->cluster_size;

        uint64_t old_offset = old_alloc->offset;

        uint64_t old_end_offset = old_alloc->offset +

            old_alloc->nb_clusters * s->cluster_size;



        if (end_offset < old_offset || offset > old_end_offset) {

            /* No intersection */

        } else {

            if (offset < old_offset) {

                /* Stop at the start of a running allocation */

                nb_clusters = (old_offset - offset) >> s->cluster_bits;

            } else {

                nb_clusters = 0;

            }



            if (nb_clusters == 0) {

                /* Wait for the dependency to complete. We need to recheck

                 * the free/allocated clusters when we continue. */

                qemu_co_mutex_unlock(&s->lock);

                qemu_co_queue_wait(&old_alloc->dependent_requests);

                qemu_co_mutex_lock(&s->lock);

                goto again;

            }

        }

    }



    if (!nb_clusters) {

        abort();

    }



    QLIST_INSERT_HEAD(&s->cluster_allocs, m, next_in_flight);



    /* allocate a new cluster */



    cluster_offset = qcow2_alloc_clusters(bs, nb_clusters * s->cluster_size);

    if (cluster_offset < 0) {

        ret = cluster_offset;

        goto fail;

    }



    /* save info needed for meta data update */

    m->offset = offset;

    m->n_start = n_start;

    m->nb_clusters = nb_clusters;



out:

    ret = qcow2_cache_put(bs, s->l2_table_cache, (void**) &l2_table);

    if (ret < 0) {

        goto fail_put;

    }



    m->nb_available = MIN(nb_clusters << (s->cluster_bits - 9), n_end);

    m->cluster_offset = cluster_offset;



    *num = m->nb_available - n_start;



    return 0;



fail:

    qcow2_cache_put(bs, s->l2_table_cache, (void**) &l2_table);

fail_put:

    QLIST_REMOVE(m, next_in_flight);

    return ret;

}

static int bmp_parse(AVCodecParserContext *s, AVCodecContext *avctx,

                     const uint8_t **poutbuf, int *poutbuf_size,

                     const uint8_t *buf, int buf_size)

{

    BMPParseContext *bpc = s->priv_data;

    uint64_t state = bpc->pc.state64;

    int next = END_NOT_FOUND;

    int i = 0;



    *poutbuf_size = 0;



restart:

    if (bpc->pc.frame_start_found <= 2+4+4) {

        for (; i < buf_size; i++) {

            state = (state << 8) | buf[i];

            if (bpc->pc.frame_start_found == 0) {

                if ((state >> 48) == (('B' << 8) | 'M')) {

                    bpc->fsize = av_bswap32(state >> 16);

                    bpc->pc.frame_start_found = 1;

                }

            } else if (bpc->pc.frame_start_found == 2+4+4) {

//                 unsigned hsize = av_bswap32(state>>32);

                unsigned ihsize = av_bswap32(state);

                if (ihsize < 12 || ihsize > 200) {

                    bpc->pc.frame_start_found = 0;

                    continue;

                }

                bpc->pc.frame_start_found++;

                bpc->remaining_size = bpc->fsize + i - 17;



                if (bpc->pc.index + i > 17) {

                    next = i - 17;

                    state = 0;

                    break;

                } else {

                    bpc->pc.state64 = 0;

                    goto restart;

                }

            } else if (bpc->pc.frame_start_found)

                bpc->pc.frame_start_found++;

        }

        bpc->pc.state64 = state;

    } else {

        if (bpc->remaining_size) {

            i = FFMIN(bpc->remaining_size, buf_size);

            bpc->remaining_size -= i;

            if (bpc->remaining_size)

                goto flush;



            bpc->pc.frame_start_found = 0;

            goto restart;

        }

    }



flush:

    if (ff_combine_frame(&bpc->pc, next, &buf, &buf_size) < 0)

        return buf_size;



    if (next != END_NOT_FOUND && next < 0)

        bpc->pc.frame_start_found = FFMAX(bpc->pc.frame_start_found - i - 1, 0);

    else

        bpc->pc.frame_start_found = 0;



    *poutbuf      = buf;

    *poutbuf_size = buf_size;

    return next;

}

