static uint64_t icp_pic_read(void *opaque, target_phys_addr_t offset,

                             unsigned size)

{

    icp_pic_state *s = (icp_pic_state *)opaque;



    switch (offset >> 2) {

    case 0: /* IRQ_STATUS */

        return s->level & s->irq_enabled;

    case 1: /* IRQ_RAWSTAT */

        return s->level;

    case 2: /* IRQ_ENABLESET */

        return s->irq_enabled;

    case 4: /* INT_SOFTSET */

        return s->level & 1;

    case 8: /* FRQ_STATUS */

        return s->level & s->fiq_enabled;

    case 9: /* FRQ_RAWSTAT */

        return s->level;

    case 10: /* FRQ_ENABLESET */

        return s->fiq_enabled;

    case 3: /* IRQ_ENABLECLR */

    case 5: /* INT_SOFTCLR */

    case 11: /* FRQ_ENABLECLR */

    default:

        printf ("icp_pic_read: Bad register offset 0x%x\n", (int)offset);

        return 0;

    }

}

static int transcode_subtitles(InputStream *ist, AVPacket *pkt, int *got_output)

{

    AVSubtitle subtitle;

    int i, ret = avcodec_decode_subtitle2(ist->dec_ctx,

                                          &subtitle, got_output, pkt);

    if (ret < 0)

        return ret;

    if (!*got_output)

        return ret;



    ist->frames_decoded++;



    for (i = 0; i < nb_output_streams; i++) {

        OutputStream *ost = output_streams[i];



        if (!check_output_constraints(ist, ost) || !ost->encoding_needed)

            continue;



        do_subtitle_out(output_files[ost->file_index]->ctx, ost, ist, &subtitle, pkt->pts);

    }



    avsubtitle_free(&subtitle);

    return ret;

}

static void noise(uint8_t *dst, const uint8_t *src,

                  int dst_linesize, int src_linesize,

                  int width, int start, int end, NoiseContext *n, int comp)

{

    FilterParams *p = &n->param[comp];

    int8_t *noise = p->noise;

    const int flags = p->flags;

    AVLFG *lfg = &p->lfg;

    int shift, y;



    if (!noise) {

        if (dst != src)

            av_image_copy_plane(dst, dst_linesize, src, src_linesize, width, end - start);

        return;

    }



    for (y = start; y < end; y++) {

        if (flags & NOISE_TEMPORAL)

            shift = av_lfg_get(lfg) & (MAX_SHIFT - 1);

        else

            shift = n->rand_shift[y];



        if (flags & NOISE_AVERAGED) {

            n->line_noise_avg(dst, src, width, p->prev_shift[y]);

            p->prev_shift[y][shift & 3] = noise + shift;

        } else {

            n->line_noise(dst, src, noise, width, shift);

        }

        dst += dst_linesize;

        src += src_linesize;

    }

}

