static inline void RENAME(LEToUV)(uint8_t *dstU, uint8_t *dstV, const uint8_t *src1, const uint8_t *src2, long width, uint32_t *unused)

{

#if COMPILE_TEMPLATE_MMX

    __asm__ volatile(

        "mov                    %0, %%"REG_a"       \n\t"

        "1:                                         \n\t"

        "movq    (%1, %%"REG_a",2), %%mm0           \n\t"

        "movq   8(%1, %%"REG_a",2), %%mm1           \n\t"

        "movq    (%2, %%"REG_a",2), %%mm2           \n\t"

        "movq   8(%2, %%"REG_a",2), %%mm3           \n\t"

        "psrlw                  $8, %%mm0           \n\t"

        "psrlw                  $8, %%mm1           \n\t"

        "psrlw                  $8, %%mm2           \n\t"

        "psrlw                  $8, %%mm3           \n\t"

        "packuswb            %%mm1, %%mm0           \n\t"

        "packuswb            %%mm3, %%mm2           \n\t"

        "movq                %%mm0, (%3, %%"REG_a") \n\t"

        "movq                %%mm2, (%4, %%"REG_a") \n\t"

        "add                    $8, %%"REG_a"       \n\t"

        " js                    1b                  \n\t"

        : : "g" ((x86_reg)-width), "r" (src1+width*2), "r" (src2+width*2), "r" (dstU+width), "r" (dstV+width)

        : "%"REG_a

    );

#else

    int i;

    // FIXME I don't think this code is right for YUV444/422, since then h is not subsampled so

    // we need to skip each second pixel. Same for BEToUV.

    for (i=0; i<width; i++) {

        dstU[i]= src1[2*i + 1];

        dstV[i]= src2[2*i + 1];

    }

#endif

}

static int dmg_read_resource_fork(BlockDriverState *bs, DmgHeaderState *ds,

                                  uint64_t info_begin, uint64_t info_length)

{

    BDRVDMGState *s = bs->opaque;

    int ret;

    uint32_t count, rsrc_data_offset;

    uint8_t *buffer = NULL;

    uint64_t info_end;

    uint64_t offset;



    /* read offset from begin of resource fork (info_begin) to resource data */

    ret = read_uint32(bs, info_begin, &rsrc_data_offset);

    if (ret < 0) {

        goto fail;

    } else if (rsrc_data_offset > info_length) {

        ret = -EINVAL;

        goto fail;

    }



    /* read length of resource data */

    ret = read_uint32(bs, info_begin + 8, &count);

    if (ret < 0) {

        goto fail;

    } else if (count == 0 || rsrc_data_offset + count > info_length) {

        ret = -EINVAL;

        goto fail;

    }



    /* begin of resource data (consisting of one or more resources) */

    offset = info_begin + rsrc_data_offset;



    /* end of resource data (there is possibly a following resource map

     * which will be ignored). */

    info_end = offset + count;



    /* read offsets (mish blocks) from one or more resources in resource data */

    while (offset < info_end) {

        /* size of following resource */

        ret = read_uint32(bs, offset, &count);

        if (ret < 0) {

            goto fail;

        } else if (count == 0) {

            ret = -EINVAL;

            goto fail;

        }

        offset += 4;



        buffer = g_realloc(buffer, count);

        ret = bdrv_pread(bs->file, offset, buffer, count);

        if (ret < 0) {

            goto fail;

        }



        ret = dmg_read_mish_block(s, ds, buffer, count);

        if (ret < 0) {

            goto fail;

        }

        /* advance offset by size of resource */

        offset += count;

    }

    ret = 0;



fail:

    g_free(buffer);

    return ret;

}

void pci_bus_reset(PCIBus *bus)

{

