void av_log_default_callback(void* ptr, int level, const char* fmt, va_list vl)

{

    static int print_prefix = 1;

    static int count;

    static char prev[LINE_SZ];

    AVBPrint part[4];

    char line[LINE_SZ];

    static int is_atty;

    int type[2];

    unsigned tint = 0;



    if (level >= 0) {

        tint = level & 0xff00;

        level &= 0xff;

    }



    if (level > av_log_level)

        return;

#if HAVE_PTHREADS

    pthread_mutex_lock(&mutex);

#endif



    format_line(ptr, level, fmt, vl, part, &print_prefix, type);

    snprintf(line, sizeof(line), "%s%s%s%s", part[0].str, part[1].str, part[2].str, part[3].str);



#if HAVE_ISATTY

    if (!is_atty)

        is_atty = isatty(2) ? 1 : -1;

#endif



    if (print_prefix && (flags & AV_LOG_SKIP_REPEATED) && !strcmp(line, prev) &&

        *line && line[strlen(line) - 1] != '\r'){

        count++;

        if (is_atty == 1)

            fprintf(stderr, "    Last message repeated %d times\r", count);

        goto end;

    }

    if (count > 0) {

        fprintf(stderr, "    Last message repeated %d times\n", count);

        count = 0;

    }

    strcpy(prev, line);

    sanitize(part[0].str);

    colored_fputs(type[0], 0, part[0].str);

    sanitize(part[1].str);

    colored_fputs(type[1], 0, part[1].str);

    sanitize(part[2].str);

    colored_fputs(av_clip(level >> 3, 0, NB_LEVELS - 1), tint >> 8, part[2].str);

    sanitize(part[3].str);

    colored_fputs(av_clip(level >> 3, 0, NB_LEVELS - 1), tint >> 8, part[3].str);



#if CONFIG_VALGRIND_BACKTRACE

    if (level <= BACKTRACE_LOGLEVEL)

        VALGRIND_PRINTF_BACKTRACE("%s", "");

#endif

end:

    av_bprint_finalize(part+3, NULL);

#if HAVE_PTHREADS

    pthread_mutex_unlock(&mutex);

#endif

}

static void setup_frame(int sig, struct target_sigaction * ka,

                        target_sigset_t *set, CPUMIPSState *regs)

{

    struct sigframe *frame;

    abi_ulong frame_addr;

    int i;



    frame_addr = get_sigframe(ka, regs, sizeof(*frame));

    if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 0))

	goto give_sigsegv;



    install_sigtramp(frame->sf_code, TARGET_NR_sigreturn);



    setup_sigcontext(regs, &frame->sf_sc);



    for(i = 0; i < TARGET_NSIG_WORDS; i++) {

	if(__put_user(set->sig[i], &frame->sf_mask.sig[i]))

	    goto give_sigsegv;

    }



    /*

    * Arguments to signal handler:

    *

    *   a0 = signal number

    *   a1 = 0 (should be cause)

    *   a2 = pointer to struct sigcontext

    *

    * $25 and PC point to the signal handler, $29 points to the

    * struct sigframe.

    */

    regs->active_tc.gpr[ 4] = sig;

    regs->active_tc.gpr[ 5] = 0;

    regs->active_tc.gpr[ 6] = frame_addr + offsetof(struct sigframe, sf_sc);

    regs->active_tc.gpr[29] = frame_addr;

    regs->active_tc.gpr[31] = frame_addr + offsetof(struct sigframe, sf_code);

    /* The original kernel code sets CP0_EPC to the handler

    * since it returns to userland using eret

    * we cannot do this here, and we must set PC directly */

    regs->active_tc.PC = regs->active_tc.gpr[25] = ka->_sa_handler;

    mips_set_hflags_isa_mode_from_pc(regs);

    unlock_user_struct(frame, frame_addr, 1);

    return;



give_sigsegv:

    unlock_user_struct(frame, frame_addr, 1);

    force_sig(TARGET_SIGSEGV/*, current*/);

}

static void apply_window_mp3(float *in, float *win, int *unused, float *out,

                             int incr)

{

    LOCAL_ALIGNED_16(float, suma, [17]);

    LOCAL_ALIGNED_16(float, sumb, [17]);

    LOCAL_ALIGNED_16(float, sumc, [17]);

    LOCAL_ALIGNED_16(float, sumd, [17]);



    float sum;



    /* copy to avoid wrap */

    memcpy(in + 512, in, 32 * sizeof(*in));



    apply_window(in + 16, win     , win + 512, suma, sumc, 16);

    apply_window(in + 32, win + 48, win + 640, sumb, sumd, 16);



    SUM8(MACS, suma[0], win + 32, in + 48);



    sumc[ 0] = 0;

    sumb[16] = 0;

    sumd[16] = 0;



#define SUMS(suma, sumb, sumc, sumd, out1, out2)               \

            "movups " #sumd "(%4),       %%xmm0          \n\t" \

            "shufps         $0x1b,       %%xmm0, %%xmm0  \n\t" \

            "subps  " #suma "(%1),       %%xmm0          \n\t" \

            "movaps        %%xmm0," #out1 "(%0)          \n\t" \

\

            "movups " #sumc "(%3),       %%xmm0          \n\t" \

            "shufps         $0x1b,       %%xmm0, %%xmm0  \n\t" \

            "addps  " #sumb "(%2),       %%xmm0          \n\t" \

            "movaps        %%xmm0," #out2 "(%0)          \n\t"



    if (incr == 1) {

        __asm__ volatile(

            SUMS( 0, 48,  4, 52,  0, 112)

            SUMS(16, 32, 20, 36, 16,  96)

            SUMS(32, 16, 36, 20, 32,  80)

            SUMS(48,  0, 52,  4, 48,  64)



            :"+&r"(out)

            :"r"(&suma[0]), "r"(&sumb[0]), "r"(&sumc[0]), "r"(&sumd[0])

            :"memory"

            );

        out += 16*incr;

    } else {

        int j;

        float *out2 = out + 32 * incr;

        out[0  ]  = -suma[   0];

        out += incr;

        out2 -= incr;

        for(j=1;j<16;j++) {

            *out  = -suma[   j] + sumd[16-j];

            *out2 =  sumb[16-j] + sumc[   j];

            out  += incr;

            out2 -= incr;

        }

    }



    sum = 0;

    SUM8(MLSS, sum, win + 16 + 32, in + 32);

    *out = sum;

}

void bdrv_set_backing_hd(BlockDriverState *bs, BlockDriverState *backing_hd)

{



    if (bs->backing_hd) {

        assert(bs->backing_blocker);

        bdrv_op_unblock_all(bs->backing_hd, bs->backing_blocker);

    } else if (backing_hd) {

        error_setg(&bs->backing_blocker,

                   "device is used as backing hd of '%s'",

                   bdrv_get_device_name(bs));

    }



    bs->backing_hd = backing_hd;

    if (!backing_hd) {

        error_free(bs->backing_blocker);

        bs->backing_blocker = NULL;

        goto out;

    }

    bs->open_flags &= ~BDRV_O_NO_BACKING;

    pstrcpy(bs->backing_file, sizeof(bs->backing_file), backing_hd->filename);

    pstrcpy(bs->backing_format, sizeof(bs->backing_format),

            backing_hd->drv ? backing_hd->drv->format_name : "");



    bdrv_op_block_all(bs->backing_hd, bs->backing_blocker);

    /* Otherwise we won't be able to commit due to check in bdrv_commit */

    bdrv_op_unblock(bs->backing_hd, BLOCK_OP_TYPE_COMMIT,

                    bs->backing_blocker);

out:

    bdrv_refresh_limits(bs, NULL);

}

