static void gdb_vm_stopped(void *opaque, int reason)

{

    GDBState *s = opaque;

    char buf[256];

    const char *type;

    int ret;



    if (s->state == RS_SYSCALL)

        return;



    /* disable single step if it was enable */

    cpu_single_step(s->env, 0);



    if (reason == EXCP_DEBUG) {

        if (s->env->watchpoint_hit) {

            switch (s->env->watchpoint_hit->flags & BP_MEM_ACCESS) {

            case BP_MEM_READ:

                type = "r";

                break;

            case BP_MEM_ACCESS:

                type = "a";

                break;

            default:

                type = "";

                break;

            }

            snprintf(buf, sizeof(buf), "T%02x%swatch:" TARGET_FMT_lx ";",

                     SIGTRAP, type, s->env->watchpoint_hit->vaddr);

            put_packet(s, buf);

            s->env->watchpoint_hit = NULL;

            return;

        }

	tb_flush(s->env);

        ret = SIGTRAP;

    } else if (reason == EXCP_INTERRUPT) {

        ret = SIGINT;

    } else {

        ret = 0;

    }

    snprintf(buf, sizeof(buf), "S%02x", ret);

    put_packet(s, buf);

}

static void draw_axis_yuv(AVFrame *out, AVFrame *axis, const ColorFloat *c, int off)

{

    int fmt = out->format, x, y, yh, w = axis->width, h = axis->height;

    int offh = (fmt == AV_PIX_FMT_YUV420P) ? off / 2 : off;

    float a, rcp_255 = 1.0f / 255.0f;

    uint8_t *vy = out->data[0], *vu = out->data[1], *vv = out->data[2];

    uint8_t *vay = axis->data[0], *vau = axis->data[1], *vav = axis->data[2], *vaa = axis->data[3];

    int lsy = out->linesize[0], lsu = out->linesize[1], lsv = out->linesize[2];

    int lsay = axis->linesize[0], lsau = axis->linesize[1], lsav = axis->linesize[2], lsaa = axis->linesize[3];

    uint8_t *lpy, *lpu, *lpv, *lpay, *lpau, *lpav, *lpaa;



    for (y = 0; y < h; y += 2) {

        yh = (fmt == AV_PIX_FMT_YUV420P) ? y / 2 : y;

        lpy = vy + (off + y) * lsy;

        lpu = vu + (offh + yh) * lsu;

        lpv = vv + (offh + yh) * lsv;

        lpay = vay + y * lsay;

        lpau = vau + yh * lsau;

        lpav = vav + yh * lsav;

        lpaa = vaa + y * lsaa;

        for (x = 0; x < w; x += 2) {

            a = rcp_255 * (*lpaa++);

            *lpy++ = a * (*lpay++) + (1.0f - a) * c[x].yuv.y + 0.5f;

            *lpu++ = a * (*lpau++) + (1.0f - a) * c[x].yuv.u + 0.5f;

            *lpv++ = a * (*lpav++) + (1.0f - a) * c[x].yuv.v + 0.5f;

            /* u and v are skipped on yuv422p and yuv420p */

            a = rcp_255 * (*lpaa++);

            *lpy++ = a * (*lpay++) + (1.0f - a) * c[x+1].yuv.y + 0.5f;

            if (fmt == AV_PIX_FMT_YUV444P) {

                *lpu++ = a * (*lpau++) + (1.0f - a) * c[x+1].yuv.u + 0.5f;

                *lpv++ = a * (*lpav++) + (1.0f - a) * c[x+1].yuv.v + 0.5f;

            }

        }



        lpy = vy + (off + y + 1) * lsy;

        lpu = vu + (off + y + 1) * lsu;

        lpv = vv + (off + y + 1) * lsv;

        lpay = vay + (y + 1) * lsay;

        lpau = vau + (y + 1) * lsau;

        lpav = vav + (y + 1) * lsav;

        lpaa = vaa + (y + 1) * lsaa;

        for (x = 0; x < out->width; x += 2) {

            /* u and v are skipped on yuv420p */

            a = rcp_255 * (*lpaa++);

            *lpy++ = a * (*lpay++) + (1.0f - a) * c[x].yuv.y + 0.5f;

            if (fmt != AV_PIX_FMT_YUV420P) {

                *lpu++ = a * (*lpau++) + (1.0f - a) * c[x].yuv.u + 0.5f;

                *lpv++ = a * (*lpav++) + (1.0f - a) * c[x].yuv.v + 0.5f;

            }

            /* u and v are skipped on yuv422p and yuv420p */

            a = rcp_255 * (*lpaa++);

            *lpy++ = a * (*lpay++) + (1.0f - a) * c[x+1].yuv.y + 0.5f;

            if (fmt == AV_PIX_FMT_YUV444P) {

                *lpu++ = a * (*lpau++) + (1.0f - a) * c[x+1].yuv.u + 0.5f;

                *lpv++ = a * (*lpav++) + (1.0f - a) * c[x+1].yuv.v + 0.5f;

            }

        }

    }

}

static void tcg_out_qemu_st(TCGContext *s, const TCGArg *args,

                            int opc)

{

    int addr_regl, addr_reg1, addr_meml;

    int data_regl, data_regh, data_reg1, data_reg2;

    int mem_index, s_bits;

#if defined(CONFIG_SOFTMMU)

    uint8_t *label1_ptr, *label2_ptr;

    int sp_args;

#endif

#if TARGET_LONG_BITS == 64

# if defined(CONFIG_SOFTMMU)

    uint8_t *label3_ptr;

# endif

    int addr_regh, addr_reg2, addr_memh;

#endif



    data_regl = *args++;

    if (opc == 3) {

        data_regh = *args++;

#if defined(TCG_TARGET_WORDS_BIGENDIAN)

        data_reg1 = data_regh;

        data_reg2 = data_regl;

#else

        data_reg1 = data_regl;

        data_reg2 = data_regh;

#endif

    } else {

        data_reg1 = data_regl;

        data_reg2 = 0;

        data_regh = 0;

    }

    addr_regl = *args++;

#if TARGET_LONG_BITS == 64

    addr_regh = *args++;

# if defined(TCG_TARGET_WORDS_BIGENDIAN)

    addr_reg1 = addr_regh;

    addr_reg2 = addr_regl;

    addr_memh = 0;

    addr_meml = 4;

# else

    addr_reg1 = addr_regl;

    addr_reg2 = addr_regh;

    addr_memh = 4;

    addr_meml = 0;

# endif

#else

    addr_reg1 = addr_regl;

    addr_meml = 0;

#endif

    mem_index = *args;

    s_bits = opc;



#if defined(CONFIG_SOFTMMU)

    tcg_out_opc_sa(s, OPC_SRL, TCG_REG_A0, addr_regl, TARGET_PAGE_BITS - CPU_TLB_ENTRY_BITS);

    tcg_out_opc_imm(s, OPC_ANDI, TCG_REG_A0, TCG_REG_A0, (CPU_TLB_SIZE - 1) << CPU_TLB_ENTRY_BITS);

    tcg_out_opc_reg(s, OPC_ADDU, TCG_REG_A0, TCG_REG_A0, TCG_AREG0);

    tcg_out_opc_imm(s, OPC_LW, TCG_REG_AT, TCG_REG_A0,

                    offsetof(CPUState, tlb_table[mem_index][0].addr_write) + addr_meml);

    tcg_out_movi(s, TCG_TYPE_I32, TCG_REG_T0, TARGET_PAGE_MASK | ((1 << s_bits) - 1));

    tcg_out_opc_reg(s, OPC_AND, TCG_REG_T0, TCG_REG_T0, addr_regl);



# if TARGET_LONG_BITS == 64

    label3_ptr = s->code_ptr;

    tcg_out_opc_br(s, OPC_BNE, TCG_REG_T0, TCG_REG_AT);

    tcg_out_nop(s);



    tcg_out_opc_imm(s, OPC_LW, TCG_REG_AT, TCG_REG_A0,

                    offsetof(CPUState, tlb_table[mem_index][0].addr_write) + addr_memh);



    label1_ptr = s->code_ptr;

    tcg_out_opc_br(s, OPC_BEQ, addr_regh, TCG_REG_AT);

    tcg_out_nop(s);



    reloc_pc16(label3_ptr, (tcg_target_long) s->code_ptr);

# else

    label1_ptr = s->code_ptr;

    tcg_out_opc_br(s, OPC_BEQ, TCG_REG_T0, TCG_REG_AT);

    tcg_out_nop(s);

# endif



    /* slow path */

    sp_args = TCG_REG_A0;

    tcg_out_mov(s, sp_args++, addr_reg1);

# if TARGET_LONG_BITS == 64

    tcg_out_mov(s, sp_args++, addr_reg2);

# endif

    switch(opc) {

    case 0:

        tcg_out_opc_imm(s, OPC_ANDI, sp_args++, data_reg1, 0xff);

        break;

    case 1:

        tcg_out_opc_imm(s, OPC_ANDI, sp_args++, data_reg1, 0xffff);

        break;

    case 2:

        tcg_out_mov(s, sp_args++, data_reg1);

        break;

    case 3:

        sp_args = (sp_args + 1) & ~1;

        tcg_out_mov(s, sp_args++, data_reg1);

        tcg_out_mov(s, sp_args++, data_reg2);

        break;

    default:

        tcg_abort();

    }

    if (sp_args > TCG_REG_A3) {

        /* Push mem_index on the stack */

        tcg_out_movi(s, TCG_TYPE_I32, TCG_REG_AT, mem_index);

        tcg_out_st(s, TCG_TYPE_I32, TCG_REG_AT, TCG_REG_SP, 16);

    } else {

        tcg_out_movi(s, TCG_TYPE_I32, sp_args, mem_index);

    }



    tcg_out_movi(s, TCG_TYPE_I32, TCG_REG_T9, (tcg_target_long)qemu_st_helpers[s_bits]);

    tcg_out_opc_reg(s, OPC_JALR, TCG_REG_RA, TCG_REG_T9, 0);

    tcg_out_nop(s);



    label2_ptr = s->code_ptr;

    tcg_out_opc_br(s, OPC_BEQ, TCG_REG_ZERO, TCG_REG_ZERO);

    tcg_out_nop(s);



    /* label1: fast path */

    reloc_pc16(label1_ptr, (tcg_target_long) s->code_ptr);



    tcg_out_opc_imm(s, OPC_LW, TCG_REG_A0, TCG_REG_A0,

                    offsetof(CPUState, tlb_table[mem_index][0].addend) + addr_meml);

    tcg_out_opc_reg(s, OPC_ADDU, TCG_REG_A0, TCG_REG_A0, addr_regl);

#else

    if (GUEST_BASE == (int16_t)GUEST_BASE) {

        tcg_out_opc_imm(s, OPC_ADDIU, TCG_REG_A0, addr_reg1, GUEST_BASE);

    } else {

        tcg_out_movi(s, TCG_TYPE_PTR, TCG_REG_A0, GUEST_BASE);

        tcg_out_opc_reg(s, OPC_ADDU, TCG_REG_A0, TCG_REG_A0, addr_reg1);

    }



#endif



    switch(opc) {

    case 0:

        tcg_out_opc_imm(s, OPC_SB, data_reg1, TCG_REG_A0, 0);

        break;

    case 1:

        if (TCG_NEED_BSWAP) {

            tcg_out_bswap16(s, TCG_REG_T0, data_reg1);

            tcg_out_opc_imm(s, OPC_SH, TCG_REG_T0, TCG_REG_A0, 0);

        } else {

            tcg_out_opc_imm(s, OPC_SH, data_reg1, TCG_REG_A0, 0);

        }

        break;

    case 2:

        if (TCG_NEED_BSWAP) {

            tcg_out_bswap32(s, TCG_REG_T0, data_reg1);

            tcg_out_opc_imm(s, OPC_SW, TCG_REG_T0, TCG_REG_A0, 0);

        } else {

            tcg_out_opc_imm(s, OPC_SW, data_reg1, TCG_REG_A0, 0);

        }

        break;

    case 3:

        if (TCG_NEED_BSWAP) {

            tcg_out_bswap32(s, TCG_REG_T0, data_reg2);

            tcg_out_opc_imm(s, OPC_SW, TCG_REG_T0, TCG_REG_A0, 0);

            tcg_out_bswap32(s, TCG_REG_T0, data_reg1);

            tcg_out_opc_imm(s, OPC_SW, TCG_REG_T0, TCG_REG_A0, 4);

        } else {

            tcg_out_opc_imm(s, OPC_SW, data_reg1, TCG_REG_A0, 0);

            tcg_out_opc_imm(s, OPC_SW, data_reg2, TCG_REG_A0, 4);

        }

        break;

    default:

        tcg_abort();

    }



#if defined(CONFIG_SOFTMMU)

    reloc_pc16(label2_ptr, (tcg_target_long) s->code_ptr);

#endif

}

static void truncpasses(Jpeg2000EncoderContext *s, Jpeg2000Tile *tile)

{

    int precno, compno, reslevelno, bandno, cblkno, lev;

    Jpeg2000CodingStyle *codsty = &s->codsty;



    for (compno = 0; compno < s->ncomponents; compno++){

        Jpeg2000Component *comp = tile->comp + compno;



        for (reslevelno = 0, lev = codsty->nreslevels-1; reslevelno < codsty->nreslevels; reslevelno++, lev--){

            Jpeg2000ResLevel *reslevel = comp->reslevel + reslevelno;



            for (precno = 0; precno < reslevel->num_precincts_x * reslevel->num_precincts_y; precno++){

                for (bandno = 0; bandno < reslevel->nbands ; bandno++){

                    int bandpos = bandno + (reslevelno > 0);

                    Jpeg2000Band *band = reslevel->band + bandno;

                    Jpeg2000Prec *prec = band->prec + precno;



                    for (cblkno = 0; cblkno < prec->nb_codeblocks_height * prec->nb_codeblocks_width; cblkno++){

                        Jpeg2000Cblk *cblk = prec->cblk + cblkno;



                        cblk->ninclpasses = getcut(cblk, s->lambda,

                                (int64_t)dwt_norms[codsty->transform][bandpos][lev] * (int64_t)band->i_stepsize >> 16);

                    }

                }

            }

        }

    }

}

void bdrv_error_action(BlockDriverState *bs, BlockErrorAction action,

                       bool is_read, int error)

{

    assert(error >= 0);



    if (action == BLOCK_ERROR_ACTION_STOP) {

        /* First set the iostatus, so that "info block" returns an iostatus

         * that matches the events raised so far (an additional error iostatus

         * is fine, but not a lost one).

         */

        bdrv_iostatus_set_err(bs, error);



        /* Then raise the request to stop the VM and the event.

         * qemu_system_vmstop_request_prepare has two effects.  First,

         * it ensures that the STOP event always comes after the

         * BLOCK_IO_ERROR event.  Second, it ensures that even if management

         * can observe the STOP event and do a "cont" before the STOP

         * event is issued, the VM will not stop.  In this case, vm_start()

         * also ensures that the STOP/RESUME pair of events is emitted.

         */

        qemu_system_vmstop_request_prepare();

        send_qmp_error_event(bs, action, is_read, error);

        qemu_system_vmstop_request(RUN_STATE_IO_ERROR);

    } else {

        send_qmp_error_event(bs, action, is_read, error);

    }

}

static void v9fs_wstat(void *opaque)

{

    int32_t fid;

    int err = 0;

    int16_t unused;

    V9fsStat v9stat;

    size_t offset = 7;

    struct stat stbuf;

    V9fsFidState *fidp;

    V9fsPDU *pdu = opaque;

    V9fsState *s = pdu->s;



    pdu_unmarshal(pdu, offset, "dwS", &fid, &unused, &v9stat);

    trace_v9fs_wstat(pdu->tag, pdu->id, fid,

                     v9stat.mode, v9stat.atime, v9stat.mtime);



    fidp = get_fid(pdu, fid);

    if (fidp == NULL) {

        err = -EINVAL;

        goto out_nofid;

    }

    /* do we need to sync the file? */

    if (donttouch_stat(&v9stat)) {

        err = v9fs_co_fsync(pdu, fidp, 0);

        goto out;

    }

    if (v9stat.mode != -1) {

        uint32_t v9_mode;

        err = v9fs_co_lstat(pdu, &fidp->path, &stbuf);

        if (err < 0) {

            goto out;

        }

        v9_mode = stat_to_v9mode(&stbuf);

        if ((v9stat.mode & P9_STAT_MODE_TYPE_BITS) !=

            (v9_mode & P9_STAT_MODE_TYPE_BITS)) {

            /* Attempting to change the type */

            err = -EIO;

            goto out;

        }

        err = v9fs_co_chmod(pdu, &fidp->path,

                            v9mode_to_mode(v9stat.mode,

                                           &v9stat.extension));

        if (err < 0) {

            goto out;

        }

    }

    if (v9stat.mtime != -1 || v9stat.atime != -1) {

        struct timespec times[2];

        if (v9stat.atime != -1) {

            times[0].tv_sec = v9stat.atime;

            times[0].tv_nsec = 0;

        } else {

            times[0].tv_nsec = UTIME_OMIT;

        }

        if (v9stat.mtime != -1) {

            times[1].tv_sec = v9stat.mtime;

            times[1].tv_nsec = 0;

        } else {

            times[1].tv_nsec = UTIME_OMIT;

        }

        err = v9fs_co_utimensat(pdu, &fidp->path, times);

        if (err < 0) {

            goto out;

        }

    }

    if (v9stat.n_gid != -1 || v9stat.n_uid != -1) {

        err = v9fs_co_chown(pdu, &fidp->path, v9stat.n_uid, v9stat.n_gid);

        if (err < 0) {

            goto out;

        }

    }

    if (v9stat.name.size != 0) {

        err = v9fs_complete_rename(pdu, fidp, -1, &v9stat.name);

        if (err < 0) {

            goto out;

        }

    }

    if (v9stat.length != -1) {

        err = v9fs_co_truncate(pdu, &fidp->path, v9stat.length);

        if (err < 0) {

            goto out;

        }

    }

    err = offset;

out:

    put_fid(pdu, fidp);

out_nofid:

    v9fs_stat_free(&v9stat);

    complete_pdu(s, pdu, err);

}

GList *g_list_insert_sorted_merged(GList *list, gpointer data,

                                   GCompareFunc func)

{

    GList *l, *next = NULL;

    Range *r, *nextr;



    if (!list) {

        list = g_list_insert_sorted(list, data, func);

        return list;

    }



    nextr = data;

    l = list;

    while (l && l != next && nextr) {

        r = l->data;

        if (ranges_can_merge(r, nextr)) {

            range_merge(r, nextr);

            l = g_list_remove_link(l, next);

            next = g_list_next(l);

            if (next) {

                nextr = next->data;

            } else {

                nextr = NULL;

            }

        } else {

            l = g_list_next(l);

        }

    }



    if (!l) {

        list = g_list_insert_sorted(list, data, func);

    }



    return list;

}

lookup_scalar(const OptsVisitor *ov, const char *name, Error **errp)

{

    if (ov->repeated_opts == NULL) {

        GQueue *list;



        /* the last occurrence of any QemuOpt takes effect when queried by name

         */

        list = lookup_distinct(ov, name, errp);

        return list ? g_queue_peek_tail(list) : NULL;

    }

    return g_queue_peek_head(ov->repeated_opts);

}

