int av_buffersrc_add_ref(AVFilterContext *buffer_filter,

                         AVFilterBufferRef *picref, int flags)

{

    BufferSourceContext *c = buffer_filter->priv;

    AVFilterLink *outlink = buffer_filter->outputs[0];

    AVFilterBufferRef *buf;

    int ret;



    if (!picref) {

        c->eof = 1;

        return 0;

    } else if (c->eof)

        return AVERROR(EINVAL);



    if (!av_fifo_space(c->fifo) &&

        (ret = av_fifo_realloc2(c->fifo, av_fifo_size(c->fifo) +

                                         sizeof(buf))) < 0)

        return ret;



    if (!(flags & AV_BUFFERSRC_FLAG_NO_CHECK_FORMAT)) {

        /* TODO reindent */

    if (picref->video->w != c->w || picref->video->h != c->h || picref->format != c->pix_fmt) {

        AVFilterContext *scale = buffer_filter->outputs[0]->dst;

        AVFilterLink *link;

        char scale_param[1024];



        av_log(buffer_filter, AV_LOG_INFO,

               "Buffer video input changed from size:%dx%d fmt:%s to size:%dx%d fmt:%s\n",

               c->w, c->h, av_pix_fmt_descriptors[c->pix_fmt].name,

               picref->video->w, picref->video->h, av_pix_fmt_descriptors[picref->format].name);



        if (!scale || strcmp(scale->filter->name, "scale")) {

            AVFilter *f = avfilter_get_by_name("scale");



            av_log(buffer_filter, AV_LOG_INFO, "Inserting scaler filter\n");

            if ((ret = avfilter_open(&scale, f, "Input equalizer")) < 0)

                return ret;



            c->scale = scale;



            snprintf(scale_param, sizeof(scale_param)-1, "%d:%d:%s", c->w, c->h, c->sws_param);

            if ((ret = avfilter_init_filter(scale, scale_param, NULL)) < 0) {

                return ret;

            }



            if ((ret = avfilter_insert_filter(buffer_filter->outputs[0], scale, 0, 0)) < 0) {

                return ret;

            }

            scale->outputs[0]->time_base = scale->inputs[0]->time_base;



            scale->outputs[0]->format= c->pix_fmt;

        } else if (!strcmp(scale->filter->name, "scale")) {

            snprintf(scale_param, sizeof(scale_param)-1, "%d:%d:%s",

                     scale->outputs[0]->w, scale->outputs[0]->h, c->sws_param);

            scale->filter->init(scale, scale_param, NULL);

        }



        c->pix_fmt = scale->inputs[0]->format = picref->format;

        c->w       = scale->inputs[0]->w      = picref->video->w;

        c->h       = scale->inputs[0]->h      = picref->video->h;



        link = scale->outputs[0];

        if ((ret =  link->srcpad->config_props(link)) < 0)

            return ret;

    }

    }



    if (flags & AV_BUFFERSRC_FLAG_NO_COPY) {

        buf = picref;

    } else {

    buf = avfilter_get_video_buffer(outlink, AV_PERM_WRITE,

                                    picref->video->w, picref->video->h);

    av_image_copy(buf->data, buf->linesize,

                  (void*)picref->data, picref->linesize,

                  picref->format, picref->video->w, picref->video->h);

    avfilter_copy_buffer_ref_props(buf, picref);



    }



    if ((ret = av_fifo_generic_write(c->fifo, &buf, sizeof(buf), NULL)) < 0) {

        if (buf != picref)

            avfilter_unref_buffer(buf);

        return ret;

    }

    c->nb_failed_requests = 0;



    return 0;

}

static inline void host_to_target_siginfo_noswap(target_siginfo_t *tinfo,

                                                 const siginfo_t *info)

{

    int sig = host_to_target_signal(info->si_signo);

    tinfo->si_signo = sig;

    tinfo->si_errno = 0;

    tinfo->si_code = info->si_code;



    if (sig == TARGET_SIGILL || sig == TARGET_SIGFPE || sig == TARGET_SIGSEGV

            || sig == TARGET_SIGBUS || sig == TARGET_SIGTRAP) {

        /* Should never come here, but who knows. The information for

           the target is irrelevant.  */

        tinfo->_sifields._sigfault._addr = 0;

    } else if (sig == TARGET_SIGIO) {

        tinfo->_sifields._sigpoll._band = info->si_band;

        tinfo->_sifields._sigpoll._fd = info->si_fd;

    } else if (sig == TARGET_SIGCHLD) {

        tinfo->_sifields._sigchld._pid = info->si_pid;

        tinfo->_sifields._sigchld._uid = info->si_uid;

        tinfo->_sifields._sigchld._status

                = host_to_target_waitstatus(info->si_status);

        tinfo->_sifields._sigchld._utime = info->si_utime;

        tinfo->_sifields._sigchld._stime = info->si_stime;

    } else if (sig >= TARGET_SIGRTMIN) {

        tinfo->_sifields._rt._pid = info->si_pid;

        tinfo->_sifields._rt._uid = info->si_uid;

        /* XXX: potential problem if 64 bit */

        tinfo->_sifields._rt._sigval.sival_ptr

                = (abi_ulong)(unsigned long)info->si_value.sival_ptr;

    }

}

static void fill_double_array(AVLFG *lfg, double *a, int len)

{

    int i;

    double bmg[2], stddev = 10.0, mean = 0.0;



    for (i = 0; i < len; i += 2) {

        av_bmg_get(lfg, bmg);

        a[i]     = bmg[0] * stddev + mean;

        a[i + 1] = bmg[1] * stddev + mean;

    }

}

static void dv_decode_ac(GetBitContext *gb, BlockInfo *mb, DCTELEM *block)

{

    int last_index = get_bits_size(gb);

    const uint8_t *scan_table = mb->scan_table;

    const uint8_t *shift_table = mb->shift_table;

    int pos = mb->pos;

    int partial_bit_count = mb->partial_bit_count;

    int level, pos1, run, vlc_len, index;



    OPEN_READER(re, gb);

    UPDATE_CACHE(re, gb);



    /* if we must parse a partial vlc, we do it here */

    if (partial_bit_count > 0) {

        re_cache = ((unsigned)re_cache >> partial_bit_count) |

	           (mb->partial_bit_buffer << (sizeof(re_cache)*8 - partial_bit_count));

	re_index -= partial_bit_count;

	mb->partial_bit_count = 0;

    }



    /* get the AC coefficients until last_index is reached */

    for(;;) {

#ifdef VLC_DEBUG

        printf("%2d: bits=%04x index=%d\n", pos, SHOW_UBITS(re, gb, 16), re_index);

#endif

        /* our own optimized GET_RL_VLC */

        index = NEG_USR32(re_cache, TEX_VLC_BITS);

	vlc_len = dv_rl_vlc[index].len;

        if (vlc_len < 0) {

            index = NEG_USR32((unsigned)re_cache << TEX_VLC_BITS, -vlc_len) + dv_rl_vlc[index].level;

            vlc_len = TEX_VLC_BITS - vlc_len;

        }

        level = dv_rl_vlc[index].level;

	run = dv_rl_vlc[index].run;



	/* gotta check if we're still within gb boundaries */

	if (re_index + vlc_len > last_index) {

	    /* should be < 16 bits otherwise a codeword could have been parsed */

	    mb->partial_bit_count = last_index - re_index;

	    mb->partial_bit_buffer = NEG_USR32(re_cache, mb->partial_bit_count);

	    re_index = last_index;

	    break;

	}

	re_index += vlc_len;



#ifdef VLC_DEBUG

	printf("run=%d level=%d\n", run, level);

#endif

	pos += run; 	

	if (pos >= 64)

	    break;



	if (level) {

            pos1 = scan_table[pos];

            block[pos1] = level << shift_table[pos1];

        } 



        UPDATE_CACHE(re, gb);

    }

    CLOSE_READER(re, gb);

    mb->pos = pos;

}

START_TEST(qdict_stress_test)

{

    size_t lines;

    char key[128];

    FILE *test_file;

    QDict *qdict;

    QString *value;

    const char *test_file_path = "qdict-test-data.txt";



    test_file = fopen(test_file_path, "r");

    fail_unless(test_file != NULL);



    // Create the dict

    qdict = qdict_new();

    fail_unless(qdict != NULL);



    // Add everything from the test file

    for (lines = 0;; lines++) {

        value = read_line(test_file, key);

        if (!value)

            break;



        qdict_put(qdict, key, value);

    }

    fail_unless(qdict_size(qdict) == lines);



    // Check if everything is really in there

    reset_file(test_file);

    for (;;) {

        const char *str1, *str2;



        value = read_line(test_file, key);

        if (!value)

            break;



        str1 = qstring_get_str(value);



        str2 = qdict_get_str(qdict, key);

        fail_unless(str2 != NULL);



        fail_unless(strcmp(str1, str2) == 0);



        QDECREF(value);

    }



    // Delete everything

    reset_file(test_file);

    for (;;) {

        value = read_line(test_file, key);

        if (!value)

            break;



        qdict_del(qdict, key);

        QDECREF(value);



        fail_unless(qdict_haskey(qdict, key) == 0);

    }

    fclose(test_file);



    fail_unless(qdict_size(qdict) == 0);

    QDECREF(qdict);

}

static int alac_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    ALACContext *alac = avctx->priv_data;

    enum RawDataBlockType element;

    int channels;

    int ch, ret, got_end;



    init_get_bits(&alac->gb, avpkt->data, avpkt->size * 8);



    got_end = 0;

    alac->nb_samples = 0;

    ch = 0;

    while (get_bits_left(&alac->gb) >= 3) {

        element = get_bits(&alac->gb, 3);

        if (element == TYPE_END) {

            got_end = 1;

            break;

        }

        if (element > TYPE_CPE && element != TYPE_LFE) {

            av_log(avctx, AV_LOG_ERROR, "syntax element unsupported: %d\n", element);

            return AVERROR_PATCHWELCOME;

        }



        channels = (element == TYPE_CPE) ? 2 : 1;

        if (ch + channels > alac->channels) {

            av_log(avctx, AV_LOG_ERROR, "invalid element channel count\n");

            return AVERROR_INVALIDDATA;

        }



        ret = decode_element(avctx, data,

                             alac_channel_layout_offsets[alac->channels - 1][ch],

                             channels);

        if (ret < 0 && get_bits_left(&alac->gb))

            return ret;



        ch += channels;

    }

    if (!got_end) {

        av_log(avctx, AV_LOG_ERROR, "no end tag found. incomplete packet.\n");

        return AVERROR_INVALIDDATA;

    }



    if (avpkt->size * 8 - get_bits_count(&alac->gb) > 8) {

        av_log(avctx, AV_LOG_ERROR, "Error : %d bits left\n",

               avpkt->size * 8 - get_bits_count(&alac->gb));

    }



    *got_frame_ptr   = 1;

    *(AVFrame *)data = alac->frame;



    return avpkt->size;

}

void kvm_physical_sync_dirty_bitmap(target_phys_addr_t start_addr, target_phys_addr_t end_addr)

{

    KVMState *s = kvm_state;

    KVMDirtyLog d;

    KVMSlot *mem = kvm_lookup_slot(s, start_addr);

    unsigned long alloc_size;

    ram_addr_t addr;

    target_phys_addr_t phys_addr = start_addr;



    dprintf("sync addr: %llx into %lx\n", start_addr, mem->phys_offset);

    if (mem == NULL) {

            fprintf(stderr, "BUG: %s: invalid parameters\n", __func__);

            return;

    }



    alloc_size = mem->memory_size >> TARGET_PAGE_BITS / sizeof(d.dirty_bitmap);

    d.dirty_bitmap = qemu_mallocz(alloc_size);



    d.slot = mem->slot;

    dprintf("slot %d, phys_addr %llx, uaddr: %llx\n",

            d.slot, mem->start_addr, mem->phys_offset);



    if (kvm_vm_ioctl(s, KVM_GET_DIRTY_LOG, &d) == -1) {

        dprintf("ioctl failed %d\n", errno);

        goto out;

    }



    phys_addr = start_addr;

    for (addr = mem->phys_offset; phys_addr < end_addr; phys_addr+= TARGET_PAGE_SIZE, addr += TARGET_PAGE_SIZE) {

        unsigned long *bitmap = (unsigned long *)d.dirty_bitmap;

        unsigned nr = (phys_addr - start_addr) >> TARGET_PAGE_BITS;

        unsigned word = nr / (sizeof(*bitmap) * 8);

        unsigned bit = nr % (sizeof(*bitmap) * 8);

        if ((bitmap[word] >> bit) & 1)

            cpu_physical_memory_set_dirty(addr);

    }

out:

    qemu_free(d.dirty_bitmap);

}

static void compute_pkt_fields(AVFormatContext *s, AVStream *st,

                               AVCodecParserContext *pc, AVPacket *pkt,

                               int64_t next_dts, int64_t next_pts)

{

    int num, den, presentation_delayed, delay, i;

    int64_t offset;

    AVRational duration;

    int onein_oneout = st->codec->codec_id != AV_CODEC_ID_H264 &&

                       st->codec->codec_id != AV_CODEC_ID_HEVC;



    if (s->flags & AVFMT_FLAG_NOFILLIN)

        return;



    if (st->codec->codec_type == AVMEDIA_TYPE_VIDEO && pkt->dts != AV_NOPTS_VALUE) {

        if (pkt->dts == pkt->pts && st->last_dts_for_order_check != AV_NOPTS_VALUE) {

            if (st->last_dts_for_order_check <= pkt->dts) {

                st->dts_ordered++;

            } else {

                av_log(s, st->dts_misordered ? AV_LOG_DEBUG : AV_LOG_WARNING,

                       "DTS %"PRIi64" < %"PRIi64" out of order\n",

                       pkt->dts,

                       st->last_dts_for_order_check);

                st->dts_misordered++;

            }

            if (st->dts_ordered + st->dts_misordered > 250) {

                st->dts_ordered    >>= 1;

                st->dts_misordered >>= 1;

            }

        }



        st->last_dts_for_order_check = pkt->dts;

        if (st->dts_ordered < 8*st->dts_misordered && pkt->dts == pkt->pts)

            pkt->dts = AV_NOPTS_VALUE;

    }



    if ((s->flags & AVFMT_FLAG_IGNDTS) && pkt->pts != AV_NOPTS_VALUE)

        pkt->dts = AV_NOPTS_VALUE;



    if (pc && pc->pict_type == AV_PICTURE_TYPE_B

        && !st->codec->has_b_frames)

        //FIXME Set low_delay = 0 when has_b_frames = 1

        st->codec->has_b_frames = 1;



    /* do we have a video B-frame ? */

    delay = st->codec->has_b_frames;

    presentation_delayed = 0;



    /* XXX: need has_b_frame, but cannot get it if the codec is

     *  not initialized */

    if (delay &&

        pc && pc->pict_type != AV_PICTURE_TYPE_B)

        presentation_delayed = 1;



    if (pkt->pts != AV_NOPTS_VALUE && pkt->dts != AV_NOPTS_VALUE &&

        st->pts_wrap_bits < 63 &&

        pkt->dts - (1LL << (st->pts_wrap_bits - 1)) > pkt->pts) {

        if (is_relative(st->cur_dts) || pkt->dts - (1LL<<(st->pts_wrap_bits - 1)) > st->cur_dts) {

            pkt->dts -= 1LL << st->pts_wrap_bits;

        } else

            pkt->pts += 1LL << st->pts_wrap_bits;

    }



    /* Some MPEG-2 in MPEG-PS lack dts (issue #171 / input_file.mpg).

     * We take the conservative approach and discard both.

     * Note: If this is misbehaving for an H.264 file, then possibly

     * presentation_delayed is not set correctly. */

    if (delay == 1 && pkt->dts == pkt->pts &&

        pkt->dts != AV_NOPTS_VALUE && presentation_delayed) {

        av_log(s, AV_LOG_DEBUG, "invalid dts/pts combination %"PRIi64"\n", pkt->dts);

        if (    strcmp(s->iformat->name, "mov,mp4,m4a,3gp,3g2,mj2")

             && strcmp(s->iformat->name, "flv")) // otherwise we discard correct timestamps for vc1-wmapro.ism

            pkt->dts = AV_NOPTS_VALUE;

    }



    duration = av_mul_q((AVRational) {pkt->duration, 1}, st->time_base);

    if (pkt->duration == 0) {

        ff_compute_frame_duration(s, &num, &den, st, pc, pkt);

        if (den && num) {

            duration = (AVRational) {num, den};

            pkt->duration = av_rescale_rnd(1,

                                           num * (int64_t) st->time_base.den,

                                           den * (int64_t) st->time_base.num,

                                           AV_ROUND_DOWN);

        }

    }



    if (pkt->duration != 0 && (s->packet_buffer || s->parse_queue))

        update_initial_durations(s, st, pkt->stream_index, pkt->duration);



    /* Correct timestamps with byte offset if demuxers only have timestamps

     * on packet boundaries */

    if (pc && st->need_parsing == AVSTREAM_PARSE_TIMESTAMPS && pkt->size) {

        /* this will estimate bitrate based on this frame's duration and size */

        offset = av_rescale(pc->offset, pkt->duration, pkt->size);

        if (pkt->pts != AV_NOPTS_VALUE)

            pkt->pts += offset;

        if (pkt->dts != AV_NOPTS_VALUE)

            pkt->dts += offset;

    }



    /* This may be redundant, but it should not hurt. */

    if (pkt->dts != AV_NOPTS_VALUE &&

        pkt->pts != AV_NOPTS_VALUE &&

        pkt->pts > pkt->dts)

        presentation_delayed = 1;



    av_dlog(NULL,

            "IN delayed:%d pts:%s, dts:%s cur_dts:%s st:%d pc:%p duration:%d delay:%d onein_oneout:%d\n",

            presentation_delayed, av_ts2str(pkt->pts), av_ts2str(pkt->dts), av_ts2str(st->cur_dts),

            pkt->stream_index, pc, pkt->duration, delay, onein_oneout);

    /* Interpolate PTS and DTS if they are not present. We skip H264

     * currently because delay and has_b_frames are not reliably set. */

    if ((delay == 0 || (delay == 1 && pc)) &&

        onein_oneout) {

        if (presentation_delayed) {

            /* DTS = decompression timestamp */

            /* PTS = presentation timestamp */

            if (pkt->dts == AV_NOPTS_VALUE)

                pkt->dts = st->last_IP_pts;

            update_initial_timestamps(s, pkt->stream_index, pkt->dts, pkt->pts, pkt);

            if (pkt->dts == AV_NOPTS_VALUE)

                pkt->dts = st->cur_dts;



            /* This is tricky: the dts must be incremented by the duration

             * of the frame we are displaying, i.e. the last I- or P-frame. */

            if (st->last_IP_duration == 0)

                st->last_IP_duration = pkt->duration;

            if (pkt->dts != AV_NOPTS_VALUE)

                st->cur_dts = pkt->dts + st->last_IP_duration;

            if (pkt->dts != AV_NOPTS_VALUE &&

                pkt->pts == AV_NOPTS_VALUE &&

                st->last_IP_duration > 0 &&

                (st->cur_dts - next_dts) <= 1 &&

                next_dts != next_pts &&

                next_pts != AV_NOPTS_VALUE)

                pkt->pts = next_dts;



            st->last_IP_duration = pkt->duration;

            st->last_IP_pts      = pkt->pts;

            /* Cannot compute PTS if not present (we can compute it only

             * by knowing the future. */

        } else if (pkt->pts != AV_NOPTS_VALUE ||

                   pkt->dts != AV_NOPTS_VALUE ||

                   pkt->duration                ) {



            /* presentation is not delayed : PTS and DTS are the same */

            if (pkt->pts == AV_NOPTS_VALUE)

                pkt->pts = pkt->dts;

            update_initial_timestamps(s, pkt->stream_index, pkt->pts,

                                      pkt->pts, pkt);

            if (pkt->pts == AV_NOPTS_VALUE)

                pkt->pts = st->cur_dts;

            pkt->dts = pkt->pts;

            if (pkt->pts != AV_NOPTS_VALUE)

                st->cur_dts = av_add_stable(st->time_base, pkt->pts, duration, 1);

        }

    }



    if (pkt->pts != AV_NOPTS_VALUE && delay <= MAX_REORDER_DELAY && has_decode_delay_been_guessed(st)) {

        st->pts_buffer[0] = pkt->pts;

        for (i = 0; i<delay && st->pts_buffer[i] > st->pts_buffer[i + 1]; i++)

            FFSWAP(int64_t, st->pts_buffer[i], st->pts_buffer[i + 1]);



        pkt->dts = select_from_pts_buffer(st, st->pts_buffer, pkt->dts);

    }

    // We skipped it above so we try here.

    if (!onein_oneout)

        // This should happen on the first packet

        update_initial_timestamps(s, pkt->stream_index, pkt->dts, pkt->pts, pkt);

    if (pkt->dts > st->cur_dts)

        st->cur_dts = pkt->dts;



    av_dlog(NULL, "OUTdelayed:%d/%d pts:%s, dts:%s cur_dts:%s\n",

            presentation_delayed, delay, av_ts2str(pkt->pts), av_ts2str(pkt->dts), av_ts2str(st->cur_dts));



    /* update flags */

    if (is_intra_only(st->codec))

        pkt->flags |= AV_PKT_FLAG_KEY;

    if (pc)

        pkt->convergence_duration = pc->convergence_duration;

}

static int img_snapshot(int argc, char **argv)

{

    BlockDriverState *bs;

    QEMUSnapshotInfo sn;

    char *filename, *snapshot_name = NULL;

    int c, ret = 0, bdrv_oflags;

    int action = 0;

    qemu_timeval tv;



    bdrv_oflags = BDRV_O_FLAGS | BDRV_O_RDWR;

    /* Parse commandline parameters */

    for(;;) {

        c = getopt(argc, argv, "la:c:d:h");

        if (c == -1) {

            break;

        }

        switch(c) {

        case '?':

        case 'h':

            help();

            return 0;

        case 'l':

            if (action) {

                help();

                return 0;

            }

            action = SNAPSHOT_LIST;

            bdrv_oflags &= ~BDRV_O_RDWR; /* no need for RW */

            break;

        case 'a':

            if (action) {

                help();

                return 0;

            }

            action = SNAPSHOT_APPLY;

            snapshot_name = optarg;

            break;

        case 'c':

            if (action) {

                help();

                return 0;

            }

            action = SNAPSHOT_CREATE;

            snapshot_name = optarg;

            break;

        case 'd':

            if (action) {

                help();

                return 0;

            }

            action = SNAPSHOT_DELETE;

            snapshot_name = optarg;

            break;

        }

    }



    if (optind >= argc) {

        help();

    }

    filename = argv[optind++];



    /* Open the image */

    bs = bdrv_new_open(filename, NULL, bdrv_oflags);

    if (!bs) {

        return 1;

    }



    /* Perform the requested action */

    switch(action) {

    case SNAPSHOT_LIST:

        dump_snapshots(bs);

        break;



    case SNAPSHOT_CREATE:

        memset(&sn, 0, sizeof(sn));

        pstrcpy(sn.name, sizeof(sn.name), snapshot_name);



        qemu_gettimeofday(&tv);

        sn.date_sec = tv.tv_sec;

        sn.date_nsec = tv.tv_usec * 1000;



        ret = bdrv_snapshot_create(bs, &sn);

        if (ret) {

            error_report("Could not create snapshot '%s': %d (%s)",

                snapshot_name, ret, strerror(-ret));

        }

        break;



    case SNAPSHOT_APPLY:

        ret = bdrv_snapshot_goto(bs, snapshot_name);

        if (ret) {

            error_report("Could not apply snapshot '%s': %d (%s)",

                snapshot_name, ret, strerror(-ret));

        }

        break;



    case SNAPSHOT_DELETE:

        ret = bdrv_snapshot_delete(bs, snapshot_name);

        if (ret) {

            error_report("Could not delete snapshot '%s': %d (%s)",

                snapshot_name, ret, strerror(-ret));

        }

        break;

    }



    /* Cleanup */

    bdrv_delete(bs);

    if (ret) {

        return 1;

    }

    return 0;

}

static int sbr_make_f_master(AACContext *ac, SpectralBandReplication *sbr,

                             SpectrumParameters *spectrum)

{

    unsigned int temp, max_qmf_subbands = 0;

    unsigned int start_min, stop_min;

    int k;

    const int8_t *sbr_offset_ptr;

    int16_t stop_dk[13];



    if (sbr->sample_rate < 32000) {

        temp = 3000;

    } else if (sbr->sample_rate < 64000) {

        temp = 4000;

    } else

        temp = 5000;



    start_min = ((temp << 7) + (sbr->sample_rate >> 1)) / sbr->sample_rate;

    stop_min  = ((temp << 8) + (sbr->sample_rate >> 1)) / sbr->sample_rate;



    switch (sbr->sample_rate) {

    case 16000:

        sbr_offset_ptr = sbr_offset[0];

        break;

    case 22050:

        sbr_offset_ptr = sbr_offset[1];

        break;

    case 24000:

        sbr_offset_ptr = sbr_offset[2];

        break;

    case 32000:

        sbr_offset_ptr = sbr_offset[3];

        break;

    case 44100: case 48000: case 64000:

        sbr_offset_ptr = sbr_offset[4];

        break;

    case 88200: case 96000: case 128000: case 176400: case 192000:

        sbr_offset_ptr = sbr_offset[5];

        break;

    default:

        av_log(ac->avctx, AV_LOG_ERROR,

               "Unsupported sample rate for SBR: %d\n", sbr->sample_rate);

        return -1;

    }



    sbr->k[0] = start_min + sbr_offset_ptr[spectrum->bs_start_freq];



    if (spectrum->bs_stop_freq < 14) {

        sbr->k[2] = stop_min;

        make_bands(stop_dk, stop_min, 64, 13);

        qsort(stop_dk, 13, sizeof(stop_dk[0]), qsort_comparison_function_int16);

        for (k = 0; k < spectrum->bs_stop_freq; k++)

            sbr->k[2] += stop_dk[k];

    } else if (spectrum->bs_stop_freq == 14) {

        sbr->k[2] = 2*sbr->k[0];

    } else if (spectrum->bs_stop_freq == 15) {

        sbr->k[2] = 3*sbr->k[0];

    } else {

        av_log(ac->avctx, AV_LOG_ERROR,

               "Invalid bs_stop_freq: %d\n", spectrum->bs_stop_freq);

        return -1;

    }

    sbr->k[2] = FFMIN(64, sbr->k[2]);



    // Requirements (14496-3 sp04 p205)

    if (sbr->sample_rate <= 32000) {

        max_qmf_subbands = 48;

    } else if (sbr->sample_rate == 44100) {

        max_qmf_subbands = 35;

    } else if (sbr->sample_rate >= 48000)

        max_qmf_subbands = 32;



    if (sbr->k[2] - sbr->k[0] > max_qmf_subbands) {

        av_log(ac->avctx, AV_LOG_ERROR,

               "Invalid bitstream, too many QMF subbands: %d\n", sbr->k[2] - sbr->k[0]);

        return -1;

    }



    if (!spectrum->bs_freq_scale) {

        int dk, k2diff;



        dk = spectrum->bs_alter_scale + 1;

        sbr->n_master = ((sbr->k[2] - sbr->k[0] + (dk&2)) >> dk) << 1;

        if (check_n_master(ac->avctx, sbr->n_master, sbr->spectrum_params.bs_xover_band))

            return -1;



        for (k = 1; k <= sbr->n_master; k++)

            sbr->f_master[k] = dk;



        k2diff = sbr->k[2] - sbr->k[0] - sbr->n_master * dk;

        if (k2diff < 0) {

            sbr->f_master[1]--;

            sbr->f_master[2]-= (k2diff < -1);

        } else if (k2diff) {

            sbr->f_master[sbr->n_master]++;

        }



        sbr->f_master[0] = sbr->k[0];

        for (k = 1; k <= sbr->n_master; k++)

            sbr->f_master[k] += sbr->f_master[k - 1];



    } else {

        int half_bands = 7 - spectrum->bs_freq_scale;      // bs_freq_scale  = {1,2,3}

        int two_regions, num_bands_0;

        int vdk0_max, vdk1_min;

        int16_t vk0[49];



        if (49 * sbr->k[2] > 110 * sbr->k[0]) {

            two_regions = 1;

            sbr->k[1] = 2 * sbr->k[0];

        } else {

            two_regions = 0;

            sbr->k[1] = sbr->k[2];

        }



        num_bands_0 = lrintf(half_bands * log2f(sbr->k[1] / (float)sbr->k[0])) * 2;



        if (num_bands_0 <= 0) { // Requirements (14496-3 sp04 p205)

            av_log(ac->avctx, AV_LOG_ERROR, "Invalid num_bands_0: %d\n", num_bands_0);

            return -1;

        }



        vk0[0] = 0;



        make_bands(vk0+1, sbr->k[0], sbr->k[1], num_bands_0);



        qsort(vk0 + 1, num_bands_0, sizeof(vk0[1]), qsort_comparison_function_int16);

        vdk0_max = vk0[num_bands_0];



        vk0[0] = sbr->k[0];

        for (k = 1; k <= num_bands_0; k++) {

            if (vk0[k] <= 0) { // Requirements (14496-3 sp04 p205)

                av_log(ac->avctx, AV_LOG_ERROR, "Invalid vDk0[%d]: %d\n", k, vk0[k]);

                return -1;

            }

            vk0[k] += vk0[k-1];

        }



        if (two_regions) {

            int16_t vk1[49];

            float invwarp = spectrum->bs_alter_scale ? 0.76923076923076923077f

                                                     : 1.0f; // bs_alter_scale = {0,1}

            int num_bands_1 = lrintf(half_bands * invwarp *

                                     log2f(sbr->k[2] / (float)sbr->k[1])) * 2;



            make_bands(vk1+1, sbr->k[1], sbr->k[2], num_bands_1);



            vdk1_min = array_min_int16(vk1 + 1, num_bands_1);



            if (vdk1_min < vdk0_max) {

                int change;

                qsort(vk1 + 1, num_bands_1, sizeof(vk1[1]), qsort_comparison_function_int16);

                change = FFMIN(vdk0_max - vk1[1], (vk1[num_bands_1] - vk1[1]) >> 1);

                vk1[1]           += change;

                vk1[num_bands_1] -= change;

            }



            qsort(vk1 + 1, num_bands_1, sizeof(vk1[1]), qsort_comparison_function_int16);



            vk1[0] = sbr->k[1];

            for (k = 1; k <= num_bands_1; k++) {

                if (vk1[k] <= 0) { // Requirements (14496-3 sp04 p205)

                    av_log(ac->avctx, AV_LOG_ERROR, "Invalid vDk1[%d]: %d\n", k, vk1[k]);

                    return -1;

                }

                vk1[k] += vk1[k-1];

            }



            sbr->n_master = num_bands_0 + num_bands_1;

            if (check_n_master(ac->avctx, sbr->n_master, sbr->spectrum_params.bs_xover_band))

                return -1;

            memcpy(&sbr->f_master[0],               vk0,

                   (num_bands_0 + 1) * sizeof(sbr->f_master[0]));

            memcpy(&sbr->f_master[num_bands_0 + 1], vk1 + 1,

                    num_bands_1      * sizeof(sbr->f_master[0]));



        } else {

            sbr->n_master = num_bands_0;

            if (check_n_master(ac->avctx, sbr->n_master, sbr->spectrum_params.bs_xover_band))

                return -1;

            memcpy(sbr->f_master, vk0, (num_bands_0 + 1) * sizeof(sbr->f_master[0]));

        }

    }



    return 0;

}

void ppc_cpu_list (FILE *f, int (*cpu_fprintf)(FILE *f, const char *fmt, ...))

{

    int i;



    for (i = 0; ; i++) {

        (*cpu_fprintf)(f, "PowerPC %-16s PVR %08x\n",

                       ppc_defs[i].name, ppc_defs[i].pvr);

        if (strcmp(ppc_defs[i].name, "default") == 0)

            break;

    }

}

static void pc_q35_init(QEMUMachineInitArgs *args)

{

    ram_addr_t below_4g_mem_size, above_4g_mem_size;

    Q35PCIHost *q35_host;

    PCIHostState *phb;

    PCIBus *host_bus;

    PCIDevice *lpc;

    BusState *idebus[MAX_SATA_PORTS];

    ISADevice *rtc_state;

    ISADevice *floppy;

    MemoryRegion *pci_memory;

    MemoryRegion *rom_memory;

    MemoryRegion *ram_memory;

    GSIState *gsi_state;

    ISABus *isa_bus;

    int pci_enabled = 1;

    qemu_irq *cpu_irq;

    qemu_irq *gsi;

    qemu_irq *i8259;

    int i;

    ICH9LPCState *ich9_lpc;

    PCIDevice *ahci;

    DeviceState *icc_bridge;

    PcGuestInfo *guest_info;



    icc_bridge = qdev_create(NULL, TYPE_ICC_BRIDGE);

    object_property_add_child(qdev_get_machine(), "icc-bridge",

                              OBJECT(icc_bridge), NULL);



    pc_cpus_init(args->cpu_model, icc_bridge);

    pc_acpi_init("q35-acpi-dsdt.aml");



    kvmclock_create();



    if (args->ram_size >= 0xb0000000) {

        above_4g_mem_size = args->ram_size - 0xb0000000;

        below_4g_mem_size = 0xb0000000;

    } else {

        above_4g_mem_size = 0;

        below_4g_mem_size = args->ram_size;

    }



    /* pci enabled */

    if (pci_enabled) {

        pci_memory = g_new(MemoryRegion, 1);

        memory_region_init(pci_memory, NULL, "pci", INT64_MAX);

        rom_memory = pci_memory;

    } else {

        pci_memory = NULL;

        rom_memory = get_system_memory();

    }



    guest_info = pc_guest_info_init(below_4g_mem_size, above_4g_mem_size);

    guest_info->has_pci_info = has_pci_info;

    guest_info->isapc_ram_fw = false;



    /* allocate ram and load rom/bios */

    if (!xen_enabled()) {

        pc_memory_init(get_system_memory(),

                       args->kernel_filename, args->kernel_cmdline,

                       args->initrd_filename,

                       below_4g_mem_size, above_4g_mem_size,

                       rom_memory, &ram_memory, guest_info);

    }



    /* irq lines */

    gsi_state = g_malloc0(sizeof(*gsi_state));

    if (kvm_irqchip_in_kernel()) {

        kvm_pc_setup_irq_routing(pci_enabled);

        gsi = qemu_allocate_irqs(kvm_pc_gsi_handler, gsi_state,

                                 GSI_NUM_PINS);

    } else {

        gsi = qemu_allocate_irqs(gsi_handler, gsi_state, GSI_NUM_PINS);

    }



    /* create pci host bus */

    q35_host = Q35_HOST_DEVICE(qdev_create(NULL, TYPE_Q35_HOST_DEVICE));



    object_property_add_child(qdev_get_machine(), "q35", OBJECT(q35_host), NULL);

    q35_host->mch.ram_memory = ram_memory;

    q35_host->mch.pci_address_space = pci_memory;

    q35_host->mch.system_memory = get_system_memory();

    q35_host->mch.address_space_io = get_system_io();

    q35_host->mch.below_4g_mem_size = below_4g_mem_size;

    q35_host->mch.above_4g_mem_size = above_4g_mem_size;

    q35_host->mch.guest_info = guest_info;

    /* pci */

    qdev_init_nofail(DEVICE(q35_host));

    phb = PCI_HOST_BRIDGE(q35_host);

    host_bus = phb->bus;

    /* create ISA bus */

    lpc = pci_create_simple_multifunction(host_bus, PCI_DEVFN(ICH9_LPC_DEV,

                                          ICH9_LPC_FUNC), true,

                                          TYPE_ICH9_LPC_DEVICE);

    ich9_lpc = ICH9_LPC_DEVICE(lpc);

    ich9_lpc->pic = gsi;

    ich9_lpc->ioapic = gsi_state->ioapic_irq;

    pci_bus_irqs(host_bus, ich9_lpc_set_irq, ich9_lpc_map_irq, ich9_lpc,

                 ICH9_LPC_NB_PIRQS);

    pci_bus_set_route_irq_fn(host_bus, ich9_route_intx_pin_to_irq);

    isa_bus = ich9_lpc->isa_bus;



    /*end early*/

    isa_bus_irqs(isa_bus, gsi);



    if (kvm_irqchip_in_kernel()) {

        i8259 = kvm_i8259_init(isa_bus);

    } else if (xen_enabled()) {

        i8259 = xen_interrupt_controller_init();

    } else {

        cpu_irq = pc_allocate_cpu_irq();

        i8259 = i8259_init(isa_bus, cpu_irq[0]);

    }



    for (i = 0; i < ISA_NUM_IRQS; i++) {

        gsi_state->i8259_irq[i] = i8259[i];

    }

    if (pci_enabled) {

        ioapic_init_gsi(gsi_state, NULL);

    }

    qdev_init_nofail(icc_bridge);



    pc_register_ferr_irq(gsi[13]);



    /* init basic PC hardware */

    pc_basic_device_init(isa_bus, gsi, &rtc_state, &floppy, false);



    /* connect pm stuff to lpc */

    ich9_lpc_pm_init(lpc);



    /* ahci and SATA device, for q35 1 ahci controller is built-in */

    ahci = pci_create_simple_multifunction(host_bus,

                                           PCI_DEVFN(ICH9_SATA1_DEV,

                                                     ICH9_SATA1_FUNC),

                                           true, "ich9-ahci");

    idebus[0] = qdev_get_child_bus(&ahci->qdev, "ide.0");

    idebus[1] = qdev_get_child_bus(&ahci->qdev, "ide.1");



    if (usb_enabled(false)) {

        /* Should we create 6 UHCI according to ich9 spec? */

        ehci_create_ich9_with_companions(host_bus, 0x1d);

    }



    /* TODO: Populate SPD eeprom data.  */

    smbus_eeprom_init(ich9_smb_init(host_bus,

                                    PCI_DEVFN(ICH9_SMB_DEV, ICH9_SMB_FUNC),

                                    0xb100),

                      8, NULL, 0);



    pc_cmos_init(below_4g_mem_size, above_4g_mem_size, args->boot_device,

                 floppy, idebus[0], idebus[1], rtc_state);



    /* the rest devices to which pci devfn is automatically assigned */

    pc_vga_init(isa_bus, host_bus);

    pc_nic_init(isa_bus, host_bus);

    if (pci_enabled) {

        pc_pci_device_init(host_bus);

    }



    if (has_pvpanic) {

        pvpanic_init(isa_bus);

    }

}

vubr_backend_recv_cb(int sock, void *ctx)

{

    VubrDev *vubr = (VubrDev *) ctx;

    VuDev *dev = &vubr->vudev;

    VuVirtq *vq = vu_get_queue(dev, 0);

    VuVirtqElement *elem = NULL;

    struct iovec mhdr_sg[VIRTQUEUE_MAX_SIZE];

    struct virtio_net_hdr_mrg_rxbuf mhdr;

    unsigned mhdr_cnt = 0;

    int hdrlen = vubr->hdrlen;

    int i = 0;

    struct virtio_net_hdr hdr = {

        .flags = 0,

        .gso_type = VIRTIO_NET_HDR_GSO_NONE

    };



    DPRINT("\n\n   ***   IN UDP RECEIVE CALLBACK    ***\n\n");

    DPRINT("    hdrlen = %d\n", hdrlen);



    if (!vu_queue_enabled(dev, vq) ||

        !vu_queue_started(dev, vq) ||

        !vu_queue_avail_bytes(dev, vq, hdrlen, 0)) {

        DPRINT("Got UDP packet, but no available descriptors on RX virtq.\n");

        return;

    }



    do {

        struct iovec *sg;

        ssize_t ret, total = 0;

        unsigned int num;



        elem = vu_queue_pop(dev, vq, sizeof(VuVirtqElement));

        if (!elem) {

            break;

        }



        if (elem->in_num < 1) {

            fprintf(stderr, "virtio-net contains no in buffers\n");

            break;

        }



        sg = elem->in_sg;

        num = elem->in_num;

        if (i == 0) {

            if (hdrlen == 12) {

                mhdr_cnt = iov_copy(mhdr_sg, ARRAY_SIZE(mhdr_sg),

                                    sg, elem->in_num,

                                    offsetof(typeof(mhdr), num_buffers),

                                    sizeof(mhdr.num_buffers));

            }

            iov_from_buf(sg, elem->in_num, 0, &hdr, sizeof hdr);

            total += hdrlen;

            ret = iov_discard_front(&sg, &num, hdrlen);

            assert(ret == hdrlen);

        }



        struct msghdr msg = {

            .msg_name = (struct sockaddr *) &vubr->backend_udp_dest,

            .msg_namelen = sizeof(struct sockaddr_in),

            .msg_iov = sg,

            .msg_iovlen = elem->in_num,

            .msg_flags = MSG_DONTWAIT,

        };

        do {

            ret = recvmsg(vubr->backend_udp_sock, &msg, 0);

        } while (ret == -1 && (errno == EINTR));



        if (i == 0) {

            iov_restore_front(elem->in_sg, sg, hdrlen);

        }



        if (ret == -1) {

            if (errno == EWOULDBLOCK) {

                vu_queue_rewind(dev, vq, 1);

                break;

            }



            vubr_die("recvmsg()");

        }



        total += ret;

        iov_truncate(elem->in_sg, elem->in_num, total);

        vu_queue_fill(dev, vq, elem, total, i++);



        free(elem);

        elem = NULL;

    } while (false); /* could loop if DONTWAIT worked? */



    if (mhdr_cnt) {

        mhdr.num_buffers = i;

        iov_from_buf(mhdr_sg, mhdr_cnt,

                     0,

                     &mhdr.num_buffers, sizeof mhdr.num_buffers);

    }



    vu_queue_flush(dev, vq, i);

    vu_queue_notify(dev, vq);



    free(elem);

}

static int read_sm_data(AVFormatContext *s, AVIOContext *bc, AVPacket *pkt, int is_meta, int64_t maxpos)

{

    int count = ffio_read_varlen(bc);

    int skip_start = 0;

    int skip_end = 0;

    int channels = 0;

    int64_t channel_layout = 0;

    int sample_rate = 0;

    int width = 0;

    int height = 0;

    int i;



    for (i=0; i<count; i++) {

        uint8_t name[256], str_value[256], type_str[256];

        int value;

        if (avio_tell(bc) >= maxpos)

            return AVERROR_INVALIDDATA;

        get_str(bc, name, sizeof(name));

        value = get_s(bc);



        if (value == -1) {

            get_str(bc, str_value, sizeof(str_value));

            av_log(s, AV_LOG_WARNING, "Unknown string %s / %s\n", name, str_value);

        } else if (value == -2) {

            uint8_t *dst = NULL;

            int64_t v64, value_len;



            get_str(bc, type_str, sizeof(type_str));

            value_len = ffio_read_varlen(bc);

            if (avio_tell(bc) + value_len >= maxpos)

                return AVERROR_INVALIDDATA;

            if (!strcmp(name, "Palette")) {

                dst = av_packet_new_side_data(pkt, AV_PKT_DATA_PALETTE, value_len);

            } else if (!strcmp(name, "Extradata")) {

                dst = av_packet_new_side_data(pkt, AV_PKT_DATA_NEW_EXTRADATA, value_len);

            } else if (sscanf(name, "CodecSpecificSide%"SCNd64"", &v64) == 1) {

                dst = av_packet_new_side_data(pkt, AV_PKT_DATA_MATROSKA_BLOCKADDITIONAL, value_len + 8);

                if(!dst)

                    return AVERROR(ENOMEM);

                AV_WB64(dst, v64);

                dst += 8;

            } else if (!strcmp(name, "ChannelLayout") && value_len == 8) {

                channel_layout = avio_rl64(bc);

                continue;

            } else {

                av_log(s, AV_LOG_WARNING, "Unknown data %s / %s\n", name, type_str);

                avio_skip(bc, value_len);

                continue;

            }

            if(!dst)

                return AVERROR(ENOMEM);

            avio_read(bc, dst, value_len);

        } else if (value == -3) {

            value = get_s(bc);

        } else if (value == -4) {

            value = ffio_read_varlen(bc);

        } else if (value < -4) {

            get_s(bc);

        } else {

            if (!strcmp(name, "SkipStart")) {

                skip_start = value;

            } else if (!strcmp(name, "SkipEnd")) {

                skip_end = value;

            } else if (!strcmp(name, "Channels")) {

                channels = value;

            } else if (!strcmp(name, "SampleRate")) {

                sample_rate = value;

            } else if (!strcmp(name, "Width")) {

                width = value;

            } else if (!strcmp(name, "Height")) {

                height = value;

            } else {

                av_log(s, AV_LOG_WARNING, "Unknown integer %s\n", name);

            }

        }

    }



    if (channels || channel_layout || sample_rate || width || height) {

        uint8_t *dst = av_packet_new_side_data(pkt, AV_PKT_DATA_PARAM_CHANGE, 28);

        if (!dst)

            return AVERROR(ENOMEM);

        bytestream_put_le32(&dst,

                            AV_SIDE_DATA_PARAM_CHANGE_CHANNEL_COUNT*(!!channels) +

                            AV_SIDE_DATA_PARAM_CHANGE_CHANNEL_LAYOUT*(!!channel_layout) +

                            AV_SIDE_DATA_PARAM_CHANGE_SAMPLE_RATE*(!!sample_rate) +

                            AV_SIDE_DATA_PARAM_CHANGE_DIMENSIONS*(!!(width|height))

                           );

        if (channels)

            bytestream_put_le32(&dst, channels);

        if (channel_layout)

            bytestream_put_le64(&dst, channel_layout);

        if (sample_rate)

            bytestream_put_le32(&dst, sample_rate);

        if (width || height){

            bytestream_put_le32(&dst, width);

            bytestream_put_le32(&dst, height);

        }

    }



    if (skip_start || skip_end) {

        uint8_t *dst = av_packet_new_side_data(pkt, AV_PKT_DATA_SKIP_SAMPLES, 10);

        if (!dst)

            return AVERROR(ENOMEM);

        AV_WL32(dst, skip_start);

        AV_WL32(dst+4, skip_end);

    }



    return 0;

}

eth_calc_pseudo_hdr_csum(struct ip_header *iphdr, uint16_t csl)

{

    struct ip_pseudo_header ipph;

    ipph.ip_src = iphdr->ip_src;

    ipph.ip_dst = iphdr->ip_dst;

    ipph.ip_payload = cpu_to_be16(csl);

    ipph.ip_proto = iphdr->ip_p;

    ipph.zeros = 0;

    return net_checksum_add(sizeof(ipph), (uint8_t *) &ipph);

}

void mips_r4k_init(MachineState *machine)

{

    ram_addr_t ram_size = machine->ram_size;

    const char *cpu_model = machine->cpu_model;

    const char *kernel_filename = machine->kernel_filename;

    const char *kernel_cmdline = machine->kernel_cmdline;

    const char *initrd_filename = machine->initrd_filename;

    char *filename;

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *ram = g_new(MemoryRegion, 1);

    MemoryRegion *bios;

    MemoryRegion *iomem = g_new(MemoryRegion, 1);

    MemoryRegion *isa_io = g_new(MemoryRegion, 1);

    MemoryRegion *isa_mem = g_new(MemoryRegion, 1);

    int bios_size;

    MIPSCPU *cpu;

    CPUMIPSState *env;

    ResetData *reset_info;

    int i;

    qemu_irq *i8259;

    ISABus *isa_bus;

    DriveInfo *hd[MAX_IDE_BUS * MAX_IDE_DEVS];

    DriveInfo *dinfo;

    int be;



    /* init CPUs */

    if (cpu_model == NULL) {

#ifdef TARGET_MIPS64

        cpu_model = "R4000";

#else

        cpu_model = "24Kf";

#endif

    }

    cpu = cpu_mips_init(cpu_model);

    if (cpu == NULL) {

        fprintf(stderr, "Unable to find CPU definition\n");

        exit(1);

    }

    env = &cpu->env;



    reset_info = g_malloc0(sizeof(ResetData));

    reset_info->cpu = cpu;

    reset_info->vector = env->active_tc.PC;

    qemu_register_reset(main_cpu_reset, reset_info);



    /* allocate RAM */

    if (ram_size > (256 << 20)) {

        fprintf(stderr,

                "qemu: Too much memory for this machine: %d MB, maximum 256 MB\n",

                ((unsigned int)ram_size / (1 << 20)));

        exit(1);

    }

    memory_region_allocate_system_memory(ram, NULL, "mips_r4k.ram", ram_size);



    memory_region_add_subregion(address_space_mem, 0, ram);



    memory_region_init_io(iomem, NULL, &mips_qemu_ops, NULL, "mips-qemu", 0x10000);

    memory_region_add_subregion(address_space_mem, 0x1fbf0000, iomem);



    /* Try to load a BIOS image. If this fails, we continue regardless,

       but initialize the hardware ourselves. When a kernel gets

       preloaded we also initialize the hardware, since the BIOS wasn't

       run. */

    if (bios_name == NULL)

        bios_name = BIOS_FILENAME;

    filename = qemu_find_file(QEMU_FILE_TYPE_BIOS, bios_name);

    if (filename) {

        bios_size = get_image_size(filename);

    } else {

        bios_size = -1;

    }

#ifdef TARGET_WORDS_BIGENDIAN

    be = 1;

#else

    be = 0;

#endif

    if ((bios_size > 0) && (bios_size <= BIOS_SIZE)) {

        bios = g_new(MemoryRegion, 1);

        memory_region_init_ram(bios, NULL, "mips_r4k.bios", BIOS_SIZE,

                               &error_abort);

        vmstate_register_ram_global(bios);

        memory_region_set_readonly(bios, true);

        memory_region_add_subregion(get_system_memory(), 0x1fc00000, bios);



        load_image_targphys(filename, 0x1fc00000, BIOS_SIZE);

    } else if ((dinfo = drive_get(IF_PFLASH, 0, 0)) != NULL) {

        uint32_t mips_rom = 0x00400000;

        if (!pflash_cfi01_register(0x1fc00000, NULL, "mips_r4k.bios", mips_rom,

                                   blk_by_legacy_dinfo(dinfo),

                                   sector_len, mips_rom / sector_len,

                                   4, 0, 0, 0, 0, be)) {

            fprintf(stderr, "qemu: Error registering flash memory.\n");

	}

    } else if (!qtest_enabled()) {

	/* not fatal */

        fprintf(stderr, "qemu: Warning, could not load MIPS bios '%s'\n",

		bios_name);

    }

    g_free(filename);



    if (kernel_filename) {

        loaderparams.ram_size = ram_size;

        loaderparams.kernel_filename = kernel_filename;

        loaderparams.kernel_cmdline = kernel_cmdline;

        loaderparams.initrd_filename = initrd_filename;

        reset_info->vector = load_kernel();

    }



    /* Init CPU internal devices */

    cpu_mips_irq_init_cpu(env);

    cpu_mips_clock_init(env);



    /* ISA bus: IO space at 0x14000000, mem space at 0x10000000 */

    memory_region_init_alias(isa_io, NULL, "isa-io",

                             get_system_io(), 0, 0x00010000);

    memory_region_init(isa_mem, NULL, "isa-mem", 0x01000000);

    memory_region_add_subregion(get_system_memory(), 0x14000000, isa_io);

    memory_region_add_subregion(get_system_memory(), 0x10000000, isa_mem);

    isa_bus = isa_bus_new(NULL, isa_mem, get_system_io());



    /* The PIC is attached to the MIPS CPU INT0 pin */

    i8259 = i8259_init(isa_bus, env->irq[2]);

    isa_bus_irqs(isa_bus, i8259);



    rtc_init(isa_bus, 2000, NULL);



    pit = pit_init(isa_bus, 0x40, 0, NULL);



    serial_hds_isa_init(isa_bus, MAX_SERIAL_PORTS);



    isa_vga_init(isa_bus);



    if (nd_table[0].used)

        isa_ne2000_init(isa_bus, 0x300, 9, &nd_table[0]);



    ide_drive_get(hd, ARRAY_SIZE(hd));

    for(i = 0; i < MAX_IDE_BUS; i++)

        isa_ide_init(isa_bus, ide_iobase[i], ide_iobase2[i], ide_irq[i],

                     hd[MAX_IDE_DEVS * i],

		     hd[MAX_IDE_DEVS * i + 1]);



    isa_create_simple(isa_bus, "i8042");

}

void pmac_format_nvram_partition (MacIONVRAMState *nvr, int len)

{

    unsigned int i;

    uint32_t start = 0, end;

    struct OpenBIOS_nvpart_v1 *part_header;



    // OpenBIOS nvram variables

    // Variable partition

    part_header = (struct OpenBIOS_nvpart_v1 *)nvr->data;

    part_header->signature = OPENBIOS_PART_SYSTEM;

    pstrcpy(part_header->name, sizeof(part_header->name), "system");



    end = start + sizeof(struct OpenBIOS_nvpart_v1);

    for (i = 0; i < nb_prom_envs; i++)

        end = OpenBIOS_set_var(nvr->data, end, prom_envs[i]);



    // End marker

    nvr->data[end++] = '\0';



    end = start + ((end - start + 15) & ~15);

    /* XXX: OpenBIOS is not able to grow up a partition. Leave some space for

       new variables. */

    if (end < DEF_SYSTEM_SIZE)

        end = DEF_SYSTEM_SIZE;

    OpenBIOS_finish_partition(part_header, end - start);



    // free partition

    start = end;

    part_header = (struct OpenBIOS_nvpart_v1 *)&nvr->data[start];

    part_header->signature = OPENBIOS_PART_FREE;

    pstrcpy(part_header->name, sizeof(part_header->name), "free");



    end = len;

    OpenBIOS_finish_partition(part_header, end - start);

}

static void start_frame(AVFilterLink *inlink, AVFilterBufferRef *picref)

{

    PixdescTestContext *priv = inlink->dst->priv;

    AVFilterLink *outlink    = inlink->dst->outputs[0];

    AVFilterBufferRef *outpicref;

    int i;



    outlink->out_buf = avfilter_get_video_buffer(outlink, AV_PERM_WRITE,

                                                outlink->w, outlink->h);

    outpicref = outlink->out_buf;

    avfilter_copy_buffer_ref_props(outpicref, picref);



    for (i = 0; i < 4; i++) {

        int h = outlink->h;

        h = i == 1 || i == 2 ? h>>priv->pix_desc->log2_chroma_h : h;

        if (outpicref->data[i]) {

            uint8_t *data = outpicref->data[i] +

                (outpicref->linesize[i] > 0 ? 0 : outpicref->linesize[i] * (h-1));

            memset(data, 0, FFABS(outpicref->linesize[i]) * h);

        }

    }



    /* copy palette */

    if (priv->pix_desc->flags & PIX_FMT_PAL)

        memcpy(outpicref->data[1], outpicref->data[1], 256*4);



    avfilter_start_frame(outlink, avfilter_ref_buffer(outpicref, ~0));

}

static void configure_rtc(QemuOpts *opts)

{

    const char *value;



    value = qemu_opt_get(opts, "base");

    if (value) {

        if (!strcmp(value, "utc")) {

            rtc_utc = 1;

        } else if (!strcmp(value, "localtime")) {

            rtc_utc = 0;

        } else {

            configure_rtc_date_offset(value, 0);

        }

    }

    value = qemu_opt_get(opts, "clock");

    if (value) {

        if (!strcmp(value, "host")) {

            rtc_clock = QEMU_CLOCK_HOST;

        } else if (!strcmp(value, "rt")) {

            rtc_clock = QEMU_CLOCK_REALTIME;

        } else if (!strcmp(value, "vm")) {

            rtc_clock = QEMU_CLOCK_VIRTUAL;

        } else {

            fprintf(stderr, "qemu: invalid option value '%s'\n", value);

            exit(1);

        }

    }

    value = qemu_opt_get(opts, "driftfix");

    if (value) {

        if (!strcmp(value, "slew")) {

            static GlobalProperty slew_lost_ticks[] = {

                {

                    .driver   = "mc146818rtc",

                    .property = "lost_tick_policy",

                    .value    = "slew",

                },

                { /* end of list */ }

            };



            qdev_prop_register_global_list(slew_lost_ticks);

        } else if (!strcmp(value, "none")) {

            /* discard is default */

        } else {

            fprintf(stderr, "qemu: invalid option value '%s'\n", value);

            exit(1);

        }

    }

}

