static void flush_encoders(void)

{

    int i, ret;



    for (i = 0; i < nb_output_streams; i++) {

        OutputStream   *ost = output_streams[i];

        AVCodecContext *enc = ost->enc_ctx;

        AVFormatContext *os = output_files[ost->file_index]->ctx;

        int stop_encoding = 0;



        if (!ost->encoding_needed)

            continue;



        if (enc->codec_type == AVMEDIA_TYPE_AUDIO && enc->frame_size <= 1)

            continue;



        if (enc->codec_type != AVMEDIA_TYPE_VIDEO && enc->codec_type != AVMEDIA_TYPE_AUDIO)

            continue;



        avcodec_send_frame(enc, NULL);



        for (;;) {

            const char *desc = NULL;



            switch (enc->codec_type) {

            case AVMEDIA_TYPE_AUDIO:

                desc   = "Audio";

                break;

            case AVMEDIA_TYPE_VIDEO:

                desc   = "Video";

                break;

            default:

                av_assert0(0);

            }



            if (1) {

                AVPacket pkt;

                av_init_packet(&pkt);

                pkt.data = NULL;

                pkt.size = 0;



                ret = avcodec_receive_packet(enc, &pkt);

                if (ret < 0 && ret != AVERROR_EOF) {

                    av_log(NULL, AV_LOG_FATAL, "%s encoding failed\n", desc);

                    exit_program(1);

                }

                if (ost->logfile && enc->stats_out) {

                    fprintf(ost->logfile, "%s", enc->stats_out);

                }

                if (ret == AVERROR_EOF) {

                    stop_encoding = 1;

                    break;

                }

                av_packet_rescale_ts(&pkt, enc->time_base, ost->st->time_base);

                output_packet(os, &pkt, ost);

            }



            if (stop_encoding)

                break;

        }

    }

}

static int dmg_read(BlockDriverState *bs, int64_t sector_num,

                    uint8_t *buf, int nb_sectors)

{

    BDRVDMGState *s = bs->opaque;

    int i;



    for(i=0;i<nb_sectors;i++) {

	uint32_t sector_offset_in_chunk;

	if(dmg_read_chunk(bs, sector_num+i) != 0)

	    return -1;

	sector_offset_in_chunk = sector_num+i-s->sectors[s->current_chunk];

	memcpy(buf+i*512,s->uncompressed_chunk+sector_offset_in_chunk*512,512);

    }

    return 0;

}

int ioinst_handle_schm(CPUS390XState *env, uint64_t reg1, uint64_t reg2,

                       uint32_t ipb)

{

    uint8_t mbk;

    int update;

    int dct;



    trace_ioinst("schm");



    if (SCHM_REG1_RES(reg1)) {

        program_interrupt(env, PGM_OPERAND, 2);

        return -EIO;

    }



    mbk = SCHM_REG1_MBK(reg1);

    update = SCHM_REG1_UPD(reg1);

    dct = SCHM_REG1_DCT(reg1);



    if (update && (reg2 & 0x0000000000000fff)) {

        program_interrupt(env, PGM_OPERAND, 2);

        return -EIO;

    }



    css_do_schm(mbk, update, dct, update ? reg2 : 0);



    return 0;

}

static int hda_codec_dev_init(DeviceState *qdev, DeviceInfo *base)

{

    HDACodecBus *bus = DO_UPCAST(HDACodecBus, qbus, qdev->parent_bus);

    HDACodecDevice *dev = DO_UPCAST(HDACodecDevice, qdev, qdev);

    HDACodecDeviceInfo *info = DO_UPCAST(HDACodecDeviceInfo, qdev, base);



    dev->info = info;

    if (dev->cad == -1) {

        dev->cad = bus->next_cad;

    }

    if (dev->cad > 15)

        return -1;

    bus->next_cad = dev->cad + 1;

    return info->init(dev);

}

static int srt_decode_frame(AVCodecContext *avctx,

                            void *data, int *got_sub_ptr, AVPacket *avpkt)

{

    AVSubtitle *sub = data;

    AVBPrint buffer;

    int x1 = -1, y1 = -1, x2 = -1, y2 = -1;

    int size, ret;

    const uint8_t *p = av_packet_get_side_data(avpkt, AV_PKT_DATA_SUBTITLE_POSITION, &size);

    FFASSDecoderContext *s = avctx->priv_data;



    if (p && size == 16) {

        x1 = AV_RL32(p     );

        y1 = AV_RL32(p +  4);

        x2 = AV_RL32(p +  8);

        y2 = AV_RL32(p + 12);

    }



    if (avpkt->size <= 0)

        return avpkt->size;



    av_bprint_init(&buffer, 0, AV_BPRINT_SIZE_UNLIMITED);



    srt_to_ass(avctx, &buffer, avpkt->data, x1, y1, x2, y2);

    ret = ff_ass_add_rect(sub, buffer.str, s->readorder++, 0, NULL, NULL);

    av_bprint_finalize(&buffer, NULL);

    if (ret < 0)

        return ret;



    *got_sub_ptr = sub->num_rects > 0;

    return avpkt->size;

}

