static abi_long do_fcntl(int fd, int cmd, abi_ulong arg)

{

    struct flock fl;

    struct target_flock *target_fl;

    struct flock64 fl64;

    struct target_flock64 *target_fl64;

#ifdef F_GETOWN_EX

    struct f_owner_ex fox;

    struct target_f_owner_ex *target_fox;

#endif

    abi_long ret;

    int host_cmd = target_to_host_fcntl_cmd(cmd);



    if (host_cmd == -TARGET_EINVAL)

	    return host_cmd;



    switch(cmd) {

    case TARGET_F_GETLK:

        if (!lock_user_struct(VERIFY_READ, target_fl, arg, 1))

            return -TARGET_EFAULT;

        fl.l_type =

                  target_to_host_bitmask(tswap16(target_fl->l_type), flock_tbl);

        fl.l_whence = tswap16(target_fl->l_whence);

        fl.l_start = tswapal(target_fl->l_start);

        fl.l_len = tswapal(target_fl->l_len);

        fl.l_pid = tswap32(target_fl->l_pid);

        unlock_user_struct(target_fl, arg, 0);

        ret = get_errno(fcntl(fd, host_cmd, &fl));

        if (ret == 0) {

            if (!lock_user_struct(VERIFY_WRITE, target_fl, arg, 0))

                return -TARGET_EFAULT;

            target_fl->l_type =

                          host_to_target_bitmask(tswap16(fl.l_type), flock_tbl);

            target_fl->l_whence = tswap16(fl.l_whence);

            target_fl->l_start = tswapal(fl.l_start);

            target_fl->l_len = tswapal(fl.l_len);

            target_fl->l_pid = tswap32(fl.l_pid);

            unlock_user_struct(target_fl, arg, 1);

        }

        break;



    case TARGET_F_SETLK:

    case TARGET_F_SETLKW:

        if (!lock_user_struct(VERIFY_READ, target_fl, arg, 1))

            return -TARGET_EFAULT;

        fl.l_type =

                  target_to_host_bitmask(tswap16(target_fl->l_type), flock_tbl);

        fl.l_whence = tswap16(target_fl->l_whence);

        fl.l_start = tswapal(target_fl->l_start);

        fl.l_len = tswapal(target_fl->l_len);

        fl.l_pid = tswap32(target_fl->l_pid);

        unlock_user_struct(target_fl, arg, 0);

        ret = get_errno(fcntl(fd, host_cmd, &fl));

        break;



    case TARGET_F_GETLK64:

        if (!lock_user_struct(VERIFY_READ, target_fl64, arg, 1))

            return -TARGET_EFAULT;

        fl64.l_type =

           target_to_host_bitmask(tswap16(target_fl64->l_type), flock_tbl) >> 1;

        fl64.l_whence = tswap16(target_fl64->l_whence);

        fl64.l_start = tswap64(target_fl64->l_start);

        fl64.l_len = tswap64(target_fl64->l_len);

        fl64.l_pid = tswap32(target_fl64->l_pid);

        unlock_user_struct(target_fl64, arg, 0);

        ret = get_errno(fcntl(fd, host_cmd, &fl64));

        if (ret == 0) {

            if (!lock_user_struct(VERIFY_WRITE, target_fl64, arg, 0))

                return -TARGET_EFAULT;

            target_fl64->l_type =

                   host_to_target_bitmask(tswap16(fl64.l_type), flock_tbl) >> 1;

            target_fl64->l_whence = tswap16(fl64.l_whence);

            target_fl64->l_start = tswap64(fl64.l_start);

            target_fl64->l_len = tswap64(fl64.l_len);

            target_fl64->l_pid = tswap32(fl64.l_pid);

            unlock_user_struct(target_fl64, arg, 1);

        }

        break;

    case TARGET_F_SETLK64:

    case TARGET_F_SETLKW64:

        if (!lock_user_struct(VERIFY_READ, target_fl64, arg, 1))

            return -TARGET_EFAULT;

        fl64.l_type =

           target_to_host_bitmask(tswap16(target_fl64->l_type), flock_tbl) >> 1;

        fl64.l_whence = tswap16(target_fl64->l_whence);

        fl64.l_start = tswap64(target_fl64->l_start);

        fl64.l_len = tswap64(target_fl64->l_len);

        fl64.l_pid = tswap32(target_fl64->l_pid);

        unlock_user_struct(target_fl64, arg, 0);

        ret = get_errno(fcntl(fd, host_cmd, &fl64));

        break;



    case TARGET_F_GETFL:

        ret = get_errno(fcntl(fd, host_cmd, arg));

        if (ret >= 0) {

            ret = host_to_target_bitmask(ret, fcntl_flags_tbl);

        }

        break;



    case TARGET_F_SETFL:

        ret = get_errno(fcntl(fd, host_cmd, target_to_host_bitmask(arg, fcntl_flags_tbl)));

        break;



#ifdef F_GETOWN_EX

    case TARGET_F_GETOWN_EX:

        ret = get_errno(fcntl(fd, host_cmd, &fox));

        if (ret >= 0) {

            if (!lock_user_struct(VERIFY_WRITE, target_fox, arg, 0))

                return -TARGET_EFAULT;

            target_fox->type = tswap32(fox.type);

            target_fox->pid = tswap32(fox.pid);

            unlock_user_struct(target_fox, arg, 1);

        }

        break;

#endif



#ifdef F_SETOWN_EX

    case TARGET_F_SETOWN_EX:

        if (!lock_user_struct(VERIFY_READ, target_fox, arg, 1))

            return -TARGET_EFAULT;

        fox.type = tswap32(target_fox->type);

        fox.pid = tswap32(target_fox->pid);

        unlock_user_struct(target_fox, arg, 0);

        ret = get_errno(fcntl(fd, host_cmd, &fox));

        break;

#endif



    case TARGET_F_SETOWN:

    case TARGET_F_GETOWN:

    case TARGET_F_SETSIG:

    case TARGET_F_GETSIG:

    case TARGET_F_SETLEASE:

    case TARGET_F_GETLEASE:

        ret = get_errno(fcntl(fd, host_cmd, arg));

        break;



    default:

        ret = get_errno(fcntl(fd, cmd, arg));

        break;

    }

    return ret;

}

void st_set_trace_file_enabled(bool enable)

{

    if (enable == !!trace_fp) {

        return; /* no change */

    }



    /* Halt trace writeout */

    flush_trace_file(true);

    trace_writeout_enabled = false;

    flush_trace_file(true);



    if (enable) {

        static const TraceRecord header = {

            .event = HEADER_EVENT_ID,

            .timestamp_ns = HEADER_MAGIC,

            .x1 = HEADER_VERSION,

        };



        trace_fp = fopen(trace_file_name, "w");

        if (!trace_fp) {

            return;

        }



        if (fwrite(&header, sizeof header, 1, trace_fp) != 1) {

            fclose(trace_fp);

            trace_fp = NULL;

            return;

        }



        /* Resume trace writeout */

        trace_writeout_enabled = true;

        flush_trace_file(false);

    } else {

        fclose(trace_fp);

        trace_fp = NULL;

    }

}

qcrypto_tls_session_new(QCryptoTLSCreds *creds,

                        const char *hostname,

                        const char *aclname,

                        QCryptoTLSCredsEndpoint endpoint,

                        Error **errp)

{

    QCryptoTLSSession *session;

    int ret;



    session = g_new0(QCryptoTLSSession, 1);

    trace_qcrypto_tls_session_new(

        session, creds, hostname ? hostname : "<none>",

        aclname ? aclname : "<none>", endpoint);



    if (hostname) {

        session->hostname = g_strdup(hostname);

    }

    if (aclname) {

        session->aclname = g_strdup(aclname);

    }

    session->creds = creds;

    object_ref(OBJECT(creds));



    if (creds->endpoint != endpoint) {

        error_setg(errp, "Credentials endpoint doesn't match session");

        goto error;

    }



    if (endpoint == QCRYPTO_TLS_CREDS_ENDPOINT_SERVER) {

        ret = gnutls_init(&session->handle, GNUTLS_SERVER);

    } else {

        ret = gnutls_init(&session->handle, GNUTLS_CLIENT);

    }

    if (ret < 0) {

        error_setg(errp, "Cannot initialize TLS session: %s",

                   gnutls_strerror(ret));

        goto error;

    }



    if (object_dynamic_cast(OBJECT(creds),

                            TYPE_QCRYPTO_TLS_CREDS_ANON)) {

        QCryptoTLSCredsAnon *acreds = QCRYPTO_TLS_CREDS_ANON(creds);



        ret = gnutls_priority_set_direct(session->handle,

                                         "NORMAL:+ANON-DH", NULL);

        if (ret < 0) {

            error_setg(errp, "Unable to set TLS session priority: %s",

                       gnutls_strerror(ret));

            goto error;

        }

        if (creds->endpoint == QCRYPTO_TLS_CREDS_ENDPOINT_SERVER) {

            ret = gnutls_credentials_set(session->handle,

                                         GNUTLS_CRD_ANON,

                                         acreds->data.server);

        } else {

            ret = gnutls_credentials_set(session->handle,

                                         GNUTLS_CRD_ANON,

                                         acreds->data.client);

        }

        if (ret < 0) {

            error_setg(errp, "Cannot set session credentials: %s",

                       gnutls_strerror(ret));

            goto error;

        }

    } else if (object_dynamic_cast(OBJECT(creds),

                                   TYPE_QCRYPTO_TLS_CREDS_X509)) {

        QCryptoTLSCredsX509 *tcreds = QCRYPTO_TLS_CREDS_X509(creds);



        ret = gnutls_set_default_priority(session->handle);

        if (ret < 0) {

            error_setg(errp, "Cannot set default TLS session priority: %s",

                       gnutls_strerror(ret));

            goto error;

        }

        ret = gnutls_credentials_set(session->handle,

                                     GNUTLS_CRD_CERTIFICATE,

                                     tcreds->data);

        if (ret < 0) {

            error_setg(errp, "Cannot set session credentials: %s",

                       gnutls_strerror(ret));

            goto error;

        }



        if (creds->endpoint == QCRYPTO_TLS_CREDS_ENDPOINT_SERVER) {

            /* This requests, but does not enforce a client cert.

             * The cert checking code later does enforcement */

            gnutls_certificate_server_set_request(session->handle,

                                                  GNUTLS_CERT_REQUEST);

        }

    } else {

        error_setg(errp, "Unsupported TLS credentials type %s",

                   object_get_typename(OBJECT(creds)));

        goto error;

    }



    gnutls_transport_set_ptr(session->handle, session);

    gnutls_transport_set_push_function(session->handle,

                                       qcrypto_tls_session_push);

    gnutls_transport_set_pull_function(session->handle,

                                       qcrypto_tls_session_pull);



    return session;



 error:

    qcrypto_tls_session_free(session);

    return NULL;

}

static void ict_int(void *_src0, void *_src1, void *_src2, int csize)

{

    int32_t *src0 = _src0, *src1 = _src1, *src2 = _src2;

    int32_t i0, i1, i2;

    int i;



    for (i = 0; i < csize; i++) {

        i0 = *src0 + (((i_ict_params[0] * *src2) + (1 << 15)) >> 16);

        i1 = *src0 - (((i_ict_params[1] * *src1) + (1 << 15)) >> 16)

                   - (((i_ict_params[2] * *src2) + (1 << 15)) >> 16);

        i2 = *src0 + (((i_ict_params[3] * *src1) + (1 << 15)) >> 16);

        *src0++ = i0;

        *src1++ = i1;

        *src2++ = i2;

    }

}

