void qmp_block_set_io_throttle(const char *device, int64_t bps, int64_t bps_rd,
                               int64_t bps_wr,
                               int64_t iops,
                               int64_t iops_rd,
                               int64_t iops_wr,
                               bool has_bps_max,
                               int64_t bps_max,
                               bool has_bps_rd_max,
                               int64_t bps_rd_max,
                               bool has_bps_wr_max,
                               int64_t bps_wr_max,
                               bool has_iops_max,
                               int64_t iops_max,
                               bool has_iops_rd_max,
                               int64_t iops_rd_max,
                               bool has_iops_wr_max,
                               int64_t iops_wr_max,
                               bool has_iops_size,
                               int64_t iops_size, Error **errp)
{
    ThrottleConfig cfg;
    BlockDriverState *bs;
    AioContext *aio_context;
    bs = bdrv_find(device);
    if (!bs) {
        error_set(errp, QERR_DEVICE_NOT_FOUND, device);
        return;
    }
    memset(&cfg, 0, sizeof(cfg));
    cfg.buckets[THROTTLE_BPS_TOTAL].avg = bps;
    cfg.buckets[THROTTLE_BPS_READ].avg  = bps_rd;
    cfg.buckets[THROTTLE_BPS_WRITE].avg = bps_wr;
    cfg.buckets[THROTTLE_OPS_TOTAL].avg = iops;
    cfg.buckets[THROTTLE_OPS_READ].avg  = iops_rd;
    cfg.buckets[THROTTLE_OPS_WRITE].avg = iops_wr;
    if (has_bps_max) {
        cfg.buckets[THROTTLE_BPS_TOTAL].max = bps_max;
    }
    if (has_bps_rd_max) {
        cfg.buckets[THROTTLE_BPS_READ].max = bps_rd_max;
    }
    if (has_bps_wr_max) {
        cfg.buckets[THROTTLE_BPS_WRITE].max = bps_wr_max;
    }
    if (has_iops_max) {
        cfg.buckets[THROTTLE_OPS_TOTAL].max = iops_max;
    }
    if (has_iops_rd_max) {
        cfg.buckets[THROTTLE_OPS_READ].max = iops_rd_max;
    }
    if (has_iops_wr_max) {
        cfg.buckets[THROTTLE_OPS_WRITE].max = iops_wr_max;
    }
    if (has_iops_size) {
        cfg.op_size = iops_size;
    }
    if (!check_throttle_config(&cfg, errp)) {
        return;
    }
    aio_context = bdrv_get_aio_context(bs);
    aio_context_acquire(aio_context);
    if (!bs->io_limits_enabled && throttle_enabled(&cfg)) {
        bdrv_io_limits_enable(bs);
    } else if (bs->io_limits_enabled && !throttle_enabled(&cfg)) {
        bdrv_io_limits_disable(bs);
    }
    if (bs->io_limits_enabled) {
        bdrv_set_io_limits(bs, &cfg);
    }
}

int ff_tls_open_underlying(TLSShared *c, URLContext *parent, const char *uri, AVDictionary **options)

{

    int port;

    const char *p;

    char buf[200], opts[50] = "";

    struct addrinfo hints = { 0 }, *ai = NULL;

    const char *proxy_path;

    int use_proxy;



    set_options(c, uri);



    if (c->listen)

        snprintf(opts, sizeof(opts), "?listen=1");



    av_url_split(NULL, 0, NULL, 0, c->host, sizeof(c->host), &port, NULL, 0, uri);



    p = strchr(uri, '?');



    if (!p) {

        p = opts;

    } else {

        if (av_find_info_tag(opts, sizeof(opts), "listen", p))

            c->listen = 1;

    }



    ff_url_join(buf, sizeof(buf), "tcp", NULL, c->host, port, "%s", p);



    hints.ai_flags = AI_NUMERICHOST;

    if (!getaddrinfo(c->host, NULL, &hints, &ai)) {

        c->numerichost = 1;

        freeaddrinfo(ai);

    }



    proxy_path = getenv("http_proxy");

    use_proxy = !ff_http_match_no_proxy(getenv("no_proxy"), c->host) &&

                proxy_path && av_strstart(proxy_path, "http://", NULL);



    if (use_proxy) {

        char proxy_host[200], proxy_auth[200], dest[200];

        int proxy_port;

        av_url_split(NULL, 0, proxy_auth, sizeof(proxy_auth),

                     proxy_host, sizeof(proxy_host), &proxy_port, NULL, 0,

                     proxy_path);

        ff_url_join(dest, sizeof(dest), NULL, NULL, c->host, port, NULL);

        ff_url_join(buf, sizeof(buf), "httpproxy", proxy_auth, proxy_host,

                    proxy_port, "/%s", dest);

    }



    return ffurl_open(&c->tcp, buf, AVIO_FLAG_READ_WRITE,

                      &parent->interrupt_callback, options);

}

static int xen_pt_bar_reg_write(XenPCIPassthroughState *s, XenPTReg *cfg_entry,

                                uint32_t *val, uint32_t dev_value,

                                uint32_t valid_mask)

{

    XenPTRegInfo *reg = cfg_entry->reg;

    XenPTRegion *base = NULL;

    PCIDevice *d = &s->dev;

    const PCIIORegion *r;

    uint32_t writable_mask = 0;

    uint32_t bar_emu_mask = 0;

    uint32_t bar_ro_mask = 0;

    uint32_t r_size = 0;

    int index = 0;



    index = xen_pt_bar_offset_to_index(reg->offset);

    if (index < 0 || index >= PCI_NUM_REGIONS) {

        XEN_PT_ERR(d, "Internal error: Invalid BAR index [%d].\n", index);

        return -1;

    }



    r = &d->io_regions[index];

    base = &s->bases[index];

    r_size = xen_pt_get_emul_size(base->bar_flag, r->size);



    /* set emulate mask and read-only mask values depend on the BAR flag */

    switch (s->bases[index].bar_flag) {

    case XEN_PT_BAR_FLAG_MEM:

        bar_emu_mask = XEN_PT_BAR_MEM_EMU_MASK;

        if (!r_size) {

            /* low 32 bits mask for 64 bit bars */

            bar_ro_mask = XEN_PT_BAR_ALLF;

        } else {

            bar_ro_mask = XEN_PT_BAR_MEM_RO_MASK | (r_size - 1);

        }

        break;

    case XEN_PT_BAR_FLAG_IO:

        bar_emu_mask = XEN_PT_BAR_IO_EMU_MASK;

        bar_ro_mask = XEN_PT_BAR_IO_RO_MASK | (r_size - 1);

        break;

    case XEN_PT_BAR_FLAG_UPPER:

        bar_emu_mask = XEN_PT_BAR_ALLF;

        bar_ro_mask = r_size ? r_size - 1 : 0;

        break;

    default:

        break;

    }



    /* modify emulate register */

    writable_mask = bar_emu_mask & ~bar_ro_mask & valid_mask;

    cfg_entry->data = XEN_PT_MERGE_VALUE(*val, cfg_entry->data, writable_mask);



    /* check whether we need to update the virtual region address or not */

    switch (s->bases[index].bar_flag) {

    case XEN_PT_BAR_FLAG_UPPER:

    case XEN_PT_BAR_FLAG_MEM:

        /* nothing to do */

        break;

    case XEN_PT_BAR_FLAG_IO:

        /* nothing to do */

        break;

    default:

        break;

    }



    /* create value for writing to I/O device register */

    *val = XEN_PT_MERGE_VALUE(*val, dev_value, 0);



    return 0;

}

