static int realloc_refcount_array(BDRVQcow2State *s, void **array,

                                  int64_t *size, int64_t new_size)

{

    size_t old_byte_size, new_byte_size;

    void *new_ptr;



    /* Round to clusters so the array can be directly written to disk */

    old_byte_size = size_to_clusters(s, refcount_array_byte_size(s, *size))

                    * s->cluster_size;

    new_byte_size = size_to_clusters(s, refcount_array_byte_size(s, new_size))

                    * s->cluster_size;



    if (new_byte_size == old_byte_size) {

        *size = new_size;

        return 0;

    }



    assert(new_byte_size > 0);



    new_ptr = g_try_realloc(*array, new_byte_size);

    if (!new_ptr) {

        return -ENOMEM;

    }



    if (new_byte_size > old_byte_size) {

        memset((void *)((uintptr_t)new_ptr + old_byte_size), 0,

               new_byte_size - old_byte_size);

    }



    *array = new_ptr;

    *size  = new_size;



    return 0;

}

static void gem_transmit(CadenceGEMState *s)

{

    unsigned    desc[2];

    hwaddr packet_desc_addr;

    uint8_t     tx_packet[2048];

    uint8_t     *p;

    unsigned    total_bytes;

    int q = 0;



    /* Do nothing if transmit is not enabled. */

    if (!(s->regs[GEM_NWCTRL] & GEM_NWCTRL_TXENA)) {

        return;

    }



    DB_PRINT("\n");



    /* The packet we will hand off to QEMU.

     * Packets scattered across multiple descriptors are gathered to this

     * one contiguous buffer first.

     */

    p = tx_packet;

    total_bytes = 0;



    for (q = s->num_priority_queues - 1; q >= 0; q--) {

    /* read current descriptor */

    packet_desc_addr = s->tx_desc_addr[q];



    DB_PRINT("read descriptor 0x%" HWADDR_PRIx "\n", packet_desc_addr);

    cpu_physical_memory_read(packet_desc_addr,

                             (uint8_t *)desc, sizeof(desc));

    /* Handle all descriptors owned by hardware */

    while (tx_desc_get_used(desc) == 0) {



        /* Do nothing if transmit is not enabled. */

        if (!(s->regs[GEM_NWCTRL] & GEM_NWCTRL_TXENA)) {

            return;

        }

        print_gem_tx_desc(desc, q);



        /* The real hardware would eat this (and possibly crash).

         * For QEMU let's lend a helping hand.

         */

        if ((tx_desc_get_buffer(desc) == 0) ||

            (tx_desc_get_length(desc) == 0)) {

            DB_PRINT("Invalid TX descriptor @ 0x%x\n",

                     (unsigned)packet_desc_addr);

            break;

        }



        if (tx_desc_get_length(desc) > sizeof(tx_packet) - (p - tx_packet)) {

            DB_PRINT("TX descriptor @ 0x%x too large: size 0x%x space 0x%x\n",

                     (unsigned)packet_desc_addr,

                     (unsigned)tx_desc_get_length(desc),

                     sizeof(tx_packet) - (p - tx_packet));

            break;

        }



        /* Gather this fragment of the packet from "dma memory" to our contig.

         * buffer.

         */

        cpu_physical_memory_read(tx_desc_get_buffer(desc), p,

                                 tx_desc_get_length(desc));

        p += tx_desc_get_length(desc);

        total_bytes += tx_desc_get_length(desc);



        /* Last descriptor for this packet; hand the whole thing off */

        if (tx_desc_get_last(desc)) {

            unsigned    desc_first[2];



            /* Modify the 1st descriptor of this packet to be owned by

             * the processor.

             */

            cpu_physical_memory_read(s->tx_desc_addr[q], (uint8_t *)desc_first,

                                     sizeof(desc_first));

            tx_desc_set_used(desc_first);

            cpu_physical_memory_write(s->tx_desc_addr[q], (uint8_t *)desc_first,

                                      sizeof(desc_first));

            /* Advance the hardware current descriptor past this packet */

            if (tx_desc_get_wrap(desc)) {

                s->tx_desc_addr[q] = s->regs[GEM_TXQBASE];

            } else {

                s->tx_desc_addr[q] = packet_desc_addr + 8;

            }

            DB_PRINT("TX descriptor next: 0x%08x\n", s->tx_desc_addr[q]);



            s->regs[GEM_TXSTATUS] |= GEM_TXSTATUS_TXCMPL;

            s->regs[GEM_ISR] |= GEM_INT_TXCMPL & ~(s->regs[GEM_IMR]);



            /* Update queue interrupt status */

            if (s->num_priority_queues > 1) {

                s->regs[GEM_INT_Q1_STATUS + q] |=

                        GEM_INT_TXCMPL & ~(s->regs[GEM_INT_Q1_MASK + q]);

            }



            /* Handle interrupt consequences */

            gem_update_int_status(s);



            /* Is checksum offload enabled? */

            if (s->regs[GEM_DMACFG] & GEM_DMACFG_TXCSUM_OFFL) {

                net_checksum_calculate(tx_packet, total_bytes);

            }



            /* Update MAC statistics */

            gem_transmit_updatestats(s, tx_packet, total_bytes);



            /* Send the packet somewhere */

            if (s->phy_loop || (s->regs[GEM_NWCTRL] & GEM_NWCTRL_LOCALLOOP)) {

                gem_receive(qemu_get_queue(s->nic), tx_packet, total_bytes);

            } else {

                qemu_send_packet(qemu_get_queue(s->nic), tx_packet,

                                 total_bytes);

            }



            /* Prepare for next packet */

            p = tx_packet;

            total_bytes = 0;

        }



        /* read next descriptor */

        if (tx_desc_get_wrap(desc)) {

            tx_desc_set_last(desc);

            packet_desc_addr = s->regs[GEM_TXQBASE];

        } else {

            packet_desc_addr += 8;

        }

        DB_PRINT("read descriptor 0x%" HWADDR_PRIx "\n", packet_desc_addr);

        cpu_physical_memory_read(packet_desc_addr,

                                 (uint8_t *)desc, sizeof(desc));

    }



    if (tx_desc_get_used(desc)) {

        s->regs[GEM_TXSTATUS] |= GEM_TXSTATUS_USED;

        s->regs[GEM_ISR] |= GEM_INT_TXUSED & ~(s->regs[GEM_IMR]);

        gem_update_int_status(s);

    }

    }

}

static int set_sps(HEVCContext *s, const HEVCSPS *sps)

{

    int ret;

    int num = 0, den = 0;



    pic_arrays_free(s);

    ret = pic_arrays_init(s, sps);

    if (ret < 0)

        goto fail;



    s->avctx->coded_width         = sps->width;

    s->avctx->coded_height        = sps->height;

    s->avctx->width               = sps->output_width;

    s->avctx->height              = sps->output_height;

    s->avctx->pix_fmt             = sps->pix_fmt;

    s->avctx->sample_aspect_ratio = sps->vui.sar;

    s->avctx->has_b_frames        = sps->temporal_layer[sps->max_sub_layers - 1].num_reorder_pics;



    if (sps->vui.video_signal_type_present_flag)

        s->avctx->color_range = sps->vui.video_full_range_flag ? AVCOL_RANGE_JPEG

                                                               : AVCOL_RANGE_MPEG;

    else

        s->avctx->color_range = AVCOL_RANGE_MPEG;



    if (sps->vui.colour_description_present_flag) {

        s->avctx->color_primaries = sps->vui.colour_primaries;

        s->avctx->color_trc       = sps->vui.transfer_characteristic;

        s->avctx->colorspace      = sps->vui.matrix_coeffs;

    } else {

        s->avctx->color_primaries = AVCOL_PRI_UNSPECIFIED;

        s->avctx->color_trc       = AVCOL_TRC_UNSPECIFIED;

        s->avctx->colorspace      = AVCOL_SPC_UNSPECIFIED;

    }



    ff_hevc_pred_init(&s->hpc,     sps->bit_depth);

    ff_hevc_dsp_init (&s->hevcdsp, sps->bit_depth);

    ff_videodsp_init (&s->vdsp,    sps->bit_depth);



    if (sps->sao_enabled) {

        av_frame_unref(s->tmp_frame);

        ret = ff_get_buffer(s->avctx, s->tmp_frame, AV_GET_BUFFER_FLAG_REF);

        if (ret < 0)

            goto fail;

        s->frame = s->tmp_frame;

    }



    s->sps = sps;

    s->vps = (HEVCVPS*) s->vps_list[s->sps->vps_id]->data;



    if (s->vps->vps_timing_info_present_flag) {

        num = s->vps->vps_num_units_in_tick;

        den = s->vps->vps_time_scale;

    } else if (sps->vui.vui_timing_info_present_flag) {

        num = sps->vui.vui_num_units_in_tick;

        den = sps->vui.vui_time_scale;

    }



    if (num != 0 && den != 0)

        av_reduce(&s->avctx->time_base.num, &s->avctx->time_base.den,

                  num, den, 1 << 30);



    return 0;



fail:

    pic_arrays_free(s);

    s->sps = NULL;

    return ret;

}

