static int vhost_user_migration_done(struct vhost_dev *dev, char* mac_addr)

{

    VhostUserMsg msg = { 0 };

    int err;



    assert(dev->vhost_ops->backend_type == VHOST_BACKEND_TYPE_USER);



    /* If guest supports GUEST_ANNOUNCE do nothing */

    if (virtio_has_feature(dev->acked_features, VIRTIO_NET_F_GUEST_ANNOUNCE)) {

        return 0;

    }



    /* if backend supports VHOST_USER_PROTOCOL_F_RARP ask it to send the RARP */

    if (virtio_has_feature(dev->protocol_features,

                           VHOST_USER_PROTOCOL_F_RARP)) {

        msg.request = VHOST_USER_SEND_RARP;

        msg.flags = VHOST_USER_VERSION;

        memcpy((char *)&msg.u64, mac_addr, 6);

        msg.size = sizeof(m.u64);



        err = vhost_user_write(dev, &msg, NULL, 0);

        return err;

    }

    return -1;

}

static void megasas_complete_frame(MegasasState *s, uint64_t context)

{

    PCIDevice *pci_dev = PCI_DEVICE(s);

    int tail, queue_offset;



    /* Decrement busy count */

    s->busy--;



    if (s->reply_queue_pa) {

        /*

         * Put command on the reply queue.

         * Context is opaque, but emulation is running in

         * little endian. So convert it.

         */

        tail = s->reply_queue_head;

        if (megasas_use_queue64(s)) {

            queue_offset = tail * sizeof(uint64_t);

            stq_le_phys(&address_space_memory,

                        s->reply_queue_pa + queue_offset, context);

        } else {

            queue_offset = tail * sizeof(uint32_t);

            stl_le_phys(&address_space_memory,

                        s->reply_queue_pa + queue_offset, context);

        }

        s->reply_queue_head = megasas_next_index(s, tail, s->fw_cmds);

        s->reply_queue_tail = ldl_le_phys(&address_space_memory,

                                          s->consumer_pa);

        trace_megasas_qf_complete(context, s->reply_queue_head,

                                  s->reply_queue_tail, s->busy, s->doorbell);

    }



    if (megasas_intr_enabled(s)) {

        /* Notify HBA */

        s->doorbell++;

        if (s->doorbell == 1) {

            if (msix_enabled(pci_dev)) {

                trace_megasas_msix_raise(0);

                msix_notify(pci_dev, 0);

            } else if (msi_enabled(pci_dev)) {

                trace_megasas_msi_raise(0);

                msi_notify(pci_dev, 0);

            } else {

                trace_megasas_irq_raise();

                pci_irq_assert(pci_dev);

            }

        }

    } else {

        trace_megasas_qf_complete_noirq(context);

    }

}

static int rm_read_audio_stream_info(AVFormatContext *s, ByteIOContext *pb,

                                     AVStream *st, int read_all)

{

    RMDemuxContext *rm = s->priv_data;

    char buf[256];

    uint32_t version;

    int i;



    /* ra type header */

    version = get_be32(pb); /* version */

    if (((version >> 16) & 0xff) == 3) {

        int64_t startpos = url_ftell(pb);

        /* very old version */

        for(i = 0; i < 14; i++)

            get_byte(pb);

        get_str8(pb, s->title, sizeof(s->title));

        get_str8(pb, s->author, sizeof(s->author));

        get_str8(pb, s->copyright, sizeof(s->copyright));

        get_str8(pb, s->comment, sizeof(s->comment));

        if ((startpos + (version & 0xffff)) >= url_ftell(pb) + 2) {

            // fourcc (should always be "lpcJ")

            get_byte(pb);

            get_str8(pb, buf, sizeof(buf));

        }

        // Skip extra header crap (this should never happen)

        if ((startpos + (version & 0xffff)) > url_ftell(pb))

            url_fskip(pb, (version & 0xffff) + startpos - url_ftell(pb));

        st->codec->sample_rate = 8000;

        st->codec->channels = 1;

        st->codec->codec_type = CODEC_TYPE_AUDIO;

        st->codec->codec_id = CODEC_ID_RA_144;

    } else {

        int flavor, sub_packet_h, coded_framesize, sub_packet_size;

        /* old version (4) */

        get_be32(pb); /* .ra4 */

        get_be32(pb); /* data size */

        get_be16(pb); /* version2 */

        get_be32(pb); /* header size */

        flavor= get_be16(pb); /* add codec info / flavor */

        rm->coded_framesize = coded_framesize = get_be32(pb); /* coded frame size */

        get_be32(pb); /* ??? */

        get_be32(pb); /* ??? */

        get_be32(pb); /* ??? */

        rm->sub_packet_h = sub_packet_h = get_be16(pb); /* 1 */

        st->codec->block_align= get_be16(pb); /* frame size */

        rm->sub_packet_size = sub_packet_size = get_be16(pb); /* sub packet size */

        get_be16(pb); /* ??? */

        if (((version >> 16) & 0xff) == 5) {

            get_be16(pb); get_be16(pb); get_be16(pb);

        }

        st->codec->sample_rate = get_be16(pb);

        get_be32(pb);

        st->codec->channels = get_be16(pb);

        if (((version >> 16) & 0xff) == 5) {

            get_be32(pb);

            buf[0] = get_byte(pb);

            buf[1] = get_byte(pb);

            buf[2] = get_byte(pb);

            buf[3] = get_byte(pb);

            buf[4] = 0;

        } else {

            get_str8(pb, buf, sizeof(buf)); /* desc */

            get_str8(pb, buf, sizeof(buf)); /* desc */

        }

        st->codec->codec_type = CODEC_TYPE_AUDIO;

        if (!strcmp(buf, "dnet")) {

            st->codec->codec_id = CODEC_ID_AC3;

            st->need_parsing = AVSTREAM_PARSE_FULL;

        } else if (!strcmp(buf, "28_8")) {

            st->codec->codec_id = CODEC_ID_RA_288;

            st->codec->extradata_size= 0;

            rm->audio_framesize = st->codec->block_align;

            st->codec->block_align = coded_framesize;



            if(rm->audio_framesize >= UINT_MAX / sub_packet_h){

                av_log(s, AV_LOG_ERROR, "rm->audio_framesize * sub_packet_h too large\n");

                return -1;

            }



            rm->audiobuf = av_malloc(rm->audio_framesize * sub_packet_h);

        } else if ((!strcmp(buf, "cook")) || (!strcmp(buf, "atrc")) || (!strcmp(buf, "sipr"))) {

            int codecdata_length, i;

            get_be16(pb); get_byte(pb);

            if (((version >> 16) & 0xff) == 5)

                get_byte(pb);

            codecdata_length = get_be32(pb);

            if(codecdata_length + FF_INPUT_BUFFER_PADDING_SIZE <= (unsigned)codecdata_length){

                av_log(s, AV_LOG_ERROR, "codecdata_length too large\n");

                return -1;

            }



            if(sub_packet_size <= 0){

                av_log(s, AV_LOG_ERROR, "sub_packet_size is invalid\n");

                return -1;

            }



            if (!strcmp(buf, "cook")) st->codec->codec_id = CODEC_ID_COOK;

            else if (!strcmp(buf, "sipr")) st->codec->codec_id = CODEC_ID_SIPR;

            else st->codec->codec_id = CODEC_ID_ATRAC3;

            st->codec->extradata_size= codecdata_length;

            st->codec->extradata= av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

            for(i = 0; i < codecdata_length; i++)

                ((uint8_t*)st->codec->extradata)[i] = get_byte(pb);

            rm->audio_framesize = st->codec->block_align;

            st->codec->block_align = rm->sub_packet_size;



            if(rm->audio_framesize >= UINT_MAX / sub_packet_h){

                av_log(s, AV_LOG_ERROR, "rm->audio_framesize * sub_packet_h too large\n");

                return -1;

            }



            rm->audiobuf = av_malloc(rm->audio_framesize * sub_packet_h);

        } else if (!strcmp(buf, "raac") || !strcmp(buf, "racp")) {

            int codecdata_length, i;

            get_be16(pb); get_byte(pb);

            if (((version >> 16) & 0xff) == 5)

                get_byte(pb);

            st->codec->codec_id = CODEC_ID_AAC;

            codecdata_length = get_be32(pb);

            if(codecdata_length + FF_INPUT_BUFFER_PADDING_SIZE <= (unsigned)codecdata_length){

                av_log(s, AV_LOG_ERROR, "codecdata_length too large\n");

                return -1;

            }

            if (codecdata_length >= 1) {

                st->codec->extradata_size = codecdata_length - 1;

                st->codec->extradata = av_mallocz(st->codec->extradata_size + FF_INPUT_BUFFER_PADDING_SIZE);

                get_byte(pb);

                for(i = 0; i < st->codec->extradata_size; i++)

                    ((uint8_t*)st->codec->extradata)[i] = get_byte(pb);

            }

        } else {

            st->codec->codec_id = CODEC_ID_NONE;

            av_strlcpy(st->codec->codec_name, buf, sizeof(st->codec->codec_name));

        }

        if (read_all) {

            get_byte(pb);

            get_byte(pb);

            get_byte(pb);



            get_str8(pb, s->title, sizeof(s->title));

            get_str8(pb, s->author, sizeof(s->author));

            get_str8(pb, s->copyright, sizeof(s->copyright));

            get_str8(pb, s->comment, sizeof(s->comment));

        }

    }

    return 0;

}

void hmp_info_snapshots(Monitor *mon, const QDict *qdict)

{

    BlockDriverState *bs, *bs1;

    QEMUSnapshotInfo *sn_tab, *sn, s, *sn_info = &s;

    int nb_sns, i, ret, available;

    int total;

    int *available_snapshots;



    bs = find_vmstate_bs();

    if (!bs) {

        monitor_printf(mon, "No available block device supports snapshots\n");

        return;

    }



    nb_sns = bdrv_snapshot_list(bs, &sn_tab);

    if (nb_sns < 0) {

        monitor_printf(mon, "bdrv_snapshot_list: error %d\n", nb_sns);

        return;

    }



    if (nb_sns == 0) {

        monitor_printf(mon, "There is no snapshot available.\n");

        return;

    }



    available_snapshots = g_malloc0(sizeof(int) * nb_sns);

    total = 0;

    for (i = 0; i < nb_sns; i++) {

        sn = &sn_tab[i];

        available = 1;

        bs1 = NULL;



        while ((bs1 = bdrv_next(bs1))) {

            if (bdrv_can_snapshot(bs1) && bs1 != bs) {

                ret = bdrv_snapshot_find(bs1, sn_info, sn->id_str);

                if (ret < 0) {

                    available = 0;

                    break;

                }

            }

        }



        if (available) {

            available_snapshots[total] = i;

            total++;

        }

    }



    if (total > 0) {

        bdrv_snapshot_dump((fprintf_function)monitor_printf, mon, NULL);

        monitor_printf(mon, "\n");

        for (i = 0; i < total; i++) {

            sn = &sn_tab[available_snapshots[i]];

            bdrv_snapshot_dump((fprintf_function)monitor_printf, mon, sn);

            monitor_printf(mon, "\n");

        }

    } else {

        monitor_printf(mon, "There is no suitable snapshot available\n");

    }



    g_free(sn_tab);

    g_free(available_snapshots);



}

static int decode_slice_thread(AVCodecContext *avctx, void *arg, int jobnr, int threadnr)

{

    ProresContext *ctx = avctx->priv_data;

    SliceContext *slice = &ctx->slices[jobnr];

    const uint8_t *buf = slice->data;

    AVFrame *pic = ctx->frame;

    int i, hdr_size, qscale, log2_chroma_blocks_per_mb;

    int luma_stride, chroma_stride;

    int y_data_size, u_data_size, v_data_size, a_data_size;

    uint8_t *dest_y, *dest_u, *dest_v, *dest_a;

    int16_t qmat_luma_scaled[64];

    int16_t qmat_chroma_scaled[64];

    int mb_x_shift;



    slice->ret = -1;

    //av_log(avctx, AV_LOG_INFO, "slice %d mb width %d mb x %d y %d\n",

    //       jobnr, slice->mb_count, slice->mb_x, slice->mb_y);



    // slice header

    hdr_size = buf[0] >> 3;

    qscale = av_clip(buf[1], 1, 224);

    qscale = qscale > 128 ? qscale - 96 << 2: qscale;

    y_data_size = AV_RB16(buf + 2);

    u_data_size = AV_RB16(buf + 4);

    v_data_size = slice->data_size - y_data_size - u_data_size - hdr_size;

    if (hdr_size > 7) v_data_size = AV_RB16(buf + 6);

    a_data_size = slice->data_size - y_data_size - u_data_size -

                  v_data_size - hdr_size;



    if (y_data_size < 0 || u_data_size < 0 || v_data_size < 0

        || hdr_size+y_data_size+u_data_size+v_data_size > slice->data_size){

        av_log(avctx, AV_LOG_ERROR, "invalid plane data size\n");

        return -1;

    }



    buf += hdr_size;



    for (i = 0; i < 64; i++) {

        qmat_luma_scaled  [i] = ctx->qmat_luma  [i] * qscale;

        qmat_chroma_scaled[i] = ctx->qmat_chroma[i] * qscale;

    }



    if (ctx->frame_type == 0) {

        luma_stride   = pic->linesize[0];

        chroma_stride = pic->linesize[1];

    } else {

        luma_stride   = pic->linesize[0] << 1;

        chroma_stride = pic->linesize[1] << 1;

    }



    if (avctx->pix_fmt == AV_PIX_FMT_YUV444P10 || avctx->pix_fmt == AV_PIX_FMT_YUVA444P10) {

        mb_x_shift = 5;

        log2_chroma_blocks_per_mb = 2;

    } else {

        mb_x_shift = 4;

        log2_chroma_blocks_per_mb = 1;

    }



    dest_y = pic->data[0] + (slice->mb_y << 4) * luma_stride + (slice->mb_x << 5);

    dest_u = pic->data[1] + (slice->mb_y << 4) * chroma_stride + (slice->mb_x << mb_x_shift);

    dest_v = pic->data[2] + (slice->mb_y << 4) * chroma_stride + (slice->mb_x << mb_x_shift);

    dest_a = pic->data[3] + (slice->mb_y << 4) * luma_stride + (slice->mb_x << 5);



    if (ctx->frame_type && ctx->first_field ^ ctx->frame->top_field_first) {

        dest_y += pic->linesize[0];

        dest_u += pic->linesize[1];

        dest_v += pic->linesize[2];

        dest_a += pic->linesize[3];

    }



    decode_slice_luma(avctx, slice, (uint16_t*)dest_y, luma_stride,

                      buf, y_data_size, qmat_luma_scaled);



    if (!(avctx->flags & CODEC_FLAG_GRAY)) {

        decode_slice_chroma(avctx, slice, (uint16_t*)dest_u, chroma_stride,

                            buf + y_data_size, u_data_size,

                            qmat_chroma_scaled, log2_chroma_blocks_per_mb);

        decode_slice_chroma(avctx, slice, (uint16_t*)dest_v, chroma_stride,

                            buf + y_data_size + u_data_size, v_data_size,

                            qmat_chroma_scaled, log2_chroma_blocks_per_mb);

    }

    /* decode alpha plane if available */

    if (ctx->alpha_info && dest_a && a_data_size)

        decode_slice_alpha(ctx, (uint16_t*)dest_a, luma_stride,

                           buf + y_data_size + u_data_size + v_data_size,

                           a_data_size, slice->mb_count);



    slice->ret = 0;

    return 0;

}

static inline void RENAME(rgb32tobgr32)(const uint8_t *src, uint8_t *dst, long src_size)

{

#ifdef HAVE_MMX

/* TODO: unroll this loop */

	asm volatile (

		"xor %%"REG_a", %%"REG_a"	\n\t"

		ASMALIGN16

		"1:				\n\t"

		PREFETCH" 32(%0, %%"REG_a")	\n\t"

		"movq (%0, %%"REG_a"), %%mm0	\n\t"

		"movq %%mm0, %%mm1		\n\t"

		"movq %%mm0, %%mm2		\n\t"

		"pslld $16, %%mm0		\n\t"

		"psrld $16, %%mm1		\n\t"

		"pand "MANGLE(mask32r)", %%mm0	\n\t"

		"pand "MANGLE(mask32g)", %%mm2	\n\t"

		"pand "MANGLE(mask32b)", %%mm1	\n\t"

		"por %%mm0, %%mm2		\n\t"

		"por %%mm1, %%mm2		\n\t"

		MOVNTQ" %%mm2, (%1, %%"REG_a")	\n\t"

		"add $8, %%"REG_a"		\n\t"

		"cmp %2, %%"REG_a"		\n\t"

		" jb 1b				\n\t"

		:: "r" (src), "r"(dst), "r" (src_size-7)

		: "%"REG_a

	);



	__asm __volatile(SFENCE:::"memory");

	__asm __volatile(EMMS:::"memory");

#else

	unsigned i;

	unsigned num_pixels = src_size >> 2;

	for(i=0; i<num_pixels; i++)

	{

#ifdef WORDS_BIGENDIAN  

	  dst[4*i + 1] = src[4*i + 3];

	  dst[4*i + 2] = src[4*i + 2];

	  dst[4*i + 3] = src[4*i + 1];

#else

	  dst[4*i + 0] = src[4*i + 2];

	  dst[4*i + 1] = src[4*i + 1];

	  dst[4*i + 2] = src[4*i + 0];

#endif

	}

#endif

}

