static void dp8393x_realize(DeviceState *dev, Error **errp)

{

    dp8393xState *s = DP8393X(dev);

    int i, checksum;

    uint8_t *prom;



    address_space_init(&s->as, s->dma_mr, "dp8393x");

    memory_region_init_io(&s->mmio, OBJECT(dev), &dp8393x_ops, s,

                          "dp8393x-regs", 0x40 << s->it_shift);



    s->nic = qemu_new_nic(&net_dp83932_info, &s->conf,

                          object_get_typename(OBJECT(dev)), dev->id, s);

    qemu_format_nic_info_str(qemu_get_queue(s->nic), s->conf.macaddr.a);



    s->watchdog = timer_new_ns(QEMU_CLOCK_VIRTUAL, dp8393x_watchdog, s);

    s->regs[SONIC_SR] = 0x0004; /* only revision recognized by Linux */



    memory_region_init_rom_device(&s->prom, OBJECT(dev), NULL, NULL,

                                  "dp8393x-prom", SONIC_PROM_SIZE, NULL);

    prom = memory_region_get_ram_ptr(&s->prom);

    checksum = 0;

    for (i = 0; i < 6; i++) {

        prom[i] = s->conf.macaddr.a[i];

        checksum += prom[i];

        if (checksum > 0xff) {

            checksum = (checksum + 1) & 0xff;

        }

    }

    prom[7] = 0xff - checksum;

}

int qemu_devtree_add_subnode(void *fdt, const char *name)

{

    int offset;

    char *dupname = g_strdup(name);

    char *basename = strrchr(dupname, '/');

    int retval;



    if (!basename) {

        return -1;

    }



    basename[0] = '\0';

    basename++;



    offset = fdt_path_offset(fdt, dupname);

    if (offset < 0) {

        return offset;

    }



    retval = fdt_add_subnode(fdt, offset, basename);

    g_free(dupname);

    return retval;

}

