static int vhost_virtqueue_start(struct vhost_dev *dev,

                                struct VirtIODevice *vdev,

                                struct vhost_virtqueue *vq,

                                unsigned idx)

{

    BusState *qbus = BUS(qdev_get_parent_bus(DEVICE(vdev)));

    VirtioBusState *vbus = VIRTIO_BUS(qbus);

    VirtioBusClass *k = VIRTIO_BUS_GET_CLASS(vbus);

    hwaddr s, l, a;

    int r;

    int vhost_vq_index = dev->vhost_ops->vhost_get_vq_index(dev, idx);

    struct vhost_vring_file file = {

        .index = vhost_vq_index

    };

    struct vhost_vring_state state = {

        .index = vhost_vq_index

    };

    struct VirtQueue *vvq = virtio_get_queue(vdev, idx);





    vq->num = state.num = virtio_queue_get_num(vdev, idx);

    r = dev->vhost_ops->vhost_set_vring_num(dev, &state);

    if (r) {

        VHOST_OPS_DEBUG("vhost_set_vring_num failed");

        return -errno;

    }



    state.num = virtio_queue_get_last_avail_idx(vdev, idx);

    r = dev->vhost_ops->vhost_set_vring_base(dev, &state);

    if (r) {

        VHOST_OPS_DEBUG("vhost_set_vring_base failed");

        return -errno;

    }



    if (vhost_needs_vring_endian(vdev)) {

        r = vhost_virtqueue_set_vring_endian_legacy(dev,

                                                    virtio_is_big_endian(vdev),

                                                    vhost_vq_index);

        if (r) {

            return -errno;

        }

    }



    s = l = virtio_queue_get_desc_size(vdev, idx);

    a = virtio_queue_get_desc_addr(vdev, idx);

    vq->desc = cpu_physical_memory_map(a, &l, 0);

    if (!vq->desc || l != s) {

        r = -ENOMEM;

        goto fail_alloc_desc;

    }

    s = l = virtio_queue_get_avail_size(vdev, idx);

    a = virtio_queue_get_avail_addr(vdev, idx);

    vq->avail = cpu_physical_memory_map(a, &l, 0);

    if (!vq->avail || l != s) {

        r = -ENOMEM;

        goto fail_alloc_avail;

    }

    vq->used_size = s = l = virtio_queue_get_used_size(vdev, idx);

    vq->used_phys = a = virtio_queue_get_used_addr(vdev, idx);

    vq->used = cpu_physical_memory_map(a, &l, 1);

    if (!vq->used || l != s) {

        r = -ENOMEM;

        goto fail_alloc_used;

    }



    vq->ring_size = s = l = virtio_queue_get_ring_size(vdev, idx);

    vq->ring_phys = a = virtio_queue_get_ring_addr(vdev, idx);

    vq->ring = cpu_physical_memory_map(a, &l, 1);

    if (!vq->ring || l != s) {

        r = -ENOMEM;

        goto fail_alloc_ring;

    }



    r = vhost_virtqueue_set_addr(dev, vq, vhost_vq_index, dev->log_enabled);

    if (r < 0) {

        r = -errno;

        goto fail_alloc;

    }



    file.fd = event_notifier_get_fd(virtio_queue_get_host_notifier(vvq));

    r = dev->vhost_ops->vhost_set_vring_kick(dev, &file);

    if (r) {

        VHOST_OPS_DEBUG("vhost_set_vring_kick failed");

        r = -errno;

        goto fail_kick;

    }



    /* Clear and discard previous events if any. */

    event_notifier_test_and_clear(&vq->masked_notifier);



    /* Init vring in unmasked state, unless guest_notifier_mask

     * will do it later.

     */

    if (!vdev->use_guest_notifier_mask) {

        /* TODO: check and handle errors. */

        vhost_virtqueue_mask(dev, vdev, idx, false);

    }



    if (k->query_guest_notifiers &&

        k->query_guest_notifiers(qbus->parent) &&

        virtio_queue_vector(vdev, idx) == VIRTIO_NO_VECTOR) {

        file.fd = -1;

        r = dev->vhost_ops->vhost_set_vring_call(dev, &file);

        if (r) {

            goto fail_vector;

        }

    }



    return 0;



fail_vector:

fail_kick:

fail_alloc:

    cpu_physical_memory_unmap(vq->ring, virtio_queue_get_ring_size(vdev, idx),

                              0, 0);

fail_alloc_ring:

    cpu_physical_memory_unmap(vq->used, virtio_queue_get_used_size(vdev, idx),

                              0, 0);

fail_alloc_used:

    cpu_physical_memory_unmap(vq->avail, virtio_queue_get_avail_size(vdev, idx),

                              0, 0);

fail_alloc_avail:

    cpu_physical_memory_unmap(vq->desc, virtio_queue_get_desc_size(vdev, idx),

                              0, 0);

fail_alloc_desc:

    return r;

}

static int mxf_get_d10_aes3_packet(AVIOContext *pb, AVStream *st, AVPacket *pkt, int64_t length)

{

    const uint8_t *buf_ptr, *end_ptr;

    uint8_t *data_ptr;

    int i;



    if (length > 61444) /* worst case PAL 1920 samples 8 channels */

        return -1;

    av_new_packet(pkt, length);

    avio_read(pb, pkt->data, length);

    data_ptr = pkt->data;

    end_ptr = pkt->data + length;

    buf_ptr = pkt->data + 4; /* skip SMPTE 331M header */

    for (; buf_ptr < end_ptr; ) {

        for (i = 0; i < st->codec->channels; i++) {

            uint32_t sample = bytestream_get_le32(&buf_ptr);

            if (st->codec->bits_per_coded_sample == 24)

                bytestream_put_le24(&data_ptr, (sample >> 4) & 0xffffff);

            else

                bytestream_put_le16(&data_ptr, (sample >> 12) & 0xffff);

        }

        buf_ptr += 32 - st->codec->channels*4; // always 8 channels stored SMPTE 331M

    }

    pkt->size = data_ptr - pkt->data;

    return 0;

}

static void spitz_common_init(MachineState *machine,

                              enum spitz_model_e model, int arm_id)

{

    PXA2xxState *mpu;

    DeviceState *scp0, *scp1 = NULL;

    MemoryRegion *address_space_mem = get_system_memory();

    MemoryRegion *rom = g_new(MemoryRegion, 1);

    const char *cpu_model = machine->cpu_model;



    if (!cpu_model)

        cpu_model = (model == terrier) ? "pxa270-c5" : "pxa270-c0";



    /* Setup CPU & memory */

    mpu = pxa270_init(address_space_mem, spitz_binfo.ram_size, cpu_model);



    sl_flash_register(mpu, (model == spitz) ? FLASH_128M : FLASH_1024M);



    memory_region_init_ram(rom, NULL, "spitz.rom", SPITZ_ROM, &error_abort);

    vmstate_register_ram_global(rom);

    memory_region_set_readonly(rom, true);

    memory_region_add_subregion(address_space_mem, 0, rom);



    /* Setup peripherals */

    spitz_keyboard_register(mpu);



    spitz_ssp_attach(mpu);



    scp0 = sysbus_create_simple("scoop", 0x10800000, NULL);

    if (model != akita) {

        scp1 = sysbus_create_simple("scoop", 0x08800040, NULL);

    }



    spitz_scoop_gpio_setup(mpu, scp0, scp1);



    spitz_gpio_setup(mpu, (model == akita) ? 1 : 2);



    spitz_i2c_setup(mpu);



    if (model == akita)

        spitz_akita_i2c_setup(mpu);



    if (model == terrier)

        /* A 6.0 GB microdrive is permanently sitting in CF slot 1.  */

        spitz_microdrive_attach(mpu, 1);

    else if (model != akita)

        /* A 4.0 GB microdrive is permanently sitting in CF slot 0.  */

        spitz_microdrive_attach(mpu, 0);



    spitz_binfo.kernel_filename = machine->kernel_filename;

    spitz_binfo.kernel_cmdline = machine->kernel_cmdline;

    spitz_binfo.initrd_filename = machine->initrd_filename;

    spitz_binfo.board_id = arm_id;

    arm_load_kernel(mpu->cpu, &spitz_binfo);

    sl_bootparam_write(SL_PXA_PARAM_BASE);

}

static int load_elf_binary(struct linux_binprm * bprm, struct target_pt_regs * regs,

                           struct image_info * info)

{

    struct elfhdr elf_ex;

    struct elfhdr interp_elf_ex;

    struct exec interp_ex;

    int interpreter_fd = -1; /* avoid warning */

    unsigned long load_addr, load_bias;

    int load_addr_set = 0;

    unsigned int interpreter_type = INTERPRETER_NONE;

    unsigned char ibcs2_interpreter;

    int i;

    unsigned long mapped_addr;

    struct elf_phdr * elf_ppnt;

    struct elf_phdr *elf_phdata;

    unsigned long elf_bss, k, elf_brk;

    int retval;

    char * elf_interpreter;

    unsigned long elf_entry, interp_load_addr = 0;

    int status;

    unsigned long start_code, end_code, end_data;

    unsigned long elf_stack;

    char passed_fileno[6];



    ibcs2_interpreter = 0;

    status = 0;

    load_addr = 0;

    load_bias = 0;

    elf_ex = *((struct elfhdr *) bprm->buf);          /* exec-header */

#ifdef BSWAP_NEEDED

    bswap_ehdr(&elf_ex);

#endif



    if (elf_ex.e_ident[0] != 0x7f ||

	strncmp(&elf_ex.e_ident[1], "ELF",3) != 0) {

	    return  -ENOEXEC;

    }



    /* First of all, some simple consistency checks */

    if ((elf_ex.e_type != ET_EXEC && elf_ex.e_type != ET_DYN) ||

       				(! elf_check_arch(elf_ex.e_machine))) {

	    return -ENOEXEC;

    }



    /* Now read in all of the header information */

    elf_phdata = (struct elf_phdr *)malloc(elf_ex.e_phentsize*elf_ex.e_phnum);

    if (elf_phdata == NULL) {

	return -ENOMEM;

    }



    retval = lseek(bprm->fd, elf_ex.e_phoff, SEEK_SET);

    if(retval > 0) {

	retval = read(bprm->fd, (char *) elf_phdata, 

				elf_ex.e_phentsize * elf_ex.e_phnum);

    }



    if (retval < 0) {

	perror("load_elf_binary");

	exit(-1);

	free (elf_phdata);

	return -errno;

    }



#ifdef BSWAP_NEEDED

    elf_ppnt = elf_phdata;

    for (i=0; i<elf_ex.e_phnum; i++, elf_ppnt++) {

        bswap_phdr(elf_ppnt);

    }

#endif

    elf_ppnt = elf_phdata;



    elf_bss = 0;

    elf_brk = 0;





    elf_stack = ~0UL;

    elf_interpreter = NULL;

    start_code = ~0UL;

    end_code = 0;

    end_data = 0;



    for(i=0;i < elf_ex.e_phnum; i++) {

	if (elf_ppnt->p_type == PT_INTERP) {

	    if ( elf_interpreter != NULL )

	    {

		free (elf_phdata);

		free(elf_interpreter);

		close(bprm->fd);

		return -EINVAL;

	    }



	    /* This is the program interpreter used for

	     * shared libraries - for now assume that this

	     * is an a.out format binary

	     */



	    elf_interpreter = (char *)malloc(elf_ppnt->p_filesz);



	    if (elf_interpreter == NULL) {

		free (elf_phdata);

		close(bprm->fd);

		return -ENOMEM;

	    }



	    retval = lseek(bprm->fd, elf_ppnt->p_offset, SEEK_SET);

	    if(retval >= 0) {

		retval = read(bprm->fd, elf_interpreter, elf_ppnt->p_filesz);

	    }

	    if(retval < 0) {

	 	perror("load_elf_binary2");

		exit(-1);

	    }	



	    /* If the program interpreter is one of these two,

	       then assume an iBCS2 image. Otherwise assume

	       a native linux image. */



	    /* JRP - Need to add X86 lib dir stuff here... */



	    if (strcmp(elf_interpreter,"/usr/lib/libc.so.1") == 0 ||

		strcmp(elf_interpreter,"/usr/lib/ld.so.1") == 0) {

	      ibcs2_interpreter = 1;

	    }



#if 0

	    printf("Using ELF interpreter %s\n", elf_interpreter);

#endif

	    if (retval >= 0) {

		retval = open(path(elf_interpreter), O_RDONLY);

		if(retval >= 0) {

		    interpreter_fd = retval;

		}

		else {

		    perror(elf_interpreter);

		    exit(-1);

		    /* retval = -errno; */

		}

	    }



	    if (retval >= 0) {

		retval = lseek(interpreter_fd, 0, SEEK_SET);

		if(retval >= 0) {

		    retval = read(interpreter_fd,bprm->buf,128);

		}

	    }

	    if (retval >= 0) {

		interp_ex = *((struct exec *) bprm->buf); /* aout exec-header */

		interp_elf_ex=*((struct elfhdr *) bprm->buf); /* elf exec-header */

	    }

	    if (retval < 0) {

		perror("load_elf_binary3");

		exit(-1);

		free (elf_phdata);

		free(elf_interpreter);

		close(bprm->fd);

		return retval;

	    }

	}

	elf_ppnt++;

    }



    /* Some simple consistency checks for the interpreter */

    if (elf_interpreter){

	interpreter_type = INTERPRETER_ELF | INTERPRETER_AOUT;



	/* Now figure out which format our binary is */

	if ((N_MAGIC(interp_ex) != OMAGIC) && (N_MAGIC(interp_ex) != ZMAGIC) &&

	    	(N_MAGIC(interp_ex) != QMAGIC)) {

	  interpreter_type = INTERPRETER_ELF;

	}



	if (interp_elf_ex.e_ident[0] != 0x7f ||

	    	strncmp(&interp_elf_ex.e_ident[1], "ELF",3) != 0) {

	    interpreter_type &= ~INTERPRETER_ELF;

	}



	if (!interpreter_type) {

	    free(elf_interpreter);

	    free(elf_phdata);

	    close(bprm->fd);

	    return -ELIBBAD;

	}

    }



    /* OK, we are done with that, now set up the arg stuff,

       and then start this sucker up */



    if (!bprm->sh_bang) {

	char * passed_p;



	if (interpreter_type == INTERPRETER_AOUT) {

	    sprintf(passed_fileno, "%d", bprm->fd);

	    passed_p = passed_fileno;



	    if (elf_interpreter) {

		bprm->p = copy_strings(1,&passed_p,bprm->page,bprm->p);

		bprm->argc++;

	    }

	}

	if (!bprm->p) {

	    if (elf_interpreter) {

	        free(elf_interpreter);

	    }

	    free (elf_phdata);

	    close(bprm->fd);

	    return -E2BIG;

	}

    }



    /* OK, This is the point of no return */

    info->end_data = 0;

    info->end_code = 0;

    info->start_mmap = (unsigned long)ELF_START_MMAP;

    info->mmap = 0;

    elf_entry = (unsigned long) elf_ex.e_entry;



    /* Do this so that we can load the interpreter, if need be.  We will

       change some of these later */

    info->rss = 0;

    bprm->p = setup_arg_pages(bprm->p, bprm, info);

    info->start_stack = bprm->p;



    /* Now we do a little grungy work by mmaping the ELF image into

     * the correct location in memory.  At this point, we assume that

     * the image should be loaded at fixed address, not at a variable

     * address.

     */



    for(i = 0, elf_ppnt = elf_phdata; i < elf_ex.e_phnum; i++, elf_ppnt++) {

        int elf_prot = 0;

        int elf_flags = 0;

        unsigned long error;



	if (elf_ppnt->p_type != PT_LOAD)

            continue;



        if (elf_ppnt->p_flags & PF_R) elf_prot |= PROT_READ;

        if (elf_ppnt->p_flags & PF_W) elf_prot |= PROT_WRITE;

        if (elf_ppnt->p_flags & PF_X) elf_prot |= PROT_EXEC;

        elf_flags = MAP_PRIVATE | MAP_DENYWRITE;

        if (elf_ex.e_type == ET_EXEC || load_addr_set) {

            elf_flags |= MAP_FIXED;

        } else if (elf_ex.e_type == ET_DYN) {

            /* Try and get dynamic programs out of the way of the default mmap

               base, as well as whatever program they might try to exec.  This

               is because the brk will follow the loader, and is not movable.  */

            /* NOTE: for qemu, we do a big mmap to get enough space

               without harcoding any address */

            error = target_mmap(0, ET_DYN_MAP_SIZE,

                                PROT_NONE, MAP_PRIVATE | MAP_ANON, 

                                -1, 0);

            if (error == -1) {

                perror("mmap");

                exit(-1);

            }

            load_bias = TARGET_ELF_PAGESTART(error - elf_ppnt->p_vaddr);

        }



        error = target_mmap(TARGET_ELF_PAGESTART(load_bias + elf_ppnt->p_vaddr),

                            (elf_ppnt->p_filesz +

                             TARGET_ELF_PAGEOFFSET(elf_ppnt->p_vaddr)),

                            elf_prot,

                            (MAP_FIXED | MAP_PRIVATE | MAP_DENYWRITE),

                            bprm->fd,

                            (elf_ppnt->p_offset - 

                             TARGET_ELF_PAGEOFFSET(elf_ppnt->p_vaddr)));

        if (error == -1) {

            perror("mmap");

            exit(-1);

        }



#ifdef LOW_ELF_STACK

        if (TARGET_ELF_PAGESTART(elf_ppnt->p_vaddr) < elf_stack)

            elf_stack = TARGET_ELF_PAGESTART(elf_ppnt->p_vaddr);

#endif



        if (!load_addr_set) {

            load_addr_set = 1;

            load_addr = elf_ppnt->p_vaddr - elf_ppnt->p_offset;

            if (elf_ex.e_type == ET_DYN) {

                load_bias += error -

                    TARGET_ELF_PAGESTART(load_bias + elf_ppnt->p_vaddr);

                load_addr += load_bias;

            }

        }

        k = elf_ppnt->p_vaddr;

        if (k < start_code) 

            start_code = k;

        k = elf_ppnt->p_vaddr + elf_ppnt->p_filesz;

        if (k > elf_bss) 

            elf_bss = k;

        if ((elf_ppnt->p_flags & PF_X) && end_code <  k)

            end_code = k;

        if (end_data < k) 

            end_data = k;

        k = elf_ppnt->p_vaddr + elf_ppnt->p_memsz;

        if (k > elf_brk) elf_brk = k;

    }



    elf_entry += load_bias;

    elf_bss += load_bias;

    elf_brk += load_bias;

    start_code += load_bias;

    end_code += load_bias;

    //    start_data += load_bias;

    end_data += load_bias;



    if (elf_interpreter) {

	if (interpreter_type & 1) {

	    elf_entry = load_aout_interp(&interp_ex, interpreter_fd);

	}

	else if (interpreter_type & 2) {

	    elf_entry = load_elf_interp(&interp_elf_ex, interpreter_fd,

					    &interp_load_addr);

	}



	close(interpreter_fd);

	free(elf_interpreter);



	if (elf_entry == ~0UL) {

	    printf("Unable to load interpreter\n");

	    free(elf_phdata);

	    exit(-1);

	    return 0;

	}

    }



    free(elf_phdata);



    if (loglevel)

	load_symbols(&elf_ex, bprm->fd);



    if (interpreter_type != INTERPRETER_AOUT) close(bprm->fd);

    info->personality = (ibcs2_interpreter ? PER_SVR4 : PER_LINUX);



#ifdef LOW_ELF_STACK

    info->start_stack = bprm->p = elf_stack - 4;

#endif

    bprm->p = (unsigned long)

      create_elf_tables((char *)bprm->p,

		    bprm->argc,

		    bprm->envc,

                    &elf_ex,

                    load_addr, load_bias,

		    interp_load_addr,

		    (interpreter_type == INTERPRETER_AOUT ? 0 : 1),

		    info);

    if (interpreter_type == INTERPRETER_AOUT)

      info->arg_start += strlen(passed_fileno) + 1;

    info->start_brk = info->brk = elf_brk;

    info->end_code = end_code;

    info->start_code = start_code;

    info->end_data = end_data;

    info->start_stack = bprm->p;



    /* Calling set_brk effectively mmaps the pages that we need for the bss and break

       sections */

    set_brk(elf_bss, elf_brk);



    padzero(elf_bss);



#if 0

    printf("(start_brk) %x\n" , info->start_brk);

    printf("(end_code) %x\n" , info->end_code);

    printf("(start_code) %x\n" , info->start_code);

    printf("(end_data) %x\n" , info->end_data);

    printf("(start_stack) %x\n" , info->start_stack);

    printf("(brk) %x\n" , info->brk);

#endif



    if ( info->personality == PER_SVR4 )

    {

	    /* Why this, you ask???  Well SVr4 maps page 0 as read-only,

	       and some applications "depend" upon this behavior.

	       Since we do not have the power to recompile these, we

	       emulate the SVr4 behavior.  Sigh.  */

	    mapped_addr = target_mmap(0, host_page_size, PROT_READ | PROT_EXEC,

                                      MAP_FIXED | MAP_PRIVATE, -1, 0);

    }



#ifdef ELF_PLAT_INIT

    /*

     * The ABI may specify that certain registers be set up in special

     * ways (on i386 %edx is the address of a DT_FINI function, for

     * example.  This macro performs whatever initialization to

     * the regs structure is required.

     */

    ELF_PLAT_INIT(regs);

#endif





    info->entry = elf_entry;



    return 0;

}

ISADevice *pc_find_fdc0(void)

{

    int i;

    Object *container;

    CheckFdcState state = { 0 };



    for (i = 0; i < ARRAY_SIZE(fdc_container_path); i++) {

        container = container_get(qdev_get_machine(), fdc_container_path[i]);

        object_child_foreach(container, check_fdc, &state);

    }



    if (state.multiple) {

        error_report("warning: multiple floppy disk controllers with "

                     "iobase=0x3f0 have been found");

        error_printf("the one being picked for CMOS setup might not reflect "

                     "your intent\n");

    }



    return state.floppy;

}

static inline void check_alignment(CPUS390XState *env, uint64_t v,

                                   int wordsize, uintptr_t ra)

{

    if (v % wordsize) {

        CPUState *cs = CPU(s390_env_get_cpu(env));

        cpu_restore_state(cs, ra);

        program_interrupt(env, PGM_SPECIFICATION, 6);

    }

}
